local P = LoreForeverPacks.Begin("LoreForever_Lang_deDE")
P.entries["subzone:bear-s-head"] = {n="Bärenkopf",s="Auf dem Bärenkopf im Südosten Azsharas unterhalten Furbolgs der Holzschlundfeste ihre Außenposten unterhalb der Klippen. Ihre Siedlungen sind mit größeren Behausungen weiter nördlich verbunden, während Erzmagier Xylem in einem Turm darüber seinen Studien nachgeht.",h="Auf dem Bärenkopf im Südosten Azsharas unterhalten Furbolgs der Holzschlundfeste ihre Außenposten unterhalb...",kw={"erzmagier xylem","azshara","bärenkopf","furbolg","holzschlundfeste","ursolan"},ang={["class:Mage"]="Als Magier könnt Ihr bei Erzmagier Xylem fortgeschrittene arkane Unterweisung suchen. Der Turm des mächtigen, exzentrischen Zauberwirkers überblickt den Bärenkopf."},sec={{t="Furbolgaußenposten und Klippenmagie",b="Furbolgs der Holzschlundfeste unterhalten Außenposten auf dem Bärenkopf, dem Hochland im Südosten Azsharas. Ihre Lager sind nach Norden hin mit den größeren Höhlen von Ursolan und der Holzschlundfeste verbunden. Über ihnen steht Xylems Turm auf den Klippen. Erzmagier Xylem studiert dort in Abgeschiedenheit mit seinen Lehrlingen und hochelfischen Gefährten arkane Magie. Die Küste um sie herum bleibt unruhig."}},faq={{q="Warum heißt dieses Gebiet Bärenkopf?",a="Die Siedlungen der Furbolgs der Holzschlundfeste auf diesen Hügeln gaben dem Bärenkopf seinen Namen. Ihre Lager hier dienen als südliche Außenposten der größeren Behausungen weiter nördlich.",al={"bärenkopf namensherkunft","warum bärenkopf","bärenkopf bedeutung"}},{q="Welche Furbolgs leben auf dem Bärenkopf?",a="Auf dem Bärenkopf leben Furbolgs der Holzschlundfeste. Viele Furbolgstämme in ganz Kalimdor verfielen dämonischer Verderbnis, doch die Furbolgs der Holzschlundfeste haben ihr weitgehend widerstanden. Ihre Siedlungen bleiben mit Ursolan und der Holzschlundfeste verbunden.",al={"bärenkopf furbolgs","holzschlundfeste auf dem bärenkopf","welcher furbolgstamm ist hier"}},{q="Was ist das für ein Turm auf den Klippen über dem Bärenkopf?",a="Erzmagier Xylem gehört der Turm auf den Klippen über dem Bärenkopf. Der exzentrische menschliche Zauberer betreibt in Azshara mit einer Handvoll Lehrlinge und hochelfischen Gefährten in Abgeschiedenheit seine Studien.",al={"turm über dem bärenkopf","wer lebt hier im turm","xylems turm"}}},fp="11,199,36.356.0,36.155.0,35.220.0,50.178.0"}
P.entries["subzone:beezil-s-wreck"] = {n="Beezils Wrack",s="Östlich von Tabetha's Farm lockt Beezils Wrack Plünderer zu seinem zerbrochenen Zeppelin und der verstreuten Fracht.",h="Östlich von Tabetha's Farm lockt Beezils Wrack Plünderer zu seinem zerbrochenen Zeppelin und der verstreuten...",kw={"beezil","beezils wrack","düstermarschen","seaforium","tabetha","zeppelinabsturz"},ang={["profession:Engineering"]="Als Ingenieur könnt Ihr im Wrack explosive mechanische Teile finden, insbesondere Seaforium-Verstärker, die jeder Tüftler begehren würde.",["race:Gnome"]="Als Gnom seht Ihr in dem rauchenden Goblinwrack eine düstere Mahnung an die Gefahren nichtgnomischer Flugkonstruktionen."},sec={{t="Eine verhängnisvolle Landung",b="Östlich von Tabetha's Farm liegt der Goblinzeppelin auseinandergebrochen im Schlamm. Er transportierte Fracht südwärts durch Kalimdor, bevor er in den Sumpf stürzte. Kapitän Beezil ist aus den Marschen verschwunden. Kisten und tickende Maschinen liegen im Schilf und verrotten im Salzwasser."},{t="Bergung im Schlamm",b="Bestien streifen um die Absturzstelle, doch Plünderer trotzen ihnen weiterhin, um an die unversehrte Fracht zu gelangen. Der Zeppelin transportierte explosive Güter, darunter Seaforium-Verstärker und schwere Kisten. Sie riskieren ihr Leben, um die Überreste zu bergen, bevor das Sumpfwasser sie zerfrisst."}},faq={{q="Was ist Beezils Wrack?",a="Beezils Wrack liegt tief in den Düstermarschen, östlich von Tabetha's Farm, wo ein Goblinzeppelin abgestürzt ist. Er stürzte ab, als er Fracht südwärts durch Kalimdor transportierte.",al={"beezils wrack","abgestürzter zeppelin düstermarschen","was ist dieses wrack"}},{q="Wo ist Beezil, der Pilot?",a="Beezil ist nirgends in der Nähe der Absturzstelle zu finden. Die Suchenden wissen nicht, ob er in die Wildnis entkam oder die Marschen verließ.",al={"wo ist beezil","wer ist beezil","beezil aufenthaltsort"}},{q="Welche wertvolle Fracht transportierte der Zeppelin?",a="Der Zeppelin transportierte Handelswaren und explosive Bauteile der Gobliningenieurskunst, darunter Seaforium-Verstärker. Plünderer suchen nach allem, was den Absturz überstanden hat.",al={"was war im zeppelin","seaforium-verstärker","wrack fracht"}}},fp="14,99,20.255.0,19.258.0,23.159.0,27.120.0,46.147.0"}
P.entries["subzone:beggar-s-haunt"] = {n="Bettlerschlupfwinkel",s="Agenten der Verlassenen überwachen vom Bettlerschlupfwinkel, einem alten Turm Sturmwinds, aus die östlichen Zugänge. Er steht auf einem Hügel im nordöstlichen Dämmerwald, nahe der Bergstraße zum Gebirgspass der Totenwinde.",h="Agenten der Verlassenen überwachen vom Bettlerschlupfwinkel, einem alten Turm Sturmwinds, aus die östlichen...",kw={"apothecary faustin","bettlerschlupfwinkel","deathstalker zraedus","dämmerwald","knight's hollow","spähturm","wache von sturmwind"},ang={["faction:Alliance"]="Agenten der Verlassenen in einem alten Spähturm Sturmwinds unweit der Hauptstraße zeigen, dass die Horde Dunkelhains Türschwelle erreicht hat.",["race:Undead"]="Als Angehöriger der Verlassenen haltet Ihr einen abgeschiedenen und gefährlichen Brückenkopf tief in den Menschenlanden des Südens."},sec={{t="Ein Wachturm im Schatten",b="Der Bettlerschlupfwinkel überblickt die Hügel östlich vom Anwesen der Dunstmantels. Sturmwind stationierte hier einst Wachen, um die östlichen Zugänge zum Königreich zu überwachen. Als der Dämmerwald in Finsternis versank, zogen sich die Patrouillen nach Dunkelhain zurück und überließen den Turm der Witterung und dem Verfall. Nun beobachten Agenten der Verlassenen die Region aus dem Gebiet der Allianz heraus. Unter ihnen sind Mitglieder der Königlichen Apothekervereinigung und der Todespirscher."},{t="Knight's Hollow und die vergessenen Toten",b="Ein gewundener Pfad hinter dem Bettlerschlupfwinkel führt hinab nach Knight's Hollow, wo ein abgeschiedener Tümpel unter einem Wasserfall liegt. Ein unmarkiertes Grab ruht zwischen zwei Steinstatuen mit Kapuzen, die den Wächtern neben dem Dunklen Portal gleichen. Zu den nahen Gräbern gehört die Ruhestätte eines Unbekannten Soldaten. Diese Gräber erinnern an vergessene Kämpfe entlang der Grenze, die lange vor der Übernahme des Wachturms durch die Verlassenen ausgefochten wurden."}},faq={{q="Warum sind Verlassene im Bettlerschlupfwinkel?",a="Agenten der Verlassenen aus Unterstadt haben den verlassenen Turm in Besitz genommen. Unter ihnen sind Apothecary Faustin von der Königlichen Apothekervereinigung und Deathstalker Zraedus. Sie beobachten die Bewegungen der Allianz und führen weit im Süden heimlich Experimente durch.",al={"wer ist im bettlerschlupfwinkel","warum ist die horde hier","untote im bettlerschlupfwinkel"}},{q="Wurde dieser Turm ursprünglich von den Verlassenen erbaut?",a="Nein. Sturmwind erbaute den Turm als Spähposten. Als die örtliche Verteidigung nachließ und die Region zum Dämmerwald wurde, gab die Wache von Sturmwind ihn auf. Später nahmen Späher der Verlassenen den leeren Turm ein.",al={"wer hat den bettlerschlupfwinkel erbaut","geschichte des bettlerschlupfwinkels","ist das ein turm der allianz"}},{q="Was hat es mit dem seltsamen Grab hinter dem Turm auf sich?",a="Knight's Hollow liegt am Ende des Pfades hinter dem Bettlerschlupfwinkel. An seinem abgeschiedenen Wasserfalltümpel ruht ein unmarkiertes Grab zwischen Wächterstatuen mit Kapuzen, die jenen neben dem Dunklen Portal gleichen.",al={"statuen in knight's hollow","grab hinter dem turm","statuen des dunklen portals im dämmerwald"}},{q="Ist der Bettlerschlupfwinkel Reisenden der Allianz feindlich gesinnt?",a="Ja. Die Agenten der Verlassenen am Turm sind kampferfahren und strecken Reisende der Allianz nieder, die ihrem Unterschlupf am Hang zu nahe kommen.",al={"greifen sie an","wachen im bettlerschlupfwinkel","ist der bettlerschlupfwinkel sicher"}}},fx={["221bad0c"]={q="Was ist der Bettlerschlupfwinkel?",a="Der Bettlerschlupfwinkel ist ein alter, verlassener Wachturm, der ursprünglich von der Sturmwind-Wache im nordöstlichen Dämmerwald errichtet wurde. Hoch entlang des Kamms östlich des Anwesens der Dunstmantels gelegen und den Pass zum Totenwindpass überblickend, ist dieser befestigte steinerne Außenposten längst der menschlichen Kontrolle entglitten und der eindringenden Dunkelheit des Waldes zum Opfer gefallen.",al={"bettlerschlupfwinkel","was ist dieser turm","bettlerschlupfwinkel dämmerwald"}},["945d85f8"]={q="Wer lebt im Bettlerschlupfwinkel?",a="Der Turm wird von zwei hochrangigen Agenten der Verlassenen besetzt: Apotheker Faustin von der Königlichen Apothekervereinigung und seinem Beschützer, Todespirscher Zraedus. Gemeinsam nutzen sie den abgelegenen Außenposten, um dunkle alchemistische Forschungen fernab der Augen von Sturmwind und ihren Feinden in Lordaeron durchzuführen.",al={"wer ist im bettlerschlupfwinkel","wer kontrolliert den bettlerschlupfwinkel","bewohner des bettlerschlupfwinkels"}},["29ce06ab"]={q="Warum wurde der Bettlerschlupfwinkel verlassen?",a="Wie weite Teile des Dämmerwaldes wurde der Außenposten verlassen, als die militärische Präsenz des Königreichs Sturmwind in der Region zusammenbrach. Da The Nachtwache Schwierigkeiten hatte, selbst Dunkelhain vor gefräßigen Bestien, untoten Schrecken und Spinnen zu verteidigen, wurden abgelegene Wachtürme entlang der Grate verlassen und schnell von feindseligen Kräften beschlagnahmt.",al={"warum ist der bettlerschlupfwinkel verlassen","ruine bettlerschlupfwinkel","warum verließ sturmwind den bettlerschlupfwinkel"}},dbe0cc4e={q="Ist der Bettlerschlupfwinkel gefährlich?",a="Extrem, besonders für ahnungslose Entdecker der Allianz, die durch den östlichen Dämmerwald reisen. Apotheker Faustin und Todespirscher Zraedus sind erfahrene Veteranen, die weit tödlicher sind als die umliegende Tierwelt, und sie werden jeden von der Allianz gnadenlos niederschlagen, der zu nah an ihre abgelegene Festung wandert.",al={"ist der bettlerschlupfwinkel sicher","stufe bettlerschlupfwinkel","gefahr am bettlerschlupfwinkel"}}},fp="14,180,27.386.0,38.388.0,41.240.0,48.190.0,43.180.0,48.130.0"}
P.entries["subzone:beren-s-peril"] = {n="Berens List",s="Bei Berens List sammeln sich Thule Rabenklaue treue Geißeltruppen in den Hügeln südwestlich von Mühlenbern und bedrohen die Verlassenen.",h="Bei Berens List sammeln sich Thule Rabenklaue treue Geißeltruppen in den Hügeln südwestlich von Mühlenbern...",kw={"allister","mühlenbern","berens list","ravenclaws knecht","geißel","das grabmal","silberwald","thule ravenclaw"},ang={["faction:Horde"]="Als Mitglied der Horde müsst Ihr die zerklüfteten Pfade des Silberwalds sichern und abtrünnige Untote aus ihren Schlupfwinkeln vertreiben, bevor sie die Versorgungslinien zwischen dem Grabmal und den südlichen Gebieten unterbrechen können.",["race:Undead"]="Als Untoter werdet Ihr bitter daran erinnert, dass die Geißel ihren Griff noch immer nicht gelockert hat. Ravenclaws Diener bedrohen das Grabmal, und Sylvanas' Getreue müssen sie rasch und ohne Gnade vernichten."},sec={{t="Verborgene Gefahr in den Hügeln",b="Hoch in den Felsen südwestlich von Mühlenbern liegen eine Höhle und ein Bergpfad vor Blicken von der Hauptstraße verborgen. Seit dem Dritten Krieg haben abtrünnige Geißeltruppen die Zuflucht unter dem abtrünnigen Nekromanten Thule Rabenklaue befestigt. Sie weigerten sich, der Dunklen Fürstin zu dienen oder nach Norden zu fliehen.\n\nRavenclaws Regenten, Wächter und Knechte sammelten sich im Verborgenen, um einen Angriff auf den Stützpunkt der Verlassenen beim Grabmal vorzubereiten. Späher der Verlassenen entdeckten sie, und die stillen Klippen wurden zum Kriegsgebiet. Nun gehen Kämpfer der Horde gegen die Untoten vor, bevor diese angreifen können."}},faq={{q="Was ist Berens List?",a="Berens List besteht aus einer Höhle und einem Pass am Berghang südwestlich von Mühlenbern im Silberwald, zwischen der zentralen Hauptstraße und der Nebenstraße nach Mühlenbern.",al={"berens list","wo liegt berens list","berens list höhle"}},{q="Wer kontrolliert Berens List?",a="Untote der Geißel, die Thule Rabenklaue treu ergeben sind, besetzen die Höhle. Unter ihnen sind Ravenclaws Wächter, Knechte und Regenten.",al={"wer lebt bei berens list","feinde bei berens list","ravenclaws untote"}},{q="Warum ist dieser Ort für die Verlassenen von Bedeutung?",a="Späher der Verlassenen entdeckten, dass die Untoten Truppen und Waffen für einen Angriff auf das Grabmal sammelten. Schattenpriester Allister befahl ihnen zuvorzukommen und zuzuschlagen.",al={"allister berens list","warum berens list angreifen","bedrohung für das grabmal"}},{q="Wer ist Thule Rabenklaue?",a="Thule Rabenklaue ist ein mächtiger Nekromant im Silberwald, der verstreute Gruppen willenloser, feindseliger Geißeluntoter kontrollierte. Er nutzte Orte wie Berens List und Burg Fenris, um die Region zu bedrohen.",al={"thule ravenclaw","thule silberwald"}}},fx={["896a3c65"]={q="Was geschah bei Berens List?",a="Nach dem Dritten Krieg wurde dieser abgelegene Höhlenkomplex in den Hügeln des Silberwaldes zu einem Aufmarschgebiet für abtrünnige Untote. Späher der Verlassenen, die Bedrohungen in der Region verfolgten, entdeckten, dass sich feindselige Untote, die dem abtrünnigen Nekromanten Thule Rabenklaue die Treue hielten, in den Höhlen angesammelt hatten und heimlich einen Angriff auf die nahe gelegene Siedlung der Verlassenen, das Grabmal, vorbereiteten.",al={"geschichte von berens list","was geschah bei berens list","lore von berens list"}},["25ec4175"]={q="Ist Berens List gefährlich?",a="Ja, Berens List ist äußerst gefährlich. Die Höhle am Hang wimmelt nur so von feindseligen Untoten, die unter der Kontrolle von Thule Rabenklaue stehen, darunter Ravenclaw-Schlepper, Wächter und Regenten. Jeder Reisende, der sich in die Höhlen wagt, riskiert, von diesen organisierten Untoten überwältigt zu werden, bevor sie ihren Angriff auf Das Grabmal starten können.",al={"gefahren von berens list","wie gefährlich ist berens list","ist berens list sicher"}}},fp="13,120,28.517.0,22.143.0,27.115.0,45.155.0,23.190.0"}
P.entries["subzone:bitter-reaches"] = {n="Bittere Landzunge",s="An Azsharas nordöstlichen Klippen erhebt sich die Bittere Landzunge über dem großen Meer. Raubtiere durchstreifen die Höhen, und Bergriesen beherrschen die nördlichen Grate.",h="An Azsharas nordöstlichen Klippen erhebt sich die Bittere Landzunge über dem großen Meer.",kw={"azshara","bittere landzunge","schimäre","hippogryph","bergriese","bergsilberweisling","schlamm"},ang={["class:Hunter"]="Die Horste an den Klippen der Bitteren Landzunge sind Jagdgebiete wilder Hippogryphen und aggressiver Schimären, die an dieser uralten Küste heimisch sind.",["profession:Herbalism"]="Bergsilberweisling wächst an wenigen Stellen auf den windgepeitschten Höhen der Bitteren Landzunge. Ihr müsst Euch mit Schimären und Riesen auseinandersetzen, um es zu sammeln."},sec={{t="Ein gefährliches Küstengrenzland",b="Die Bittere Landzunge erhebt sich entlang Azsharas nordöstlicher Klippen über dem großen Meer. Wilde Hippogryphen und zweiköpfige Schimären nisten in den Höhen. Säurehaltige Schlämme sickern durch den kalten Boden, während kolossale Bergriesen die hohen nördlichen Grate für sich beanspruchen. Sie vertreiben schwächere Kreaturen und machen die gefrorenen Zugänge für allein reisende Wanderer gefährlich."},{t="Flora der Felsen",b="Bergsilberweisling wächst in vereinzelten Gruppen auf den zerklüfteten Felsen. Das seltene Kraut klammert sich an hohe Felswände und windige Vorsprünge. Kräuterkundige müssen den Riesen und revierverteidigenden Schimären ausweichen, um es zu sammeln."}},faq={{q="Wo liegt die Bittere Landzunge?",a="Die Bittere Landzunge erstreckt sich über Azsharas nordöstliche Klippen und Grate oberhalb der Bucht.",al={"bittere landzunge lage","wo liegt die bittere landzunge","bittere landzunge azshara"}},{q="Welche Kreaturen leben hier?",a="Revierverteidigende Hippogryphen, zweiköpfige Schimären und Schlämme leben in der Region. Bergriesen durchstreifen ihren nördlichen Rand.",al={"bittere landzunge gegner","was lebt auf der bitteren landzunge","monster auf der bitteren landzunge"}},{q="Warum gibt es hier Bergriesen?",a="Uralte Bergriesen beanspruchen die hohen nördlichen Gipfel und Randgebiete Azsharas für sich. Sie vertreiben die meisten heimischen Wildtiere aus ihrem Revier.",al={"bergriesen azshara","warum sind riesen auf der bitteren landzunge"}},{q="Welche wertvollen Ressourcen wachsen auf der Bitteren Landzunge?",a="Bergsilberweisling wächst vereinzelt auf Felsvorsprüngen und entlang der Grate der Bitteren Landzunge.",al={"kräuter bittere landzunge","bittere landzunge sammeln"}}},fp="14,157,28.349.0,18.190.0,29.82.0,25.120.0,35.128.0,51.90.0"}
P.entries["subzone:black-channel-marsh"] = {n="Schwarzkanalmarschen",s="Raptoren durchstreifen die Schwarzkanalmarschen an der Straße zum Hafen von Menethil. Im südwestlichen Sumpfland droht Reisenden und Kurieren entlang der Küste Gefahr.",h="Raptoren durchstreifen die Schwarzkanalmarschen an der Straße zum Hafen von Menethil.",kw={"schwarzkanalmarschen","marschland","hafen von menethil","raptoren","sumpf","sumpfland"},ang={["class:Hunter"]="Als Jäger könnt Ihr neben der Hauptstraße wilde Raptoren des Sumpflands aufspüren oder zähmen, doch das Marschland ist gefährliches Gelände.",["faction:Alliance"]="Als Reisende der Allianz seid Ihr auf diese Straße angewiesen, die den Hafen von Menethil mit dem Rest von Khaz Modan verbindet. Raptoren bleiben eine ständige Gefahr."},sec={{t="Gefahr auf der Straße nach Menethil",b="Die Schwarzkanalmarschen erstrecken sich über das Tiefland südwestlich der Hauptstraße zum Hafen von Menethil. Karawanenführer und Kuriere wissen, dass sie sich in Acht nehmen müssen. Die erhöhte Straße mag sicher wirken, doch zwischen den stillen Kanälen und dem dichten Schilf lauern Raptoren, die ihr Revier verteidigen. Hungrige Bestien geraten oft auf die Straße und überfallen Rekruten oder erschöpfte Reisende, die auch nur ein wenig vom Weg abkommen."}},faq={{q="Wo liegen die Schwarzkanalmarschen?",a="Die Schwarzkanalmarschen liegen im südwestlichen Sumpfland, entlang der Südseite der Hauptstraße zum Hafen von Menethil.",al={"wo liegen die schwarzkanalmarschen","lage der schwarzkanalmarschen","sumpfland schwarzkanal"}},{q="Warum gilt dieses Marschland als gefährlich für Reisende?",a="Überall im Marschland haben Raptoren ihre Lager und jagen nahe seinem Rand. Sie streifen dicht an der Straße umher und überraschen Reisende und unerfahrene Abenteurer.",al={"warum ist es gefährlich","gefahren in den schwarzkanalmarschen","raptoren auf der straße"}},{q="Wer reist hier am häufigsten entlang?",a="Boten der Allianz, zwergische Händler und Reisende zwischen Eisenschmiede und den Docks im Hafen von Menethil nutzen häufig die Straße am Marschland.",al={"wer nutzt diese straße","reisende hier"}}},fp="19,151,26.354.0,37.117.0,53.145.0,36.138.0"}
P.entries["subzone:blackchar-cave"] = {n="Schwarzbrandhöhle",s="Im Südwesten der Sengenden Schlucht verschließt Geröll die Schwarzbrandhöhle zwischen den Felsen.",h="Im Südwesten der Sengenden Schlucht verschließt Geröll die Schwarzbrandhöhle zwischen den Felsen.",kw={"schwarzbrandhöhle","der schwarzfels","versiegelte höhle","sengende schlucht"},sec={{t="Eine versiegelte Schwelle",b="Die Schwarzbrandhöhle liegt zwischen den Felsen nahe dem Zugang zum Schwarzfels. Geröll und versengte Schlacke versiegeln ihren Eingang und versperren jeden Tunnel dahinter. Asche und Magma zeichnen den kargen Boden ringsum."}},faq={{q="Könnt Ihr die Schwarzbrandhöhle betreten?",a="Nein. Eingestürztes Felsgestein, Asche und Geröll versiegeln den Eingang der Schwarzbrandhöhle, sodass kein zugänglicher Innenraum zum Erkunden bleibt.",al={"ist die schwarzbrandhöhle offen","schwarzbrandhöhle betreten","in der schwarzbrandhöhle"}},{q="Wo liegt die Schwarzbrandhöhle?",a="Die Schwarzbrandhöhle liegt im Südwesten der Sengenden Schlucht, zwischen felsigen Ausläufern nahe dem Durchgang zum Schwarzfels.",al={"lage der schwarzbrandhöhle","wo ist die schwarzbrandhöhle"}}},fp="14,77,18.197.0,33.106.0,32.116.0"}
P.entries["subzone:blackfathom-deeps"] = {n="Tiefschwarze Grotte",s="Naga, Satyren und der Schattenhammerkult halten die Tiefschwarze Grotte unter Eschentals nordwestlicher Küste besetzt. Überflutete Hallen, die einst Elune ehrten, liegen unter dem Zoramstrand in Trümmern.",h="Naga, Satyren und der Schattenhammerkult halten die Tiefschwarze Grotte unter Eschentals nordwestlicher Küste...",kw={"aku'mai","blackfathom","tiefen","ghamoo-ra","kelris","sarevess","schattenhammerkult","der zoramstrand"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass die Grotte beunruhigend nahe an Zoram'gar liegt. Die Kultisten und Naga, die sich am Zoramstrand sammeln, bedrohen die Verteidiger des Außenpostens.",["race:NightElf"]="Als Kaldorei trauert Ihr vielleicht um dieses uralte Heiligtum Elunes. Leerenkultisten und Naga haben seine heiligen Hallen und seinen Mondbrunnen entweiht."},sec={{t="Von Elunes Tempel zum finstersten Abgrund",b="Unter Eschentals nordwestlichen Klippen sind überflutete Hallen eines uralten Tempels erhalten geblieben. Bevor die Große Zerschlagung Kalimdor vor zehntausend Jahren zerriss, ehrte der Tempel Elune und besaß einen eigenen Mondbrunnen. Als der Brunnen der Ewigkeit kollabierte, versank das Heiligtum in den Wellen und galt für immer als verloren. Über Jahrtausende hinweg wichen die Küstenlinien zurück und der Boden verschob sich, sodass der Tempel teilweise überflutet unter den Klippen zurückblieb."},{t="Aku'mai und der Kult",b="Der Schattenhammerkult hat sich unter Zwielichtfürst Kelris im überfluteten Tempel niedergelassen. Die Verderbnis eines Alten Gottes ist durch die Tiefen der Erde emporgestiegen und hat den heiligen Mondbrunnen verunreinigt. Aus seinem Wasser erhob sich Aku'mai, eine monströse dreiköpfige Hydra und Diener des Alten Gottes. Naga unter der Führung von Lady Sarevess und umherstreifende Satyren schließen sich den Kultisten an, die Aku'mai Unschuldige opfern, um Macht zu erlangen."}},faq={{q="Wofür wurde die Tiefschwarze Grotte ursprünglich erbaut?",a="Bevor sie bei der Zerschlagung in den Wellen versank, war die Tiefschwarze Grotte ein Nachtelfentempel für Elune mit einem heiligen Mondbrunnen in seinem Herzen.",al={"bfd geschichte","was war die tiefschwarze grotte","bfd tempel"}},{q="Warum ist der Schattenhammerkult hier?",a="Der Schattenhammerkult kam, um Aku'mai anzubeten, eine urzeitliche Hydra und Diener eines Alten Gottes. Unter Zwielichtfürst Kelris opfert der Kult der Bestie Unschuldige, um dunkle Macht zu erlangen.",al={"warum sind kultisten in bfd","schattenhammerkult blackfathom","kelris ziel"}},{q="Wo befindet sich der Eingang?",a="Der Eingang liegt in höhlenartigen Ruinen am Zoramstrand, an Eschentals äußerster Nordwestküste. Ihr durchquert überflutete Kammern und feindliche Naga-Außenposten, um das Tempelportal zu erreichen.",al={"wo ist bfd","tiefschwarze grotte lage","wie kommt man in bfd"}},{q="Wer ist Ghamoo-ra?",a="Ghamoo-ra ist eine riesige, wahnsinnig gewordene Schildkröte, die auf einer Insel in einer der überfluteten Tempelhöhlen lauert. Sie greift jeden Eindringling an, der sich ihr nähert.",al={"riesenschildkrötenboss","ghamoo-ra hintergrundgeschichte","schildkröte bfd"}}},fx={f0315c0b={q="Was ist die Tiefschwarze Grotte?",a="Die Tiefschwarze Grotte ist eine überflutete unterirdische Ruine, die unter The Zoram Strand an der Küste des Eschentals liegt. Einst war es ein prächtiger Nachtelfentempel, der der Mondgöttin Elune gewidmet war; er zerbrach und versank während des Großen Bruchs. Heute bilden die teilweise überfluteten Hallen und Meereshöhlen ein dunkles Heiligtum, das von Kultisten, uralten Bestien und den abscheulichen Dienern der Alten Götter beansprucht wird.",al={"was ist die tiefschwarze grotte","überblick über die tiefschwarze grotte","erzähl mir von der tiefschwarzen grotte"}},["11da3285"]={q="Was ist in der Tiefschwarzen Grotte geschehen?",a="Vor langer Zeit errichteten die Nachtelfen diesen Tempel für Elune, komplett mit heiligen Becken und einem Mondbrunnen. Vor zehntausend Jahren riss der Große Bruch Kalimdor auseinander und stieß das Heiligtum unter die Wellen. Obwohl man es für immer verloren glaubte, ist die Verderbnis der Alten Götter in den Mondbrunnen eingedrungen und hat finstere Mächte zurück in die lichtlosen Ruinen gelockt, um einen uralten Schrecken zu erwecken.",al={"geschichte der tiefschwarzen grotte","was ist hier passiert","geschichte von lathar'lazal"}},bfbbd665={q="Warum ist die Tiefschwarze Grotte eine Ruine?",a="Der Tempel wurde zerstört, als der Brunnen der Ewigkeit während des Großen Bruchs vor zehntausend Jahren implodierte. Die Katastrophe spaltete den Kontinent und versenkte den Tempelkomplex unter dem eindringenden Meer, ertränkte dessen Mondbrunnen und verwandelte die prachtvolle Architektur in ein dunkles, überflutetes Höhlensystem.",al={"warum ist sie eine ruine","warum ist blackfathom überflutet","warum ist sie zerstört"}},e7974e12={q="Ist die Tiefschwarze Grotte gefährlich?",a="Sie ist außerordentlich gefährlich. Tief im Inneren schlachten fanatische Kultisten Gefangene in blasphemischen Riten ab, um Aku'mai zu stärken, eine urzeitliche Bestie, deren Erwachen droht, das Chaos über Kalimdor zu bringen. Eindringlinge müssen die überfluteten Tunnel durchqueren, in denen rasende aquatische Bestien, grausame Naga-Zauberer, gerissene Satyrn und Kultisten lauern, die jeden Außenstehenden töten werden, um ihre Rituale zu verbergen.",al={"ist die tiefschwarze grotte sicher","wie gefährlich ist die tiefschwarze grotte","gefahren der tiefschwarzen grotte"}},e07691c2={q="Wer lebt in der Tiefschwarzen Grotte?",a="Der versunkene Tempel wird vom Kult des Schattenhammers beherrscht, angeführt von Zwielichtfürst Kelris, der dunkle Rituale und Blutopfer für ihre schattenhaften Meister durchführt. Neben den Kultisten hausen schlangenförmige Naga unter Lady Sarevess, verdorbene Satyren, die von der uralten Macht angezogen wurden, und aquatische Monströsitäten – allen voran Aku'mai, eine monströse Hydra und Diener eines Alten Gottes.",al={"wer lebt hier","wer kontrolliert die tiefschwarze grotte","wer ist in blackfathom"}}},fp="17,177,36.425.0,20.383.1,48.140.0,39.177.0,30.192.0,17.138.0"}
P.entries["subzone:blackrock-mountain"] = {n="Der Schwarzfels",s="Im Schwarzfels kämpfen rivalisierende Armeen über Tiefen, die von Feuer und Krieg gezeichnet sind. Die Beschwörung von Ragnaros ließ den Vulkan zwischen der Brennenden Steppe und der Sengenden Schlucht aufsteigen, und seine Wurzeln bergen heute Zwergenhallen.",h="Im Schwarzfels kämpfen rivalisierende Armeen über Tiefen, die von Feuer und Krieg gezeichnet sind.",kw={"der schwarzfels","schwarzfelsspitze","brennende steppe","schicksalshammer","ragnaros","sengende schlucht","shadowforge","thaurissan"},ang={["faction:Horde"]="Für die Horde erinnert die Schwarzfelsspitze an Knechtschaft und Blutvergießen unter Schicksalshammer. Orcische Schurken, die Thralls Führung ablehnen, kämpfen nun um sie.",["race:Dwarf"]="Für Zwerge steht der Schwarzfels für ein dunkles Kapitel ihrer Geschichte. Die Torheit des Dunkeleisenklans kostete sie ihre Freiheit und hinterließ Narben in den Östlichen Königreichen."},sec={{t="Ein kataklysmischer Ursprung",b="Der Schwarzfels entstand im Krieg der drei Hämmer vor zweieinhalb Jahrhunderten. Die vereinten Armeen von Eisenschmiede und dem Wildhammer clan drohten, die Dunkeleisenzwerge zu vernichten. Also griff Sorcerer-Thane Thaurissan nach einer Waffe tief in der Erde, und sein Zauber durchbrach die Barrieren zwischen den Welten. Er brachte Ragnaros den Feuerfürsten nach Azeroth.\n\nDie Explosion riss das Rotkammgebirge auseinander, schuf die Sengende Schlucht und die Brennende Steppe und schleuderte einen gewaltigen Vulkan gen Himmel. Thaurissan starb bei der Zerstörung. Der überlebende Dunkeleisenklan wurde dazu verdammt, dem Feuerfürsten auf ewig zu dienen. Sie schlugen Shadowforge City tief in den Wurzeln des Berges aus dem Stein."},{t="Zitadelle aus Asche und Blut",b="Im Ersten und Zweiten Krieg nahm der Schwarzfels einen düsteren Platz in der Geschichte ein. Nach der Plünderung von Sturmwind säuberte Orgrim Schicksalshammer den Schattenrat und machte die Schwarzfelsspitze zur Festungshauptstadt der Horde. Der Berg bleibt ein Schlachtfeld.\n\nDunkeleisenzwerge und ihr elementarer Meister beherrschen die feurigen Tiefen. Darüber besetzen Schurken unter den Schwarzfelsorcs, Drachenbrut und ihre dunklen Meister die Spitzen."}},faq={{q="Wie entstand der Schwarzfels?",a="Der Schwarzfels entstand vor etwa zweihundertfünfzig Jahren während des Krieges der drei Hämmer. Sorcerer-Thane Thaurissan suchte unter der Erde nach Macht, um rivalisierende Zwergenklans zu besiegen. Sein Zauber beschwor Ragnaros den Feuerfürsten und entfesselte die Explosion, die den Vulkan aufsteigen ließ.",al={"ursprung des schwarzfels","wer erschuf den schwarzfels","wie entstand der vulkan"}},{q="Warum heißt er Schwarzfels?",a="Kein Bericht nennt die erste Person, die ihn Schwarzfels nannte. Auch die Schwarzfelsorcs tragen diesen Namen. Im Zweiten Krieg machte Orgrim Schicksalshammers Horde die Schwarzfelsspitze zu ihrer Hauptstadt, und Überreste des Schwarzfelsklans halten sie noch immer.",al={"herkunft des namens schwarzfels","nach dem schwarzfelsklan benannt"}},{q="Wer kontrolliert den Schwarzfels derzeit?",a="Dunkeleisenzwerge halten die Hallen von Shadowforge City und dienen Ragnaros. Über ihnen beherrschen Überreste des Schwarzfelsklans und schwarze Drachenbrut die Schwarzfelsspitze.",al={"wer lebt im schwarzfels","wer herrscht über den schwarzfels"}},{q="Welche Gebiete verbindet der Schwarzfels?",a="Wege und Ketten im Inneren des Schwarzfels verbinden die Sengende Schlucht im Norden mit der Brennenden Steppe im Süden.",al={"wie durch den schwarzfels gelangen","verbindungen durch den schwarzfels"}}},fp="18,208,20.647.0,24.398.0,35.276.0,35.230.0,42.149.0,46.127.0"}
P.entries["subzone:blackrock-pass"] = {n="Schwarzfelspass",s="Am Schwarzfelspass markiert ein schweres Eisentor den Weg vom Rotkammgebirge in die Brennende Steppe. Der Korridor verläuft unterhalb der Klippen nach Norden, von den Kernlanden der Menschen zu den Kriegsgebieten der Dunkeleisenzwerge und Schwarzfelsorcs. Reisende zu Fuß überqueren eine raue Grenze.",h="Am Schwarzfelspass markiert ein schweres Eisentor den Weg vom Rotkammgebirge in die Brennende Steppe.",kw={"schwarzfelsorcs","schwarzfelspass","brennende steppe","grenze","tor","seenhain","rotkammgebirge"},ang={["faction:Alliance"]="Für die Verteidiger des Rotkammgebirges und das Königreich Sturmwind ist der Schwarzfelspass eine ständige Quelle der Furcht. Er bietet den Schwarzfelsorcs einen direkten Weg nach Süden in die Lande der Menschen."},sec={{t="Eine versengte Schwelle",b="Der Schwarzfelspass durchschneidet die Berge zwischen dem Rotkammgebirge und der Brennenden Steppe. Ein schweres Eisentor markiert die felsige Grenze jenseits der Wälder und Seen der südlichen Täler. Südlich des Tores schützt die bedrängte Miliz von Seenhain ländliche Gebiete. Nördlich davon bevölkern Feuerelementare, Drachenbrut und feindliche Kriegstrupps der Orcs ein offenes Ödland. Nur wenige überqueren den Pass zu Fuß, sofern ihr Ziel nicht im Schatten des Schwarzfels selbst liegt."}},faq={{q="Wohin führt der Schwarzfelspass?",a="Der Schwarzfelspass führt von der Nordgrenze des Rotkammgebirges an den südlichen Rand der Brennenden Steppe. Er bietet einen direkten Landweg zwischen den südlichen Gebieten der Allianz und den Ausläufern des Schwarzfels.",al={"wohin führt der schwarzfelspass","ziel des schwarzfelspasses","weg vom rotkammgebirge in die brennende steppe"}},{q="Können Reisende aus Seenhain den Pass sicher überqueren?",a="Nein. Die Lande nördlich des Passes sind weitaus gefährlicher als die Hügel im Rotkammgebirge. Wilde Schwarzfelsorcs, riesige Feuerelementare und schwarze Welpen machen die Brennende Steppe für Abenteurer niedriger Stufen und gewöhnliche Reisende gefährlich.",al={"ist der schwarzfelspass passierbar","ist der schwarzfelspass gefährlich","stufenanforderung schwarzfelspass"}},{q="Wer kontrolliert den Schwarzfelspass?",a="Weder Sturmwind noch die Horde kontrolliert den Schwarzfelspass vollständig. Schwarzfelsorcs und wilde Tiere bedrängen den spärlich befestigten Engpass, während die Stadtwachen im Rotkammgebirge von unten voller Furcht hinaufblicken.",al={"wem gehört der schwarzfelspass","wachen am schwarzfelspass","fraktionskontrolle schwarzfelspass"}}},fp="14,269,20.433.0,31.234.0,58.235.0,28.210.0"}
P.entries["subzone:blackrock-stronghold"] = {n="Schwarzfelsfestung",s="Orcs der Dunklen Horde sichern von der Schwarzfelsfestung aus die Zugänge zum Schwarzfels. Ihr befestigtes Lager ist eine Feldgarnison in der Brennenden Steppe.",h="Orcs der Dunklen Horde sichern von der Schwarzfelsfestung aus die Zugänge zum Schwarzfels.",kw={"schwarzfelsklan","schwarzfelsfestung","brennende steppe","dunkle horde","rend schwarzfaust"},ang={["faction:Alliance"]="Die Festung erinnert an den Zweiten Krieg. Sie liegt in Schlagweite der nördlichen Grenzen des Königreichs Sturmwind.",["faction:Horde"]="Für Thralls Horde erinnert der Schwarzfelsklan an die Schande der Old Horde: blutdürstige, verderbte Überreste, die Ehre und Frieden ablehnen."},sec={{t="Garnison der Dunklen Horde",b="Die Schwarzfelsfestung erstreckt sich über die verbrannten Ausläufer unterhalb des Schwarzfels. Der Schwarzfelsklan unterhält hier in der Brennenden Steppe seinen Hauptstützpunkt. Diese Orcs halten an den alten Wegen des Krieges fest. Sie folgen Rend Schwarzfaust und der Drachenbrut, die oben in der Spitze lauert, nicht Thralls Horde."},{t="Frontlinie der Schwarzfelsspitze",b="Die Schwarzfelsfestung bewacht die südlichen Zugänge zum Berg. Ihre Truppen sammeln sich für Angriffe auf das Rotkammgebirge und die benachbarten Menschenlande. Die Wache ist unablässig, und jeder, der das verheerte Ödland durchquert, wird von ihr gestellt."}},faq={{q="Was ist die Schwarzfelsfestung?",a="Im Norden der Brennenden Steppe bewacht die Schwarzfelsfestung die Zugänge zum Schwarzfels. Die Schwarzfelsorcs nutzen sie als vorgelagerte Garnison.",al={"was ist dieser ort","schwarzfelsfestung brennende steppe","was ist die schwarzfelsfestung"}},{q="Sind die Orcs hier Thralls Horde freundlich gesinnt?",a="Nein. Die Orcs in der Schwarzfelsfestung gehören zur Dunklen Horde unter Rend Schwarzfaust. Sie lehnen Thralls Führung ab und stehen sowohl der Allianz als auch Thralls Horde feindlich gegenüber.",al={"ist das die horde","gehören schwarzfelsorcs zur horde","der horde freundlich gesinnt"}}},fp="20,149,26.286.0,29.233.0,29.146.0,45.172.0"}
P.entries["subzone:blackthorn-ridge"] = {n="Schwarzdorngrat",s="Am Schwarzdorngrat bewachen Stachelmähnen-Stacheleber das südliche Brachland nördlich vom Kral der Klingenhauer. Brine, ein Orc-Schamane, hält von einem Lager über einem Becken mit ungewöhnlich reinem Bergwasser aus Wache.",h="Am Schwarzdorngrat bewachen Stachelmähnen-Stacheleber das südliche Brachland nördlich vom Kral der...",kw={"brachland","schwarzdorngrat","brine","reines wasser","stacheleber","kral der klingenhauer","stachelmähnen"},ang={["class:Shaman"]="Als junger Schamane der Horde könnt Ihr Brine am Grat aufsuchen und inmitten der rauen, trockenen Ebenen etwas über die Reinheit natürlicher Wasserelemente erfahren.",["faction:Horde"]="Stachelmähnen-Stacheleber bedrohen die Versorgungslinien der Horde durch das südliche Brachland in Richtung Tausend Nadeln. Durchreisende Karawanen müssen wachsam bleiben."},sec={{t="Eine dornenüberwucherte Schanze",b="Neben dem Kral der Klingenhauer erhebt sich der Schwarzdorngrat aus dichtem, scharfem Dornengestrüpp. Die Stachelmähnen-Stacheleber beanspruchen diese Hänge als Land ihrer Ahnen. Sie nutzen die Dornenbarrieren, um Fremden aufzulauern und im südlichen Brachland Scharmützel auszutragen. Trotz der Gefahr suchen Reisende den Grat weiterhin auf, angezogen von Brine, einem als Einsiedler lebenden Orc-Schamanen. Sein Lager überblickt eine Quelle, die in ganz Kalimdor für ihr klares, spirituell reines Wasser berühmt ist."}},faq={{q="Wo liegt der Schwarzdorngrat?",a="Der Schwarzdorngrat liegt im äußersten Süden des Brachlands, unmittelbar nördlich des Dornengestrüpps um den Kral der Klingenhauer und südlich von Camp Taurajo.",al={"schwarzdorngrat lage","wo liegt schwarzdorn","wie den schwarzdorngrat finden"}},{q="Wer lebt am Schwarzdorngrat?",a="Feindselige Stachelmähnen-Stacheleber besetzen die Talsohle. Brine, ein Orc-Schamane, lebt auf einem Felsvorsprung über ihrem Dornengestrüpp und wacht über die nahe Bergquelle.",al={"wer ist am schwarzdorngrat","schwarzdorngrat bewohner","stacheleber schwarzdorn"}},{q="Warum ist das Wasserbecken unter Brines Lager besonders?",a="Ein verborgenes Becken unterhalb des Grats birgt außergewöhnlich reines, klares Wasser, trotz der trockenen Ebenen und der Dornendickichte der Stacheleber ringsum. Schamanen nutzen das Becken als heiligen Mittelpunkt ihrer Rituale.",al={"brine wasserbecken","wasser von schwarzdorn","schwarzdorngrat quelle"}}},fx={a60eac08={q="Was ist der Schwarzdorngrat?",a="Der Schwarzdorngrat ist ein zerklüftetes, von Dornengestrüpp überwuchertes Tal im südlichen Brachland, nördlich der gewaltigen Stacheleberfestung namens Kral der Klingenhauer. Das Gebiet hat seinen Namen von dem hohen Grat, der sich über dem Tal erhebt, wo sich massives Dornengestrüpp über den trockenen Fels windet. Es dient als befestigter Außenposten für die örtlichen Stacheleberstämme, abgelegen von den offenen Ebenen.",al={"was ist der schwarzdorngrat","überblick über den schwarzdorngrat","erzähl mir von dem schwarzdorngrat"}},["4cf5ece9"]={q="Ist der Schwarzdorngrat gefährlich?",a="Ja, für unvorsichtige Reisende ist er äußerst gefährlich. Der Talgrund und die umliegenden Pfade werden stark von feindseligen Stachelebern der Klingenhauer durchstreift, die die Zugänge zum Kral der Klingenhauer bewachen. Abgesehen von einem isolierten Orc-Schamanen namens Brine, der auf dem hohen Grat lagert, gibt es keine freundlichen Außenposten oder sicheren Pfade durch das Dickicht.",al={"ist der schwarzdorngrat sicher","gefahr im schwarzdorngrat","wie gefährlich ist der schwarzdorngrat"}}},fp="16,180,22.409.0,26.124.0,30.162.0,45.191.0"}
P.entries["subzone:blackwolf-river"] = {n="Schwarzwolfschnellen",s="Durch die Scherwindklippe tragen die Schwarzwolfschnellen Abwässer aus der Holzgewinnung und den Industrieanlagen der Venture Company. Ihre Wasser fließen vom Felskesselsee herab.",h="Durch die Scherwindklippe tragen die Schwarzwolfschnellen Abwässer aus der Holzgewinnung und den...",kw={"schwarzwolfschnellen","felskesselsee","abholzung","verschmutzung","steinkrallengebirge","venture co","venture company","die scherwindklippe"},ang={["class:Druid"]="Als Druide erkennt Ihr, wie die Holzgewinnung der Goblins die Schwarzwolfschnellen verschmutzt. Solches Treiben ist dem Zirkel des Cenarius und allen, die Kalimdors ungezähmte Gewässer verehren, ein Frevel.",["race:Tauren"]="Als Tauren seht Ihr, wie Außenstehende auf der Suche nach Profit die Erde schänden und ihre Gewässer verschmutzen. Das bestärkt Euch darin, das Steinkrallengebirge von den Verheerungen rücksichtsloser Industrie zu reinigen."},sec={{t="Industrielle Abwässer",b="Vom Felskesselsee gespeist, fließen die Schwarzwolfschnellen durch die Scherwindklippe. Holzfäller der Venture Company roden die umliegenden Wälder mit schweren Maschinen und Kreissägen. Schlamm, Öl und Holzabfälle gelangen in die Strömung und tragen den Preis der Unternehmensarbeit durch das Becken."}},faq={{q="Wo entspringen die Schwarzwolfschnellen und wohin fließen sie?",a="Die Schwarzwolfschnellen fließen vom Felskesselsee durch das abgeholzte Becken der Scherwindklippe.",al={"quelle der schwarzwolfschnellen","wo sind die schwarzwolfschnellen","lage der schwarzwolfschnellen"}},{q="Warum ist das Flusswasser verschmutzt?",a="Die Venture Company holzt überall in der Scherwindklippe mit schweren Maschinen. Abwässer, Abfälle und Kahlschlag verschmutzen den Fluss.",al={"warum sind die schwarzwolfschnellen schmutzig","verschmutzung der schwarzwolfschnellen","verschmutzung durch venture company"}},{q="Wer ist derzeit entlang des Flusses tätig?",a="Die Venture Company arbeitet entlang des Flusses, schlägt Holz und betreibt Maschinen im Tal, trotz des Widerstands der örtlichen Tierwelt und der einheimischen Bewohner.",al={"wer kontrolliert die schwarzwolfschnellen","wer ist an den schwarzwolfschnellen","feinde nahe den schwarzwolfschnellen"}}},fx={d14d2651={q="Was ist die Geschichte der Schwarzwolfschnellen?",a="Die Schwarzwolfschnellen flossen einst klar durch das Herz des Steinkrallengebirges und strömten vom Felskesselsee über Die Scherwindklippe. Dieses Gleichgewicht wurde zerstört, als die Venture Company ihre Schwerindustrie in die Klippe verlegte. Ihre aggressive Abholzung und mechanisierte Holzfällerei vergifteten den Wasserlauf schnell und verwandelten einen unberührten Gebirgsbach in einen giftigen, schlammigen Abfluss für die Goblin-Industrie.",al={"lore der schwarzwolfschnellen","geschichte der schwarzwolfschnellen","was ist mit den schwarzwolfschnellen passiert"}},["476e6164"]={q="Sind die Schwarzwolfschnellen gefährlich?",a="Ja, sowohl das Wasser als auch die Ufer bergen ernsthafte Gefahren. Der Fluss selbst führt giftige Industrieabwässer von den Holzfällarbeiten der Venture Company flussaufwärts. Darüber hinaus wimmelt die umliegende Klippe von aggressiven Arbeitern, Holzfällern und mechanisierten Schreddern der Venture Company, die ihre Maschinen erbittert bewachen und Holz fällen, ohne Rücksicht auf jeden, der dort vorbeikommt.",al={"sind die schwarzwolfschnellen sicher","gefahren der schwarzwolfschnellen"}}},fp="15,151,17.265.0,46.84.0,32.117.0,43.161.0"}
P.entries["subzone:blackwood-den"] = {n="Bau der Schwarzfelle",s="Im Süden der Dunkelküste ist der Bau der Schwarzfelle der Verderbnis der Schwarzfellfurbolgs erlegen. Ihre Höhle und Lager, einst ein friedliches Heim nahe Eschental, hallen nun von Wahnsinn wider. Volcor, ein Nachtelfenspäher, sitzt darin fest und wartet auf Hilfe aus Auberdine.",h="Im Süden der Dunkelküste ist der Bau der Schwarzfelle der Verderbnis der Schwarzfellfurbolgs erlegen.",kw={"eschental","auberdine","bau der schwarzfelle","blackwood hold","dunkelküste","furbolg","volcor"},ang={["class:Druid"]="Als Druide mögt Ihr um die Furbolgs trauern, die einst standhafte Beschützer der Wildnis waren. Der Wahnsinn im Bau der Schwarzfelle ist ein weiteres schmerzliches Zeichen für Kalimdors verdorbene Natur.",["race:NightElf"]="Für die Nachtelfen von Auberdine ist die Verderbnis des Stammes der Schwarzfelle eine Tragödie. Volcors Rettung ist eine dringende Pflicht, um ihr Volk entlang der südlichen Straße zu schützen."},sec={{t="Eine verderbte Bastion",b="Nahe der südlichen Grenze zwischen Dunkelküste und Eschental halten Furbolgs der Schwarzfelle eine felsige Höhle und primitive Lager besetzt. Verderbnis hat den Stamm erfasst, und seine Mitglieder greifen Außenstehende an. Tief in der Höhle sitzt der Nachtelf Volcor fest und schwebt in Gefahr. Späher und Reisende aus Auberdine werden gebraucht, um ihm zu helfen."}},faq={{q="Was ist der Bau der Schwarzfelle?",a="Der Bau der Schwarzfelle ist eine Furbolgsiedlung mit einem Höhlenkomplex im äußersten Süden der Dunkelküste, nahe Eschental. Der verderbte Stamm der Schwarzfelle hat dort sein Zuhause.",al={"was ist der bau der schwarzfelle","blackwood hold","wo ist der bau der schwarzfelle"}},{q="Wer befindet sich in der Höhle im Bau der Schwarzfelle?",a="Volcor, ein Nachtelf, sitzt hinter den feindlichen Linien in der Höhle fest. Reisende, die ihn finden, müssen mit Verbündeten in Auberdine zusammenarbeiten, um ihm sicher aus dem Bau zu helfen.",al={"wer sitzt in der höhle fest","wer ist volcor","elf im bau der schwarzfelle"}},{q="Warum sind die Furbolgs hier feindselig?",a="Die Verderbnis, die sich nach dem Dritten Krieg über die Dunkelküste und Kalimdor ausbreitet, hat die Furbolgs der Schwarzfelle in den Wahnsinn getrieben. Sie greifen Außenstehende an, sobald sie sie erblicken.",al={"warum sind die furbolgs der schwarzfelle aggressiv","sind die furbolgs der schwarzfelle böse","verderbte furbolgs dunkelküste"}}},fx={["9f3b6295"]={q="Was ist im Bau der Schwarzfelle geschehen?",a="Der Bau der Schwarzfelle war einst eine gewöhnliche Siedlung des Schwarzfell-Furbolgstammes im südlichen Dunkelküste. Doch wie ein Großteil der lokalen Tierwelt und der einheimischen Stämme fielen auch die Furbolgs hier einer dunklen Verderbnis zum Opfer, die sich über das Land ausbreitete. Von ihren einst friedlichen Wegen abgekommen, wurden sie erbittert aggressiv, errichteten befestigte Lager und fingen Außenstehende, die es wagten, sich ihren Höhlen zu nähern.",al={"geschichte vom bau der schwarzfelle","was ist im bau der schwarzfelle passiert"}},d219a6ba={q="Wer lebt im Bau der Schwarzfelle?",a="Der Bau und die umliegenden Lager werden von den verderbten Schwarzfell-Furbolgs gehalten, die ihr Territorium aggressiv gegen jeden Eindringling verteidigen. Tief in der Höhle ist ein unglücklicher Nachtelf namens Volcor gefangen, in die Enge getrieben von den feindseligen Furbolgs, und wartet auf die Rettung durch jeden, der mutig genug ist, sich durch den Bau zu kämpfen.",al={"wer lebt im bau der schwarzfelle","bewohner des baus der schwarzfelle","wer hält den bau der schwarzfelle"}},["3aa28176"]={q="Ist der Bau der Schwarzfelle gefährlich?",a="Ja, er ist sehr gefährlich. Die Schwarzfell-Furbolgs bewohnen mehrere zusammenhängende Lager direkt vor dem Höhleneingang und im gesamten Bau selbst. Verderbt und gewalttätig greifen sie jeden Außenstehenden sofort in Rudeln an, was jeden Versuch, in das Innere vorzudringen – besonders um den gefangenen Nachtelfen Volcor zu erreichen –, ohne sorgfältige Vorbereitung zu einem tödlichen Unterfangen macht.",al={"ist der bau der schwarzfelle gefährlich","gefahren des baus der schwarzfelle","wie gefährlich ist der bau der schwarzfelle"}},f77a0955={q="Warum heißt er Bau der Schwarzfelle?",a="Der Bau hat seinen Namen von dem Schwarzfell-Furbolgstamm, der hier zu Hause ist. In den südlichen Ausläufern der Dunkelküste nahe der Grenze zum Eschental gelegen, dienen die Höhle und die umliegenden Lager als zentrale Behausung und Zufluchtsort für diesen verderbten Clan.",al={"warum heißt er bau der schwarzfelle","bedeutung des namens bau der schwarzfelle","woher hat der bau der schwarzfelle seinen namen"}}},fp="13,246,22.313.0,22.149.0,40.160.0,34.141.0"}
P.entries["subzone:blackwood-lake"] = {n="Faulholzsee",s="Im Süden der Östlichen Pestländer wacht ein kleines Lager der Argentumdämmerung über den Faulholzsee. Seine Wasser wimmeln von feindseligen, verderbten Elementaren und bergen Erinnerungen an Tragödien und Krieg.",h="Im Süden der Östlichen Pestländer wacht ein kleines Lager der Argentumdämmerung über den Faulholzsee.",kw={"blackwood","darrowshire","elementare","horgus","see","plaguelands"},ang={["class:Paladin"]="Als Paladin seht Ihr, wie die Fäulnis Lordaerons natürliche Elementare in den verseuchten Wassern und der verfallenden Umgebung des Faulholzsees verdirbt. Sie brauchen die reinigende Berührung des Lichts.",["race:Human"]="Für die Menschen Lordaerons ruft der Faulholzsee in Erinnerung, wie gründlich die Geißel das ländliche Kernland des Königreichs vergiftet hat."},sec={{t="Eine verseuchte Erinnerung",b="Die Seuche, die weite Teile des Eastweald vergiftet, hat den Faulholzsee erreicht. Kranke Wasserelementare wühlen unter seiner trüben Oberfläche und greifen jeden an, der sich dem Ufer nähert."},{t="Relikte der Gefallenen",b="Der Faulholzsee birgt düstere Relikte aus der Schlacht von Darrowshire. Die Erweiterten Annalen von Darrowshire berichten, dass der abgetrennte Schädel von Horgus dem Verwüster in seine ranzigen Tiefen geworfen wurde.\n\nIn der Nähe versorgt ein Sanitäter der Argentumdämmerung angeschlagene Infanteristen an einem kleinen vorgeschobenen Außenposten. Der Sanitäter ringt darum, die Soldaten inmitten der Verwüstungen der Geißel am Leben zu erhalten."}},faq={{q="Welche Kreaturen lauern im Faulholzsee?",a="Verderbte Wasserelementare bevölkern den Faulholzsee. Nekromantische Abwässer und Unrat haben die Süßwassergeister der Plaguelands in gewalttätige, giftige Wesen verwandelt.",al={"was ist im wasser","seeungeheuer","elementare im faulholzsee"}},{q="Warum ist die Argentumdämmerung am See stationiert?",a="Die Argentumdämmerung unterhält ein kleines Feldlager nahe dem Faulholzsee. Dort versorgt ein Argent Medic verwundete Infanteristen und unterstützt Patrouillen, die entlang der Straßen zwischen Darrowshire und nahe gelegenen Festungen der Geißel kämpfen.",al={"lager der argentumdämmerung","argent medic","warum sind hier soldaten"}},{q="Welches Relikt aus Darrowshire liegt im Faulholzsee begraben?",a="Laut den Annalen von Darrowshire liegt der Schädel von Horgus dem Verwüster im Faulholzsee. Horgus war einer der wichtigsten Anführer der Geißel beim Angriff auf Darrowshire. Er wurde niedergestreckt, und sein Schädel wurde in die Tiefen des Sees geschleudert.",al={"kopf von horgus dem verwüster","questgegenstand im see","annalen von darrowshire see"}}},fp="14,170,17.175.0,20.341.1,38.155.0,45.209.0,51.242.0"}
P.entries["subzone:bladefist-bay"] = {n="Messerbucht",s="An Durotars Ostküste öffnet sich die Messerbucht gleich vor Orgrimmars Toren zum großen Meer. Schroffe Klippen erheben sich über dem Ufer, gegenüber liegt Azsharas Südküste.",h="An Durotars Ostküste öffnet sich die Messerbucht gleich vor Orgrimmars Toren zum großen Meer.",kw={"bucht","messerfaust","durotar","großes meer","kargath","orgrimmar","shattered hand","die knochenhöhle"},ang={["class:Rogue"]="Als Schurke wisst Ihr, dass die Shattered Hand in Orgrimmars Schatten als Gilde der Diebe und Assassinen der Horde agiert. Für verdeckt operierende Agenten hat diese Küste eine stille Bedeutung.",["race:Orc"]="Als Orc wisst Ihr, dass die Bucht Kargath Messerfausts stolzen und brutalen Namen trägt. Sie erinnert an die Prüfungen des Clans Shattered Hand auf Draenor."},sec={{t="Eine Bucht am großen Meer",b="Die Messerbucht trifft an Durotars Nordostrand auf das große Meer, östlich von Orgrimmar, der Hauptstadt der Horde. Felsige Klippen erheben sich über ihrer tückischen Brandung. Im Norden, jenseits des Wassers, zeichnen sich Azsharas uralte rote Klippen und Ruinen am gegenüberliegenden Ufer ab. Hier trifft Durotar auf die offene See."},{t="Schatten der Shattered Hand",b="Kargath Messerfaust gab der Bucht ihren Namen. Als Häuptling des Clans Shattered Hand trennte er sich während der Prüfungen der alten Horde auf Draenor die eigene Hand ab und ersetzte sie durch eine Klinge. Ganz in der Nähe bietet die Knochenhöhle Kultisten und verborgenen Schurkennetzwerken Unterschlupf. Die Küste erinnert an das wilde und unbarmherzige Erbe des Clanhäuptlings."}},faq={{q="Nach wem ist die Messerbucht benannt?",a="Die Messerbucht ist nach Kargath Messerfaust benannt, dem Häuptling des Clans Shattered Hand. Während der Prüfungen der alten Horde auf Draenor ersetzte er seine abgetrennte Hand durch eine tödliche Sensenklinge.",al={"wer ist messerfaust","messerfaust namensgeber","kargath messerfaust bucht"}},{q="Wo liegt die Messerbucht?",a="Die Messerbucht erstreckt sich entlang Durotars Nordostküste, östlich von Orgrimmars Haupttoren. Azshara liegt im Norden auf der anderen Seite des Wassers.",al={"messerbucht lage","wo liegt die messerbucht","wie gelangt man zur messerbucht"}},{q="Welche Gefahren lauern rund um die Messerbucht?",a="Die Knochenhöhle liegt direkt an der Küste. Ihre Höhlen beherbergen Hexenmeister, Dämonen und Mitglieder des Kults Burning Blade.",al={"messerbucht gefahr","gefahren an der messerbucht","feinde in der messerbucht"}},{q="Warum wird die Bucht manchmal als Abfallhaufen bezeichnet?",a="Kein Bericht aus dieser Zeit bezeichnet die Bucht als Abfallhaufen. Sie ist ein felsiger Abschnitt von Durotars Küste östlich von Orgrimmar, gegenüber von Azshara auf der anderen Seite des Wassers.",al={"abfallhaufen","messerfaust treibgut","meeresmüll bucht"}}},fx={["6e8d698f"]={q="Was ist die Messerbucht?",a="Die Messerbucht ist eine Meeresbucht des Großen Meeres an der nordöstlichen Küste von Durotar, die östlich von Orgrimmar und südlich von Azshara liegt.",al={"was ist die messerbucht","messerbucht durotar","ueber die messerbucht"}}},fp="13,190,22.277.0,28.315.0,33.184.0,31.134.0,39.113.0,46.148.0"}
P.entries["subzone:bloodfen-burrow"] = {n="Blutsumpfbau",s="Blutsumpfraptoren drängen sich nun in der Höhle und auf der Lichtung im Südwesten der Düstermarschen. Sie haben die Ruinen einer Siedlung überrannt, die einst um ihr Überleben im Feuchtgebiet kämpfte.",h="Blutsumpfraptoren drängen sich nun in der Höhle und auf der Lichtung im Südwesten der Düstermarschen.",kw={"blutsumpfbau","blutsumpfraptor","cortello's riddle","düstermarschen","raptorenhöhle"},ang={["class:Hunter"]="Als Jäger könnt Ihr hier wilde, schnelle Blutsumpfraptoren finden. Sie sind zähe, angriffslustige Sumpfbegleiter."},sec={{t="Ein Bau voller Raubtiere",b="Blutsumpfraptoren drängen sich in der Höhle und der Senke im Südwesten der Düstermarschen. Die geschützte Spalte und die ergiebigen Jagdgründe locken das Rudel an. Vor dem Eingang zeugen verstreute Trümmer und zersplitterte Überreste von einer unbekannten Siedlung. Reisende flüstern auch, dass Cortello, ein abenteuerlustiger Freibeuter, einen seiner versteckten Rätselhinweise irgendwo im Bau hinterlassen hat."}},faq={{q="Was lebt im Blutsumpfbau?",a="Blutsumpfraptoren haben die Höhle und die umliegende Lichtung überrannt. Ihre Nester liegen dicht beieinander, und sie greifen jeden an, der ihr Revier betritt.",al={"wer lebt hier","blutsumpfbau raptoren","welche gegner im blutsumpfbau"}},{q="Was sind die Ruinen vor der Höhle?",a="Die Ruinen vor der Höhle sind alles, was von einer unbekannten Siedlung übrig ist. Raptoren haben sie zerstört, und keine Aufzeichnung nennt ihre Bewohner oder berichtet, was aus ihnen wurde.",al={"siedlungsruinen düstermarschen","wer baute die hütten beim blutsumpfbau","ruinen vor der höhle"}},{q="Warum sollte ein Abenteurer den Blutsumpfbau durchsuchen?",a="Entdecker auf der Suche nach Cortello's Riddle müssen den Blutsumpfbau betreten, um einen der versteckten Hinweise des Freibeuters zu finden. Wilde Sumpfraptoren locken auch Jäger in die Höhle.",al={"cortello's riddle bloodfen","schatz im blutsumpfbau","blutsumpfbau quest"}}},fp="15,173,18.355.0,30.141.0,36.164.0,47.164.1"}
P.entries["subzone:bloodhoof-village"] = {n="Dorf der Bluthufe",s="Im Dorf der Bluthufe am Stonebullsee bereiten sich junge Tauren auf den Weg nach Donnerfels vor. Baine Bluthuf führt sie, während sich das Dorf um Mulgোরes Verteidigung, Handel und Riten kümmert.",h="Im Dorf der Bluthufe am Stonebullsee bereiten sich junge Tauren auf den Weg nach Donnerfels vor.",kw={"baine bluthuf","dorf der bluthufe","camp narache","kodo","mulgore","stonebullsee","zarlman zwillingsmond"},ang={["faction:Horde"]="Für die Horde bietet das Dorf der Bluthufe einen friedlichen Zwischenhalt und eine wichtige Verbindung zwischen Mulgোরes südlichen Ebenen und der Hordenhauptstadt Donnerfels.",["race:Tauren"]="Für junge Tauren bedeutet der Einzug ins Dorf der Bluthufe den ersten wirklichen Schritt über die Jugend hinaus zu größerer Stammesverantwortung und spiritueller Reife."},sec={{t="Herz der Ebenen",b="Am Stonebullsee im Herzen Mulgোরes liegt das Dorf der Bluthufe, wohin junge Tauren nach ihren Prüfungen in Camp Narache kommen. Hier verfeinern sie ihre Fertigkeiten, bevor sie zu den großen Tafelbergen von Donnerfels weiterziehen. Geduldige Züchter zähmen wilde Kodobestien für die Reise, und das Dorf ist auch ein Zentrum für Handwerk und Zeremonien."},{t="Führung und Riten",b="Baine Bluthuf, Sohn des Obersten Häuptlings Cairne Bluthuf, wacht über die tägliche Verwaltung und die Verteidigung der Region. Krieger patrouillieren im Grasland, um angriffslustige Wildtiere, eindringende Borstennacken und die Venture Company abzuwehren.\n\nSpirituelle Führer wie Zarlman Zwillingsmond kümmern sich um das innere Leben des Stammes. Sie führen Neulinge auf heilige Reisen, darunter den Rite of Vision."}},faq={{q="Wer führt das Dorf der Bluthufe?",a="Baine Bluthuf, Sohn des Obersten Häuptlings Cairne Bluthuf, führt das Dorf der Bluthufe und leitet seine Verteidigung gegen Bedrohungen der zentralen Ebenen.",al={"dorfführung","baine bluthuf aufenthaltsort","wer leitet das dorf der bluthufe"}},{q="Welche bedeutenden Riten werden hier vollzogen?",a="Spirituelle Führer wie Zarlman Zwillingsmond geleiten junge Tauren durch den traditionellen Rite of Vision, eine wesentliche spirituelle Reise auf dem Weg zum Erwachsensein.",al={"rite of vision","spirituelle prüfungen","zarlman zwillingsmond quest"}},{q="Für welche Erzeugnisse ist die Siedlung bekannt?",a="Im Dorf der Bluthufe zähmen geduldige Züchter wilde Ebenenkodos und bilden sie zu Reittieren aus.",al={"reittiere der tauren","kodos zähmen","bluthuf trommeln"}},{q="Wohin ziehen Reisende, nachdem sie ihre Aufgaben hier erfüllt haben?",a="Nach ihren Taten im zentralen Mulgore werden Reisende gewöhnlich nach Norden nach Donnerfels geschickt, der Hauptstadt der Tauren.",al={"nach dem dorf der bluthufe","wohin nach dem dorf der bluthufe","nächster anlaufpunkt"}}},fx={["0d479a74"]={q="Was ist das Dorf der Bluthufe?",a="Das Dorf der Bluthufe ist eine wichtige Taurensiedlung im zentralen Mulgore am Ufer des Stonebullsees. Sie dient als primäre Station und Kreuzung für Reisende und junge Helden, die von Die Hochwolkenebene in Richtung Donnerfels nach Norden ziehen. Hier versammeln sich die Tauren, um zu handeln, spirituellen Rat zu suchen und wilde Kodos für die Reise zu zähmen.",al={"was ist bloodhoof","lore von bloodhoof","über bloodhoof"}},["4dcc3235"]={q="Ist das Dorf der Bluthufe gefährlich?",a="Das Dorf selbst ist ein gut bewachter Zufluchtsort, über den Baine Bluthuf und lokale Helden wachen. Die umliegenden Ebenen von Mulgore bergen jedoch ständige Gefahren, von streunenden Raubtieren und aggressiven Gnollen bis hin zu eindringenden Holzfällern der Venture Company und schattenhaften Grimtotem-Agenten, die gegen den Frieden der vereinigten Stämme arbeiten.",al={"gefahren von bloodhoof","ist bloodhoof sicher","bedrohungen für bloodhoof"}},["39f13758"]={q="Warum heißt es Dorf der Bluthufe?",a="Die Siedlung ist zu Ehren des Bluthuf-Stammes benannt, dem prominenten Tauren-Clan, der von Häuptling Cairne Bluthuf angeführt wird. Sie trägt stolz den Namen des Clans und bleibt unter der direkten Verwaltung von Cairnes Sohn, Baine.",al={"namensursprung von bloodhoof","warum bloodhoof","nach wem ist bloodhoof benannt"}}},fp="17,186,19.311.0,20.360.0,28.144.0,36.157.0,43.82.0,55.114.0"}
P.entries["subzone:bloodtooth-camp"] = {n="Blutreißers Lager",s="Im Herzen von Eschental liegt Blutreißers Lager westlich des Falfarren. Ran Bloodtooth führt die verderbten Furbolgs an, die jeden angreifen, der sich nähert. Späher der Allianz wollen die umliegenden Wälder läutern.",h="Im Herzen von Eschental liegt Blutreißers Lager westlich des Falfarren.",kw={"eschental","blutreißers lager","der falfarren","furbolg","krolg","raene's cleansing","ran bloodtooth"},ang={["faction:Alliance"]="Für Abenteurer der Allianz ist Blutreißers Lager ein Hort der Verderbnis, der Eschentals südliche Haine und Mondbrunnen bedroht.",["race:NightElf"]="Als Nachtelf seht Ihr den wahnsinnig gewordenen Stamm von Ran Bloodtooth als tragisches Zeichen der Verderbnis, die Eure angestammte Heimat heimsucht."},sec={{t="Ein verderbter Unterschlupf",b="Blutreißers Lager liegt südwestlich des südlichen Mondbrunnens und westlich des Falfarren. Die Furbolgs waren einst mit der heiligen Wildnis Kalimdors verbunden, doch anhaltende geistige Verderbnis hat ihren Stamm verzehrt. Ran Bloodtooth befehligt die primitive Siedlung. Seine Anhänger greifen Reisende ebenso an wie die Beschützer der Nachtelfen."},{t="Die Läuterung des Waldes",b="Die Schar von Ran Bloodtooth bedroht nahegelegene heilige Stätten, weshalb Schildwachen der Allianz und ihre Verbündeten ins Lager kommen. Sie unterstützen Raene Wolfsläufers Bemühungen, den Wald zu läutern. Krolg weist Abenteurer an, das Lager zu betreten, Ran Bloodtooth zu töten und seine Leibwächter zu besiegen."}},faq={{q="Wo liegt Blutreißers Lager?",a="Blutreißers Lager liegt im Herzen von Eschental, westlich des Falfarren und südwestlich des südlichen Mondbrunnens.",al={"blutreißers lager standort","wo ist blutreißers lager","blutreißers lager finden"}},{q="Warum sind die Furbolgs hier feindselig?",a="Anhaltende dämonische Verderbnis in Eschentals Wildnis hat den Bloodtooth-Klan und viele andere Furbolgstämme in den Wahnsinn getrieben und gegenüber Fremden aggressiv gemacht.",al={"warum greifen bloodtooth-furbolgs an","bloodtooth verderbnis","sind furbolgs hier böse"}},{q="Wer führt die Furbolgs in Blutreißers Lager an?",a="Ran Bloodtooth führt die Furbolgs im Lager an und befehligt seine Leibwächter.",al={"blutreißers lager boss","ran bloodtooth","wer führt blutreißers lager an"}},{q="Warum schickt die Allianz Späher hierher?",a="Während der Bemühungen um Raene’s Cleansing weist Krolg, ein verbannter Furbolg, die Streiter der Allianz an, das Lager anzugreifen, Ran Bloodtooth zu töten und die Bedrohung zu beseitigen, die seine Anhänger für die Region darstellen.",al={"blutreißers lager quest","warum ran bloodtooth töten","krolg mission"}}},fx={["3d0c2137"]={q="Ist Blutreißers Lager gefährlich?",a="Ja, es ist außerordentlich gefährlich. Die Furbolgs dort sind von Verderbnis zerfressen und greifen jeden, den sie sehen, in wildem Zorn an. Wer das Lager betritt, legt sich mit abgehärteten Furbolgkriegern und Ran Blutreißers persönlichen Leibwächtern an, was jeden unvorsichtigen Schritt zu einem tödlichen Fehler macht.",al={"ist blutreißers lager gefährlich","gefahr blutreißers lager","bedrohungen in blutreißers lager"}},["39c5c848"]={q="Warum heißt es Blutreißers Lager?",a="Die Siedlung hat ihren Namen von Ran Blutreißer, dem grimmigen Häuptling, der über den dort versammelten Stamm verderbter Furbolgs herrscht.",al={"warum heißt es blutreißers lager","bedeutung name blutreißers lager","wer ist blutreißer"}},f92ad28e={q="Was ist Blutreißers Lager?",a="Blutreißers Lager ist ein Lager im zentralen Eschental, westlich des Falfarren und südwestlich eines heiligen Mondbrunnens der Nachtelfen gelegen. Es dient als Festung für eine Bande verderbter Furbolgs, die unter dunkle Einflüsse geraten sind und nun gewaltsam gegen jeden vorgehen, der sich in ihr Territorium wagt.",al={"was ist blutreißers lager","lore von blutreißers lager","blutreißers lager im eschental"}},["15670459"]={q="Wer lebt in Blutreißers Lager?",a="Das Lager wird von einem Stamm wilder, verderbter Furbolgs unter dem Kommando von Ran Bloodtooth bewohnt. Bewacht von loyalen Furbolg-Beschützern und Leibwächtern, betrachten diese einst friedlichen Kreaturen alle Außenstehenden als Todfeinde und verteidigen ihr Lager mit wilder Feindseligkeit.",al={"wer lebt in blutreißers lager","furbolgs in blutreißers lager","bewohner von blutreißers lager"}}},fp="15,206,15.324.0,20.265.1,33.110.0,34.163.0,42.74.0,39.196.0"}
P.entries["subzone:bloodvenom-falls"] = {n="Die Blutgiftfälle",s="An den Blutgiftfällen stürzt giftiges Wasser über die nördlichen Klippen des Teufelswalds. Es speist den Blutgiftbach und trägt dämonische Fäulnis die Berge hinab und darüber hinaus.",h="An den Blutgiftfällen stürzt giftiges Wasser über die nördlichen Klippen des Teufelswalds.",kw={"die blutgiftfälle","blutgiftbach","verderbnis","dunkelküste","teufelswald","schleim","wasserfall","der wildbend"},ang={["class:Druid"]="Als Druide sind die Blutgiftfälle für Euch ein bitterer Anblick für den Zirkel des Cenarius. Ihr Wasser trägt die abscheuliche Krankheit des Teufelswalds in die tiefer gelegenen Lande.",["race:NightElf"]="Als Nachtelf seht Ihr, wie die Blutgiftfälle den vergifteten Wildbend in Dunkelküste speisen. Ihr Wasser bedroht die Heimat der Ahnen und die Heiligtümer an der Küste."},sec={{t="Ein Quell der Fäulnis",b="Die Blutgiftfälle stürzen über die Klippen im Teufelswald, eine grelle Wunde in Kalimdors uralten Wäldern. Das einst unberührte Wasser wurde während des Dritten Krieges durch dämonische Magie und die Überreste der Brennenden Legion verdorben. Die Fälle speisen den Blutgiftbach, der sich durch das Herz des Teufelswalds schlängelt. Dann stürzt der verseuchte Strom die Berghänge hinab und wird in Dunkelküste zum fauligen Wildbend, der die Fäulnis über die Grenzen des Teufelswalds hinausträgt."},{t="Gift für die Natur",b="Das abfließende Wasser der Blutgiftfälle verfärbt das Flussbett und verformt alles, was es berührt. Verdrehte Treants, kränkelnde Bestien und aggressive Schleime vermehren sich an den sumpfigen Ufern im Bereich ihrer Gischt. Für Druiden und Wächter, die die Fäulnis des Teufelswalds einzudämmen versuchen, zeigen die Fälle, wie schwer die Gewässer des nördlichen Kalimdors an ihrer Quelle noch erkrankt sind."}},faq={{q="Wohin fließt das Wasser der Blutgiftfälle?",a="Die Fälle speisen den Blutgiftbach, der sich durch den Teufelswald schlängelt. Dann stürzt er die Berge hinab nach Dunkelküste und wird zum verderbten Wildbend.",al={"wohin fließt der blutgiftbach","flussverlauf der blutgiftfälle","wohin fließt das wasser ab"}},{q="Warum ist der Wasserfall verderbt?",a="Während des Dritten Krieges durchdrang die dämonische Magie der Brennenden Legion die Region und verdarb die wilden Wälder des Teufelswalds. Teufelsfäulnis gelangte in die Quellen und hohen Gebirgsbäche, die die Fälle speisen, und verwandelte ihr Wasser in giftigen Schlamm.",al={"warum sind die blutgiftfälle grün","warum ist das wasser vergiftet","was hat die blutgiftfälle verderbt"}},{q="Wirkt sich die Verderbnis an den Fällen auf andere Gebiete aus?",a="Ja. Die Fluten stürzen vom Teufelswald über die westlichen Bergkämme hinab nach Dunkelküste. Dort treten sie als verseuchter Wildbend hervor und tragen Fäulnis zur Küste.",al={"vergiftet der teufelswald dunkelküste","wie wirkt sich das auf dunkelküste aus","flussverschmutzung in dunkelküste"}},{q="Lässt sich das Wasser der Blutgiftfälle reinigen?",a="Der Zirkel des Cenarius sucht weiter nach Wegen, den Teufelswald zu reinigen, doch der Fluss birgt gewaltige Mengen tief eingedrungener dämonischer Verderbnis. Die Heilung der Fälle bleibt ein gewaltiger Kampf, und die Verderbnis besteht fort.",al={"können druiden die blutgiftfälle heilen","lassen sich die blutgiftfälle reinigen","reinigung des wasserfalls"}}},fp="16,160,17.438.0,17.323.0,48.157.0,31.234.0,52.169.0,47.209.0"}
P.entries["subzone:bloodvenom-post"] = {n="Blutgiftposten",s="Am Blutgiftposten bewachen Hordewachen die hohen Klippen des Teufelswalds über der Dunkelküste. Ihre Siedlung im Stil der Tauren steht inmitten dämonischer Verderbnis und korrumpierter Tierwelt.",h="Am Blutgiftposten bewachen Hordewachen die hohen Klippen des Teufelswalds über der Dunkelküste.",kw={"blutgiftposten","blutgiftbach","klippen der dunkelküste","teufelswald","außenposten der horde","tauren"},ang={["faction:Horde"]="Als Mitglied der Horde findet Ihr in diesem Lager Schutz und einen Stützpunkt in der feindseligen Wildnis des Teufelswalds. Es ist die einzige befestigte Zuflucht der Horde in diesem Gebiet.",["race:Tauren"]="Als Tauren schließt Ihr Euch den tapferen Kriegern an, die diesen Posten unterhalten. Ihr untersucht die Schäden, die die Legion dem Land zugefügt hat, und bekämpft die Verderbnis, die seinen Naturgeistern schadet."},sec={{t="Ein gefährdeter Stützpunkt",b="Der Blutgiftposten klammert sich an die hohen Klippen des Teufelswalds über der Dunkelküste. Ein schmaler Pfad führt von der Hauptstraße am verseuchten Südufer des Blutgiftbachs entlang. Traditionelle Taurenzelte, Totems und Wachposten bieten Wanderern der Horde einen Stützpunkt im sterbenden Wald. Späher beobachten dämonische Streitkräfte, die durch die Region vorrücken, und untersuchen die Verderbnis in den Gewässern. Sie verfolgen auch Wildtiere, die durch die nachwirkende Macht der Brennenden Legion verändert wurden."},{t="Blicke über den Kamm",b="Von den Klippen aus überblickt der Blutgiftposten die verseuchte Wildnis des Teufelswalds und die nördliche Dunkelküste. Seine abgelegene Lage ermöglicht es den Streitkräften der Horde, die Bewegungen der Nachtelfen entlang der Westküste zu beobachten. Das Lager liegt zudem weit außerhalb der bequemen Reichweite von Allianzpatrouillen auf der zentralen Straße des Waldes."}},faq={{q="Wo liegt der Blutgiftposten?",a="Der Blutgiftposten klammert sich an die westlichen Höhenzüge im Herzen des Teufelswalds. Folgt von der Hauptstraße zwischen Norden und Süden einem schmalen Pfad westwärts am felsigen Hang neben dem Südufer des Blutgiftbachs entlang.",al={"blutgiftposten finden","wie zum blutgiftposten gelangen","weg zum blutgiftposten"}},{q="Wer kontrolliert diesen Außenposten?",a="Taurenwachen halten den Blutgiftposten für die Horde. Seine Gebäude folgen der traditionellen Bauweise der Tauren.",al={"wer führt den blutgiftposten","fraktion des blutgiftpostens"}},{q="Warum heißt der Posten Blutgift?",a="Der Blutgiftposten verdankt seinen Namen dem nahe gelegenen Blutgiftbach. Dämonische Verderbnis hat sein Wasser verunreinigt und giftig gemacht.",al={"warum blutgift","bedeutung des namens blutgift"}},{q="Welchen Gefahren begegnen die Späher hier?",a="Späher stehen der korrumpierten Tierwelt des Teufelswalds gegenüber, darunter tollwütige Säbler, verseuchte Schlämme und entstellte Treants. Auch der Shadow Council und Überreste der Brennenden Legion treiben in diesem Gebiet ihr Unwesen.",al={"feinde von blutgift","was greift den blutgiftposten an"}}},fp="15,159,21.433.0,21.275.0,33.198.0,26.98.0,33.126.0,37.178.0"}
P.entries["subzone:bloodvenom-river"] = {n="Blutgiftbach",s="Im Herzen des Teufelswalds trägt der Blutgiftbach die dämonische Verderbnis des Waldes flussabwärts. Seine Wasser durchqueren die Berge nach Dunkelküste und fließen als verderbter Wildbend weiter.",h="Im Herzen des Teufelswalds trägt der Blutgiftbach die dämonische Verderbnis des Waldes flussabwärts.",kw={"blutgiftbach","verderbnis","dunkelküste","teufelswald","schleim","verseuchtes wasser","der wildbend"},ang={["class:Druid"]="Als Druide seht Ihr, wie der Blutgiftbach die Verderbnis der Teufelsmagie über die Grenzen der Regionen hinausträgt. Sie verwundet Kalimdors heilige Haine und verlangt nach der Wiederherstellung der Natur.",["race:NightElf"]="Als Nachtelf seht Ihr, wie die Gewässer der Wälder Eurer Ahnen Dunkelküste über den Wildbend vergiften. Es ist eine bittere Erinnerung an die noch immer offene Wunde der Legion."},sec={{t="Eine Ader der Verderbnis",b="Der Blutgiftbach durchschneidet das verderbte Herz des Teufelswalds und trägt den Verfall des Waldes mit sich. Abscheuliche Schleime, mutierte Bestien und faulige Abwässer säumen seine Ufer, Hinterlassenschaften der Invasion der Brennenden Legion. Die Verderbnis fließt westwärts durch die Berge nach Dunkelküste. Dort fließt der Bach als Wildbend weiter."}},faq={{q="Warum ist der Bach verderbt?",a="Der Blutgiftbach durchfließt das Zentrum des Teufelswalds, eines uralten Nachtelfenwaldes, der im Dritten Krieg durch die dämonische Magie der Brennenden Legion entstellt wurde. Die Verderbnis drang in Land und Wasser ein und hinterließ giftigen Schlamm und nekrotischen Schleim im Bach.",al={"blutgiftbach verderbnis","warum ist das wasser grün","teufelswald fluss gift"}},{q="Wohin fließt der Blutgiftbach?",a="Der Blutgiftbach fließt durch das verseuchte Tal des Teufelswalds und ergießt sich dann durch die Berge nach Dunkelküste. Jenseits des Bergrückens fließen seine verderbten Wasser als Wildbend weiter flussabwärts.",al={"blutgiftbach verlauf","wohin fließt er","fluss nach dunkelküste"}},{q="Welche Kreaturen leben an den Ufern?",a="Giftige Schleime, entstellte Wildtiere und verderbte Raubtiere leben am Wasser und an den schlammigen Ufern des Blutgiftbachs. Die dämonische Seuche lockt sie dorthin oder erschafft sie.",al={"blutgiftbach tierwelt","mobs am blutgiftbach","monster im fluss"}}},fp="16,178,20.304.0,27.247.0,37.190.0,41.164.0"}
P.entries["subzone:bluefen"] = {n="Blaumoor",s="Blaumoors Sumpfpfade führen Reisende zwischen Sumpfraubtiere und Späher aus Theramore. Das Moor liegt im Norden der Düstermarschen, direkt östlich von Brackenwall.",h="Blaumoors Sumpfpfade führen Reisende zwischen Sumpfraubtiere und Späher aus Theramore.",kw={"blaumoor","brackenwall","krokilisken","düstermarschen","sumpf","theramore infiltrators"},ang={["faction:Alliance"]="Wilde Bestien machen Reisen gefährlich, während Späher aus Theramore durch Blaumoors dichtes Sumpflaub das nahe Ogerlager beobachten.",["faction:Horde"]="Östlich von Brackenwall geraten Champions der Horde in Blaumoor zwischen Sumpfbestien und Theramore Infiltrators, die die Stonemaul-Oger beobachten."},sec={{t="Ein umkämpftes Moor",b="Östlich von Brackenwall, der Heimat der Stonemaul-Oger, wimmelt Blaumoors feuchter Boden von Gefahren. Raptoren, Riesenspinnen, Aas fressende Vögel und Krokilisken durchstreifen den Sumpf. Auch Theramore Infiltrators ziehen durch das Moor, beobachten die Bewegungen der Horde und tragen den menschlichen Einfluss tiefer in den Sumpf hinein."}},faq={{q="Wo liegt Blaumoor?",a="Blaumoor liegt im Norden der Düstermarschen, direkt östlich von Brackenwall.",al={"blaumoor lage","wo liegt blaumoor","blaumoor karte"}},{q="Welche Gefahren lauern in Blaumoor?",a="Raptoren, Riesenspinnen, Krokilisken und Aas fressende Vögel jagen in Blaumoor. Auch Theramore Infiltrators erkunden den Sumpf und bedrohen Reisende der Horde.",al={"blaumoor feinde","was lebt in blaumoor","blaumoor gegner"}},{q="Warum sind Späher aus Theramore in Blaumoor aktiv?",a="Theramore Infiltrators beobachten Brackenwall, die Heimat der Stonemaul-Oger, und patrouillieren auf den umkämpften Pfaden durch die nördlichen Düstermarschen.",al={"theramore infiltrators","warum ist die allianz hier","theramore spione"}}},fp="7,160,15.305.0,25.76.0,37.152.0,43.144.0"}
P.entries["subzone:bluegill-marsh"] = {n="Blaukiemenmarschen",s="Die Blaukiemenmarschen liegen im westlichen Sumpfland, wo der Stamm der Bluegill die Untiefen beansprucht. Gobbler bewacht ihre Hütten und Wasserwege, und Reisende laufen Gefahr, umzingelt zu werden.",h="Die Blaukiemenmarschen liegen im westlichen Sumpfland, wo der Stamm der Bluegill die Untiefen beansprucht.",kw={"bluegill","blaukiemenmarschen","gobbler","menethil","murloc","sumpf","sumpfland"},ang={["faction:Alliance"]="Nahe dem Hafen von Menethil bedrohen aggressive Bluegill-Murlocs Reisende und Versorgungswege, die durch das westliche Sumpfland führen."},sec={{t="Gefahr in Scharen",b="Bluegill-Murlocs drängen sich auf den schlammigen Flächen und im Schilf des westlichen Sumpflands. Ihr Stamm hat primitive Lager im stehenden Wasser errichtet und beansprucht die Marschen. Sie leben und jagen in eng zusammengeschlossenen Rudeln. Reisende und Späher aus dem Hafen von Menethil riskieren Hinterhalte von allen Seiten, wenn sie ins Gebiet der Bluegill waten, wo Häuptling Gobbler durch die Untiefen streift."}},faq={{q="Was sind die Blaukiemenmarschen?",a="Die Blaukiemenmarschen sind ein sumpfiger Landstrich im westlichen Sumpfland und die wichtigste Heimat und Brutstätte der aggressiven Bluegill-Murlocs.",al={"wo liegen die blaukiemenmarschen","was ist das für ein ort","sumpfland murlocs sumpf"}},{q="Wer herrscht über die Marschen?",a="Gobbler, ein mächtiger und grausamer Murloc, herrscht über den Stamm der Bluegill. Er wacht über dessen dicht beieinanderliegende Lager und streckt Landgänger nieder, die das Wasser betreten.",al={"murlocanführer sumpfland","gobbler","wer führt die bluegill-murlocs an"}},{q="Warum ist es gefährlich, hier allein zu reisen?",a="Bluegill-Murlocs versammeln sich in Gruppen von zwei oder drei bei ihren Hütten und am Ufer. Ihre Überzahl und der tiefe, bremsende Schlamm können einen einzelnen Reisenden überwältigen.",al={"warum gibt es so viele murlocs","sind die blaukiemenmarschen schwierig","murloc-aggro"}},{q="Warum wagen sich Reisende in die Blaukiemenmarschen?",a="Späher und Abenteurer aus nahe gelegenen Siedlungen wie dem Hafen von Menethil betreten die Blaukiemenmarschen, um die aggressiven Murlocs zu dezimieren und Diebesgut aus ihren Lagern zurückzuholen.",al={"warum hierher kommen","blaukiemenmarschen quests","gründe für einen besuch"}}},fx={c61162da={q="Warum heißt es Blaukiemenmarschen?",a="Die Marschen haben ihren Namen direkt von den Blaukiemenmurlocs, die mehrere Lager in den trüben Gewässern errichtet haben. Ihr aggressiver Stamm beherrscht die westlichen Sumpfland hier, wodurch das Gebiet unter ihrem Banner berüchtigt ist.",al={"warum blaukiemenmarschen","bedeutung name blaukiemenmarschen","woher haben die blaukiemenmarschen ihren namen"}}},fp="14,164,17.342.0,23.126.0,25.153.0,41.153.0,45.175.0"}
P.entries["subzone:bolgan-s-hole"] = {n="Bolgans Loch",s="Im Süden von Desolace hüten die Gelkis ihre Macht und ihre heiligen Kristalle in Bolgans Loch. Ihr Khan und ihre Schamanen bewachen die Höhle.",h="Im Süden von Desolace hüten die Gelkis ihre Macht und ihre heiligen Kristalle in Bolgans Loch.",kw={"bolgans loch","zentauren","desolace","gelkis","khan shaka","tränen von theradras"},ang={["class:Shaman"]="Als Schamane könnt Ihr erkennen, wie die Gelkis ihre Verehrung der Erde mit Prinzessin Theradras und dem gewaltsamen Erbe des Zentaurenvolkes verbinden."},sec={{t="Machtsitz der Gelkis",b="Über dem Lager der Gelkis hält der Khan in einer Höhle in den Steilklippen Hof. Erfahrene Wachen und einflussreiche Schamanen scharen sich um ihren Herrscher. Die Klippen schützen den Klan vor seinen Rivalen, besonders den Magram-Zentauren im Osten."},{t="Tränen der Erdprinzessin",b="Blaue Kristalle schimmern in den feuchten Steinwänden von Bolgans Loch. Die Gelkis nennen sie die Tränen von Theradras und verehren sie als heilige Segnungen. Ihre Schamanen ernten und bewachen die Kristalle. Sie glauben, die Steine gewähren den Schutz von Prinzessin Theradras, der urzeitlichen Erdelementar-Mutter des Zentaurenvolkes."}},faq={{q="Wo liegt Bolgans Loch?",a="Bolgans Loch liegt in den südlichen Klippen des Dorfs der Gelkis im Süden von Desolace.",al={"bolgans loch lage","wo ist bolgans loch","bolgan höhleneingang"}},{q="Wer lebt in Bolgans Loch?",a="Die Höhle beherbergt die höchsten Anführer des Gelkis-Klans, darunter ihren Khan, sowie ihre Beschützer und Schamanen.",al={"wer ist in bolgans loch","bolgans loch boss","gelkis khan aufenthaltsort"}},{q="Was sind die leuchtenden blauen Kristalle in der Höhle?",a="Die leuchtenden blauen Kristalle werden die Tränen von Theradras genannt. Die Gelkis verehren sie als Zeichen der Gunst ihrer Erdmutter und glauben, dass sie jeden schützen, der sie besitzt.",al={"blaue kristalle in bolgans loch","tränen von theradras","bolgans loch steine"}},{q="Können Spieler Bolgans Loch gefahrlos betreten?",a="Die Gelkis-Zentauren im Inneren sind Fremden feindlich gesinnt. Reisende, die die verhassten Rivalen der Gelkis, den Magram-Klan, niedermetzeln, können genug Ansehen gewinnen, um die Höhle in Frieden zu durchqueren.",al={"ist bolgans loch feindlich","freundlich bei den gelkis","bolgans loch betreten"}}},fp="13,132,24.235.0,27.308.0,31.82.0,31.112.0,51.171.0,39.180.0"}
P.entries["subzone:bones-of-grakkarond"] = {n="Knochen von Grakkarond",s="Im zentralen Silithus liegen Grakkaronds Knochen unter der Sonne. Der bronzene Drache fiel im uralten Krieg der Sandstürme, und die Anubisath halten seine Überreste heilig.",h="Im zentralen Silithus liegen Grakkaronds Knochen unter der Sonne.",kw={"anubisath","knochen von grakkarond","bronzener drache","grakkarond","ossirian the unscarred","silithus","krieg der sandstürme"},ang={["race:NightElf"]="Als kaldorei könnt Ihr auf diese Knochen blicken und Euch an den Krieg der Sandstürme erinnern. Euer Volk und die vier Drachenschwärme kämpften Seite an Seite gegen den Ansturm der Qiraji."},sec={{t="Ein Monument der Sandstürme",b="Grakkaronds Schädel und Brustkorb liegen in den Dünen des zentralen Silithus. Vor tausend Jahren fiel er im Krieg der Sandstürme. In jener gewaltigen Schlacht streckte Ossirian the Unscarred ihn nieder. Ossirian war ein Anubisath-Krieger, gestärkt durch die dunklen Mächte des Stadtkönigreichs. Die Anubisath belassen die Knochen dort, wo Grakkarond fiel, als heiliges Zeichen ihrer Macht gegen die Drachenschwärme."}},faq={{q="Wessen Knochen sind das?",a="Dies sind die Knochen von Grakkarond, einem großen bronzenen Drachen des Bronze Dragonflight. Vor tausend Jahren fiel er im Krieg der Sandstürme im Kampf gegen die insektenartigen Streitkräfte von Ahn'Qiraj.",al={"wer war grakkarond","welcher drache starb hier","drachenskelett silithus"}},{q="Wer hat Grakkarond getötet?",a="Ossirian the Unscarred erschlug Grakkarond. Als Anubisath-Krieger errang er durch seinen Sieg über den bronzenen Lindwurm großen Ruhm und dunkle Segnungen von den Meistern Ahn'Qirajs.",al={"wer tötete den drachen","wie starb grakkarond"}},{q="Warum verehren die Anubisath diesen Ort?",a="Die Anubisath verehren das Skelett als Erinnerung an ihren entscheidenden Sieg über einen mächtigen Drachenschwarm. Es bezeugt ihre Stärke gegenüber jenen, die kamen, um sie einzuschließen.",al={"warum sind die knochen heilig","anubisath knochen"}}},fp="19,172,32.391.0,22.190.0,22.163.0,39.167.0"}
P.entries["subzone:booty-bay"] = {n="Beutebucht",s="In Beutebucht halten Goblins einen neutralen Hafen für Allianz und Horde gleichermaßen offen. Die Blackwater Raiders des Steamwheedle Cartels halten diesen Hafen im südlichen Schlingendorntal, den Reisende auf dem Landweg durch den Rachen eines riesigen Hais betreten.",h="In Beutebucht halten Goblins einen neutralen Hafen für Allianz und Horde gleichermaßen offen.",kw={"blackwater raiders","blutsegelbukaniere","beutebucht","ratschet","revilgaz","salty sailor","seehorn","steamwheedle cartel","schlingendorntal"},ang={["class:Rogue"]="Als Schurke könnt Ihr in Beutebucht Kontakte zur Unterwelt, Hehler, Schließkassetten und geheime Informanten finden. Sie tauschen Geheimnisse gegen Münzen.",["faction:Alliance"]="Weit südlich der geschützten Grenzen Sturmwinds bietet Euch Beutebucht neutrale Einrichtungen, Flugrouten und eine Schiffspassage direkt nach Kalimdor."},sec={{t="Ein Hort der Schurken und Profite",b="Beutebucht entstand als menschliche Siedlung Schwarzmeerbucht. Dschungeltrolle nahmen sie ein, dann eroberten Goblins des Steamwheedle Cartels sie. Heute kommen Händler, Ausgestoßene und Schurken aus vielen Ländern hierher. Baron Revilgaz und Flottenmeister Seehorn wachen von den Balkonen der Salty Sailor Tavern über den Hafen.\n\nDer Hafen mag gesetzlos wirken, doch das Kartell sorgt für Ordnung. Jeder darf trinken, handeln oder Söldner anheuern, solange er den Frieden des Kartells wahrt und die Hafengebühren zahlt."},{t="Gefahren auf dem Wasser",b="Die Docks von Beutebucht verbinden die Östlichen Königreiche über das große Meer mit Ratschet. Handel und Reisende gelangen hier von einem Kontinent zum anderen. Solcher Reichtum lockt Feinde an. Die Blutsegelbukaniere sind eine feindliche Piratenflotte, die Schiffe der Blackwater überfällt und vor der Küste des Schlingendorntals umherstreift. Sie planen, den Goblinhafen zu zerstören und zu plündern."}},faq={{q="Wer herrscht über Beutebucht?",a="Baron Revilgaz herrscht für das Steamwheedle Cartel über Beutebucht, gemeinsam mit Flottenmeister Seehorn, dem Taurenkommandanten der Blackwater Raiders. Sie leiten ihre Unternehmungen von den oberen Decks der Salty Sailor Tavern aus, hoch über dem Hafen.",al={"anführer von beutebucht","wer hat in beutebucht das sagen","boss von beutebucht"}},{q="Warum können Spieler von Allianz und Horde hier zusammenstehen?",a="Das neutrale Steamwheedle Cartel stellt Profit und Handel über den Konflikt zwischen Allianz und Horde. Es heißt jeden willkommen, der Münzen mitbringt. Wenn jemand eine Schlägerei beginnt, gehen Goblinschläger gegen ihn vor.",al={"warum ist beutebucht neutral","beutebucht sichere zone","kann die horde hier die allianz angreifen"}},{q="Wer sind die Blutsegelbukaniere?",a="Die Blutsegelbukaniere sind ein Syndikat von Gesetzlosen, das mit den Blackwater Raiders im Krieg liegt. Ihre Schiffe beherrschen die Gewässer vor dem südlichen Schlingendorntal, und sie planen, Beutebucht zu überwältigen und seinen einträglichen Hafen einzunehmen.",al={"blutsegelpiraten","warum hassen die blutsegelbukaniere beutebucht","geschichte der blutsegelbukaniere"}},{q="Wohin fährt das Schiff in Beutebucht?",a="Das Passagierschiff von den unteren Docks von Beutebucht überquert das große Meer nach Ratschet im Brachland. Es ist die wichtigste neutrale Verbindung zwischen den südlichen Östlichen Königreichen und Kalimdor.",al={"beutebucht schiffsziel","wohin fährt das schiff","schiff nach kalimdor"}},{q="Was ist das für eine riesige Statue an der Einfahrt zur Bucht?",a="Die gewaltige Statue an der Janeirospitze, direkt vor der Hafeneinfahrt, ist einem unbekannten Goblin mit ausgestreckten Armen nachgebildet. Sie weist Handelsschiffen und Piratenbesatzungen als Leuchtfeuer und Willkommensdenkmal den Weg.",al={"beutebucht statue","koloss von beutebucht","statue auf der insel"}}},fp="9,229,30.476.0,20.328.0,20.230.0,55.184.0,33.217.0,38.181.0,56.203.0"}
P.entries["subzone:bough-shadow"] = {n="Bough Shadow",s="Im nordöstlichen Eschental liegt Bough Shadow östlich von Forest Song unter einem gewaltigen Großen Baum. Seine Wurzeln umgeben ein uraltes Portal in den Smaragdgrünen Traum.",h="Im nordöstlichen Eschental liegt Bough Shadow östlich von Forest Song unter einem gewaltigen Großen Baum.",kw={"eschental","bough shadow","drachenbrut","dreamstalker","smaragdgrüner traum","großer baum","grüne drachen","phantim","portal"},ang={["class:Druid"]="Als Druide steht Ihr in Bough Shadow auf heiligem Boden, wo eine natürliche Schwelle Azeroth mit der Domäne von Green Flight und dem Smaragdgrünen Traum verbindet.",["race:NightElf"]="Als Nachtelf findet Ihr Bough Shadow weit hinter Forest Song. Sein Großer Baum und das schlummernde Portal zeugen vom Band zwischen den kaldorei und dem Smaragdgrünen Traum."},sec={{t="Ein Tor zum Traum",b="In Bough Shadow winden sich die Wurzeln des Großen Baums um einen natürlichen Übergang in den Smaragdgrünen Traum. Der Grüne Drachenschwarm bewacht den stillen Hain. Smaragddrachen wie Phantim und Dreamstalker kreisen über dem Blätterdach. Emeraldon-Drachenbrut und Orakel patrouillieren am wirbelnden grünen Portal am Fuß des Baums. Sterbliche, die sich ohne Erlaubnis nähern, werden abgewiesen."}},faq={{q="Was ist das leuchtende grüne Portal hier?",a="Der wirbelnde Strudel unter dem Großen Baum führt direkt in den Smaragdgrünen Traum, Azeroths ungezähmtes Geisterreich. Ähnliche natürliche Übergänge gibt es auch anderswo auf der Welt.",al={"bough shadow portal","was ist das portal in bough shadow","grünes portal eschental"}},{q="Warum bewachen grüne Drachen Bough Shadow?",a="Yseras Grüner Drachenschwarm wacht über den Smaragdgrünen Traum und seine Übergänge in die physische Welt. Smaragddrachen und Drachenbrut patrouillieren in Bough Shadow, um Eindringlinge und verderbende Mächte am Übertritt zu hindern.",al={"warum gibt es drachen im eschental","grüner drachenschwarm bough shadow","warum grüne drachen hier"}},{q="Können Spieler das Portal betreten?",a="Nein. Das Tor ist für Sterbliche versiegelt, und die Elitewachen der Drachenwesen greifen jeden an, der zu nahe kommt.",al={"kann man durch das portal gehen","bough shadow portal betreten","wie das traumportal betreten"}}},fx={ca240e18={q="Was ist Bough Shadow?",a="Bough Shadow ist eine abgeschiedene Lichtung am nordöstlichen Rand des Eschentals, östlich von Forest Song. Sie befindet sich inmitten eines der großen Weltbäume und beherbergt ein mystisches Portal, das direkt in den Smaragdgrünen Traum führt.",al={"was ist das für ein ort","lore von bough shadow","über bough shadow"}},["626e8e50"]={q="Was ist in Bough Shadow passiert?",a="Bough Shadow beheimatet einen der großen Weltbäume, der über einem der Portale zum Smaragdgrünen Traum verwurzelt ist, und der Grüne Drachenschwarm wacht streng über diesen Ort.",al={"geschichte von bough shadow","geschichte bough shadow"}},f0692632={q="Wer lebt in Bough Shadow?",a="Der Hain wird vollständig von Mitgliedern des Grünen Drachenschwarms bewohnt. Drachen wie Phantim und Dreamstalker bewachen die Lichtung, unterstützt von Patrouillen aus grünen Drachenbrütlingen, darunter Emeraldon-Baumwächter, Boughguards und Orakel.",al={"wer ist hier","wer bewohnt bough shadow","bewohner bough shadow"}},["30f2c168"]={q="Ist Bough Shadow gefährlich?",a="Ja, es ist sehr gefährlich für Reisende. Die grünen Drachen und ihre Wächterbrütlinge bewachen das Portal mit wachsamer Strenge und werden nicht zögern, jeden Sterblichen niederzustrecken, der sich zu nah an ihre heilige Stätte wagt.",al={"ist bough shadow sicher","gefahr in bough shadow"}}},fp="12,156,22.362.0,38.169.0,44.207.0,29.103.0"}
P.entries["subzone:boulder-gor"] = {n="Fels'gor",s="Fels'gor beherrscht das westliche Arathi nördlich von Stromgarde, wo Oger der Boulderfist und Trolle der Witherbark ein Lager teilen.",h="Fels'gor beherrscht das westliche Arathi nördlich von Stromgarde, wo Oger der Boulderfist und Trolle der...",kw={"arathihochland","fels'gor","boulderfist","oger","stromgarde","witherbark"},ang={["faction:Alliance"]="Als Soldat der Allianz, der Stromgarde zurückerobern will, steht Ihr bei Fels'gor einer ernsten Bedrohung gegenüber, unmittelbar vor den nördlichen Toren des gefallenen Königreichs.",["race:Troll"]="Als Troll der Dunkelspeer werdet Ihr bei den Waldtrollen der Witherbark von Fels'gor keine Verbundenheit finden. Sie hegen uralten Groll gegen Außenstehende, selbst gegen andere Trollstämme."},sec={{t="Ein Unterschlupf für Oger und Trolle",b="Nördlich der zerfallenden Wehrmauern von Burg Stromgarde erhebt sich Fels'gor über die zentralen Straßen von Arathi. Der Hügel von Boulderfist Outpost liegt in seinem Schatten, eine Bastion der Ogermacht im Hochland. Oger der Boulderfist teilen Lagerfeuer und Befestigungen mit Waldtrollen der Witherbark. Ihre finsteren Zauberwirker ergänzen die rohe Gewalt des Clans um dunkle Magie, und gemeinsam gefährden sie Reisende auf den Straßen."},{t="Das umliegende Gebiet",b="Von den Hängen von Fels'gor könnt Ihr über das offene Hochland im Westen von Arathi blicken. Der Hügel liegt zwischen den vom Syndikat infiltrierten Ruinen von Stromgarde und den wilden Elementarstätten der Ebenen. Schwer bewacht und feindselig bleibt Fels'gor eine Stammeshochburg gegen Wanderer der Allianz und der Horde."}},faq={{q="Was ist Fels'gor?",a="Fels'gor erhebt sich als Hügel mit einem Lager nördlich von Burg Stromgarde im Arathihochland. Oger der Boulderfist und Waldtrolle der Witherbark halten ihn mit starken Kräften besetzt.",al={"wo liegt fels'gor","infos zu fels'gor","was ist das für ein ort"}},{q="Warum leben hier Waldtrolle an der Seite von Ogern?",a="Die Trolle der Witherbark und die Oger der Boulderfist unterhalten ein Zweckbündnis in Arathi. Beide streben nach der Vorherrschaft im Hochland und wollen rivalisierende Fraktionen abwehren, indem sie die Schattenkünste der Trolle mit roher Ogerkraft verbinden.",al={"warum sind hier trolle","bündnis der witherbark und oger","trolle und oger"}},{q="Welche bedeutenden Orte liegen in der Nähe von Fels'gor?",a="Fels'gor liegt direkt nördlich von Burg Stromgarde. Der Ogerhügel von Boulderfist Outpost liegt innerhalb des Hügels.",al={"orte in der nähe","was liegt neben fels'gor","bedeutende orte"}},{q="Ist Fels'gor der Horde oder der Allianz freundlich gesinnt?",a="Keine der beiden Fraktionen ist willkommen. Oger der Boulderfist und Trolle der Witherbark verteidigen Fels'gor erbittert gegen Außenstehende der Allianz und der Horde.",al={"ist der weg dorthin sicher","ist fels'gor feindselig"}}},fp="11,124,25.408.0,21.298.0,20.157.0,50.211.0,42.110.0,49.134.0"}
P.entries["subzone:boulder-lode-mine"] = {n="Felsadermine",s="Im nordöstlichen Brachland gräbt die Venture Company nach den Reichtümern der Felsadermine. Orkische Banner und Wachtürme markieren ein Abbaugebiet, das einst der Horde gehörte.",h="Im nordöstlichen Brachland gräbt die Venture Company nach den Reichtümern der Felsadermine.",kw={"boss copperplug","felsadermine","dizzywig","miner's fortune","samophlanghandbuch","brachland","venture company"},ang={["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie Arbeiter der Venture Company von Befestigungen aus operieren, die mit Standarten der Horde gekennzeichnet sind. Es ist eine bittere Erinnerung an die Reichweite des Kartells in ganz Kalimdor.",["profession:Mining"]="Als Bergarbeiter erkennt Ihr reiche Erzadern in den tiefen Stollen, die in die kargen Hügel getrieben wurden. Die Venture Company beutet die Erde gnadenlos aus."},sec={{t="Der Anspruch der Firma",b="Verwitterte orkische Bauwerke säumen den Mineneingang. Sie zeigen, dass die Horde das Abbaugebiet einst besaß oder erschloss. Heute unterstehen die Aufseher und Vollstrecker der Venture Company Boss Copperplug. Das Goblinsyndikat plündert den Canyon auf der Suche nach Mineralien, Edelsteinen und Maschinen und schert sich kaum um das Land oder seine Arbeiter."},{t="Edelsteine und Baupläne",b="Die Reichtümer der Mine haben in Ratschet Aufmerksamkeit erregt. Werftmeister Dizzywig hat Söldner auf einen gewaltigen Smaragd angesetzt, der Gerüchten zufolge in den Stollen gefunden wurde. Ingenieure, die Goblinmaschinen verstehen wollen, wissen außerdem, dass Boss Copperplug wichtige Betriebshandbücher in seinem Lager aufbewahrt."}},faq={{q="Wer kontrolliert die Felsadermine?",a="Die Venture Company betreibt die Felsadermine unter Boss Copperplug. Bewaffnete Vollstrecker und Aufseher bewachen den Betrieb.",al={"wer betreibt die felsadermine","boss der felsadermine","wer ist in der felsadermine"}},{q="Gehörte diese Mine ursprünglich der Horde?",a="Verwitterte orkische Holzbauten, Wachtürme und Banner der Horde deuten darauf hin, dass die Horde den Ort zuerst erschloss oder beanspruchte. Heute kontrolliert ihn die Venture Company.",al={"orkische banner bei der felsadermine","mine der horde","warum gibt es dort hordenflaggen"}},{q="Warum interessiert sich Werftmeister Dizzywig für diesen Ort?",a="Werftmeister Dizzywig hat gehört, dass ein Bergarbeiter in den Stollen einen ungewöhnlich großen Smaragd ausgegraben hat. Er heuert Halsabschneider an, die ihn gegen einen Anteil am Gewinn stehlen sollen.",al={"dizzywig minenquest","smaragdquest brachland","miners fortune"}},{q="Was verbindet Boss Copperplug mit der samophlange?",a="Boss Copperplug besitzt das Betriebshandbuch für die nahe gelegene samophlange-Maschinerie. Ingenieure in Ratschet schicken Abenteurer los, um das Buch und seine verstreuten Seiten von seiner Mannschaft zurückzuholen.",al={"samophlanghandbuch felsadermine","copperplug handbuch","rilli greasygob mine"}}},fx={["60cbae83"]={q="Was ist die Felsadermine?",a="Die Felsadermine ist ein Bergbaubetrieb in den felsigen Hügeln des nordöstlichen Brachlands. Obwohl sie mit unverkennbarem orkischem Holz und Bannern errichtet wurde, was darauf hindeutet, dass sie einst von der Horde gegründet wurde, wurde die Mine von der Venture Company übernommen. Heute treiben Goblin-Aufseher und angeheuerte Schläger fieberhafte Ausgrabungen tief in das Gestein voran und durchsuchen die Erde nach wertvollen Erzen und kostbaren Edelsteinen.",al={"was ist die felsadermine","felsadermine brachland","über die felsadermine"}},["97c77cb5"]={q="Wer lebt oder arbeitet in der Felsadermine?",a="Die Mine wird derzeit von der Venture Company unter der rücksichtslosen Leitung von Boss Copperplug besetzt. Er beaufsichtigt eine Arbeiterschaft, die von Aufsehern und Schlägern der Venture Company bewacht wird, treibt ständige Ausgrabungen in den Hügeln voran und hält die firmeneigenen Maschinenhandbücher sowie wertvolle Funde unter strengem Verschluss.",al={"wer betreibt die felsadermine","wer ist in der felsadermine","bewohner felsadermine"}},a11a7920={q="Ist die Felsadermine gefährlich?",a="Ja. Die Venture Company heißt keine Besucher oder Eindringlinge willkommen, die in ihrem Unternehmen herumschnüffeln. Die Mine wimmelt von bewaffneten Schlägern und wachsamen Aufsehern, die jeden angreifen werden, der ihre Ansprüche bedroht oder versucht, die wertvollen Erzadern und Schätze zu plündern, die im Inneren verborgen sind.",al={"ist die felsadermine gefährlich","gefahren in der felsadermine","gefahr venture company felsadermine"}}},fp="17,158,15.292.0,19.272.0,31.111.0,39.151.0,53.152.0,56.177.0"}
P.entries["subzone:boulderfist-hall"] = {n="Halle der Felsfäuste",s="Boulderfist-Oger halten die südlichen Hügel des Arathihochlands nördlich des Thandol-Übergangs besetzt. Unter Kor'gresh Coldrage bedrohen sie die nahen Straßen und Täler.",h="Boulderfist-Oger halten die südlichen Hügel des Arathihochlands nördlich des Thandol-Übergangs besetzt.",kw={"arathihochland","boulderfist","halle der felsfäuste","kor'gresh coldrage","ogerhügel","phalanax","thandol-übergang"},ang={["faction:Alliance"]="Oberhalb des Thandol-Übergangs bedrohen Boulderfist-Oger Kuriere und Verstärkungen der Allianz, die von Eisenschmiede nach Norden ins Arathi reisen.",["faction:Horde"]="Um das Arathihochland zu sichern, müsst Ihr die eigenständige Macht der Oger brechen und den südlichen Höhenzug räumen. Das schützt die Truppenbewegungen der Horde von Hammerfall aus."},sec={{t="Eine Bastion roher Stärke",b="Die Halle der Felsfäuste beherbergt den Boulderfist-Klan in den südlichen Klippen des Arathihochlands. Ihre Erdwälle und tiefen Höhlen beherbergen Ogerschläger und -magier, nahe Witherbark und der Brücke am Thandol-Übergang. Kor'gresh Coldrage führt den Klan aus dem Innersten des Hügels, mit Vollstreckern wie Phalanax an seiner Seite. Die Oger kontrollieren die umliegenden Straßen mit Gewalt und machen den Weg zwischen Arathi und dem Sumpfland für Reisende und Versorgungskarawanen gefährlich."}},faq={{q="Was ist die Halle der Felsfäuste?",a="Die Halle der Felsfäuste ist ein befestigter Hügel mit einem Höhlenkomplex im südlichen Arathihochland. Der Boulderfist-Klan hat dort seinen Stützpunkt.",al={"was ist dieser ort","boulderfist-hügel","ogerhöhle arathi"}},{q="Wer herrscht über die Halle der Felsfäuste?",a="Kor'gresh Coldrage führt die Oger aus einer tiefen Höhle im Hügel. Champions wie Phalanax stehen ihm zur Seite.",al={"wer führt die halle der felsfäuste","ogeranführer arathi","kor'gresh"}},{q="Warum ist dieser Ort strategisch wichtig?",a="Nahe dem Thandol-Übergang können die Boulderfist-Oger den Landweg zwischen dem Arathihochland und Khaz Modan bedrohen. Sie überfallen Reisende und unterbinden den Verkehr.",al={"warum oger hier","thandol-übergang gefahr"}},{q="Sind die Boulderfist mit den benachbarten Witherbark-Trollen verbündet?",a="Kein förmliches Bündnis verbindet die Boulderfist-Oger mit den Witherbark-Waldtrollen. Sie leben nahe beieinander bei Witherbark, und in Fels'gor, anderswo im Hochland, teilen sich Witherbark-Trolle das Gelände mit Ogern. Beide Gruppen bleiben Außenstehenden jeder Fraktion feindlich gesinnt.",al={"oger und trolle freunde","witherbark bündnis"}}},fp="16,159,27.458.0,25.131.0,27.112.0,45.167.0,61.278.0"}
P.entries["subzone:boulderfist-outpost"] = {n="Boulderfist Outpost",s="Tief in Fels'gor halten Oger der Felsfäuste einen befestigten Hügel und seine inneren Hallen. Einige Bleichborkentrolle leben unter ihnen im Arathihochland.",h="Tief in Fels'gor halten Oger der Felsfäuste einen befestigten Hügel und seine inneren Hallen.",kw={"arathi","fels'gor","felsfäuste","gefangene","kovork","ogerhügel","bleichborken"},ang={["faction:Alliance"]="Späher der Allianz, die Arathi durchqueren, sollten einen weiten Bogen um den Hügel machen. Vollstrecker der Felsfäuste greifen Eindringlinge an, sobald sie sie sehen.",["faction:Horde"]="Die Oger der Felsfäuste unterscheiden nicht zwischen den Fraktionen. Sie greifen Wanderer der Horde ebenso bereitwillig an wie deren Rivalen von der Allianz."},sec={{t="Eine Festung im Hügel",b="Boulderfist Outpost liegt im Herzen von Fels'gor im westlichen Arathi. Brutale Vollstrecker beherrschen die Siedlung darüber, während sich die Streitmacht des Clans im Inneren des Hügels sammelt. Seine dunklen, aus Erde und Stein gehauenen Hallen dienen als Unterschlupf und Gefängnis. Einige Hexendoktoren der Bleichborkentrolle leben unter den Ogern, ein Zeichen dafür, dass die Stämme dieses Gebiet gelegentlich gemeinsam nutzen."}},faq={{q="Wo liegt Boulderfist Outpost?",a="Boulderfist Outpost liegt in Fels'gor, der größeren Ogersiedlung im westlichen Arathihochland.",al={"boulderfist outpost standort","wo liegt boulderfist outpost","felsfäuste hügeleingang"}},{q="Warum gibt es Trolle in einem Ogeraußenposten?",a="Die Waldtrolle der Bleichborken leben in der Nähe im Arathihochland und teilen sich gelegentlich ein Gebiet mit den Ogern der Felsfäuste. Einige Hexendoktoren der Bleichborken üben an ihrer Seite im Inneren des Hügels ihre Kunst aus.",al={"warum sind bleichborken hier","trolle bei den felsfäusten","bleichborkentrolle arathi"}},{q="Wer wird im Außenposten gefangen gehalten?",a="Derzeit sind keine Gefangenen namentlich bekannt, die im Außenposten festgehalten werden. Vollstrecker der Felsfäuste und einige Hexendoktoren der Bleichborken besetzen seine feuchten Gänge, wo Eindringlinge eher mit einem Kampf als einer Rettung rechnen sollten.",al={"gefangene der felsfäuste","wer ist bei den felsfäusten gefangen","gefangene bei arathis ogern"}},{q="Wer führt die Oger im Außenposten an?",a="Brutale Vollstrecker der Felsfäuste patrouillieren im Inneren. Ein außergewöhnlich wilder Oger namens Kovork lauert im Hügel und stellt eine besondere Bedrohung dar.",al={"kovork","felsfäuste boss arathi","seltene felsfäuste"}}},fp="19,152,29.357.0,37.104.0,44.201.0,33.204.0,39.134.0"}
P.entries["subzone:boulderslide-cavern"] = {n="Steinschlaghöhle",s="Boulderslide-Kobolde graben tief in der Steinschlaghöhle am hintersten Ende der Steinschlagklamm. Sie durchsuchen das Gestein nach leuchtenden Mineralformationen.",h="Boulderslide-Kobolde graben tief in der Steinschlaghöhle am hintersten Ende der Steinschlagklamm.",kw={"boulderslide","höhle","irdene","goggeroc","kobold","resonit","steinkrallengebirge"},ang={["class:Shaman"]="Sowohl Resonit als auch der schlafende Irdene Goggeroc tragen urzeitliche Erdmagie in sich, einen Nachhall der uralten Steinformer der Welt.",["profession:Mining"]="Boulderslide-Kobolde treiben unablässig Stollen durch die Höhle und suchen nach leuchtenden Adern magischen Resonits."},sec={{t="Die Resonitgrabung",b="Boulderslide-Kobolde haben eine Festung in die schroffen Felsen des Steinkrallengebirges gehauen. Sie graben wie besessen nach Resonit, einem seltenen violetten Kristall, der im Gestein eingeschlossen ist. Sein Leuchten trägt Spuren irdischer Magie, und die Kobolde greifen jeden erbittert an, der sich ihrer Ausgrabung nähert."},{t="Der schlummernde Riese",b="Goggeroc schläft in einer Resonitkassette tief in der Steinschlaghöhle. Die Grabungen der Kobolde haben diesen uralten Irdenen erreicht, und ihre Arbeit nahe seiner Ruhestätte droht ihn zu wecken. Seine urzeitliche Steinmagie könnte die gesamte Klamm plötzlich in Gefahr bringen."}},faq={{q="Was bauen die Kobolde hier ab?",a="Die Kobolde bauen Resonit ab, einen seltenen violetten Kristall, der in den Höhlenwänden eingeschlossen ist. Schwache irdische Magie summt darin, und die Kobolde bewachen ihre Vorräte erbittert.",al={"was ist resonit","violette kristalle steinkrallengebirge","warum graben die kobolde"}},{q="Wer ist Goggeroc?",a="Goggeroc ist ein uralter Irdene, der in einer Resonitkassette tief in der Höhle schläft. Die Grabungen der Kobolde nahe seiner Ruhestätte drohen seinen jahrhundertelangen Schlummer zu stören.",al={"goggeroc geschichte","irdene in boulderslide","schlafender riese in der höhle"}},{q="Wo liegt die Steinschlaghöhle?",a="Die Steinschlaghöhle liegt am hintersten Ende der Steinschlagklamm im zerklüfteten Süden des Steinkrallengebirges, unmittelbar nordöstlich des Pfades zum Brachland.",al={"steinschlaghöhle lage","wie die steinschlaghöhle finden","wo ist die höhle"}},{q="Warum interessiert sich die Horde für diese Höhle?",a="Die Horde beobachtet die Höhle, um die aggressiven Kobolde einzudämmen, die sich in der Klamm ausbreiten, und die magischen Eigenschaften ihres abgebauten Resonits zu erforschen.",al={"hordenquests boulderslide","warum nach boulderslide geschickt"}}},fx={["5c565568"]={q="Was ist die Steinschlaghöhle?",a="Die Steinschlaghöhle ist eine unterirdische Mine tief am Ende der Steinschlagklamm im Steinkrallengebirge. Sie dient den dortigen Kobolden als aktiver Nistplatz und weitläufige Ausgrabungsstätte, wo sie unermüdlich seltene, magische Resonitkristalle aus den steinigen Tiefen abbauen.",al={"was ist die steinschlaghöhle","lore steinschlaghöhle","über die steinschlaghöhle"}},["66cd11c1"]={q="Wer lebt in der Steinschlaghöhle?",a="Die Höhle wird vollständig von den Steinschlagkobolden bewohnt. Diese aggressiven unterirdischen Gräber haben hier ihre Bauten errichtet und arbeiten fieberhaft daran, Resonit abzubauen, während sie ihre Tunnel gewaltsam gegen jeden Eindringling verteidigen, der sich zu nähern wagt.",al={"wer lebt in der steinschlaghöhle","bewohner steinschlaghöhle","wer ist in der steinschlaghöhle"}},babd5bca={q="Ist die Steinschlaghöhle gefährlich?",a="Ja, es ist extrem gefährlich. Die Kobolde im Inneren verteidigen ihre Bergbauaktivitäten mit ihrem Leben und werden jeden überwältigen, der ihre Bauten betritt. Darüber hinaus sind ihre tiefen Ausgrabungen auf uralte Relikte gestoßen, darunter ein schlafender Irderner, der tief in der Mine ruht.",al={"ist die steinschlaghöhle gefährlich","gefahr steinschlaghöhle","bedrohungen steinschlaghöhle"}}},fp="19,146,16.272.0,20.252.1,33.160.0,16.173.1,37.155.0,43.148.0"}
P.entries["subzone:boulderslide-ravine"] = {n="Steinschlagklamm",s="Am Weberpass durchschneidet die Steinschlagklamm die zentralen Gipfel des Steinkrallengebirges. Kämpfe zwischen Horde und Allianz erreichen diesen ruhigen Pass nur selten. Felsige Hänge führen zur Steinschlaghöhle, während wilde Bergtiere durch die Höhen streifen.",h="Am Weberpass durchschneidet die Steinschlagklamm die zentralen Gipfel des Steinkrallengebirges.",kw={"steinschlaghöhle","steinschlagklamm","cliff stormer","widder","steinkrallengebirge","weberpass"},ang={["profession:Mining"]="Haltet als Bergmann entlang der steilen Schluchtwände nach Adern Ausschau, die durch Verschiebungen im Gebirgsgestein freigelegt werden.",["race:Tauren"]="Als Tauren erkennt Ihr vielleicht die verblassten Stammesmotive in der kleinen Seitenhöhle wieder. Sie deuten auf Pfade der Ahnen durch die Höhen des Steinkrallengebirges hin."},sec={{t="Ein ruhiger Gebirgspass",b="Der Weberpass führt in die Steinschlagklamm, hoch im Steinkrallengebirge. Holzfäller, Nachtelfen und die Horde kämpfen andernorts in der Region um Bauholz und heilige Haine, doch Soldaten betreten diesen schmalen Pass nur selten. Bergwidder und Klippenbestien durchstreifen seine Felsvorsprünge und steilen Wände. Cliff Stormer sind unter ihnen. Auf dem Weg zum tiefer gelegenen Höhlennetzwerk halten Goldsucher an den Hängen nach ergiebigen Mineraladern Ausschau."},{t="Spuren im Stein",b="Gegenüber dem Eingang zur Steinschlaghöhle liegt eine kleine Höhle mit Blick auf die Schlucht. Einfache Fackeln beleuchten verwitterte Vorratsfässer und primitive Stammesmalereien. Die Motive ähneln uralter Taurenkunst. Sie deuten darauf hin, dass einheimische Stämme einst durch diese Felsen zogen oder hier Schutz suchten, lange bevor neuzeitliche Konflikte das Gebirge erreichten."}},faq={{q="Wo liegt die Steinschlagklamm?",a="Die Steinschlagklamm liegt im Steinkrallengebirge. Folgt dem Weberpass in die höher gelegenen Felsen, um sie zu erreichen.",al={"steinschlagklamm lage","wie zur steinschlagklamm gelangen","wo liegt die steinschlagklamm"}},{q="Welche Kreaturen bewohnen die Steinschlagklamm?",a="Bergwidder und Klippenbestien bewohnen die Steinschlagklamm. Cliff Stormer gehören zu den gefährlichen Klippenbestien, die dort vorkommen.",al={"steinschlagklamm gegner","was gibt es in der steinschlagklamm"}},{q="Was ist die verlassene Höhle gegenüber der Steinschlaghöhle?",a="Gegenüber dem Eingang zur Steinschlaghöhle liegt eine kleine Höhle mit alten Fässern, die von Fackelschein erhellt wird. Stammesmalereien bedecken ihre Steinwände und ähneln Taurenkunst. Sie deuten darauf hin, dass einst einheimische Wanderer oder Jäger den Unterschlupf nutzten.",al={"verlassene höhle steinschlag","höhle in der steinschlagklamm","taurenhöhle steinkrallengebirge"}},{q="Warum ist die Steinschlagklamm von Bedeutung?",a="Die Steinschlagklamm führt zur Steinschlaghöhle, einem unterirdischen Unterschlupf tief im Gebirge. Ihre Hänge bieten durchreisenden Abenteurern zudem wertvolle Mineralvorkommen.",al={"wozu dient die steinschlagklamm","steinschlagklamm zweck"}}},fx={["92909b11"]={q="Was ist die Steinschlagklamm?",a="Die Steinschlagklamm ist eine raue Schlucht im Steinkrallengebirge, die über den Weberpass erreicht wird. Sie dient hauptsächlich als Zugangsweg zur tiefer gelegenen Steinschlaghöhle. Während der Krieg zwischen Horde und Allianz einen Großteil der umliegenden Gipfel einnimmt, bleibt diese abgelegene Schlucht weitgehend von den Zusammenstößen verschont.",al={"was ist die steinschlagklamm","überblick steinschlagklamm","lore steinschlagklamm"}},["846b0de4"]={q="Warum ist die Höhle in der Steinschlagklamm verlassen?",a="Gegenüber dem Höhleneingang befindet sich ein abgeschiedener, verlassener Unterschlupf, der von einfachen Fackeln beleuchtet wird und mit alten Fässern bestückt ist. Seine Wände tragen verblasste Stammeskunst, die an die Handwerkskunst der Tauren erinnert, was darauf hindeutet, dass lokale Stämme oder wandernde Jäger dort einst ihr Lager aufschlugen, bevor sie die Schlucht den wilden Tieren überließen.",al={"warum ist die höhle verlassen","verlassene höhle steinschlagklamm","wer hat die höhle verlassen"}},["2463d3df"]={q="Ist die Steinschlagklamm gefährlich?",a="Obwohl sie von organisierten militärischen Gefechten verschont geblieben ist, ist die Schlucht keineswegs sicher. Einheimische Widder grasen entlang der steilen Pfade und flüchtige Klippenstürmer durchstreifen die Felsen, was den unvorsichtigen Durchgang für Reisende, die die Erzadern suchen oder zur Höhle wollen, riskant macht.",al={"ist die steinschlagklamm gefährlich","gefahren in der steinschlagklamm","bedrohungen steinschlagklamm"}}},fp="19,252,21.422.0,19.331.0,37.110.0,43.122.0,59.228.0,39.178.0"}
P.entries["subzone:brackenwall-village"] = {n="Brackenwall",s="Im nordwestlichen Sumpf bietet Brackenwall den Stonemaul-Ogern Schutz. Schwarze Drachenbrut vertrieb sie aus ihrer Heimat im Süden, und Spione, Deserteure und der Schwarze Drachenschwarm bedrohen nun die Zuflucht.",h="Im nordwestlichen Sumpf bietet Brackenwall den Stonemaul-Ogern Schutz.",kw={"brackenwall","draz'zilb","düstermarschen","infiltratoren","mok'morokk","oger","paval reethe","stonemaul"},ang={["faction:Alliance"]="Brackenwall liegt tief in feindlichem Gebiet. Ermittlungen zum vermissten Diplomaten und zu abtrünnigen Deserteuren aus Theramore werden wagemutige Agenten an den Rand des Ogerlagers führen.",["faction:Horde"]="Brackenwall ist Eure einzige Zuflucht und Flugverbindung im Sumpf. Seine Verteidigung hilft der Horde, einen wichtigen Horchposten und eine Verteidigungsflanke gegen Theramore zu halten."},sec={{t="Zuflucht der Stonemaul",b="Oberanführer Mok'Morokk führte die überlebenden Stonemaul nach Norden, nachdem schwarze Drachenbrut sie aus ihrer uralten Heimat in Stonemaul Village vertrieben hatte. Als Nachfolger von Rexxar versammelte er den Clan im Sumpf, um Brackenwall zu errichten. Erdhügel, Hütten und ein alter Wachturm bieten den angeschlagenen Ogern eine Zuflucht, die sie verteidigen können.\n\nBrackenwall ist mit der Horde verbündet, doch Mok'Morokk sitzt untätig herum, hortet Vorräte und weigert sich, der Bedrohung durch die Drachen entgegenzutreten. Der Ogermagier Draz'Zilb und Abgesandte der Horde geben dem Clan spirituelle und taktische Führung."},{t="Augen im Sumpf",b="Infiltratoren aus Theramore beobachten Brackenwall aus dem Dickicht und melden der Inselfestung die Bewegungen im Dorf. Paval Reethe, ein aus der verlassenen Wacht verstoßener Deserteur aus Theramore, wird verdächtigt, lebenswichtige Vorräte aus dem Außenposten gestohlen zu haben.\n\nWachsame Augen beobachten das Dorf aus dem Osten, während schwarze Drachen die südlichen Gebiete durchstreifen. Brackenwall bleibt ein isolierter Aufmarschstützpunkt der Horde gegen die Allianz und Onyxias Brut."}},faq={{q="Warum gibt es hier Oger, die mit der Horde verbündet sind?",a="Die Stonemaul-Oger schlossen sich der heutigen Horde durch Rexxar an, ihren Champion während der Gründung Durotars. Nachdem er ihren früheren Anführer besiegt hatte, wurde Rexxar ihr Häuptling und band den Clan an die Koalition von Kriegshäuptling Thrall. Später übergab er die Führung an Mok'Morokk.",al={"warum oger der horde","geschichte des stonemaul-clans","wer sind diese oger"}},{q="Warum siedelten sich die Stonemaul hier an, statt in ihrer alten Heimat zu bleiben?",a="Schwarze Drachenbrut überrannte und zerstörte die angestammte Siedlung der Stonemaul in den südlichen Düstermarschen. Oberanführer Mok'Morokk führte die vertriebenen Überlebenden nach Norden durch den Sumpf, um Brackenwall als befestigte Zuflucht zu errichten.",al={"was geschah mit stonemaul village","warum brackenwall","ogerflüchtlinge"}},{q="Wer hat in Brackenwall das Sagen?",a="Oberanführer Mok'Morokk führt Brackenwall, doch viele sind über seine Herrschaft erbittert. Er kauert im Dorf, statt die Oger zu sammeln, um ihre Heimat zurückzuerobern oder sich den Drachen zu stellen. Der Ogermagier Draz'Zilb und Gesandte der Horde bewältigen die täglichen Krisen.",al={"anführer von brackenwall","wer führt brackenwall","mok'morokk"}},{q="Warum gibt es vor dem Dorf Spione aus Theramore?",a="Theramores Militär beobachtet die Truppenbewegungen der Horde in den Düstermarschen trotz des brüchigen Waffenstillstands zwischen Theramore und Orgrimmar. Infiltratoren umkreisen Brackenwall und berichten über die Stärke der Oger und die Operationen der Horde.",al={"allianzspione düstermarschen","infiltratoren aus theramore","warum beobachtet theramore"}}},fp="19,200,23.518.0,15.405.1,47.266.0,71.218.0,40.235.0,50.205.0"}
P.entries["subzone:brackwell-pumpkin-patch"] = {n="Brackbrunns Kürbisbeet",s="Defiasräuber halten Brackbrunns Kürbisbeet im südöstlichen Wald von Elwynn besetzt. Der Hof gehörte der Familie Brackwell, doch nun treffen sich Verschwörer in seinem Häuschen und auf den Feldern, wo gestohlenes Minengold eintrifft.",h="Defiasräuber halten Brackbrunns Kürbisbeet im südöstlichen Wald von Elwynn besetzt.",kw={"brackwell","defias","elwynn","erlan drudgemoor","morgan der sammler","princess","kürbisbeet","surena caledon"},ang={["class:Warlock"]="Surena Caledon, eine flüchtige Lehrling, versteckt sich in der Hütte des Hofes. Ihr gestohlener Blutsteinhalsreif wird benötigt, um einen Leerwandler zu binden.",["faction:Alliance"]="Das überrannte Beet ist einer der östlichsten Stützpunkte der Bruderschaft der Defias in Elwynn. Es bedroht nahe gelegene Höfe und Handelswege."},sec={{t="Ein Banditenversteck",b="Südöstlich vom Hof der Steinfelds liegen Brackwells Felder brach. Die Familie verschwand, als sich das Verbrechen in der Gegend ausbreitete, vertrieben oder Schlimmeres. Die Bruderschaft der Defias besetzt nun das robuste Häuschen und die überwucherten Felder. Außerhalb der Reichweite der Patrouillen aus Goldhain sammeln sich hier Räuber neu. Morgan der Sammler und andere führende Verschwörer nutzen den abgelegenen Hof, um unrechtmäßig erbeutetes Gold aus den Minen des Waldes entgegenzunehmen."},{t="Schweine und dunkle Magie",b="Eine riesige Sau namens Princess streift noch immer durch die Kürbisranken. Die Brackwells ließen sie zurück, und sie versetzt die benachbarten Felder in Schrecken. Der Dachboden des Bauernhauses und die Nebengebäude bieten weiteren gefährlichen Machenschaften Unterschlupf. Erlan Drudgemoor, ein Bandit, verführte Surena Caledon, eine abtrünnige Hexenmeisterlehrling, die mit einem gestohlenen Blutstein-Artefakt vor ihrem Meister in Sturmwind floh. Ihre Anwesenheit hat Anwender dunkler Magie in das Versteck gelockt."}},faq={{q="Was geschah mit der Familie Brackwell?",a="Niemand kennt das genaue Schicksal der Familie Brackwell. Als sich die Bruderschaft der Defias im südöstlichen Wald von Elwynn ausbreitete, floh die Familie oder wurde getötet. Ihre Kürbisfelder und ihr Bauernhaus fielen den Banditen in die Hände.",al={"wo sind die brackwells","wer lebte auf brackwells hof","schicksal der familie brackwell"}},{q="Warum nutzt die Bruderschaft der Defias diesen Hof?",a="Der Hof bietet den Defias einen abgelegenen Stützpunkt nahe den Grenzen des Waldes. Dort lagern sie Beutegut und organisieren den Schmuggel, darunter gestohlenes Minengold, das Kuriere wie Morgan der Sammler bringen. So bleiben ihre Geschäfte vor der Sturmwind Guard verborgen.",al={"warum sind die defias hier","was machen banditen am kürbisbeet","defias bei brackwell"}},{q="Wer ist Princess?",a="Princess ist eine gewaltige, preisgekrönte Sau, die von den Brackwells aufgezogen wurde. Als der Hof fiel, blieb sie zurück und wurde noch größer, indem sie immer wieder in den nahen Hof der Steinfelds eindrang und dessen kostbare Feldfrüchte fraß.",al={"riesenschwein","schwein princess","warum ist hier ein riesiger eber"}},{q="Warum kommen Hexenmeister zum Kürbisbeet?",a="Surena Caledon, Lehrling des Hexenmeisterlehrers Gakin der Dunkelbinder aus Sturmwind, stahl einen mächtigen Blutsteinhalsreif und floh mit ihrem Geliebten, dem Defiasbanditen Erlan Drudgemoor, zum Hof. Gakin schickt unerfahrene Hexenmeister los, um sie zu töten und das Relikt zurückzuholen.",al={"hexenmeisterquest brackwell","surena caledon","gakins leerwandlerquest"}}},fx={["43009602"]={q="Warum heißt es Brackwells Kürbisbeet?",a="Es ist nach der Familie Brackwell benannt, den menschlichen Farmern, die das Land besiedelten und ihre markanten Kürbisfelder bestellten, bevor sie durch Banditenüberfälle aus ihrem Zuhause vertrieben wurden.",al={"ursprung des namens brackwell","warum brackwell","wer waren die brackwells"}},f38a2be0={q="Was ist Brackwells Kürbisbeet?",a="Brackwells Kürbisbeet ist ein sturmwindscher Bauernhof im südöstlichen Wald von Elwynn. Einst ein friedliches landwirtschaftliches Gehöft, das reife Kürbisse kultivierte und Vieh züchtete, ist es vor Kurzem im Chaos versunken und in die Hände von Gesetzlosen gefallen.",al={"brackwells kürbisbeet","was ist das für ein bauernhof","brackwell hof"}},["0e932b65"]={q="Was ist bei Brackwells Kürbisbeet passiert?",a="Früher ein produktiver Familienbauernhof, wurde das Beet von der The Defias Brotherhood überrannt, als Banditen das Gebiet übernahmen. Die Brackwells verschwanden und der Hof wurde schnell zu einem Außenposten für Aktivitäten der Defias, einschließlich Goldübergaben und illegalen Verstecken.",al={"geschichte brackwell hof","was ist hier passiert","brackwell lore"}},ae1356ee={q="Wer lebt oder arbeitet in Brackwells Kürbisbeet?",a="Die ursprünglichen Besitzer des Hofes sind fort, und Banditen der Defias besetzen derzeit das Gelände. Unter ihnen verstecken sich Figuren wie Erlan Drudgemoor und seine flüchtige Geliebte Surena Caledon, während Morgan der Sammler den Hof nutzt, um Goldlieferungen aus lokalen Minen entgegenzunehmen.",al={"wer betreibt brackwells kürbisbeet","wer lebt in brackwells kürbisbeet","bewohner brackwell patch"}},["90becbea"]={q="Ist Brackwells Kürbisbeet gefährlich?",a="Ja, Ihr solltet vorsichtig sein. Bewaffnete Defias-Taschendiebe patrouillieren durch die Kürbisfelder, zusammen mit dem berüchtigten und gefräßigen preisgekrönten Schwein Prinzessin, das ihr Futtergebiet mit ihren schweineartigen Begleitern aggressiv verteidigt.",al={"ist brackwell sicher","gefahren in brackwell","ist dieser bauernhof gefährlich"}}},fp="23,203,14.413.0,19.414.1,38.209.0,46.259.0,16.192.0,42.244.0"}
P.entries["subzone:brambleblade-ravine"] = {n="Dornrankenklamm",s="Die Stacheleber der Borstennacken überfallen Camp Narache von der Dornrankenklamm am nordöstlichen Rand der Hochwolkenebene aus. Junge Taurenkrieger betreten die Klamm, um ihre Heimat zu verteidigen und ihre Stärke zu beweisen.",h="Die Stacheleber der Borstennacken überfallen Camp Narache von der Dornrankenklamm am nordöstlichen Rand der...",kw={"dornranken","borstennacken","camp narache","mulgore","stacheleber","klamm","die hochwolkenebene","thornmantle"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, ihren frühen Einfluss in ganz Mulgore zu festigen. Ihr vertreibt die angriffslustigen Borstennacken aus der Dornrankenklamm.",["race:Tauren"]="Als junger Tauren, der in Camp Narache erwachsen wird, steht Ihr vor einer Eurer ersten Prüfungen körperlicher und geistiger Ausdauer im Kampf. Ihr stoßt in die Dornrankenklamm vor, um Euren Stamm zu verteidigen."},sec={{t="Ein Dorn in der Flanke",b="Die Dornrankenklamm schneidet sich in den nordöstlichen Rand der Hochwolkenebene, wo dorniges Gestrüpp und Stacheleberlager dem Stamm der Borstennacken Schutz bieten. Von dort aus überfallen die Borstennacken Camp Narache und bedrohen junge Tauren, die gerade erwachsen werden. Chief Sharptusk Thornmantle führt die Schamanen und Krieger, die tief in der Klamm zusammen mit ihren abgerichteten Kampfebern hausen. Für die Shu'halo ist ein Vorstoß in den Canyon sowohl ein Initiationsritus als auch eine bittere Notwendigkeit, wenn die Ebenen sicher sein sollen."}},faq={{q="Was ist die Dornrankenklamm?",a="Die Dornrankenklamm schneidet sich in den nordöstlichen Rand der Hochwolkenebene in Mulgore. Die Stacheleber der Borstennacken halten sie als Festung.",al={"dornrankenklamm","was ist die dornrankenklamm","dornranken mulgore"}},{q="Warum greifen die Stacheleber der Borstennacken von hier aus an?",a="Die Borstennacken beanspruchen das Land um die Dornrankenklamm und sehen die Tauren als Eindringlinge. Von der Klamm aus überfallen sie das nahe gelegene Camp Narache.",al={"warum greifen stacheleber an","beweggründe der borstennacken","stacheleber camp narache"}},{q="Wer führt die Stacheleber in der Dornrankenklamm an?",a="Chief Sharptusk Thornmantle führt die Stacheleber in der Dornrankenklamm an. Er lebt in einer großen Hütte im hinteren Teil der Klamm.",al={"anführer der dornrankenklamm","stacheleberboss mulgore","chief sharptusk thornmantle"}},{q="Warum ziehen junge Tauren in die Klamm?",a="Die Ältesten und Häuptlinge der Tauren in Camp Narache schicken junge Krieger in die Klamm, um die Borstennacken zurückzudrängen, ihre Zahl zu verringern und ihre Anführer zu besiegen. Damit wollen sie die Hochebene sichern.",al={"taurenquests dornrankenklamm","warum zur dornrankenklamm","camp narache quests"}}},fx={["9e3e8e60"]={q="Wer lebt in der Dornrankenklamm?",a="Die Schlucht dient den Borstennacken-Stachelebern als befestigte Siedlung. Neben aggressiven Schlachtbern, Stammeskriegern und Schamanen haben die Borstennacken überall auf den unbefestigten Pfaden ihre Hütten errichtet, wo sie dem Häuptling Scharfhuf Dornmantel und seinen Verwandten unterstehen.",al={"wer lebt in der dornrankenklamm","bewohner der dornrankenklamm","wer ist in der dornrankenklamm"}},cff45375={q="Ist die Dornrankenklamm gefährlich?",a="Sie ist für unvorsichtige Reisende sehr gefährlich. Die Stacheleber bewachen ihre Höhlen aggressiv und schwärmen mit ausgebildeten Schlachtbern und mystischen Schamanen aus, um Eindringlinge zu überfallen. Jeder, der unvorsichtig in die Schlucht hinabsteigt, kann schnell an den hohen Schluchtwänden in die Enge getrieben werden.",al={"ist die dornrankenklamm gefährlich","wie gefährlich ist die dornrankenklamm","gefahr in der dornrankenklamm"}}},fp="19,193,26.466.0,28.124.0,53.139.0,46.122.0,41.194.0"}
P.entries["subzone:bramblescar"] = {n="Dornennarbe",s="Im Südlichen Brachland kämpfen Razormane-Krieger aus der Dornennarbe jenseits der Goldstraße gegen die Bristleback. Dichtes Dornengestrüpp schützt ihre Siedlung.",h="Im Südlichen Brachland kämpfen Razormane-Krieger aus der Dornennarbe jenseits der Goldstraße gegen die...",kw={"agama'gor","brachland","dornennarbe","bristleback","goldstraße","stacheleber","razormane"},ang={["faction:Horde"]="Als Mitglied der Horde braucht Ihr eine Goldstraße ohne Überfälle aus der Dornennarbe, um sicher zwischen dem Wegekreuz, Camp Taurajo und der südlichen Grenze zu reisen."},sec={{t="Eine dornige Schanze",b="Im Südlichen Brachland bildet scharfes Dornengestrüpp eine Schanze für die Razormane-Stacheleber. Die dichten Dornen halten zufällig vorbeikommende Wanderer fern. Der Stamm bewacht sein Gebiet erbittert und betrachtet Außenstehende als Eindringlinge auf dem Land, das seine uralten Ebergötter gesegnet haben."},{t="Blutfehde der Stämme",b="Auf der anderen Seite der Goldstraße liegt gegenüber der Dornennarbe Agama'gor, das Lager der Bristleback. Die beiden Stämme führen einen unerbittlichen Krieg um die Vorherrschaft über das Südliche Brachland. Razormane-Krieger bekämpfen Reisende der Horde entlang der Straße und schlagen Überfalltrupps der Bristleback zurück. So bleiben die Stämme in einem ständigen, gewaltsamen Konflikt."}},faq={{q="Wer lebt in der Dornennarbe?",a="Der Stamm der Razormane-Stacheleber lebt in der Dornennarbe. Sie verteidigen ihr von Dornen überwuchertes Lager gegen rivalisierende Stacheleber und vorbeiziehende Reisende.",al={"wer ist hier","dornennarbe gegner","dornennarbe stacheleber"}},{q="Warum kämpfen die Stacheleber hier gegeneinander?",a="Die Razormane der Dornennarbe und die Bristleback in Agama'gor sind erbitterte Feinde. Sie kämpfen um die Kontrolle über das Südliche Brachland.",al={"warum führen sie krieg","razormane gegen bristleback","stacheleberkrieg"}},{q="Wo liegt die Dornennarbe?",a="Die Dornennarbe liegt in den südlichen Ebenen des Brachlands, unmittelbar östlich der Hauptstraße, der Goldstraße, und gegenüber von Agama'gor.",al={"dornennarbe lage","wo ist die dornennarbe","wie findet man die dornennarbe"}},{q="Sind die Stacheleber hier der Horde feindlich gesinnt?",a="Ja. Die Razormane betrachten die Horde als Eindringlinge auf ihrem heiligen Stammesland. Sie greifen Reisende an, die ihnen zu nahe kommen.",al={"ist die dornennarbe freundlich","horde ruf dornennarbe"}}},fx={["86a75fd0"]={q="Was ist die Dornennarbe?",a="Die Dornennarbe ist ein Lager und Bau der Klingenmähnen-Stacheleber im südlichen Brachland. Sie liegt direkt an der Hauptstraße, genau gegenüber dem Borstennacken-Stacheleber-Außenposten Agama'gor. Die Siedlung dient den Klingenmähnen als befestigte Basis in ihrem unerbittlichen Territorialkrieg gegen ihre Rivalen, die Borstennacken.",al={"was ist die dornennarbe","infos zur dornennarbe","über die dornennarbe"}},f9fc9349={q="Ist die Dornennarbe gefährlich?",a="Ja, die Dornennarbe ist für jeden Reisenden außergewöhnlich gefährlich. Die Klingenmähnen-Stacheleber, die hier hausen, sind überaus aggressiv und werden jeden, der sich ihrem Bau nähert, bereitwillig hinterhaltartig angreifen, völlig ungeachtet dessen, wer er ist, während sie gleichzeitig einen gewaltsamen Krieg mit dem nahegelegenen Borstennacken-Stamm führen.",al={"ist die dornennarbe gefährlich","gefahr in der dornennarbe","wie sicher ist die dornennarbe"}}},fp="11,145,17.245.0,17.314.0,25.138.0,46.129.0,29.114.0,43.116.0"}
P.entries["subzone:brewnall-village"] = {n="Bräuhall",s="Im Frosthauchtal arbeitet die Familie Gerstenbräu an neuen Bieren und schützt sich vor wilden Bestien. Ihr Lager liegt nahe dem Eingang nach Gnomeregan.",h="Im Frosthauchtal arbeitet die Familie Gerstenbräu an neuen Bieren und schützt sich vor wilden Bestien.",kw={"barleybrew","bier","bräuhall","frosthauchtal","dun morogh","gnomeregan","stout"},ang={["race:Dwarf"]="Als Zwerg könnt Ihr das Streben der Barleybrews nach dem besten Rezept als ehrbares Handwerk betrachten, das in der Tradition Eisenschmiedes wurzelt.",["race:Gnome"]="Nahe Gnomeregan findet Ihr tief in den gnomischen Tälern im Westen von Dun Morogh ein Zwergenlager."},sec={{t="Ein bitteres Bier im Tal",b="Die Siedlung des Gerstenbräu-Klans liegt im Frosthauchtal in den gnomischen Ausläufern des westlichen Dun Morogh. Sie haben es sich zur Aufgabe gemacht, die uralten Rezepte zu perfektionieren und das ultimative Bier zu brauen. Obwohl als Dorf betitelt, besteht der Außenposten größtenteils aus Zelten und Brauanlagen unter freiem Himmel anstelle von beständiger Steinarchitektur. \nNeben dem Testen experimenteller Ale-Chargen bedrohen wilde Wölfe und Bären das Tal, weswegen umherziehende Bergsteiger die seltenen Zutaten beschaffen und das Tal sichern."}},faq={{q="Was ist Bräuhall?",a="Bräuhall ist ein kleines Zwergenlager im Frosthauchtal im Westen von Dun Morogh, direkt östlich von Gnomeregan. Es dient als Außenposten, an dem der Gerstenbräu-Klan mit neuen Bierrezepten experimentiert und Bedrohungen durch die örtliche Tierwelt bewältigt.",al={"wo liegt bräuhall","was ist bräuhall","bräuhall infos"}},{q="Warum heißt es Dorf, wenn es keine Gebäude gibt?",a="Bräuhall ist ein Lager unter freiem Himmel mit Zelten und Vorratsfässern statt Steinhäusern. Die Barleybrews brauen im kalten Tal, ohne feste Behausungen zu errichten.",al={"warum ist es ein lager","wo sind die häuser","bräuhall gebäude"}},{q="Warum liegt eine Zwergensiedlung auf gnomischem Gebiet?",a="Die Barleybrews ließen sich im Frosthauchtal nieder, wo Gnome nahe Gnomeregan leben. Eisenschmiede und die Gnome sind enge Verbündete, und die Zwerge gehen hier ungestört ihrem Brauhandwerk nach.",al={"zwerge nahe gnomeregan","warum sind hier zwerge","gnomisches gebiet zwergenlager"}},{q="Mit welchen Problemen kämpfen die Bewohner?",a="Aggressive Wildtiere bedrohen das Lager, darunter Felseber, Bären und Frostwölfe. Die Barleybrews suchen außerdem seltene Zutaten für neue und bessere Biere.",al={"bräuhall quests","was brauchen die barleybrews","probleme im dorf"}}},fx={c4fa2ce1={q="Wer lebt in Bräuhall?",a="Bräuhall dient der Familie Gerstenbräu als Zuhause und Testgelände. Diese zwergischen Brauer haben ihr Lager hier im Frosthauchtal aufgeschlagen, um sich ganz ihrem Handwerk zu widmen und unaufhörlich zu experimentieren, um die Kunst des Zwergenbierbrauens zu verfeinern und zu perfektionieren.",al={"wer leitet bräuhall","bewohner von bräuhall","wer lebt in bräuhall"}}},fp="16,145,27.379.0,25.196.0,53.162.0,57.186.0,36.155.0"}
P.entries["subzone:brightwater-lake"] = {n="Blendwassersee",s="In Tirisfals Niederungen liegt der Blendwassersee kalt und dunkel nordöstlich von Brill. Einst ein Rückzugsort für Lordaeron, umgibt er nun eine Insel, auf der ein einsamer Nekromant verbotene Forschungen betreibt.",h="In Tirisfals Niederungen liegt der Blendwassersee kalt und dunkel nordöstlich von Brill.",kw={"blendwassersee","brill","gunther arkanus","gunthers zufluchtsort","nekromant","scharlachroter wachposten","tirisfal","untoter"},ang={["class:Mage"]="Als Magier könnt Ihr auf der Insel des Sees im abtrünnigen Zauberer Gunther Arkanus ungewöhnliche, ohne Anleitung erworbene Meisterschaft finden.",["race:Undead"]="Als Verlassener müsst Ihr den Blendwassersee sichern, um die östlichen Zugänge nach Brill zu verteidigen. Ihr müsst außerdem herausfinden, ob der unabhängige Nekromant Gunther Arkanus ein Gewinn oder ein Feind sein wird."},sec={{t="Die Wasser des Nordens",b="Der Blendwassersee erstreckt sich über das nördliche Tirisfal zwischen Brill und dem Scharlachroten Wachposten. Unter dem Königreich Lordaeron boten seine Ufer eine stille Zuflucht auf dem Land. Dieser Frieden ist vergangen. Die Pestländer liegen im Osten, und grauer Himmel hängt über dem trüben, kalten Wasser des Sees. Verdorrte Bäume säumen das Ufer, an dem Murlocs und feindselige Untote umherstreifen."},{t="Die Zuflucht des Hermit",b="Gunther Arkanus lebt abgeschieden auf der Insel im Herzen des Blendwassersees. Er befreite sich allein aus der Kontrolle des Lichkönigs, glaubt jedoch, dass alle anderen Untoten weiterhin Sklaven der Geißel sind. Untote Diener bewachen seine Zuflucht. Bethor Eismacht hofft, seinem alten Freund zu zeigen, dass die Verlassenen ihren eigenen Weg wählen können. Als ein Abenteurer seine Gegnerschaft zur Geißel beweist, stimmt Gunther zu, sich den Verlassenen anzuschließen."}},faq={{q="Wo liegt der Blendwassersee?",a="Der Blendwassersee liegt im nordöstlichen Tirisfal, gleich nordöstlich von Brill. Er liegt südlich der zerklüfteten Nordküste und westlich des Scharlachroten Wachpostens, der die Gebirgspässe in Richtung der Westlichen Pestländer bewacht.",al={"blendwassersee lage","wo liegt der blendwassersee","blendwassersee finden"}},{q="Wer lebt auf der Insel in der Mitte des Sees?",a="Gunther Arkanus lebt mit seinen untoten Dienern auf der zentralen Insel, die als Gunthers Zufluchtsort bekannt ist. Die Verlassenen in Brill und Unterstadt interessieren sich für ihn.",al={"wer ist auf der insel","gunther arkanus","blendwassersee insel npc"}},{q="Welche Bedrohungen gibt es am Wasser?",a="Aggressive vile fins und Murlocs suchen am Ufer nach Nahrung. Untote Diener bewachen Gunther Arkanus' Insel gegen Eindringlinge.",al={"monster im see","blendwassersee feinde","gefahren am blendwassersee"}},{q="Warum sprechen die Wachen in Brill von einem Sommerlager hier?",a="Brills Todeswachen scherzen, dass die Verlassenen versucht hätten, an den Ufern des Blendwassersees ein Sommerlager für Kinder zu betreiben. Sie erzählen, maskierte Psychopathen hätten das Gelände terrorisiert, bis das Lager schließen musste, eine düstere örtliche Abwandlung menschlicher Lagerfeuergeschichten.",al={"sommerlager gerücht","brill wachen see witz","maskierter psychopath lager"}}},fx={["010a8c36"]={q="Was ist der Blendwassersee?",a="Der Blendwassersee ist das größte Gewässer in Tirisfal, er erstreckt sich nordöstlich von Brill und wird im Osten von den Hügeln begrenzt, die zum Scharlachroten Wachposten führen. In der Mitte seines dunklen Wassers liegt eine markante Insel, die als Gunthers Zufluchtsort bekannt ist, zusammen mit kleineren Felsvorsprüngen, die die Weite des Sees punktieren.",al={"was ist der blendwassersee","lore zum blendwassersee","erzähl mir vom blendwassersee"}},["5d21e80d"]={q="Was ist die Geschichte des Blendwassersees?",a="Vor der Pest war der Blendwassersee ein friedlicher Zufluchtsort auf dem Land des Königreichs Lordaeron. Heute umgibt sein kaltes Wasser Gunthers Zufluchtsort, wo sich der untote Magier Gunther Arkanus vor der Welt versteckt.",al={"geschichte des blendwassersees","was geschah am blendwassersee","vergangenheit des blendwassersees"}}},fp="16,194,19.347.0,19.415.1,34.218.0,50.169.0,41.124.0,57.224.0"}
P.entries["subzone:brightwood-grove"] = {n="Schattenhain",s="Westlich von Dunkelhain bieten verfallene Höfe und überwucherte Lichtungen im Schattenhain wilden Nightbane-Worgen Unterschlupf.",h="Westlich von Dunkelhain bieten verfallene Höfe und überwucherte Lichtungen im Schattenhain wilden...",kw={"schattenhain","dunkelhain","dämmerwald","night watch","nightbane","wolfsmenschen","worgen"},ang={["class:Hunter"]="Die dunklen Dickichte des Hains erschweren es Euch als Jäger, die bösartigen Nightbane aufzuspüren. Haltet nach Hinterhalten hinter der Baumgrenze Ausschau.",["faction:Alliance"]="Der Schattenhain liegt direkt vor den Toren von Dunkelhain. Seine Worgenrudel zu beseitigen hilft, die Verbindung der bedrängten Stadt nach Westen zu sichern."},sec={{t="Ein Hain im Schatten",b="Der Schattenhain liegt in Sichtweite von Dunkelhain, wo verfallene Höfe und Zäune den Stadtrand markieren. Nightbane-Worgen errichten primitive Lager zwischen den überwucherten Lichtungen und streifen nahe der Stadt umher. Ihre Anwesenheit bedroht Dunkelhain. Deshalb halten die Nachtwache und durchreisende Reisende ihre Zahl gering, um die Siedlung zu schützen."}},faq={{q="Wo liegt der Schattenhain?",a="Der Schattenhain liegt im östlichen Dämmerwald, direkt westlich von Dunkelhain entlang der Hauptwege.",al={"schattenhain lage","wo liegt der schattenhain","schattenhain dämmerwald"}},{q="Welche Kreaturen bewohnen den Schattenhain?",a="Wilde Nightbane-Worgen bewohnen den Schattenhain. Sie errichten primitive Lager in verfallenen Gebäuden und greifen jeden an, der sich nähert.",al={"monster im schattenhain","schattenhain feinde","was lebt im schattenhain"}},{q="Warum ist der Hain für Dunkelhain gefährlich?",a="Der Schattenhain liegt direkt westlich von Dunkelhain. Aggressive Worgenrudel im Unterholz bedrohen Stadtpatrouillen, Versorgungswege und Reisende, die über die Straße ankommen.",al={"warum ist der schattenhain gefährlich","dunkelhain schattenhain bedrohung"}},{q="Gibt es im Hain befreundete Siedlungen?",a="Im Hain gibt es keine befreundeten Siedlungen mehr. Seine wenigen Steingebäude und Gehöfte liegen in Trümmern, den Elementen überlassen und von umherstreifenden Worgen besetzt.",al={"ist jemand im schattenhain freundlich","schattenhain stadt"}}},fx={d7b16ad8={q="Was ist der Schattenhain?",a="Der Schattenhain ist eine schattige Gegend, die sich westlich von Dunkelhain im Dämmerwald befindet. Einst ein Teil des grünen Waldes, bevor Dunkelheit über die Region kroch, liegt der Hain nun unter einer bedrückenden Düsternis. Die verstreuten Gebäude, die einst an seinen Rändern standen, sind zu Ruinen zerfallen, und wilde Rudel von Nachtbann-Worgen haben die überwucherten Felder und Wälder zu ihrem Jagdrevier erklärt.",al={"schattenhain","was ist der schattenhain","schattenhain dämmerwald"}},d83f7d45={q="Warum ist der Schattenhain eine Ruine?",a="Wie ein Großteil des Dämmerwalds ist auch der Schattenhain dem ausbreitenden Fluch und dem Schrecken erlegen, die die Region verschlangen. Die Gehöfte und Strukturen an seinen Rändern wurden aufgegeben und verfielen, als räuberische Nachtbann-Worgen in das Gebiet vordrangen. Jetzt sind statt friedlicher Farmlandschaften oder geschützter Außenposten nur noch die primitiven Lager der Bestien und zertrümmerte Steinfundamente übrig.",al={"warum ist der schattenhain verfallen","schattenhain ruinen","warum wurde der schattenhain aufgegeben"}},f237257f={q="Ist der Schattenhain gefährlich?",a="Der Schattenhain ist für Reisende extrem gefährlich. Grausame Nachtbann-Worgen streifen durch die dunklen Felder, schlagen primitive Lager auf und greifen jeden bösartig an, der sich nähert. Da er direkt westlich von Dunkelhain liegt, stellen die gefräßigen Wolfsmenschen eine ständige Bedrohung für die Grenzen der Stadt dar, was standhafte Verteidiger und Abenteurer erfordert, um ihre Zahl aktiv zu dezimieren.",al={"ist der schattenhain gefährlich","gefahr im schattenhain","wie gefährlich ist der schattenhain"}},["90b29732"]={q="Warum heißt der Ort Schattenhain?",a="Keine erhaltene Überlieferung erklärt den Namen des Hains. Er scheint an eine hellere Vergangenheit zu erinnern, als der Dämmerwald unter Sturmwinds Obhut noch ein üppiger, sonnenbeschienener Wald war. Schatten, Flüche und Worgen haben dem Wald inzwischen das Licht vollständig geraubt.",al={"warum heißt der ort schattenhain","bedeutung des namens schattenhain","ursprung des namens brightwood"}}},fp="16,108,17.325.0,26.87.0,40.125.0,40.151.0,48.154.0"}
P.entries["subzone:brill"] = {n="Brill",s="In Brill versammeln sich Verlassene nördlich der Ruinen von Lordaeron. Frisch erwachte Untote reisen aus Todesend hierher, in eine wiederaufgebaute Menschenstadt, die heute Herrschaft und Streitmacht der Verlassenen in Tirisfal stützt.",h="In Brill versammeln sich Verlassene nördlich der Ruinen von Lordaeron.",kw={"brill","verlassene","galgenschlinge","lordaeron","magistrat sevren","tirisfal","zeppelin"},ang={["faction:Horde"]="Brills Zeppelinanleger verbindet die Horde im Norden mit verbündeten Stützpunkten in Kalimdor und den Östlichen Königreichen.",["race:Undead"]="Verlassenen, die Todesend hinter sich lassen, bietet Brill den ersten Blick auf die Zivilisation und einen Ort, um ihre Treue zur Dark Lady zu beweisen."},sec={{t="Vom Seuchenherd zur Bastion",b="Vor dem Dritten Krieg wuchs Brill unter Adligen wie den Familien Barov und Agamand. Dann wählte Kel'Thuzad die Region für die ersten Experimente des Kults der Verdammten mit der Seuche des Untods aus. Die Seuche erfasste die Bevölkerung so rasch, dass die örtliche Miliz floh. Ein riesiger Friedhof blieb für die Toten zurück.\n\nHeute führt Magistrat Sevren die Verlassenen an, die Brill wiederaufgebaut haben. Verwitterte Gebäude aus Lordaeron säumen die Straßen. Die Stadt koordiniert die Verteidigung gegen Angriffe des Scharlachroten Kreuzzugs, Überreste der Geißel und einheimische Bestien, die durch nekromantischen Verfall verändert wurden."},{t="Knotenpunkt im nördlichen Lordaeron",b="Brill verbindet Tirisfal mit der übrigen Horde. Goblins betreiben den Zeppelinturm und bringen Reisende nach Süden in Richtung Durotar und tief ins Schlingendorntal. Die Taverne Zur Galgenschlinge bietet Unterkunft. In ihrem Keller werden auch gefangene Eiferer des Scharlachroten Kreuzzugs für Verhöre und Versuche der Apotheker festgehalten."}},faq={{q="Wer herrscht über Brill?",a="Magistrat Sevren leitet Brills Zivilverwaltung und örtliche Verteidigung im Auftrag von Fürstin Sylvanas Windläufer und den Verlassenen.",al={"brill anführer","wer hat das sagen in brill","magistrat von brill"}},{q="Warum liegt vor Brill ein so riesiger Friedhof?",a="Kel'Thuzad führte in Brill einige seiner ersten Versuche mit der Seuche des Untods an Lebenden durch. Die Seuche tötete die örtliche Menschenbevölkerung so rasch, dass ein riesiger Friedhof nötig war, um die Opfer zu bestatten, bevor sie als Geißel auferstanden.",al={"brill friedhof","friedhof bei brill","warum so viele gräber"}},{q="Wozu dient die Taverne Zur Galgenschlinge?",a="Die Taverne Zur Galgenschlinge bietet müden Reisenden Unterkunft. In ihrem Keller erproben Apotheker Chemikalien und Gifte an gefangenen Eiferern des Scharlachroten Kreuzzugs.",al={"galgenschlinge","brill gasthaus","was geschieht in der taverne von brill"}},{q="Wohin führen die Zeppelinrouten vom Turm vor Brill?",a="Goblinbesatzungen fliegen von Brills Zeppelinturm nach Kalimdor vor die Tore Orgrimmars und nach Süden zum Basislager Grom'gol im Schlingendorntal.",al={"brill zeppelinziele","wohin fliegen zeppeline von brill","brill flugrouten"}}},fx={["0490a2ec"]={q="Was ist Brill?",a="Brill ist die zentrale Siedlung von Tirisfal, die sich nördlich der Ruinen von Lordaeron befindet. Einst ein verschlafenes menschliches Dorf, dient es heute als wichtiger militärischer Knotenpunkt und Außenposten für die Verlassenen. Frische Rekruten, die von Todesend kommen, melden sich hier, um die Streitkräfte von Fürstin Sylvanas Windläufer bei der Sicherung der umliegenden Wälder gegen eindringende Bedrohungen zu unterstützen.",al={"was ist brill","übersicht brill","stadt brill"}},["3209731c"]={q="Was ist früher mit Brill passiert?",a="Während des Dritten Krieges gehörte Brill zu den ersten Dörfern, die von der Pest des Untods heimgesucht wurden, als der Nekromant Kel'Thuzad seine dunklen Experimente in Tirisfal begann. Seine Verteidiger wurden überwältigt, was die Überlebenden zur Flucht zwang, bevor Prinz Arthas die Region untersuchte. Nachdem die Geißel durch das Königreich gewütet hatte, beanspruchten die Verlassenen die zerstörte Siedlung für sich und bauten sie zu ihrem wichtigsten befestigten Knotenpunkt nördlich der Hauptstadt aus.",al={"geschichte von brill","was geschah in brill","lore zu brill"}},fbdb53db={q="Ist Brill gefährlich?",a="Innerhalb seiner Grenzen wird Brill von wachsamen Todeswachen und der Wache von Magistrat Sevren stark verteidigt. Außerhalb der Stadt jedoch drängt die Gefahr von allen Seiten. Gedankenlose Geißel streifen durch die Landschaft, bösartige Fäulnisbalg-Gnolle durchkämmen nahegelegene Wasserwege und fanatische Scharlachrote Kreuzzügler führen einen unerbittlichen Krieg durch die Wälder, um jeden, der in der Siedlung lebt, vollständig auszulöschen.",al={"ist brill sicher","bedrohungen für brill","ist brill gefährlich"}}},fp="5,198,29.552.0,32.284.0,16.121.0,52.235.0,37.137.0,54.130.0"}
P.entries["subzone:brill-town-hall"] = {n="Rathaus von Brill",s="Im Rathaus von Brill regieren die Verlassenen Brill und planen die Verteidigung Tirisfals. Seine Türen stehen im zerschlagenen Herzen Lordaerons.",h="Im Rathaus von Brill regieren die Verlassenen Brill und planen die Verteidigung Tirisfals.",kw={"brill","verlassene","lordaeron","magistrat sevren","sevren","tirisfal","rathaus"},ang={["faction:Horde"]="Als Verbündeter der Horde könnt Ihr nach Eurer Ankunft in Tirisfal das Rathaus von Brill besuchen und sehen, wie die Verlassenen in ihrer verdüsterten Heimat zivile Obrigkeit und militärische Ordnung aufrechterhalten.",["race:Undead"]="Als Verlassener, der von Todesend aufbricht, erlebt Ihr hier erstmals eine geordnete zivile Verwaltung unter Königin Sylvanas. Das Rathaus von Brill organisiert offiziell die örtliche Verteidigung und die Bemühungen, das Land zurückzuerobern."},sec={{t="Verwaltungssitz der Verlassenen",b="Vom Rathaus von Brill aus herrschen die Verlassenen weiter, während weite Teile Lordaerons in Trümmern liegen. Magistrat Sevren leitet von seinem Rednerpult aus die Stadtgeschäfte und erteilt reisenden Verlassenen Befehle. Nur wenige bekannte Rathäuser sind unter der Kontrolle der Verlassenen noch in Betrieb. Neben der Entweihten Feste im Arathihochland zählt das Rathaus von Brill dazu. Es hält Lordaerons alte städtische Ordnung unter untoter Herrschaft am Leben."}},faq={{q="Wozu dient das Rathaus von Brill?",a="Im Rathaus von Brill regieren die Verlassenen der Stadt. Magistrat Sevren und andere Anführer leiten die örtliche Verteidigung, erlassen Verordnungen und weisen Reisenden sowie frisch erwachten Untoten Aufgaben zu.",al={"zweck des rathauses von brill","was ist dieses gebäude","warum das rathaus von brill besuchen"}},{q="Wer hat hier das Sagen?",a="Magistrat Sevren führt von seinem Rednerpult aus den Vorsitz im Rathaus von Brill. Er verwaltet die Stadtgeschäfte für die Verlassenen und leitet ihre Einsätze im zentralen Tirisfal.",al={"wer leitet das rathaus von brill","anführer im rathaus von brill","wer ist der magistrat"}},{q="Was macht dieses Rathaus im Vergleich zu anderen bemerkenswert?",a="Das Rathaus von Brill ist eines der wenigen aktiven Rathäuser unter der Leitung der Verlassenen. Die Entweihte Feste in Arathi ist ein weiteres; die meisten Rathäuser gehören zu Königreichen lebender Menschen.",al={"besonderes rathaus der verlassenen","gibt es andere rathäuser der verlassenen"}}},fx={["27f01e5a"]={q="Was ist das Rathaus von Brill?",a="Das Rathaus von Brill ist das markanteste Gebäude in der Siedlung Brill im zentralen Tirisfal. Es dient als ziviles und administratives Herz der Stadt, wo die Führung der Verlassenen lokale Angelegenheiten organisiert und Bemühungen in der gesamten Region koordiniert.",al={"was ist das rathaus von brill","ort rathaus von brill","brill rathaus"}},["0a44eaf1"]={q="Ist das Rathaus von Brill gefährlich?",a="Nicht, wenn Ihr ein Verbündeter der Verlassenen und der Horde seid. Das Rathaus von Brill steht fest unter der Kontrolle der Verlassenen und fungiert sicher als deren lokaler Regierungssitz, obwohl jeder Eindringling, der der Dunklen Fürstin feindlich gesinnt ist, innerhalb seiner Mauern keine Gnade finden wird.",al={"ist das rathaus von brill gefährlich","rathaus von brill sicher","gefahr im rathaus von brill"}}},fp="15,122,26.379.0,37.178.0,22.166.0,49.162.0"}
P.entries["subzone:broken-hall"] = {n="Broken Hall",s="Unter dem Tränenteich liegt die Broken Hall überflutet am äußeren Rand des Tempels von Atal'Hakkar. Ysera und ihre grünen Drachen zerrten die Zikkurat unter Wasser und trieben die Atal'ai in tiefere Kammern.",h="Unter dem Tränenteich liegt die Broken Hall überflutet am äußeren Rand des Tempels von Atal'Hakkar.",kw={"atal'ai","broken hall","hall of masks","tränenteich","versunkener tempel","sümpfe des elends","der tempel von atal'hakkar"},ang={["race:Troll"]="Als Troll, der die Loa verehrt, seht Ihr in der Broken Hall ein düsteres Mahnmal für das Verderben, das über die Eiferer der Atal'ai kam, die sich gegen ihresgleichen stellten, um Hakkar the Soulflayer zu dienen."},sec={{t="Überflutete Schwelle",b="Trübes Sumpfwasser bedeckt den Boden der Broken Hall. Als die grünen Drachen die Zikkurat der Atal'ai unter den Tränenteich zerrten, wurde die äußere Halle am schwersten beschädigt. Ihr Boden brach ein, und die Eiferer der Atal'ai verließen die überflutete Kammer und zogen in tiefere Bereiche des Tempels. Ihr müsst durch die Ruinen waten, bevor Ihr die Treppe zur Hall of Masks hinaufsteigt."}},faq={{q="Was ist die Broken Hall?",a="Die Broken Hall ist die äußere Eingangskammer des Tempels von Atal'Hakkar, gleich hinter seinem versunkenen Eingang unter dem Tränenteich.",al={"broken hall überblick","was ist dieser ort","eingangshalle des tempels"}},{q="Warum ist die Broken Hall überflutet und zerstört?",a="Der grüne Drachenschwarm zerschlug die Broken Hall, als er den Tempel unter das Sumpfwasser zerrte, um die Beschwörung des Blutgottes Hakkar zu verhindern. Der Boden brach auf, und Wasser füllte die Kammer.",al={"warum ist die broken hall nass","warum ist die broken hall versunken","wer hat die halle zerstört"}},{q="Leben noch Trolle der Atal'ai in dieser Halle?",a="Die Broken Hall liegt weitgehend verlassen da. Nachdem der obere Teil des Tempels versunken war, zogen sich die Kultisten der Atal'ai in trockenere, leichter zu verteidigende Kammern tiefer im Komplex zurück.",al={"gegner in der broken hall","ist die broken hall leer"}},{q="Wohin führt die Treppe in der Broken Hall?",a="Die Steintreppe aus der überfluteten Broken Hall führt direkt zur Hall of Masks.",al={"broken hall treppe","broken hall ausgang","wohin von der broken hall"}}},fp="11,205,17.342.0,24.130.0,42.190.0,49.159.0,44.79.0"}
P.entries["subzone:broken-pillar"] = {n="Zerbrochene Säule",s="Südlich von Gadgetzan erforscht Marvon Rivetseeker Artefakte, die im Sand von Tanaris vergraben liegen. Sein Forschungslager steht neben den uralten Trollruinen der Zerbrochenen Säule.",h="Südlich von Gadgetzan erforscht Marvon Rivetseeker Artefakte, die im Sand von Tanaris vergraben liegen.",kw={"zerbrochene säule","gadgetzan","gahz'ridian","marvon rivetseeker","ratschet","tanaris","trollruinen"},ang={["race:Gnome"]="Marvon Rivetseekers Erforschung unbekannter Relikte spiegelt die wissenschaftliche Neugier der Gnome wider, auch wenn seine Methoden unverkennbar goblinisch sind.",["race:Troll"]="Für Trolle zeugen die zerfallenden Säulen von einem Zeitalter der Trollarchitektur ihrer Ahnen, bevor Zeit und Sand die Herrschaft des Reiches über das südliche Kalimdor brachen."},sec={{t="Sonnengebleichter Stein",b="Südlich von Gadgetzan und östlich der Ewigen Sande erhebt sich die Zerbrochene Säule aus der Wüste. Tanaris hat einen Großteil ihres uralten Trollmauerwerks verschlungen. Wüstenbestien streifen in der Nähe umher, doch die Ruinen bieten noch immer Hinweise auf die frühesten Zivilisationen des Kontinents. Marvon Rivetseeker, ein Goblinforscher aus Ratschet, hat sein Lager neben den zertrümmerten Steinen aufgeschlagen. Dort untersucht er Gahz'ridian-Relikte, die über die Ödnis verstreut liegen."}},faq={{q="Was ist die Zerbrochene Säule?",a="Die Zerbrochene Säule ist eine uralte Trollruine im Zentrum von Tanaris, südlich von Gadgetzan und östlich der Ewigen Sande. Verwitterte Säulen und Trümmer, halb in wandernden Dünen vergraben, sind alles, was noch übrig ist.",al={"zerbrochene säule tanaris","was ist die zerbrochene säule","säulenruinen"}},{q="Wer lagert an der Zerbrochenen Säule?",a="Marvon Rivetseeker, ein Goblinwissenschaftler und Goldsucher aus Ratschet, hat zwischen den Ruinen ein Forschungslager aufgeschlagen. Er untersucht geheimnisvolle Gahz'ridian-Ornamente, die in der umliegenden Wüste vergraben liegen.",al={"wer ist an der zerbrochenen säule","zerbrochene säule npc","marvon rivetseeker standort"}},{q="Wer hat die ursprünglichen Bauwerke hier errichtet?",a="Uralte Trolle errichteten die Bauwerke, deren Ruinen hier stehen. Ihr Mauerwerk stammt aus der Zeit, als Trollreiche das südliche Kalimdor beherrschten, lange bevor Wüstensand die Region bedeckte.",al={"wer erbaute die zerbrochene säule","zerbrochene säule geschichte","zerbrochene säule ursprung"}},{q="Was sind Gahz'ridian-Relikte?",a="Gahz'ridian sind uralte Steinartefakte und gemeißelte Gesichter, die im Sand von Tanaris vergraben liegen. Von seinem Lager an der Zerbrochenen Säule aus erforscht Marvon Rivetseeker sie, um die Handwerkskunst und Macht des verschwundenen Reiches zu ergründen.",al={"gahzridian","was ist gahzridian","marvon questgegenstände"}}},fp="13,163,18.419.0,26.194.0,35.187.0,34.154.0,28.208.0"}
P.entries["subzone:bronzebeard-encampment"] = {n="Bronzebeards Lager",s="Im südlichen Silithus hält Bronzebeards Lager einen Zwergenstützpunkt östlich des Skarabäuswalls. Forscher der Explorer's League untersuchen uralte Silithidenglyphen und Geheimnisse, die unter der Wüste begraben liegen.",h="Im südlichen Silithus hält Bronzebeards Lager einen Zwergenstützpunkt östlich des Skarabäuswalls.",kw={"bronzebeards lager","deathclasp","explorer's league","frankal stonebridge","glibb","rutgar glyphenschnitzer","der skarabäuswall","silithus"},ang={["faction:Alliance"]="Als Reisender der Allianz in Silithus könnt Ihr weit südlich von Burg Cenarius ein freundlich gesinntes Lager finden.",["race:Dwarf"]="Als Zwerg könnt Ihr in dieser rauen Wüste die Hartnäckigkeit der Explorer's League bei der Arbeit erleben. Forscher aus Eisenschmiede suchen hier nach historischer Wahrheit."},sec={{t="Ein Stützpunkt im wandernden Sand",b="Bronzebeards Lager liegt nahe den südlichen Klippen von Silithus, in Sichtweite des Skarabäuswalls. Eisenschmiede gründete das Lager für archäologische Arbeiten. Die Forscher Rutgar Glyphenschnitzer und Frankal Stonebridge untersuchen Inschriften und Monumente, die vergessene Zivilisationen hinterlassen haben. Sengende Hitze, Skorpide und Silithidenschwärme machen ihre Arbeit gefährlich."},{t="Glyphen und Verzweiflung",b="In Bronzebeards Lager geht Forschung Hand in Hand mit dem Überleben. Die Bedrohung durch Silithiden breitet sich aus unterirdischen Schwarmbauten aus, und der monströse Skorpid Deathclasp streift in der Nähe umher. Die Forscher verlassen sich auf durchreisende Abenteurer, um Abreibungen rätselhafter Glyphen zu beschaffen, uralte insektoide Sprachen zu entziffern und in der Wüste verschollene Gefährten zu finden."}},faq={{q="Wo liegt Bronzebeards Lager?",a="Bronzebeards Lager liegt im südlichen Silithus, östlich des Skarabäuswalls und nördlich des südlichen Gebirgskamms.",al={"wo liegt bronzebeards lager","bronzebeards lager standort","wie findet man bronzebeards lager"}},{q="Wer leitet Bronzebeards Lager?",a="Im Lager arbeiten Mitglieder und Mitarbeiter der zwergischen Explorer's League. Dazu gehören der Glyphenforscher Rutgar Glyphenschnitzer, Frankal Stonebridge und ihr Gefährte Glibb.",al={"wer ist in bronzebeards lager","bronzebeards lager npcs","wer leitet bronzebeards lager"}},{q="Was erforschen die Zwerge hier?",a="Die Forscher untersuchen uralte Steinglyphen, das Verständigungssystem der Silithiden und seit Langem verschüttete Geheimnisse des südlichen Kalimdor.",al={"warum sind zwerge in silithus","was erforscht rutgar","zweck von bronzebeards lager"}},{q="Welche Gefahren lauern nahe dem Lager?",a="Aggressive Silithidenkäfer, Sandskorpione und Deathclasp durchstreifen die umliegende Wüste. Deathclasp ist der riesige Skorpid, der als Terror of the Sands bekannt ist, und nistet unmittelbar südöstlich des Lagers.",al={"gefahren nahe bronzebeards lager","deathclasp standort","bronzebeards lager monster"}}},fp="22,195,32.341.0,22.324.0,44.115.0,36.169.0,35.124.0,38.181.0"}
P.entries["subzone:browman-mill"] = {n="Braumanns Mühle",s="Untote drängen sich nun in Braumanns Mühle, nördlich der Kapelle des Hoffnungsvollen Lichts. Einst diente sie Lordaerons Holzhandel; heute bleibt Stephen Browman im Tod in seiner zerstörten Werkstatt gefangen.",h="Untote drängen sich nun in Braumanns Mühle, nördlich der Kapelle des Hoffnungsvollen Lichts.",kw={"monstrositäten","banshees","braumanns mühle","östliche pestländer","kapelle des hoffnungsvollen lichts","sägewerk","geißel","stephen browman"},ang={["class:Paladin"]="Als Paladin seht Ihr in der entweihten Mühle und ihren gepeinigten Geistern jene Übel, von denen die heiligen Orden Lordaeron zu reinigen suchen.",["race:Undead"]="Als Untoter wisst Ihr, dass Stephen Browmans Versklavung an jene erinnert, die der Lichkönig beanspruchte und denen der freie Wille verwehrt blieb, den die Verlassenen errangen."},sec={{t="Ein Gewerbe in Trümmern",b="Vor dem Dritten Krieg verarbeitete Braumanns Mühle Holz aus dem Ostweald für nahe gelegene Städte und Gehöfte. Dann breitete sich die Seuche der Geißel über Lordaeron aus, und die Mühle fiel mit der Provinz. Nun liegen verrottende Balken und zerschlagene Räder still, während Monstrositäten, Banshees und Skelettkrieger auf dem Gelände patrouillieren. So nahe an der Kapelle des Hoffnungsvollen Lichts zeigen die Ruinen, wie nah die untote Horde der Argentumdämmerung gekommen ist."},{t="Das Schicksal des Aufsehers",b="Stephen Browman besaß Braumanns Mühle, bevor die Geißel sein Anwesen überrannte. Die Geißel tötete ihn und erweckte ihn als Ghul, gebunden an den Willen des Lichkönigs. Er verharrt in der dunklen Mühle und bewacht die zerbrochenen Überreste seines Lebenswerks."}},faq={{q="Wo liegt Braumanns Mühle?",a="Braumanns Mühle liegt im äußersten Osten der Östlichen Pestländer, direkt nördlich der Kapelle des Hoffnungsvollen Lichts.",al={"braumanns mühle lage","wo ist braumanns mühle","wie braumanns mühle finden"}},{q="Welche Feinde bewohnen die Mühle?",a="Monstrositäten, Banshees, Skelettkrieger und Ghule bevölkern das Gelände von Braumanns Mühle.",al={"braumanns mühle gegner","wer ist bei braumanns mühle","was lebt in braumanns mühle"}},{q="Wer war Stephen Browman?",a="Stephen Browman besaß und betrieb das Sägewerk. Die Geißel tötete ihn während Lordaerons Untergang und erweckte ihn als Ghul, dazu verdammt, die zerstörte Mühle zu bewachen.",al={"wer ist stephen browman","stephen browman geschichte","browman ghul"}},{q="Warum ist Braumanns Mühle für Reisende gefährlich?",a="Mächtige Untote suchen Braumanns Mühle heim und machen sie für Reisende gefährlich. Die Mühle liegt einen kurzen Ritt nördlich der Bastion der Argentumdämmerung an der Kapelle des Hoffnungsvollen Lichts.",al={"warum ist braumanns mühle gefährlich","bedrohung durch braumanns mühle"}}},fp="12,174,17.410.0,19.231.0,30.111.0,38.82.0,24.157.0,43.157.0"}
P.entries["subzone:bulwark"] = {n="Das Bollwerk",s="Am Rand von Tirisfal wacht das Bollwerk über die Westlichen Pestländer. Truppen der Verlassenen und der Argentumdämmerung halten den Außenposten gemeinsam, und Expeditionen der Horde brechen von dort in den verseuchten Osten auf.",h="Am Rand von Tirisfal wacht das Bollwerk über die Westlichen Pestländer.",kw={"argentumdämmerung","das bollwerk","chillwind","verlassene","geißel","tirisfal","westliche pestländer"},ang={["faction:Horde"]="Als Angehörige der Horde dient Euch das Bollwerk als wichtigster Zugang und als Stützpunkt für Einsätze in den Plaguelands. Die Allianz hält das Zugwindlager auf der gegenüberliegenden Seite.",["race:Undead"]="Als Verlassene haltet Ihr am schmalen Durchgang des Bollwerks Wache gegen die Armeen des Lichkönigs. Sie dürfen nicht geradewegs auf Brill und Unterstadt zumarschieren."},sec={{t="Ein Schild gegen die Geißel",b="Wachen der Verlassenen halten die Palisade des Bollwerks, wo Tirisfal an die Westlichen Pestländer grenzt. Der Außenposten versperrt den Weg aus den verseuchten Landen, in denen Untote umherstreifen. Hier arbeiten die Truppen der Verlassenen mit der neutralen Argentumdämmerung zusammen. Gemeinsam rufen sie erfahrene Champions der Horde auf, die Geißel anzugreifen und die Schergen des Lichkönigs daran zu hindern, Tirisfal zu erreichen."}},faq={{q="Welchem Zweck dient das Bollwerk?",a="Das Bollwerk ist die vorderste Verteidigungsstellung der Horde gegen die Geißel und ein Stützpunkt für ihre Truppen. Es schützt Tirisfal und Unterstadt vor Angriffen aus den Westlichen Pestländern. Befehlshaber der Argentumdämmerung und der Verlassenen koordinieren Vorstöße in die verseuchten Lande.",al={"warum steht das bollwerk hier","zweck des bollwerks","was ist das für ein ort"}},{q="Können Allianzcharaktere das Bollwerk besuchen, um mit der Argentumdämmerung zu sprechen?",a="Nein. Die Vertreter der Argentumdämmerung am Bollwerk sind neutral, doch Wachen der Verlassenen bilden die Garnison des Lagers. Besucher der Allianz, die die Palisade betreten, werden sofort angegriffen.",al={"kann die allianz das bollwerk nutzen","allianz am bollwerk","ist das bollwerk nur für die horde"}},{q="Ist das Bollwerk für junge Abenteurer sicher, die Tirisfal verlassen?",a="Nein. Das Tor führt nach Tirisfal, doch in den Westlichen Pestländern dahinter lauern tödliche Untote und Seuchenkessel. Unerfahrene Reisende, die die Palisade passieren, finden rasch den Tod.",al={"mit niedriger stufe am bollwerk vorbei","plaguelands mit niedriger stufe betreten"}}},fx={["3800d924"]={q="Was ist das Bollwerk?",a="Das Bollwerk ist ein befestigter Außenposten an der Grenze zwischen Tirisfal und den Westlichen Pestländern. Es dient als östliche Verteidigungslinie der Verlassenen und schützt den Eingang zu Tirisfal vor den unerbittlichen Schrecken der Geißel. Hier arbeiten die Wachen der Verlassenen und Abgesandte der Argentumdämmerung Seite an Seite, um die Verteidigung zu koordinieren, untote Einfälle zurückzuhalten und fähige Champions in die verheerten Lande dahinter zu entsenden.",al={"was ist das bollwerk","übersicht das bollwerk","über das bollwerk"}},["7098c368"]={q="Wer besetzt das Bollwerk?",a="Der Außenposten wird von Soldaten der Verlassenen, die Königin Sylvanas die Treue geschworen haben, zusammen mit Mitgliedern der neutralen Argentumdämmerung bemannt. Während die Verlassenen die Grenze bewachen und ihr nördliches Königreich sichern, unterhält die Argentumdämmerung hier eine Präsenz, um erfahrene Abenteurer der Horde zu rekrutieren und sie mit Missionen auszustatten, um gegen die Schergen des Lichkönigs in den Pestländern zu schlagen.",al={"wer leitet das bollwerk","wer ist am bollwerk","bewohner des bollwerks"}},a92b042c={q="Warum heißt es das Bollwerk?",a="Die Befestigung hat ihren Namen von ihrer Rolle als buchstäbliches Bollwerk – ein Verteidigungswall, der gebaut wurde, um die Länder der Verlassenen vor Invasionen zu schützen. Da es genau an der Schwelle steht, an der Tirisfal auf die Pestländer trifft, bilden seine schweren Barrikaden die letzte Verteidigungslinie, die die monströsen Legionen der Geißel zurückhält.",al={"warum heißt es bollwerk","bedeutung des namens bollwerk","warum der name bollwerk"}}},fp="7,192,28.348.0,35.254.0,72.168.0,59.173.0"}
P.entries["subzone:burning-blade-coven"] = {n="Koven der Brennenden Klinge",s="In den nördlichen Klippen des Tals der Prüfungen bedroht der Koven der Brennenden Klinge neue Rekruten der Horde. Kultisten und beschworene Dämonen suchen die alten Mineralienhöhlen heim und nutzen sie, um direkt vor Durotars Toren dunkle Magie zu praktizieren.",h="In den nördlichen Klippen des Tals der Prüfungen bedroht der Koven der Brennenden Klinge neue Rekruten der...",kw={"koven der brennenden klinge","dämon","durotar","wichtel","thazz'ril","das tal der prüfungen","yarrog baneshadow"},ang={["class:Warlock"]="Als Hexenmeister erkennt Ihr in den dämonischen Wichteln und finsteren Ritualen hier eine frühe Warnung, denn hier wird Teufelsmacht leichtfertig eingesetzt.",["race:Orc"]="Als Orc könnt Ihr den Kult der Burning Blade nahe dem Tal der Prüfungen als unerträgliche Beleidigung für Thralls neue Horde ansehen. Seine Anwesenheit erinnert an die Dämonenverehrung, die die Orcs mühsam hinter sich gelassen haben."},sec={{t="Ein Schatten über Proving Grounds",b="Finstere Rituale bringen nun Unheil in die Höhlen am Nordrand des Tals der Prüfungen. Wichtel und niedere Unholde strömen aus dem Höhleneingang und stiften Chaos unter den jungen Orcs und Dunkelspeertrollen, die hier für die Horde ausgebildet werden. Yarrog Baneshadow führt den Kult der Burning Blade tief aus dem Inneren der Höhlen an. Was einst eine Wildnis zur Bewährung war, ist nun ein Schlachtfeld gegen dämonische Verderbnis."},{t="Verderbnis im Gestein",b="Bevor die Dämonen Fuß fassten, hofften örtliche Aufseher, die Rohstoffe der Höhlen für die Siedlung abzubauen. Großknecht Thazz'ril ging hinein, um die Mineralienvorkommen zu untersuchen, doch Kultisten vertrieben ihn so hastig, dass er wertvolle Ausrüstung zurückließ.\n\nNun ist die Vertreibung von Baneshadows Koven aus den Höhlen die letzte Bewährungsprobe für angehende Krieger, Schurken und Zauberwirker, bevor sie ins übrige Durotar aufbrechen."}},faq={{q="Wo befindet sich der Koven der Brennenden Klinge?",a="Der Koven der Brennenden Klinge besetzt Höhlen in den hohen roten Felskämmen am Nordrand des Tals der Prüfungen in Durotar.",al={"standort des kovens","wo ist der koven der brennenden klinge","höhlenstandort im tal"}},{q="Wer führt die Kultisten hier an?",a="Der Hexenmeister Yarrog Baneshadow führt den Koven an, leitet seine Rituale und befehligt seine beschworenen Dämonen.",al={"anführer des kovens","wer führt den koven der brennenden klinge an","yarrog"}},{q="Welche Arten von Feinden lauern im Inneren?",a="In den Höhlen hausen abtrünnige Wichtel, niedere dämonische Diener und sterbliche Akolythen, die dem Kult der Burning Blade angehören.",al={"welche gegner sind in der höhle","monster des kovens","dämonen im tal der prüfungen"}},{q="Warum gehen neue Rekruten in die Höhle?",a="Neue Abenteurer unter den Orcs und Trollen wagen sich in die Tiefen der Höhle, um verlorene Werkzeuge wie die Hacke von Großknecht Thazz'ril zu bergen. Außerdem töten sie Yarrog Baneshadow als letzten Initiationsritus, bevor sie das Tal verlassen.",al={"warum zum koven gehen","zweck des kovens","letzte prüfung beim koven"}}},fx={["8ab36280"]={q="Was ist der Koven der Brennenden Klinge?",a="Der Koven der Brennenden Klinge ist eine dunkle Höhle, die in die nördlichen roten Berge des Tals der Prüfungen gegraben wurde. Einst eine verlassene Höhle, die auf Mineralien untersucht wurde, wurde sie von dämonischen Kultisten besetzt, die die Proving Grounds der Horde bedrohen.",al={"was ist der koven der brennenden klinge","hintergrund zum koven der brennenden klinge","was ist diese höhle"}},["7f26a7cc"]={q="Ist der Koven der Brennenden Klinge gefährlich?",a="Er stellt eine ernste Bedrohung für das Tal der Prüfungen dar. Boshafte Wichtel und gefährliche Dämonen strömen bereits aus dem Höhleneingang, und finstere Mitglieder der Brennenden Klinge lauern in ihren Tiefen. Das Eindringen in die Höhle, um sich diesen Gefahren zu stellen, dient als letzte Prüfung für angehende Orc- und Troll-Abenteurer, bevor ihnen gestattet wird, nach Durotar zu reisen.",al={"ist der koven der brennenden klinge gefährlich","wie gefährlich ist der koven","ist es hier sicher"}},["5cf26a24"]={q="Warum heißt er Koven der Brennenden Klinge?",a="Die Höhle hat ihren Namen von dem Kult der Brennenden Klinge, dessen Mitglieder ihre Tunnel heimlich besetzt haben. Sie nutzen die abgelegenen Aushöhlungen als Koven, um sich mit dämonischen Wesen zu verbünden und Pläne gegen die junge Horde direkt vor der Nase ihrer Mentoren zu schmieden.",al={"warum heißt er koven der brennenden klinge","namensursprung koven der brennenden klinge","wer benannte den koven der brennenden klinge"}}},fp="19,218,33.377.0,23.397.0,41.122.0,28.101.0,34.108.0,37.202.0"}
P.entries["subzone:caer-darrow"] = {n="Darrowehr",s="Phantome suchen Darrowehr über dem Darrowmeresee in den Westlichen Pestländern heim. Einst herrschte Haus Barov von seiner Festung aus, die inzwischen an Kel'Thuzad verkauft und in Scholomance verwandelt wurde.",h="Phantome suchen Darrowehr über dem Darrowmeresee in den Westlichen Pestländern heim.",kw={"barov","darrowehr","kult der verdammten","darrowmeresee","gandling","runenstein","sarkhoff","scholomance","spectral essence"},ang={["faction:Alliance"]="Für die Allianz erinnert Darrowehr an zwei Fälle von Verrat. Freibeuter aus Alterac überfielen während des Zweiten Krieges die Flotte von Lord Uther dem Lichtbringer aus dem Hinterhalt und enthüllten damit König Perenoldes Verrat. Später verkaufte Haus Barov seinen Stammsitz an Kel'Thuzad.",["race:Human"]="Als Mensch könnt Ihr Darrowehr als ehemaligen Sitz des Hauses Barov erkennen, das einst zu den reichsten Adelsfamilien Lordaerons zählte. Ihre Gier brachte sie dazu, Pakte mit dem Kult der Verdammten zu schließen."},sec={{t="Erbe von Krieg und Verrat",b="Darrowehr schützte Lordaeron und beherbergte lange vor der Geißel einen uralten Runenstein der Elfen. Während des Zweiten Krieges plünderte die Horde die Festung und zerschlug den Stein für Gul'dans Altäre der Stürme. Lord Uther der Lichtbringer stach in See, um den Überlebenden zu helfen, doch Freibeuter aus Alterac überfielen seine Flotte aus dem Hinterhalt. Ihre Hinterlist offenbarte der Allianz den Verrat Alteracs."},{t="Der Fall des Hauses Barov",b="Nach dem Zweiten Krieg erstand Darrowehr als prächtiger Landsitz der Familie Barov neu. Ihre umfangreichen Besitzurkunden umfassten Ländereien in Brill, Tarrens Mühle und Süderstade. Als das Alter ihren Reichtum und ihre Sterblichkeit bedrohte, schlossen die Barovs einen Handel mit Kel'Thuzad. Der Kult der Verdammten fasste unter der Festung Fuß und gründete Scholomance.\n\nNoch bevor der Dritte Krieg über Lordaeron hinwegfegte, befiel eine erste Seuche die Bediensteten und Stadtbewohner der Insel. Sie starben, dazu verdammt, als verweilende Echos die verfallene Festung heimzusuchen."}},faq={{q="Was ist Darrowehr?",a="Darrowehr erhebt sich als Inselfestung im Darrowmeresee in den Westlichen Pestländern. Einst war es der Stammsitz der wohlhabenden Familie Barov, heute ist es eine Ruine über den Katakomben von Scholomance, einer Akademie der Nekromantie.",al={"darrowehr überblick","was ist dieser ort","darrowehr hintergrund"}},{q="Warum ist die Stadt verlassen und verfallen?",a="Darrowehr wurde verlassen, nachdem die Familie Barov mit Kel'Thuzad einen Handel geschlossen und ihren Landsitz dem Kult der Verdammten für Unsterblichkeit überlassen hatte. Der Kult ließ eine tödliche Seuche auf die Siedlung los, bevor die großflächige Invasion Lordaerons begann.",al={"warum ist darrowehr zerstört","was geschah mit darrowehr","darrowehr geschichte"}},{q="Warum kann ich die Geister in der Stadt nicht sehen?",a="Die ermordeten Bewohner von Darrowehr verweilen als ruhelose Geister, gefangen in ihren letzten Augenblicken. Gewöhnliche Augen können sie ohne besondere magische Sicht nicht sehen, wie sie etwa die Spectral Essence gewährt, die von den Geistern von Eva und Lucien Sarkhoff bereitgestellt wird.",al={"wo sind die geister","unsichtbare menschen darrowehr","wie geister sehen"}},{q="Was war das für ein Runenstein, der einst hier stand?",a="Während des Zweiten Krieges beherbergte Darrowehr einen uralten Runenstein der Hochelfen. Die Horde überfiel die Insel und meißelte den heiligen Stein in Stücke. Gul'dan nutzte sie, um die Altäre der Stürme zu errichten und Magie in Ogermagier zu leiten.",al={"runenstein in darrowehr","runenstein der elfen","stein altar der stürme"}},{q="Was liegt unter der Festung?",a="Scholomance liegt unter der Festung und dient dem Kult der Verdammten als Hauptquartier und Ausbildungsstätte. Unter der Führung von Dunkelmeister Gandling studieren ihre Nekromanten und Akolythen die dunklen Künste und experimentieren an den Toten.",al={"was liegt unter darrowehr","was ist im keller","dungeon unter darrowehr"}}},fp="11,164,28.361.0,23.497.1,20.216.0,37.243.0,39.240.1,44.226.0,32.202.0"}
P.entries["subzone:calmbreeze-inn"] = {n="Calmbreeze Inn",s="In Shen'dar und Valaanar bieten die Calmbreeze Inns Reisenden auf der Insel Zephras Erholung. Beide bieten Unterkunft und örtliche Dienste.",h="In Shen'dar und Valaanar bieten die Calmbreeze Inns Reisenden auf der Insel Zephras Erholung.",kw={"calmbreeze inn","coriella calmbreeze","eldre'thalas","shen'dar","valaanar","insel zephras"},ang={["class:Rogue"]="Als Schurke in Shen'dar könnt Ihr Euch am Herdfeuer des Calmbreeze Inn von Miriann Mistblade unterweisen lassen.",["profession:Herbalism"]="Als Kräuterkundiger in Shen'dar könnt Ihr Halassa Fernbreeze im Calmbreeze Inn finden und Eure Sammelfertigkeiten verfeinern."},sec={{t="Rast auf der Insel",b="Reisende können in den Calmbreeze Inns auf der Insel Zephras rasten. Coriella Calmbreeze führt das Gasthaus in Shen'dar, wo sich die Handwerker der Insel versammeln. Dort findet Ihr Lehrmeister für Kräuterkunde, Kürschnerei und Verzauberkunst.\n\nGegenüber heißt das Gasthaus in Valaanar einheimische Wanderer willkommen und beherbergt seltene Kuriositäten. Im Obergeschoss enthält ein Audiokristall eine Aufzeichnung der uralten Rebellion in Eldre'Thalas."}},faq={{q="Wo befinden sich die Calmbreeze Inns?",a="Die Calmbreeze Inns befinden sich in Shen'dar und Valaanar auf der Insel Zephras.",al={"calmbreeze inn standort","wo ist calmbreeze inn","calmbreeze inn karte"}},{q="Wer führt das Gasthaus in Shen'dar?",a="Gastwirtin Coriella Calmbreeze führt das Gasthaus in Shen'dar und heißt Inselbewohner und Reisende willkommen.",al={"calmbreeze gastwirtin","wer führt calmbreeze inn"}},{q="Welche Lehrer sind im Gasthaus zu finden?",a="Im Gasthaus in Shen'dar lehrt Halassa Fernbreeze Kräuterkunde, Mendalass Tattermend Kürschnerei, Nasalanna Windsinger Verzauberkunst, und Miriann Mistblade bildet Schurken aus.",al={"calmbreeze lehrer","shen'dar gasthaus lehrer"}},{q="Was ist der Audiokristall im Obergeschoss in Valaanar?",a="Im Obergeschoss des Gasthauses in Valaanar enthält ein Audiokristall Teil drei von 'The Rebellion In Eldre'Thalas', der Ereignisse aus der uralten Stadt der Highborne schildert.",al={"valaanar audiokristall","the rebellion in eldre'thalas kristall"}}},fx={["043ce63b"]={q="Was ist das Calmbreeze Inn?",a="Das Calmbreeze Inn bezeichnet das Netzwerk von Gasthäusern, die Reisenden auf der Insel Zephras dienen, mit Standorten sowohl in Valaanar als auch im Dorf Shen'dar. Diese Einrichtungen dienen als wichtige Gemeinschaftszentren und bieten müden Reisenden einen Ort zum Ausruhen, zum Treffen von lokalen Händlern und Ausbildern sowie zum Sammeln von Neuigkeiten von der gesamten Insel.",al={"was ist das calmbreeze inn","hintergrund zum calmbreeze inn","über das calmbreeze inn"}},c8344be2={q="Ist das Calmbreeze Inn gefährlich?",a="Nein. Die Calmbreeze Inns sind friedliche Zufluchtsorte innerhalb ihrer jeweiligen Siedlungen Shen'dar und Valaanar. Sie sind voll von freundlichen Bürgern, Gastwirten und Handwerksausbildern statt von feindlichen Bedrohungen.",al={"ist das calmbreeze inn sicher","gefahren im calmbreeze inn","gefahr im calmbreeze inn"}}},fp="14,128,16.384.0,38.75.0,37.104.0,38.192.0,53.146.0"}
P.entries["subzone:camp-aparaje"] = {n="Camp Aparaje",s="Krieger der Grimmtotem halten nun Camp Aparaje in den östlichen Höhen des Steinkrallengebirges. Sie schlachteten die friedlichen Tauren ab, die dort siedelten, und beanspruchten den Außenposten für sich.",h="Krieger der Grimmtotem halten nun Camp Aparaje in den östlichen Höhen des Steinkrallengebirges.",kw={"camp aparaje","grimmtotem","posten der grimmtotem","grundig darkcloud","kaya flathoof","makaba flachhuf","steinkrallengebirge"},ang={["faction:Horde"]="Als Mitglied der Horde habt Ihr Grund, die Grimmtotem aus Rache und zur Verteidigung aus Camp Aparaje zu vertreiben. Der Stamm metzelte unschuldige Untertanen der Horde im Steinkrallengebirge nieder.",["race:Tauren"]="Als Tauren können Euch die Ruinen von Camp Aparaje an die Grausamkeit von Magathas Stamm der Grimmtotem erinnern. Nicht alle Kinder der Earth Mother teilen Cairne Bluthufs Vorstellung von Ehre und Frieden."},sec={{t="Ein tragischer Untergang",b="Friedliche Tauren lebten einst zwischen den Felsen des Steinkrallengebirges und suchten ein ruhiges Leben im Hochland. Dann schlugen Angreifer vom nahegelegenen Posten der Grimmtotem unter Grundig Darkclouds Führung zu. Die Angreifer metzelten einige Dorfbewohner nieder und vertrieben andere. Überlebende wie Makaba Flachhuf trauern um ihre verlorene Heimat und fürchten um gefangene Angehörige."},{t="Unter der Herrschaft der Grimmtotem",b="Krieger der Grimmtotem besetzen nun Camp Aparaje als vorgeschobenen Stützpunkt ihres aggressiven Stammes in der Region. Viele Siedlungen der Grimmtotem tragen blaue Markierungen, doch das große Totem hier ist tiefrot bemalt."}},faq={{q="Wer lebte früher in Camp Aparaje?",a="Friedliche Tauren der Horde und des Stammes Bloodhoof lebten in Camp Aparaje, darunter Makaba Flachhuf und seine Tochter Kaya. Sie lebten dort, bevor die Siedlung angegriffen wurde.",al={"wer lebte hier","ursprüngliche dorfbewohner von camp aparaje","makaba flachhufs dorf"}},{q="Warum ist das Lager Spielern der Horde feindlich gesinnt?",a="Die Grimmtotem nahmen das Dorf mit Gewalt ein. Der fremdenfeindliche, verräterische Klan lehnt Cairne Bluthufs Autorität ab und greift Außenstehende an, selbst Mitglieder der Horde.",al={"warum greifen tauren mich an","wer kontrolliert camp aparaje","warum ist camp aparaje rot"}},{q="Wer führte den Angriff auf Camp Aparaje an?",a="Grundig Darkcloud führte den Angriff vom Posten der Grimmtotem aus an. Der brutale Häuptling der Grimmtotem will die gewaltsame Herrschaft seines Stammes über das Steinkrallengebirge ausweiten.",al={"wer griff aparaje an","grundig darkcloud","wer ist hier der anführer"}},{q="Was geschah mit den überlebenden Dorfbewohnern?",a="Die meisten Dorfbewohner starben bei dem Überfall. Einige entkamen, während andere gefangen genommen und am nahegelegenen Posten der Grimmtotem festgehalten wurden, darunter die junge Kaya Flathoof.",al={"kaya flathoof","wo sind die überlebenden","gibt es überlebende"}}},fx={fcad7814={q="Was ist Camp Aparaje?",a="Camp Aparaje war einst eine friedliche Tauren-Siedlung, die in die östlichen Höhen des Steinkrallengebirges eingebettet war. Es diente als Heimat für ruhige Familien wie Makaba Flachhuf und seine Tochter, doch diese friedliche Existenz wurde zerstört, als gewalttätige Grimmtotem-Plünderer aus ihrer Festung herabstürmten, um das Dorf mit Gewalt einzunehmen.",al={"übersicht camp aparaje","was ist dieses lager","erzähle mir von camp aparaje"}},["358940fc"]={q="Was geschah in Camp Aparaje?",a="Feindliche Grimmtotem-Krieger starteten einen plötzlichen, brutalen Angriff auf das Dorf vom nahegelegenen Posten der Grimmtotem aus. Unter der Führung von Grundig Darkcloud vertrieben oder schlachteten die Angreifer die ansässigen Tauren ab, nahmen diejenigen gefangen, die nicht rechtzeitig entkommen konnten, und beanspruchten den Außenposten vollständig für ihren eigenen verräterischen Stamm.",al={"was passierte hier","geschichte von camp aparaje","wie wurde camp aparaje zerstört"}},["8b937e47"]={q="Wer kontrolliert Camp Aparaje jetzt?",a="Das Lager wird derzeit von besetzenden Grimmtotem-Plünderern unter dem Kommando von Grundig Darkcloud gehalten. Nachdem sie die ursprünglichen Bewohner vertrieben haben, nutzen diese feindlichen Tauren das Dorf nun als aktives Lager, unterhalten Wachposten und halten Gefangene unter Bewachung.",al={"wer lebt in camp aparaje","wer hält camp aparaje","wer ist in camp aparaje"}},["33da0239"]={q="Warum wurde Camp Aparaje von seinem ursprünglichen Volk aufgegeben?",a="Die friedlichen Dorfbewohner hatten keine Chance gegen den Überraschungsangriff der Grimmtotem. Diejenigen, die das anfängliche Massaker überlebten, wie Makaba Flachhuf, waren gezwungen, um ihr Leben in die umliegende Wildnis zu fliehen und ihre Häuser und Besitztümer zurückzulassen, damit sie von ihren Eroberern geplündert werden konnten.",al={"warum ist camp aparaje ruiniert","warum ging das dorf verloren","warum verließen die dorfbewohner es"}},["46090024"]={q="Ist Camp Aparaje gefährlich?",a="Ja. Die Siedlung ist schwer von aggressiven Grimmtotem-Kriegern besetzt, die jeden, der sich dem Lager nähert, sofort angreifen, unabhängig von Eurem Ansehen beim Rest der Horde. Wer in seine Grenzen wandert, provoziert den sofortigen Kampf mit Grundig Darkclouds abgehärteten Plünderern.",al={"ist camp aparaje sicher","gefahr in camp aparaje","bedrohungen in camp aparaje"}}},fp="12,172,17.332.0,20.199.0,33.171.0,41.162.0,36.143.0,41.140.0"}
P.entries["subzone:camp-e-thok"] = {n="Camp E'thok",s="Im Nordwesten von Tausend Nadeln drohen Karawanen unterhalb von Camp E'thok Hinterhalte. Galak-Zentauren jagen Reisende in der Schlucht.",h="Im Nordwesten von Tausend Nadeln drohen Karawanen unterhalb von Camp E'thok Hinterhalte.",kw={"camp e'thok","zentauren","ethok","galak","tausend nadeln","wizlo lagerputzer"},ang={["race:Tauren"]="Als Tauren erinnert Ihr Euch vielleicht an den Krieg Eurer Vorfahren gegen die Zentauren im gesamten südlichen Kalimdor, wenn Ihr die Angriffslust der Galak-Zentauren in Camp E'thok seht."},sec={{t="Eine Hochburg der Galak",b="Galak-Zentauren jagen Reisende in der Schlucht bei Camp E'thok. Ihr Lager liegt im Nordwesten von Tausend Nadeln. Von dort aus überfällt der Klan Händlerkarawanen, die das Flussbett unterhalb des Lagers durchqueren. Mit einer Karawane reiste der Goblin Wizlo Lagerputzer. Die Zentauren raubten ihre Waren, doch Wizlos wilder Haustierpanther hielt sein kostbares Gerät außerhalb ihrer Reichweite."}},faq={{q="Wer lebt in Camp E'thok?",a="Der Zentaurenklan der Galak lebt in Camp E'thok. Der aggressive Stamm beherrscht Teile des Nordwestens von Tausend Nadeln.",al={"wer ist in camp ethok","camp ethok bewohner","wer kontrolliert camp ethok"}},{q="Was geschah hier mit Wizlo Lagerputzer?",a="Galak-Zentauren aus Camp E'thok überfielen Wizlo Lagerputzers Karawane und raubten ihre Waren. Sein kostbares Gerät konnten sie nicht erbeuten, da es am Halsband seines wilden Haustierpanthers befestigt war.",al={"wizlo lagerputzer überfall","goblinkarawane angegriffen","was stahlen die zentauren wizlo"}},{q="Wo liegt Camp E'thok?",a="Camp E'thok liegt im Nordwesten von Tausend Nadeln am Fuß der Schluchtwände.",al={"camp ethok lage","wo liegt camp ethok","camp ethok karte"}}},fx={["740a44e0"]={q="Was ist Camp E'thok?",a="Camp E'thok ist ein aktives Lager des Zentaurenstammes der Galak, das sich in den Schluchten des nordwestlichen Tausend Nadeln angesiedelt hat. Die Zentauren nutzen diesen befestigten Ort als Basis, um gewaltsame Hinterhalte und Überfälle auf Reisende und Handelskarawanen zu inszenieren, die durch die darunter liegenden Schluchten ziehen.",al={"was ist camp e'thok","hintergrund zu camp e'thok","erzähle mir von camp e'thok"}},["7ec291b4"]={q="Ist Camp E'thok gefährlich?",a="Camp E'thok ist extrem gefährlich. Die hier hausenden Galak-Zentauren greifen Außenstehende bei Sichtkontakt an und fallen über Handelskarawanen her, die es wagen, die Schlucht zu durchqueren. Jeder, der in das Lager wandert, sieht sich feindlichen Kriegern, Schamanen und der Beute gegenüber, die sie gewaltsam zusammengetragen haben.",al={"ist camp e'thok feindlich","wie gefährlich ist camp e'thok","gefahr camp e'thok"}}},fp="11,117,18.341.0,25.118.0,42.183.0,29.85.0"}
P.entries["subzone:camp-kosh"] = {n="Camp Kosh",s="Bei Camp Kosh überfallen Dustbelcher-Oger Karawanen, die den Norden des Ödlands durchqueren. Sie plündern zurückgelassene Ausrüstung auf den Straßen nach Kargath und zur Sengenden Schlucht.",h="Bei Camp Kosh überfallen Dustbelcher-Oger Karawanen, die den Norden des Ödlands durchqueren.",kw={"ödland","camp kosh","dustbelcher","oger","sigrun ironhew","uldaman"},ang={["faction:Alliance"]="Späher der Allianz auf der nördlichen Route zur Sengenden Schlucht müssen sich vor den Ogern von Camp Kosh in Acht nehmen. Sie überfallen vorbeiziehende Versorgungskarawanen.",["race:Dwarf"]="Sigrun Ironhews Zwergenexpedition ließ Rationen und Waffen zurück, als sie aus Uldaman floh. Die Oger von Camp Kosh nahmen sie mit."},sec={{t="Ein Schlupfwinkel der Plünderer",b="Im Norden des Ödlands haben die Dustbelcher-Oger ihr nördlichstes Lager in Camp Kosh aufgeschlagen. Ihr Stamm hält auch die nahe gelegenen Lager Boff, Cagg und Wurg. Von diesen Lagern aus greifen sie verwundbare Nachschublinien an, die nach Kargath oder westwärts in die Sengende Schlucht führen. Als die zwergischen Prospektoren unter Sigrun Ironhew von der Ausgrabung bei Uldaman flohen, plünderten die Oger ihre zurückgelassenen Wagen. Sie trugen Nahrungsrationen und Waffen zurück nach Camp Kosh."}},faq={{q="Wer lebt in Camp Kosh?",a="In Camp Kosh leben Dustbelcher-Oger, deren Stamm mehrere kleine Lager im Ödland hält.",al={"camp kosh gegner","wer ist in camp kosh","oger camp kosh"}},{q="Warum liegt Camp Kosh hier?",a="Von Camp Kosh im nördlichen Ödland aus können Dustbelcher-Oger Versorgungskarawanen und unachtsamen Reisenden auf dem Weg zur Sengenden Schlucht oder nach Kargath auflauern.",al={"warum camp kosh","camp kosh lage"}},{q="Was haben die Oger den Zwergen gestohlen?",a="Als Sigrun Ironhews Zwergenexpedition aus Uldaman floh, ließ sie Versorgungswagen in der Wüste zurück. Die Oger von Camp Kosh plünderten daraus Kisten mit Nahrung und Waffen.",al={"zwergenvorräte camp kosh","sigrun ironhew vorräte","uldaman wagen"}}},fp="9,166,19.444.0,23.102.0,30.151.0,42.166.0"}
P.entries["subzone:camp-mojache"] = {n="Camp Mojache",s="In Camp Mojache hält die Horde einen Stützpunkt im östlichen Feralas an dem Bach, der den Wildwindsee speist. Der Außenposten der Tauren bietet Vorräte und Flugverbindungen inmitten gefährlicher Wildtiere und uralter Ruinen.",h="In Camp Mojache hält die Horde einen Stützpunkt im östlichen Feralas an dem Bach, der den Wildwindsee speist.",kw={"krieger","camp mojache","feralas","flugmeister","gordunni","tauren","wildwindsee","woodpaw"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr Euch auf Mojache als einzigen befestigten Knotenpunkt in Feralas für Rast, Vorräte und schnelle Reisen durch den dichten Wald verlassen.",["race:Tauren"]="Als Tauren findet Ihr Camp Mojache am südlichsten Rand der Verbreitung traditioneller Handwerkskunst und Siedlungen Eures Volkes in Kalimdor. Hier schafft Euer Volk Harmonie im dichten Regenwald."},sec={{t="Eine Taurenbastion im Regenwald",b="Im östlichen Feralas bietet Camp Mojache Reisenden der Horde Schutz an dem Bach, der den Wildwindsee speist. Dichter Wald umgibt das Lager, und in der Nähe leben wilde Tiere, Gordunni-Oger und Woodpaw-Gnolle. Unterkünfte, Handelswaren und ein Wind Rider-Horst versorgen Reisende, die die Region durchqueren."},{t="Außenposten im Grenzland",b="Jäger und Krieger der Tauren halten nach Angriffen aus der Wildnis Ausschau. Mojache zu halten, erweitert den Einfluss der Horde in Feralas, wo Nachtelfen die Küste halten und finstere Mächte im Düsterbruch lauern."}},faq={{q="Was ist Camp Mojache?",a="Camp Mojache ist der Hauptstützpunkt der Horde in Feralas. Vor allem Tauren haben es an dem Bach erbaut, der in den Wildwindsee mündet, und unterhalten es mit Unterkünften, Handelswaren und Flugtransport.",al={"camp mojache zweck","was ist dieses lager","taurensiedlung feralas"}},{q="Wer führt oder verteidigt das Lager?",a="Erfahrene Krieger der Tauren verteidigen Camp Mojache gegen heimische Wildtiere, Gordunni-Oger und Woodpaw-Gnolle, die durch die Hügel unmittelbar südlich des Lagers streifen.",al={"camp mojache wachen","wer verteidigt mojache","wer leitet camp mojache"}},{q="Wohin fliegt der örtliche Flugmeister?",a="Vom Wind Rider-Horst in Camp Mojache könnt Ihr nach Donnerfels, zum Wegekreuz im Brachland, nach Schattenflucht in Desolace und ins nahe Gadgetzan in Tanaris fliegen.",al={"camp mojache flugrouten","wohin kann man von camp mojache fliegen"}},{q="Welche großen Bedrohungen umgeben Camp Mojache?",a="Woodpaw-Gnolle leben in den Wäldern im Süden, während Gordunni-Oger im Norden und Süden umherstreifen. Truppen der Allianz operieren von der Mondfederfeste an der fernen Westküste aus.",al={"feralas gefahren camp mojache","bedrohungen nahe camp mojache","feinde nahe mojache"}}},fp="12,209,34.290.0,16.194.0,21.194.0,30.136.0,42.163.0,41.179.0"}
P.entries["subzone:camp-narache"] = {n="Camp Narache",s="In Camp Narache beginnen junge Tauren ihre Ausbildung, hoch auf der Hochwolkenebene im südlichen Mulgore. Es ist die angestammte Heimat des Hawkwind-Stammes. Hier oben, über den Ebenen, werden die alten Traditionen bewahrt. Doch das Lager muss stets gegen die Stacheleber und die Zentauren auf der Hut sein.",h="In Camp Narache beginnen junge Tauren ihre Ausbildung, hoch auf der Hochwolkenebene im südlichen Mulgore.",kw={"borstennacken","großmutter falkenwind","hawkwind","mulgore","narache","die hochwolkenebene","geistzelt","tauren"},ang={["class:Shaman"]="Als junger Schamane macht Ihr hier Eure ersten Schritte auf dem spirituellen Pfad und besteht Prüfungen, um Euer Erdtotem zu verdienen und mit den Elementaren der Hochebene zu sprechen.",["race:Tauren"]="Als Tauren beginnt Ihr auf dieser heiligen Erde Eure Jagdriten und stimmt Euch unter der Aufsicht der Hawkwind-Ältesten auf die Ahnengeister ein."},sec={{t="Herz des Hawkwind-Stammes",b="Das Lager liegt am nördlichen Rand der Hochebene, ein Dorf aus großen Lederhütten und Pavillons. Es gibt ein Zelt für verwundete Krieger und eine Hütte für die Zwiesprache mit den Ahnen. In seiner Mitte stehen die Stammesältesten und Ausbilder im Kreis. Unter ihnen ist die ehrwürdige Großmutter Falkenwind. Sie leitet die Jungen noch immer an, während sie ihren Platz als Verteidiger der Erdenmutter einnehmen."},{t="Eine Prüfungsstätte in Gefahr",b="Die steilen Klippen der Hochebene bilden eine natürliche Festung, doch das Lager kennt wenig Frieden. Stacheleber der Borstennacken dringen aus der Dornrankenklamm vor, und Zentaurenspäher lauern in der Ferne. Hier beweisen junge Jäger, Schamanen, Druiden und Krieger ihren Mut. Sie dünnen die aggressive Tierwelt aus, bewachen den Dorfbrunnen und schlagen die Überfälle der Stacheleber zurück. Dann steigen sie den großen Pfad hinab, in die weiten Täler von Mulgore."}},faq={{q="Was ist Camp Narache?",a="Junge Tauren beginnen ihre Ausbildung in Camp Narache, auf der Hochwolkenebene im südlichen Mulgore. Das Lager ist die Hauptsiedlung des Hawkwind-Stammes, wo Jäger, Krieger, Druiden und Schamanen ihr Handwerk erlernen, bevor sie zum Dorf der Bluthufe und nach Donnerfels reisen. In den Hütten werden Waffen gelagert und Brot gebacken.",al={"was ist camp narache","narache geschichte","startdorf der tauren"}},{q="Wer führt das Dorf?",a="Großmutter Falkenwind leitet den Stamm gemeinsam mit Häuptling Falkenwind, der die Krieger anführt und die Verteidigung der Hochebene koordiniert. Die Ältesten und Ausbilder versammeln sich in der Mitte des Lagers, um die Jungen zu unterweisen.",al={"wer führt camp narache","häuptling von camp narache","anführer der hawkwind"}},{q="Welche Gefahren bedrohen das Lager?",a="Stacheleber der Borstennacken aus der Dornrankenklamm im Osten bedrängen das Lager. Battleboars und Schreiter durchstreifen die umliegenden Anhöhen, und Zentaurenbanden bleiben eine Bedrohung.",al={"feinde von camp narache","wer greift camp narache an","gefahren auf der hochebene"}},{q="Können Reisende die Hochebene leicht verlassen?",a="Steile Klippen begrenzen die Hochwolkenebene, und ein bewachter Bergpfad führt nach Norden in die Ebenen von Mulgore. Krieger der Hawkwind bewachen den Weg, damit feindselige Tiere und Stacheleber Reisenden nicht auflauern können.",al={"hochwolkenebene verlassen","ausgang aus camp narache","pfad von der hochebene hinab"}}},fx={["017769ab"]={q="Was geschah in Camp Narache?",a="Camp Narache wurde als geschützte Heimat für den Stamm der Falkenwind auf den erhöhten Höhen der Hochwolkenebene gegründet. Über Generationen entwickelte es sich von einem einfachen Versammlungsort des Stammes zum wichtigsten Prüfungsort für junge Tauren in ganz Mulgore. Geschützt durch steile Klippen und natürliche Wälle, ermöglichte das Lager es angehenden Jägern, Schamanen und Kriegern, ihre traditionellen Riten fernab der heftigen Zentaurenüberfälle zu absolvieren, die die offenen Ebenen darunter plagten.",al={"geschichte von camp narache","was passierte hier"}},de5ddd4a={q="Wer lebt in Camp Narache?",a="Camp Narache ist das Hauptdorf des Stammes der Falkenwind, angeführt von Häuptling Falkenwind und seiner älteren Mutter, Großmutter Falkenwind. Neben Stammeskriegern, Händlern und Handwerkern versammeln sich hier Mentoren aus allen Tauren-Traditionen. Schamanen, Druiden, Krieger und Jäger wohnen in den Fellhütten des Lagers, um junge Tauren auszubilden, die angekommen sind, um ihre Prüfungen zum Erwachsenwerden abzulegen.",al={"wer lebt in camp narache","bewohner von camp narache","wer lebt hier"}},["452dc8d4"]={q="Ist Camp Narache gefährlich?",a="Die Siedlung selbst ist friedlich und wird von Falkenwind-Kriegern gut bewacht, aber die umliegende Ebene ist zunehmend gefährlich. Aggressive Bergpumas und territoriale Kampfkeiler streifen an den Grenzen umher, während eine wachsende Population von Borstennacken-Stachelebern in die nahegelegene Schlucht eingedrungen ist. Während man innerhalb des Umkreises der Hütten sicher ist, bringt ein weites Wandern von den Lagerfeuern aus unmittelbare Gefahr für unerfahrene Jugendliche.",al={"ist camp narache sicher","wie gefährlich ist camp narache","gefahr in camp narache"}},["602085f2"]={q="Ist das der Ort, an dem alle Tauren anfangen?",a="Ja. Hoch auf den geschützten Klippen der Hochwolkenebene gelegen, dient Camp Narache als das primäre Ausbildungslager für alle jungen Tauren. Bevor Ihr als vertrauenswürdig gilt, in die weiteren Täler von Mulgore zu reisen oder dem Häuptling in Donnerfels zu dienen, müsst Ihr hier unter den wachsamen Augen der Ältesten Eure Stärke, Weisheit und Euren Respekt vor der Natur beweisen.",al={"fangen alle tauren hier an","startgebiet der tauren","warum fangen tauren hier an"}},e8115520={q="Wer hat Camp Narache erbaut?",a="Das Lager wurde vom Stamm der Falkenwind als ihr Stammesdorf auf der Hochwolkenebene gegründet. Hauptsächlich mit robusten Lederzelten, geschnitzten Totems und natürlichem Holz erbaut, wurde es nach traditionellen nomadischen Techniken entworfen, obwohl es als dauerhaftes Zentrum für Stammesversammlungen und die Bildung der Tauren-Jugend Bestand hat.",al={"wer erbaute camp narache","ursprung von camp narache","wer gründete camp narache"}},["9d2ccac7"]={q="Ist Häuptling Falkenwind wichtig für die Tauren?",a="Häuptling Falkenwind ist der Anführer des Stammes der Falkenwind und der Aufseher der Hochwolkenebene. Während er das Lager regiert und die Verteidigung gegen die Borstennacken leitet, besteht seine wichtige kulturelle Rolle darin, neu erwachte Krieger durch ihre frühen Prüfungen zu führen, bevor sie in den Dienst der vereinten Stämme treten.",al={"rolle von häuptling falkenwind","wer ist häuptling falkenwind","bedeutung von häuptling falkenwind"}},["5c34accd"]={q="Steht Häuptling Falkenwind jemand anderem gegenüber in der Verantwortung?",a="Ja. Wie alle Stammeshäuptlinge in Mulgore erkennt Häuptling Falkenwind Cairne Bluthuf als den Oberhäuptling der vereinten Taurenstämme an. Über Cairne hinaus haben die Tauren ihre Loyalität gegenüber Kriegshäuptling Thrall und der größeren Horde geschworen, obwohl die tägliche Verwaltung des Lagers in Falkenwinds Händen bleibt.",al={"wem untersteht häuptling falkenwind","vorgesetzte von häuptling falkenwind","wer regiert über falkenwind"}},["4397ed07"]={q="Was sind die Borstennacken und warum greifen sie uns an?",a="Die Borstennacken sind ein wilder Stamm von Stachelebern, die die Felsen und dornigen Dickichte der Ebene bewohnen. Sie sind stark territorial und verzweifelt auf der Suche nach Ressourcen und betrachten die Tauren-Siedlungen als Eindringen in ihre Futterplätze. Ermutigt durch ihre Häuptlinge haben sie begonnen, die Nachschubwege der Tauren zu überfallen und Camp Narache direkt zu bedrohen.",al={"warum greifen die borstennacken an","borstennacken stacheleber","wer sind die borstennacken"}},["35bda353"]={q="Was ist die Dornrankenklamm?",a="Die Dornrankenklamm ist ein zerklüfteter, von Dornenranken überwucherter Canyon am nordöstlichen Rand der Hochwolkenebene. Er dient als primärer Unterschlupf und Festung der Borstennacken-Stacheleber in dieser Region und beherbergt ihre Kampfkeiler sowie ihren Häuptling, Sharptusk Thornmantle.",al={"dornrankenklamm","wo ist die dornrankenklamm","über die dornrankenklamm"}},["7ff27be4"]={q="Wer ist die Erdenmutter?",a="Die Erdenmutter ist die gütige Schöpfergottheit, die von den Tauren über alles andere verehrt wird. Die Tradition der Tauren lehrt, dass sie die Welt gebar, den Ländern Leben einhauchte und ihr Volk erschuf, damit es in Einklang mit der Wildnis lebe. Ihr Wille leitet ihre spirituellen Praktiken, schamanistischen Rituale und die Ehrfurcht vor der Natur.",al={"wer ist die erdenmutter","erdenmutter-lore","tauren erdenmutter"}},d26e5d41={q="Was ist Mulgore?",a="Mulgore ist die angestammte Heimat der Tauren – eine weite, grüne Ausdehnung aus windgepeitschten Graslandebenen, sanften Hügelländern und hoch aufragenden Plateaus. An allen Seiten von unpassierbaren Bergwällen umgeben, beherbergen ihre fruchtbaren Täler umherstreifende Kodo-Bestien, Wölfe und die permanente Taurenhauptstadt Donnerfels.",al={"was ist das land mulgore","über mulgore","mulgore-lore"}},["2ba66ce3"]={q="Warum siedelten sich die Tauren in Mulgore an?",a="Über Generationen hinweg zwangen brutale Zentaurenplünderer die Tauren in ein umherziehendes, nomadisches Dasein durch das Brachland. Nachdem sie sich mit Kriegshäuptling Thrall und der The New Horde zusammengeschlossen hatten, um die Zentauren aus der Region zu vertreiben, führte der Hohe Häuptling Cairne Bluthuf sein Volk dazu, sich dauerhaft in den üppigen, gut zu verteidigenden Tälern ihrer angestammten Heimat niederzulassen.",al={"warum leben tauren in mulgore","warum kamen tauren nach mulgore","besiedlung von mulgore"}},b543a978={q="Ist Mulgore sicher?",a="Obwohl es auf natürliche Weise befestigt und im Vergleich zum Brachland friedlich ist, ist Mulgore nicht ohne Gefahren. Feindselige Palemane-Gnolle, Windfury-Harpyien, aggressive Stacheleber und opportunistische Goblin-Bergleute der Venture Company stören kontinuierlich den Frieden, was die Tauren dazu zwingt, wachsam zu bleiben.",al={"ist mulgore gefährlich","wie sicher ist mulgore","bedrohungen in mulgore"}},["2e7cb737"]={q="Was ist das Dorf der Bluthufe?",a="Das Dorf der Bluthufe ist eine zentrale Siedlung der Tauren am Ufer des Stonebullsee im mittleren Mulgore. Sie dient als wichtiger Handels- und Kulturknotenpunkt zwischen den Proving Grounds der Hochwolkenebene und den luftigen Höhen von Donnerfels.",al={"über bloodhoof","wo ist bloodhoof","was ist bloodhoof"}},["8b10e970"]={q="Was ist die Hochwolkenebene?",a="Die Hochwolkenebene ist ein hohes, geschütztes Plateau, das sich über das südliche Mulgore erhebt. Flankiert von steilen Klippen, die die meisten Raubtiere und Eindringlinge aus dem Tiefland fernhalten, beherbergt die Ebene das Camp Narache und dient als abgeschiedene Ausbildungsstätte für alle jungen Tauren.",al={"die hochwolkenebene","was ist diese ebene","über die hochwolkenebene"}},dff4694b={q="Was ist Donnerfels?",a="Donnerfels ist die prächtige Hauptstadt der Tauren, die hoch oben auf einer Reihe von windgeformten Plateaus im nördlichen Mulgore thront. Verbunden durch hängende Seilbrücken und erreichbar über riesige Holzaufzüge, wurde sie von Hoher Häuptling Cairne Bluthuf als vereintes Heiligtum für alle Taurenstämme gegründet.",al={"was ist donnerfels","über donnerfels","taurenhauptstadt"}},["51c45aa6"]={q="Wann schlossen sich die Tauren der Horde an?",a="Die Tauren verbündeten sich während des Dritter Krieg mit der Horde, kurz nachdem Thrall und seine Orks auf Kalimdor landeten. In der Erkenntnis einer gemeinsamen spirituellen Ehre und Verbundenheit half Thrall Cairne Bluthuf dabei, seine Karawane vor Überfällen der Zentauren zu verteidigen, was eine dauerhafte Freundschaft festigte, die die Tauren in die The New Horde brachte.",al={"beitritt der tauren zur horde","wie schlossen sich tauren der horde an","wann trafen tauren auf thrall"}},["6d7e8195"]={q="Wie bin ich im Camp Narache gelandet?",a="Ihr seid auf die abgeschiedenen Höhen der Hochwolkenebene zum Camp Narache gekommen, um zu trainieren und Euch unter dem Stamm der Hawkwind zu beweisen. Während das untere Flachland von Mulgore nur durch einen befestigten Pass erreicht werden kann, versammeln sich junge Tauren in diesem geschützten Zufluchtsort, um ihre Fähigkeiten unter dem wachsamen Auge der Stammesältesten und Klassenlehrer zu meistern, bevor sie sich in die weite Welt hinauswagen.",al={"wie kam ich hierher","wie bin ich hier gelandet","warum bin ich im camp narache"}},ccbc2a7d={q="Was soll ich im Camp Narache tun?",a="Eure Pflicht ist es, Häuptling Falkenwind und den Ältesten des Lagers zu helfen, während Ihr die Riten Eures Pfades erlernt. Die Hochwolkenebene ist ständigen Belästigungen durch aggressive Borstennacken-Stacheleber, die in der Dornrankenklamm lauern, und Bergkugeln, die auf dem Plateau schleichen, ausgesetzt. Indem Ihr die Siedlung verteidigt, verwundeten Kriegern helft und heilige Rituale für die Erdenmutter vollzieht, werdet Ihr das Recht verdienen, ins Dorf der Bluthufe hinabzusteigen und der Horde zu dienen.",al={"was mache ich hier","was ist mein ziel hier","warum bin ich hier"}},["74e7cbb8"]={q="Warum startet ein neuer Taure hier, im Camp Narache?",a="Camp Narache ist die angestammte Ausbildungsstätte, in der junge Tauren ihre ersten Schritte in Richtung Erwachsensein machen. Sicher hoch oben auf der Hochwolkenebene gelegen, fernab von den umherstreifenden Zentauren und äußeren Bedrohungen, die das zentrale Kalimdor heimsuchen, bietet es einen sicheren Zufluchtsort. Hier führen die Ältesten und Ausbilder des Stammes der Hawkwind neue Krieger in die Jagd, die Ehrung der Geister und das Verteidigen der neuen Heimat ein, die Cairne Bluthuf für Euer Volk gesichert hat.",al={"warum starten tauren hier","warum in camp narache starten","warum ist das das tauren-startgebiet"}}},fp="12,280,27.381.0,29.413.0,21.305.0,22.200.0,32.163.0,36.191.0"}
P.entries["subzone:camp-taurajo"] = {n="Camp Taurajo",s="In Camp Taurajo finden Reisende Schutz und einen Weg nach Westen nach Mulgore. Das Taurenlager bietet Vorräte, Lehrmeister und Windreiterverbindungen über die Ebenen und durch das zentrale Kalimdor.",h="In Camp Taurajo finden Reisende Schutz und einen Weg nach Westen nach Mulgore.",kw={"brachland","dorf der bluthufe","camp taurajo","mulgore pass","südliches brachland","taurajo","taurenaußenposten"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr über Camp Taurajos Wegkreuzung und Flugverbindung Mulgore und das übrige zentrale Kalimdor unter der Herrschaft der Horde erreichen.",["race:Tauren"]="Wenn Ihr als Tauren Mulgore zum ersten Mal verlasst, findet Ihr in Camp Taurajo Eure erste freundliche Zuflucht auf den unwirtlichen Ebenen des Brachlands."},sec={{t="Grenze der Teufelsfelsen",b="Von Camp Taurajo aus könnt Ihr den Pass nach Westen nach Mulgore nehmen. Für junge Tauren, die das Dorf der Bluthufe verlassen, bietet das Lager oft den ersten Blick auf das weite Brachland. Trockenes Buschland und schroffe Tafelberge umgeben diesen Außenposten und Handelsknotenpunkt. Jäger, Lederer und Kräuterkundige auf Wanderschaft finden hier Schutz. Windreiter bringen Reisende nach Donnerfels, zum Wegekreuz und zum Freiwindposten weiter im Süden."}},faq={{q="Was ist Camp Taurajo?",a="Camp Taurajo ist eine Taurensiedlung und ein Außenposten im südlichen Brachland, zwischen Mulgore und dem trockenen Buschland.",al={"camp taurajo überblick","was ist taurajo","taurajo geschichte"}},{q="Wohin führt der Weg nach Westen?",a="Der unbefestigte Pfad westlich von Camp Taurajo führt über den Gebirgspass nach Mulgore, in Richtung Dorf der Bluthufe und Donnerfels.",al={"taurajo westlicher pass","weg westlich von camp taurajo","pfad nach mulgore"}},{q="Wohin fliegen die Windreiter von Camp Taurajo?",a="Windreiter fliegen von Camp Taurajo nach Norden zum Wegekreuz, nach Westen nach Donnerfels und nach Süden zum Freiwindposten in Tausend Nadeln.",al={"taurajo flugmeister","taurajo flugrouten","flugverbindungen taurajo"}}},fx={["9a32993c"]={q="Ist Camp Taurajo gefährlich?",a="Das Lager selbst ist eine sichere Siedlung, die von tapferen Tauren beschützt wird, doch die umliegende Wildnis des südlichen Brachlands ist tückisch. Aggressive Stacheleberstämme streiten um das nahe Buschland, während umherstreifende Bestien und Raubtiere jeden weiten Abstecher von der Straße zu einem gefährlichen Wagnis machen.",al={"ist camp taurajo sicher","gefahren nahe camp taurajo","bedrohungen rund um taurajo"}}},fp="12,173,25.394.0,21.113.0,30.121.0,47.132.0"}
P.entries["subzone:camp-wurg"] = {n="Camp Wurg",s="Dustbelcher-Oger halten Camp Wurg zwischen den schroffen Felsen des Ödlands. Ihre Lager erstrecken sich über weite Teile der unwirtlichen Region.",h="Dustbelcher-Oger halten Camp Wurg zwischen den schroffen Felsen des Ödlands.",kw={"ödland","boss tho'grun","camp boff","camp cagg","camp kosh","camp wurg","dustbelcher","oger","wurg"},sec={{t="Eine Hochburg der Dustbelcher",b="Dustbelcher-Oger bewachen Camp Wurg zwischen den schroffen Felsen des Ödlands. Es ist neben Camp Cagg, Camp Boff und Camp Kosh eines ihrer vier Hauptlager. Die Oger suchen im Wüstenödland nach Verwertbarem und verteidigen ihr zerklüftetes Gebiet erbittert. Schläger und Vollstrecker versammeln sich um primitive Feuer und grobe Tierhäute. Boss Tho'grun, ihr Häuptling, hat keinen festen Sitz in Wurg. Er durchstreift die Pfade des Ödlands und wacht über alle vier Lager."}},faq={{q="Wer lebt in Camp Wurg?",a="Dustbelcher-Oger leben in Camp Wurg, einer ihrer Siedlungen im Ödland.",al={"camp wurg gegner","wer ist in camp wurg","wer lebt hier"}},{q="Wo ist der Anführer des Lagers?",a="Boss Tho'grun, Häuptling der Dustbelcher-Oger, durchstreift die Pfade des Ödlands zwischen Camp Wurg, Camp Cagg, Camp Boff und Camp Kosh.",al={"camp wurg boss","boss thogrun aufenthaltsort","wer führt camp wurg"}},{q="Welche anderen Lager gehören diesem Stamm?",a="Die Dustbelcher-Oger halten vier Hauptlager im Ödland: Camp Wurg, Camp Cagg, Camp Boff und Camp Kosh.",al={"dustbelcher lager","andere ogerlager ödland","ogersiedlungen ödland"}}},fp="9,109,24.414.0,23.82.0,32.132.0,38.107.0"}
P.entries["subzone:canals-stormwind-city"] = {n="Kanäle",s="Spaziergänger und Angler teilen sich die Wege an Sturmwinds Kanälen, die sich zwischen den Stadtvierteln winden.",h="Spaziergänger und Angler teilen sich die Wege an Sturmwinds Kanälen, die sich zwischen den Stadtvierteln...",kw={"kanalviertel","kanäle","krokilisk","gallina","kanalisation","verlies","sturmwind","wasserwege"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr sehen, wie Sturmwinds Kanäle nach den Verwüstungen des Ersten Krieges wiederhergestellt wurden und die Hauptstadt zu einer funktionierenden, malerischen Stadt wurde.",["profession:Cooking"]="Als angehender Koch könnt Ihr an den ruhigen Kanalufern angeln, sicher innerhalb der Mauern der Hauptstadt."},sec={{t="Die Adern der Hauptstadt",b="Ihr könnt den Kanälen von den Märkten des Handelsdistrikts bis zu den alten Gassen der Altstadt, den Kathedralengärten und dem Zwergendistrikt folgen. Steinbrücken und Torbögen überspannen das Wasser, während Wege am Weingut Gallina, an Schneidereien und stillen Wohnhäusern vorbeiführen. Händler und Fischer nutzen diese Wasserwege. Unter den Straßen hält der befestigte Eingang zum Verlies Sturmwinds gefährlichste Verbrecher und Rebellen gefangen."},{t="Grausige Vergangenheit, lauernde Schatten",b="Die Horde brandschatzte Sturmwind während des Ersten Krieges und hinterließ die Kanäle in Trümmern. Die Wasserwege wurden wiederhergestellt, als die Hauptstadt nach dem Zweiten Krieg neu erstand. Heute sind sie sauber und instand gesetzt, doch Gerüchte berichten von einem riesigen Albino-Krokilisken unter den Stegen."}},faq={{q="Was geschah während des Ersten Krieges mit den Kanälen?",a="Die Horde brandschatzte Sturmwind während des Ersten Krieges und hinterließ die Stadt und ihre Wasserwege in Trümmern. Die Kanäle wurden wiederhergestellt, als die Hauptstadt nach dem Zweiten Krieg wiederaufgebaut wurde.",al={"geschichte der kanäle","kanäle erster krieg","sturmwind brandschatzung kanäle"}},{q="Gibt es wirklich ein Ungeheuer in Sturmwinds Kanälen?",a="Niemand kann es mit Sicherheit sagen. Gerüchte erzählen von einem riesigen weißen Krokilisken, der in den Wasserwegen lauert, doch Wachen und Bewohner tun die Geschichten oft als Tavernengeschwätz ab. Es gibt weiterhin Berichte, und Abenteurer werden davor gewarnt, hineinzufallen.",al={"sturmwind krokodil","kanal alligator","kanalisationsbestie","weißer krokilisk"}},{q="Wo befindet sich der Eingang zum Verlies?",a="Der Eingang zum Verlies liegt am nördlichsten Abschnitt des Kanals rund um das Magierviertel und wird von der Sturmwind City Guard bewacht.",al={"wo ist das verlies","eingang zum verlies","wie kommt man zum verlies"}},{q="Können Spieler durch die Kanäle schwimmen, um sich in Sturmwind fortzubewegen?",a="Ihr könnt durch die Kanäle schwimmen und dann über Steintreppen oder Stege entlang der Uferwege wieder zur Straße hinaufsteigen.",al={"schwimmen in den kanälen","sturmwind auf dem wasser bereisen","wasserweg sturmwind"}}},fx={["8ec6c1e0"]={q="Was sind die Kanäle?",a="Die Kanäle sind ein weitläufiges Netzwerk aus Wasserwegen und gepflasterten Steinufern, die sich durch ganz Sturmwind ziehen und die wichtigsten Stadtviertel voneinander trennen. Während sie primär als Wasserwege und Durchgangsstraßen dienen, sind ihre Stege und Anlegestellen von kleinen Läden, Schneidereien und Angelplätzen gesäumt. Die Kanäle bieten zudem Zugang zum gesicherten Eingang der Sturmwind Stockade.",al={"was sind die kanäle","sturmwind kanäle hintergrundgeschichte","kanalviertel"}},["74e84108"]={q="Sind die Kanäle gefährlich?",a="Größtenteils sind die Kanäle sicher und werden viel von Stadtbewohnern, Ladenbesitzern und örtlichen Anglern genutzt. Dennoch solltet Ihr am Wasser auf Euren Schritt achten. Unter den Einheimischen halten sich hartnäckig Gerüchte über einen monströsen Albino-Krokolisken, der unter der Oberfläche lauert und für jeden, der unvorsichtig genug ist hineinzufallen, eine echte Bedrohung darstellt.",al={"ist es sicher in den kanälen","kanal gefahr","kanäle gefährlich"}}},fp="10,100,23.400.0,38.255.0,49.169.0,50.225.0,46.127.0,63.114.0"}
P.entries["subzone:canals-undercity"] = {n="Kanäle",s="In Unterstadt füllt grüner Schleim die Kanäle zwischen den Vierteln. Die trüben Rinnen führen Abfälle und prägen die unterirdische Festung der Verlassenen.",h="In Unterstadt füllt grüner Schleim die Kanäle zwischen den Vierteln.",kw={"kanäle","angeln","verlassene","grüner schleim","lordaeron","schlamm","giftig","unterstadt"},ang={["class:Shaman"]="Als Schamane stellt Ihr fest, dass die Elemente wenig Macht über den verschmutzten Morast in Unterstadts Wasserwegen haben. Gewöhnliche Zauber wie Wasserwandeln versagen dort.",["race:Undead"]="Den Verlassenen schaden die üblen Kanäle nicht an ihren untoten Körpern. Sie führen chemische Abwässer durch das unterirdische Reich und dienen als Graben."},sec={{t="Ein giftiger Graben",b="Unter den Ruinen von Lordaeron füllt grüner Schlamm die Kanäle. Die steinernen Rinnen umschließen Unterstadt und trennen ihre Viertel voneinander. Sie führen Industrieabfälle, chemische Abwässer und alchemistischen Müll statt fließenden Wassers. Schwaches Licht schimmert durch die Flüssigkeit, und üble Dämpfe steigen daraus auf. Wasserwandeln kann niemanden hinübertragen. Dennoch ziehen verzweifelte Angler manchmal seltsame, verseuchte Kuriositäten aus dem Morast."}},faq={{q="Was ist die grüne Flüssigkeit in den Kanälen?",a="Die grüne Flüssigkeit ist alchemistischer Schlamm aus giftigen Abwässern, Nebenprodukten der Seuche und Industrieabfällen, die sich in Unterstadts Abflüssen sammeln. Anders als sauberes Wasser ist sie verseucht und giftig.",al={"unterstadt grünes wasser","was ist der schleim in unterstadt","grüner schleimfluss"}},{q="Kann man in Unterstadts Kanälen angeln?",a="Ja. Geduldige Angler können ihre Leinen im Schlamm auswerfen und manchmal kränkliche, verseuchte Fische oder weggeworfenen Plunder herausziehen. Darunter sind alte Menschenschädel aus Lordaerons untergegangener Vergangenheit.",al={"angeln unterstadt","kann man hier angeln","angeln im grünen schleim"}},{q="Warum funktioniert Wasserwandeln auf den Kanälen nicht?",a="Die dicke chemische Brühe verhält sich nicht wie natürliches Wasser. Ihre üble, zähflüssige Beschaffenheit hindert Schamanen und andere Zauberwirker daran, gewöhnliche Wasserwandelmagie darauf anzuwenden.",al={"wasserwandeln unterstadt","schamane wasserwandeln fehler","warum funktioniert wasserwandeln in unterstadt nicht"}}},fx={dc46e6d3={q="Was sind die Kanäle in der Unterstadt?",a="Die Kanäle sind die versunkenen Wasserwege, die sich zwischen den verschiedenen Vierteln der Unterstadt winden. Diese tiefen Steinkanäle fließen in einer breiten kreisförmigen Schleife durch die unterirdische Stadt und führen einen trägen Fluss aus fauligem, grünem Schlamm, der die Bezirke voneinander trennt und gleichzeitig die höhlenartige untere Stadt miteinander verbindet.",al={"unterstadt kanäle","was sind die kanäle","kanalsystem unterstadt"}},c0800d9e={q="Sind die Kanäle gefährlich?",a="Obwohl von den Kanälen kaum eine unmittelbare physische Bedrohung durch lauernde Raubtiere ausgeht, sind ihre trüben, grünen Tiefen alles andere als sauber. Der zähe Schlamm ist faulig genug, um weggeworfene Knochen, menschliche Schädel und kränkliche, mutierte Wasserlebewesen zu beherbergen, was ein versehentliches Hineinfallen äußerst unangenehm macht.",al={"gefahr kanäle","ist es sicher in den kanälen der unterstadt zu schwimmen","sind die kanäle der unterstadt sicher"}}},fp="10,147,12.411.0,39.184.0,37.172.0,45.170.0"}
P.entries["subzone:cape-of-stranglethorn"] = {n="Kap des Schlingendorntals",s="Beutebucht behauptet sich, während rivalisierende Mannschaften um das Kap des Schlingendorntals kämpfen. Von der Arena der Gurubashi bis zu den Meeresklippen ringen Goblins, Blutsegelbukaniere, uralte Dschungeltrolle und wilde Tiere um die Vorherrschaft.",h="Beutebucht behauptet sich, während rivalisierende Mannschaften um das Kap des Schlingendorntals kämpfen.",kw={"baron revilgaz","blackwater raiders","blutsegelbukaniere","beutebucht","kap des schlingendorntals","arena der gurubashi","die südlichen meere","schlingendorntal"},ang={["class:Rogue"]="Als Schurke könnt Ihr überall am Kap Freibeuter, Halunken und Halsabschneider finden. Leert Taschen, schmuggelt Waren entlang der Küste oder spielt die Blackwater Raiders gegen die Blutsegelbukaniere aus.",["profession:Cooking"]="Als Koch könnt Ihr die fischreichen Gewässer der südlichen Meere und der Küste befischen. Beutebuchts Fischhändler und Hafenköche verkaufen seltene Rezepte."},sec={{t="Am Rand des Kontinents",b="Südlich der Arena der Gurubashi reicht dichter Dschungel bis an die Küste. Die Ruinen von Jubuwal und die Ruinen von Aboraz markieren Gebiete, die das Gurubashi Empire nicht mehr beherrscht. Heute füllen Raubtiere, Murloclager und rivalisierende Piratenmannschaften die Strände, Buchten und Lichtungen. Sie kämpfen um Handelsrouten und vergrabene Beute."},{t="Beutebucht und der Bukanierkrieg",b="Die Blackwater Raiders sind die stärkste Macht am Kap. Baron Revilgaz und Flottenmeister Seehorn führen sie von Beutebucht aus, einem neutralen Hafen, der in die Klippen der südlichen Bucht gehauen wurde. Dampfschiffe verbinden die Östlichen Königreiche über Ratschet mit Kalimdor.\n\nDoch die Herrschaft der Goblins bleibt unsicher. Entlang der südlichen Untiefen und vorgelagerten Inseln überfallen die Blutsegelbukaniere Versorgungslinien und planen, Beutebucht zu stürzen und die südlichen Meere an sich zu reißen."}},faq={{q="Was ist der Unterschied zwischen dem Schlingendorntal und dem Kap des Schlingendorntals?",a="Das Kap des Schlingendorntals ist der südliche Teil des größeren Schlingendorntals. Es erstreckt sich vom Gebiet südlich der Arena der Gurubashi bis nach Beutebucht und zur Küste.",al={"kap oder tal","schlingendorntal geografie","wo liegt das kap"}},{q="Wer herrscht über das Kap des Schlingendorntals?",a="Keine einzelne Macht kontrolliert das gesamte Kap. Baron Revilgaz und die von Goblins unterstützten Blackwater Raiders regieren Beutebucht und die umliegenden Gewässer. Blutsegelbukaniere, Naga und verbliebene Trolle halten Strände und Ruinen im Landesinneren.",al={"wer führt beutebucht","herrscher des kaps","wer kontrolliert das kap"}},{q="Können sowohl Horde als auch Allianz Beutebucht nutzen?",a="Ja. Beutebucht ist ein offener, neutraler Hafen, der vom Steamwheedle Cartel unterhalten wird. Lasst Eure Waffen stecken und wahrt innerhalb der Stadtgrenzen den Frieden, dann können Reisende der Allianz und der Horde die Docks, Händler, den Flugmeister und das Auktionshaus nutzen.",al={"ist beutebucht neutral","allianz horde beutebucht","kann die horde beutebucht betreten"}},{q="Was ist die Arena der Gurubashi?",a="Die Arena der Gurubashi ist eine uralte Kampfgrube der Trolle nahe dem Nordrand des Kaps. Kämpfer versammeln sich dort, um sich zu messen.",al={"gurubashi truhe","arenaregeln","pvp arena schlingendorntal"}},{q="Wie gelangen Reisende zwischen dem Kap und Kalimdor hin und her?",a="Ein von Goblins betriebenes Dampfschiff fährt regelmäßig von Beutebucht nach Ratschet, der Hafenstadt im Brachland. Es ist eine der wenigen Passagierverbindungen über die südlichen Meere.",al={"schiff nach ratschet","transport nach kalimdor","beutebucht schiff"}}},fp="21,201,21.299.0,31.432.0,80.146.0,36.213.0,42.239.0,28.129.0,51.160.0"}
P.entries["subzone:capital-gardens"] = {n="Capital Gardens",s="In Düsterbruchs Westflügel suchen verdorbener Bewuchs und Geister die Capital Gardens heim. Einst ein Park für den Adel der Kaldorei, beherbergt das Gelände nun verdorbene Urtume, Geister und Überreste der Shen'dralar.",h="In Düsterbruchs Westflügel suchen verdorbener Bewuchs und Geister die Capital Gardens heim.",kw={"athenaeum","capital gardens","düsterbruch west","eldre'thalas","feralas","immol'thar","shen'dralar"},ang={["class:Mage"]="Die Pfade der Gärten führen zum Athenaeum, einer der größten erhaltenen Sammlungen magischer Theorie aus der Zeit vor der Großen Zerschlagung in Kalimdor.",["race:NightElf"]="Für Nachtelfen erinnert das verseuchte Pflaster der Capital Gardens an die Hybris der Hochgeborenen und den verheerenden Preis arkaner Abhängigkeit."},sec={{t="Ein verfallenes Refugium",b="Zerbrochene Marmorterrassen und verdrehte graue Äste füllen die Capital Gardens. Verdorbene Treants suchen die Innenhöfe heim. Vor zehntausend Jahren war Eldre'Thalas eine der großen Städte des Kaldorei-Imperiums. Ihr Außenbezirk bot verzauberte Pflanzen und weitläufige Terrassen, auf denen sich die Zauberer der Hochgeborenen trafen, um zu debattieren und zu ruhen.\n\nNach der Großen Zerschlagung geriet die Enklave in schwere Zeiten. Ohne den Brunnen der Ewigkeit wandten sich die Shen'dralar dunkler Magie zu, um ihre Unsterblichkeit zu bewahren. Die Gärten verdorrten, und anhaltende Verderbnis hindert den Wald daran, zu heilen."},{t="Das Athenaeum und das Gefängnis",b="Überwucherte Pfade führen an feindseligen Urtumen vorbei zum Hof der Hochgeborenen und zum Athenaeum. Die Bibliothek bewahrt Jahrhunderte arkanen Wissens und vergessene Abhandlungen. Weiter im Inneren hält das Gefängnis von Immol'thar einen Dämon gefangen, den die überlebenden Elfen banden, um seine Macht anzuzapfen. Diese Verzweiflungstat entstellte die umliegenden Gärten."}},faq={{q="Was sind die Capital Gardens?",a="Die Capital Gardens nehmen Düsterbruchs Westflügel ein, inmitten der Ruinen von Eldre'Thalas im Zentrum von Feralas. Einst dienten sie als öffentlicher Park und als Wohnstätte der Hochgeborenenelite der Stadt.",al={"was sind die capital gardens","düsterbruch westliche gärten","eldre'thalas park"}},{q="Warum sind die Bäume und Urtume hier verdorben?",a="Nach der Zerstörung des Brunnens der Ewigkeit entzogen die überlebenden Shen'dralar dem beschworenen Dämon Immol'thar dunkle Teufelsenergie, um sich am Leben zu erhalten. Die austretende Magie entstellte die örtlichen Pflanzen und trieb die ansässigen Urtume in gewalttätigen Wahnsinn.",al={"warum sind die urtume hier böse","was geschah mit den bäumen","warum ist das gebiet verseucht"}},{q="Wohin führt dieses Gebiet?",a="Die Gärten führen tiefer in Düsterbruchs westlichen Komplex, zum Hof der Hochgeborenen, zum gelehrten Athenaeum und zum inneren Heiligtum, in dem Immol'thar gefangen gehalten wird.",al={"was ist mit den capital gardens verbunden","wohin führt es"}},{q="Gibt es noch freundliche Elfen in den Gärten?",a="Die meisten Hochgeborenen auf den Pfaden sind feindselige Geister oder wahnsinnige Verteidiger. Einige Gelehrte der Shen'dralar harren noch im nahen Athenaeum aus, wo sie uraltes Wissen feilbieten oder verlorene elfische Buchbände eintauschen.",al={"verbündete im inneren","wer lebt in den capital gardens"}}},fp="15,195,19.544.0,28.332.1,28.179.0,46.235.0,26.163.0,49.203.0"}
P.entries["subzone:cathedral-of-light"] = {n="Kathedrale des Lichts",s="Auf dem Kathedralenplatz steht die Kathedrale des Lichts, das wichtigste Heiligtum der Kirche des Heiligen Lichts. Sie ist Sturmwinds geistliches Herz und das Zentrum der menschlichen Priesterschaft und der Ritter der Silbernen Hand.",h="Auf dem Kathedralenplatz steht die Kathedrale des Lichts, das wichtigste Heiligtum der Kirche des Heiligen...",kw={"benedictus","kathedrale des lichts","kathedralenplatz","duthorian rall","heiliges licht","laurena","schattenbruch","silberne hand","sturmwind"},ang={["class:Paladin"]="Als Paladin findet Ihr die Haupthalle Eures Ordens in Sturmwinds Kathedrale des Lichts. Duthorian Rall und Lord Grayson Schattenbruch führen Euch durch die heiligen Prüfungen des Folianten der Ehre und des Tome of Divinity.",["class:Priest"]="Als Priester findet Ihr in der Kathedrale des Lichts den Hauptsitz der Kirche des Heiligen Lichts in den südlichen Königreichen. Hohepriesterin Laurena und Erzbischof Benedictus leiten Euch in Eurer Andacht und heiligen Heilkunst an."},sec={{t="Heiligtum der Gläubigen",b="Erzbischof Benedictus führt die Gläubigen von der Kathedrale des Lichts aus, die nach den Verwüstungen des Ersten Krieges wiederaufgebaut wurde. Erzbischof Alonsus Faol und Bischof Benedictus leiteten ihren Wiederaufbau. Ihre aufragende Gestalt erinnert noch immer an die Widerstandskraft der Stadt.\n\nNachdem die Geißel Lordaeron während des Dritten Krieges eingenommen hatte, verlegte die Kirche ihren Sitz nach Süden, nach Sturmwind. Vom großen Saal aus spendet Benedictus der Allianz geistlichen Beistand."},{t="Hallen der Andacht und Waffen",b="Die Kathedrale des Lichts ist ein Ort des Gebets und der Heilung. Sie ist auch das Hauptquartier der Ritter der Silbernen Hand in den südlichen Königreichen.\n\nLord Grayson Schattenbruch und Duthorian Rall bilden vielversprechende Knappen in den heiligen Prüfungen des Folianten der Ehre und des Tome of Divinity aus. Hohepriesterin Laurena lehrt Akolythen die tiefsten Glaubenssätze des Lichts. Sie bereitet heilige Streiter darauf vor, das Reich gegen die wachsenden Bedrohungen durch die Bruderschaft der Defias und die Geißel zu verteidigen."}},faq={{q="Wer führt die Kirche in der Kathedrale?",a="Erzbischof Benedictus führt die Kirche des Heiligen Lichts von Sturmwind aus. Nachdem Lordaeron gefallen und Erzbischof Alonsus Faol gestorben war, übernahm Benedictus die geistliche Führung der neu geordneten Kirche.",al={"oberhaupt der kathedrale","wer ist der erzbischof","wer führt die kirche"}},{q="Welche Verbindung hat die Kathedrale zu den Paladinen?",a="Die Kathedrale des Lichts ist das Hauptquartier der Ritter der Silbernen Hand in Sturmwind. Lord Grayson Schattenbruch und Duthorian Rall unterweisen neue Knappen durch heilige Prüfungen und führen Kreuzfahrer gegen die Feinde des Reiches.",al={"silberne hand sturmwind","paladinorden sturmwind","warum sind paladine hier"}},{q="Was liegt unter dem Boden der Kathedrale?",a="Die Katakomben der Kathedrale liegen unter dem Hauptheiligtum. Sie bergen die sterblichen Überreste geehrter Helden, Priester und Paladine.",al={"keller der kathedrale","katakomben der kathedrale","was liegt unter der kathedrale"}}},fx={["2c1d9b08"]={q="Was ist die Kathedrale des Lichts?",a="Die Kathedrale des Lichts ist das große spirituelle Herz der Kirche des Heiligen Lichts und der Allianz. Gelegen am Kathedralenplatz von Sturmwind, dient sie als heiliges Heiligtum für Gebet, Meditation und Heilung. Vielversprechende Priester und Paladine der Ritter der Silbernen Hand reisen aus dem ganzen Reich an, um unter ihren gewölbten Dächern zu studieren, während unter ihren mit Kobalt eingelegten Steinhallen die geehrten Toten ruhen.",al={"was ist die kathedrale des lichts","zweck der kathedrale des lichts","sturmwind kathedrale"}},b98edca3={q="Ist die Kathedrale des Lichts gefährlich?",a="Nein. Die Kathedrale des Lichts ist ein friedliches Heiligtum im bewachten Herzen von Sturmwind. Es ist ein Ort, der der Kontemplation, der Anbetung und den Heilkünsten gewidmet ist. Sofern Ihr kein Feind der Allianz oder ein Eindringling auf der Flucht vor der Stadtwache seid, werdet Ihr in ihren Hallen nur Sicherheit, Mentoren und Mitpraktizierende des das Licht finden.",al={"ist die kathedrale des lichts gefährlich","ist die sturmwinder kathedrale sicher","gefahr an der kathedrale des lichts"}},e612604f={q="Was geschah in der Vergangenheit mit der Kathedrale des Lichts?",a="Während des Ersten Krieges wurde die ursprüngliche Kathedrale von der Alten Horde schwer beschädigt. Nach dem Zweiten Krieg leiteten Erzbischof Alonsus Faol und sein damaliger Lehrling Benedictus ihren vollständigen Wiederaufbau. Mit dem Fall von Lordaeron im Dritten Krieg stieg sie zum Hauptsitz des Glaubens auf.",al={"geschichte der kathedrale des lichts","geschichte der kathedrale von sturmwind","was geschah an der kathedrale des lichts"}}},fp="18,203,25.417.0,26.474.0,42.188.0,51.228.0,38.123.0"}
P.entries["subzone:cathedral-square"] = {n="Kathedralenplatz",s="Auf dem Kathedralenplatz kommen Glaube und Stadtleben unter der Kathedrale des Lichts zusammen. Das Rathaus, das Waisenhaus und das Hauptquartier der Argentumdämmerung in Sturmwind sind hier.",h="Auf dem Kathedralenplatz kommen Glaube und Stadtleben unter der Kathedrale des Lichts zusammen.",kw={"argentumdämmerung","kathedrale des lichts","kathedralenplatz","rathaus","heiliges viertel","waisenhaus","paladin","priester","sturmwind"},ang={["class:Paladin"]="Als Paladin könnt Ihr auf dem Kathedralenplatz Mentoren, heilige Gelübde und Rüstungsschmiede für heilige Krieger finden.",["class:Priest"]="Als Priester könnt Ihr in den Hallen und Türmen des Platzes das Heilige Licht studieren, beten und den Bürgern Sturmwinds geistlichen Beistand leisten."},sec={{t="Das heilige Viertel",b="Nordwestlich des Handelsdistrikts und südöstlich des Zwergendistrikts zieht der Kathedralenplatz Gläubige aus dem ganzen Königreich Sturmwind an. Die Kathedrale des Lichts erhebt sich über dem Platz, das bedeutendste Heiligtum des Heiligen Lichts in ganz Azeroth. Priester, Paladine und Heiler kommen, um zu studieren, zu beten und zu trainieren. Bürger und Pilger mischen sich unter Schulkinder, die von School Mistress Danna geführt werden."},{t="Bürgerliches Herz und heiliger Orden",b="Auf dem Kathedralenplatz teilt sich das Gebet den Raum mit den Aufgaben des Königreichs. Das Rathaus und das Waisenhaus von Sturmwind bilden die Grundpfeiler seines bürgerlichen Lebens. Entlang der Alleen versorgen Rüstungsschmiede und Waffenschmiede heilige Kreuzfahrer, darunter Righteous Plates und Just Maces. Die Argentumdämmerung unterhält hier ihren Stützpunkt in Sturmwind. Ihre Anwerber und Vertreter koordinieren Hilfsmaßnahmen und sammeln Champions gegen die Geißel in den nördlichen Königreichen."}},faq={{q="Was ist der Kathedralenplatz?",a="Der Kathedralenplatz vereint Andacht und Stadtleben rund um die Kathedrale des Lichts in Sturmwind. Das Rathaus, das örtliche Waisenhaus und Geschäfte füllen das Viertel.",al={"kathedralenviertel","heiliges viertel","was ist dieser ort"}},{q="Wer trainiert auf dem Kathedralenplatz?",a="Priester, Paladine und Heiler studieren und trainieren auf dem Kathedralenplatz und in der Kathedrale des Lichts. Sanitäter und Pflegekräfte lernen hier bei Lehrern für Erste Hilfe.",al={"klassenlehrer hier","wer trainiert hier","paladin- und priesterlehrer"}},{q="Warum ist die Argentumdämmerung hier?",a="Die Argentumdämmerung unterhält einen Stützpunkt auf dem Kathedralenplatz, um Champions anzuwerben und Unterstützung aus Sturmwind gegen die Geißel in den Plaguelands zu koordinieren.",al={"argentumdämmerung sturmwind","präsenz der argentumdämmerung"}},{q="Wohin führt der Kathedralenplatz?",a="Brücken und Kanalwege verbinden den Kathedralenplatz mit dem Handelsdistrikt im Südosten, dem Zwergendistrikt im Nordwesten und dem Park im Südwesten.",al={"verbundene viertel","wohin führt das"}}},fx={["2ce95091"]={q="Warum heißt es Kathedralenplatz?",a="Der Bezirk verdankt seinen Namen der prächtigen Kathedrale des Lichts, die über ihm thront. Dieses große Bauwerk, das die Skyline von Sturmwind dominiert, steht als bedeutendstes Denkmal für das das Heilige Licht in ganz Azeroth und verleiht den umliegenden Straßen und bürgerlichen Plätzen auf natürliche Weise seinen Namen und seine heilige Bestimmung.",al={"bedeutung des namens kathedralenplatz","warum kathedralenplatz","wie erhielt der kathedralenplatz seinen namen"}},aa9b3d24={q="Wer wohnt am Kathedralenplatz oder betreibt ihn?",a="Der Kathedralenplatz dient als spiritueller und bürgerlicher Kern von Sturmwind. Das Priestertum und die Paladine der Kathedrale des Lichts leiten das religiöse Leben, während bürgerliche Führer die Angelegenheiten von der Stadthalle aus beaufsichtigen. Er beherbergt auch das Waisenhaus der Stadt, spezialisierte Waffen- und Rüstungshändler sowie prominente Organisationen wie die Argentumdämmerung, die hier eine aktive Präsenz unterhalten.",al={"wer verwaltet den kathedralenplatz","wer lebt am kathedralenplatz","bewohner des kathedralenplatzes"}},e4d635a7={q="Ist der Kathedralenplatz gefährlich?",a="Nein, der Kathedralenplatz ist einer der sichersten und am besten geschützten Orte im Königreich. Geschützt innerhalb der Mauern von Sturmwind und patrouilliert von Stadtwachen, wird er Tag und Nacht von standhaften Paladinen und heiligen Priestern bewacht, die sich der Wahrung des Friedens widmen.",al={"ist der kathedralenplatz sicher","gefahr am kathedralenplatz","bedrohungen am kathedralenplatz"}}},fp="16,161,17.386.0,26.392.0,25.157.0,31.152.0,36.147.0,33.158.0"}
P.entries["subzone:cauldron"] = {n="Der Kessel",s="In der Sengenden Schlucht treiben Dunkeleisen-Bergleute die Arbeit im Kessel unter den Augen von Aufsehern und Feuerelementaren voran. Gefangene Sklaven schuften in seinen Tiefen, wo Hitze und Qualen viele in den Wahnsinn getrieben haben.",h="In der Sengenden Schlucht treiben Dunkeleisen-Bergleute die Arbeit im Kessel unter den Augen von Aufsehern...",kw={"kessel","dunkeleisen","ausgrabung","magmaelementare","steinbruch","sengende schlucht","sklavenarbeiter","sklaven"},ang={["profession:Mining"]="Die schweren Maschinen und offenen Terrassen des Kessels zeigen das Ausmaß des Bergbaus der Dunkeleisenzwerge, der sich in die instabile Vulkankruste schneidet.",["race:Dwarf"]="Als Zwerg aus Eisenschmiede empfindet Ihr tiefen Abscheu beim Anblick der Dunkeleisenzwerge, die Gefangene als gebrochene Arbeitskräfte zwischen Feuerelementaren einsetzen."},sec={{t="Der glühende Steinbruch",b="Im Zentrum der Sengenden Schlucht schneidet der Kessel tief in die verbrannte Erde. Die Dunkeleisenzwerge befestigten die Grube, nachdem Imperator Thaurissan Ragnaros mit katastrophalen Folgen beschworen hatte. Schwere Ausgrabungsmaschinen schaben Gestein und Erz aus dem schwelenden Stein entlang der Schluchtwände. Unten streifen Feuer- und Magmaelementare neben Dunkeleisen-Zuchtmeistern umher. Hitze steigt aus den Tiefen des Berges auf."},{t="Die gebrochenen Arbeiter",b="Gefangene Sklaven ertragen brutale Schichten unter der Peitsche der Dunkeleisen-Aufseher. Unerbittliche Arbeit, drückende Hitze und Qualen haben viele in den Wahnsinn getrieben. Sie können Freund und Feind nicht mehr unterscheiden. Jeder, der ihre Arbeit stört, wird geschlagen, selbst jene, die ihnen eine Chance auf Freiheit bieten könnten."}},faq={{q="Was ist der Kessel?",a="Der Kessel ist ein gewaltiger Tagebau im Zentrum der Sengenden Schlucht. Der Dunkeleisenzwergen-Klan befestigte ihn, um inmitten gewaltiger vulkanischer Hitze Gestein und Erz abzubauen.",al={"geschichte des kessels","was ist der kessel","steinbruch der sengenden schlucht"}},{q="Wer kontrolliert die Ausgrabung?",a="Der Dunkeleisenzwergen-Klan leitet die Ausgrabung mit schweren Maschinen und bewaffneten Aufsehern. Die Dunkeleisenzwerge herrschen über die Grube und ihre Arbeiter.",al={"wer leitet den kessel","herren des kessels"}},{q="Warum greifen die Sklaven Abenteurer an, die helfen wollen?",a="Grausame Qualen, sengende Hitze und endlose Erschöpfung haben die Sklaven in den Wahnsinn getrieben. Sie sehen jeden, der ihre Arbeit unterbricht, als Bedrohung und greifen alle in ihrer Nähe an.",al={"warum sind sklaven feindselig","angreifende sklavenarbeiter","kann man die sklaven befreien"}},{q="Welche Arten von Kreaturen leben in der Grube?",a="Dunkeleisen-Aufseher und versklavte Arbeiter bevölkern die Grube. Feuer- und Magmaelementare streifen durch ihre feurigen Spalten.",al={"gegner im kessel","was ist im kessel","monster im kessel"}}},fp="8,199,17.382.0,20.277.0,21.153.0,28.120.0,53.157.0,44.108.0"}
P.entries["subzone:cavern-of-mists"] = {n="Cavern of Mists",s="Die Cavern of Mists ist die weitläufige äußere Vorkammer, die in die Tiefen der Höhlen des Wehklagens führt. Gespeist von unterirdischen Geysiren, die durch den Fels hervorbrechen, beherbergen ihr zentrales Becken und der dichte Nebel eine sonderbare, mutierte Tierwelt, die direkt vor der Schwelle des Portals umherstreift.",h="Die Cavern of Mists ist die weitläufige äußere Vorkammer, die in die Tiefen der Höhlen des Wehklagens führt.",kw={"brachland","cavern of mists","geysire","threshadons","trigore the lasher","die höhlen des wehklagens"},ang={["class:Druid"]="Die verquere Tierwelt, die in den schweren Dämpfen gedeiht, ist für die Druiden des Cenarius die erste Warnung davor, wie tiefgreifend Naralex' Zwiesprache mit dem Smaragdgrünen Traum fehlgeschlagen ist.",["faction:Horde"]="Direkt im Herzen des Brachlands gelegen, ist das Beseitigen der in diesen Nebeln lauernden Raubtiere entscheidend für die Sicherung der Handelsrouten und Außenposten rund um das Wegekreuz."},sec={{t="Die Schwelle des Alptraums",b="Bevor Reisende in das wahre Herz der Höhlen des Wehklagens hinabsteigen, müssen sie die Cavern of Mists durchqueren. Dicker, warmer Dunst liegt beständig in der Luft, genährt von natürlichen Geysiren, die aus dem Höhlenboden in ein tiefes zentrales Becken ausbrechen. Obwohl sie als Eingang dient, ist sie alles andere als friedlich. Schwärme von Raptoren, Schlangen, Schlämmen und halbaquatischen Threshadons streifen über die Felsvorsprünge und durch die Gewässer, zusammen mit berüchtigten Bestien wie der Hydra Trigore the Lasher. Sie bietet Abenteurern einen unheilvollen Vorgeschmack auf das unnatürliche Wachstum, das weiter unten schwelt."}},faq={{q="Wo befindet sich die Cavern of Mists?",a="Die Cavern of Mists umfasst das äußere Höhlensystem der Höhlen des Wehklagens südwestlich vom Wegekreuz im Brachland. Es ist die nicht-instanziierte Kammer, die Spieler durchqueren müssen, um das eigentliche Instanzportal zu erreichen.",al={"cavern of mists ort","wo ist cavern of mists","höhlen des wehklagens eingangshöhle"}},{q="Warum heißt sie Cavern of Mists?",a="Aktive Geysire brechen unentwegt aus dem steinernen Boden hervor, speisen das zentrale Becken und füllen die unterirdische Luft mit schwerem, feuchtem Nebel.",al={"warum neblig","cavern of mists namensursprung"}},{q="Welche Kreaturen leben hier?",a="Die Höhle wird von Raptoren, Schlämmen, Windnattern, Schlangen, Kröten und das Becken bewohnenden Threshadons bevölkert, ebenso wie von gelegentlichen Sichtungen der seltenen Hydra Trigore the Lasher.",al={"mobs in cavern of mists","cavern of mists monster"}},{q="Wer ist Trigore the Lasher?",a="Trigore the Lasher ist eine gefährliche, seltene Hydra, die man gelegentlich an der Seite der Threshadons im zentralen Becken der Höhle schwimmen sehen kann.",al={"trigore","hydra rare höhlen des wehklagens"}}},fx={["923aae57"]={q="Was ist die Cavern of Mists?",a="Die Cavern of Mists, auch als die Höhlen des Wehklagens bezeichnet, ist die äußere unterirdische Kammer, die den tieferen Bereichen der Höhlen des Wehklagens vorausgeht. Gespeist von aktiven Geysiren, die aus dem Steinboden ausbrechen, bietet die Höhle ein grünes zentrales Becken, in dem sich warmes Wasser und Dampf vermischen und die eingeschlossene unterirdische Luft mit einem beständigen, schweren Nebel füllen.",al={"was ist die cavern of mists","lore der cavern of mists","über die cavern of mists"}},["8ec0c6f8"]={q="Ist die Cavern of Mists gefährlich?",a="Ja, die Kammer ist für unvorsichtige Reisende gefährlich. Wilde Raubtiere streifen durch die nebligen Ufer und trüben Gewässer, darunter aggressive Raptoren, kriechende Schlammwesen, giftige Schlangen und schnappende Windschlangen. Das tiefe, zentrale Becken beherbergt räuberische Threshadons sowie monströse Bedrohungen wie die schwer fassbare Hydra, bekannt als Trigore the Lasher.",al={"ist cavern of mists gefährlich","cavern of mists gefahr","bedrohungen in cavern of mists"}}},fp="15,268,30.540.0,29.223.0,37.134.0,25.180.0,26.141.0"}
P.entries["subzone:caverns-of-time"] = {n="Die Höhlen der Zeit",s="In den Höhlen der Zeit bewachen Nozdormu und der bronzene Drachenschwarm Azeroths empfindliche Zeitwege. Tief in den östlichen Klippen von Tanaris achten sie auf eindringende Sterbliche und Veränderungen im Fluss der Zeit.",h="In den Höhlen der Zeit bewachen Nozdormu und der bronzene Drachenschwarm Azeroths empfindliche Zeitwege.",kw={"anachronos","bronzener drachenschwarm","die höhlen der zeit","nozdormu","tanaris","zeitlich","zeitwege"},ang={["class:Mage"]="Die Zeitmagie in den Höhlen der Zeit übersteigt die Chronomantie der Sterblichen bei Weitem. Als Magier könnt Ihr einen Blick auf Kräfte jenseits arkaner Manipulation erhaschen.",["race:NightElf"]="Als Nachtelf erinnert Ihr Euch an die uralten Pakte der kaldorei mit den Dragon Aspects. Nozdormus Auftrag ist entscheidend für das Überleben der Welt."},sec={{t="Die gewundenen Zeitwege",b="Tief unter den östlichen Klippen von Tanaris bündeln die Höhlen der Zeit die Ströme der Geschichte. Zu Beginn der Welt beauftragten die Titanen Nozdormu den Zeitlosen und seinen bronzenen Drachenschwarm damit, diese gewundenen Korridore zu bewachen.\n\nIn ihrem Inneren verläuft die Zeit auf seltsame Weise, und verborgene Risse gewähren Einblicke in Vergangenheit und Zukunft. Relikte aus fernen Epochen liegen verstreut im Sand. Anachronos wacht nahe dem Eingang, während niedere Bronzedrachen den Abstieg patrouillieren und die eine wahre Zeitlinie bewachen."},{t="Ein Hort der Epochen",b="Die Höhlen der Zeit bergen auch eine Schatzkammer, in der Vergangenheit und Zukunft zusammentreffen. Über Jahrtausende hat der bronzene Drachenschwarm Fragmente aus Azeroths Geschichte gesammelt: uralte Zwergenbauten, einen Wachturm aus Lordaeron, Häuptlingsunterkünfte der orkischen Clans und Rüstungen der ersten Könige von Stromgarde. Einige Reisende sind an den Wächtern vorbeigeschlüpft, um diese Wunder zu sehen. Die inneren Portale bleiben verschlossen, bis der Drachenschwarm ein Eingreifen Sterblicher für nötig hält."}},faq={{q="Kann ich die Höhlen der Zeit jetzt betreten?",a="Nein. Der Weg in die Höhlen der Zeit bleibt versiegelt, und der bronzene Drachenschwarm gewährt keinen Sterblichen Einlass. Anachronos steht Reisenden gleichgültig gegenüber, doch seine Gefährten patrouillieren am Eingang und greifen Sterbliche an, die sich zu nahe heranwagen.",al={"höhlen der zeit betreten möglich","wie die höhlen der zeit betreten","sind die höhlen der zeit offen"}},{q="Wer herrscht über die Höhlen der Zeit?",a="Nozdormu der Zeitlose herrscht über die Höhlen der Zeit. Die Titanen verliehen ihm die Macht, über die Zeit zu wachen, und er vertraut seinem ranghöchsten Spross Anachronos und den Wächtern des bronzenen Drachenschwarms die tägliche Obhut über die Höhlen und die Bewachung des Eingangs an.",al={"wer führt die höhlen der zeit","höhlen der zeit boss","wer lebt in den höhlen der zeit"}},{q="Warum stehen dort zusammengewürfelte Gebäude und Artefakte?",a="Nozdormu verbrachte Zeitalter damit, materielle Relikte aus Azeroths gesamter Geschichte zu sammeln und zu katalogisieren. Die Höhlen bergen Schätze fern ihres angestammten Ortes, darunter einen Wachturm aus Lordaeron, Zwergenbauten, orkische Bauwerke und Waffen aus längst vergessenen Reichen der Sterblichen.",al={"warum stehen menschliche türme in den höhlen der zeit","artefakte in den höhlen der zeit"}},{q="Welche Aufgabe hat der bronzene Drachenschwarm hier?",a="Die Titanen beauftragten den bronzenen Drachenschwarm damit, den Fluss der Zeit und die Unversehrtheit der Geschichte zu bewahren. Seine Wächter verhindern, dass Eingriffe Sterblicher und Störungen von außen die Ereignisse auflösen, die die Welt prägen.",al={"was tun bronzedrachen hier","aufgabe des bronzenen drachenschwarms"}}},fp="15,188,20.491.0,15.443.0,46.218.0,35.230.0,52.255.0,52.206.0"}
P.entries["subzone:cenarion-enclave"] = {n="Die Enklave des Cenarius",s="In Darnassus versammelt sich der Zirkel des Cenarius unter Fandral Hirschhaupts Führung der nachtelfischen Druiden. Die Enklave des Cenarius ist ihr Versammlungsort und Machtzentrum, eingebettet zwischen den großen Höhlungen und lebenden Ästen der Hauptstadt.",h="In Darnassus versammelt sich der Zirkel des Cenarius unter Fandral Hirschhaupts Führung der nachtelfischen...",kw={"zirkel des cenarius","die enklave des cenarius","darnassus","druide","fandral hirschhaupt","nachtsäbler","teldrassil"},ang={["class:Druid"]="Als nachtelfischer Druide findet Ihr hier auf Teldrassil das zivile Zentrum Eures Ordens. Ausbildung und Anleitung erfolgen unter der strengen Führung von Erzdruide Fandral Hirschhaupt.",["class:Hunter"]="Als Jäger verfeinert Ihr Eure Schießkunst und Eure Wildniskenntnisse im östlichen Geäst der Enklave. Dort ziehen Tiermeister die Nachtsäbler von Darnassus auf."},sec={{t="Herz des Zirkels",b="Hoch über den Tempelgärten vereint die Enklave des Cenarius den Zirkel des Cenarius unter uralten Eichen und Eschen, deren Rinde Runen trägt. Ihre Hallen sind aus lebendem Holz und Stein geformt. Da Malfurion Sturmgrimm im Smaragdgrünen Traum weilt, leitet Erzdruide Fandral Hirschhaupt hier die Geschäfte des Zirkels. Seine ehrgeizige Vision für Teldrassil führt zu politischen Reibungen mit Hohepriesterin Tyrande Wisperwind.\n\nDruiden meditieren an den Bächen, und auch die Jäger der Hauptstadt versammeln sich hier. In den Ställen lernen geschickte Reiter, darnassische Nachtsäbler zu zähmen."},{t="Schatten im Geäst",b="Die Enklave des Cenarius ist als friedliches Heiligtum bekannt, doch unter ihrem westlichsten Ast bietet sie auch stillen Geschäften Raum. Unter den ausgehöhlten Wurzeln liegt ein Zufluchtsort, an dem die im Verborgenen tätigen Schurken von Darnassus arbeiten, geschützt vom Blätterdach darüber."}},faq={{q="Wer führt die Enklave des Cenarius?",a="Erzdruide Fandral Hirschhaupt führt den Hain und die nachtelfischen Druiden, die in Darnassus leben. Malfurion Sturmgrimm, das oberste Oberhaupt des Zirkels des Cenarius, bleibt im Smaragdgrünen Traum in einem tiefen, unerklärlichen Schlaf gefangen. Damit liegt die tatsächliche Führung des Zirkels bei Hirschhaupt.",al={"wer hat hier das sagen","anführer der enklave des cenarius","fandral hirschhaupt"}},{q="Welche Klassen werden hier ausgebildet?",a="Druidenlehrer unterrichten zwischen den lebenden Bäumen der Enklave des Cenarius, der wichtigsten Heimstatt der Druiden von Darnassus. Jägerlehrer arbeiten im östlichen Geäst, während Schurkenlehrer einen stillen Unterschlupf in den Wurzelgängen unter dem westlichen Ast unterhalten.",al={"lehrer in der enklave des cenarius","druidenlehrer darnassus","jägerlehrer darnassus"}},{q="Wo kann ich einen Nachtsäbler als Reittier kaufen?",a="Reitlehrer und Züchter versorgen die Säbelkatzen von Darnassus am Fuß des östlichen Baums, nahe dem Eingang zum Hain. Sie bieten berechtigten Reisenden der Allianz Reitunterricht und Nachtsäbler als Reittiere an.",al={"nachtsäbler reitlehrer","reitlehrer für nachtelfen","darnassus reitlehrer"}},{q="Wie steht der Zirkel des Cenarius zur Allianz?",a="Der Zirkel des Cenarius schützt die natürliche Ordnung, statt Fraktionskriege zu führen, obwohl seine Enklave in einer Hauptstadt der Allianz liegt. Erzdruide Fandral Hirschhaupt führt die Enklave und ist ein überzeugter Nationalist, der sie stark auf die regionalen Interessen der Nachtelfen ausrichtet.",al={"gehört der zirkel des cenarius zur allianz","gehören druiden nur zur allianz"}}},fx={cda262fb={q="Was ist Die Enklave des Cenarius?",a="Die Enklave des Cenarius ist ein üppiger Hain und ein Stadtviertel, das in den nordwestlichen Ästen von Darnassus eingebettet ist. Charakterisiert durch alte Eichen und Eschen, die mit mystischen Runen versehen sind, dient es als Herz des druidischen Lebens und Denkens der Stadt. Während The Temple of the Moon die Priesterschaft leitet, versammelt die Enklave Gelehrte, Heiler und Bewahrer der Natur, um zu beraten, zu lehren und ihre spirituellen Künste zu verfeinern.",al={"die enklave des cenarius darnassus","was ist die enklave des cenarius","über die enklave des cenarius"}},fed5260a={q="Was ist in Die Enklave des Cenarius passiert?",a="Die Enklave entwickelte sich zusammen mit Darnassus als Versammlungsort für die Druiden der Hauptstadt. Ihre Heiligtümer kombinieren lebendes Holz und geformten Stein. Erz-Druide Fandral Hirschhaupt residiert in der größten dieser Strukturen und führt die Druiden an, während Malfurion Sturmgrimm im Smaragdgrünen Traum abwesend bleibt.",al={"die enklave des cenarius geschichte","geschichte der enklave des cenarius","was ist hier passiert"}},["1a9fb52b"]={q="Ist Die Enklave des Cenarius gefährlich?",a="Nein. Die Enklave ist eines der friedlichsten und am stärksten bewachten Viertel in Darnassus, gefüllt mit erfahrenen Druiden, geschickten Jägern und wachsamen Baumschützern. Sofern Ihr keine Feindseligkeit gegenüber den Nachtelfen und der Allianz hegt, werdet Ihr es als einen friedlichen Zufluchtsort der Meditation und des Studiums empfinden.",al={"ist die enklave des cenarius sicher","die enklave des cenarius gefahr","die enklave des cenarius feindselig"}},["88e7d09b"]={q="Warum heißt es Die Enklave des Cenarius?",a="Der Name leitet sich vom Zirkel des Cenarius ab, dem druidischen Orden, der sich der Bewahrung der Natur und der Ehre von Cenarius, dem Halbgott und Schutzherrn aller Druiden, widmet. Als Hauptsitz für die Praktizierenden des Zirkels innerhalb der Nachtelfenhauptstadt steht sie als eine Enklave, die speziell für ihre uralte Handwerkskunst und die Gemeinschaft mit der Natur geschaffen wurde.",al={"warum heißt es die enklave des cenarius","herkunft des namens enklave des cenarius","wer benannte die enklave des cenarius"}}},fp="16,226,19.563.0,21.219.0,31.278.0,24.235.0,35.197.0,57.262.0"}
P.entries["subzone:cenarion-hold"] = {n="Burg Cenarius",s="Burg Cenarius wacht über die uralten Gefahren unter Silithus. Der Zirkel des Cenarius unterhält seine Druiden in dieser Wüstenfestung, wo sie bewachen, was unter dem Sand begraben liegt.",h="Burg Cenarius wacht über die uralten Gefahren unter Silithus.",kw={"zirkel des cenarius","burg cenarius","druiden","kalimdor","sandstürme","silithiden","silithus"},ang={["class:Druid"]="Als Druide findet Ihr in Burg Cenarius eine der größten druidischen Enklaven außerhalb der Mondlichtung. Sie spiegelt das Versprechen des Zirkels wider, das natürliche Gleichgewicht gegen kosmische Schrecken zu bewahren.",["race:NightElf"]="Als Nachtelf könnt Ihr Burg Cenarius als eine Würdigung der Opfer sehen, die vor Jahrtausenden während des Krieges der Sandstürme gebracht wurden."},sec={{t="Eine Bastion in den Dünen",b="Im Süden von Silithus lenkt Burg Cenarius die Arbeit des Zirkels des Cenarius. Ihr erreicht sie auf gewundenen Wegen am Krater von Un'Goro vorbei. Nach dem Krieg der Sandstürme errichtet, wacht die Festung über schlummernde Bedrohungen, die unter der Wüste versiegelt sind. Silithus ist ein raues Land voller Silithiden und trockener Stürme. Die Burg bietet den Nachtelfen- und Taurendruiden, die über jene begrabenen Gefahren wachen, Unterkunft, Handel und Vorräte."},{t="Neutraler Boden",b="Burg Cenarius bleibt neutral, denn die Welt vor uraltem Unheil zu schützen, steht über den Zwistigkeiten der Sterblichen. Reisende der Allianz und der Horde erhalten Einlass, und Rüstmeister und Aufseher heißen sie trotz unsicherer Nachschubwege willkommen. Flugrouten verbinden die Burg mit Außenposten in Feralas, Tanaris und dem Krater von Un'Goro. Sie ist der einzige Stützpunkt in der Wüste für Abenteurer, die den dortigen Unruhen nachgehen."}},faq={{q="Wer kontrolliert Burg Cenarius?",a="Der Zirkel des Cenarius verwaltet Burg Cenarius und stellt ihre Garnison. Malfurion Sturmgrimm gründete den Druidenorden, und die neutrale Festung heißt Mitglieder der Allianz und der Horde willkommen.",al={"wer führt burg cenarius","burg cenarius fraktion","ist burg cenarius neutral"}},{q="Warum wurde die Festung hier draußen in der Wüste errichtet?",a="Die Festung wurde nach dem Krieg der Sandstürme errichtet, um über das tief unter Silithus versiegelte uralte Unheil zu wachen und das Wiedererstarken der Silithiden in der Region einzudämmen.",al={"warum liegt burg cenarius in silithus","zweck von burg cenarius","warum bauten druiden hier"}},{q="Wie reist Ihr nach Burg Cenarius?",a="Ihr könnt dem steilen Bergpfad nach Nordwesten aus dem Krater von Un'Goro folgen. Flugrouten verbinden die Burg mit Gadgetzan, Un'Goro und Feralas.",al={"wie kommt man nach burg cenarius","weg nach burg cenarius","nach silithus gelangen"}},{q="Können Mitglieder beider Fraktionen hier die Dienste nutzen?",a="Ja. Händler und Flugmeister in Burg Cenarius stehen allen Abenteurern zu Diensten, die der Wüste trotzen wollen, unabhängig von ihrer Zugehörigkeit.",al={"ist es für die horde sicher","kann die allianz hier rasten","burg cenarius händler"}}},fp="13,171,22.407.0,14.392.0,27.183.0,50.170.0,35.133.0,47.128.0"}
P.entries["subzone:chamber-of-atonement"] = {n="Chamber of Atonement",s="Gefangene Untote und angeklagte Ketzer erwarten in der Chamber of Atonement Verhöre und Folter. Am Eingang zum Friedhofsflügel des Scharlachroten Klosters öffnet sich die Halle zum Kreuzgang, in den der Scharlachrote Kreuzzug ihre Überreste wirft.",h="Gefangene Untote und angeklagte Ketzer erwarten in der Chamber of Atonement Verhöre und Folter.",kw={"chamber of atonement","forlorn cloister","friedhof","befrager vishas","das scharlachrote kloster","folter","vorrel sengutz"},ang={["class:Priest"]="Hier verwandeln die Befrager des Scharlachroten Kreuzzugs heilige Disziplin in körperliche Qualen. Die Kammer zeigt, wie weit sie von ihren heiligen Gelübden abgekommen sind.",["race:Undead"]="Für die Verlassenen zeigt die Chamber of Atonement die Grausamkeit des Scharlachroten Kreuzzugs gegenüber Eurem Volk. Gefangene Verlassene wie Vorrel Sengutz werden hier allein für ihre Existenz gefoltert."},sec={{t="Eine Halle der Qualen",b="Die Chamber of Atonement öffnet sich zum Forlorn Cloister, wo weder Frieden noch Gebet warten. Der Scharlachrote Kreuzzug hat diese prunkvolle Eingangshalle mit Folterbänken, Fesseln und brennenden Kohlebecken gefüllt. Eifernde Inquisitoren nutzen sie, um Geständnisse zu erzwingen und Gefangene zu quälen. Sie glauben, unheilige Wesen verdienten Schmerz als Buße, während Schreie widerhallen und grausame Zuchtmeister Wache halten."},{t="Das Reich des Befragers",b="Befrager Vishas beaufsichtigt die Kammer. Er ist stolz darauf, jeden zu brechen, der beim Überschreiten der Klostergrenzen gefasst wird. Der gefangene Verlassene Vorrel Sengutz hat durch seine Hand wochenlange Qualen erduldet. Hier ist der Kampf des Scharlachroten Kreuzzugs für Reinheit in Sadismus umgeschlagen."}},faq={{q="Wozu dient die Chamber of Atonement?",a="Im Friedhofsflügel des Klosters nutzt der Scharlachrote Kreuzzug die Chamber of Atonement, um Gefangene zu verhören und zu foltern. Verlassene und andere, die er als Feinde betrachtet, werden mit brutalen Werkzeugen verhört und gequält, bevor ihre Leichen auf den Friedhof geworfen werden.",al={"zweck der kammer","warum gibt es hier foltergeräte","was geschieht in der chamber of atonement"}},{q="Wer kontrolliert diese Kammer?",a="Befrager Vishas befehligt die Kammer. Der Folterknecht des Scharlachroten Kreuzzugs erfreut sich am Leid seiner Opfer.",al={"wer ist hier der boss","anführer der chamber of atonement","wer leitet die folterkammer"}},{q="Wohin führt dieser Raum?",a="Die Chamber of Atonement öffnet sich direkt zum Forlorn Cloister am äußersten Rand des Friedhofsflügels. Gefallene Kreuzfahrer und ruhelose Tote hausen auf seinem Friedhofsgelände unter freiem Himmel.",al={"ausgänge der kammer","wohin führt die chamber of atonement","nächster bereich nach atonement"}},{q="Wer wird hier gefangen gehalten?",a="Vorrel Sengutz, ein gefangener Verlassener, wird seit Wochen von Befrager Vishas gefangen gehalten und gefoltert.",al={"wer ist hier gefangen","vorrel sengutz","gefolterter gefangener"}}},fx={["5cd82fbf"]={q="Was ist Chamber of Atonement?",a="Chamber of Atonement ist die äußerste Halle des Friedhofsflügels im Scharlachroten Kloster. Sie liegt direkt vor dem Forlorn Cloister und dem offenen Friedhofsgelände und dient als düstere Schwelle, an der The Scarlet Crusade Gefangene für brutale Verhöre verschleppt.",al={"was ist chamber of atonement","chamber of atonement informationen","über chamber of atonement"}},f468ffff={q="Ist Chamber of Atonement gefährlich?",a="Sie ist außerordentlich gefährlich. Die Kammer wird von fanatischen scharlachroten Folterknechten unter der Leitung von Befrager Vishas besetzt, umgeben von grausamen Folterinstrumenten. Jeder Eindringling oder mutmaßliche Sympathisant der Untoten wird sofort angegriffen und derselben gnadenlosen Grausamkeit unterzogen wie die Gefangenen.",al={"ist chamber of atonement gefährlich","chamber of atonement bedrohungen","wie gefährlich ist chamber of atonement"}},["1937bc67"]={q="Warum heißt es Chamber of Atonement?",a="The Scarlet Crusade benannte die Halle nach ihrem verdrehten Glauben, dass jedes Wesen, das durch Untod befleckt ist oder sich ihrem Kreuzzug widersetzt, gestehen und für seine Sünden durch Qualen bezahlen muss. Für die Inquisitoren sind Leiden und Folter unter ihren Klingen die einzigen wahren Pfade zur Buße.",al={"warum chamber of atonement","chamber of atonement namensbedeutung","warum heißt es atonement"}}},fp="20,235,15.361.0,25.268.0,42.261.0,26.112.0,26.186.0,31.102.0"}
P.entries["subzone:champions-hall"] = {n="Halle der Champions",s="In Sturmwinds bewachter Halle der Champions versammeln sich Offiziere der Allianz, um Feldzüge in ganz Azeroth zu besprechen. Ihre Rüstmeister versorgen bewährte Veteranen mit spezialisierten Waffen, Plattenrüstungen und Ornat.",h="In Sturmwinds bewachter Halle der Champions versammeln sich Offiziere der Allianz, um Feldzüge in ganz...",kw={"halle der champions","grand marshal","ritter","offizierskaserne","die altstadt","pvp-händler","rüstmeister","sturmwind"},ang={["class:Warrior"]="Als Krieger an vorderster Front findet Ihr in der Halle der Champions schwere Kampfausrüstung und Waffen, die bewährten Anführern auf dem Schlachtfeld vorbehalten sind.",["faction:Alliance"]="Für die Allianz ehrt die Halle der Champions jene in Sturmwind, die ihr Leben der Abwehr von Einfällen der Horde widmen."},sec={{t="Die Offizierskaserne der Allianz",b="Nur Soldaten der Allianz, die sich im Kampf den Rang eines Ritters oder höher verdient haben, passieren den bewachten Eingang zur Halle der Champions. Befehlshaber versammeln sich zwischen Waffen und Rangabzeichen um Karten von Azeroth, um laufende Feldzüge zu besprechen. Rüstmeister versorgen kampferprobte Soldaten mit Elitewaffen und Rüstungen für den Kampf gegen die Horde in umkämpften Gebieten sowie mit Reittieren."}},faq={{q="Wo befindet sich die Halle der Champions?",a="Die Halle der Champions liegt im Süden der Altstadt von Sturmwind, hinter einem bewachten Eingang.",al={"wo ist die halle der champions","pvp-händler sturmwind standort","wie die halle der champions finden"}},{q="Wer darf die Halle der Champions betreten?",a="Soldaten der Allianz, die sich im Kampf den Rang eines Ritters oder höher verdient haben, dürfen die Halle der Champions betreten. Rekruten ohne diesen Rang und Zivilisten werden abgewiesen.",al={"darf jeder hinein","halle der champions voraussetzungen","warum kein zutritt zur halle der champions"}},{q="Was befindet sich in der Halle der Champions?",a="Die Rüstmeister im Inneren bieten Waffen, Rüstungen und Insignien für Offiziere sowie spezialisierte Kriegsreittiere an. Taktiker und Generäle der Allianz versammeln sich um Tische, die mit Karten von Azeroth bedeckt sind.",al={"was gibt es in der halle der champions","welche händler sind in der halle der champions","halle der champions belohnungen"}},{q="Was ist das Gegenstück dieses Gebäudes bei der Horde?",a="Das Gegenstück bei der Horde ist die Halle der Legenden in Orgrimmar, wo ausgezeichnete Krieger der Horde dieselben militärischen Versorgungsgüter erhalten.",al={"gegenstück der horde zur halle der champions","orgrimmar pvp-raum","horde pvp-kaserne"}}},fx={["5bb2303a"]={q="Was ist Halle der Champions?",a="Die Halle der Champions dient als Offiziersunterkunft für die Allianz innerhalb Sturmwind. Sie liegt versteckt in Die Altstadt und ist ein exklusiver Zufluchtsort, an dem sich ausgezeichnete Militäroffiziere und bewährte Kämpfer der Allianz versammeln, Kriegsstrategien überprüfen und sich mit speziellen Waffen und Rüstungen ausrüsten.",al={"was ist halle der champions","halle der champions sturmwind","was ist dieser ort"}},["68396c8b"]={q="Warum heißt es Halle der Champions?",a="Der Name leitet sich von den bewährten Champions der Allianz ab, die sich das Recht verdient haben, ihre Schwelle zu überschreiten. Nur diejenigen, die sich auf dem Schlachtfeld ausgezeichnet haben – und den Offiziersrang eines Ritters oder höher erreicht haben – gelten als wahre Champions, die es wert sind, ihre Hallen zu betreten.",al={"warum heißt es halle der champions","halle der champions namensbedeutung","wer sind die champions"}},b22714b1={q="Ist Halle der Champions gefährlich?",a="Nicht für Soldaten der Allianz. Die Kaserne liegt tief in Sturmwinds Die Altstadt und ist hinter einem verzauberten Portal geschützt. Sie wird stark von Offizieren und Quartiermeistern der Allianz bewacht. Jeder Infiltrator der Horde jedoch, der unvorsichtig genug ist, in Sturmwind einzudringen, würde die Halle mit einigen der furchterregendsten Veteranen der Allianz besetzt vorfinden.",al={"ist halle der champions gefährlich","ist es sicher in halle der champions","bedrohungen in halle der champions"}}},fp="15,121,31.349.0,37.87.0,42.161.0,35.178.0,46.125.0"}
P.entries["subzone:charred-vale"] = {n="Das Verbrannte Tal",s="Im Südwesten des Steinkrallengebirges verzehren Feuer und Rauch noch immer das Verbrannte Tal. Die Abholzung durch die Venture Company hinterließ einen verwüsteten Wald, und Feuerelementare streifen umher, während Blutwut-Harpyien ihr Gebiet verteidigen.",h="Im Südwesten des Steinkrallengebirges verzehren Feuer und Rauch noch immer das Verbrannte Tal.",kw={"geschwärzter uralter","blutwut","das verbrannte tal","chimaäre","feuerelementar","steinkrallengebirge","sonnenfels","venture company"},ang={["class:Druid"]="Als Druide könnt Ihr erkennen, wie ungezügelte Gier hier das natürliche Gleichgewicht zerstört hat. Das Tal bleibt ein Schwerpunkt der Bemühungen, das Land zurückzugewinnen.",["faction:Horde"]="Von Sonnenfels aus arbeiten Streitkräfte der Horde mit Verbündeten von Cenarion daran, die elementaren Unruhen einzudämmen und die anhaltende Verderbnis der Venture Company zurückzudrängen."},sec={{t="Ein versengter Wald",b="Einst füllten Bäume das Becken im Südwesten des Steinkrallengebirges, und Baumhirten wachten über den Wald. Heimische Chimaären und Harpyien lebten unter ihnen. Dann kamen die Goblins der Venture Company mit explosiven Maschinen und holzten den Wald ab. Ihre Arbeit verdarb die Baumhirten und weckte chaotische Feuerelementare.\n\nDie Baumhirten drängten die Goblins zurück, doch die Holzfäller hinterließen ein verwüstetes, vom Feuer gezeichnetes Land. Welche üblen Vorrichtungen sie auf ihrer Flucht auch einsetzten, sie verseuchten damit auch das Tal."},{t="Ringen um Erneuerung",b="Geschwärzte Uralte irren blind durch Rauch und Asche, während wutentbrannte Elementare in der Nähe umherstreifen. Blutwut-Harpyien nisten in skelettartigen Baumruinen und verteidigen, was von ihrem Gebiet übrig ist.\n\nDruiden aus Sonnenfels wollen das Tal nicht aufgeben. Sie schicken Reisende aus, um verzauberte Samen zu säen und die verdorbenen Uralten zu pflegen, während sie die versengte Erde zurückzugewinnen versuchen."}},faq={{q="Warum brennt das Verbrannte Tal?",a="Die rücksichtslose Abholzung durch die Venture Company setzte das Verbrannte Tal in Brand. Ihre zerstörerischen Maschinen erzürnten die Urgeister des Landes und entfesselten Feuerelementare, die sich im Tal ausbreiteten.",al={"warum brennt es","wer hat das verbrannte tal angezündet","was ist im verbrannten tal geschehen"}},{q="Kann sich der Wald im Verbrannten Tal jemals erholen?",a="Tauren-Druiden aus dem nahen Sonnenfels glauben, dass sich der Wald erholen kann. Sie bitten Reisende, die wahnsinnigen Baumhirten zu besänftigen und verzauberte Erdsamen in die Asche zu pflanzen, in der Hoffnung auf grüne Triebe im verwüsteten Boden.",al={"erholt sich das verbrannte tal","druiden im verbrannten tal"}},{q="Welche Kreaturen bewohnen das Verbrannte Tal?",a="Feindselige Feuerelementare, geschwärzte und rachsüchtige Uralte, Scorched Basilisks und wilde Chimaären bewohnen das Verbrannte Tal. Auch Blutwut-Harpyien suchen das Becken heim.",al={"monster im verbrannten tal","was lebt im verbrannten tal"}},{q="Wie hieß das Verbrannte Tal, bevor es brannte?",a="Der ursprüngliche Name des Verbrannten Tals ist im Lauf der Zeit verloren gegangen. Lange bevor die Goblinäxte kamen, war es als üppig bewaldete Zuflucht bekannt.",al={"alter name des verbrannten tals","ursprünglicher name des verbrannten tals"}}},fx={e38ca889={q="Was ist Das verbrannte Tal?",a="Das verbrannte Tal ist ein riesiges, schwelendes Tal im südwestlichen Steinkrallengebirge. Einst ein üppiger, grüner Wald, der von uralten Baumschützern bewacht wurde, ist es nach verheerender industrieller Ausbeutung zu Asche, Lavaspalten und brennenden Baumstümpfen verkommen.",al={"was ist das verbrannte tal","das verbrannte tal übersicht","über das verbrannte tal"}},["97858e06"]={q="Was ist in Das verbrannte Tal passiert?",a="Die Goblins der Venture Company fegten durch das Tal, holzten den Wald ab und verbrannten das Land. Als sich die uralten Baumwächter erhoben, um den Wald zu verteidigen und die Holzfäller zu vertreiben, erzürnte der Konflikt die lokalen Naturgeister, spaltete die Erde und entfesselte flüchtige Feuerelementare. Als sich die Goblins zurückzogen, korrumpierten ihre giftigen Waffen die überlebenden Baumwesen zu geschwärzten, wahnsinnigen Hüllen.",al={"das verbrannte tal geschichte","was ist im verbrannten tal passiert","wie wurde das verbrannte tal zerstört"}},["543e0702"]={q="Ist Das verbrannte Tal gefährlich?",a="Es ist einer der feindseligsten Orte im Steinkrallengebirge. Jenseits des schwelenden Bodens und des erstickenden Rauchs stehen Euch Feuerelementare, wilde Bloodfury-Harpyien, aggressive Chimären, versengte Basilisken und wahnsinnige, geschwärzte Baumwesen gegenüber.",al={"ist das verbrannte tal gefährlich","das verbrannte tal bedrohungen","gefahren des verbrannten tals"}}},fp="12,205,19.456.0,20.358.0,32.189.0,48.222.0,40.166.0,50.134.0"}
P.entries["subzone:chill-breeze-valley"] = {n="Frosthauchtal",s="Im westlichen Dun Morogh durchqueren Reisende das Frosthauchtal zwischen Kharanos und Gnomeregan. Flüchtlinge und junge Reisende folgen dem Hauptpfad, während gefährliche Bestien in den abgelegenen Winkeln lauern.",h="Im westlichen Dun Morogh durchqueren Reisende das Frosthauchtal zwischen Kharanos und Gnomeregan.",kw={"höhlen","frosthauchtal","dun morogh","gnomeregan","kharanos","t-förmig","wendigo"},ang={["race:Dwarf"]="Als Zwerg könnt Ihr Euch gegen die wilden Wendigos beweisen, die den wichtigen Durchgang zwischen dem zentralen Dun Morogh und dem westlichen Hochland bedrohen.",["race:Gnome"]="Als Gnom, der aus Gnomeregan in die Sicherheit von Kharanos oder Eisenschmiede flieht, müsst Ihr an den Raubtieren rund um das Frosthauchtal vorbei."},sec={{t="Ein Wegekreuz aus Schnee und Klauen",b="Ein T-förmiger Einschnitt durchzieht die Berge, sein Hauptpfad verläuft von Osten nach Westen. Junge Zwerge und Gnome reisen zwischen Kharanos und den Ausläufern von Gnomeregan. Der Nord-Süd-Abzweig führt in gefährliches Gelände. Blut befleckt den Schnee, und verstümmelte Kadaver liegen in der Nähe.\n\nWilde Wendigos hausen in tiefen Eishöhlen. Sie machen Jagd auf jeden, der sich in ihre Jagdgründe verirrt."}},faq={{q="Wo liegt das Frosthauchtal?",a="Das Frosthauchtal liegt im westlichen Dun Morogh, zwischen Kharanos im Osten und Gnomeregan im Westen.",al={"frosthauchtal lage","wo liegt das frosthauchtal","frosthauchtal karte"}},{q="Warum ist die Reise durch das Tal so gefährlich?",a="Der Hauptpfad zwischen Kharanos und Gnomeregan ist stark frequentiert und vergleichsweise sicher. Raubtiere jagen in den nördlichen und südlichen Abzweigen, wo Blut den Schnee befleckt und zerfetzte Kadaver die Höhlen kennzeichnen, in denen Wendigos hausen.",al={"frosthauchtal monster","gefahren im frosthauchtal","warum liegen hier knochen"}},{q="Welche Bestien haben hier ihre Höhlen?",a="Wilde Wendigos hausen in den entlegeneren Winkeln des Tals. Ein besonders großer und mächtiger Wendigo hat eine Höhle zu seinem Unterschlupf gemacht.",al={"wendigo im frosthauchtal","was lebt im frosthauchtal"}}},fx={["746bfe00"]={q="Was ist Frosthauchtal?",a="Frosthauchtal ist ein rauer, T-förmiger Pass im westlichen Dun Morogh, der die Ruinen von Gnomeregan im Westen mit der Stadt Kharanos im Osten verbindet. Sein zentraler Pfad dient als lebenswichtiger Transitkorridor für reisende Zwerge und Gnom-Flüchtlinge, während seine tieferen Bereiche weiterhin eine tückische, verschneite Wildnis bleiben.",al={"frosthauchtal","was ist dieses tal","über frosthauchtal"}}},fp="19,194,30.379.0,37.104.0,49.239.0,42.137.0"}
P.entries["subzone:chillwind-camp"] = {n="Zugwindlager",s="Am südlichen Pass hält das Zugwindlager die Stellung der Allianz gegen die Geißel. Von diesem Außenposten vor den verseuchten Ruinen von Lordaeron aus greifen Allianzsoldaten und die Argentumdämmerung nahe Festungen und Pestkessel an.",h="Am südlichen Pass hält das Zugwindlager die Stellung der Allianz gegen die Geißel.",kw={"alteracgebirge","andorhal","argentumdämmerung","ashlam valorfist","kessel","zugwindlager","zugwindspitze","westliche pestländer"},ang={["class:Paladin"]="Als vielversprechender Paladin erhaltet Ihr von Lord Grayson Schattenbruch in Sturmwind den Auftrag, Kommandant Valorfist im Zugwindlager zu unterstützen. Dort bringt Ihr den heiligen Zorn der Silver Hand über die Reihen der Untoten.",["faction:Alliance"]="Als Mitglied der Allianz findet Ihr im Zugwindlager sichere Zuflucht. Greifen sorgen für den Transport, und Befehlshaber erteilen Befehle für den Kampf gegen die Geißel im nördlichen Lordaeron."},sec={{t="Am Rand der Verderbnis",b="Das Zugwindlager bewacht den Pass von der Zugwindspitze in die Westlichen Pestländer. Es ist die erste Verteidigungslinie der Allianz und ihr Hauptstützpunkt für Vorstöße in die Region. Hohe Bergkämme halten die schlimmste Verderbnis fern, doch die Todeskälte des Nordens liegt über den Zelten und Palisaden.\n\nKommandant Ashlam Valorfist führt eine kleine Garnison aus Soldaten, Spähern und Spezialisten der Argentumdämmerung. Sie halten die Schrecken entlang der King's Road in Schach und sammeln Informationen, um Lordaerons gefallene Fluren zurückzuerobern."},{t="Ein zermürbender Krieg",b="Ohne Armeen für einen Angriff auf Andorhal oder Scholomance ist das Zugwindlager auf unabhängige Champions und Söldner angewiesen. Seine Truppen greifen den Kult der Verdammten an, machen bodenvergiftende Pestkessel unschädlich und halten Nachschubwege zu östlichen Außenposten wie der Kapelle des Hoffnungsvollen Lichts offen. Unmittelbar nördlich liegen Ruinen in der Hand der Geißel, während die Verlassenen die Westgrenze befestigen. Die Verteidiger kämpfen darum, ein Überrennen des Passes zu verhindern."}},faq={{q="Welchen Zweck erfüllt das Zugwindlager?",a="Das Zugwindlager ist der südliche Brückenkopf der Allianz und der Argentumdämmerung an der Grenze der Westlichen Pestländer. Es bietet einen sicheren Stützpunkt für Angriffe gegen die Geißel in Andorhal und für Bemühungen, die Pestkessel der Region unschädlich zu machen.",al={"warum ist das zugwindlager hier","zweck des zugwindlagers","was ist das zugwindlager"}},{q="Wie erreicht Ihr das Zugwindlager von Süderstade aus?",a="Reist von Süderstade im Vorgebirge des Hügellands nach Norden in Richtung Tarrens Mühle und folgt dann dem Bergpfad in den äußersten Osten des Alteracgebirges. Der Weg führt an den Trollruinen der Zugwindspitze vorbei und dann nordwärts durch eine Schlucht hinab ins Lager.",al={"wie zum zugwindlager gelangen","wegbeschreibung zum zugwindlager","weg zum zugwindlager"}},{q="Welcher Außenposten entspricht diesem aufseiten der Horde?",a="Das Gegenstück der Horde ist das Bollwerk an der Westgrenze zwischen Tirisfal und den Westlichen Pestländern. Beide Außenposten sind befestigte Stützpunkte für Feldzüge gegen die Geißel der Region.",al={"horde zugwindlager","horde-gegenstück zum zugwindlager","gibt es ein zugwindlager der horde"}},{q="Wer befehligt die Truppen im Zugwindlager?",a="Kommandant Ashlam Valorfist führt die Garnison im Zugwindlager. Er koordiniert Freiwillige der Allianz, Ritter der Silbernen Hand und Verbindungsoffiziere der Argentumdämmerung bei Einsätzen in den umliegenden Ruinen und auf verseuchten Bauernhöfen.",al={"anführer des zugwindlagers","wer befehligt das zugwindlager","kommandant des zugwindlagers"}}},fp="14,225,22.506.0,18.422.0,38.220.0,48.252.0,45.194.0,42.206.0"}
P.entries["subzone:chillwind-point"] = {n="Zugwindspitze",s="An der Zugwindspitze fegen kalte Luftzüge über eine felsige Anhöhe oberhalb des Gebirgspasses. Uralte Trollruinen stehen dort, wo das Vorgebirge des Hügellands, das Alteracgebirge und die Westlichen Pestländer aufeinandertreffen, und Bath'rah der Windbehüter lebt zwischen den Steinen.",h="An der Zugwindspitze fegen kalte Luftzüge über eine felsige Anhöhe oberhalb des Gebirgspasses.",kw={"alterac","bath'rah","zugwind","zugwindspitze","hillsbrad","pestländer","trollruinen","windbehüter"},ang={["class:Shaman"]="Als Schamane könnt Ihr gemeinsam mit Bath'rah dem Windbehüter die wilden Böen erforschen, die der Pass bündelt. Der Einsiedler zieht jene an, die ihre Verbindung zu den Elementen vertiefen wollen.",["faction:Alliance"]="Als Reisender der Allianz findet Ihr diese uralten Ruinen gleich südlich des Grenzpostens im Zugwindlager. Hier geht das umkämpfte Vorgebirge in die Pestländer über."},sec={{t="Ein bitterer Scheideweg",b="Die Zugwindspitze blickt über eine Schlucht am Rand von Hillsbrad. Der Pass führt in die Westlichen Pestländer, und nahebei erhebt sich das Alteracgebirge. Lange bevor Lordaeron diese Wege beanspruchte, errichteten uralte Trolle steinerne Bauwerke auf den Höhen. Ihre verwitterten Überreste trotzen noch immer den Elementen. Heute wehen kalte Winde durch die Schlucht nach Süden und tragen die Kälte des Nordens in das tiefer gelegene Vorgebirge."},{t="Der Windbehüter",b="Bath'rah der Windbehüter lebt zwischen den alten Steinen an der Zugwindspitze. Der Dschungeltrolleinsiedler hält Zwiesprache mit den heftigen Stürmen, die durch den Einschnitt jagen. Obwohl die Höhen kahl und ungeschützt sind und von der Geißel verheerte Lande nahebei liegen, ist sein Lager nicht völlig verlassen. Reisende und Schamanen auf dem Weg nach Norden suchen ihn oft auf, um die Geheimnisse der Gebirgsströmungen zu erlernen."}},faq={{q="Was ist die Zugwindspitze?",a="Die Zugwindspitze ist eine uralte Trollruine auf einer hohen Anhöhe über dem Pass zwischen Hillsbrad, Alterac und den Westlichen Pestländern. Beißende Luftzüge pfeifen durch die nahe Schlucht und geben dem Ort seinen Namen.",al={"zugwindspitze überblick","wo liegt die zugwindspitze","was ist das für ein ort"}},{q="Ist die Zugwindspitze dasselbe wie das Zugwindlager?",a="Nein. Das Zugwindlager ist der befestigte Außenposten der Allianz und der Argentumdämmerung gleich nördlich hinter der Grenze, in den Westlichen Pestländern. Die Zugwindspitze ist die Anhöhe mit den Trollruinen im Süden.",al={"zugwindspitze oder zugwindlager","zugwindlager unterschied","ist das das zugwindlager"}},{q="Wer lebt an der Zugwindspitze?",a="Bath'rah der Windbehüter lebt zwischen den Ruinen an der Zugwindspitze. Der freundliche Dschungeltroll erforscht die Winde und hilft Suchern nach den Elementen und Schamanen, die sich durch den Pass wagen.",al={"wer ist hier","wer ist der troll","bathrah"}},{q="Warum ist es hier so kalt?",a="Eine enge Gebirgsschlucht neben der Zugwindspitze bündelt eisige Luftzüge aus den hoch gelegenen nördlichen Regionen und den verseuchten Westlichen Pestländern und leitet sie ins tiefere Vorgebirge.",al={"warum ist es kalt","kalte winde","eisiger wind"}}},fx={["8e613e22"]={q="Was ist in der Vergangenheit mit Zugwindspitze passiert?",a="Dieser erhöhte Pass bildete einst einen Teil des wohlhabenden menschlichen Königreichs Lordaeron. Lange vor dem Fall von Lordaeron errichteten Trolle jedoch die uralte Steinstruktur, die noch immer den Hügel krönt. Heute steht sie als verlassenes Relikt, gefangen zwischen den unruhigen Ländern von Alterac und der Fäulnis, die sich aus dem Norden herunterschleicht.",al={"zugwindspitze geschichte","vergangenheit der zugwindspitze","was ist bei zugwindspitze passiert"}},["14e6a6f5"]={q="Warum ist Zugwindspitze in Ruinen?",a="Das steinerne Bauwerk auf der Anhöhe ist eine uralte Trollruine, die lange vor den jüngsten Kriegen verfiel. Mit dem Zusammenbruch von Lordaeron und der Verwüstung, die über die umliegenden Berge gebracht wurde, unterhält keine zivilisierte Macht den Pass, sodass nur noch verwittertes Mauerwerk den beißenden Elementen ausgesetzt ist.",al={"warum ist zugwindspitze ruiniert","zugwindspitze ruinen","warum ist zugwindspitze verlassen"}},b1aade3c={q="Ist Zugwindspitze gefährlich?",a="Der Hügel selbst ist relativ ruhig und beherbergt nur den einsamen Eremiten Bath'rah der Windbehüter. Gefahr lauert jedoch direkt in der Nähe: Der Pass leitet beißende Zugluft von den geplagten Schrecken der Westliche Pestländer direkt aus dem Norden herab, und die umliegende Wildnis ist voll von Bergpredatoren und Banditen.",al={"ist zugwindspitze sicher","zugwindspitze gefahr","bedrohungen zugwindspitze"}}},fp="15,238,19.400.0,15.370.0,24.209.0,46.185.0,29.169.0,23.170.0"}
P.entries["subzone:circle-of-aquementas"] = {n="Circle of Aquementas",s="Reisende kommen an die Ostküste von Tanaris, um am Circle of Aquementas Aquementas zu beschwören.",h="Reisende kommen an die Ostküste von Tanaris, um am Circle of Aquementas Aquementas zu beschwören.",kw={"aquementas","circle of aquementas","elementar","mast- und schotbucht","aufrecht stehende steine","tanaris"},ang={["class:Shaman"]="Als Schamane an der Küste von Tanaris mag Euch die Macht des Kreises faszinieren, Urenergien zu bündeln und einen Elementargeist zu verankern."},sec={{t="Ein Ring am Meer",b="Südlich der Mast- und Schotbucht steht der Circle of Aquementas dort, wo die Ostküste von Tanaris auf die Wüste trifft. Verwitterte Steine ragen neben dem Meer in einem Ring empor. Reisende versammeln sich hier, um Aquementas herbeizurufen, einen Elementargeist, der mit einem uralten Artefakt verbunden ist. Südmeerbanditen und Meereskreaturen durchstreifen die nahen Strände, doch die Steine markieren einen Ort der Beschwörung."}},faq={{q="Was ist der Circle of Aquementas?",a="An der Südostküste von Tanaris bilden aufrecht stehende Steine einen Ring, in dem Reisende den Elementargeist Aquementas beschwören können.",al={"was ist dieser steinring","zweck des circle of aquementas","aufrecht stehende steine tanaris"}},{q="Wo liegt der Kreis?",a="Der Kreis liegt an der Ostküste von Tanaris, direkt südlich der Klippen und des Eingangs zur Mast- und Schotbucht.",al={"wo ist der circle of aquementas","wie findet man den circle of aquementas","standort des circle of aquementas"}},{q="Wer ist Aquementas?",a="Aquementas ist ein Elementargeist, der mit einem uralten Artefakt verbunden ist und am Steinkreis beschworen wird.",al={"wer ist aquementas","geschichte von aquementas"}},{q="Wird der Kreis von Piraten bewacht?",a="Südmeerpiraten streifen nahe der Mast- und Schotbucht und an der umliegenden Küste umher. Der Kreis selbst ist ein abgelegener Ort der Beschwörung.",al={"gibt es hier piraten","südmeerpiraten nahe dem kreis"}}},fp="20,93,17.353.0,33.121.0,28.108.0,18.98.0,33.125.0"}
P.entries["subzone:circle-of-east-binding"] = {n="Kreis der Östlichen Bindung",s="Im östlichen Arathi bewachen Wasserelementare den Kreis der Östlichen Bindung, südwestlich von Hammerfall. In seinem Herzen ist der Stein der Östlichen Bindung heftig umkämpft.",h="Im östlichen Arathi bewachen Wasserelementare den Kreis der Östlichen Bindung, südwestlich von Hammerfall.",kw={"arathihochland","kreis der östlichen bindung","cresting exile","elementare","hammerfall","stein der östlichen bindung"},ang={["class:Shaman"]="Als Schamane seht Ihr Arathis Bindungssteine vielleicht als uralte Methode, Elementarkräfte zu unterdrücken, fern des Gleichgewichts und der Verbundenheit, die Ihr sucht.",["faction:Horde"]="Nur ein kurzes Stück die Straße von Hammerfall hinunter machen unbeständige Wassergeister rund um den Kreis den Patrouillen und Versorgungslinien der Horde zu schaffen."},sec={{t="Die östliche Schutzwehr",b="Östlich von Stromgarde liegt der Kreis der Östlichen Bindung im zerklüfteten Hochland von Arathi. In seinem Zentrum erhebt sich der Stein der Östlichen Bindung, erfüllt von Elementarmagie. Um ihn herum streifen cresting exiles umher. Diese wirbelnden Wasserelementare verteidigen den Stein erbittert gegen jeden Sterblichen, der sich nähert."},{t="Elementare Gefangenschaft",b="Uralte Steine in ganz Arathi binden unbeständige Elementarkräfte. Rund um den östlichen Kreis zeigen rastlose Wassergeister, wie sehr diese Schutzwehren belastet sind. Von der Magie des Steins angezogen oder gefangen gehalten, greifen sie Reisende auf der nahe gelegenen Straße nach Hammerfall an."}},faq={{q="Wo liegt der Kreis der Östlichen Bindung?",a="Der Kreis der Östlichen Bindung liegt im östlichen Arathi, südlich der Hauptstraße und südwestlich von Hammerfall, dem Lager der Horde.",al={"östliche bindung standort","wo ist der kreis der östlichen bindung","kreis der östlichen bindung karte"}},{q="Welche Kreaturen gibt es hier?",a="Aggressive Wasserelementare namens cresting exiles durchstreifen den Kreis und bewachen den Stein der Östlichen Bindung.",al={"östliche bindung gegner","welche monster gibt es bei der östlichen bindung","cresting exiles"}},{q="Warum gibt es Wasserelementare im Hochland?",a="Uralte Steine in ganz Arathi binden Elementarkräfte. Die Wasserelementare hier werden möglicherweise vom östlichen Schutzstein festgehalten oder von seiner Energie angezogen.",al={"warum wasserelementare in arathi","östliche bindung elementargeschichte"}},{q="Welchen Zweck erfüllt der Stein der Östlichen Bindung?",a="Der Stein der Östlichen Bindung gehört zu einem Netz von Bindungssteinen im gesamten Arathihochland. Sie wurden errichtet, um unbeständige Elementarkräfte zu verankern, zu kanalisieren und gefangen zu halten.",al={"stein der östlichen bindung zweck","was bewirkt der stein der östlichen bindung"}}},fp="22,156,16.294.0,22.248.0,44.118.0,30.103.0,48.139.0,49.169.0"}
P.entries["subzone:circle-of-inner-binding"] = {n="Kreis der Inneren Bindung",s="Unter dem Arathihochland hält der Kreis der Inneren Bindung Myzrael unter uralten Steinen gefangen. Der Stein der Inneren Bindung verankert den stärksten Bannzauber, doch Risse lassen die gefangene Prinzessin Kontakt zu Wanderern aufnehmen.",h="Unter dem Arathihochland hält der Kreis der Inneren Bindung Myzrael unter uralten Steinen gefangen.",kw={"arathihochland","kreis der inneren bindung","erdelementare","myzrael","rumbling exile","stein der inneren bindung","burg stromgarde"},ang={["class:Mage"]="Als Magier könnt Ihr ein komplexes Muster in den Steinen erkennen. Ihre geometrische Anordnung bildet ein beständiges Bannfeld, das gewaltige unterirdische magische Druckkräfte kanalisiert und verankert.",["class:Shaman"]="Als Schamane könnt Ihr spüren, wie rohe Erdenergie durch den Kreis der Inneren Bindung strömt. Seine uralten, schweren Elementarfesseln sind deutlich spürbar, während die unnatürliche Unruhe der Erdgeister vor Verderbnis unter dem Boden warnt."},sec={{t="Das innerste Siegel",b="Südlich der Hauptstraße umringen hoch aufragende Steinplatten den Stein der Inneren Bindung auf einem Plateau. Der Stein pulsiert vom stärksten Bannzauber unter Arathi und dessen dichter geomagischer Kraft. Rumbling Exiles patrouillieren zwischen den Steinen, angezogen von der Resonanz des Ortes oder dort als Wächter gebunden.\n\nRisse im inneren Siegel lassen die gefangene Myzrael telepathisch Kontakt aufnehmen. Sie flüstert ahnungslosen Wanderern, die Splitter ihres Steins berühren, Bitten um Freiheit zu."}},faq={{q="Welchen Zweck erfüllt der Kreis der Inneren Bindung?",a="Der Kreis beherbergt den Stein der Inneren Bindung, den stärksten Bannzauber, der Myzraels Gefängnis unter der Erde verankert. Er wirkt mit anderen Elementarkreisen zusammen, die über das Arathihochland verstreut liegen, um sie unter der Oberfläche festzuhalten.",al={"warum ist dieser kreis hier","was bewirkt die innere bindung","geschichte des kreises der inneren bindung"}},{q="Welche Kreaturen bewachen diesen Kreis?",a="Mächtige Erdelementare bewachen den Kreis, vor allem Rumbling Exiles. Diese steinernen Kolosse greifen jeden an, der sich den Ritualsteinen nähert.",al={"welche feinde sind hier","gegner der inneren bindung","rumbling exile"}},{q="Wer flüstert durch den Stein?",a="Myzrael ist eine uralte und mächtige Elementarprinzessin, die tief unter der Erde gefangen ist. Ihre geistige Kraft hat das rissige Siegel durchdrungen und lässt sie durch den Bindungssplitter Kontakt zum Geist Sterblicher aufnehmen.",al={"wer spricht hier","myzraels stimme","flüsternder stein"}},{q="Wo liegt der Kreis der Inneren Bindung?",a="Der Kreis liegt auf einem erhöhten Bergrücken im südlichen Arathihochland, direkt östlich der Burg Stromgarde.",al={"standort der inneren bindung","wo ist der kreis der inneren bindung","innere bindung finden"}}},fp="23,213,13.435.0,51.221.0,33.138.0,36.198.0,45.106.0"}
P.entries["subzone:circle-of-west-binding"] = {n="Kreis der westlichen Bindung",s="Nahe Thoradinswall überrennen Brennende Verbannte den Kreis der westlichen Bindung und bewachen seinen Stein. Die uralte Ritualstätte ist eine von mehreren, die über das Arathihochland verstreut sind.",h="Nahe Thoradinswall überrennen Brennende Verbannte den Kreis der westlichen Bindung und bewachen seinen Stein.",kw={"arathihochland","brennender verbannter","kreis der westlichen bindung","elementar","ruul onestone","stein der westlichen bindung","thoradinswall"},ang={["class:Mage"]="Als Magier könnt Ihr an Arathis Bindungssteinen erkennen, wie einstige Magier und Schamanen elementare Wesen aus anderen Ebenen verankerten und unterwarfen.",["class:Shaman"]="Als Schamane könnt Ihr die unbeständige Präsenz der Brennenden Verbannten als Zeichen elementarer Unruhe deuten, die noch immer an diese uralten Schlüsselsteine Arathis gebunden ist."},sec={{t="Der westliche Schlüsselstein",b="Nahe Thoradinswall steht der Stein der westlichen Bindung im Kreis der westlichen Bindung. Die Stätte gehört zu einem größeren Netzwerk uralter Ritualorte, die über das Arathihochland verstreut sind. Brennende Verbannte überrennen das Gelände und bewachen den Stein. Ihre feurige Präsenz macht eine Annäherung für Reisende gefährlich, die die westlichen Ebenen durchqueren."}},faq={{q="Was ist der Kreis der westlichen Bindung?",a="Der Kreis der westlichen Bindung ist eine uralte Ritualstätte im westlichen Arathihochland, nahe Thoradinswall. Dort steht der Stein der westlichen Bindung, bewacht von feindseligen Feuerelementaren.",al={"kreis der westlichen bindung","stein der westlichen bindung"}},{q="Warum gibt es hier Feuerelementare?",a="Die Brennenden Verbannten hausen am Stein der westlichen Bindung und bewachen ihn. Diese elementaren Kräfte werden von uralten magischen Fokussen angezogen oder an sie gebunden, die überall im Arathihochland errichtet wurden.",al={"brennende verbannte arathi","warum fe身erelementare westliche bindung","elementare kreis der westlichen bindung"}},{q="Wer ist Ruul Onestone?",a="Ruul Onestone ist ein Ogermagier der Boulderfist, der das Gelände durchstreift. Er ist ein seltener und gefährlicher Unhold, kein Gelehrter, der den Bindungsstein erforscht.",al={"ruul onestone","ruul","zwerg bei der westlichen bindung"}}},fp="22,173,20.332.0,35.179.0,35.164.0,21.131.0"}
P.entries["subzone:clean-zone"] = {n="Clean Zone",s="Gnome halten die Clean Zone als Zuflucht im zerstörten Gnomeregan. Hinter der oberen Hall of Gears bleibt diese befestigte Enklave inmitten der verstrahlten Stadt sicher. Sanitäter, Techniker und Sparklematic-Maschinen unterstützen ihre Verteidiger und die Bergungsarbeiten.",h="Gnome halten die Clean Zone als Zuflucht im zerstörten Gnomeregan.",kw={"clean zone","dormitory","gnomeregan","hall of gears","strahlung","sparklematic 5200","tink sprocketwhistle","troggs"},ang={["profession:Engineering"]="Als Ingenieur könnt Ihr die funktionierenden Sparklematic 5200-Einheiten hier nutzen, um verstrahlten Schrott nach seltenen Bauplänen und mechanischen Teilen zu durchsuchen. Auch der Händler Tink Sprocketwhistle ist hier.",["race:Gnome"]="Als Gnom seht Ihr in der Clean Zone eine düstere Erinnerung an den Fall Eurer Heimat und ein Hoffnungszeichen, dass Gnomeregans Technologie den Troggs noch entrissen werden kann."},sec={{t="Eine Bastion in der Schlacke",b="Die Clean Zone bleibt unverseucht, während der Großteil von Gnomeregan Mekkatorques verhängnisvollem Ablassen radioaktiver Abfälle zum Opfer fiel. Sie liegt zwischen dem von Troggs befallenen Dormitory darunter und der umkämpften Hall of Gears darüber. Gnomische Verteidiger, Techniker und Feldsanitäter halten ihre Barrikaden Tag und Nacht. Expeditionen der Allianz sammeln sich hier, versorgen Wunden und warten ihre Maschinen."},{t="Der Sparklematic 5200",b="Die Clean Zone unterstützt auch die Bergung von Gegenständen aus Gnomeregans zerstörter Hauptstadt. Gnomische Ingenieure installierten Sparklematic 5200-Einheiten, um schmutzverkrustete Relikte aus den radioaktiven Tiefen der Stadt zu schrubben und zu waschen. Techniker und Händler wie Tink Sprocketwhistle verarbeiten geborgene Zahnräder und Schmuckstücke, rüsten Abenteurer aus und untersuchen den giftigen Niederschlag in den tiefen Tunneln."}},faq={{q="Warum ist dieses Gebiet nicht wie der Rest von Gnomeregan verstrahlt?",a="Die Gnome in der Clean Zone bleiben von der Strahlung verschont, die Gnomeregan verwüstet hat. Kein Bericht erklärt genau, warum dieses kleine Gebiet der Verseuchung entging.",al={"warum clean zone nicht verstrahlt","warum hier sicher","clean zone strahlung"}},{q="Was machen die Sparklematic 5200-Maschinen?",a="Sparklematic 5200 sind gnomische Maschinen, die Gegenstände waschen und dekontaminieren. Abenteurer können schmutzverkrustete Gegenstände hineinlegen, die sie Troggs und Lepragnomen abgenommen haben. Die Maschinen waschen radioaktiven Schmutz ab und bringen nützliche Erze, Edelsteine, Münzen oder technische Kuriositäten zum Vorschein.",al={"sparklematic 5200","was sind sparklematics","schmutz entfernen"}},{q="Wer kontrolliert und verteidigt die Clean Zone?",a="Unkorrumpierte gnomische Wachen, Feldsanitäter und Techniker halten die Außengrenzen der Clean Zone. Sie bekämpfen Troggs, die aus dem Dormitory vorrücken, und Lepragnome, die aus den oberen Ebenen herabsteigen, um den Stützpunkt zu sichern.",al={"wer ist in der clean zone","clean zone wachen","wer hält die clean zone"}},{q="Können Spieler hier sicher rasten oder ihre Ausrüstung reparieren lassen?",a="Ja. Die Clean Zone ist ein Feldlager in Gnomeregan mit Ingenieursbedarf, Reparaturen bei Tink Sprocketwhistle und einem funktionierenden Briefkasten für Abenteurer hinter der Front.",al={"reparaturen clean zone","rasten in der clean zone möglich","briefkasten in gnomeregan"}}},fx={["844f3e3b"]={q="Ist die Clean Zone gefährlich?",a="Das Innere der Clean Zone selbst ist sicher und wird gut von Elite-Gnomwachen und Sanitätern verteidigt. Die Gebiete direkt daneben sind jedoch gefährlich: Feindselige Troggs wimmeln im Schlafsaal unter uns und überrennen die oberen Ebenen der Hall of Gears direkt vor dem Außenbereich.",al={"ist die clean zone gefährlich","bedrohungen in der clean zone","gefahr in der clean zone"}},dc9c4202={q="Was ist Clean Zone?",a="Die Clean Zone ist ein befestigtes Heiligtum, das tief in Gnomeregan liegt und direkt hinter der oberen Ebene der Hall of Gears liegt. Sie ist die letzte verbliebene Festung innerhalb der gefallenen Hauptstadt, in der nicht korrumpierte Gnome einen Stützpunkt halten, der frei von tödlichem Fallout ist.",al={"was ist clean zone","clean zone übersicht","über clean zone"}},fa9b1319={q="Was ist während des Falls von Gnomeregan mit der Clean Zone passiert?",a="Als Hochtüftler Mekkatorque die Strahlungsventile öffnete, um die einfallenden Troggs zu vertreiben, verwüstete giftiger Fallout die Stadt und mutierte viele Gnome zu Lepragnomen. Unbetroffene Gnome halten diese kleine Zuflucht und verteidigen sie gegen umliegende Eindringlinge.",al={"clean zone geschichte","was ist bei clean zone passiert","geschichte der clean zone"}}},fp="10,243,21.370.0,21.371.0,59.158.0,42.269.0,40.220.0,39.178.0"}
P.entries["subzone:cleft"] = {n="Die Kluft",s="Nordwestlich von Dolanaar überfallen Gnarlpine-Furbolgs Reisende in der Kluft.",h="Nordwestlich von Dolanaar überfallen Gnarlpine-Furbolgs Reisende in der Kluft.",kw={"die kluft","darnassus","dolanaar","furbolg","gnarlpine","mondpriesterin amara"},ang={["class:Druid"]="Als Druide wisst Ihr, dass die verderbten Gnarlpine Reisende auf der Straße nach Darnassus bedrohen.",["race:NightElf"]="Als Nachtelf seht Ihr, wie langjährige Verbündete unter den Furbolgs in den Wahnsinn getrieben werden und Reisende angreifen."},sec={{t="Ein Bau der Verderbnis",b="Abseits der Straße zwischen Dolanaar und Darnassus haben Gnarlpine-Furbolgs ihren Bau in der Kluft eingerichtet. Teldrassils um sich greifende Verderbnis hat sie wahnsinnig gemacht, und sie haben die Senke befestigt. Von dort aus bedrohen sie Reisende auf der Hauptstraße und könnten Dolanaar von Darnassus abschneiden."},{t="Die Straßenräuber",b="Mondpriesterin Amara und ihre Wächter bewachen den Eingang zur Kluft. Sie sichern die Hauptstraße zwischen Teldrassils Dörfern und Darnassus, doch die Gnarlpine bedrohen weiterhin den Weg."}},faq={{q="Was ist die Kluft?",a="Die Kluft ist ein Furbolgbau nordwestlich von Dolanaar, neben der Hauptstraße nach Darnassus.",al={"was ist die kluft","die kluft teldrassil","kluft lage"}},{q="Wer kontrolliert die Kluft?",a="Feindselige Gnarlpine-Furbolgs besetzen die Kluft, von Teldrassils um sich greifender Verderbnis in den Wahnsinn getrieben.",al={"wer lebt in der kluft","kluft feinde","wer beherrscht die kluft"}},{q="Warum kämpfen die Nachtelfen hier?",a="Die Gnarlpine überfallen Reisende auf der Straße nach Darnassus, weshalb Mondpriesterin Amara und die Wächter daran arbeiten, die Straße zu sichern.",al={"warum die kluft angreifen","kluft nachtelfen quests","straße nach darnassus"}},{q="Hat die Kluft etwas mit der Kluft der Schatten zu tun?",a="Nein. Die Kluft ist eine Furbolghöhle in Teldrassil; die Kluft der Schatten ist eine dunkle Höhle unter Orgrimmar.",al={"kluft der schatten verbindung","kluft und kluft der schatten unterschied"}}},fx={["3e19e4c1"]={q="Was ist in der Kluft passiert?",a="Die Gnarlpine-Furbolgs suchten Zuflucht in der Höhle, doch üble Verderbnis bemächtigte sich schnell ihrer Geister. Sie verfielen in Wahnsinn, begannen, die nahegelegene Straße in Richtung Darnassus zu überfallen, griffen unvorsichtige Reisende an und bedrohten den Handel mit der Hauptstadt.",al={"geschichte der kluft","was geschah in der kluft","geschichte kluft"}},de17fe22={q="Ist die Kluft gefährlich?",a="Die Kluft ist sehr gefährlich. Feindselige, korrumpierte Gnarlpine-Furbolgs drängen sich in dem dunklen Bau. Sie verteidigen ihr ausgehöhltes Heim erbittert, nachdem sie bereits Nachschubwege überfallen und Reisende bedroht haben. Mondpriesterin Amara und ihre Wächterinnen müssen die Straße direkt davor bewachen, um sie zurückzuhalten.",al={"gefahr in der kluft","ist die kluft sicher","bedrohungen in der kluft"}}},fp="5,72,19.284.0,21.188.1,18.84.0,23.95.0,38.126.0,44.102.0"}
P.entries["subzone:cleft-of-shadow"] = {n="Die Kluft der Schatten",s="Schurken, Hexenmeister und ihre Lehrer versammeln sich in Orgrimmars Kluft der Schatten. Dort üben sie ihre Künste unter dem wachsamen Auge der Horde aus.",h="Schurken, Hexenmeister und ihre Lehrer versammeln sich in Orgrimmars Kluft der Schatten.",kw={"die kluft der schatten","darkfire enclave","orgrimmar","der flammenschlund","schurke","shadowswift brotherhood","hexenmeister"},ang={["class:Rogue"]="Als Schurke findet Ihr die Shadowswift Brotherhood, Gifthändler und Schlossknacker in diesem dunklen Winkel. Er ist der wichtigste Treffpunkt der Horde für verdeckt operierende Agenten.",["class:Warlock"]="Als Hexenmeister der Horde könnt Ihr in der Darkfire Enclave unter Orgrimmar Dämonen beschwören und Teufelsenergie binden. Dort seid Ihr dem unmittelbaren Zorn der Schamanen und Krieger entzogen."},sec={{t="Eine unterirdische Zuflucht",b="Unter Orgrimmar bietet die Kluft Schurken der Shadowswift Brotherhood und Hexenmeistern der Darkfire Enclave Zuflucht. Thralls Horde ehrt den Schamanismus und die Stärke der Waffen, doch ihre Anführer lassen Raum für subtilere Künste. So wirken Anwender von Giften und Teufelsenergie abseits der Talbezirke, unter Orgrimmars wachsamem Auge."},{t="Eine gefährliche Schwelle",b="Am tiefsten Punkt der Höhle führt ein Durchgang in den Flammenschlund. Vulkanische Höhlen durchziehen den Boden unter Orgrimmar. Die Gefahr, die von ihnen ausgeht, zieht Verteidiger und finstere Kultisten an den Rand der Höhle."}},faq={{q="Warum werden Hexenmeister und Schurken hier unter der Erde gehalten?",a="Thrall will die Horde durch ehrenhafte Traditionen der Schamanen und Krieger vereinen. Viele Orcs misstrauen den Künsten der Schurken und Hexenmeister, weshalb deren gefährliches Teufelswirken und unerlaubte Praktiken in den Höhlen eingegrenzt und überwacht werden.",al={"warum kluft der schatten","warum hexenmeister unter orgrimmar","geschichte der kluft der schatten"}},{q="Welche wichtigen Lehrer und Dienste gibt es in der Kluft der Schatten?",a="Lehrer für Schurken und Hexenmeister arbeiten in der Kluft, neben Giftlieferanten, Reagenzienverkäufern und Händlern, die Zauberstäbe und Stäbe verkaufen.",al={"lehrer in der kluft der schatten","wer ist in der kluft der schatten"}},{q="Was ist der Eingang am Grund der Höhle?",a="Die Öffnung führt in den Flammenschlund, ein gefährliches Netz aus Lavaröhren unter Orgrimmar. Troggs, sengende Elementare und abtrünnige Kultisten bevölkern seine Tiefen.",al={"dungeon in der kluft der schatten","höhleneingang der kluft","welche instanz ist hier"}}},fx={b6f6ea67={q="Ist die Kluft der Schatten gefährlich?",a="Die Höhle selbst ist ein funktionierender Bezirk von Orgrimmar und für Bürger relativ sicher, wenngleich die Dämonenbeschwörer und Giftverkäufer sie beunruhigend machen. Eine weitaus größere Gefahr lauert am tiefsten Punkt der Kluft: der vulkanische Abstieg zum Flammenschlund, einem weitläufigen Netzwerk aus Lavatunneln, das direkt unter den Grundmauern der Stadt von Troggs und Kultisten verseucht ist.",al={"ist die kluft der schatten sicher","ist die kluft der schatten gefährlich","gefahr in der kluft der schatten"}},["866219a4"]={q="Was ist Die Kluft der Schatten?",a="Die Kluft der Schatten ist eine gewaltige unterirdische Höhle, die tief unter den felsigen Schluchten von Orgrimmar gegraben liegt. Während die Stadt darüber Stärke, Ehre und offenen Kampf zelebriert, beherbergt diese düstere unterirdische Vertiefung die weniger erfreulichen Ausübenden, deren Künste mit Argwohn betrachtet werden: Schurken, die in den Schatten lauern, und Hexenmeister, die Dämonenmagie praktizieren.",al={"was ist die kluft der schatten","wissen über die kluft der schatten","über die kluft der schatten"}},["3bd03716"]={q="Wer lebt in der Kluft der Schatten oder leitet sie?",a="Kein einzelner Anführer befehligt die Höhle offen; vielmehr gehört sie den Ausgestoßenen, Spionen und okkulten Ausübenden, die von der Horde geduldet werden. Ihr werdet die heimlichtuerischen Schurken der Shadowswift Brotherhood und die Hexenmeister der Darkfire Enclave hier versammelt finden, neben Giftmischern und Reagenzienhändlern, die für ihre illegalen Künste sorgen.",al={"wer führt die kluft der schatten an","bewohner der kluft der schatten","wer lebt in der kluft der schatten"}}},fp="15,133,24.319.0,21.192.0,50.228.0,69.130.0,49.155.0"}
P.entries["subzone:cliffspring-falls"] = {n="Cliffspring Falls",s="Bei Cliffspring Falls stürzt Wasser von den östlichen Klippen der Dunkelküste in den Wald hinab. Der Wasserfall speist den Klippenquell und versorgte einst nahe gelegene Nachtelfensiedlungen. Nun breitet sich eine üble Verderbnis im Flussbecken aus.",h="Bei Cliffspring Falls stürzt Wasser von den östlichen Klippen der Dunkelküste in den Wald hinab.",kw={"auberdine","cliffspring falls","der klippenquell","cliffwater falls","dunkelküste","teufelswald","naga","schattenhammer","wasserverderbnis"},ang={["class:Druid"]="Als Druide des Zirkels des Cenarius beobachtet Ihr den Fluss aufmerksam und arbeitet daran, die unnatürliche Fäulnis aufzuspüren und zu beseitigen, die die Wildnis bedroht.",["race:NightElf"]="Als Nachtelf aus Auberdine wisst Ihr, dass die Verderbnis in Cliffspring Falls Gewässer verunreinigt, die für die uralten Wälder der Dunkelküste lebenswichtig sind. Sie bedroht die Gesundheit und den Geist des Waldes."},sec={{t="Eine verderbte Quelle",b="Cliffspring Falls entspringt Höhlen hoch in den östlichen Klippen der Dunkelküste und speist den Klippenquell. Der Fluss schlängelt sich westwärts durch die Wälder, bevor er ins Meer mündet. Sein klares Wasser lieferte den nahe gelegenen Nachtelfensiedlungen einst ihr reinstes Trinkwasser.\n\nNun fließt das Wasser trüb und faulig dahin und trägt Krankheit und Verfall durch das Flussbecken. Naturforscher, die den Wasserfall untersuchen, finden Höhlen vor, die von Naga und Kultisten überrannt wurden. Sie schmieden im Schatten Pläne, während dämonische Verderbnis aus dem benachbarten Teufelswald durch das Grundgestein des Hochlands zu sickern droht."}},faq={{q="Was ist Cliffspring Falls?",a="Cliffspring Falls ergießt sich aus Höhlen im Osten der Dunkelküste und speist den Klippenquell. Sein Wasser war einst die wichtigste Quelle für frisches Trinkwasser der nahe gelegenen Siedlungen.",al={"cliffspring falls","cliffwater falls","was ist cliffspring falls"}},{q="Warum ist das Wasser des Wasserfalls verderbt?",a="Dämonische Verderbnis könnte aus dem Teufelswald durch die Berge sickern. Auch Kultisten des Schattenhammers und Naga besetzen die Höhlen, die den Wasserfall speisen.",al={"warum ist das wasser verderbt","verderbnis im klippenquell","verderbtes wasser"}},{q="Wer besetzt die Höhlen hinter dem Wasserfall?",a="Naga und Kultisten des Schattenhammers besetzen die überfluteten Höhlen oberhalb und hinter dem Wasserfall.",al={"wer ist in den höhlen","gegner in cliffspring-höhlen","wer lebt in cliffspring falls"}},{q="Warum ist Cliffspring Falls für die Dunkelküste so wichtig?",a="Der Klippenquell durchquert den Norden der Dunkelküste, und sein Wasser ist eine der wichtigsten Frischwasserquellen. Seine Vergiftung bedroht die Tierwelt, uralte Haine und die Heimstätten der Nachtelfen.",al={"warum ist das für die dunkelküste wichtig","bedeutung von cliffspring"}}},fx={b072a170={q="Was ist mit Cliffspring Falls passiert?",a="Cliffspring Falls war einst ein unberührter Gebirgswasserfall, der den Norden der Dunkelküste mit sauberem Trinkwasser versorgte. Nach der Verwüstung durch den Dritten Krieg krochen dunkle Mächte in die umliegende Wildnis. Verderbnis ergriff die Höhle an der Quelle des Flusses, verwandelte den reinen Gebirgsstrom in etwas Übles und lockte bösartige Wesen in ihre verborgenen Tiefen.",al={"geschichte von cliffspring falls","was passierte bei cliffspring falls","warum veränderte sich cliffspring falls"}},["894b4715"]={q="Ist Cliffspring Falls gefährlich?",a="Die Wasserfälle und die dahinter liegenden Höhlen sind extrem gefährlich. Feindselige Naga kriechen durch die Wasserwege, während fanatische Kultisten des Schattenhammers tief im Höhlensystem lauern und üble Rituale durchführen. Abgesehen von den tödlichen Bewohnern stellt das verseuchte Wasser selbst eine ernsthafte Gefahr für jeden dar, der es zu trinken wagt.",al={"gefahr bei cliffspring falls","ist cliffspring falls sicher","bedrohungen bei cliffspring falls"}}},fp="17,225,16.551.0,26.180.0,49.145.0,42.94.0,51.176.0"}
P.entries["subzone:clockwerk-run"] = {n="Clockwerk Run",s="In Gnomeregan versperren giftige Dämpfe und verstrahlte Troggs den Clockwerk Run zwischen dem Train Depot und der Hall of Gears.",h="In Gnomeregan versperren giftige Dämpfe und verstrahlte Troggs den Clockwerk Run zwischen dem Train Depot und...",kw={"clockwerk run","gnomeregan","hall of gears","verstrahlte troggs","train depot","troggs"},ang={["profession:Engineering"]="Als Ingenieur erkennt Ihr an den zerstörten Maschinen und eingestürzten Bauwerken entlang des Clockwerk Run, was Sprengkraft und Strahlung gnomischen Mechanismen antun können.",["race:Gnome"]="Als Gnom führt Euch der Weg durch den Clockwerk Run den Fall Eurer Hauptstadt vor Augen. Der verzweifelte Versuch, die Stadt zu säubern, veränderte die Eindringlinge, statt sie zu vernichten."},sec={{t="Eine zerstörte Schwelle",b="Der Clockwerk Run führt Euch vom äußeren Train Depot nach Gnomeregan hinein. Einst verlief der gnomische Verkehr samt Nachschub durch diesen Korridor. Dann befahl Hochtüftler Mekkatorque, radioaktiven Abfall abzulassen, um die Invasion der Troggs aufzuhalten. Der Abfall verwandelte den Durchgang in eine tödliche Falle.\n\nDie Explosion und die darauffolgenden Kämpfe brachten Teile des Ganges zum Einsturz. Giftige Dämpfe und verstrahlte Troggs versperren nun den Weg zur oberen Hall of Gears."}},faq={{q="Wohin führt der Clockwerk Run?",a="Der Clockwerk Run verbindet das Train Depot außerhalb der tiefen Gewölbe mit der oberen Hall of Gears im Inneren von Gnomeregan.",al={"clockwerk run lage","wohin führt dieser gang","clockwerk run eingang"}},{q="Warum gibt es hier so viele Troggs?",a="Während der Invasion strömten Troggs durch Gnomeregans untere Gänge. Im Clockwerk Run wurden sie durch abgelassenen radioaktiven Abfall gewalttätig und verstrahlt, und sie greifen jeden an, der die Stadt betritt.",al={"warum troggs","clockwerk run gegner"}},{q="Warum ist der Korridor teilweise eingestürzt?",a="Die Kämpfe während Gnomeregans Fall und die Freisetzung giftiger Abwehrmittel beschädigten den Außenbereich schwer. Teile des Korridors stürzten ein.",al={"clockwerk run eingestürzt","warum ist er zerstört"}}},fx={["8c8c10db"]={q="Was ist der Clockwerk Run?",a="Der Clockwerk Run ist der große Eingangskorridor, der direkt in die Tiefen von Gnomeregan führt. Er erstreckt sich vom oberen Train Depot bis hinunter zur Hall of Gears und war einst eine geschäftige Transitader, die die äußeren Transitsysteme der Gnom-Hauptstadt mit ihrem industriellen Herzen verband. Heute steht er als zerbrochenes, gefährliches Tor in die gefallene Stadt.",al={"was ist der clockwerk run","überblick über den clockwerk run","was ist dieser ort"}},["556e3735"]={q="Was ist mit dem Clockwerk Run passiert?",a="Als Troggs aus den tiefen Höhlen hervorbrachen, um Gnomeregan zu überrennen, setzten die Gnome in einem verzweifelten Versuch, die Eindringlinge auszurotten, giftiges radioaktives Gas frei. Der Plan schlug katastrophal fehl: Die Gnome mussten fliehen oder kamen ums Leben, der Korridor stürzte inmitten des Chaos teilweise ein und verstrahlte Troggs beanspruchten den Durchgang für sich.",al={"geschichte des clockwerk run","was geschah am clockwerk run","fall des clockwerk run"}},c5bdf1c1={q="Wer kontrolliert den Clockwerk Run jetzt?",a="Keine zivilisierte Autorität kontrolliert den Run mehr. Der Korridor wird vollständig von wilden Troggs überrannt, die durch den giftigen Fallout, der während des Falls von Gnomeregan freigesetzt wurde, mutiert sind. Sie greifen jeden Außenstehenden an, der es wagt, den ruinierten Durchgang zu betreten.",al={"wer lebt im clockwerk run","wer kontrolliert den clockwerk run","wer betreibt den clockwerk run"}},aa198084={q="Ist der Clockwerk Run gefährlich?",a="Er ist außergewöhnlich gefährlich. Der Durchgang wimmelt von feindseligen, verstrahlten Troggs, die durch den anhaltenden Fallout in den Wahnsinn getrieben wurden, während Teile der Decke und der Wände strukturelle Schäden erlitten haben. Jeder, der sich diesen Korridor hinunterwagt, muss bereit sein, sich inmitten instabiler Ruinen durch Horden mutierter Bestien zu kämpfen.",al={"ist der clockwerk run gefährlich","gefahren im clockwerk run","bedrohungen im clockwerk run"}}},fp="13,115,18.430.0,34.108.0,34.189.0,39.137.0"}
P.entries["subzone:cold-hearth-manor"] = {n="Coldhearth-Anwesen",s="An Tirisfals Hauptstraße halten Wachen der Verlassenen das Coldhearth-Anwesen westlich von Brill. Einst ein Bauernhof, der Lordaeron ernährte, fiel es der Seuche des Untodes zum Opfer, und heute sucht die Geißel seine Felder heim.",h="An Tirisfals Hauptstraße halten Wachen der Verlassenen das Coldhearth-Anwesen westlich von Brill.",kw={"brill","coldhearth-anwesen","gehöft","verlassene","geißel","tirisfal","zombies"},ang={["faction:Horde"]="Das Anwesen bietet einen sicheren Rastpunkt an der Straße zwischen Brill und den östlichen Ausläufern Tirisfals. Reisende können dort inmitten der verseuchten Landschaft eine Pause einlegen.",["race:Undead"]="Für die Verlassenen weckt die Rückeroberung des Coldhearth-Anwesens Erinnerungen an ihr verlorenes sterbliches Leben. Sie verwandeln einstige Zufluchtsorte der Menschen in düstere Außenposten gegen die Geißel und den Scharlachroten Kreuzzug."},sec={{t="Ein erkalteter Herd",b="Wachen der Verlassenen halten das Bauernhaus des Coldhearth-Anwesens westlich von Brill an Tirisfals Hauptstraße. Vor dem Dritten Krieg war das Gut für herzliche Gastfreundschaft und reiche Ernten im Herzen von Lordaeron bekannt.\n\nAls die Seuche durch das Königreich fegte, starben die Familie und ihre Landarbeiter und erhoben sich erneut als Hüllen, die an die Geißel gebunden waren. Wilde Untote streifen noch immer durch die verwüsteten Felder, doch die Streitkräfte der Verlassenen vertrieben die geistlosen Toten aus dem Bauernhaus. Heute nutzen sie es als Handelsposten und Stützpunkt an der Straße zu den östlichen Lichtungen."}},faq={{q="Was geschah mit den Menschen, die hier lebten?",a="Die Familie und die Landarbeiter, die das Gut bewirtschafteten, starben, als die Seuche des Untodes über Lordaeron hinwegfegte. Sie erhoben sich erneut als geistlose Zombies, die noch immer die umliegenden Felder heimsuchen.",al={"wer lebte im coldhearth-anwesen","vorgeschichte des anwesens","was geschah mit der familie"}},{q="Warum heißt es Coldhearth-Anwesen?",a="Das Gut war einst für seinen herzlichen Empfang und seine wärmenden Feuer bekannt. Die Verlassenen gaben ihm vermutlich einen düsteren Namen als finsteren Gegensatz zu seinem einstigen Leben und dem toten, verseuchten Bauernhof, der daraus geworden ist.",al={"namensbedeutung coldhearth-anwesen","warum coldhearth"}},{q="Wer kontrolliert das Anwesen derzeit?",a="Die Verlassenen halten das Hauptbauernhaus als sicheren Rastplatz für Reisende und Händler auf der Straße von Brill. Feindliche Untote der Geißel suchen noch immer die umliegenden Felder und Scheunen heim.",al={"wem gehört das coldhearth-anwesen","ist das coldhearth-anwesen freundlich gesinnt"}},{q="Warum räumen die Verlassenen die Felder nicht?",a="Die Verlassenen in Tirisfal sind stark beansprucht und kämpfen gegen geistlose Überreste der Geißel und Kreuzfahrer des Scharlachroten Kreuzzugs. Sie sichern das Bauernhaus und die Hauptstraße zur sofortigen Nutzung, während verstreute Tote auf den Feldern eher ein Ärgernis als eine unmittelbare Bedrohung für Brill bleiben.",al={"warum sind zombies auf den feldern","warum ist die geißel hier"}}},fx={["29a639a2"]={q="Was ist das Coldhearth-Anwesen?",a="Das Coldhearth-Anwesen ist ein Gehöft im Zentrum von Tirisfal, direkt an der Hauptstraße gelegen. Einst in ganz Lordaeron für seine reichen Ernten und einladende Atmosphäre berühmt, fiel das Anwesen während des Dritten Krieges, als die Pest der Untoten über das Land fegte. Heute unterhalten Händler der Verlassenen eine zerbrechliche Präsenz am Straßenrand beim Bauernhaus und handeln mit Reisenden, während sie ein wachsames Auge auf die verseuchten Lande um sich herum haben.",al={"was ist das coldhearth-anwesen","überblick über das coldhearth-anwesen","lore des coldhearth-anwesens"}},["673749f2"]={q="Was ist beim Coldhearth-Anwesen passiert?",a="Während des Dritten Krieges verwüstete die Pest der Untoten das Gehöft und tötete jeden, der dort lebte und das Land bearbeitete. Geistlose Zombies der Geißel erhoben sich aus den Gefallenen, um durch die verwilderten Felder zu streifen. Nach dem Fall von Lordaeron nahmen die Verlassenen das Bauernhaus wieder in Besitz und verwandelten das grimmige Überbleibsel menschlichen landwirtschaftlichen Lebens in einen Außenposten entlang der Durchgangsstraße von Tirisfal.",al={"geschichte des coldhearth-anwesens","was ist hier passiert"}},["7e9cca93"]={q="Ist das Coldhearth-Anwesen gefährlich?",a="Das Bauernhaus selbst bietet neben den Händlern der Verlassenen ein gewisses Maß an Sicherheit, aber die umliegenden Felder sind gefährlich. Geistlose Zombies der Geißel befallen immer noch das öde Gelände und greifen jeden an, der sich von der Straße entfernt. Reisende müssen auf der Hut sein, da die Präsenz der Geißel direkt vor den Türen des Anwesens eine allgegenwärtige Bedrohung bleibt.",al={"gefahr im coldhearth-anwesen","ist es hier sicher","bedrohungen im coldhearth-anwesen"}}},fp="17,183,16.529.0,43.178.0,35.176.0,33.163.0,44.274.0"}
P.entries["subzone:coldridge-pass"] = {n="Eisklamm",s="Troggs versperren nun den Weg durch den Eisklamm, den Ausgang aus dem Coldridgetal.",h="Troggs versperren nun den Weg durch den Eisklamm, den Ausgang aus dem Coldridgetal.",kw={"ambossar","eisklamm","das coldridgetal","dun morogh","kharanos","gebirgspass","trogg","tunnel"},ang={["race:Dwarf"]="Als Zwerg verlasst Ihr nach Eurer Grundausbildung in Ambossar das Tal durch den Eisklamm, um in den Landen von Eisenschmiede zu dienen.",["race:Gnome"]="Als Gnom müsst Ihr den von Troggs besetzten Pass durchqueren, um Kharanos und die höher gelegene Straße nach Eisenschmiede zu erreichen. Dort könnt Ihr der Allianz helfen."},sec={{t="Das Tor aus dem Tal",b="Rekruten verlassen das Coldridgetal durch die Eisklamm und ziehen in Richtung Kharanos. Der Tunnel durchquert den südlichen Gebirgskamm von Dun Morogh und führt sie von geschützten Übungsplätzen ins weitläufige Königreich. Troggs haben den Durchgang überrannt und bedrohen jeden, der zwischen dem Tal und dem übrigen Dun Morogh unterwegs ist."}},faq={{q="Wohin führt der Eisklamm?",a="Der Eisklamm führt aus dem Coldridgetal im Südwesten ins übrige Dun Morogh. Er mündet zwischen verschneiten Hügeln unmittelbar westlich von Kharanos.",al={"wohin führt der eisklamm","ziel des eisklamms","wie das coldridgetal verlassen"}},{q="Warum gibt es Troggs im Eisklamm?",a="Troggs sind aus tiefen Spalten unter Dun Morogh hervorgeströmt und haben Höhlen und Tunnel in der ganzen Region besetzt. Der Eisklamm bietet ihnen Schutz und einen Ort, um Reisenden aufzulauern.",al={"warum sind hier troggs","monster im eisklamm","troggbefall"}},{q="Ist die Reise durch den Eisklamm sicher?",a="Nein. Feindselige Troggs drängen sich im Tunnel, sodass Rekruten und Reisende sich hindurchkämpfen oder durch die Dunkelheit sprinten müssen, um das andere Ende zu erreichen.",al={"ist der eisklamm gefährlich","kann man durch den eisklamm gehen"}},{q="Wer bewacht den Pass oder hält ihn instand?",a="Gebirgsjäger bewachen das Tal und die Straßenausgänge, doch der Tunnel bleibt umkämpft und ist noch nicht von Feinden geräumt. Reisende müssen sich beim Durchqueren selbst verteidigen.",al={"zwergenwachen am eisklamm","wer kontrolliert den pass"}}},fx={["7f71f8e0"]={q="Was ist die Geschichte der Eisklamm?",a="Die Eisklamm wurde durch die Berge von Dun Morogh gegraben und diente als lebenswichtige Verbindung, die das isolierte Trainingsgelände des Coldridgetals mit dem restlichen Reich und der Grenzstadt Kharanos verband. Über Generationen hinweg nutzten Zwergenrekruten und Bergsteiger diesen Korridor, um sich frei zwischen dem Tal und dem Rest des Königreichs zu bewegen. Das kürzliche Auftauchen feindseliger Troggs im Tunnel störte jedoch diesen Frieden und zwang Reisende dazu, sich ihren Weg durch eine einst sichere Transitroute freizukämpfen.",al={"geschichte der eisklamm","was geschah an der eisklamm","hintergrund zur eisklamm"}}},fp="14,80,29.327.0,31.136.0,39.175.0,41.125.0,33.141.0"}
P.entries["subzone:coldridge-valley"] = {n="Das Coldridgetal",s="Im Coldridgetal werden junge Zwerge und Gnomenflüchtlinge für den Dienst in Eisenschmiede ausgebildet. Tiefer Schnee liegt über diesem geschützten Tal, hoch im Südwesten von Dun Morogh. Steile Klippen schließen es ein. Nur eine Straße führt hinaus in die weite Bergwelt, und zwar durch die Eisklamm.",h="Im Coldridgetal werden junge Zwerge und Gnomenflüchtlinge für den Dienst in Eisenschmiede ausgebildet.",kw={"ambossar","eisklamm","das coldridgetal","dun morogh","frostmane","eisenschmiede","startgebiet","troggs"},ang={["race:Dwarf"]="Als Zwerg wagt Ihr Eure ersten Schritte jenseits des heimischen Herds auf dem traditionellen Übungsgelände der Bronzebeard-Gebirgsjäger und -Kleriker und bereitet Euch auf den Dienst am High Seat vor.",["race:Gnome"]="Als aus Gnomeregan verbannter Gnom findet Ihr im Schnee des Coldridgetals eine sichere Zuflucht, wo Ihr an der Seite Eurer zwergischen Gastgeber Zauber und Maschinen meistern könnt."},sec={{t="Ein abgeschiedener Prüfungsort",b="Die Rekruten versammeln sich in Ambossar, der Ausbildungshalle des Tals. Dort lernen sie zu kämpfen, sich ungesehen zu bewegen und Zauberei zu wirken. Erfahrene Zwerge unterrichten sie, Seite an Seite mit Gnomengelehrten, die ihre Heimat verloren haben. Draußen auf dem verschneiten Talboden streifen Eber und hungrige Winterwölfe umher. Sie stellen auf die Probe, ob ein Neuling im Grenzland überleben kann."},{t="Vordringende Feinde",b="Doch in diesem Tal herrscht kein Frieden. Frostmane-Trolle lagern hier, bei Frostmane Hovel und darüber hinaus. Sie beanspruchen das Land als Erbe ihrer Ahnen und liefern sich darum Scharmützel mit den Gebirgsjägern. Und Rockjaw-Troggs haben die Eisklamm überrannt. Sie ist der Tunnel nach Kharanos, und solange sie versperrt ist, gelangt nichts ungehindert nach Eisenschmiede."}},faq={{q="Wie verlasst Ihr das Coldridgetal?",a="Die Eisklamm ist der einzige Landweg aus dem Tal. Der verschneite Tunnel führt nach Nordosten durch den Gebirgskamm, dann verläuft die Straße ostwärts nach Kharanos und weiter zu den großen Toren von Eisenschmiede.",al={"coldridgetal verlassen","wie hinausgelangen","weg nach kharanos"}},{q="Warum beginnen Gnome hier an der Seite von Zwergen?",a="Überlebende Gnome flohen nach Dun Morogh, nachdem Troggs und radioaktiver Niederschlag den tragischen Untergang von Gnomeregan herbeigeführt hatten. König Magni Bronzebart hieß das Volk von High Tinker Mekkatorque willkommen, und viele verbannte Gnomenlehrlinge werden nun neben jungen Zwergen in Ambossar ausgebildet.",al={"gnome im coldridgetal","warum sind gnome hier","startgebiet der gnome"}},{q="Welche Bedrohungen setzen dem Tal zu?",a="Frostmane-Trolle nehmen den Zwergen ihre Siedlungen in ihrem Berggebiet übel, während Rockjaw-Troggs sich aus der Tiefe emporgegraben und die Eisklamm versperrt haben. Auch Wölfe und Eber setzen unvorsichtigen Reisenden zu. Der versperrte Pass verhindert den freien Verkehr zwischen dem Tal und dem Bergreich.",al={"feinde im coldridgetal","bedrohungen im tal","wer greift an"}},{q="Was ist Ambossar?",a="Ambossar ist die zentrale Festungshalle samt Siedlung im Coldridgetal. Sie beherbergt Klassenlehrer, Schmiedemeister und örtliche Offiziere der Gebirgsjäger, die die Verteidigung des Tals koordinieren und frischgebackene Abenteurer auf die weite Welt vorbereiten.",al={"ort ambossar","welcher ort ist hier"}}},fx={["80e4cacf"]={q="Was ist das Coldridgetal?",a="Das Coldridgetal ist ein geschütztes, schneebedecktes Becken in der südwestlichen Ecke von Dun Morogh. Umgeben von zerklüfteten Berggipfeln dient es als abgelegenes Trainingsgelände und Lager für junge Zwerge und Gnom-Flüchtlinge, bevor sie sich in das größere Königreich wagen.",al={"überblick über das coldridgetal","wo ist das coldridgetal","infos zum coldridgetal"}},["73aec6cd"]={q="Ist das Coldridgetal Teil von Dun Morogh?",a="Ja, es liegt in den südwestlichen Höhen von Dun Morogh. Es bleibt physisch vom Rest der schneebedeckten Region durch einen Ring von Bergen getrennt und ist nur durch den schmalen Tunnel der Eisklamm im Nordosten mit dem Festland verbunden.",al={"liegt coldridge in dun morogh","coldridgetal in dun morogh"}},["0ba4a80e"]={q="Ist das Coldridgetal gefährlich?",a="Obwohl es als ruhiges, geschütztes Trainingsgelände gedacht war, haben sich kürzlich Unruhen in das Tal ausgebreitet. Feindselige Frostmähnentrolle lauern in nahegelegenen Lagern, aggressive Wildtiere streifen durch die Schneeverwehungen und bösartige Troggs haben den einzigen Bergpass überrannt, der in den Rest von Dun Morogh führt.",al={"gefahr in coldridge","ist es hier sicher","bedrohungen in coldridge"}},["7fc500c6"]={q="Wer regiert die Zwerge?",a="Die Zwerge von Eisenschmiede werden von König Magni Bronzebart regiert. Als standhafter Anführer und Veteran der Großen Kriege regiert König Magni das Königreich Eisenschmiede von seinem mächtigen Bergthronsaal aus und steht als einer der entschlossensten Verfechter der Allianz.",al={"wer ist der zwergenkönig","könig von eisenschmiede","zwergenanführer"}},ff57e405={q="Was ist Kharanos und warum wird es ständig erwähnt?",a="Kharanos ist die belebte Grenzstadt, die direkt hinter dem Eisklamm an der Hauptstraße nach Eisenschmiede liegt. Sie dient als primärer Außenposten, an dem sich junge Rekruten zum aktiven Dienst melden, ihr handwerkliches Training vorführen und das weltberühmte Bier in der Brauerei Donnerbräu kosten können.",al={"was ist kharanos","warum nach kharanos gehen","stadt kharanos"}},["966deec9"]={q="Wer ist Senir Weißbart?",a="Senir Weißbart ist ein bedeutender Anführer der Zwerge, der in der nahe gelegenen Grenzstadt Kharanos stationiert ist. Er koordiniert die Verteidigungsbemühungen in der Region und arbeitet aktiv daran, den gefährlichen Stützpunkt auszurotten, den die Frostmähneneistrolle auf den Gipfeln von Dun Morogh errichtet haben.",al={"senir weißbart","senir kharanos"}},a3c72edd={q="Wie bin ich im Coldridgetal gelandet?",a="Ihr seid im Coldridgetal angekommen, weil es als geschütztes Übungsgelände für neue Rekruten in Dun Morogh dient. Das in den südwestlichen Bergen versteckte Tal bietet angehenden Verteidigern einen abgeschiedenen Ort, um ihr Handwerk zu erlernen, Ausrüstung zu sammeln und ihre Fähigkeiten zu beweisen, bevor sie sich in die weitere, rauere Welt hinauswagen.",al={"wie bin ich hierher gekommen","warum bin ich hier","wie bin ich hier gelandet","was hat mich hierher gebracht"}},["8bdf0a70"]={q="Was soll ich im Coldridgetal tun?",a="Eure Aufgabe ist es, eine Grundausbildung zu absolvieren, eure Kampffertigkeiten zu schärfen und die örtlichen Behörden in Ambossar zu unterstützen. Ihr sollt die widerspenstige einheimische Tierwelt ausdünnen, die eindringenden Frostmähneneistrolle und Troggs zurückschlagen und schließlich einen Weg durch den Eisklamm freimachen, um Euch in Kharanos zum Dienst zu melden.",al={"was mache ich hier","was ist meine mission","was soll ich in coldridge tun"}},["2eeaa2be"]={q="Warum fängt ein neuer Zwerg hier im Coldridgetal an?",a="Als junger abenteuerlustiger Zwerg seid Ihr nach Ambossar gekommen, um Eure kriegerischen und magischen Traditionen unter erfahrenen Ausbildern zu meistern. Eisenschmiede benötigt standhafte Champions, um sein Reich zu schützen, und diese Bergwiege bietet den idealen Erprobungsort, um frische Rekruten zu erfahrenen Verteidigern von Khaz Modan zu schmieden.",al={"warum fangen zwerge hier an","warum bin ich hier zwerg","startgebiet zwerg","warum coldridgetal zwerg"}},ef9153cd={q="Warum fängt ein neuer Gnom hier im Coldridgetal an?",a="Da Gnomeregan kürzlich der Trogg-Invasion zum Opfer gefallen ist, sind überlebende Gnome aus ihrer Heimat geflohen und haben bei ihren zwergischen Verbündeten Zuflucht gefunden. Als ein im Exil lebender Gnom, der begierig darauf ist, der Allianz zu helfen und die Zukunft seines Volkes wiederaufzubauen, beginnt Ihr Euer Training an der Seite zwergischer Rekruten in der Sicherheit vom Coldridgetal.",al={"warum fangen gnome hier an","warum bin ich hier gnom","startgebiet gnom","warum coldridgetal gnom"}}},fp="16,264,25.331.0,16.327.0,34.199.0,47.257.0,38.286.0,17.241.0"}
P.entries["subzone:command-center"] = {n="Command Center",s="Sturmwinds Armee ist durch Feldzüge im Ausland ausgedünnt, und Rekruten üben im Command Center. Auch als Sturmwind-Kaserne bekannt, beherbergt es die Offiziere der Stadt und eine erfahrene Mannschaft, die sich auf die Ausbildung von Rekruten und der örtlichen Miliz konzentriert.",h="Sturmwinds Armee ist durch Feldzüge im Ausland ausgedünnt, und Rekruten üben im Command Center.",kw={"ander germaine","kaserne","command center","die altstadt","sturmwind-kaserne","kriegerlehrer","wu shen"},ang={["class:Warrior"]="Als Krieger könnt Ihr in Sturmwinds Command Center trainieren. Veteranen wie Ander Germaine und Wu Shen lehren Rekruten, als disziplinierte Frontsoldaten zu kämpfen."},sec={{t="Eine dünne Verteidigungslinie",b="In der Altstadt bildet Sturmwinds Command Center die Soldaten des Königreichs aus. Ein Großteil der königlichen Armee dient im Ausland, weshalb es in seinen Hallen ruhiger ist als sonst. Der erfahrene Ausbilder Ander Germaine und der Kampfkünstler Wu Shen schulen neue Krieger, um die Verteidigung der Stadt zu stärken."},{t="Militärischer Mittelpunkt der Altstadt",b="Wenn Ihr Unterweisung im Umgang mit schweren Waffen oder in Kampftaktik sucht, verweisen Euch Sturmwinds Wachen womöglich an die Kaserne. Sie steht nahe der Pig and Whistle Tavern und den zwielichtigen Machenschaften der Altstadt. Der Übungsplatz hilft, die Ordnung in einem Viertel zu wahren, das für Kneipenschlägereien und schurkische Aktivitäten bekannt ist."}},faq={{q="Warum ist das Command Center so leer?",a="Der Großteil von Sturmwinds stehendem Heer dient an fernen Außenposten und auf fremden Schlachtfeldern überall auf der Welt. Eine erfahrene Mannschaft bleibt zurück, um Rekruten auszubilden und die örtliche Verteidigung zu organisieren.",al={"warum so wenige wachen hier","wo ist sturmwinds armee","kaserne leer"}},{q="Ist das Command Center dasselbe wie die Sturmwind-Kaserne?",a="Ja. Der offizielle Name des Gebäudes lautet Command Center, doch Wachen und Einwohner nennen es bei Wegbeschreibungen oft Sturmwind-Kaserne.",al={"sturmwind-kaserne","sind command center und kaserne dasselbe","standort der kaserne"}},{q="Wer leitet hier die Ausbildung?",a="Ander Germaine koordiniert die Krieger Sturmwinds und bildet sie gemeinsam mit Ausbildern wie Wu Shen und Ilsa Corbin aus.",al={"wer bildet hier krieger aus","kriegerlehrer command center","wer leitet die kaserne"}},{q="Wo befindet sich das Command Center?",a="Ihr findet das Command Center in der Altstadt, nahe der Pig and Whistle Tavern und den Ausbildungseinrichtungen des Viertels.",al={"wo ist das command center","standort des command centers","wie das command center finden"}}},fx={["3e3491ec"]={q="Was ist das Command Center?",a="Das Command Center dient als operatives Hauptquartier und Ausbildungsbaracke für das Militär von Sturmwind. Es liegt in Die Altstadt und ist das wichtigste Zentrum, in dem Armeeoffiziere und Krieger-Ausbilder Rekruten drillen und die Verteidigung des Königreichs koordinieren.",al={"was ist command center","command center sturmwind","was ist dieses gebäude"}},["1a0e6604"]={q="Ist das Command Center gefährlich?",a="Überhaupt nicht. Das Command Center ist eine befestigte Festung, die sicher im Herzen von Sturmwind liegt. Sie wird von erfahrenen Veteranen und Elite-Kampfausbildern bemannt, die der Allianz treu ergeben sind, was sie zu einer der sichersten Einrichtungen in der Hauptstadt macht.",al={"ist command center gefährlich","gefahr command center","ist es sicher"}}},fp="14,224,22.264.0,22.284.0,35.179.0,57.145.0,28.114.0,36.112.0"}
P.entries["subzone:commons"] = {n="Commons",s="Reisende und Händler füllen die Commons gleich hinter den Toren von Eisenschmiede. Von hier aus öffnen sich die gewaltigen Höhlen der Bergstadt vor ihnen, und Händler, Reisende und Bankiers kommen aus der gesamten Allianz.",h="Reisende und Händler füllen die Commons gleich hinter den Toren von Eisenschmiede.",kw={"auktionshaus","bank","commons","eisenschmiede","markt","stonefire tavern","tresor von eisenschmiede"},ang={["faction:Alliance"]="Für die Allianz sind die Commons ein geschäftiger Handelsplatz. Helden aus Teldrassil, Sturmwind und Gnomeregan kommen hierher, um wertvolle Beute zu versteigern und Vorräte zu beschaffen.",["race:Dwarf"]="Als Bronzebeard-Zwerg könnt Ihr sehen, wie zwergische Gastfreundschaft, Handwerk und Handel tief im Inneren eines gefrorenen Berges gedeihen."},sec={{t="Das Handelszentrum des Berges",b="Die Commons empfangen Euch direkt nordöstlich der Tore von Eisenschmiede. Ihre Marktstraße ist aus Berggestein gehauen und beherbergt das Auktionshaus der Allianz, die Stonefire Tavern und die zentrale Bank im Tresor von Eisenschmiede. Breite Straßen führen zur Großen Schmiede, zum Mystic Ward und zum Military Ward. Fast jeder, der die Stadt durchquert, kommt an ihren Geschäften vorbei."},{t="Das Wegekreuz für die Allianz",b="Handelswaren erreichen die Commons aus den gesamten Östlichen Königreichen. Eisenschmiedes zentrale Lage und die unterirdische Tiefenbahn nach Sturmwind führen Reisende und Händler durch ihre Straßen. Abenteurer handeln mit Waren aus ganz Azeroth, kaufen Waffen bei Steelfury's Weapon Emporium oder erwerben Reagenzien von Barim. Manche versammeln sich unter den warm leuchtenden Laternen des Gasthauses, bevor sie in den Schnee von Khaz Modan aufbrechen."}},faq={{q="Warum sind die Commons so viel belebter als andere Bezirke?",a="Die Commons sind so belebt, weil sich hier das Auktionshaus der Allianz, der Tresor von Eisenschmiede und die Stonefire Tavern befinden. Gleich hinter den Haupttoren gelegen, bieten sie einen leicht erreichbaren Ort für Treffen und Handel.",al={"warum sind die commons belebt","warum so viele spieler hier","handelszentrum eisenschmiede"}},{q="Wohin führen die Commons?",a="Die Commons führen zu fast jedem größeren Bezirk von Eisenschmiede. Im Südwesten liegen die Stadttore, im Nordosten die Große Schmiede, im Osten der Military Ward und im Norden der Mystic Ward.",al={"ausgänge der commons","commons verlassen","wege in den commons"}},{q="Welche wichtigen Geschäfte und Dienstleistungen gibt es hier?",a="In den Commons befinden sich das Auktionshaus und die Bank sowie das Eisenschmiede Visitor's Center, Steelfury's Weapon Emporium, die Eisenschmiede Armory, Barim's Reagents und Fizzlespinner's General Goods.",al={"händler in den commons","dienstleistungen in den commons","einrichtungen der commons in eisenschmiede"}},{q="Befindet sich die Bank hier?",a="Ja. Der Tresor von Eisenschmiede, die Hauptbank der Stadt, steht in den Commons gegenüber dem Auktionshaus.",al={"wo ist die bank von eisenschmiede","tresor von eisenschmiede","standort der bank"}}},fx={["1b528195"]={q="Was ist Die Altstadt?",a="Die Altstadt dient als primäre kommerzielle Durchgangsstraße von Eisenschmiede. Direkt hinter den Stadttoren gelegen und mit fast jedem anderen Stadtteil verbunden, fungiert sie als das pulsierende wirtschaftliche Herz der Zwergenhauptstadt. Hier versammeln sich Reisende und Bürger, um im Auktionshaus Waren zu handeln, auf die Stadtgewölbe zuzugreifen, in der Stonefire Tavern zu übernachten oder das Angebot verschiedener örtlicher Händler zu durchstöbern.",al={"was ist die commons","eisenschmiede commons","über die commons"}},e4c18740={q="Ist Die Altstadt gefährlich?",a="Nicht im Geringsten. Die Altstadt ist einer der sichersten und am dichtesten besiedelten Stadtteile im gesamten Khaz Modan. Geschützt durch die undurchdringlichen Steinmauern des Berges und ständig patrouilliert von wachsamen Wachen von Eisenschmiede, haben Besucher nichts von wilden Tieren oder feindlichen Übergriffen zu befürchten, während sie hier ihren Geschäften nachgehen.",al={"ist commons gefährlich","gefahr in der commons","ist es hier sicher"}}},fp="7,203,34.338.0,29.400.0,62.180.0,28.171.0,43.190.0,25.103.0"}
P.entries["subzone:corin-s-crossing"] = {n="Corins Kreuzung",s="Die Geißel hat Corins Kreuzung überrannt, wo zerstörte Straßen einen alten Treffpunkt im südlichen Zentrum der Östlichen Pestländer markieren. Einst kamen Reisende auf ihrem Weg zwischen Stratholme, Tyrs Hand, Darrowshire und Andorhal hier vorbei. Nun hausen Schrecken im Rathaus und in der Schmiede, und unsichtbare Wächter treiben durch die Ruinen.",h="Die Geißel hat Corins Kreuzung überrannt, wo zerstörte Straßen einen alten Treffpunkt im südlichen Zentrum...",kw={"corins kreuzung","östliche pestländer","die infektnarbe","mereldarsee","unseen servants"},ang={["class:Paladin"]="Als Paladin seht Ihr in Corins Kreuzung das entweihte Herzland Lordaerons. Die Ruinen bleiben eine elende Festung der Geißel, die Stratholmes heiliger Bastion weiter die Straße hinauf spottet.",["class:Rogue"]="Vertraut hier nicht auf Eure Schatten. Unseen Servants durchstreifen die Gassen, bleiben sterblichen Augen verborgen und durchschauen Eure Tarnung. Ein Gang über den Stadtplatz kann tödlich enden."},sec={{t="Eine zerstörte Wegkreuzung",b="Vor dem Dritten Krieg verband Corins Kreuzung die Straßen des östlichen Lordaeron. Händler, Kuriere und Pilger machten an dieser Zwischenstation zwischen Stratholme und den südlichen Festungen halt. Die Siedlung lag zwischen dem Mereldarsee und dem Ort, der heute als die Infektnarbe verseucht ist. Als die Seuche durch die Provinz fegte, erreichte die untote Vorhut die Stadt. Corins Kreuzung fiel bald unter ihrem Ansturm."},{t="Eine Zuflucht der Damned",b="Die Geißel hält Corins Kreuzung nun besetzt, und umherwandernde Untote drängen sich in den schlammigen Straßen. Verrottende Kolosse und Ghule verweilen in der ausgehöhlten Schmiede und im Rathaus. Zwischen den Ruinen droht Spähern eine weitere Gefahr. Unseen Servants treiben jenseits gewöhnlicher Sicht umher, durchschauen gewöhnliche Tarnung und überfallen jeden, der versucht, unbemerkt an der Haupthorde vorbeizuschlüpfen."}},faq={{q="Was war Corins Kreuzung vor der Seuche?",a="Vor der Seuche war Corins Kreuzung ein wohlhabender Knotenpunkt im östlichen Lordaeron. Rathaus und Schmiede bildeten das Herz einer Zwischenstation zwischen Stratholme, Tyrs Hand, Darrowshire und Andorhal. Die Geißel löschte ihre Bevölkerung aus.",al={"corins kreuzung geschichte","corins kreuzung hintergrund","was war corins kreuzung"}},{q="Warum ist Corins Kreuzung für getarnte Reisende so gefährlich?",a="Unseen Servants suchen Corins Kreuzung als unsichtbare, an die Geißel gebundene Phantome heim. Sie durchschauen magische und gewöhnliche Tarnung, überraschen dann unvorsichtige Schurken oder Späher und alarmieren Untote in der Nähe.",al={"tarnung in corins kreuzung","unseen servants","schurke corins kreuzung"}},{q="Welche bedeutenden Landmarken umgeben die Stadt?",a="Corins Kreuzung liegt im südlichen Zentrum der Östlichen Pestländer. Der verseuchte Graben der Infektnarbe liegt in der Nähe, und der Mereldarsee erstreckt sich entlang des Stadtrands.",al={"corins kreuzung lage","wo liegt corins kreuzung"}},{q="Wer kontrolliert Corins Kreuzung heute?",a="Die Geißel hält Corins Kreuzung besetzt. Keine lebenden Verteidiger sind mehr übrig, und umherwandernde untote Soldaten und Geister wimmeln durch die Siedlung.",al={"wem gehört corins kreuzung","corins kreuzung fraktion"}}},fp="16,314,22.409.0,21.342.0,44.241.0,60.186.0,39.163.0,36.127.0"}
P.entries["subzone:corrahn-s-dagger"] = {n="Corrahns Dolch",s="Halsabschneider des Syndikats halten Corrahns Dolch, den zweiten Grat unter den vier felsigen Fingern im Norden Hillsbrads. Von seinen Höhen aus überwachen sie das Tal und unterhalten ein Versteck.",h="Halsabschneider des Syndikats halten Corrahns Dolch, den zweiten Grat unter den vier felsigen Fingern im...",kw={"corrahn","corrahns dolch","dolch","vier finger","hillsbrad","syndikat"},ang={["race:Dwarf"]="Als Zwerg auf dem Weg durch das nördliche Vorgebirge müsst Ihr in diesem Versteck des Syndikats mit Banditen statt mit Verbündeten rechnen.",["race:Undead"]="Als Verlassene, die in Hillsbrad tätig sind, begegnet Ihr der Feindseligkeit der Halsabschneider des Syndikats auf dem Grat."},sec={{t="Ein nördlicher Stützpunkt",b="Im nördlichen Vorgebirge des Hügellands ist Corrahns Dolch der zweite von vier felsigen Graten, die als die Finger von Hillsbrad bekannt sind. Halsabschneider des Syndikats haben den Grat überrannt und nutzen seine Höhen, um das Tal unter ihnen zu überwachen."}},faq={{q="Wer kontrolliert Corrahns Dolch?",a="Menschliche Schurken des Syndikats halten Corrahns Dolch und nutzen seine Höhen als Versteck.",al={"wer ist bei corrahns dolch","corrahns dolch fraktion","wer lebt hier"}},{q="Was sind die Finger von Hillsbrad?",a="Die Finger von Hillsbrad sind vier markante Grate, die vom nördlichen Gebirgszug südwärts ins Tal von Hillsbrad hineinragen. Corrahns Dolch ist der zweite Grat.",al={"vier finger hillsbrad","vier grate hillsbrad","hillsbrad finger"}}},fx={["2610a3ae"]={q="Was ist Corrahns Dolch?",a="Corrahns Dolch ist der zweite der vier markanten Bergrücken, die als die Finger von Hillsbrad bekannt sind und sich entlang des nördlichen Randes der Ausläufer erheben. Schurkische Menschen des Syndikat halten das höher gelegene Gelände als Versteck mit Blick auf das darunter liegende Tal besetzt.",al={"was ist corrahns dolch","corrahns dolch hintergrund","corrahn dolch hügel"}},dcd9fc97={q="Ist Corrahns Dolch gefährlich?",a="Ja. Der Bergrücken wird von Halsabschneidern des Syndikat gehalten, die die Höhen als Versteck nutzen und Reisende sowohl der Allianz als auch der Horde angreifen, die zu nahe kommen.",al={"ist corrahns dolch sicher","gefahr corrahns dolch","corrahns dolch feinde"}}},fp="16,167,22.207.0,30.85.0,34.163.0"}
P.entries["subzone:craftsmen-s-terrace"] = {n="Die Terrasse der Handwerker",s="Werkstätten und Besucher sammeln sich auf der Terrasse der Handwerker am Nordrand von Darnassus. Ihre Lehrer, ihr Gasthaus und die Gesandtschaft der Argentumdämmerung dienen Handwerkern und Reisenden.",h="Werkstätten und Besucher sammeln sich auf der Terrasse der Handwerker am Nordrand von Darnassus.",kw={"argentumdämmerung","handwerker","die terrasse der handwerker","terrasse der handwerker","darnassus","teldrassil","lehrer"},ang={["faction:Alliance"]="Als Besucher der Allianz findet Ihr Handelsbedarf, Gildendienste und Unterkunft in einem der gastfreundlichsten Viertel von Darnassus. Auch auswärtige Vertreter haben hier ihren Platz.",["race:NightElf"]="Als Kaldorei seht Ihr auf der Terrasse die Eigenständigkeit auf Teldrassil, wo uraltes Handwerk den täglichen Bedarf der neuen Hauptstadt deckt."},sec={{t="Das Handwerkerherz von Darnassus",b="Holzarbeiter, Lederer, Alchemisten und andere Handwerker arbeiten am Nordrand von Darnassus. Ihre Läden vereinen die Gewerbe, die die Stadt am Laufen halten, und setzen die Methoden der Nachtelfen praktisch ein. Ein Gasthaus, ein Gildenmeister und Verkäufer von Gildensatzungen stehen Besuchern hier zur Verfügung. Brücken führen nach Westen zur Enklave des Cenarius und nach Süden zur Terrasse der Krieger."},{t="Auswärtige Bande und vergessenes Wissen",b="Die Argentumdämmerung unterhält eine Gesandtschaft auf der Terrasse der Handwerker und stimmt sich mit nördlichen Verbündeten gegen die Geißel ab. Zwischen den Werkstätten liegen verstreute Gelehrtenbände. Darunter finden sich Geschichten über den Krieg der Ahnen, Chroniken des Zweiten Krieges und Abhandlungen über die Alten Götter."}},faq={{q="Welche Dienste bietet die Terrasse der Handwerker?",a="Auf der Terrasse der Handwerker finden sich Berufslehrer, Händler für Handwerksbedarf, ein Gasthaus und Dienste zur Gildenregistrierung. Reisende kommen hierher, um in Darnassus praktische Fertigkeiten zu erlernen oder auszuüben.",al={"dienste der handwerker","was gibt es auf der terrasse der handwerker","lehrer in darnassus"}},{q="Warum ist die Argentumdämmerung auf der Terrasse der Handwerker vertreten?",a="Die Argentumdämmerung unterhält eine Gesandtschaft auf der Terrasse der Handwerker, um mit den Nachtelfen Verbindung zu halten und Unterstützung gegen die Geißel zu gewinnen. Sie verbindet die Streitkräfte der Allianz im Westen mit den kriegsgezeichneten Landen von Lordaeron.",al={"argentumdämmerung darnassus","gesandtschaft der argentumdämmerung","warum ist die argentumdämmerung hier"}},{q="Wie erreicht Ihr die Terrasse der Handwerker?",a="Die Terrasse der Handwerker nimmt den nördlichen Teil von Darnassus ein. Brücken führen von der Terrasse der Krieger nach Norden und von der Enklave des Cenarius nach Osten.",al={"wie gelangt man zur terrasse der handwerker","lage der terrasse der handwerker","terrasse der handwerker finden"}},{q="Welche bemerkenswerten Bücher finden sich bei den Werkstätten?",a="Zu den Gelehrtenbänden in den Werkstätten gehören Geschichten über den Krieg der Ahnen, Berichte über die Folgen des Zweiten Krieges und eine Studie über die Alten Götter in den Räumen der Argentumdämmerung.",al={"bücher der terrasse der handwerker","geschichtsbücher darnassus","bücher auf der terrasse der handwerker"}}},fx={["7384ca35"]={q="Was ist Die Terrasse der Handwerker?",a="Die Terrasse der Handwerker ist ein geschäftiger nördlicher Stadtteil innerhalb von Darnassus, der Hauptstadt der Nachtelfen auf Teldrassil. Sie dient als primärer Handels- und Handwerksknotenpunkt für die Kaldorei und versammelt Ausbilder, Händler und Werkstätten unter den Ästen des Weltenbaums. Hier finden Reisende und Bürger geschickte Handwerker, die ihr Handwerk ausüben, Gilden-Dienste, ein einladendes Gasthaus und eine offizielle Botschaft, die von der Argentumdämmerung unterhalten wird.",al={"was ist die terrasse der handwerker","terrasse der handwerker darnassus","über die terrasse der handwerker"}},ef9e89a7={q="Warum heißt es Die Terrasse der Handwerker?",a="Der Stadtteil verdankt seinen Namen seiner Rolle als Zentrum für Industrie und Handel in Darnassus. Er beherbergt die Berufslehrer, Versorgungsanbieter und Handwerkswerkstätten der Stadt und ist damit der Versammlungsort für die Handwerker, Bauherren und Gewerbetreibenden der Nachtelfen.",al={"warum heißt es terrasse der handwerker","bedeutung terrasse der handwerker","name terrasse der handwerker"}},["1dc55189"]={q="Ist Die Terrasse der Handwerker gefährlich?",a="Nein. Die Terrasse der Handwerker ist ein sicherer ziviler Stadtteil innerhalb der Nachtelfenhauptstadt Darnassus. Geschützt durch die Wächterinnen und bewacht von örtlichen Handwerkern und der Argentumdämmerung, ist es völlig friedlich und frei von feindlichen Bedrohungen für Mitglieder der Allianz.",al={"ist terrasse der handwerker sicher","gefahr terrasse der handwerker","bedrohungen terrasse der handwerker"}}},fp="19,158,30.353.0,31.283.0,51.198.0,58.205.0,41.141.0,53.184.0"}
P.entries["subzone:crag-of-the-everliving"] = {n="Crag of the Everliving",s="Der Crag of the Everliving liegt unter einem Dach aus verderbtem Bewuchs in den Höhlen des Wehklagens. Lord Pythas beherrscht seine mittleren Bereiche, und in den Höhen darüber haust ein uraltes Wesen.",h="Der Crag of the Everliving liegt unter einem Dach aus verderbtem Bewuchs in den Höhlen des Wehklagens.",kw={"brachland","crag of the everliving","deviate shamblers","druids of the fang","lord pythas","lord serpentis","verdan","die höhlen des wehklagens"},ang={["class:Druid"]="Für Cenarion-Druiden ist der Crag of the Everliving eine tragische Lehre: Der Alptraum hat die Lebenskraft der Natur und ihre elementaren Wächter zu tödlichen Werkzeugen gemacht.",["profession:Herbalism"]="Der feuchte, von Träumen durchtränkte Boden der Felswand und die unnatürlich üppige unterirdische Luft nähren seltene Wurzeln und Pilze."},sec={{t="Ein verderbtes Blätterdach",b="Verdrehter Bewuchs erfüllt den Crag of the Everliving, genährt vom Alptraum, der Naralex' Schlaf verdirbt. Moosbewachsene Plattformen ragen über gewundenen Pfaden auf, auf denen Deviate Shamblers umherstreifen. Diese lebenden Pflanzenkolosse drängen sich im Unterholz.\n\nLord Pythas wacht über die mittleren Bereiche der Felswand. Einst ein Schüler von Naralex, gab er seine druidischen Gelübde für die giftigen Riten der Druids of the Fang auf."},{t="Der uralte Wächter",b="Verdan der Ewiglebende gibt der Kammer ihren Namen. Dieser kolossale, urzeitliche Pflanzenelementar haust in den oberen Höhen der Felswand, verdorben vom Smaragdgrünen Alptraum, der die Höhle im Griff hat. Verdan ist kein friedlicher Wächter der Natur mehr und bildet nun eine furchterregende Verteidigungslinie.\n\nHinter Verdans hoch aufragender Gestalt wartet Lord Serpentis. Er nennt sich selbst Anführer der Giftzahnhäuptlinge und überwacht den Abstieg der Sekte in den Schlangenwahnsinn."}},faq={{q="Woher hat dieses Gebiet seinen Namen?",a="Die Kammer verdankt ihren Namen Verdan dem Ewiglebenden, einem uralten, kolossalen Pflanzenungetüm auf den höchsten Terrassen der Felswand. Einst war er die Verkörperung der zeitlosen Lebenskraft der Natur, doch nun steht er unter dem Einfluss des Alptraums.",al={"warum crag of the everliving","namensherkunft des ewiglebenden","name der felswand"}},{q="Wer beherrscht diesen Teil der Höhlen?",a="Lord Pythas herrscht über die Felswand. Auf höheren Vorsprüngen über ihm lauern Verdan der Ewiglebende und Lord Serpentis, der Anführer der Druids of the Fang.",al={"wer herrscht hier","boss der felswand","giftzahnhäuptling hier"}},{q="Welche Kreaturen findet man häufig im Crag of the Everliving?",a="Deviate Shamblers bevölkern die Felswand in Scharen, neben verdrehten Schlangen und fanatischen Druids of the Fang. Die Shamblers sind Pflanzenschrecken, die aus den verderbten Quellen hervorgegangen sind.",al={"monster in der felswand","feinde der felswand","was lebt hier"}},{q="Warum gedeihen Pflanzen so tief unter der Erde?",a="Naralex, ein Nachtelfendruide, nutzte die unterirdischen Quellen, um das Brachland zu neuem Leben zu erwecken. Der Smaragdgrüne Alptraum bemächtigte sich seines Rituals, ließ den Wildwuchs wuchern und verwandelte ihn in feindselige, entstellte Pflanzen.",al={"warum gibt es unterirdisch pflanzen","warum so grün","verderbter bewuchs"}}},fx={["6a6b08ee"]={q="Was ist Crag of the Everliving?",a="Crag of the Everliving ist eine üppige, grüne unterirdische Höhle tief in Die Höhlen des Wehklagens. Gespeist von korrupten natürlichen Energien, zeichnet sie sich durch blühendes Pflanzenleben, wucherndes Wachstum und hoch aufragende Felsvorsprünge aus.",al={"was ist crag of the everliving","infos zu crag of the everliving","über crag of the everliving"}},cca8a755={q="Ist Crag of the Everliving gefährlich?",a="Ja, er gehört zu den tödlichsten Teilen der Höhlen. Abweichlerschlinger lauern auf den überwucherten Terrassen, und der Felsvorsprung wird von korrupten Druiden des Giftzahns verteidigt, die von Lord Pythas angeführt werden und sich in der Nähe des Verstecks von Lord Serpentis befinden.",al={"wie gefährlich ist crag of the everliving","ist crag of the everliving gefährlich","bedrohungen in crag of the everliving"}}},fp="22,181,18.373.0,20.419.0,34.208.0,38.143.0,64.161.0,47.205.0"}
P.entries["subzone:cragpool-lake"] = {n="Felskesselsee",s="In der Scherwindklippe hängen die Holzverarbeitungsanlagen der Venture Company über dem Felskesselsee und seinem dunklen Wasser.",h="In der Scherwindklippe hängen die Holzverarbeitungsanlagen der Venture Company über dem Felskesselsee und...",kw={"felskesselsee","gerenzo wrenchwhistle","steinkrallengebirge","venture company","die scherwindklippe"},ang={["class:Druid"]="Als Druide seht Ihr die Abwässer, Holzplattformen und Eingriffe rund um den Felskesselsee als eine Narbe im Steinkrallengebirge. Sie verändern das örtliche Ökosystem und verdrängen die heimischen Wildtiere.",["profession:Engineering"]="Das Holzgerüst und die auskragenden Maschinen über dem Felskesselsee zeugen von Goblinindustrie, schnell und massiv errichtet, mit wenig Rücksicht auf das Land darunter."},sec={{t="Die Industrie dringt vor",b="Am Felskesselsee führen Plattformen der Venture Company unter einer gewaltigen Holzkonstruktion über das Wasser. Gerenzo Pfeifzang überwacht die Arbeiten im gesamten Gebirgstal. Arbeiter der Firma besetzen die Plattformen darüber."}},faq={{q="Was ist die gewaltige Holzkonstruktion über dem See?",a="Die Venture Company errichtete eine gewaltige Holzkonstruktion über dem Felskesselsee, um ihren Holzeinschlag und Bergbau in der Scherwindklippe zu leiten. Plattformen und schwere Maschinen überspannen das Wasser.",al={"venture company plattform","felskesselsee gerüst","felskesselsee brücke"}},{q="Wer beaufsichtigt die Arbeiten am Felskesselsee?",a="Gerenzo Pfeifzang beaufsichtigt die Arbeiten am Felskesselsee. Vom hohen Gerüst aus überwacht der Mitarbeiter der Venture Company die Abholzung und den Rohstoffabbau in der gesamten Scherwindklippe.",al={"wer leitet die venture company hier","wer ist hier der chef","gerenzo wrenchwhistle"}},{q="Welche Gefahren lauern rund um den Felskesselsee?",a="Arbeiter der Venture Company sind auf den Plattformen über dem Felskesselsee tätig. Ihre bewaffnete Präsenz macht den Ort für Eindringlinge gefährlich.",al={"was ist im felskesselsee"}},{q="Hat die Venture Company den Felskesselsee verlassen?",a="Nein. Arbeiter der Venture Company und Gerenzo Pfeifzang besetzen die Konstruktion über dem Felskesselsee.",al={"ist die venture company weg","wer lebt am felskesselsee"}}},fx={["588e76b4"]={q="Was ist Felskesselsee?",a="Felskesselsee ist ein kleines Gewässer, das in Die Scherwindklippe im Steinkrallengebirge liegt. Er wird von einer weitläufigen, erhöhten Holzkonstruktion dominiert, die von der Venture Company über dem Wasser errichtet wurde, um ihre Holzfäll- und Aushubmaschinen im Tal zu unterstützen.",al={"was ist felskesselsee","felskesselsee hintergrund","felskesselsee steinkrallengebirge"}},["686f269e"]={q="Was ist am Felskesselsee passiert?",a="Die Venture Company baute ihre riesige Holzkonstruktion über dem Felskesselsee als Teil ihrer Operationen in Die Scherwindklippe. Gerenzo Pfeifzang beaufsichtigt die Arbeit von den Plattformen aus.",al={"felskesselsee geschichte","was ist am felskesselsee passiert","felskesselsee vergangenheit"}}},fp="13,99,23.214.0,59.166.0,45.185.0,36.130.0,48.95.0"}
P.entries["subzone:crossroads"] = {n="Das Wegekreuz",s="Reisende der Horde treffen sich am Wegekreuz, wo die Goldstraße den Weg von Ratschet zum Steinkrallengebirge kreuzt. Der Außenposten dient dem Handel, dem militärischen Aufmarsch und dem Reiseverkehr zwischen Durotar, Mulgore und den nördlichen Frontlinien.",h="Reisende der Horde treffen sich am Wegekreuz, wo die Goldstraße den Weg von Ratschet zum Steinkrallengebirge...",kw={"brachland","das wegekreuz","devrak","goldstraße","raptoren","ratschet","steinkrallengebirge","wind rider"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr das Wegekreuz angreifen, um Verstärkungen der Horde zwischen Orgrimmar, Mulgore und den umstrittenen Grenzen des Eschentals aufzuhalten.",["faction:Horde"]="Als Mitglied der Horde erlebt Ihr, wie das Wegekreuz die Heimatgebiete von Orcs, Tauren und Trollen verbindet und zugleich den Nachschub in ganz Kalimdor koordiniert. Es stellt Eure junge Nation auf die Probe."},sec={{t="Wichtiger Knotenpunkt der Savanne",b="Das Wegekreuz versammelt Reisende dort, wo die Goldstraße auf den Weg von Ratschet zum Steinkrallengebirge trifft. Seine Unterkünfte sind bescheiden, doch Windreitermeister, Händler, Schmiede und Ausbilder arbeiten unter den Wachtürmen. Jungen Kriegern aus Durotar oder Mulgore zeigt der Außenposten, wie die neue Horde ihre fernen Fronten und deren Versorgung verbindet."},{t="Grenzposten unter Belagerung",b="Am Wegekreuz für Ordnung zu sorgen, ist ein ständiger Kampf. Ebenenraptoren streifen nahe genug umher, um Soldsilber aus den Wachtürmen zu stehlen. Harpyien, Borstennacken und Zentaurenstämme bedrängen die Außengrenzen, während Späher der Allianz nahe den Verteidigungsbarrikaden zuschlagen. Das neutrale Ratschet liegt in der Nähe, und die umkämpften Wälder des Eschentals sind in Reichweite."}},faq={{q="Warum ist das Wegekreuz für die Horde so wichtig?",a="Das Wegekreuz bildet den Knotenpunkt der wichtigsten Wege im zentralen Kalimdor. Reisende zwischen Durotar, Mulgore, Ratschet, dem Steinkrallengebirge oder dem Eschental passieren den Außenposten oder seine Umgebung, was ihn für Nachschub und Verstärkung entscheidend macht.",al={"warum ist das wegekreuz wichtig","zweck des wegekreuzes","warum das wegekreuz von bedeutung ist"}},{q="Wer bietet am Wegekreuz Flugverbindungen an?",a="Devrak verwaltet den Windreiterhorst am Wegekreuz. Er befördert Reisende zu Außenposten in ganz Kalimdor, darunter Orgrimmar und Donnerfels.",al={"flugmeister am wegekreuz","wer hat hier wyvern","flugmeister wegekreuz"}},{q="Warum greift die Allianz das Wegekreuz so häufig an?",a="Das Wegekreuz liegt im Herzen des Reiseverkehrs der Horde und in Angriffsreichweite des Eschentals und Ratschets. Überfalltrupps der Allianz greifen den Außenposten an, um die Nachschublinien der Horde zu stören.",al={"warum die allianz das wegekreuz überfällt","allianz pvp wegekreuz","angriffe auf das wegekreuz"}},{q="Was geschah mit dem Soldsilber des Außenpostens?",a="Raptoren aus dem Brachland stahlen eine Silberlieferung aus dem Wachturm am Wegekreuz. Das Silber war als Sold für die verteidigenden Wachen bestimmt, und die Raptoren verstreuten es in der umliegenden Savanne.",al={"gestohlener sold wegekreuz","wer hat das silber genommen","wegekreuz silber gestohlen"}}},fx={["2f66b0ff"]={q="Was ist Das Wegekreuz?",a="Das Wegekreuz ist die größte und zentralste Siedlung der Horde im Brachland. Erbaut um einen befestigten Wachturm und ein Gasthaus, dient es als primäre Zwischenstation und Versorgungslager, das Orgrimmar, Donnerfels, Ratschet und die Grenze im Steinkrallengebirge und Eschental verbindet. Für Reisende durch das zentrale Kalimdor ist es ein geschäftiger Knotenpunkt für Rast, Handel und regionale Verteidigung.",al={"was ist das wegekreuz","wegekreuz brachland","was ist die stadt das wegekreuz"}},["6d918d5a"]={q="Warum nennt man es Das Wegekreuz?",a="Der Außenposten hat seinen Namen direkt von der Geografie: Er liegt genau dort, wo sich die wichtigste Nord-Süd-Verbindung, die Goldstraße, mit der Ost-West-Route kreuzt, die vom neutralen Hafen Ratschet in das Steinkrallengebirge führt. Da fast jede Überlandreise durch das Brachland hier vorbeiführt, entwickelte sich die Siedlung ganz natürlich um diesen entscheidenden Knotenpunkt herum.",al={"warum das wegekreuz","herkunft des namens wegekreuz","wie erhielt das wegekreuz seinen namen"}},["9b710adc"]={q="Ist Das Wegekreuz gefährlich?",a="Während das Innere von Wachen der Horde gesichert wird, ist die Siedlung ständiger Gefahr ausgesetzt. Durch die unmittelbare Nähe zum Eschental und zu Ratschet ist sie ein häufiges Ziel für waghalsige Vorstöße der Allianz, während die umliegenden Ebenen von aggressiven Raptoren, Harpy Raiders und feindseligen Stämmen der Stacheleber geplagt werden, die versuchen, die lebenswichtigen Versorgungswege der Horde zu kappen.",al={"ist das wegekreuz sicher","gefahren am wegekreuz","bedrohungen für das wegekreuz"}}},fp="10,226,32.341.0,28.340.0,48.216.0,48.139.0,58.174.0,46.187.0"}
P.entries["subzone:crown-guard-tower"] = {n="Turm der Kronenwache",s="Im Süden der Östlichen Pestländer umgibt die Seuche die Ruinen des Turms der Kronenwache. Die Geißel zerstörte ihn während der Invasion von Lordaeron im Dritten Krieg.",h="Im Süden der Östlichen Pestländer umgibt die Seuche die Ruinen des Turms der Kronenwache.",kw={"turm der kronenwache","östliche pestländer","lordaeron","geißel","spähturm","wachturm"},ang={["faction:Alliance"]="Für die Allianz erinnern die Ruinen des Turms der Kronenwache daran, wie vollständig die Geißel die Verteidigungsanlagen des Königreichs Lordaeron zerschlug."},sec={{t="Ein gefallenes Bollwerk",b="Der Turm der Kronenwache wachte einst als Teil der Verteidigungsanlagen des Königreichs über das östliche Lordaeron. Als die Geißel das Königreich überrannte, zerstörte sie den Turm und ließ ihn in Trümmern zurück. Mehrere eingestürzte Türme liegen über die heutigen Östlichen Pestländer verstreut. Verkohlte Steine sind hier in einem Land zurückgeblieben, das noch immer von den Untoten beherrscht wird."}},faq={{q="Wozu wurde der Turm der Kronenwache ursprünglich erbaut?",a="Der Turm der Kronenwache wurde vor dem Dritten Krieg als regionaler militärischer Wachturm und Spähposten für das menschliche Königreich Lordaeron erbaut. Er sicherte die Straßen gegen Überfälle.",al={"geschichte des turms der kronenwache","warum wurde er erbaut","turm von lordaeron"}},{q="Warum liegt der Turm in Trümmern?",a="Die Geißel zerstörte den Turm der Kronenwache während ihrer Invasion von Lordaeron. Wellen von Untoten überrannten die Verteidigungsanlagen des Königreichs und legten das Bauwerk in Trümmer.",al={"wer zerstörte den turm der kronenwache","was geschah hier"}}},fp="17,156,16.317.0,48.177.0,24.156.0"}
P.entries["subzone:crusader-outpost"] = {n="Außenposten der Kreuzzügler",s="Von den Höhen des Außenpostens der Kreuzzügler aus überwachen scharlachrote Kreuzzügler die östliche Straße. Ihr Turm bewacht die Zugänge zum Scharlachroten Kloster und ist für Vorstöße der Verlassenen gewappnet.",h="Von den Höhen des Außenpostens der Kreuzzügler aus überwachen scharlachrote Kreuzzügler die östliche Straße.",kw={"captain vachon","außenposten der kreuzzügler","scharlachroter kreuzzug","das scharlachrote kloster","spähturm","tirisfal","wachturm"},ang={["faction:Horde"]="Als Mitglied der Horde müsst Ihr die östlichen Pfade von Tirisfal mit Vorsicht bereisen. Scharlachrote Wachposten auf dem Hügel greifen jeden an, der sich dem Kloster nähert.",["race:Undead"]="Als untoter Reisender kommt Ihr an einem Wachturm am Rand des Gebiets der Verlassenen vorbei. Seine lebenden Kreuzzügler halten ein kleines Stück Land in den Lichtungen."},sec={{t="Augen über Tirisfal",b="Von den Klippen über dem Tal aus überwacht der Außenposten der Kreuzzügler die östliche Straße. Scharlachrote Wachposten beobachten den Weg zwischen Brill und den östlichen Weiten Lordaerons. Sie hoffen, Untote und Spähtrupps zu entdecken, bevor diese die Klostertore erreichen. Der Turm ermöglicht es der Garnison auch, Truppen in die Flanke zu fallen, die durch das Tal zu ihrer heiligen Bastion vorrücken."},{t="Ein Dorn im Auge der Dark Lady",b="Captain Vachon und die anderen scharlachroten Offiziere halten die Garnison wachsam. Für sie sind die Wälder unheiliger Boden, den Monster der Menschheit geraubt haben, kein Gebiet der Verlassenen. Reisenden, die Unterstadt die Treue halten, droht nahe den Klippen ein Hinterhalt. Armbrustbolzen und reinigender Stahl erwarten jeden, der zu nahe kommt."}},faq={{q="Was ist der Außenposten der Kreuzzügler?",a="Der Scharlachrote Kreuzzug hält diesen Wachturm im östlichen Tirisfal. Seine Wachposten überwachen die Straße unterhalb und bewachen den südlichen Zugang zum Scharlachroten Kloster.",al={"was ist dieser turm","außenposten der kreuzzügler tirisfal","scharlachroter wachturm"}},{q="Wer kontrolliert diesen Außenposten?",a="Captain Vachon befehligt die Fanatiker des Scharlachroten Kreuzzugs, die den Außenposten bemannen. Sie betrachten alle Untoten als Abscheulichkeiten, die beim ersten Anblick ausgemerzt werden müssen.",al={"wem gehört der außenposten der kreuzzügler","wer lebt hier","außenposten des scharlachroten kreuzzugs"}},{q="Warum steht der Turm in diesen Hügeln?",a="Die Höhe des Turms gewährt den Kreuzzüglern freie Sicht auf die östliche Straße von Tirisfal. Von dort aus können sie Truppenbewegungen der Verlassenen früh erkennen und Streitkräften, die das Scharlachrote Kloster angreifen, in die Flanke fallen.",al={"warum hier bauen","standort des außenpostens","taktischer zweck"}},{q="Werden mich die Wachen hier angreifen?",a="Ja. Der Scharlachrote Kreuzzug betrachtet Außenstehende, besonders die Verlassenen und ihre Verbündeten der Horde, als verderbte Feinde, die in heiligem Feuer geläutert werden müssen.",al={"ist der außenposten der kreuzzügler feindselig","sind sie aggressiv"}}},fx={a83c5de5={q="Wer hat das Kommando über den Außenposten der Kreuzzügler?",a="Das Kommando über den Außenposten hat Hauptmann Vachon, ein Offizier des Scharlachroten Kreuzzugs, der hier stationiert ist, um die Aufklärung zu überwachen und die Stellung gegen Eindringlinge zu halten, die das Territorium des Kreuzzugs betreten.",al={"wer führt den außenposten der kreuzzügler","hauptmann des außenpostens der kreuzzügler","kommandant des außenpostens der kreuzzügler"}},b91596ef={q="Warum heißt er Außenposten der Kreuzzügler?",a="Der Außenposten hat seinen Namen direkt vom Scharlachroten Kreuzzug, dem fanatischen menschlichen Orden, der ihn als Frühwarnposten und defensive Flanke für das nahegelegene Das Scharlachrote Kloster errichtet hat und unterhält.",al={"warum heißt er außenposten der kreuzzügler","herkunft des namens außenposten der kreuzzügler","warum außenposten der kreuzzügler"}}},fp="16,180,18.338.0,31.303.0,29.161.0,26.131.0,41.196.0,31.130.0"}
P.entries["subzone:crusader-s-armory"] = {n="Crusader's Armory",s="Munition füllt die Crusader's Armory im Scharlachroten Kloster. Enge Hallen bergen Schießpulver und Kanonenkugeln für die Eiferer, die den Weg ins Innere bewachen. Eine verschlossene Eisentür versperrt den Weg zur Hall of Champions.",h="Munition füllt die Crusader's Armory im Scharlachroten Kloster.",kw={"waffenkammer","crusader's armory","schießpulver","hall of champions","scharlachroter schlüssel","das scharlachrote kloster"},ang={["faction:Horde"]="Für die Verlassenen und die Horde bedrohen die Sprengstoffvorräte in der Crusader's Armory die Grenzen von Tirisfal und die Tore von Unterstadt.",["profession:Blacksmithing"]="Die hier gehorteten Waffen und Munitionsvorräte zeugen von der hohen Fertigungsqualität und militärischen Disziplin der einstigen Schmiede Lordaerons, die nun eifrigem Fanatismus verfallen sind."},sec={{t="Arsenal des Eifers",b="Zwischen der Footman's Armory und der Hall of Champions bergen enge Steinkorridore Schießpulverkisten und Stapel von Kanonenkugeln. Bewaffnete Kreuzfahrer stehen bereit, Eindringlinge zurückzuschlagen. Der Scharlachrote Kreuzzug hat eine ehemalige Klosteranlage zur Festung gemacht und jede verfügbare Halle mit Kriegsgerät gefüllt. Eine schwere Eisentür, mit dem Scharlachroten Schlüssel verschlossen, versperrt den Weg in die inneren Kammern."}},faq={{q="Was ist die Crusader's Armory?",a="Die Crusader's Armory birgt Munition im Durchgang zwischen der Footman's Armory und der Hall of Champions, im Waffenkammerflügel des Scharlachroten Klosters.",al={"crusader's armory","was ist die crusader's armory","waffenkammerraum im kloster"}},{q="Warum ist die Tür am Ende verschlossen?",a="Die verschlossene Tür sichert den Durchgang zur Hall of Champions und zu den dahinterliegenden Gemächern des Kommandanten. Der Scharlachrote Kreuzzug verlangt den Scharlachroten Schlüssel aus dem Library-Flügel des Klosters, um sie zu öffnen.",al={"verschlossene tür waffenkammer","waffenkammertür öffnen","scharlachroter schlüssel waffenkammer"}},{q="Warum gibt es hier so viele Kanonenkugeln und Schießpulverkisten?",a="Der Scharlachrote Kreuzzug lagert hier Kanonenkugeln und Schießpulver für seine Kanonen und Sprenggeschosse. Seine aktiven Belagerungstruppen und Artilleriestellungen in ganz Tirisfal brauchen stetigen Nachschub für den Krieg gegen die Geißel und die Verlassenen.",al={"pulverkisten waffenkammer","kanonen im kloster","warum schießpulver"}},{q="Wer bewacht diesen Bereich?",a="Erfahrene Soldaten des Scharlachroten Kreuzzugs bewachen die Halle inmitten der Munition, darunter Fußsoldaten, Kreuzfahrer und Bogenschützen. Sie halten Eindringlinge auf, die tiefer in die Anlage vordringen wollen.",al={"gegner in der waffenkammer","wer ist in der crusader's armory"}}},fx={["2e345cd4"]={q="Ist die Crusader's Armory gefährlich?",a="Sie ist außerordentlich gefährlich. Die Rüstkammer ist vollgestopft mit eifrigen Kämpfern des Scharlachroten Kreuzzugs, die jeden Eindringling sofort angreifen und jeden Außenstehenden als Agent der Verderbnis oder der Geißel betrachten. Hinzu kommt die Gefahr, dass der gesamte Korridor mit hochexplosivem Material vollgestopft ist, einschließlich flüchtiger Pulverfässer und Artilleriebestände, die für ihren unerbittlichen Krieg in Tirisfal bereitstehen.",al={"gefahr der crusader's armory","ist die crusader's armory sicher","bedrohungen der crusader's armory"}},["9c475e8e"]={q="Warum nennt man sie Crusader's Armory?",a="Die Kammer hat ihren Namen von den Scharlachroten Kreuzzüglern, die sie besetzt halten und dort ihr Belagerungsgerät lagern. Tief im militärischen Flügel von Das Scharlachrote Kloster hinter der Rüstkammer der Fußknechte gelegen, beherbergt sie Kanonenkugeln, Schießpulver und Waffen, die für die erfahrenen Krieger des Kreuzzugs bestimmt sind, während diese sich darauf vorbereiten, die umliegenden Pestländer anzugreifen.",al={"warum nennt man sie crusader's armory","herkunft des namens crusader's armory","bedeutung von crusader's armory"}}},fp="17,206,15.391.0,30.153.0,34.187.0,60.232.0,21.171.0"}
P.entries["subzone:crusader-s-outpost"] = {n="Crusader's Outpost",s="Scharlachrote Kreuzfahrer halten einen befestigten Spähturm im westlichen Tirisfal, neben Sollidens Bauernhof. Er ist ihre westlichste Stellung in ganz Lordaeron, fern ihrer Hauptfestungen und tief im feindlichen Gebiet der Verlassenen.",h="Scharlachrote Kreuzfahrer halten einen befestigten Spähturm im westlichen Tirisfal, neben Sollidens Bauernhof.",kw={"crusader's outpost","scharlachroter kreuzzug","spähturm","sollidens bauernhof","tirisfal","tyrs hand"},ang={["faction:Horde"]="Als Mitglied der Horde seht Ihr im Außenposten eine bittere Erinnerung daran, dass der Scharlachrote Kreuzzug sich weigert, Tirisfal den Verlassenen und ihren Verbündeten zu überlassen.",["race:Undead"]="Als frisch erweckter Verlassener, der Todesend verlässt, findet Ihr in der Nähe einen Turm, den scharlachrote Fanatiker bewachen. Sie sind eine unmittelbare Bedrohung an Eurer Grenze."},sec={{t="Ein einsamer Wachturm",b="In den westlichen Hügeln von Tirisfal erhebt sich ein steinerner Turm, direkt nördlich von Todesend. Die scharlachrote Garnison markiert die äußerste Reichweite der Macht des Kreuzzugs in Lordaeron. Ihre Soldaten stehen gemeinsam mit den überlebenden menschlichen Arbeitern auf Sollidens Bauernhof gegen die vordringenden Untoten. Wachposten beobachten die nahen Kürbisfelder und Waldpfade und halten Ausschau nach Unholden der Geißel und Patrouillen aus Unterstadt."},{t="Isoliert hinter feindlichen Linien",b="Die Westgrenze bringt die Kreuzfahrer in Gefahr. Ihre Hauptfestungen liegen im Scharlachroten Kloster und weit im Osten in Tyrs Hand, weshalb rasche Verstärkung unwahrscheinlich ist, falls ein Angriff die Palisade durchbricht. In ganz Tirisfal sammeln sich Streitkräfte der Verlassenen. Beginnen sie eine Belagerung, muss die Garnison den Turm allein halten oder mit ihrer Vernichtung rechnen, bevor Hilfe eintreffen kann."}},faq={{q="Warum ist der Scharlachrote Kreuzzug so weit draußen im westlichen Tirisfal?",a="Der Turm dient als Frühwarnposten und Verteidigungsanlage in den westlichen Hügeln von Tirisfal. Er schützt die lebenden menschlichen Bauern auf Sollidens Bauernhof und überwacht die westlichen Zugänge auf der Suche nach verwilderten Geißeluntoten und Vorhutspähern der Verlassenen.",al={"warum sind scharlachrote hier","scharlachrote kreuzfahrer westliches tirisfal","zweck des außenpostens der kreuzzügler"}},{q="Kann Verstärkung diesen Außenposten erreichen, wenn er angegriffen wird?",a="Verstärkung kann den Außenposten nur schwer erreichen. Er ist die westlichste scharlachrote Stellung in Lordaeron, während die Hauptbastionen des Kreuzzugs weit im Osten im Scharlachroten Kloster und in Tyrs Hand liegen. Wenn Streitkräfte der Verlassenen die Garnison umzingeln, ist sie abgeschnitten.",al={"können scharlachrote verstärkung schicken","hilfe für den außenposten","wie weit ist hilfe entfernt"}},{q="Welche Verbindung besteht zwischen dem Turm und Sollidens Bauernhof?",a="Die Kreuzfahrer haben sich mit den verbliebenen menschlichen Bauern auf Sollidens Bauernhof verbündet. Die Soldaten schützen sie vor den wandelnden Toten und erhalten dafür Nahrung und einen loyalen Stützpunkt am Rande Lordaerons.",al={"verbindung zu solliden","warum sind kreuzfahrer auf dem bauernhof","kreuzfahrer und bauern"}},{q="Gibt es in der Region weitere solche Türme?",a="Ja. Der Scharlachrote Kreuzzug errichtete vier ähnliche Außenposten der Kreuzzügler in ganz Tirisfal, um die umliegenden Ländereien zu überwachen und dort zu patrouillieren.",al={"weitere außenposten der kreuzzügler","weitere scharlachrote türme"}}},fx={["74d073f8"]={q="Wer kontrolliert Crusader's Outpost?",a="Der Turm wird von eifrigen Mitgliedern des Scharlachroten Kreuzzugs bemannt und betrieben. Fernab ihrer Festungen im Osten unterhalten diese Wachen und Kreuzzügler eine isolierte Garnison und arbeiten eng mit den sympathisierenden menschlichen Bauern von Sollidens Bauernhof zusammen, um ihre kleine Enklave in Tirisfal zu schützen.",al={"wer wohnt in crusader's outpost","bewohner von crusader's outpost","wer leitet crusader's outpost"}},["30c5615e"]={q="Ist Crusader's Outpost gefährlich?",a="Ja, überaus gefährlich, wenn Ihr ein Außenstehender oder ein Untoter seid. Der Scharlachrote Kreuzzug betrachtet fast jeden außerhalb seiner Reihen als befleckt oder korrumpiert und greift Eindringlinge sofort an. Tief im feindlichen Gebiet isoliert, bleiben die Kreuzzügler hier in ständiger Alarmbereitschaft, was jede Annäherung gefährlich macht.",al={"ist crusader's outpost gefährlich","gefahr bei crusader's outpost","sind kreuzzügler hier feindselig"}},["52f2bf53"]={q="Warum heißt es Crusader's Outpost?",a="Es hat seinen Namen direkt vom Scharlachroten Kreuzzug, dem religiösen Militärorden, der den Spähturm errichtet hat und besetzt. Er dient als einer von mehreren solcher Außenposten, die in ganz Tirisfal errichtet wurden, um ihren fanatischen Kreuzzug gegen die Geißel und die Verlassene abzusichern.",al={"warum heißt es crusader's outpost","herkunft des namens crusader's outpost"}},["5e123392"]={q="Was ist Crusader's Outpost?",a="Crusader's Outpost ist ein befestigter Spähturm im westlichen Tirisfal, knapp nördlich von Todesend. Als westlichster Besitz des Scharlachroten Kreuzzugs in Lordaeron dient er als vorderster Wachposten gegen die umgebenden Bedrohungen durch die Verlassenen und die Geißel und hält an der Seite der nahegelegenen verbündeten Bauern von Sollidens Bauernhof Wache über die Region.",al={"was ist crusader's outpost","außenposten der kreuzzügler tirisfal","scharlachroter außenposten westliches tirisfal"}}},fp="18,227,19.377.0,27.361.0,68.234.0,58.255.0,66.209.0,47.138.0"}
P.entries["subzone:crypt-badlands"] = {n="Gruft",s="In den Hügeln des Ödlands thront ein gepanzertes Skelett in einem verborgenen Grab. Urnen, Truhen und ein uraltes Schwert liegen neben den stummen Überresten.",h="In den Hügeln des Ödlands thront ein gepanzertes Skelett in einem verborgenen Grab.",kw={"ödland","barbarenherrscher","krypta","hammerzehs grabungsstätte","schwert","thron"},ang={["class:Warrior"]="Als Krieger könnt Ihr vor einem gefallenen Streiter innehalten, der in Plattenrüstung starb. Seine mächtige Klinge liegt noch immer neben ihm.",["race:Dwarf"]="Als Zwerg findet Ihr die Krypta nahe aktiven zwergischen Grabungsstätten. Ihre Architektur und der Thron mit dem Skelett deuten auf Geheimnisse aus der Zeit vor Eisenschmiedes jüngsten Ausgrabungen hin."},sec={{t="Das Grab des Barbarenherrschers",b="Südöstlich von Hammerzehs Grabungsstätte führt ein unmarkierter Pfad den Hang hinauf zur Krypta. Unten sitzt ein gepanzertes Skelett auf einem steinernen Thron in dunklen Kammern. Neben den Überresten liegt das Schwert des Barbarenherrschers, zwischen Knochen, Urnen und vergessenen Truhen. Bergleute und Reisende durchsuchen nahe Schluchten nach Zwergenruinen und Reichtümern, während die Herkunft des thronenden Herrschers im Ödland verschollen bleibt."}},faq={{q="Wo liegt die Krypta im Ödland?",a="Der Eingang der Krypta liegt südöstlich von Hammerzehs Grabungsstätte. Ein unmarkierter Pfad führt den Hügel oberhalb der Grabungsstätte hinauf.",al={"krypta ödland standort","wie krypta im ödland finden","krypta eingang ödland"}},{q="Wer ist das Skelett auf dem Thron im Inneren?",a="Das gepanzerte Skelett ist als Barbarenherrscher bekannt. Keine erhaltenen örtlichen Schriften berichten, wer er war oder wie er herrschte, und so bleibt seine Geschichte im Ödland verschollen.",al={"skelett auf thron","wer ist der barbarenherrscher","krypta skelett identität"}},{q="Was ist das für ein Schwert neben dem Thron?",a="Das Schwert wird Schwert des Barbarenherrschers genannt. Es ruht neben dem skelettierten Herrscher als Grabzeichen aus seiner kriegerischen Vergangenheit.",al={"schwert des barbarenherrschers","krypta schwert","ödland thron schwert"}},{q="Gibt es Quests, die mit dieser Krypta verbunden sind?",a="Keine gewöhnlichen Aufgaben führen Reisende in die Krypta. Sie bleibt eine verborgene Entdeckung für jene, die die Klippen erkunden.",al={"ödland krypta quest","warum zur krypta im ödland"}}},fp="5,141,30.385.0,43.111.0,49.148.0,37.128.0,48.111.0"}
P.entries["subzone:crypt-stromgarde-keep"] = {n="Crypt",s="In Burg Stromgarde bewachen Loyalisten die königliche Gruft unter dem Sanktum. Sie birgt das Grab von König Thoras Trollbane und die Schätze seiner Dynastie.",h="In Burg Stromgarde bewachen Loyalisten die königliche Gruft unter dem Sanktum.",kw={"arathi","gruft","galen","sanktum","stromgarde","thoras","trol'kalar","trollbane"},ang={["faction:Alliance"]="Als Mitglied der Allianz findet Ihr in Stromgardes königlicher Gruft eine der letzten Bastionen des Erbes der Allianz in Arathi. Ihre Verteidiger halten Banditen, Oger und die Horde fern.",["race:Human"]="Als Mensch der Allianz könnt Ihr in diesem Grab Stromgardes Niedergang erkennen. Hier ruht einer der erbittertsten Heerführer der Allianz aus einem ihrer sieben großen Königreiche."},sec={{t="Das Grab von Thoras Trollbane",b="Unter dem Sanktum von Burg Stromgarde liegt das Grab von König Thoras Trollbane. Er führte Stromgarde durch den Zweiten Krieg. Die Stadt liegt in Trümmern, aufgeteilt zwischen Schurken des Syndikats und Ogern der Boulderfist, doch die verbliebene Miliz von Stromgarde hält noch dieses Viertel.\n\nPrinz Galen Trollbane wacht mit den königlichen Hütern über die Gruft. Sie schützen den Leichnam und das Erbe seines Vaters vor Plünderern und Feinden draußen."},{t="Das Gewölbe von Trol'kalar",b="Die Gruft birgt Artefakte der Trollbane-Dynastie. Darunter ist Trol'kalar, ein uraltes runenverziertes Großschwert, das vor Jahrhunderten geschmiedet wurde, um Trolle zu töten. Eidlich verpflichtete Hüter, darunter Alaric, Nevlin und Weston, schützen die Kammer und ihre Schätze mit mächtigen Schutzvorkehrungen.\n\nGalen und seine Loyalisten halten Wache. Rivalisierende Fraktionen und feindselige Trolle in ganz Arathi begehren die uralte Macht der Klinge."}},faq={{q="Wer liegt in der Gruft begraben?",a="König Thoras Trollbane, Stromgardes verstorbener Herrscher, liegt in der Gruft begraben. Sein Sohn, Prinz Galen Trollbane, wacht inmitten der zerstörten Stadt über das Grab.",al={"wer liegt hier begraben","wessen grab ist das","gruft grab"}},{q="Was ist Trol'kalar?",a="Trol'kalar ist eine uralte Klinge, die als Erbstück der Familie Trollbane weitergegeben wird. Ihr Name bedeutet in der alten Sprache „Trolltöter“. Sie wurde geschmiedet, um die Waldtrolle des Arathibeckens zu bekämpfen.",al={"trolkalar schwert","trollbane schwert","was ist trolkalar"}},{q="Wer bewacht die Gruft?",a="Prinz Galen Trollbane und Stromgardes königliche Hüter, darunter Alaric, Nevlin und Weston, bewachen die Gruft. Sie verteidigen die Grabkammer gegen Diebe des Syndikats und Oger der Boulderfist.",al={"wachen der gruft","wer verteidigt die gruft","hüter"}},{q="Wo liegt die Gruft?",a="Die Gruft liegt in Burg Stromgarde im Arathihochland, tief im Sanktumsbezirk hinter der Kapelle der Burg. Sie befindet sich in dem Viertel, das noch von Stromgardes Loyalisten gehalten wird.",al={"lage der gruft","wie die gruft finden","wo ist stromgardes gruft"}}},fp="5,143,28.412.0,23.380.0,27.150.0,19.183.0,21.190.0,27.176.0"}
P.entries["subzone:crystal-lake"] = {n="Kristallsee",s="Am Kristallsee beanspruchen Murlocs das Ufer östlich von Goldhain. Ihre Angriffe gefährden Dorfbewohner und vorbeiziehende Reisende.",h="Am Kristallsee beanspruchen Murlocs das Ufer östlich von Goldhain.",kw={"kristallseetang","kristallsee","elwynn","goldhain","murloc","william pestle"},ang={["faction:Alliance"]="Die Murlocs nahe Goldhain zeigen, wie sehr die Streitkräfte des Königreichs beim Schutz seiner Kerngebiete an ihre Grenzen stoßen.",["profession:Herbalism"]="Kristallseetang wächst in den flachen Süßwasserbereichen des Sees. Der größte Teil davon stammt von den dort lebenden Murlocs, die ihn vom Seegrund sammeln."},sec={{t="Ein bedrohtes Ufer",b="Östlich von Goldhain liegt der Kristallsee nur einen kurzen Fußweg vom Gasthaus \"Zur Höhle des Löwen\" entfernt. Süßwassermurlocs beanspruchen sein Ufer und seine flachen Untiefen und greifen jeden an, der ihnen zu nahe kommt. William Pestle, ein Alchemist im Gasthaus, heuert Reisende an, um sie zurückzudrängen und den Kristallseetang, den sie bei sich tragen, für seine Experimente zu sammeln."}},faq={{q="Wo liegt der Kristallsee?",a="Der Kristallsee liegt östlich von Goldhain im Herzen des Waldes von Elwynn, gleich hinter dem Dorfrand.",al={"kristallsee lage","wo liegt der kristallsee","kristallsee finden"}},{q="Warum sammeln sich Murlocs am Kristallsee?",a="Süßwassermurlocs nisten am Kristallsee und suchen dort nach Nahrung. Ihre Zahl nahe Goldhain ist gestiegen, während die örtliche Wache von Sturmwind Mühe hat, das Gebiet zu schützen.",al={"warum murlocs am kristallsee","murlocproblem goldhain","kristallsee murlocs"}},{q="Was brauchen Abenteurer vom Kristallsee?",a="William Pestle, ein Apotheker im Gasthaus \"Zur Höhle des Löwen\" in Goldhain, heuert Reisende an, um Murlocs am Ufer zu töten und Kristallseetang für einen Unsichtbarkeitstrank zu sammeln.",al={"william pestle kristallsee","seetangquest kristallsee","unsichtbarkeitstrank elwynn"}}},fx={["18711dcc"]={q="Was ist der Kristallsee?",a="Der Kristallsee ist ein Süßwassersee, der östlich von Goldhain im Herzen vom Wald von Elwynn liegt. Auch wenn er einst eine friedliche Tränke gewesen sein mag, sind seine ruhigen Gewässer in letzter Zeit zu einem Brennpunkt für Ärger für nahegelegene Reisende und Stadtbewohner geworden.",al={"was ist der kristallsee","kristallsee in elwynn","hintergrund zum kristallsee"}},c07536f5={q="Ist der Kristallsee gefährlich?",a="Ja, für einen unvorsichtigen oder unerfahrenen Reisenden kann er sich als tödlich erweisen. Die Ufer und Untiefen des Sees sind stark von aggressiven Murlocs befallen, die jeden angreifen, der zu nahe an das Ufer wandert.",al={"wie gefährlich ist der kristallsee","ist der kristallsee sicher","bedrohungen am kristallsee"}}},fp="12,118,16.314.0,30.94.0,41.149.0,43.167.0"}
P.entries["subzone:crystal-shore"] = {n="Das Kristallufer",s="Das Kristallufer liegt an der südöstlichen Küste des Schlingendorntals den südlichen Meeren zugewandt. Sein Strand liegt südlich der Ruinen von Aboraz und gegenüber der Insel Jaguero auf der anderen Seite des Wassers.",h="Das Kristallufer liegt an der südöstlichen Küste des Schlingendorntals den südlichen Meeren zugewandt.",kw={"das kristallufer","die insel jaguero","nebeltal","ruinen von aboraz","die südlichen meere","schlingendorntal","die wilden ufer"},sec={{t="Ein abgeschiedener Küstenstreifen",b="Am südöstlichen Rand des Schlingendorntals trifft der Dschungel am Kristallufer auf die südlichen Meere. Steile Bergkämme trennen den Strand von der Wildnis des Nebeltals im Landesinneren, doch ein paar unwegsame Pässe führen darüber. Die verfallenden Trollbauten der Ruinen von Aboraz stehen im Norden, während die wilden Ufer den südlichen Biegungen des Kaps folgen. Fernab der Docks von Beutebucht bleibt diese Küste ruhig und windgepeitscht."}},faq={{q="Wo liegt das Kristallufer?",a="Das Kristallufer erstreckt sich entlang der äußersten Südostküste des Schlingendorntals und ist den südlichen Meeren zugewandt. Es liegt südlich der Ruinen von Aboraz und nordöstlich der wilden Ufer.",al={"kristallufer lage","wo liegt das kristallufer","kristallufer karte"}},{q="Wie gelangt Ihr vom Landesinneren zum Kristallufer?",a="Ein steiler Bergkamm trennt das Kristallufer vom Dschungel des Festlands. Ein paar schmale natürliche Pässe führen durch die Klippen, darunter ein Pfad ins Nebeltal.",al={"wie zum kristallufer gelangen","pfad zum kristallufer","kristallufer erreichen"}},{q="Welche markanten Orte liegen in der Nähe?",a="Die uralten Ruinen von Aboraz liegen unmittelbar nördlich des Kristallufers, und jenseits des Kanals im Südwesten liegt die Insel Jaguero. Die wilden Ufer erstrecken sich weiter entlang der Küste nach Süden.",al={"markante orte nahe dem kristallufer","was liegt nahe dem kristallufer"}},{q="Ist das Kristallufer von einer Fraktion besiedelt?",a="Keine Fraktion unterhält eine Stadt oder Siedlung am Kristallufer. Heimische Wildtiere, die uralten Trollruinen im Norden und die südlichen Meere prägen diesen ungezähmten Strand.",al={"wer lebt am kristallufer","kristallufer siedlung","kristallufer städte"}}},fp="13,160,24.407.0,35.162.0,48.155.0,26.173.0,44.161.0"}
P.entries["subzone:crystal-vale"] = {n="Das Kristalltal",s="Im Nordwesten von Silithus vereint das Kristalltal Stein, Wind und uralte Macht. Zerklüftete Spitzen ragen über felsige Ebenen, auf denen Erd- und Luftelementare zwischen reichen Erzadern umherstreifen. Mächtige Beschwörungsmagie ist hier mit den uralten Elementarlords verbunden.",h="Im Nordwesten von Silithus vereint das Kristalltal Stein, Wind und uralte Macht.",kw={"das kristalltal","elementare","hochlord demitrian","verwüsteter twilight-stützpunkt","silithus","thorium","thunderaan"},ang={["class:Shaman"]="Als Schamane könnt Ihr im Kristalltal den ungebändigten Zusammenprall von Erd- und Luftgeistern erleben. Er erinnert an das zügellose Chaos der Elementare in ganz Silithus.",["profession:Mining"]="Die zerklüfteten Ränder und Schluchtwände des Kristalltals bergen reiche Thoriumadern. Bergbau kann dort einträglich sein, doch das Tal ist gefährlich."},sec={{t="Wo Stein und Wind zusammenströmen",b="Das Kristalltal schneidet ein felsiges Becken in den Süden von Silithus. Steile Klippen umrahmen schimmernde Mineralformationen, Erdelementare und tosende Wirbelwinde aus lebendiger Luft. Reiche Thoriumvorkommen locken einige Prospektoren an, doch das Tal bleibt gefährlich. Feindselige Elementare bewachen einen Boden, den die urzeitlichen Konflikte des alten Azeroth geformt haben."},{t="Der Schlummer des Windsuchers",b="Hochlord Demitrian verweilt im Kristalltal und hütet Geheimnisse über Prinz Thunderaan, den Windsucher. Wer die getrennten elementaren Fesseln des gefallenen Prinzen und die seltensten geschmiedeten Metalle bringt, wird in das Tal gewiesen. Dort kann der gefangene Lord der Luft aus seinen Fesseln gelockt und im offenen Kampf herausgefordert werden."}},faq={{q="Wo liegt das Kristalltal?",a="Das Kristalltal liegt im äußersten Nordwesten von Silithus, am gebirgigen Rand der Wüste.",al={"wo liegt das kristalltal","kristalltal karte","kristalltal lage"}},{q="Welche Kreaturen bewohnen dieses Tal?",a="Aggressive Luft- und Erdelementare streifen zwischen den Mineralaufschlüssen des Tals umher.",al={"kristalltal gegner","was lebt im kristalltal","elementare im kristalltal"}},{q="Wer ist Hochlord Demitrian und warum ist er hier?",a="Hochlord Demitrian lebt allein im Kristalltal und weiß viel über Prinz Thunderaan. Er hilft Streitern, die die Fesseln des Windsuchers wieder vereinen und den Elementarprinzen beschwören können.",al={"wer ist demitrian","hochlord demitrian kristalltal","demitrian aufenthaltsort"}},{q="Was ist der Verwüstete Twilight-Stützpunkt?",a="Der Verwüstete Twilight-Stützpunkt ist das Trümmerfeld eines Lagers von Twilight's Hammer im Tal. Gewalttätige Elementare haben es zerstört und überrannt.",al={"verwüsteter twilight-stützpunkt kristalltal","twilight-stützpunkt im tal","zerstörter twilight-stützpunkt"}}},fp="12,241,30.321.0,29.307.1,34.100.0,35.77.0,45.179.0,34.136.0"}
P.entries["subzone:crystalvein-mine"] = {n="Kristalladermine",s="Im zentralen Schlingendorntal trotzen Goldsucher den Basilisken der Kristalladermine, um an ihre Singenden Kristalle zu gelangen. Die Höhle liegt nahe den alten Ruinen von Zul'Mamwe, und die Kreaturen darin haben das Gelände überrannt und Bergleute in Stein verwandelt.",h="Im zentralen Schlingendorntal trotzen Goldsucher den Basilisken der Kristalladermine, um an ihre Singenden...",kw={"basilisk","crank fizzlebub","kristalladermine","singende kristalle","schlingendorntal","venture company","zul'mamwe"},ang={["profession:Mining"]="Wenn Ihr als Bergmann von Singenden Kristallen angelockt werdet, seid vorsichtig. Die einheimischen Basilisken machen die Erzsuche hier zu einem der gefährlichsten Unterfangen im Schlingendorntal."},sec={{t="Eine lukrative Falle",b="Nahe Zul'Mamwe führt die Kristalladermine in die Dschungelhügel hinein. Ihre Singenden Kristalle erzielen in den südlichen Handelshäfen hohe Preise, weshalb die Venture Company kam, um die wertvollen Adern abzubauen.\n\nDie einheimischen Basilisken der Mine haben diese Arbeit gefährlich gemacht. Sie fressen die seltsamen Kristalle, die ihre Schuppen härten und sie unnatürlich tödlich machen. Versteinerte Trolle und Menschen vor dem Höhleneingang zeugen vom Scheitern der Expeditionen der Venture Company."}},faq={{q="Was macht die Kristalladermine wertvoll?",a="Die Kristalladermine birgt seltene Singende Kristalle, ein wertvolles Mineral, das nur im Schlingendorntal vorkommt. Goblins wie Crank Fizzlebub schätzen ihren Klang und ihren Wert, was Goldsucher in die gefährlichen Höhlen lockt.",al={"warum ist die kristalladermine wichtig","was gibt es in der kristalladermine","singende kristalle"}},{q="Warum stehen Steinstatuen vor der Mine?",a="Die Statuen sind versteinerte einheimische Trolle und Arbeiter der Venture Company. Die Basilisken ernähren sich von den klingenden Kristallen, wodurch ihre Haut härter wird, und verwandeln Eindringlinge in Stein.",al={"versteinerte menschen kristalladermine","kristallisierte trolle kristalladermine","steinerne körper schlingendorntal"}},{q="Wer kontrolliert die Kristalladermine derzeit?",a="Die Venture Company beanspruchte das Recht, die Kristalladermine auszubeuten, doch die Basilisken verwehren ihr den Zugang. Den Goblins ist es bisher nicht gelungen, in den Tiefen der Höhle einen aktiven Bergbaubetrieb aufzubauen.",al={"wem gehört die kristalladermine","kristalladermine fraktion","venture company kristalladermine"}}},fp="16,235,16.437.0,37.207.0,45.167.0,40.194.0"}
P.entries["subzone:cut-throat-alley"] = {n="Cut-Throat Alley",s="In Cut-Throat Alley liegt hinter einem Laden am Kanal in Sturmwind ein verborgener Innenhof. Sein gepflasterter Weg endet an einem leeren Wohnhaus, verborgen vor dem gewöhnlichen Stadtverkehr.",h="In Cut-Throat Alley liegt hinter einem Laden am Kanal in Sturmwind ein verborgener Innenhof.",kw={"kathedralenplatz","cut-throat alley","der zwergendistrikt","geheime gasse","shady lady","kanäle von sturmwind"},ang={["class:Rogue"]="Als Schurke könnt Ihr diese unbewachte Sackgasse nur durch die Hintertür eines zwielichtigen Ladens am Kanal erreichen. Sie bietet ein Versteck außerhalb des Blickfelds der Sturmwind City Guard."},sec={{t="Ein abgeschiedener Winkel",b="Tretet durch die Shady Lady, und eine gepflasterte Sackgasse öffnet sich vor Euch. Gestapelte Kisten und vergessene Fässer stehen neben einem zweistöckigen Wohnhaus, in dem niemand zu Hause ist. Obwohl die Gasse zum Zwergendistrikt gezählt wird, liegt sie abseits seiner Schmiedefeuer und seines Rußes.\n\nKeine Hauptstraße führt nach Cut-Throat Alley. Der einzige Fußweg führt durch den Laden am Kanal, unmittelbar südlich der Brücke vom Kathedralenplatz. Vorbeikommende Wachen und gewöhnliche Bürger können diesen stillen Winkel der Hauptstadt nicht sehen."}},faq={{q="Wie gelangt Ihr nach Cut-Throat Alley?",a="Folgt dem Kanalufer am Rand des Zwergendistrikts, unmittelbar südlich der Fußgängerbrücke zum Kathedralenplatz. Sucht die Shady Lady und geht durch den Laden, um die Gasse zu erreichen.",al={"cut-throat alley finden","lage von cut-throat alley","wo ist cut-throat alley","wie gelangt man nach cut-throat alley"}},{q="Warum bezeichnet die Karte diesen Ort als Zwergendistrikt?",a="Cut-Throat Alley liegt innerhalb der Grenzen des Zwergendistrikts und wird gewöhnlich zu ihm gezählt. Hier gibt es weder den Rauch des Distrikts noch eine Straßenanbindung. Betretet die Gasse durch die Shady Lady am Kanalufer.",al={"minikarte zwergendistrikt","warum steht dort zwergendistrikt","namensfehler cut-throat alley"}},{q="Wohnt jemand in Cut-Throat Alley?",a="Niemand wohnt in Cut-Throat Alley. Das einzige Haus, ein zweistöckiges Wohnhaus, ist verlassen. Nur gestapelte Frachtkisten und leere Fässer sind geblieben; es gibt keine Bewohner, Ladenbesitzer oder Stadtwachen.",al={"npcs in cut-throat alley","wer wohnt in cut-throat alley","leeres haus cut-throat alley"}},{q="Gibt es Quests in Cut-Throat Alley?",a="Keine offiziellen Pflichten oder städtischen Aufträge führen nach Cut-Throat Alley. Die Gasse bleibt ein übersehener, abgeschiedener Winkel der Hauptstadt.",al={"quests in cut-throat alley","handlung von cut-throat alley"}}},fx={["636e4761"]={q="Was ist Cut-Throat Alley?",a="Cut-Throat Alley ist eine abgelegene, unbewohnte Seitengasse, die sich hinter der Shady Lady entlang der Canals von Sturmwind versteckt. Obwohl sie offiziell als Teil vom Zwergendistrikt gilt, bleibt sie vom Rest des Viertels isoliert und weist nicht den starken Rauch und das geschäftige Treiben auf, das man in der Nähe findet. Sie enthält verstreute Kisten, Fässer und ein unbewohntes zweistöckiges Wohnhaus.",al={"was ist cut-throat alley","hintergrund zu cut-throat alley","über cut-throat alley"}},e98a554d={q="Ist Cut-Throat Alley gefährlich?",a="Trotz ihres unheimlichen Namens ist die Gasse völlig friedlich und frei von feindseligen Bedrohungen. Ihr werdet hier weder umherstreifende Halsabschneider noch lauernde Taschendiebe finden – nur einen leeren Hof, ruhige Kisten und ein verlassenes Stadthaus abseits der üblichen Patrouillenrouten der Stadtwache.",al={"ist cut-throat alley gefährlich","gibt es feinde in cut-throat alley","gefahr in cut-throat alley"}}},fp="16,165,15.496.0,35.178.0,48.207.0,37.201.0,41.123.0"}
P.entries["subzone:dabyrie-s-farmstead"] = {n="Bauernhof der Dabyries",s="Im Norden Arathis behaupten die Dabyries ihren Hof gegen die Gefahren ringsum. Kenata Dabyrie harrt mit ihren Söhnen aus, treu zu Stromgarde und der Allianz, in einem vom Dritten Krieg zerrütteten Reich.",h="Im Norden Arathis behaupten die Dabyries ihren Hof gegen die Gefahren ringsum.",kw={"arathi","callow","dabyrie","fardel","bauernhof","kenata","marcel","stromgarde"},ang={["faction:Alliance"]="Als Reisender der Allianz findet Ihr hier ein seltenes Zeichen dafür, dass Stromgardes Bewohner trotz vordringender Feinde noch immer überleben und für ihr Land kämpfen.",["race:Undead"]="Als Verlassener seht Ihr einen wohlhabenden menschlichen Bauernhof mit Gütern, die laut Eurem Volk Familien genommen wurden, die im Dritten Krieg umkamen."},sec={{t="Eine Bastion im Hochland",b="Kenata Dabyrie und ihre Söhne behaupten ihren Hof gegen die Gefahren ringsum. Fardel und Marcel bestellen die Felder, während eine einheimische Familienmiliz das Gelände bewacht. Nur wenige menschliche Gehöfte bestehen noch im zerrütteten Königreich Stromgarde. Aggressive Wildtiere und Banditen bedrohen den Hof, und die Verlassenen rücken von Norden her vor. Die Dabyries bewahren ihr Zuhause in einem Land, in dem nur wenige menschliche Siedlungen verblieben sind."},{t="Bittere Fehden",b="Die Verlassenen haben sich gegen die Dabyries gewandt, und Genavie Callow zählt zu ihren erbittertsten Feinden. Einst eine Adlige, verlor Callow im Dritten Krieg ihre Ländereien und Angehörigen. Sie beschuldigt die überlebenden Mitglieder der Familie Dabyrie, im Chaos der Seuche die Erbstücke ihrer Familie an sich genommen zu haben. Nun nehmen Söldner der Horde den bescheidenen Hof ins Visier, um alte Rechnungen aus dem Norden zu begleichen."}},faq={{q="Wer lebt auf dem Bauernhof der Dabyries?",a="Kenata Dabyrie lebt mit ihren Söhnen Fardel und Marcel auf dem Hof. Sie sind menschliche Bürger Stromgardes, der Allianz treu ergeben und von einer eingeschworenen einheimischen Miliz verteidigt.",al={"wem gehört der bauernhof der dabyries","familie dabyrie","kenata dabyrie"}},{q="Warum nimmt die Horde diesen Hof ins Visier?",a="Die Verlassene Genavie Callow hegt einen Groll gegen die Dabyries. Sie beschuldigt sie, das Anwesen und die verbliebenen Erbstücke ihrer Familie an sich genommen zu haben, während ihre Angehörigen im Dritten Krieg umkamen.",al={"warum dabyrie töten","genavie callow quest","horde dabyrie quest"}},{q="Gehört der Bauernhof der Dabyries zu Stromgarde?",a="Ja. Die Dabyries betrachten sich als Untertanen Stromgardes und als Verbündete der gesamten Allianz, obwohl ihre Hauptstadt im Süden in Trümmern liegt.",al={"gehört dabyrie zur allianz","stromgarde bauernhof"}},{q="Welche Gefahren umgeben den Bauernhof?",a="Raubtiere des Hochlands und umherstreifende Halsabschneider des Syndikats bedrohen den Hof. Truppen der Verlassenen rücken von Norden her vor.",al={"bedrohungen für dabyrie","gefahren nahe dem bauernhof der dabyries"}}},fp="19,195,26.395.0,12.349.1,33.166.0,37.188.0,42.145.0,36.108.0"}
P.entries["subzone:dagger-hills"] = {n="Die Dolchhügel",s="Banditen halten die Dolchhügel, die felsigen Höhen hinter Mondbruch im Süden von Westfall. Seit die königlichen Patrouillen ausbleiben, bedroht der Bergrücken Reisende und die Ebenen darunter.",h="Banditen halten die Dolchhügel, die felsigen Höhen hinter Mondbruch im Süden von Westfall.",kw={"die dolchhügel","defias","schnapsbart","leprithus","mondbruch","thunderbrew","westfall"},ang={["faction:Alliance"]="Die Hügel zeigen, wie die gesetzliche Ordnung im Süden von Westfall zerfallen ist. Gryan Starkmantels People's Militia muss kämpfen, um das von Sturmwind aufgegebene Land zurückzuerobern.",["race:Dwarf"]="Als Zwerg könnt Ihr Schnapsbart Donnerbräus einsame Präsenz auf diesem ungeschützten Bergrücken sehen. Brauer suchen mit sturer Entschlossenheit nach ungestörten Orten für ihr Handwerk."},sec={{t="Ein Hort der Banditen",b="Die Bruderschaft der Defias nutzt dieses trockene Hochland als Festung. Knöchelschläger, Pfadpirscher und Wegelagerer verstecken sich zwischen den Kämmen und im Gestrüpp. Sie überfallen unvorsichtige Reisende und bewachen die Zugänge zu ihren darunter gelegenen Hochburgen, wodurch die umliegenden Ebenen bedroht bleiben."},{t="Schatten auf dem Bergrücken",b="Die Dunkelheit bringt Gefahr in die Dolchhügel. Nach Sonnenuntergang wurde Leprithus, ein umherwandernder Ghul, dabei gesichtet, wie er durch die öden Höhen schleicht. Gesetzlose und zurückgebliebene Untote streifen über den Bergrücken. In der Nähe stellt Schnapsbart Donnerbräu, ein zwergischer Brauer, trotz der Gefahren seine Destillationsausrüstung auf."}},faq={{q="Wo liegen die Dolchhügel?",a="Die Dolchhügel bilden die felsige Südgrenze von Westfall, direkt hinter Mondbruch.",al={"dolchhügel lage","wo liegen die dolchhügel","wie gelangt man zu den dolchhügeln"}},{q="Wer kontrolliert die Dolchhügel?",a="Die Bruderschaft der Defias hält einen Großteil des Bergrückens. Wegelagerer, Pfadpirscher und Knöchelschläger bewachen die südlichen Hügel.",al={"dolchhügel defias","wer lebt in den dolchhügeln","feinde in den dolchhügeln"}},{q="Warum braut ein Zwerg hier draußen Bier?",a="Schnapsbart Donnerbräu destilliert in den einsamen Höhen starke zwergische Gebräue und trotzt für einen guten Trunk Banditen und wilden Tieren.",al={"schnapsbart westfall","zwerg in den dolchhügeln","schnapsbart donnerbräu geschichte"}},{q="Was ist Leprithus?",a="Leprithus ist ein berüchtigter Ghul, der zwischen den Felsen der Dolchhügel umherstreift. Er versetzt Reisende und Banditen in Angst, die ihm im Dunkeln begegnen.",al={"leprithus erscheinungsort","ghul in den dolchhügeln","dolchhügel untote"}}},fx={["7ebc9df0"]={q="Was macht Die Dolchhügel gefährlich?",a="Der zerklüftete Bergrücken ragt direkt hinter Mondbruch empor und wimmelt von bewaffneten Schurken der Bruderschaft der Defias, Wegelagerern und Schlägern, die das höher gelegene Gelände nutzen, um das Tiefland zu beobachten. Abgesehen von den Banditenpatrouillen ist bekannt, dass der ruhelose untote Ghul Leprithus die trostlosen Anhöhen durchstreift, was Reisen durch diese Felsen für jeden einzelnen Reisenden gefährlich macht.",al={"gefahr bei den dolchhügeln","sind die dolchhügel gefährlich","was ist gefährlich an den dolchhügeln"}}},fp="12,160,14.266.0,20.276.0,35.81.0,30.117.0,36.117.0,18.122.0"}
P.entries["subzone:dalaran"] = {n="Dalaran",s="Am Lordameresee bauen Dalarans überlebende Magi ihre zerstörte Stadt wieder auf. Einst die strahlende Hauptstadt der Kirin Tor, fiel sie im Dritten Krieg der Geißel und Archimonde zum Opfer. Ihr schützender violetter Schild wurde entfernt.",h="Am Lordameresee bauen Dalarans überlebende Magi ihre zerstörte Stadt wieder auf.",kw={"alterac","archimonde","council of six","dalaran","kuppel","kirin tor","lordamere","schild","violet citadel"},ang={["class:Mage"]="Als Magier seht Ihr in Dalaran die historische Wiege der Zauberkunst der Menschen und Hochelfen. Seine legendären Türme werden noch immer wiederaufgebaut, eine ernste Erinnerung an die Verluste, die Magier im Dritten Krieg erlitten.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr Dalarans Platz in Eurer Geschichte auf seine Rolle als eines der sieben Gründungskönigreiche der ursprünglichen Allianz von Lordaeron zurückführen. Die Kirin Tor bauen ihre verwüstete Hauptstadt wieder auf."},sec={{t="Der Fall der Magokratie",b="Dalaran entstand als Zuflucht für arkane Studien, gegründet von Zauberern des Arathorian Empire nach den uralten Trollkriegen. Jahrhundertelang war es das bedeutendste Zentrum der Magie für die Menschheit. Der Council of Six führte die Kirin Tor und bewahrte gewaltige Archive und mächtige Artefakte in der Violet Citadel.\n\nDieses Zeitalter endete während des Dritten Krieges. Der Verräterprinz Arthas führte die Geißel durch die Stadttore, um sich des Book of Medivh zu bemächtigen. Kurz darauf zermalmte der Dämonenfürst Archimonde Dalarans hoch aufragende Türme zu Trümmern."},{t="Wiederaufbau der Magokratie",b="Nach der Niederlage der Legion kehrten die überlebenden Zauberer der Kirin Tor in ihre verwüstete Heimat zurück. Sie wollten ihr angestammtes Land weder der Geißel noch Plünderern überlassen und errichteten eine schimmernde violette Barriere über dem Herzen der Stadt. Der Schild wurde inzwischen entfernt, während der Wiederaufbau weitergeht. Die Magi stellen ihre zerstörte Zuflucht wieder her, und Erzmagier Ansirem Runenweber ist in der Violet Citadel anzutreffen."}},faq={{q="Was wurde aus Dalarans schützendem Schild?",a="Nach Dalarans Zerstörung im Dritten Krieg errichteten die Kirin Tor einen magischen Schild über der Stadt. Der Schild wurde inzwischen entfernt, und der Wiederaufbau geht weiter.",al={"violette blase","violetter schild alterac","was ist die kuppel","dalaran kuppel"}},{q="Können Spieler Dalaran betreten?",a="Ja. Der Wiederaufbau ist im Gange, und Erzmagier Ansirem Runenweber residiert in der Violet Citadel. Die Kirin Tor stehen auf der Seite der Allianz, und die Horde ist bei ihnen verhasst und wird in der Stadt sofort angegriffen. Gruppen der Horde können den Dungeon Dalaran dennoch betreten.",al={"kann man dalaran betreten","wie dalaran betreten","dalarans schild überwinden"}},{q="Wer hat Dalaran zerstört?",a="Prinz Arthas und seine Geißelarmee griffen Dalaran an und stahlen das Book of Medivh aus den Gewölben der Stadt. Kurz darauf legte der Dämonenfürst Archimonde die Stadt mit dunkler Zauberei in Schutt und Asche.",al={"wie fiel dalaran","wer hat dalaran gesprengt","warum liegt dalaran in trümmern"}},{q="Wer herrscht über Dalaran?",a="Die Kirin Tor regieren Dalaran durch ihr Führungsgremium, den Council of Six.",al={"wer regiert dalaran","dalarans führung","wer führt die kirin tor"}}},fp="7,230,21.503.0,24.413.0,43.159.0,26.258.0,22.187.0,18.78.0"}
P.entries["subzone:dalson-s-tears"] = {n="Dalsons Tränenfeld",s="Auf Dalsons Tränenfeld vergiftet ein Kessel der Geißel die Felder der Westlichen Pestländer. Einst als Dalson's Orchard bekannt, wurde dieser Hof während des Dritten Krieges zum Aufmarschplatz der Geißel. Seine ehemaligen Besitzer suchen noch immer die Felder und Nebengebäude heim.",h="Auf Dalsons Tränenfeld vergiftet ein Kessel der Geißel die Felder der Westlichen Pestländer.",kw={"cauldron lord malvinious","dalson's orchard","dalsons tränenfeld","farmer dalson","mrs dalson","pestkessel","westliche pestländer"},ang={["class:Paladin"]="Als Paladin könnt Ihr das Böse erkennen, das in den entweihten Feldern fortbesteht, und die leidenden Seelen der Familie Dalson sehen. Die heiligen Krieger des Lichts haben geschworen, Lordaeron von diesem Bösen zu reinigen.",["race:Undead"]="Für die Verlassenen erinnert dieses zerstörte Gehöft an das Schicksal vieler Menschen aus Lordaeron. Sylvanas Windläufer brach die Kontrolle des Lichkönigs über sie."},sec={{t="Eine vergiftete Ernte",b="Dalsons Tränenfeld war einst Dalson's Orchard, ein ertragreicher Bauernhof in Lordaerons Kornkammer. Verfall erstickt nun die Felder, während ein großer eiserner Kessel in ihrer Mitte grüne Pestdämpfe über das Land verbreitet. Cauldron Lord Malvinious wacht darüber. Verseuchte Zombies, faulende Kadaver und skelettartige Schrecken bewachen die Vorrichtung im Dienste des Lichkönigs."},{t="Das Schicksal der Dalsons",b="Die Familie Dalson fiel der Pest zum Opfer, und der Tod brachte ihr keine Erlösung. Mrs. Dalson, die Frau von Farmer Dalson, wandert als geistloses Skelett mit dem Schlüssel zum Plumpsklo des Hofes über den vergifteten Boden. In der verschlossenen Hütte wartet der Ghul, der einst Farmer Dalson war. Seine verzweifelte Frau sperrte ihn ein, bevor beide dem Fluch der Geißel erlagen."}},faq={{q="Wie hieß Dalsons Tränenfeld vor der Pest?",a="Vor der Pest hieß der Hof Dalson's Orchard, ein blühendes Stück Land in Lordaeron. Der Dritte Krieg verwüstete das Land.",al={"dalson's orchard","ursprünglicher name","wie hieß dieser hof"}},{q="Warum steht mitten auf dem Hof ein riesiger Kessel?",a="Die Geißel errichtete große Pestkessel auf Lordaerons Ackerland, um ohne Unterlass Giftstoffe zu sieden. Ihre Dämpfe ziehen über die Region, lassen die Erde veröden, vergiften die Wasservorräte und verderben Lebewesen, die ihnen ausgesetzt sind.",al={"dalson kessel","grüner rauch kessel","warum steht hier ein kessel"}},{q="Wer bewacht den Kessel auf Dalsons Tränenfeld?",a="Cauldron Lord Malvinious beschützt den Pestkessel. Die Geißel dient ihm, mit verseuchten Zombies, skelettartigen Schrecken und faulenden Kadavern an seiner Seite.",al={"cauldron lord","wer ist hier der boss","cauldron lord malvinious"}},{q="Was ist über das verschlossene Plumpsklo bekannt?",a="Das verschlossene Plumpsklo gehört zum verlassenen Hof. Das Tagebuch von Mrs. Dalson gibt Hinweise auf das Schicksal der Familie.",al={"plumpsklo monster","wer ist im plumpsklo","farmer dalson"}}},fp="14,230,18.343.0,23.337.1,49.123.0,56.228.0,42.153.0,40.105.1"}
P.entries["subzone:dandred-s-fold"] = {n="Dandreds Senke",s="Gesetzlose des Syndikats halten Dandreds Senke am nordwestlichen Ufer des Lordameresees. Gehöft und Herrenhaus bieten Lord Aliden Perenolde und seinen Mitverschwörern Unterschlupf. Horde und Allianz beobachten das Anwesen aus unterschiedlichen Gründen.",h="Gesetzlose des Syndikats halten Dandreds Senke am nordwestlichen Ufer des Lordameresees.",kw={"aliden perenolde","argus wake","dandreds senke","elysa","der lordameresee","nagaz","syndikat","das oberland"},ang={["faction:Alliance"]="Die Allianz kann ein Bündnis zwischen menschlichen Gesetzlosen und dem dämonischen Argus Wake nicht dulden. Magistrat Henry Maleb befiehlt Angriffe auf das Anwesen.",["faction:Horde"]="Für die Horde ist Dandreds Senke eine persönliche Angelegenheit. Kriegshäuptling Thrall will Taretha Foxtons Halskette zurückerlangen."},sec={{t="Adelszuflucht in gesetzlosen Händen",b="Am westlichen Rand des Oberlands liegt Dandreds Senke am Lordameresee, abgeschieden vom Umland. Das Anwesen war einst friedlich und gehörte möglicherweise einem Alteraci-Adligen namens Dandred. Nach dem Fall von Alterac machte das Syndikat daraus einen befestigten Zufluchtsort. Seine Assassinen und Vollstrecker patrouillieren auf dem Gelände. Sie halten die Behörden von Süderstade und die Verlassenen jenseits des Sees vom gestürzten Adel fern, der hier Zuflucht gefunden hat."},{t="Ein Knotenpunkt der Intrigen",b="Lord Aliden Perenolde führt das Syndikat und nutzt Dandreds Senke als Stützpunkt. Seine Mätresse Elysa ist dort bei ihm. Auch Nagaz hat sich im Herrenhaus eingerichtet. Als abtrünniger Orc des Schattenrats vom Argus Wake vermittelt er dunkle Pakte mit den menschlichen Banditen. Dieses Bündnis hat die Aufmerksamkeit der Magistrate von Süderstade und der Champions der Horde erregt."}},faq={{q="Wer kontrolliert Dandreds Senke?",a="Das Syndikat hält Dandreds Senke besetzt. Es ist ein aristokratisches Verbrechernetzwerk unter der Führung der entmachteten Adligen von Alterac, dessen Assassinen und Vollstrecker das Anwesen unter Lord Aliden Perenolde bewachen.",al={"wer ist in dandreds senke","wer lebt in dandreds senke","dandreds senke gegner"}},{q="Warum interessiert sich die Horde für dieses Anwesen?",a="Die Horde nimmt das Herrenhaus ins Visier, um Lord Aliden Perenolde niederzustrecken und ein gestohlenes Erinnerungsstück zurückzuholen. Es ist die als Erbstück überlieferte Halskette von Taretha Foxton, Thralls Retterin und Vertrauter aus seiner Kindheit.",al={"horde dandreds senke","warum geht die horde nach dandreds senke"}},{q="Warum schickt die Allianz Abenteurer hierher?",a="Magistrat Henry Maleb aus Süderstade schickt Agenten der Allianz aus, um Nagaz zu beseitigen. Er ist ein gefährliches Mitglied des Kults Argus Wake und paktiert mit den Gesetzlosen des Syndikats.",al={"allianz dandreds senke","magistrat maleb quest dandreds senke"}},{q="Wer war Dandred?",a="Kein gesicherter Bericht gibt Auskunft über Dandreds Identität. Das Anwesen trägt seinen Namen, doch sein ursprünglicher Besitzer ist unbekannt.",al={"wer ist dandred","dandred hintergrundgeschichte"}}},fx={e469c160={q="Was ist Dandreds Senke?",a="Dandreds Senke ist eine abgelegene Farm und ein Herrenhaus auf den westlichen Hochebenen vom Alteracgebirge, die an die nebligen Ufer vom Lordameresee grenzt. Einst ein friedliches Adelsgut, dient es heute als befestigter Zufluchtsort und Operationsbasis für das Syndikat.",al={"was ist dandreds senke","dandreds senke in alterac","über dandreds senke"}},b8b5cedb={q="Was geschah in Dandreds Senke?",a="Nach dem Zusammenbruch vom Königreich Alterac fiel diese Farm am See in die Hände vom Syndikat. Lord Aliden Perenolde verwandelte das abgelegene Herrenhaus in eine persönliche Festung und einen Rückzugsort und schmiedete gefährliche Verbindungen mit zwielichtigen Organisationen wie der Argus Wake.",al={"geschichte von dandreds senke","was geschah mit dandreds senke"}},fc1f4fab={q="Ist Dandreds Senke gefährlich?",a="Für alleinreisende Reisende ist es extrem gefährlich. Das Gelände wird von erfahrenen Vollstreckern des Syndikats, verstohlenen Halsabschneidern und verdeckten Agenten der Argus Wake bewacht, die alle Lord Aliden Perenolde treu ergeben und gegenüber Außenstehenden feindselig eingestellt sind.",al={"ist dandreds senke gefährlich","gefahr bei dandreds senke","wer ist in dandreds senke"}}},fp="14,219,36.429.0,20.340.1,28.188.0,42.185.1,44.167.0,16.102.0"}
P.entries["subzone:dark-portal"] = {n="Das Dunkle Portal",s="Am Südrand der Verwüsteten Lande birgt das ruhende Dunkle Portal einen Riss zwischen Welten. Seine Öffnung brachte die Alte Horde nach Azeroth und löste den Ersten Krieg aus.",h="Am Südrand der Verwüsteten Lande birgt das ruhende Dunkle Portal einen Riss zwischen Welten.",kw={"schwarzer morast","verwüstete lande","das dunkle portal","draenor","great portal","guldan","khadgar","medivh"},ang={["faction:Alliance"]="Für die Allianz erinnert das Dunkle Portal an den Ersten Krieg und den Fall des alten Sturmwind. Die Magier von Nethergarde halten ohne Unterlass Wache darüber.",["race:Orc"]="Für Euer Volk steht das Dunkle Portal für eine schmerzliche Vergangenheit. Unter dämonischen Herren marschierte die Alte Horde hindurch und verließ ihre angestammte Heimat, um Krieg zu führen."},sec={{t="Ein Riss zwischen Wirklichkeiten",b="Wo sich einst der Schwarze Morast über den Süden erstreckte, riss das Dunkle Portal auf. Medivh, von Sargeras besessen, verband seine Tirisfal-Magie mit Gul'dans Teufelszauberei auf Draenor. Ihr Ritual zehrte unzählige Leben auf und riss die Wirklichkeit auseinander. Die Alte Horde verankerte den Riss mit gewaltigem Mauerwerk und marschierte hindurch, um das Königreich von Sturmwind im Ersten Krieg zu zerschlagen.\n\nTeufelsmacht aus dem Portal vergiftete das Land. Üppige Sümpfe wurden zu den roten, versteinerten Ödlanden, die Ihr heute seht."},{t="Wacht am ruhenden Tor",b="Nachdem die Allianz von Lordaeron den Zweiten Krieg gewonnen hatte, zerschmetterte Erzmagier Khadgar den Steinrahmen des Portals mit mächtiger Magie. Er hoffte, Draenor für immer von Azeroth zu trennen, doch der Riss darunter ließ sich nicht zerstören. Die Allianz errichtete in der Nähe Burg Nethergarde, um die Narbe zu überwachen.\n\nDämonen und Überreste des Schattenrats schleichen noch immer durch die verwüstete Caldera. Das Tor wurde wieder zusammengesetzt, doch es ruht weiterhin. Es ist eine stille Wunde zwischen Welten, die keine Seite aufzugeben wagt."}},faq={{q="Könnt Ihr gerade durch das Dunkle Portal gehen?",a="Nein. Der Steinrahmen des Dunklen Portals ist unversehrt, doch der Riss darin ruht. Kein Reisender kann ihn derzeit durchqueren.",al={"kann ich das dunkle portal betreten","ist das dunkle portal offen","portal nach outland"}},{q="Wer hat das Dunkle Portal ursprünglich erbaut?",a="Medivh, der menschliche Guardian auf Azeroth, und Gul'dan, der Hexenmeister auf Draenor, erschufen das Dunkle Portal in einem gemeinsamen Ritual. Ihr Werk setzte die Invasion in Gang, mit der der Erste Krieg begann.",al={"wer erschuf das dunkle portal","medivh guldan portal","erschaffer des dunklen portals"}},{q="Warum wacht Burg Nethergarde darüber?",a="Nachdem Erzmagier Khadgar nach dem Zweiten Krieg den ersten Rahmen des Portals zerschmettert hatte, überzeugte er die Allianz, dessen Ruinen zu bewachen. Die Allianz gründete Burg Nethergarde, um für den Fall einer Rückkehr der Bedrohungen Wache zu halten.",al={"warum ist burg nethergarde hier","nethergarde portalwache","warum nethergarde"}},{q="Warum ist der Boden um das Portal rot und karg?",a="Die Verwüsteten Lande waren einst der fruchtbare Schwarze Morast. Teufelsmagie, die die Wirklichkeit aufriss, Verderbnis aus Draenor und dämonische Bestien vergifteten den Boden und versteinerten das Land.",al={"warum sind die verwüsteten lande tot","portalverderbnis","warum sind die verwüsteten lande rot"}}},fp="11,160,23.477.0,17.496.0,47.108.0,37.185.0,40.207.0,51.171.0"}
P.entries["subzone:darkcloud-pinnacle"] = {n="Düsterwolkengipfel",s="Grimtotem-Tauren halten den Düsterwolkengipfel über der Schlucht östlich des Großen Aufzugs. Von ihren verbundenen Tafelbergen aus stiften sie Unruhe in der Region und gehen geheimen Geschäften nach.",h="Grimtotem-Tauren halten den Düsterwolkengipfel über der Schlucht östlich des Großen Aufzugs.",kw={"arnak grimtotem","düsterwolkengipfel","grimtotem","harb foulmountain","tafelberg","tausend nadeln"},ang={["faction:Horde"]="Als Mitglied der Horde begegnen Euch die Grimtotem hier mit Feindseligkeit. Sie bedrohen Reisende, die vom Großen Aufzug nach Tausend Nadeln ziehen.",["race:Tauren"]="Als Tauren seht Ihr, wie der Verrat der Grimtotem auf diesen Tafelbergen der Einheit und dem Frieden entgegensteht, die Cairne Bluthuf unter den Stämmen anstrebt."},sec={{t="Eine Festung auf Klippen",b="Der Düsterwolkengipfel erhebt sich auf drei großen, durch Seilbrücken verbundenen Tafelbergen über dem Schluchtbecken. Ihr könnt vom Schluchtboden einen steilen natürlichen Hang hinaufsteigen und dann Holzbrücken überqueren. Ein hoch gelegener Übergang nahe den Hügeln der Klingenhauer bietet einen weiteren Aufstieg. Von diesen windgepeitschten Felsen aus überblicken Wachposten der Grimtotem das Tal. Die Höhen schützen sie vor einfachen Angriffen und halten sie von den übrigen Taurenstämmen fern."},{t="Intrigen auf den Tafelbergen",b="Arnak Grimtotem und Harb Foulmountain gehören zu den Anführern, die den Düsterwolkengipfel lenken. Auf dem Tafelberg gefundene Korrespondenz deutet auf Geschäfte der Grimtotem mit dunklen, unbekannten Mächten hin. Ihre Ambitionen reichen über den Frieden hinaus, den Cairne Bluthuf in Donnerfels geschmiedet hat."}},faq={{q="Wer kontrolliert den Düsterwolkengipfel?",a="Der Grimtotem-Klan hält den Düsterwolkengipfel. Diese aggressiven, zurückgezogen lebenden Tauren stehen den meisten Außenstehenden feindselig gegenüber und misstrauen der Horde zutiefst.",al={"wer lebt auf dem düsterwolkengipfel","besitzer des düsterwolkengipfels","wer ist auf dem düsterwolkengipfel"}},{q="Wie erreicht Ihr den Düsterwolkengipfel?",a="Ihr könnt vom Schluchtboden eine natürliche Rampe zu einem benachbarten Tafelberg hinaufsteigen und dann hölzerne Seilbrücken überqueren. Ein weiterer Weg führt über eine Brücke nahe den Hügeln der Klingenhauer.",al={"wie kommt man auf den düsterwolkengipfel","weg zum düsterwolkengipfel","zugang zum düsterwolkengipfel"}},{q="Wer führt die Grimtotem hier an?",a="Arnak Grimtotem und Harb Foulmountain gehören zu den bedeutenden Persönlichkeiten der Grimtotem, die die Siedlung beaufsichtigen.",al={"anführer des düsterwolkengipfels","wer führt den düsterwolkengipfel","grimtotem-anführer"}},{q="Was planen die Grimtotem hier?",a="Die Grimtotem auf dem Düsterwolkengipfel stehen in geheimem Austausch mit einem unbekannten dunklen Einfluss. Ihre finsteren Ziele bedrohen die Stabilität in Tausend Nadeln.",al={"was geschieht auf dem düsterwolkengipfel","grimtotem-verschwörung"}}},fx={["0ab7147f"]={q="Was ist der Düsterwolkengipfel?",a="Der Düsterwolkengipfel ist ein befestigtes Dorf der Tauren, das hoch über dem Grund des Canyons der Tausend Nadeln liegt, direkt östlich vom großen Aufzug. Es erstreckt sich über drei bewohnte Mesas, die durch hängende Seilbrücken miteinander verbunden sind. Die Siedlung dient als wichtige Festung für den Stamm der Grimtotem, einen aggressiven und isolationistischen Tauren-Clan, der sein Territorium eifersüchtig gegen Außenstehende verteidigt.",al={"was ist der düsterwolkengipfel","infos zum düsterwolkengipfel","über den düsterwolkengipfel"}},["44a431c5"]={q="Ist der Düsterwolkengipfel gefährlich?",a="Sehr gefährlich. Die Tauren der Grimtotem, die den Düsterwolkengipfel besetzen, sind gegenüber Eindringlingen gewalttätig und feindselig eingestellt und halten die gesamte Siedlung schwer bewacht. Mit seinen hohen Mesas und schmalen Seilbrücken birgt ein Kampf hier die ständige Gefahr, in den darunter liegenden Canyon zu stürzen, und die Schamanen und Krieger des Stammes sind bereit, jeden zu töten, der sich die Hänge hinaufwagt.",al={"gefahr am düsterwolkengipfel","wie gefährlich ist der düsterwolkengipfel","ist der düsterwolkengipfel gefährlich"}}},fp="18,158,21.398.0,20.259.1,32.146.0,36.155.0,29.106.0,37.154.1"}
P.entries["subzone:darkened-bank"] = {n="Das Dunkle Ufer",s="Am Nordrand des Dämmerwalds verläuft das Dunkle Ufer neben dem Wald von Elwynn. Es reicht nach Osten zum Rotkammgebirge, zwischen sichererem Boden und den Schrecken des Waldes.",h="Am Nordrand des Dämmerwalds verläuft das Dunkle Ufer neben dem Wald von Elwynn.",kw={"das dunkle ufer","dämmerwald","wald von elwynn","lars","fluss","uferlinie","sven yorgen"},ang={["faction:Alliance"]="Als Abenteurer der Allianz könnt Ihr nach dem Verlassen des Waldes von Elwynn zuerst am Dunklen Ufer haltmachen, bevor Ihr tiefer ins heimgesuchte Herz des Dämmerwalds vordringt."},sec={{t="Eine unsichere Grenze",b="Das Dunkle Ufer folgt dem Fluss, der den Dämmerwald vom Wald von Elwynn trennt. Es erstreckt sich von den westlichen Flussbiegungen bis zur Steinbrücke, die ins Rotkammgebirge führt. Unter dem düsteren Blätterdach des Dämmerwalds erreichen Reisende aus Elwynn auf ihrem Weg nach Süden oft zuerst dieses Gebiet. Nahe der westlichen Spitze bietet ein Behelfslager den Vertriebenen Sven Yorgen und Lars Schutz, unmittelbar außerhalb der tiefen Wälder."}},faq={{q="Wo liegt das Dunkle Ufer?",a="Das Dunkle Ufer folgt dem nördlichen Flussufer des Dämmerwalds, gegenüber dem Wald von Elwynn. Es reicht vom äußersten Westen des Gebiets bis zur Brücke ins Rotkammgebirge.",al={"dunkles ufer lage","wo liegt das dunkle ufer","dunkles ufer dämmerwald"}},{q="Wer lebt am Dunklen Ufer?",a="Ein bescheidenes Zufluchtslager am äußersten Westrand bietet Sven Yorgen und Lars Schutz. Ihrem früheren Leben tiefer im Gebiet entrissen, nutzen sie das Flussufer als unsicheren Zufluchtsort und suchen Hilfe gegen die Bedrohungen des Dämmerwalds.",al={"lager am dunklen ufer","wer ist am dunklen ufer","dunkles ufer npcs"}},{q="Wie erreichen Reisende dieses Gebiet gewöhnlich?",a="Ihr könnt das westliche Ufer erreichen, indem Ihr vom Südwesten des Waldes von Elwynn aus nach Süden über den Fluss schwimmt. Oder folgt dem südlichen Flussufer von der Brücke zum Rotkammgebirge aus nach Westen.",al={"wie gelangt man zum dunklen ufer","weg zum dunklen ufer"}}},fx={["84b37a17"]={q="Was ist das Dunkle Ufer?",a="Das Dunkle Ufer ist der lange nördliche Küstenstreifen des Dämmerwalds, der sich vom westlichen Rand des Waldes nach Osten in Richtung der Brücke erstreckt, die in das Rotkammgebirge führt. Wenn Ihr über den Fluss auf den Wald von Elwynn blickt, markiert dieses Grenzland den Übergang vom goldenen Licht des Nordens in die unnatürliche Finsternis, die den Dämmerwald einhüllt.",al={"was ist das dunkle ufer","dunkles ufer dämmerwald","erzähle mir vom dunklen ufer"}},["180e4478"]={q="Ist das Dunkle Ufer gefährlich?",a="Obwohl das Dunkle Ufer im Vergleich zu den tödlichen Schrecken, die tiefer im Dämmerwald lauern, eine Heimat für relativ schwächere Wildtiere und Raubtiere ist, ist es alles andere als sicher. Raubtiere streifen durch das Unterholz entlang des Flussufers, und Flüchtlinge, die am westlichen Ufer kampieren, bleiben in höchster Alarmbereitschaft gegenüber der sich ausbreitenden Dunkelheit.",al={"gefahr dunkles ufer","ist das dunkle ufer sicher","bedrohungen dunkles ufer"}}},fp="13,174,21.383.0,35.177.0,34.221.0,41.163.0"}
P.entries["subzone:darkmist-cavern"] = {n="Graunebelhöhlen",s="Graunebelspinnen wimmeln in der alten Mine im Nordwesten der Düstermarschen. Verfallene Hütten stehen am Eingang, und die Einheimischen streiten noch immer darüber, ob die Höhle oder die Brut den Namen zuerst trug.",h="Graunebelspinnen wimmeln in der alten Mine im Nordwesten der Düstermarschen.",kw={"graunebelhöhlen","graunebelspinnen","düstermarschen","minenruinen","spinnenmine","sumpfauge jarl"},ang={["profession:Cooking"]="Der Einsiedler ‚Sumpfauge‘ Jarl bezeichnet Graunebelspinnenaugen als die beste Zutat für Sumpfeintopf. Außerhalb des Sumpfes teilen nur wenige seinen Geschmack.",["profession:Mining"]="Bergleute haben die Höhle einst ausgehöhlt. Wer ihre felsigen Tiefen nach Erz absuchen will, muss sich zuerst den dort nistenden Spinnen stellen."},sec={{t="Die Brut in der Mine",b="Verrottende Hütten stehen vor den Graunebelhöhlen im Nordwesten der Düstermarschen. Dichte Spinnweben verstopfen die Tunnel. Einst kamen Menschen wegen der Mine hierher, doch heute ist kein Mensch mehr hier. Nun bevölkern Graunebelspinnen die Gänge. Ihre Größe und ihr Gift machen sie für unvorsichtige Wanderer tödlich.\n\nDie Sumpfbewohner streiten noch immer darüber, wie die Höhle zu ihrem Namen kam. Manche sagen, sie sei nach der Brut benannt worden, die darin nistet. Andere sagen, die Spinnen hätten ihren Namen von der nebligen Höhle erhalten."},{t="Die Vorratskammer des Einsiedlers",b="Selbst diese von Spinnweben verstopfte Höhle zieht Plünderer an. Der Einsiedler ‚Sumpfauge‘ Jarl schickt Reisende tief in ihre Gespinste, um die Augen monströser Spinnen zu sammeln. Er behauptet, sie ergäben eine vorzügliche Brühe. Die meisten vernünftigen Reisenden meiden den von Spinnweben bedeckten Eingang."}},faq={{q="Was sind die Graunebelhöhlen?",a="Die Graunebelhöhlen sind eine verlassene Mine im Nordwesten der Düstermarschen, die heute von riesigen, giftigen Graunebelspinnen bevölkert wird.",al={"was sind die graunebelhöhlen","graunebelhöhlen","spinnenhöhle düstermarschen"}},{q="Wer lebte in den Ruinen vor der Höhle?",a="Die Ruinen vor der Höhle deuten darauf hin, dass dort einst eine Siedlung oder ein Bergbaulager stand, doch niemand weiß, wer dort lebte.",al={"wer lebte hier","häuser vor den graunebelhöhlen","verlassenes dorf graunebel"}},{q="Warum wagen sich Einheimische in die Graunebelhöhlen?",a="Nur wenige betreten die Graunebelhöhlen freiwillig. Der Einsiedler ‚Sumpfauge‘ Jarl schickt wagemutige Reisende in ihre Tunnel, um Spinnenaugen für seinen seltsamen Sumpfeintopf zu holen.",al={"warum in die graunebelhöhlen gehen","graunebelhöhlen quest"}},{q="Trugen die Spinnen oder die Höhle den Namen zuerst?",a="Die Bewohner der Düstermarschen sind sich uneins, ob die Höhle nach den Spinnen benannt wurde oder die Spinnen nach der Höhle. Keine gesicherte Überlieferung gibt Auskunft darüber, welcher Name zuerst da war.",al={"herkunft des spinnennamens","warum heißt es graunebel"}}},fp="15,174,21.445.0,15.248.0,24.120.0,40.114.0,43.160.0,49.169.0"}
P.entries["subzone:darkshire"] = {n="Dunkelhain",s="Dunkelhains Nachtwache hält stand, während die unnatürliche Finsternis des Dämmerwalds die Stadt umschließt. Mit wenig Hilfe aus Sturmwind müssen die Menschen ihre Häuser selbst beschützen.",h="Dunkelhains Nachtwache hält stand, während die unnatürliche Finsternis des Dämmerwalds die Stadt umschließt.",kw={"brightwood","dunkelhain","dämmerwald","schwarzhaupt","grand hamlet","night watch","scarlet raven"},ang={["class:Paladin"]="Als Paladin findet Ihr Tote, die auf jedem umliegenden Friedhof auferstehen, und verängstigte Einheimische, die das Licht beinahe vergessen haben. Rings um das Dorf breitet sich vielerorts unheilige Verderbnis aus.",["faction:Alliance"]="Für die Allianz zeigt Dunkelhain, wie die Grenzgebiete des Königreichs zerfallen. Die Stadtbewohner sind ihren Helden dankbar, doch gegenüber dem untätigen Adel in Sturmwind empfinden sie Verbitterung."},sec={{t="Eine verlassene Stadt",b="Dunkelhain begann als Grand Hamlet, eine friedliche Waldsiedlung. Die Alte Horde machte sie im Ersten Krieg dem Erdboden gleich, und das Dorf wurde wieder aufgebaut. Nachdem Medivh in Karazhan gefallen war, machten die in den umliegenden Wäldern nachwirkenden Todeswehen sie zur schattigen Wildnis des Dämmerwalds.\n\nDunkelhain gehört zum Königreich Sturmwind, doch die Krone schickt dem Rathaus so gut wie keine Hilfe. Politische Lähmung in Sturmwind hat die Garnison unbesetzt und die Grenzen unbewacht gelassen. Bürgermeister Ello Schwarzhaupt und der örtliche Rat regieren allein und setzen in den Schatten eine harte, abgeschottete Justiz durch."},{t="Die Front im Dunkeln",b="Wandelnde Tote von den westlichen Friedhöfen und wilde Worgen aus den Wäldern bedrängen Dunkelhains Palisaden. Die Nachtwache, eine freiwillige Bürgermiliz unter der Führung von Althea Schwarzhaupt, ist der wichtigste Schutz der Stadt. Vom Stadtplatz aus patrouillieren erschöpfte Wachposten auf den pechschwarzen Straßen, halten sie offen und schlagen die Schrecken am Waldrand zurück.\n\nIn der Scarlet Raven Tavern treffen Reisende auf misstrauische, verängstigte Einheimische, die verzweifelt nach jedem suchen, der eine Klinge führen kann."}},faq={{q="Warum wurde die Stadt von Grand Hamlet umbenannt?",a="Die Siedlung hieß Grand Hamlet, als die Region noch ein sonniger Wald war. Nachdem Medivh im nahen Karazhan gestorben war, breitete sich dunkle Magie in den Wäldern aus, versperrte das Sonnenlicht und erweckte die Toten. Als der Wald zum Dämmerwald verkam, benannten die Bewohner das Dorf in Dunkelhain um, passend zu ihrer düsteren, verfluchten Umgebung.",al={"warum heißt es dunkelhain","grand hamlet namensänderung","geschichte von dunkelhain"}},{q="Warum hilft Sturmwind nicht bei der Verteidigung Dunkelhains?",a="Sturmwind zog seine Truppen während der politischen Unruhen nach dem Verschwinden von König Varian Wrynn aus dem Dämmerwald ab. Die Stadtbewohner gründeten die Nachtwache, um sich den Bedrohungen zu stellen, die die Krone nicht länger eindämmte.",al={"wo ist die stormwind army","warum keine wachen im dämmerwald","warum hat sturmwind dunkelhain verlassen"}},{q="Wer führt Dunkelhain?",a="Lord Ello Schwarzhaupt und der Rat von Dunkelhain üben gemeinsam mit Amtmann Daltry vom Rathaus aus die zivile Gewalt aus. Ellos Tochter, Kommandantin Althea Schwarzhaupt, führt die Nachtwache bei der Verteidigung der Stadt an.",al={"wer hat in dunkelhain das sagen","führung von dunkelhain","bürgermeister von dunkelhain"}},{q="Was ist die Nachtwache?",a="Die Nachtwache ist eine Bürgermiliz, die Althea Schwarzhaupt aus der Not heraus gründete. Da keine Truppen der Sturmwind Army in den Dämmerwald entsandt werden, patrouillieren die Bewohner auf den düsteren Straßen, bewachen die Grenzen und vertreiben Ghule und wilde Bestien.",al={"was ist die night watch","wachen von dunkelhain","wer beschützt dunkelhain"}},{q="Wer war Morgan Ladimore?",a="Morgan Ladimore war ein Veteran, der nach dem Dritten Krieg zurückkehrte und sein Zuhause verwüstet und seine Familie verschwunden vorfand. Seine Suche führte ihn nach Dunkelhain, wo örtliche Berichte den Rest seiner Geschichte bewahren.",al={"morla dime hintergrundgeschichte","ladimore dunkelhain","wer ist dieser ladimore"}}},fx={["59ecffc1"]={q="Was ist Dunkelhain?",a="Dunkelhain ist die letzte überlebende menschliche Siedlung im Dämmerwald. Einst ein friedliches Walddorf namens Grand Hamlet, steht es heute als isolierter, belagerter Außenposten, gehüllt in ewige Finsternis. Die Stadt beherbergt ein Gasthaus, einen Schmied und ein Rathaus und dient als einzige Zuflucht für Reisende und die bedrängten Einheimischen, die den Schrecken des Waldes trotzen.",al={"was ist das für eine stadt","erzähle mir von dunkelhain","informationen über dunkelhain"}},a7f74618={q="Wer lebt in Dunkelhain?",a="Dunkelhain wird von hartnäckigen, schreckhaften Einheimischen, Handwerkern und der lokalen Regierung unter der Führung von Lord Ello Schwarzhaupt und Amtmann Daltry bewohnt. Die Bevölkerung wird von Althea Schwarzhaupt und ihrer freiwilligen Miliz, der Nachtwache, verteidigt und lebt in ständiger Angst und Misstrauen. Abgeschnitten von königlicher Hilfe, sind sie dennoch entschlossen, ihre angestammte Heimat gegen die vordringende Dunkelheit zu verteidigen.",al={"wer lebt hier","bewohner von dunkelhain","wer lebt in dunkelhain"}},a9d39424={q="Ist Dunkelhain gefährlich?",a="Obwohl die Siedlung selbst schwer von der Nachtwache bewacht wird, drängt die Gefahr bis an ihre Tore. Untote bevölkern nahegelegene Friedhöfe und Straßen, grausame Worgen streifen durch die dunklen Wälder und Sturmwind hat die Region ihrem Schicksal überlassen. Wer sich ohne Eskorte außerhalb des fahlen Laternenlichts der Stadt wagt, begibt sich in Lebensgefahr.",al={"ist es hier sicher","ist dunkelhain gefährlich","wie gefährlich ist dunkelhain"}},["2c565dbf"]={q="Was geschah in der Vergangenheit mit Dunkelhain?",a="Ursprünglich als Grand Hamlet in damals sonnigen Wäldern gegründet, wurde die Stadt während des Ersten Krieges von der Alten Horde dem Erdboden gleichgemacht. Nach dem Zweiten Krieg wiederaufgebaut, erlebte die Siedlung einen langsamen Abstieg in den Schrecken, als Medivhs Tod den umliegenden Wald in den Dämmerwald verwandelte. Als ewiges Zwielicht das Land einhüllte, nahm die Stadt den Namen Dunkelhain an.",al={"geschichte von dunkelhain","geschichte von grand hamlet","was geschah mit grand hamlet"}}},fp="9,162,16.570.0,20.462.0,43.311.0,45.189.0,20.208.0,24.224.0,24.200.0"}
P.entries["subzone:darkshire-town-hall"] = {n="Rathaus von Dunkelhain",s="Im Rathaus von Dunkelhain regieren Bürgermeister und Rat eine von Dunkelheit und Untoten belagerte Stadt. Seine dämmrigen Hallen sind der Sitz ihrer Herrschaft.",h="Im Rathaus von Dunkelhain regieren Bürgermeister und Rat eine von Dunkelheit und Untoten belagerte Stadt.",kw={"amtmann daltry","rat","dunkelhain","dämmerwald","ello schwarzhaupt","rathaus"},ang={["faction:Alliance"]="Für Reisende der Allianz spiegelt das Rathaus die zerbrechliche Autorität an der südlichen Grenze des Königreichs und die Grenzen von Sturmwinds Schutz in isolierten Siedlungen wider."},sec={{t="Dunkelhains Regierungssitz",b="Unmittelbar westlich von Dunkelhains Hauptplatz liegt das Rathaus, von dem aus die Stadtführung ein zunehmend isoliertes Gebiet regiert. Bürgermeister Lord Ello Schwarzhaupt ringt darum, die Ordnung zu wahren und die Bevölkerung zu schützen, während Sturmwind kaum militärische Hilfe schickt.\n\nAmtmann Daltry und andere Beamte führen die städtischen Aufzeichnungen und erfassen Reisende, die den gefährlichen Straßen des Dämmerwalds trotzen. Angesichts der allgegenwärtigen Gefahr ist es eine düstere Aufgabe, diese Register auf dem neuesten Stand zu halten."}},faq={{q="Wer führt die Stadt von diesem Gebäude aus?",a="Lord Ello Schwarzhaupt führt Dunkelhain als Bürgermeister und hat vom Rathaus aus den Vorsitz im Stadtrat. Er leitet die örtliche Verteidigung und bittet durchreisende Abenteurer um Hilfe, da Sturmwind fast keine Verstärkung schickt.",al={"wer ist der bürgermeister","wer regiert dunkelhain","wer ist im rathaus"}},{q="Welche Aufzeichnungen werden im Rathaus geführt?",a="Amtmann Daltry führt städtische Register über Einwohner und Reisende, die Dunkelhain passieren. Durch das Chaos und die häufigen Gefahren im Dämmerwald sind viele Aufzeichnungen veraltet.",al={"amtmann daltrys aufzeichnungen","was macht daltry","stadtregister"}},{q="Warum ist das Rathaus so wichtig für das Überleben des Dämmerwalds?",a="Da der Dämmerwald von direkter militärischer Unterstützung aus Sturmwind abgeschnitten ist, dient das Rathaus als Arbeitszentrale der Nachtwache und der örtlichen Behörden. Der Rat koordiniert die zivile Verteidigung und schickt Hilfe in die gesamte schattenverhangene Region.",al={"warum ist das rathaus wichtig","rolle des stadtrats von dunkelhain"}}},fx={e48299c3={q="Was ist das Rathaus von Dunkelhain?",a="Das Rathaus von Dunkelhain dient als administratives Herz und Sitz der lokalen Regierung für die Siedlung Dunkelhain. Das Gebäude befindet sich am westlichen Rand des Stadtplatzes und ist der Ort, an dem lokale Anführer, Ratsmitglieder und städtische Beamte zivile Angelegenheiten koordinieren, öffentliche Register führen und versuchen, eine verängstigte Bevölkerung zu regieren, die von der verwüsteten Wildnis des Dämmerwalds umgeben ist.",al={"was ist das rathaus von dunkelhain","zweck rathaus von dunkelhain","über das rathaus von dunkelhain"}},bcc317cc={q="Wer lebt oder arbeitet im Rathaus von Dunkelhain?",a="Das Rathaus wird von Bürgermeister Lord Ello Schwarzhaupt und dem Rat von Dunkelhain geleitet, zusammen mit Verwaltungspersonal wie Amtmann Daltry. Es fungiert nicht als privater Wohnsitz, sondern als kommunales Zentrum, in dem Dunkelhains Zivilbehörden, Historiker und Schreiber täglich daran arbeiten, Stadtregister zu führen, zivile Angelegenheiten zu verwalten und über die Verteidigung der Siedlung zu beraten.",al={"wer arbeitet im rathaus von dunkelhain","wer ist im rathaus von dunkelhain","personal rathaus von dunkelhain"}},["8f432bfa"]={q="Ist das Rathaus von Dunkelhain gefährlich?",a="Das Gebäude selbst ist einer der sichersten Zufluchtsorte im Dämmerwald. Schwer bewacht von der Nachtwache und umgeben vom Verteidigungsring der Stadt, bleibt es sicher vor Untoten, wilden Tieren und dunkleren Bedrohungen, die im umliegenden Wald lauern, solange die Stadtgrenzen gegen Angriffe von außen halten.",al={"ist das rathaus von dunkelhain sicher","gefahr rathaus von dunkelhain","gefahr im rathaus von dunkelhain"}}},fp="19,134,21.415.0,38.223.0,43.163.0,57.227.0"}
P.entries["subzone:darkspear-strand"] = {n="Strand der Dunkelspeere",s="Der Strand der Dunkelspeere bietet den Trollen Zuflucht, die von den Echoinseln flohen. Sie landeten an Durotars Südküste und errichteten unter Vol'jins Führung das nahe gelegene Sen'jin.",h="Der Strand der Dunkelspeere bietet den Trollen Zuflucht, die von den Echoinseln flohen.",kw={"dunkelspeer","strand der dunkelspeere","durotar","die echoinseln","sen'jin","vol'jin","zalazane"},ang={["faction:Horde"]="Für Euch als Mitglied der Horde markiert dieser Strand den Ort, an dem die Dunkelspeer nach dem Verlust ihrer Inselheimat an Kalimdors Südküste neben ihren verbündeten Orcs Fuß fassten.",["race:Troll"]="Als Dunkelspeertroll erinnert Euch diese Küste an Zalazanes Verrat und Eure Flucht, um Sen'jin zu gründen."},sec={{t="Eine Küste des Exils",b="Die Dunkelspeertrolle landeten hier, nachdem sie die Echoinseln verloren hatten. Hexendoktor Zalazane riss ihre Heimat an sich, also überquerten die Überlebenden die schmale Meerenge und landeten an dieser Küste. Sie sammelten sich nur wenige Meter landeinwärts, statt sich in Durotars lebensfeindlichen roten Einöden zu verstreuen. Dort errichteten sie Sen'jin. Vom Strand aus blickt man über die Brandung auf die Inseln, die sie noch immer zurückzuerobern hoffen."}},faq={{q="Was geschah am Strand der Dunkelspeere?",a="Die Dunkelspeertrolle landeten an dieser Küste, nachdem sie von den Echoinseln geflohen waren. Als Zalazane sich gegen sein Volk wandte, überquerten die Überlebenden das Wasser und sammelten sich in der Nähe, um Sen'jin zu gründen.",al={"warum heißt er strand der dunkelspeere","geschichte des strands der dunkelspeere","was ist das für ein strand"}},{q="Warum verließen die Dunkelspeer die Echoinseln?",a="Die Dunkelspeer verließen die Echoinseln, nachdem Hexendoktor Zalazane seine Sippe verraten und den Geist seiner Stammesgenossen mit dunklem Voodoo versklavt hatte. Häuptling Vol'jin führte die verbliebenen, unverdorbenen Trolle fort, um der völligen Unterwerfung zu entgehen, und sie landeten an diesem Strand.",al={"warum verließen die trolle die echoinseln","zalazane exil","evakuierung der echoinseln"}},{q="Welche Siedlung liegt neben dem Strand der Dunkelspeere?",a="Sen'jin liegt nur wenige Meter landeinwärts vom Strand. Flüchtlinge gründeten es nach ihrer Landung, und es ist der wichtigste Außenposten und das spirituelle Zentrum der Dunkelspeer in Durotar.",al={"dorf nahe dem strand der dunkelspeere","ort neben dem strand","lage von sen'jin"}}},fx={["88a2cf68"]={q="Was ist der Strand der Dunkelspeere?",a="Der Strand der Dunkelspeere ist der Küstenabschnitt von Durotar, der direkt gegenüber den Echoinseln liegt und sich direkt vor Sen'jin befindet. Er dient als der Hauptstrand, an dem die Dunkelspeere nach ihrem tragischen Rückzug aus ihrer Heimatinsel an Land gespült wurden und sich neu formierten.",al={"was ist der strand der dunkelspeere","überlieferung strand der dunkelspeere","über den strand der dunkelspeere"}},["504bffc1"]={q="Warum heißt er Strand der Dunkelspeere?",a="Der Küstenabschnitt trägt den Namen des Stammes der Dunkelspeere, um ihre Landung hier während der Evakuierung von den Echoinseln zu ehren. Er markiert den ersten sicheren Boden, den der Stamm auf dem Festland von Kalimdor erreichte, nachdem er vor dem verräterischen Putsch von Zalazane geflohen war.",al={"warum strand der dunkelspeere","wie bekam der strand der dunkelspeere seinen namen","namensherkunft strand der dunkelspeere"}}},fp="16,171,16.383.0,34.194.0,43.258.0,52.163.0"}
P.entries["subzone:darkwhisper-gorge"] = {n="Die Flüsternde Schlucht",s="Dämonen halten die Flüsternde Schlucht in den südlichen Höhen von Winterquell besetzt. Sie flohen nach Archimondes Fall dorthin und bewachen nun ihre Mineralien und Ebenenrelikte.",h="Dämonen halten die Flüsternde Schlucht in den südlichen Höhen von Winterquell besetzt.",kw={"brennende legion","die flüsternde schlucht","earthcaller franzahl","eye of shadow","hederine","lady hederine","hyjal","vi'el","winterquell"},ang={["class:Warlock"]="Hederine-Dämonen in diesen Höhlen besitzen unverzichtbare planare Komponenten. Die Schlucht stellt Hexenmeister auf die Probe, die mächtigere Beschwörungsrituale wie das für den Doomguard meistern wollen.",["profession:Mining"]="Die gefährlichen Klüfte bergen reichlich Echtsilber und reiche Thoriumadern. Bergleute, die mutig genug sind, an Elitedämonen vorbeizuschlüpfen, können sie erreichen."},sec={{t="Ein Legionsstützpunkt im Schnee",b="In Winterquells südlichen Höhen haben Dämonen die Flüsternde Schlucht zu ihrer Zuflucht gemacht. Nachdem Archimonde auf dem Gipfel von Hyjal gefallen war, verstreuten sich die Überlebenden in den Gebirgszügen. Eine disziplinierte Vorhut ließ sich hier nieder und machte die Grenze zur Festung.\n\nHederine-Dämonen führen den Stützpunkt unter Lady Hederine. Manapirscher, Schlächter und Akolythen verteidigen die Tunnel und feurigen Lager. Am tiefsten Punkt der Schlucht deutet ein versiegelter Torbogen auf Durchgänge hin, die weiter hinauf in den heiligen Berg führen."},{t="Verborgene Reagenzien und seltenes Wissen",b="Die Gefahr hat Abenteurer und Opportunisten nicht vom Reichtum der Schlucht ferngehalten. Ihre Klüfte bergen Echtsilber und dichte Thoriumvorkommen. In den schattigen Grotten verkauft der Wichtelhändler Vi'el teufelsbefleckte Reagenzien wie Teufelsstoff und Gromsblut.\n\nDer schwer fassbare Hochelf Earthcaller Franzahl hütet uraltes metallurgisches Wissen über das Verhütten von seltenem Elementium."}},faq={{q="Warum gibt es so viele Dämonen in Winterquell?",a="Die Dämonen in der Flüsternden Schlucht haben die Invasion der Brennenden Legion auf Hyjal während des Dritten Krieges überlebt. Nachdem Archimonde am Weltbaum gefallen war, zogen sich seine zerschlagenen Streitkräfte in die Klüfte zurück, um sich neu zu sammeln.",al={"warum dämonen hier","flüsternde schlucht legionsgeschichte","woher kamen die dämonen"}},{q="Was ist das versiegelte Tor im hinteren Teil der Schlucht?",a="Ein runenverzierter Torbogen und eine aktive magische Barriere stehen tief im Süden der Schlucht. Sie bewachen einen Gebirgspass, der direkt nach Hyjal führt.",al={"flüsternde schlucht portal","instanzportal winterquell","hyjal tor"}},{q="Wer führt die Dämonen hier an?",a="Die Hederine, eine Sekte dämonischer Invasoren, beherrschen das Lager offenbar unter Lady Hederines Befehl. Sie patrouillieren in den Klüften mit Schlächtern, Akolythen und Teufelshunden, die Manapirscher genannt werden.",al={"flüsternde schlucht boss","hederine anführer","wer beherrscht die flüsternde schlucht"}},{q="Warum sollte sich ein Abenteurer in die Flüsternde Schlucht wagen?",a="Die Flüsternde Schlucht ist außergewöhnlich gefährlich, und Gruppen müssen zusammenarbeiten, um sie sicher zu durchqueren. Hexenmeister suchen nach planaren Bindungen, Priester jagen das seltene Eye of Shadow, und Schmiede und Bergleute suchen reiche Thoriumadern. Gelehrte kommen auf der Suche nach Earthcaller Franzahl.",al={"warum in die flüsternde schlucht gehen","flüsternde schlucht quests","flüsternde schlucht belohnungen"}}},fp="17,154,29.470.0,34.343.0,45.200.0,49.148.0,26.191.0,55.263.0"}
P.entries["subzone:darnassus"] = {n="Darnassus",s="In Teldrassils hohen Ästen birgt Darnassus die Kaldorei als Hauptstadt und Zuflucht. Seine friedlichen Haine und Gewässer sind das spirituelle Herz der Nachtelfen und die wichtigste Bastion der Allianz im nördlichen Kalimdor. Hohepriesterin Tyrande Wisperwind und Erzdruide Fandral Hirschhaupt führen ihr Volk durch die Prüfungen der neu erlangten Sterblichkeit.",h="In Teldrassils hohen Ästen birgt Darnassus die Kaldorei als Hauptstadt und Zuflucht.",kw={"hauptstadt","darnassus","kaldorei","hirschhaupt","teldrassil","tempel des mondes","tyrande"},ang={["faction:Alliance"]="Für Reisende aus den Östlichen Königreichen ist Darnassus ein abgeschiedener, friedlicher Zufluchtsort und die wichtigste Bastion der Allianz auf Kalimdor.",["race:NightElf"]="Für Euch als Kaldorei ist Darnassus die kulturelle und politische Hauptstadt Eures Volkes, ein Neuanfang und eine souveräne Zuflucht nach den erschütternden Opfern des Dritten Krieges."},sec={{t="Zuflucht in den Ästen",b="Darnassus entstand nach dem Dritten Krieg und würdigte das Überleben der Nachtelfen nach dem Verlust der Unsterblichkeit, die ihr heiliger Weltbaum Nordrassil ihnen gewährt hatte. Anders als die steinernen Städte Eisenschmiede und Sturmwind ist dies eine offene, friedliche Siedlung aus gezimmerten Holzunterkünften, leuchtenden Schreinen und Bogenbrücken über klaren Seen. Wachsame Schildwachen, hoch aufragende Urtume des Krieges und Druiden, die Bäume formen, bewachen die Pfade und bewahren die Stille der Natur in der Stadt."},{t="Eine gespaltene Führung",b="Darnassus steht für die Einheit der Kaldorei, doch seine Anführer tragen unterschiedliche Verantwortung. Hohepriesterin Tyrande Wisperwind lenkt die zivilen und militärischen Angelegenheiten vom strahlenden Tempel des Mondes aus, umgeben von den Schwestern von Elune. Erzdruide Fandral Hirschhaupt leitet die Angelegenheiten des Zirkels des Cenarius und setzte sich für die Pflanzung Teldrassils ein, um die verlorene Unsterblichkeit der Elfen wiederherzustellen.\n\nMalfurion Sturmgrimm wird vermisst, verloren in einem rätselhaften Schlummer im Smaragdgrünen Traum. Hirschhaupts aggressive Zukunftsvision gerät oft mit der geduldigeren Priesterschaft in Konflikt."}},faq={{q="Wer regiert Darnassus?",a="Hohepriesterin Tyrande Wisperwind führt die Gesellschaft der Nachtelfen vom Tempel des Mondes aus und befehligt die Schildwachen. Erzdruide Fandral Hirschhaupt leitet den Zirkel des Cenarius während Malfurion Sturmgrimms Abwesenheit.",al={"anführer von darnassus","wer führt darnassus","anführer der nachtelfen"}},{q="Wie erreichen Reisende Darnassus von außerhalb Teldrassils?",a="Schiffe und Flugrouten von außerhalb Teldrassils erreichen Rut'theran am Fuße des Weltbaums. Von dort bringt ein magisches Portal Besucher hinauf nach Darnassus.",al={"wie nach darnassus gelangen","eingang nach darnassus","nach darnassus gelangen"}},{q="Warum wurde Darnassus erst vor Kurzem gegründet?",a="Nach den Verwüstungen am Hyjal im Dritten Krieg verloren die Nachtelfen ihre Unsterblichkeit und ihre uralte Lebensweise. Fandral Hirschhaupt und seine Verbündeten pflanzten Teldrassil vor Kalimdors Küste, und Darnassus schlug auf seinen Ästen als neue Zuflucht für ihr Volk Wurzeln.",al={"warum ist darnassus neu","wann wurde darnassus erbaut","alter von darnassus"}},{q="Wo ist Malfurion Sturmgrimm?",a="Erzdruide Malfurion Sturmgrimm wird vermisst, sein Geist ist in einem tiefen, unerklärlichen Schlummer im Smaragdgrünen Traum gefangen. In seiner Abwesenheit führt Fandral Hirschhaupt den Zirkel des Cenarius in Darnassus.",al={"wo ist malfurion","ist malfurion in darnassus","malfurions zustand"}}},fx={["24a1a5b0"]={q="Was ist Darnassus?",a="Darnassus ist die Hauptstadt der Nachtelfen, hoch oben in den kolossalen Ästen des neu gewachsenen Weltenbaums Teldrassil gelegen. Erbaut um einen friedlichen See und offen für den dämmernden Himmel, dient sie nach dem Dritten Krieg als spirituelles und kulturelles Herz ihrer Zivilisation. Anmutige Brücken, Lodges aus lebendem Holz und heilige Haine prägen ihr Layout, verankert durch den glänzenden Tempel des Mondes. Sie steht als Zufluchtsort der Allianz und als lebendiges Zeugnis für die Ehrfurcht der Kaldorei vor der Natur.",al={"was ist das für ein ort","erzähle mir von darnassus","übersicht stadt darnassus"}},["3a9c78e5"]={q="Wer lebt in Darnassus?",a="Die Stadt ist überwiegend die Heimat der Nachtelfen und heißt Druiden, Jäger, Priester und Krieger gleichermaßen willkommen. Hohepriesterin Tyrande Wisperwind präsidiert vom großen Tempel des Mondes aus zusammen mit ihren Schwesternschaft von Elune, während Erzdruide Fandral Hirschhaupt den Zirkel des Cenarius von der Enklave des Cenarius aus leitet. Die wachsamen Sentinels patrouillieren auf den Wegen, und uralte Beschützer wandern durch die Pfade. Besucher werden auch auf Abgesandte anderer Völker der Allianz sowie auf Vertreter neutraler Orden wie der Argentumdämmerung treffen.",al={"wer lebt hier","bewohner von darnassus","einwohner von darnassus"}},["0325f465"]={q="Ist Darnassus gefährlich?",a="Für Mitglieder der Allianz ist Darnassus ein außergewöhnlich friedlicher Zufluchtsort, abgeschirmt von den härteren Gefahren Kalimdors durch den Ozean und die gewaltige Höhe von Teldrassil. Sie wird von bewaffneten Sentinels und beeindruckenden Uralten Beschützern genauestens geschützt. Agenten der Horde werden sie jedoch als feindselig empfinden, da sie bei ihrem Eintritt sofort von den standhaften Verteidigern der Stadt angegriffen werden.",al={"ist darnassus sicher","bedrohungen in darnassus","gibt es gefahren in darnassus"}}},fp="9,348,23.457.0,20.553.0,20.204.0,57.166.0,38.274.0,29.190.0"}
P.entries["subzone:darrow-hill"] = {n="Darrow Hill",s="Im nördlichen Hillsbrad erhebt sich Darrow Hills schroffes Grasland unterhalb des Vorgebirges. Berglöwen und Hirsche ziehen über die offenen Hänge, während wilde Yetis in den Vorgebirgshöhlen hausen. Alteracgranit lockt Reisende in dieses gefährliche Grenzland.",h="Im nördlichen Hillsbrad erhebt sich Darrow Hills schroffes Grasland unterhalb des Vorgebirges.",kw={"alteracgranit","darrow hill","vorgebirgshöhlen","vorgebirge","vorgebirge des hügellands","yetis"},ang={["class:Hunter"]="Ihr könnt überall in den Hügeln Berglöwen und Hirsche jagen, die zwischen dem Waldrand von Alterac und dem tiefer gelegenen Grasland umherziehen.",["profession:Mining"]="Darrow Hills Höhlensysteme, besonders die Vorgebirgshöhlen, bergen reiche Adern von Alteracgranit und regionalen Mineralien. Ihr müsst Euch mit den Yetis herumschlagen, die in der Nähe nisten."},sec={{t="Ein tückisches Grenzland",b="Unterhalb des Vorgebirges verbinden Darrow Hills felsige Hänge die sanften Weiden des südlichen Hillsbrad mit den kälteren, zerklüfteten Höhen von Alterac. Berglöwen und Hirsche ziehen durch das hohe Gras, während gewaltige Yetis aus den Vorgebirgshöhlen hervorkommen.\n\nDie Höhlenwände bergen dichten Alteracgranit und locken Steinbrucharbeiter, Bergleute und Abenteurer in Gefahr. Die Gebietsansprüche bleiben umstritten, und Reisende beider Fraktionen können auf den Pfaden unversehens überrascht werden."}},faq={{q="Wo liegt Darrow Hill?",a="Darrow Hill liegt im nördlichen Vorgebirge des Hügellands, direkt südlich der als Vorgebirge bekannten felsigen Steilhänge und östlich der Hauptbergstraße nach Alterac.",al={"darrow hill lage","wo liegt darrow hill","darrow hill karte"}},{q="Welche Kreaturen bedrohen Reisende rund um Darrow Hill?",a="Hirsche und Berglöwen streifen über die offenen Hänge, während wilde Yetis in den Vorgebirgshöhlen und ihrer Umgebung umherziehen.",al={"darrow hill gegner","was lebt auf darrow hill","monster darrow hill"}},{q="Was findet man in den Vorgebirgshöhlen?",a="Wilde Yetis bevölkern die Vorgebirgshöhlen, deren felsige Wände Adern von Alteracgranit bergen, nach denen Bergleute suchen.",al={"vorgebirgshöhlen","darrow hill höhle","was ist in der höhle"}},{q="Warum gilt dieses Gebiet als so gefährlich für Reisende?",a="Wilde Tiere und Yetibauten bedrohen Reisende, und das offene Gelände liegt unmittelbar neben umkämpften Straßen. Reisende der Allianz und der Horde überfallen einander dort häufig aus dem Hinterhalt.",al={"warum ist darrow hill gefährlich","darrow hill pvp","gefahr bei darrow hill"}}},fx={["35480940"]={q="Was ist Darrow Hill?",a="Darrow Hill ist eine erhöhte, raue Fläche in den nördlichen Ausläufern des Vorgebirges des Hügellands, die direkt unter den gewaltigen Höhen des Headland ruht. Ihre offenen Hänge beherbergen umherstreifende Wildtiere, während die nahegelegenen Foothill Caverns in den Stein gehauen sind und unter der ruhigen Oberfläche unterirdische Gefahren bergen.",al={"was ist darrow hill","darrow hill hügelland","informationen darrow hill"}}},fp="11,237,22.446.0,29.153.0,53.111.0,46.117.0,55.176.0"}
P.entries["subzone:darrowmere-lake"] = {n="Darrowmeresee",s="Im Herzen der Westlichen Pestländer umschließt der Darrowmeresee Darrowehr. Die Inselfestung birgt verfallene Hallen über Scholomance, der Akademie des Kults der Verdammten für Nekromantie.",h="Im Herzen der Westlichen Pestländer umschließt der Darrowmeresee Darrowehr.",kw={"barov","darrowehr","darrowmere","darrowmeresee","proudmoore flotte","scholomance","thondroril","westliche pestländer"},ang={["faction:Alliance"]="Veteranen der Allianz erinnert der Darrowmeresee an eine wichtige Front im Seekrieg. Die Flotte von Proudmoore kämpfte hier während des Zweiten Krieges gegen die Old Horde.",["race:Undead"]="Als Untoter wisst Ihr, dass der Darrowmeresee die Schwelle zu Darrowehr bildet. Dort überließen die noch lebenden Barovs dem Lich King ihre sterbliche Heimat, um Scholomance zu erschaffen, die gefürchtete Akademie."},sec={{t="Ein sagenumwobener Binnensee",b="Der Darrowmeresee zählt zu den größten Binnengewässern der Östlichen Königreiche. Der Thondroril und der Darrowmere River speisen seine tiefen Gewässer unterhalb der verseuchten Wälder Lordaerons. Während des Zweiten Krieges lieferten sich die Horde und die Flotte von Großadmiral Daelin Prachtmeer hier Seegefechte.\n\nDie Horde plünderte Darrowehr auf der Insel in der Mitte des Sees und entwendete seinen uralten Runenstein. Einst trieb das blühende Haus Barov Handel über den See. Heute liegt ein düsteres Becken nebelverhangen im Herzen der Pestländer."},{t="Der Schatten auf dem Wasser",b="Darrowehr erhebt sich inmitten des Darrowmeresees. Einst war es der stolze Stammsitz der Familie Barov. Unter seinen zerfallenen Fundamenten liegt Scholomance, die wichtigste Akademie der Geißel für Nekromantie und dunkle Künste. Die Gewässer um die Insel stehen still und spiegeln das finstere Erbe des Kults der Verdammten wider. Um die Festung im Herzen des Sees zu erreichen, müsst Ihr diese Gewässer durch die Gefahren des verseuchten Umlands hindurch überqueren."}},faq={{q="Wo liegt der Darrowmeresee?",a="Der Darrowmeresee liegt im südöstlichen Winkel der Westlichen Pestländer. Er verbindet den Thondroril im Norden mit dem nach Süden fließenden Darrowmere River.",al={"darrowmere lage","wo liegt der darrowmeresee","wie gelangt man nach darrowmere"}},{q="Was befindet sich auf der Insel in der Mitte des Sees?",a="Auf der Insel liegt Darrowehr, eine uralte Siedlung, die einst vom adligen Haus Barov beherrscht wurde. Unter der verfallenen Stadt liegt Scholomance, eine weitläufige Schule der dunklen Magie, die vom Kult der Verdammten geführt wird.",al={"insel in darrowmere","was ist auf der insel","darrowehr lage"}},{q="Welche Rolle spielte der Darrowmeresee im Zweiten Krieg?",a="Während des Zweiten Krieges war der Darrowmeresee eine umkämpfte Wasserstraße. Die Flotte von Proudmoore schlug Seeschlachten gegen die Horde, die auch Darrowehr plünderte und dessen uralten Runenstein an sich riss.",al={"zweiter krieg darrowmere","seeschlachten darrowmere","darrowmere geschichte"}},{q="Können Schiffe noch in den Darrowmeresee einfahren?",a="Große Schiffe können den Darrowmeresee nicht mehr vom Meer aus erreichen. Die verbindenden Flüsse haben steile Wasserfälle und seichte Passagen, obwohl während des Zweiten Krieges gewaltige Flotten den See befuhren.",al={"darrowmere zugang per boot","können schiffe darrowmere erreichen"}}},fp="15,185,20.508.0,24.429.0,33.159.0,48.201.0,53.189.0,42.190.0"}
P.entries["subzone:darrowshire"] = {n="Darrowshire",s="Darrowshire liegt in den südlichen Hügeln der Östlichen Pestländer in Trümmern. Einst ein friedlicher Weiler Lordaerons, leistete es während des Dritten Krieges verzweifelten Widerstand gegen die Geißel. Zerborstene Balken, ruhelose Geister und bittere Erinnerungen bleiben zurück.",h="Darrowshire liegt in den südlichen Hügeln der Östlichen Pestländer in Trümmern.",kw={"schlacht um darrowshire","darrowshire","östliche pestländer","ghule","horgus the ravager","lordaeron","marduk blackpool"},ang={["class:Paladin"]="Als Paladin könnt Ihr das reinigende Licht in die Plaguelands bringen, die Untoten niederstrecken und gequälte Geister zur Ruhe betten.",["race:Human"]="Als Mensch der Allianz erinnert Euch Darrowshire an die Verwüstung Lordaerons und die einfachen Leute, die hoffnungslosen Widerstand leisteten, um ihre Familien zu verteidigen."},sec={{t="Ein tragischer Widerstand",b="Darrowshires Dorfbewohner kämpften während des Dritten Krieges gegen die Geißel. Bevor die Seuche das nördliche Lordaeron verschlang, lag die bescheidene Siedlung unterhalb der südlichen Klippen. Marduk Blackpool, ein Todesritter, und Horgus the Ravager, ein Ghullord, führten die Belagerer an.\n\nDie Dorfbewohner und örtlichen Verteidiger hielten eine Zeit lang die Stellung, obwohl ihre Lage aussichtslos war. Dann brach ihre Verteidigung zusammen, und die Geißel metzelte die Bewohner bis auf die letzte Seele nieder. Viele gefallene Verteidiger wurden als Ghule wiedererweckt, um die Reihen der Geißel zu verstärken. Darrowshire bleibt ein leeres Mahnmal für jene, die dort starben."},{t="Echos der Schlacht",b="Darrowshires Ruinen tragen noch immer die Last des Gemetzels. Die Lebenden haben das Dorf längst verlassen, doch geisterhafte Überreste seiner Bewohner bleiben dort gefangen. Reisende berichten von seltsamen Erscheinungen, darunter geisterhafte Nachstellungen der Schlacht, die sich in Stille entfalten. Noch immer haftet dem Boden Trauer an, eine Erinnerung an das, was die Geißel dem Königreich nahm."}},faq={{q="Was geschah mit Darrowshire?",a="Die Geißel zerstörte Darrowshire während des Dritten Krieges. Marduk Blackpool, ein Todesritter, und Horgus the Ravager, ein Ghullord, führten den Angriff an. Ihre Streitkräfte überwältigten die Verteidiger und metzelten die Bewohner nieder, sodass das Dorf in Trümmern zurückblieb.",al={"darrowshire geschichte","warum ist darrowshire zerstört","was ist hier geschehen"}},{q="Wer führte den Angriff der Geißel auf Darrowshire an?",a="Marduk Blackpool, ein Todesritter, und Horgus the Ravager, ein Ghullord, führten den Angriff der Geißel auf Darrowshire an. Ihre Streitkräfte brachen den Widerstand der Verteidiger des Dorfes und zerstörten die Siedlung.",al={"wer griff darrowshire an","darrowshire schurken","horgus und marduk"}},{q="Warum spukt es in Darrowshire?",a="Das Gemetzel band die Geister von Darrowshires Gefallenen an die Erde. Geisterhafte Gestalten verweilen zwischen den Ruinen, und manchmal spielt sich die Schlacht selbst in geisterhafter Form erneut ab, sodass die Toten in ihren letzten Augenblicken gefangen bleiben.",al={"darrowshire geister","warum gibt es geister in darrowshire"}},{q="Was wurde aus den Dorfbewohnern, die bei der Verteidigung des Ortes starben?",a="Die Geißel metzelte Darrowshires Verteidiger nieder, und viele wurden als Ghule wiedererweckt. Sie wurden gezwungen, der Armee zu dienen, die ihre Heimat zerstört hatte.",al={"darrowshire dorfbewohner","verteidiger von darrowshire"}}},fp="11,245,14.578.0,20.354.0,29.246.0,58.184.0,27.224.0,57.147.0"}
P.entries["subzone:dawning-isles"] = {n="Die Morgeninseln",s="Am östlichen Rand des Silberwalds erheben sich die Morgeninseln aus dem Lordameresee, bevölkert von immer mehr Murlocs der Vile Fin. Die Seuche des Untods verseuchte ihre Ufer und ließ die Inselchen verrotten.",h="Am östlichen Rand des Silberwalds erheben sich die Morgeninseln aus dem Lordameresee, bevölkert von immer...",kw={"die morgeninseln","lordaeron","der lordameresee","silberwald","vile fin"},ang={["faction:Alliance"]="Die Morgeninseln zeigen, wie weit die Verderbnis der Geißel in Lordaerons malerische Gewässer vordrang.",["race:Undead"]="Die Morgeninseln liegen im Lordameresee, in Sichtweite der westlichen Zugänge zur Unterstadt. Die Murlocs der Vile Fin, die sie besetzt halten, werden mit jedem Jahr zahlreicher."},sec={{t="Verderben auf dem See",b="Die Murlocs der Vile Fin halten die Morgeninseln besetzt. Vor dem Dritten Krieg lagen diese Inselchen in den ruhigen, klaren Gewässern des Lordameresees. Dann fegte die Seuche des Untods über Lordaeron hinweg, und Verderbnis breitete sich in den Untiefen aus. Die Vegetation wurde bleich und faulig, und die Inseln verloren ihren einstigen Frieden.\n\nHeute beherrschen die Murlocs der Vile Fin die schlammigen Ufer und das dichte Gestrüpp. Sie verteidigen ihre wachsenden Kolonien gegen jeden, der versucht, den See zu überqueren."},{t="Eine Festung der Murlocs",b="Einst streiften neben den Murlocs auch Moormonster über die verseuchten Morgeninseln. Seit die Moormonster verschwunden sind, ist die Bevölkerung der Vile Fin stark angewachsen. Die Murlocs kontrollieren die Inseln nun vollständig und machen diese Inselkette zu ihrer Festung auf dem Lordameresee."}},faq={{q="Wo liegen die Morgeninseln?",a="Die Morgeninseln erheben sich aus dem Lordameresee an der östlichen Grenze des Silberwalds, unmittelbar westlich der Ruinen von Lordaeron.",al={"morgeninseln lage","wo liegen die morgeninseln","morgeninseln karte"}},{q="Welche Kreaturen bewohnen die Morgeninseln?",a="Der Murlocstamm der Vile Fin gedeiht an den verderbten Ufern. Einst streiften auch Moormonster über die Inselchen, doch mit dem Wachstum der Murlocbevölkerung sind sie weitgehend verschwunden.",al={"gegner auf den morgeninseln","was lebt auf den morgeninseln","morgeninseln monster"}},{q="Warum verrotten hier die Bäume und Ufer?",a="Die Seuche des Untods verseuchte die Morgeninseln, als sie während des Dritten Krieges über Lordaeron hinwegfegte. Wasser und Boden nahmen das Verderben auf, das die Vegetation vergiftete und die Inselchen trüb, kränklich und verfallen zurückließ.",al={"warum sind die morgeninseln verseucht","see verderben morgeninseln"}}},fx={["501d8847"]={q="Was sind die Morgeninseln?",a="Die Morgeninseln sind eine Ansammlung von niedrigen Inseln, die aus den Gewässern des Lordameresees entlang des nordöstlichen Silberwalds aufragen. Einst als idyllischer und ruhiger Rückzugsort auf der kristallinen Oberfläche des Sees betrachtet, ist der Archipel seitdem unter der anhaltenden Fäulnis der Seuche des Untodes verfallen.",al={"was sind die morgeninseln","überlieferung morgeninseln","über die morgeninseln"}},["425e68c2"]={q="Was ist mit den Morgeninseln geschehen?",a="Einst unberührte kleine Inseln auf dem Lordameresee, wurden die Morgeninseln durch die Ausbreitung der Seuche des Untodes ruiniert, was ihre Vegetation krank machte und die Ufer verrotten ließ. Murlocs und Sumpfbestien überrannten die Inseln; die Sumpfbestien sind seitdem verschwunden, und die Vile Fin Murlocs sind zahlreich genug geworden, um die Kontrolle über die Inseln zu übernehmen.",al={"geschichte der morgeninseln","was geschah auf den morgeninseln"}},d646a662={q="Sind die Morgeninseln gefährlich?",a="Ja, sie sind außergewöhnlich gefährlich. Abgesehen von der anhaltenden Fäulnis der Seuche werden die Inseln von aggressiven Vile Fin Murlocs überrannt, die sich stark vermehrt haben und jeden angreifen, der ihr Territorium betritt.",al={"sind die morgeninseln sicher","wie gefährlich sind die morgeninseln","gefahr morgeninseln"}}},fp="13,206,18.452.0,19.249.0,36.125.0,41.172.0,42.214.0"}
P.entries["subzone:dawning-wood-catacombs"] = {n="Katakomben des Morgenwaldes",s="Unter dem Friedhof von Rabenflucht im westlichen Dämmerwald füllen Untote die Katakomben des Morgenwaldes. Skelettwachen und unersättliche Ghule spuken in ihren steinernen Tunneln.",h="Unter dem Friedhof von Rabenflucht im westlichen Dämmerwald füllen Untote die Katakomben des Morgenwaldes.",kw={"gruften","katakomben des morgenwaldes","dämmerwald","ghule","friedhof von rabenflucht","skelette","untoter"},ang={["class:Paladin"]="Für einen Paladin bergen diese Katakomben die Gefallenen des Königreichs, und ihre geschändeten Gräber verlangen nach dem heiligen Zorn des Lichts.",["class:Priest"]="Für einen Priester liegen unter den Steingewölben von Rabenflucht rastlose Geister und verwesende Leichen, denen die letzte Ruhe verwehrt bleibt. Die Katakomben stellen den Glauben derer auf die Probe, die sie betreten."},sec={{t="Unter Rabenflucht",b="Unter dem verfallenen Friedhof von Rabenflucht bergen die Katakomben des Morgenwaldes die Toten der umliegenden Wälder. Bevor die Dämmerung den Wald verfluchte, ruhten diese Toten in den steinernen Korridoren. Nun beherbergen die Katakomben einige der tödlichsten Untoten der Region, und einsame Reisende geraten in ihren Tiefen in Gefahr.\n\nDie Katakomben sind in zwei unterirdische Flügel unterteilt. Belebte Skelette bewachen die Ahnengräber in den westlichen Gängen. Im Osten führen Tunnel in einen fauligen Bau hinab, der von unersättlichen, krankheitsübertragenden Ghulen überrannt wird."}},faq={{q="Wo liegen die Katakomben des Morgenwaldes?",a="Die Katakomben des Morgenwaldes liegen unter dem Friedhof von Rabenflucht am äußersten Westrand des Dämmerwalds. Ihre Eingänge führen zwischen weit verstreuten Grabsteinen und verfallenen Gruften hinab.",al={"lage der katakomben","wo liegen die katakomben des morgenwaldes","weg zu den katakomben"}},{q="Was lauert in den Katakomben?",a="Dort lauern die wildesten Untoten des Dämmerwalds auf engstem Raum. Schwer bewaffnete Skelettkrieger verteidigen den westlichen Flügel, während wilde, pestverseuchte Ghule die östlichen Tunnel bevölkern.",al={"feinde der katakomben","was ist in den katakomben des morgenwaldes","monster der katakomben"}},{q="Warum wurden die Katakomben ursprünglich erbaut?",a="Die Katakomben wurden als prächtige Gruft für einheimische Familien und bedeutende Persönlichkeiten ausgehoben, als die Region noch grün war. Der Fluch, der die Wälder später heimsuchte, erweckte die darin Bestatteten zu neuem Leben.",al={"geschichte der katakomben","warum wurden die katakomben erbaut","ursprünglicher zweck der katakomben"}},{q="Ist es sicher, die Katakomben allein zu erkunden?",a="Die Katakomben allein zu erkunden ist gefährlich. Dicht gedrängte Gruppen aggressiver Untoter können einzelne Reisende überwältigen, und die engen Tunnel lassen wenig Raum für einen Rückzug.",al={"katakomben allein bewältigen","gefahren der katakomben","sind die katakomben schwierig"}}},fx={fdcc93ff={q="Was sind die Katakomben des Morgenwaldes?",a="Die Katakomben des Morgenwaldes sind ein verschlungenes unterirdisches Labyrinth, das unter dem weitläufigen Friedhof von Rabenflucht im westlichen Dämmerwald gegraben wurde. Ursprünglich angelegt, um die Toten der Region zur Ruhe zu betten, sind diese höhlenartigen Steinhallen seitdem von einigen der grausamsten und krankesten Untoten befallen, die den Wald durchstreifen. Aufgeteilt in zwei Hauptflügel, dient die eine Seite als elender Bau von tollwütigen Ghulen, während die andere von bewaffneten Skelettwächtern heimgesucht wird.",al={"was sind die katakomben","übersicht katakomben des morgenwaldes","katakomben von rabenflucht"}},["514fe1a3"]={q="Ist es gefährlich, die Katakomben des Morgenwaldes zu betreten?",a="Sich unter den Friedhof zu wagen, gehört zu den tödlichsten Unternehmungen im Dämmerwald. Die Katakomben wimmeln von Scharen unerbittlicher Untoter, die einen einsamen Reisenden in der absoluten Finsternis schnell überwältigen können. Der östliche Flügel ist vollgestopft mit krankheitsübertragenden Ghulen, die Fleisch zerfetzen, während die Westseite von erfahrenen Skelettwächtern gehalten wird, die über entweihten Gräbern Wache halten. Ohne erfahrene Verbündete im Rücken ist ein Ausflug diese Treppen hinunter fast sicher tödlich.",al={"gefahr katakomben","sind die katakomben gefährlich","wie gefährlich sind die katakomben"}}},fp="22,151,18.504.0,45.165.0,32.184.0,48.192.0,42.161.0"}
P.entries["subzone:dead-acre"] = {n="Der Todesacker",s="Im Südosten Westfalls liegt der Todesacker niedergebrannt und verlassen nahe der Brücke zum Dämmerwald. Die Bruderschaft der Defias steckte den Hof während ihres Aufstands in Brand, und abtrünnige Erntegolems durchstreifen noch immer die verkohlten Felder.",h="Im Südosten Westfalls liegt der Todesacker niedergebrannt und verlassen nahe der Brücke zum Dämmerwald.",kw={"niedergebrannter hof","der todesacker","defias","hof","erntewächter","westfall"},ang={["faction:Alliance"]="Der Todesacker erinnert daran, wie Sturmwind Westfall vernachlässigte und treue Bauern der Gewalt der Bruderschaft der Defias schutzlos auslieferte."},sec={{t="Asche an der Grenze",b="Nördlich der Straße von der Späherkuppe zum Dämmerwald liegt der Todesacker zwischen den alten Kornkammerhöfen Westfalls. Das Gehöft brachte einst gute Ernten ein, bis die Bruderschaft der Defias sich erhob und die Landbesitzer vertrieb. Dann gingen Hof und Ernte in Flammen auf. Verkohltes Holz und rauchende Erde sind geblieben, während mechanische Erntewächter noch immer den kargen Boden abernten."}},faq={{q="Warum heißt dieser Ort der Todesacker?",a="Die Bruderschaft der Defias brannte das Gehöft und die Felder nieder, als sie die Kontrolle über Westfall übernahm. Geschwärzte Ruinen und schwelende Erde gaben dem Hof seinen düsteren Namen.",al={"warum todesacker","was geschah mit dem todesacker","warum ist er niedergebrannt"}},{q="Warum streifen hier mechanische Erntewächter umher?",a="Mechanische Erntemaschinen bestellten einst Westfalls Felder, doch die Siedler flohen oder starben und ließen sie zurück. Ohne Aufseher oder durch Verderbnis verändert patrouillieren die Erntewächter noch immer auf den verbrannten Feldern und greifen jeden an, der sich nähert.",al={"erntegolems todesacker","warum gibt es golems","erntewächter"}},{q="Wo liegt der Todesacker?",a="Der Todesacker liegt im Südosten Westfalls, direkt nördlich der Hauptstraße nahe der Brücke zum Dämmerwald.",al={"todesacker lage","wo ist der todesacker","wie findet man den todesacker"}}},fx={["6eb41297"]={q="Was ist der Todesacker?",a="Der Todesacker ist ein zerstörtes, schwelendes ehemaliges Gehöft im südöstlichen Westfall, das nahe der Flussbrücke liegt, die in den Dämmerwald führt. Was einst fruchtbares Ackerland war, wurde zu geschwärzter Erde und versengten Trümmern reduziert.",al={"was ist der todesacker","todesacker westfall","todesacker lore"}},e7e3cf0f={q="Was geschah mit dem Todesacker?",a="Als die The Defias Brotherhood die Kontrolle über Westfall an sich riss, legten ihre Plünderer dieses Gehöft und seine Felder in Schutt und Asche. Die Gebäude wurden vollständig zerstört, sodass nichts als rauchende Ruinen und zerstörte Ackerreihen zurückblieben.",al={"was geschah am todesacker","warum wurde der todesacker zerstört","todesacker geschichte"}},["80cb4842"]={q="Warum ist der Todesacker zerstört und verlassen?",a="Die Farm wurde während der Machtübernahme der Region durch die The Defias Brotherhood dem Erdboden gleichgemacht. Da das Gehöft bis auf die Grundmauern niedergebrannt und das Land versengt wurde, wurden die ursprünglichen Farmer vertrieben oder getötet, wodurch die schwelenden Felder völlig verlassen zurückblieben.",al={"warum ist der todesacker verlassen","todesacker niedergebrannt","warum ist der todesacker ruiniert"}},["3f91a783"]={q="Ist der Todesacker gefährlich?",a="Ja. Feindselige mechanische Erntewächter patrouillieren aktiv auf dem versengten Gelände und greifen jeden Reisenden oder Farmer an, der sich auf das schwelende Grundstück wagt.",al={"ist der todesacker gefährlich","bedrohungen am todesacker","todesacker feinde"}}},fp="9,210,19.364.0,39.156.0,51.218.0,31.99.0"}
P.entries["subzone:dead-field"] = {n="Das Todesfeld",s="Im nördlichen Silberwald stocken die Angriffe der Verlassenen am Todesfeld, einem verfallenen Gehöft. Dort dienen Gnolle der Rot Hide der Geißel, und die Banshee Nightlash schlägt jeden Angriff zurück.",h="Im nördlichen Silberwald stocken die Angriffe der Verlassenen am Todesfeld, einem verfallenen Gehöft.",kw={"banshee","das todesfeld","todespirscher","nightlash","rot hide","silberwald","thule ravenclaw"},ang={["class:Rogue"]="Als Schurke wisst Ihr, dass Späher der Todespirscher das Gehöft genau beobachten. Die Reihen der Gnolle zu unterwandern und ihre Führung anzugreifen, ist ein entscheidendes militärisches Ziel.",["race:Undead"]="Für Euch Verlassene bedroht der Stützpunkt der Geißel auf dem Todesfeld die Straße zwischen dem Grabmal und dem nördlichen Lordaeron. Er muss rasch ausgelöscht werden."},sec={{t="Ein verseuchter Aufmarschplatz",b="Im nördlichen Silberwald steht das verfallene Gehöft leer, seit seine menschlichen Bewohner im Dritten Krieg umkamen. Gnolle der Rot Hide nutzen das Grundstück nun als Stützpunkt und dienen der Geißel bereitwillig. Späher der Todespirscher haben Anzeichen eines bevorstehenden Truppenaufmarschs entdeckt, der die Nachschublinien und Vorposten der Verlassenen bedroht.\n\nKleinere Angriffe der Verlassenen auf das Gehöft sind immer wieder gescheitert. Wann immer die Gnolle in Gefahr geraten, erscheint Nightlash, eine heulende Banshee, und schlägt die Angreifer zurück."},{t="Ravenclaws Ehrgeiz",b="Thule Rabenklaue befehligt die Gnolle der Rot Hide von der Insel Fenris aus. Der Nekromant strebt die Herrschaft der Geißel über den Silberwald an und will Sylvanas' Streitkräfte aus Lordaeron vertreiben. Er schickt magische Erscheinungen zum Gehöft, um seine untote Horde zu überwachen und Eindringlinge der Verlassenen zu warnen."}},faq={{q="Was ist das Todesfeld?",a="Das Todesfeld ist ein verfallenes Gehöft im nördlichen Silberwald. Einst ein gewöhnlicher menschlicher Bauernhof, verfiel es und beherbergt nun Gnolle der Rot Hide, die mit der Geißel verbündet sind.",al={"todesfeld silberwald","wo ist das todesfeld","was geschah mit dem todesfeld"}},{q="Warum sind Gnolle auf dem Gehöft?",a="Die Gnolle der Rot Hide dienen der Geißel und nutzen das Gehöft, um Streitkräfte zu sammeln und Angriffe auf Stellungen der Verlassenen im nördlichen Silberwald vorzubereiten.",al={"warum gnolle der rot hide","rot hide todesfeld","geißel gnolle"}},{q="Wer ist Nightlash?",a="Nightlash ist eine Banshee der Geißel, die die Gnolle der Rot Hide auf dem Gehöft befehligt. Wenn Streitkräfte der Verlassenen angreifen, erscheint sie, um ihre Diener zu verteidigen und die Versuche abzuwehren, das Land zurückzuerobern.",al={"nightlash banshee","banshee auf dem todesfeld","wer beschützt die gnolle"}},{q="Wer befehligt hier die Streitkräfte der Geißel?",a="Thule Rabenklaue befehligt die hiesigen Streitkräfte der Geißel von der nahe gelegenen Insel Fenris aus. Der mächtige Nekromant lenkt die Gnolle durch Erscheinungen und magische Überwachung, um die Ausbreitung der Verlassenen zu behindern.",al={"wer kontrolliert das todesfeld","thule ravenclaw todesfeld","wer hat das kommando"}}},fx={["8ddbb760"]={q="Was geschah mit der Farm am Todesfeld?",a="Die Farm war einst ein Gehöft im nördlichen Silberwald, doch die Namen und Schicksale der ursprünglichen Farmer gingen im Dritten Krieg verloren. Als das Königreich fiel, verfiel das Land und Agenten der Geißel zogen ein. Anstatt Feldfrüchte anzubauen, verwandelte die Geißel das verlassene Gelände in einen Außenposten, versammelte untote Gnolle und bereitete sich darauf vor, nahegelegene Siedlungen der Verlassenen zu bedrohen.",al={"todesfeld geschichte","was geschah am todesfeld","wer lebte am todesfeld"}},["00a3cfa2"]={q="Wer kontrolliert das Todesfeld?",a="Die Farm wird von den Rot Hide-Gnollen besetzt, die der Geißel als Fußsoldaten dienen. Über ihnen lauert die Banshee Nightlash, die den Außenposten beaufsichtigt und erscheint, sobald ihre Diener angegriffen werden. Der Nekromant Thule Rabenklaue koordiniert ihre Bewegungen aus der Ferne und nutzt Erscheinungen, um ihre Bemühungen gegen die Verlassenen zu lenken.",al={"wer führt das todesfeld","wer lebt am todesfeld","todesfeld bewohner"}},["242af2de"]={q="Warum ist das Todesfeld verlassen?",a="Wie ein Großteil des nördlichen Silberwaldes brach die Farm zusammen, als die Geißel Lordaeron überrannte. Die Bewohner wurden getötet oder vertrieben, und keine lebenden Seelen blieben zurück, um den Boden zu bestellen oder die Gebäude instand zu halten. Inmitten des geplagten Bodens wurden die verfallenden Scheunen und zerstörten Zäune schnell von der Geißel als vorderster Stützpunkt beschlagnahmt.",al={"warum ist das todesfeld ruiniert","warum ist das todesfeld verlassen","todesfeld ruine"}},fd654559={q="Ist das Todesfeld gefährlich?",a="Es ist extrem gefährlich für jeden, der alleine reist. Die Rot Hide-Gnolle versammeln sich hier in wachsender Zahl, was auf eine drohende Aggression der Geißel hindeutet. Wiederholte Überfälle der Verlassenen konnten sie nicht vertreiben, da Nightlash schnell erscheint, um ihre Diener zu beschützen, was jede direkte Konfrontation in einen tödlichen Zusammenstoß gegen sowohl wilde Gnolle als auch ätherisches Geheul verwandelt.",al={"wie gefährlich ist das todesfeld","todesfeld bedrohung","ist das todesfeld sicher"}}},fp="10,182,25.483.0,20.267.1,23.166.0,33.149.0,17.191.0,37.189.1"}
P.entries["subzone:deadeye-shore"] = {n="Killrogs Küste",s="Am östlichen Rand Durotars erstreckt sich Killrogs Küste östlich der Staubwindklamm. Ihre kargen Sandstrände sind nach Kilrogg Deadeye benannt, dem Häuptling des Bleeding Hollow-Clans, während Raptoren, Skorpide und wilde Eber die Küste durchstreifen.",h="Am östlichen Rand Durotars erstreckt sich Killrogs Küste östlich der Staubwindklamm.",kw={"bleeding hollow","killrogs küste","staubwindklamm","durotar","kilrogg deadeye"},ang={["race:Orc"]="Als Orc seht Ihr eine Küste, die nach Kilrogg Deadeye benannt ist. Sie erinnert an die alten Häuptlinge, die während der Kriege auf Azeroth die Geschichte der Horde prägten."},sec={{t="Eine Küste des Bleeding Hollow-Clans",b="Unterhalb der roten Klippen im Herzen Durotars verläuft Killrogs Küste entlang von Sandflächen und Felsvorsprüngen, deren Form entfernt einem Schädel mit einer leeren Augenhöhle ähnelt. Die Küste ist nach Kilrogg Deadeye benannt, dem einäugigen Häuptling des Bleeding Hollow-Clans, der im Ersten und Zweiten Krieg kämpfte.\n\nKeine große Siedlung und kein militärischer Außenposten halten diese Küste. Aggressive Tiere durchstreifen den Sand, und Kultisten der Burning Blade aus nahegelegenen Schluchtenverstecken wurden dabei beobachtet, wie sie zum Wasser schlichen."}},faq={{q="Warum heißt sie Killrogs Küste?",a="Kilrogg Deadeye, der berühmte Häuptling des Bleeding Hollow-Clans, gab der Küste ihren Namen. Ihre Felsvorsprünge ähneln außerdem entfernt einem Schädel mit einer leeren Augenhöhle.",al={"wer ist deadeye","warum killrogs küste","herkunft des namens"}},{q="Wer lebt an Killrogs Küste?",a="An Killrogs Küste gibt es keine dauerhaften Siedlungen. Raptoren, Skorpide und Eber durchstreifen die Küste, während Fischer und Reisende gelegentlich vorbeikommen und auf verborgene Kultisten der Burning Blade treffen können.",al={"wer ist hier","siedlungen killrogs küste","npcs deadeye"}},{q="Welche Gefahren gibt es rund um Killrogs Küste?",a="Aggressive Tiere durchstreifen Killrogs Küste, und Kultisten der Burning Blade aus der benachbarten Staubwindklamm steigen gelegentlich aus deren felsigen Schluchten herab. Sie überfallen unvorsichtige Reisende und Fischer aus dem Hinterhalt.",al={"gefahren killrogs küste","feinde hier","burning blade deadeye"}}},fx={["46f1927a"]={q="Was ist Killrogs Küste?",a="Killrogs Küste ist ein rauer Küstenabschnitt am östlichen Rand von Durotar, der direkt östlich der Staubwindklamm liegt. Er zeichnet sich durch seinen kargen, sonnengebleichten Sand und felsige Klippen aus, die über das Große Meer blicken, und ist weitgehend von den Siedlungen der Horde isoliert.",al={"was ist killrogs küste","killrogs küste übersicht","wo ist killrogs küste"}},["01a709cb"]={q="Was geschah an Killrogs Küste?",a="Abgesehen von seiner Benennung zu Ehren von Kilrogg Deadeye, Häuptling des Clans Bleeding Hollow, ist über diesen Küstenabschnitt nur wenig Geschichte überliefert. Seine Abgeschiedenheit macht ihn für Wanderer noch immer gefährlich, denn Raptoren, Skorpide und Eber durchstreifen den Sand.",al={"killrogs küste geschichte","was geschah hier","killrogs küste ereignisse"}}},fp="13,223,34.452.0,31.154.0,30.188.0,44.183.0"}
P.entries["subzone:deadman-s-crossing"] = {n="Totmannsfurt",s="An der Totmannsfurt folgen Reisende noch immer der festgetretenen Straße unter einem Baum, an dem Tote hängen. Die Kreuzung am Gebirgspass der Totenwinde verbindet den Dämmerwald, die Sümpfe des Elends und den Pfad nach Karazhan und führt Reisende durch die südlichen Östlichen Königreiche.",h="An der Totmannsfurt folgen Reisende noch immer der festgetretenen Straße unter einem Baum, an dem Tote hängen.",kw={"totmannsfurt","gebirgspass der totenwinde","dämmerwald","galgen","henkersbaum","karazhan","wegweiser","sümpfe des elends"},ang={["faction:Alliance"]="Als Kurier der Allianz auf dem Weg von Dunkelhain zur Burg Nethergarde in den Verwüsteten Landen könnt Ihr die kürzeste Route durch die Totmannsfurt nehmen. Die Straße ist unheimlich.",["faction:Horde"]="Als Wanderer der Horde auf dem Weg von Steinard nach Westen zum Dämmerwald passiert Ihr dieses grausige Wahrzeichen auf dem Weg in die verseuchten Menschenlande."},sec={{t="Eine grausige Kreuzung",b="Die Totmannsfurt verbindet die Straßen im östlichen Gebirgspass der Totenwinde. Die westliche Straße führt zum Dämmerwald und die östliche zu den Sümpfen des Elends. Im Süden steigt ein Pfad nach Karazhan hinauf. An der Weggabelung steht ein verdrehter Henkersbaum, an dessen Ästen zwei verwesende Leichen hängen.\n\nRamponierte Holzschilder mahnen Reisende, umzukehren und alle Hoffnung aufzugeben. Feindselige Bestien und dunkle Zauberei suchen die Schlucht heim, doch die festgetretene Erdstraße durch die Kreuzung bleibt frei. Reisende, die ihr folgen, meiden die verseuchten Felsen."}},faq={{q="Wohin führen die einzelnen Straßen von der Totmannsfurt aus?",a="Die westliche Straße von der Totmannsfurt führt zum Dämmerwald, die östliche zu den Sümpfen des Elends. Der gewundene südliche Pfad durchquert den Gebirgspass der Totenwinde in Richtung Karazhan.",al={"wohin führen die straßen","wegbeschreibung kreuzung","pfade der totmannsfurt"}},{q="Wer sind die Leichen, die am Baum hängen?",a="Niemand weiß, wer die Toten waren. Der Gebirgspass der Totenwinde hat über die Jahre zahllose Wanderer, Banditen und Flüchtlinge das Leben gekostet. Jemand errichtete den Galgenbaum als grausiges Grenzzeichen, um Reisende fernzuhalten.",al={"hängende leichen","leichen am baum","wer wurde gehängt"}},{q="Ist die Totmannsfurt für Reisende sicher?",a="Die Kreuzung und die Hauptstraße von Ost nach West sind frei, doch bösartige Geier, Geister und Oger bevölkern die umliegenden Felsen und Höhlen. Kuriere und Abenteurer können sicher zwischen dem Dämmerwald und den Sümpfen des Elends reisen, solange sie auf dem Erdweg bleiben.",al={"ist es sicher","angriffe auf der straße","gefahrenstufe"}},{q="Was steht auf den Schildern an der Kreuzung?",a="Auf einem verwitterten Schild steht: „Kehrt um!“ Ein anderes warnt: „Lasst alle Hoffnung fahren, die Ihr hier eintretet.“ Beide warnen Reisende vor den Gefahren des Tals.",al={"wegweiser an der kreuzung","was steht auf den schildern","schild alle hoffnung aufgeben"}}},fp="18,248,19.512.0,50.176.0,42.201.0,41.240.0,38.153.0"}
P.entries["subzone:deadmines"] = {n="Die Todesminen",s="Unter dem zerstörten Mondbruch liegen die Todesminen still, doch Gerüchte berichten von Gefahren in ihren vergessenen Schächten. Einst die größte Goldförderstätte in den Ländern der Menschen, verstummten die Minen während des Ersten Krieges.",h="Unter dem zerstörten Mondbruch liegen die Todesminen still, doch Gerüchte berichten von Gefahren in ihren...",kw={"die todesminen","defias","edwin van cleef","eiserne bucht","kriegsschiff","lothar","mondbruch","distelklette","van cleef","westfall"},ang={["class:Paladin"]="Als Paladin teilt Ihr eine heilige Geschichte mit den Todesminen. Während des Ersten Krieges betrat Sir Anduin Lothar ihre dunkelsten Kammern, um den heiligen Tome of Divinity aus den Händen wilder Oger zu bergen.",["profession:Mining"]="Als Bergarbeiter wandelt Ihr dort, wo der Bergbau der Menschen einst seinen Höhepunkt erreichte. Vor dem Ersten Krieg führten die Todesminen alle Länder der Menschen in der Goldförderung an. Später übernahmen Goblinmaschinen und Gesetzlose der Defias das Gebiet."},sec={{t="Eine Ader aus Gold und Blut",b="Einst strömte Gold aus den Todesminen, den reichsten Minen in den Ländern der Menschen. Whitestone oak lieferte ihr Bauholz und ihre Stützen. Als die orkische Horde nach Norden vordrang, flohen die Bergleute in aller Eile.\n\nWährend des Ersten Krieges betrat Sir Anduin Lothar die tückischen Tiefen, um den heiligen Tome of Divinity zu bergen. Unterirdisch lebende Oger hielten ihn zwanzig Monate lang gefangen, bevor Retter ihn befreiten. Nach dem Fall des Königreichs verstummten die Schächte, und die Menschen begannen zu erzählen, sie seien verflucht."},{t="Van Cleefs Gießerei",b="Nach dem Aufstand der Steinmetze von Sturmwind machte die neu gegründete Bruderschaft der Defias die Todesminen zu ihrer wichtigsten Zuflucht. Sturmwinds Miners' League versuchte unter Großknecht Distelklette, die Tunnel wieder zu öffnen. Banditen der Defias überfielen die Arbeiter und brachten die Schächte zum Einsturz, und die getöteten Bergleute wandern nun als rastlose Untote umher.\n\nOger-Vollstrecker und Goblin-Tüftler bewachen die tiefen Tunnel. Dort haben die Defias rund um eine Werft in der Eisernen Bucht ein industrielles Kriegslager errichtet."}},faq={{q="Wie gelangt Ihr in die Todesminen?",a="Der Haupteingang liegt im Defias Hideout im zerstörten Mondbruch, im Südwesten von Westfall. Folgt dem gewundenen Weg durch die Kellergeschosse hinab zu den Minenschächten.",al={"wo ist der eingang der todesminen","wie gelangt man in die todesminen","todesminen standort"}},{q="Warum wurden die Minen ursprünglich aufgegeben?",a="Die Minen verstummten während des Ersten Krieges, als die Horde die südlichen Gebiete des Königreichs überrannte. Der Krieg tobte, und Oger zogen in die Tiefen ein, wodurch der Bergbau zum Erliegen kam. Die leeren Tunnel gerieten bald in den Ruf, von Geistern heimgesucht zu werden.",al={"warum wurden die todesminen geschlossen","warum sind die todesminen verlassen"}},{q="Was baut die Bruderschaft der Defias hier unten?",a="Edwin van Cleef und angeheuerte Gobliningenieure bauen ein gewaltiges gepanzertes Kriegsschiff in der überfluteten Höhle der Eisernen Bucht. Van Cleef will damit die Küste hinaufsegeln und Sturmwind zur Vergeltung beschießen und belagern.",al={"was ist in den todesminen","van cleefs plan todesminen","eiserne bucht schiff"}},{q="Wer sind die Untoten, die nahe den Eingangstunneln umherwandern?",a="Die Untoten sind Arbeiter der Miners' League unter der Führung von Großknecht Distelklette. Schläger der Defias überfielen die League, als sie die Mine erkunden und zurückgewinnen wollte, und brachten dann die Schächte zum Einsturz. Die eingeschlossenen Bergleute starben und erhoben sich als rastlose Ghule.",al={"untote bergleute todesminen","großknecht distelklette todesminen","warum gibt es ghule in den todesminen"}},{q="Welche Verbindung hat Anduin Lothar zu den Todesminen?",a="Während des Ersten Krieges drang Sir Anduin Lothar tief in die Todesminen vor, um den heiligen Tome of Divinity zu bergen. Oger in den Höhlen nahmen ihn gefangen und hielten ihn fast zwei Jahre lang fest, bevor er gerettet wurde.",al={"lothar todesminen","anduin lothar todesminen"}}},fx={["00c1b6a4"]={q="Wer kontrolliert die Todesminen?",a="Die The Defias Brotherhood hat die totale Kontrolle über das Labyrinth. Angeführt von Edwin van Cleef nahmen die entrechteten Steinmetze und Briganten die Höhlen mit Gewalt ein und zerschlugen die Arbeiter der Bergarbeiterliga, die versuchten, hier zu arbeiten. Tief im Inneren leitet VanCleef ein riesiges Netzwerk aus Dieben der Defias, angeheuerten Goblin-Ingenieuren, Oger-Vollstreckern und verbündeten Halsabschneidern, die daran arbeiten, seine Vendetta gegen das Königreich Sturmwind zu erfüllen.",al={"wer lebt in den todesminen","wer führt die todesminen","todesminen fraktionen"}},["3042a935"]={q="Sind die Todesminen gefährlich?",a="Extrem gefährlich. Die oberen Tunnel sind von rastlosen untoten Bergleuten und Halsabschneidern verseucht, während die Tiefen von der The Defias Brotherhood stark befestigt sind. Neben bewaffneten Gesetzlosen und skrupellosen Aufsehern sehen sich Eindringlinge von Goblins entwickelte Kriegsmaschinen, tödliche Gießereien, rohe Oger-Muskelkraft und defensive Schießpulverladungen gegenüber. Das Eindringen in den Komplex ohne fähige Verbündete wird von der The People's Militia als Todesurteil angesehen.",al={"sind die todesminen gefährlich","gefahr der todesminen","wie gefährlich sind die todesminen"}},fb059910={q="Was sind die Todesminen?",a="Die Todesminen sind ein weitläufiges, verwinkeltes Netzwerk von Tunneln, die unter Westfall und dem nördlichen Schlingendorntal gegraben wurden und durch die Geisterstadt Mondbruch betreten werden. Vor dem Ersten Krieg waren diese Schächte das größte Goldförderzentrum in den Ländern der Menschen. Inmitten des Chaos der orkischen Invasion aufgegeben und lange Zeit als verwunschen gemieden, wurde das riesige unterirdische Labyrinth heimlich von der Bruderschaft der Defias als ihre primäre Operationsbasis übernommen.",al={"was sind die todesminen","ueberblick ueber die todesminen","lore der todesminen"}}},fp="9,199,24.464.0,18.459.1,34.153.1,48.227.0,50.222.1,55.224.0,57.205.0"}
P.entries["subzone:deadwood-village"] = {n="Lager der Totenwaldfelle",s="Im südlichen Teufelswald verteidigen die Furbolgs im Lager der Totenwaldfelle ihre groben Holzhütten gegen jeden, der sich nähert. Einst friedlich und naturverbunden, erlagen sie der dämonischen Verderbnis, die den Wald verheerte.",h="Im südlichen Teufelswald verteidigen die Furbolgs im Lager der Totenwaldfelle ihre groben Holzhütten gegen...",kw={"verderbnis","totenwaldfelle","lager der totenwaldfelle","teufelswald","furbolg","holzschlundfurbolgs"},ang={["class:Druid"]="Euch als Druide zeigt das Lager der Totenwaldfelle, wie tief dämonische Verderbnis friedliche Geschöpfe entstellen kann und wie die Abwehrkräfte der Natur versagen können."},sec={{t="Ein gefallener Stamm",b="Nahe der südlichen Grenze des Teufelswalds versammelt sich der Stamm der Totenwaldfelle in seinem Dorf. Als dämonische Energien die uralten Wälder durchströmten, konnten die Furbolgs der schleichenden Fäulnis nicht widerstehen. Teuflische Bosheit verzerrte ihren Verstand, und sie gaben ihre Traditionen und ihre Harmonie mit der Natur auf.\n\nNun verteidigen Schläger, Schamanen und Höhlenbehüter ihr verseuchtes Gebiet gegen Eindringlinge. Ihre Gewalttätigkeit stürzt ihre unverdorbenen Vettern, die Holzschlundfurbolgs, in Verzweiflung."}},faq={{q="Warum sind die Furbolgs hier feindselig?",a="Dämonische Verderbnis überwältigte die Furbolgs im Lager der Totenwaldfelle, als der Teufelswald während des Dritten Krieges verheert wurde. Teufelsmagie verwandelte ihre natürlichen Instinkte in rasende Angriffslust und machte sie gewalttätig, wahnsinnig und feindselig gegenüber Außenstehenden.",al={"feindseligkeit der totenwaldfelle","warum greifen sie an","warum sind totenwaldfelle rot"}},{q="Können Spieler mit den Bewohnern des Lagers der Totenwaldfelle sprechen oder Frieden schließen?",a="Nein. Der Stamm der Totenwaldfelle ist zu tief verdorben, um Frieden zu schließen. Abenteurer jagen sie wegen ihrer Stammesfedern und um die Gunst der unverdorbenen Holzschlundfurbolgs zu gewinnen, die die Tunnel im Norden bewachen.",al={"mit totenwaldfellen befreundet sein","ruf bei den totenwaldfellen"}},{q="In welcher Beziehung steht dieser Stamm zu den Holzschlundfurbolgs?",a="Die Totenwaldfelle und die Holzschlundfurbolgs waren einst Furbolgstämme, die im Einklang mit der Natur lebten. Als der Teufelswald verdorben wurde, bewahrten die Holzschlundfurbolgs ihren Verstand, doch die Totenwaldfelle verfielen dem Teufelswahnsinn. Die Holzschlundfurbolgs betrachten sie nun als gefallen und gefährlich.",al={"holzschlundfurbolgs und totenwaldfelle","furbolgstämme"}}},fp="16,200,14.436.0,34.229.0,56.193.0,44.237.0"}
P.entries["subzone:deathknell"] = {n="Todesend",s="In Todesend erwachen die frisch befreiten Toten zum ersten Mal, in einem verborgenen Tal im Südwesten von Tirisfal. Sie haben sich aus dem Griff des Lichkönigs gelöst und schließen sich hier den Verlassenen an. Doch willenlose Diener der Geißel, Eiferer und wilde Tiere bedrängen das Dorf. Wer einen Platz in Sylvanas Windläufers Königreich beanspruchen will, steht hier vor einer harten ersten Prüfung.",h="In Todesend erwachen die frisch befreiten Toten zum ersten Mal, in einem verborgenen Tal im Südwesten von...",kw={"todesend","startgebiet der verlassenen","mindless ones","nachtwebergrund","schattengrab","sylvanas","tirisfal"},ang={["faction:Horde"]="Obwohl dieses Tal abgeschieden und dunkel ist, öffnet es den Weg ins Königreich der Verlassenen und entsendet neue Soldaten, die den Stützpunkt der Horde in den Östlichen Königreichen stärken.",["race:Undead"]="Als Abenteurer der Verlassenen beginnt Ihr hier und erhebt Euch aus der kalten Erde des Schattengrabs. Lady Sylvanas bietet Euch nach dem Schrecken der Plague eine Aufgabe und Zuflucht."},sec={{t="Wiege der Verlassenen",b="Das Tal liegt hinter zerklüfteten Hügeln, knapp nördlich der Grenze zu Silberwald. Elite-Todeswachen halten die enge Schlucht, die aus dem Tal führt, fest verschlossen. Die meisten Ortschaften in Tirisfal behielten ihre menschlichen Namen aus dem gefallenen Lordaeron. Diese nicht. Die Untoten, die sie für sich beanspruchten, nannten sie Todesend.\n\nDie Stadt selbst ist zweigeteilt. Ihre nördliche Hälfte samt der Dorfschmiede ist noch immer von willenlosen Zombies und wilden Ghulen überrannt. Die Verlassenen halten sich im Süden, rund um die alte Kirche. Dort nehmen die Betreuer jeden Neuankömmling auf und führen ihn in den Dienst der Banshee-Königin."},{t="Ein belagertes Tal",b="Das Überleben ist hier niemals gewiss. Im Nordwesten haben monströse Spinnen den Nachtwebergrund eingenommen, eine Goldmine, die die junge Nation der Verlassenen braucht. Im Südosten unterhält der Scharlachrote Kreuzzug ein Lager und beobachtet das Tal ohne Unterlass. Seine Kuriere laufen zu den Hochburgen des Kreuzzugs im Osten, und seine Späher erkunden Todesends Verteidigung. Und in den nördlichen Ruinen müssen die Betreuer noch immer die willenlosen Toten abwehren."}},faq={{q="Warum wurde die Stadt in Todesend umbenannt?",a="Die Untoten, die Todesend für sich beanspruchten, benannten es um, nachdem sie sich dort niedergelassen hatten, während die meisten Gemeinden Tirisfals ihre menschlichen Namen behielten. Warum sie diesen Namen wählten, ist unbekannt.",al={"todesend namensherkunft","warum heißt es todesend","alter name von todesend"}},{q="Warum ist die nördliche Hälfte der Stadt von Untoten überrannt?",a="Viele Leichname, die nach dem Dritten Krieg erweckt wurden, erlangten ihren Verstand nicht zurück. Der nördliche Dorfplatz und die Schmiede sind von den Mindless Ones, wilden Zombies, Ghulen und Skeletten bevölkert, die noch immer der nachwirkende Wille der Geißel antreibt. Verteidiger der Verlassenen vertreiben sie, um Ausrüstung zu bergen und die Kirche zu bewachen. Betreuer sammeln Altmetall, Werkzeuge und Vorräte für neu auferstandene Seelen, die sich auf den vor ihnen liegenden Weg machen.",al={"warum gibt es zombies in todesend","geißel in todesend","mindless ones todesend"}},{q="Was tut der Scharlachrote Kreuzzug in der Nähe von Todesend?",a="Ein Trupp des Scharlachroten Kreuzzugs lagert in den Hügeln südöstlich von Todesend. Seine Mitglieder wollen alle Untoten vernichten, überwachen den Pass, überfallen frisch erwachte Verlassene und tauschen Spähberichte mit scharlachroten Hochburgen andernorts in Lordaeron aus.",al={"scharlachrotes lager todesend","kreuzfahrer vor todesend","scharlachroter kreuzzug tal von tirisfal"}},{q="Warum können die Verlassenen die örtliche Goldmine nicht nutzen?",a="Der Nachtwebergrund in den Klippen nordwestlich von Todesend ist von aggressiven Spinnen überrannt. Gold ist für die Kriegsanstrengungen der Verlassenen wichtig, doch solange die Spinnen bleiben, kann die Siedlung die Ader nicht ausbeuten. Ihr Verlust schneidet die Verlassenen von einer Ressource ab, die für ihre junge Wirtschaft lebenswichtig ist.",al={"todesend mine","nachtwebergrund","spinnenmine tirisfal"}}},fx={["1ab0c524"]={q="Was ist Todesend?",a="Todesend ist eine kleine Siedlung der Verlassenen, die in einem geschützten Tal im südwestlichen Tirisfal liegt, direkt nördlich der Grenze zum Silberwald. Sie dient als Erwachensort für neu befreite Untote, an dem die frisch Auferstandenen empfangen, beurteilt und ausgebildet werden. Das Dorf ist in zwei Teile gespalten: Während die Verlassenen das südliche Gelände nahe der Kirche halten, bleiben die nördliche Hälfte und ihre alte Schmiede von sinnlosen Untoten überrannt.",al={"was ist dieser ort","todesend dorf","über todesend"}},ae63ed0c={q="War es einst ein normales Dorf?",a="Ja. Bevor der Dritte Krieg das Land verwüstete, war Todesend eine lebende menschliche Siedlung innerhalb des Königreichs Lordaeron. Als die Pest der Untoten über das Land fegte, erlagen die Menschen ihr und wurden in den Bann der Geißel erhoben. Im Gegensatz zu anderen Städten in Tirisfal, die ihre ursprünglichen menschlichen Namen behielten, wurde dieses Dorf später von den Verlassenen in Todesend umbenannt.",al={"todesend vergangenheit","war todesend menschlich","altes todesend"}},["2ffa4d6f"]={q="Wer lebte hier zuvor?",a="Die ursprünglichen Bewohner waren gewöhnliche menschliche Untertanen des Königreichs Lordaeron, darunter Farmer, Schmiede und Stadtbewohner. Als das Königreich unter der Geißel zusammenbrach, wurden viele geschlachtet oder durch die Pest verdorben, auf dem Friedhof und in den Krypten am Hang begraben oder in sinnlose Sklaven verwandelt, die immer noch durch die nördlichen Ruinen wandern.",al={"wer lebte hier","ursprüngliche bewohner todesend","ehemalige dorfbewohner"}},e9c17660={q="Warum ist Todesend zerstört oder verlassen?",a="Die Stadt fiel während des Dritten Krieges, als die Pest der Untoten Lordaeron verzehrte. Die Verlassenen haben seither nur den südlichen Teil um die Kirche zurückerobert. Die nördlichen Gebäude, einschließlich der Schmiede, bleiben verlassen und von feindseligen untoten Überresten der Geißel befallen, die die Verteidiger noch nicht vollständig säubern konnten.",al={"warum ist todesend zerstört","warum ist todesend kaputt","ruinen von todesend"}},af76d1fc={q="Ist Todesend gefährlich?",a="Sehr gefährlich jenseits des südlichen Umkreises. Sinnlose Untote streifen durch die nördliche Hälfte der Stadt, während riesige Nachtnetzspinnen die nahegelegene Goldmine im Nordwesten befallen. Um die Sache noch schlimmer zu machen, befindet sich ein Lager fanatischer Scharlachroter Kreuzzügler direkt im Südosten, das regelmäßig Überfälle auf das Dorf startet.",al={"ist todesend sicher","gefahr todesend","bedrohungen in todesend"}},["9b2c91d1"]={q="Warum bin ich untot? Was ist mit mir geschehen?",a="Ihr seid während des Falls von Lordaeron gestorben, ein Opfer der schrecklichen Pest der Untoten, die vom Lichkönig entfesselt wurde. Euer Körper wurde in die Armee der Geißel erhoben und gezwungen, dem eisernen Willen des Meisters zu dienen. Als der Griff des Lichkönigs nach dem Dritten Krieg schwächer wurde, brach Euer Geist frei und hinterließ Euch mit freiem Willen in einem toten Körper.",al={"warum bin ich untot","wie bin ich gestorben","was ist mit mir passiert"}},["4fca782c"]={q="War ich davor lebendig?",a="Das wart Ihr. Ihr lebtet als sterblicher Bewohner von Lordaeron, bevor der Dritte Krieg das Reich in den Ruin trieb. Ihr hattet ein Leben, ein Zuhause und sterbliche Bindungen, bevor die Pest Euch forderte und unheilige Magie Euren Leichnam neu erschuf.",al={"war ich lebendig","war ich ein mensch","mein früheres leben"}},["37eab6c0"]={q="Erinnere ich mich an mein altes Leben?",a="Viele Untote behalten fragmentarische, qualvolle Erinnerungen an ihr früheres sterbliches Leben und die Schrecken, die sie während der Herrschaft des Lichkönigs begehen mussten. Für die meisten Verlassenen sind diese Erinnerungen eine Quelle anhaltender Qual und stiller Rache.",al={"erinnere ich mich","vergangene erinnerungen untote","verlassene erinnerung"}},e26c7288={q="Wer sind die Verlassenen?",a="Die Verlassenen sind intelligente Untote mit freiem Willen, die sich nach dem Dritten Krieg von der Kontrolle des Lichkönigs befreit haben. Gesammelt und angeführt von Fürstin Sylvanas Windläufer, schufen sie sich ein Zuhause in den Ruinen von Lordaeron und errichteten ihre Hauptstadt in der Unterstadt.",al={"wer sind die verlassenen","fraktion der verlassenen","was sind die verlassenen"}},b31080e3={q="Wie unterscheiden wir uns von den anderen Untoten?",a="Die überwiegende Mehrheit der Untoten auf Azeroth gehört zur Geißel und ist vollständig der mentalen Beherrschung des Lichkönigs unterworfen. Ihr und die anderen Verlassenen habt diese Ketten gesprengt und Eure Wahrnehmung, Eure Autonomie und Euren freien Willen zurückgewonnen.",al={"unterschied zwischen verlassenen und geißel","sind wir geißel","untote mit freiem willen"}},["7fbc82e5"]={q="Warum sind wir der Horde beigetreten?",a="Umgeben von feindseligen lebenden Königreichen und der unerbittlichen Geißel, sahen sich die Verlassenen allein der völligen Vernichtung gegenüber. Sie gingen ein Zweckbündnis mit der Horde jenseits des Meeres ein, wodurch sie sich die notwendige militärische Unterstützung und das gegenseitige Überleben sicherten, im Austausch für einen nördlichen Stützpunkt in den Östlichen Königreichen.",al={"warum der horde beitreten","bündnis verlassene horde","warum horde"}},c317a133={q="Wer ist die Dunkle Fürstin, von der alle sprechen?",a="Sie ist Fürstin Sylvanas Windläufer, die Bansheekönigin und souveräne Herrscherin der Verlassenen. Einst Waldläufergeneralin von Silbermond, wurde sie während der Invasion der Geißel auf Quel'Thalas von Prinz Arthas getötet und als Banshee wiedererweckt. Später befreite sie sich vom Willen des Lichkönigs, versammelte die abtrünnigen Untoten und eroberte die Katakomben von Lordaeron zurück.",al={"dunkle fürstin","wer ist die dunkle fürstin","bansheekönigin"}},["1b5563f2"]={q="Was sind die geistlosen Zombies? Waren sie nicht auch Verlassene?",a="Sie waren niemals Verlassene. Als die Seuche die Toten von Lordaeron wiedererweckte, verloren viele von ihnen jegliche Vernunft und höhere Denkkraft und wurden zu wilden Hüllen, die nur noch von grundlegenden Raubtierinstinkten getrieben wurden. Da ihnen der Verstand fehlt, um sich zu befreien oder Entscheidungen zu treffen, bleiben sie feindselige Schergen der Geißel.",al={"geistlose zombies","wer sind die geistlosen zombies","zombies in todesend"}},["68a4c897"]={q="Hätte mir das auch passieren können?",a="Ja. Unzählige Leichen, die durch die Seuche wiedererweckt wurden, erlitten einen völligen mentalen Verfall und erlangten nie wieder ihren Verstand oder ihr Bewusstsein zurück. Es war reines Glück oder eiserner Wille, dass Euer Intellekt und Eure Selbstbeherrschung bewahrt wurden, während so viele andere an geistloser Wildheit zugrunde gingen.",al={"könnte ich geistlos sein","warum bin ich nicht geistlos","gefahr geistloser zombies"}},["05e3a89b"]={q="Wer ist der Scharlachrote Kreuzzug und warum greifen sie uns an?",a="Der Scharlachrote Kreuzzug ist ein fanatischer Orden, der aus den Überresten der Ritter der Silbernen Hand und den überlebenden Menschen von Lordaeron hervorgegangen ist. Sie sind von fanatischem Hass auf alle Untoten verzehrt, weigern sich, zwischen der blutrünstigen Geißel und den Verlassenen mit freiem Willen zu unterscheiden, und streben die völlige Ausrottung der Untoten in ganz Lordaeron an.",al={"wer ist der scharlachrote kreuzzug","warum greift der scharlachrote kreuzzug an","scharlachroter kreuzzug"}},b4877dc1={q="Waren sie einst Teil der Ritter der Silbernen Hand?",a="Ja. Als die Ritter der Silbernen Hand während des Dritten Krieges nach dem Tod von Uther der Lichtbringer und dem Fall der Hauptstadt zerschlagen wurden, schlossen sich überlebende Paladine und Priester zusammen, um gegen die Untoten zu kämpfen, und wandelten sich schließlich zu dem fanatischen Kreuzzug, den Ihr heute seht.",al={"scharlachroter kreuzzug silberne hand","waren scharlachrote paladine","ursprung silberne hand"}},["56471820"]={q="Was sind die Rattlecage Skeletons und warum sind sie uns gegenüber feindselig?",a="Rattlecage Skeletons sind Automaten der Geißel, die durch Nekromantie aus den Knochen der Toten Lordaerons erhoben wurden. Da ihnen ein eigener Wille oder lebendiges Fleisch fehlt, sind sie direkt an den anhaltenden nekromantischen Zwang des Lichkönigs gebunden, jeden lebenden oder untoten Eindringling zu töten.",al={"klapperskelette","warum greifen klapperskelette an","feindselige skelette"}},["574ed092"]={q="Sind sie nicht auch Untote wie ich?",a="Sie sind Untote wie Ihr, aber die feindseligen Rattlecage Skeletons zeigen nicht den freien Willen und die Selbstbeherrschung, die die Verlassenen auszeichnen. Sie dienen den destruktiven Zwecken der Geißel.",al={"sind klapperskelette untot","sind skelette nicht wie wir","skelette untote"}},["9d34c29a"]={q="Was sind die Night Web-Spinnen und woher kommen sie?",a="Die Night Web-Spinnen sind giftige Spinnentiere, die die Goldmine und die umliegende Senke nordwestlich von Todesend befallen haben. Als Tirisfal unter der Seuche verkümmerte, mutierten einheimische Ungeziefer und wurden aggressiv; sie übernahmen das Tal und vertrieben die Verlassenen von ihren wichtigen Goldvorkommen.",al={"nachtnetzspinnen","woher kommen die spinnen","nachtnetzspinnen mine"}},["22acb08e"]={q="Was kommt nach Todesend? Was gibt es in Brill?",a="Wenn Ihr das Tal von Todesend verlasst, gelangt Ihr nach Tirisfal in Richtung Brill. Brill ist eine größere Stadt der Verlassenen mit einem Rathaus, der Taverne Zur Galgenschlinge und Ausbildern. Von dort aus führt die Straße weiter nach Süden in die Unterstadt.",al={"nach todesend","was gibt es in brill","wohin nach todesend"}},["969b7b3b"]={q="Wo ist die Unterstadt von hier aus?",a="Die Unterstadt liegt östlich von Todesend. Um sie zu erreichen, nehmt Ihr die nördliche Straße aus dem Tal, passiert Brill und fahrt weiter nach Süden unter den Ruinen des Palastes der Hauptstadt hindurch.",al={"wo ist die unterstadt","wie komme ich zur unterstadt","richtung unterstadt"}},["95231242"]={q="Wie bin ich in Todesend gelandet?",a="Ihr seid während der Zerstörung von Lordaeron durch die Geißel gestorben und wurdet in den Krypten des Schattengrabs über dem Dorf begraben. Als der eiserne Griff des Lichkönigs auf die Untoten schwächer wurde, kehrte Euer Bewusstsein zurück. Ihr habt Euch aus Eurem Grab befreit und seid den Hang hinunter nach Todesend gewandert, wo die Verlassenen frisch erwachte Leichen versammeln, um zu sehen, ob sie den Willen besitzen, der Dunklen Fürstin zu dienen.",al={"wie bin ich hierher gekommen","warum bin ich hier","woher komme ich"}},["6fb0c436"]={q="Was soll ich in Todesend tun?",a="Ihr beweist Eure Nützlichkeit für die Verlassenen und sichert dieses Tal. Frisch erwachte Untote müssen zeigen, dass sie ihren Verstand nicht an die geistlose Geißel verloren haben, die um das Dorf herum lauert. Die örtlichen Anführer brauchen Euch, damit Ihr abtrünnige Zombies ausschaltet, den Spinnenbefall in der nahegelegenen Goldmine beseitigt und die Eiferer des Scharlachroten Kreuzzugs zurückdrängt, die versuchen, die Untoten aus Tirisfal zu vertreiben, bevor Ihr nach Brill weitergeschickt werden könnt.",al={"was tue ich hier","was ist mein ziel hier","was ist meine mission"}},["3bebe502"]={q="Warum beginnt ein neuer Untoter hier in Todesend?",a="Todesend dient als Erholungsort für die frisch wiedererweckten Toten der Verlassenen. Die umliegenden Hügel und Krypten, insbesondere das Schattengrab, beherbergen Tausende von Opfern Lordaerons aus dem Dritten Krieg. Da die mentale Beherrschung des Lichkönigs nachlässt, erheben sich hier ständig Leichen mit intaktem freiem Willen. Todeswachen, die im gesamten Tal stationiert sind, fangen die neu Erhobenen ab und bieten den Überlebenden Schutz und Führung, bevor Wahnsinn oder feindselige Kreuzfahrer sie vernichten können.",al={"warum starten untote hier","warum starte ich in todesend","warum todesend für untote"}}},fp="10,336,22.570.0,20.417.0,36.179.0,55.409.0,50.244.0,47.278.0"}
P.entries["subzone:decrepit-ferry"] = {n="Die Verfallene Fähre",s="An der Verfallenen Fähre liegt die Insel Fenris durch zerstörte Anleger jenseits des Lordameresees abgeschnitten. Die Geißel tötete den Fährmann und zerstörte die Boote, und Untote und Rot-Hide-Gnolle überrennen das Ufer.",h="An der Verfallenen Fähre liegt die Insel Fenris durch zerstörte Anleger jenseits des Lordameresees...",kw={"die verfallene fähre","insel fenris","fährmann","ghule","der lordameresee","rot hide","geißel","silberwald"},ang={["race:Undead"]="Als Untoter seht Ihr in diesen Ruinen den Fall Lordaerons. Überreste der Geißel und Rot-Hide-Gnolle bedrohen nun die Unternehmungen der Verlassenen im östlichen Silberwald."},sec={{t="Eine Lebensader durchtrennt",b="Vor dem Dritten Krieg überquerten die Menschen von diesem Anleger aus täglich den Lordameresee. Einheimische Bauern brachten frische Erzeugnisse ans Wasser und verkauften sie an den wohlhabenden Herrn der Insel Fenris und seinen Haushalt. Gegen ein geringes Entgelt beförderte der Fährmann Handelswaren, Boten und Adlige zu Besuch zwischen dem Festland und der Festung.\n\nDann fegte die Geißel durch das Königreich, und der Handel endete. Der Fährmann wurde brutal getötet, die Boote wurden zerschlagen, und der Steg verfiel."},{t="Ein verderbtes Ufer",b="Die Anleger sind gefährlich für Reisende am Seeufer. Da die Fähre außer Betrieb ist, liegt die Insel Fenris isoliert jenseits des Wassers. Ghule und Skelettkrieger durchstreifen die Ruinen, ebenso wie Rot-Hide-Gnolle. Die alte Überfahrt ist heute ein gefährlicher Uferabschnitt im Silberwald."}},faq={{q="Wofür wurde die Verfallene Fähre ursprünglich genutzt?",a="Die Fähre beförderte Menschen und Waren zwischen dem Festland des Silberwalds und der Insel Fenris. Bauern brachten ihre Ernte über den Lordameresee, um sie dem wohlhabenden Herrn der Insel zu verkaufen, und zahlten dem Fährmann für jede Überfahrt ein geringes Entgelt.",al={"geschichte der fähre","was war dieser anleger","warum gibt es hier eine fähre"}},{q="Was geschah mit der Fähre und ihrem Fährmann?",a="Als die Geißel durch Lordaeron fegte, wurde der Fährmann ermordet und die Boote wurden zerschlagen. Der Steg verfiel, und die Überfahrten endeten.",al={"was geschah mit dem fährmann","wer zerstörte die fähre"}},{q="Welche Monster lauern heute an den Fähranlegern?",a="Ghule und Skelettkrieger durchstreifen das Ufer, während Rot-Hide-Gnolle die nahen Uferbereiche durchstreifen.",al={"kreaturen an der verfallenen fähre","was lebt an der fähre"}},{q="Könnt Ihr von hier aus noch ein Boot zur Insel Fenris nehmen?",a="Nein. Die Boote wurden zerschlagen und der Steg verfiel, sodass die Insel Fenris jenseits des Sees abgeschnitten liegt.",al={"boot nach fenris nehmen","wie gelangt man zur insel fenris","ist die fähre in betrieb"}}},fx={e48e8d6c={q="Was ist The Decrepit Ferry?",a="The Decrepit Ferry sind die verfallenen Überreste eines einst geschäftigen Docks am östlichen Ufer des Silberwaldes. Vor dem Fall von Lordaeron diente es als wichtiger Übergang über den Lordameresee zur Insel Fenris und transportierte örtliche Bauern, Reisende und Vorräte zum Anwesen auf der Insel.",al={"was ist the decrepit ferry","the decrepit ferry silberwald","the decrepit ferry docks"}},db91f3d1={q="Warum ist The Decrepit Ferry verfallen und verlassen?",a="Als die Geißel durch Lordaeron fegte, fand der Fährbetrieb ein gewaltsames Ende. Der Fährmann wurde von dem Ansturm der Untoten ermordet, die Schiffe wurden zerschmettert und die Docks verfielen völlig, als monströse Raubtiere die umliegenden Ufer überrannten.",al={"warum ist es verlassen","warum ist the decrepit ferry zerstört","the decrepit ferry zerstört"}},e3243651={q="Ist The Decrepit Ferry gefährlich?",a="Ja, es ist extrem gefährlich für unvorsichtige Reisende. Die verlassenen Docks und das Ufer wimmeln von aggressiven Ghulen, ruhelosen Skelettkriegern und wilden Rot Hide-Gnollen, was jeden Aufenthalt in der Nähe der Anlegestelle zu einem tödlichen Unterfangen macht.",al={"ist the decrepit ferry gefährlich","bedrohungen the decrepit ferry","ist es hier sicher"}},bec7dabe={q="Warum nennt man sie Die verfallene Fähre?",a="Sie verdankt ihren düsteren Namen dem zerstörten, verrottenden Zustand, der nach dem Dritten Krieg zurückblieb. Was einst eine robuste, geschäftige Lebensader zur Insel Fenris war, ist zu verwitterten Balken, zertrümmertem Schutt und wassergetränkten Ruinen verfallen.",al={"warum nennt man sie die verfallene fähre","name die verfallene fähre","herkunft des namens die verfallene fähre"}}},fp="14,185,20.464.0,21.276.0,48.222.0,44.145.0,46.99.0,51.101.0"}
P.entries["subzone:deep-elem-mine"] = {n="Tiefenfelsmine",s="Im Herzen des Silberwalds halten Worgen die Tiefenfelsmine und ihre Stollen besetzt. Einst wurde dort Erz abgebaut, doch die Mine fiel, als Erzmagier Arugals Magie die Region erfasste und ihre Bergleute verwandelte.",h="Im Herzen des Silberwalds halten Worgen die Tiefenfelsmine und ihre Stollen besetzt.",kw={"arugal","dalar morgenweber","tiefenfelsmine","grimson der bleiche","silberwald","varimathras","worgen"},ang={["profession:Mining"]="Das wilde Rudel macht den Bergbau gefährlich, doch die Tiefenfelsmine birgt eines der reichsten unterirdischen Mineralvorkommen des Silberwalds.",["race:Undead"]="Die Sicherung der Mine bringt den Verlassenen wirtschaftlichen Gewinn und erfüllt den Befehl des Grabmals, Arugals Macht über den zentralen Silberwald zu brechen."},sec={{t="Ein Unterschlupf der Bestien",b="Die Tiefenfelsmine lieferte einst Erz für die lebenden Bewohner Lordaerons. Dann entfesselte Erzmagier Arugal seinen Wolfsfluch im gesamten Silberwald, und er breitete sich in den Stollen aus. Die Arbeiter erlagen ihm und wurden zu bösartigen Worgen. Sie ließen ihre Spitzhacken zurück und beanspruchten die Höhle als Unterschlupf."},{t="Grimson und die Ambitionen der Verlassenen",b="Grimson der Bleiche befehligt das Rudel in der Tiefenfelsmine. Der einstige Vorarbeiter der Mine bewahrte seine Gerissenheit auch nach der Verwandlung. Die Verlassenen im Grabmal wollen die Stollen und ihre Erze zurückgewinnen. Auf Befehle hin, die Schreckenslord Varimathras unterstützt, wollen ihre Agenten Grimson enthaupten und die Bestien ausmerzen, damit die Horde den Reichtum der Mine sichern kann."}},faq={{q="Was befindet sich in der Tiefenfelsmine?",a="Feindselige Worgen, die von Erzmagier Arugals Magie befallen sind, bevölkern die Tiefenfelsmine. Grimson der Bleiche, einst der menschliche Vorarbeiter, führt das Rudel tief in den Stollen an.",al={"was ist in der tiefenfelsmine","gegner der tiefenfelsmine","wer lebt in der tiefenfelsmine"}},{q="Warum wollen die Verlassenen die Tiefenfelsmine räumen lassen?",a="Die Verlassenen wollen die Bodenschätze der Mine für ihre Kriegsanstrengungen in Lordaeron nutzen. Dalar Morgenweber und die Anführer des Grabmals wollen ihre Ressourcen im Namen von Schreckenslord Varimathras beanspruchen, sobald die Worgen verschwunden sind.",al={"interesse der verlassenen an der mine","warum die tiefenfelsmine räumen","wer will die mine"}},{q="Wer ist Grimson der Bleiche?",a="Grimson der Bleiche war der sterbliche Vorarbeiter der Tiefenfelsmine. Arugals wilder Fluch verwandelte die Arbeiter, und Grimson wurde zu einem gerissenen Alphaworgen. Er bewahrte genug von seinem Verstand, um das Rudel in der Mine zu befehligen.",al={"wer ist grimson","geschichte von grimson dem bleichen","boss der tiefenfelsmine"}},{q="Wie kamen die Worgen in die Mine?",a="Die Worgen der Tiefenfelsmine waren ursprünglich ihre eigenen Arbeiter. Erzmagier Arugals Fluch breitete sich im gesamten Silberwald aus und verwandelte sie an ihrem Arbeitsplatz.",al={"warum sind worgen in der mine","ursprung der worgen in der tiefenfelsmine","wie wurden die bergleute verwandelt"}}},fx={["1f4b67a8"]={q="Was ist die Tiefenfelsmine?",a="Die Tiefenfelsmine ist eine alte Minenanlage, die in die Hügel des zentralen Silberwaldes gehauen wurde. Einst ein regulärer Abbauort unter menschlichen Aufsehern, hat sie den normalen Betrieb eingestellt und ist unter die Kontrolle wilder Worgen geraten, die durch die dunkle Zauberei von Erzmagier Arugal entstanden sind.",al={"tiefenfelsmine","was ist die tiefenfelsmine","tiefenfelsmine silberwald"}},["3a795aef"]={q="Warum wurde die Tiefenfelsmine aufgegeben?",a="Die Mine fiel, als sich die Teufelsmagie von Erzmagier Arugal über die Hügel des Silberwaldes ausbreitete. Anstatt einfach von außen überrannt zu werden, kollabierte die Mine von innen, als ihr eigener Vorarbeiter, Grimson der Bleiche, dem Worgenfluch erlag und den Ort in eine Höhle für wilde Bestien verwandelte.",al={"warum wurde die tiefenfelsmine aufgegeben","tiefenfelsmine ruiniert","was hat die tiefenfelsmine zerstört"}},ee2e1c55={q="Ist die Tiefenfelsmine gefährlich?",a="Die Tiefenfelsmine zu betreten, ohne vorbereitet zu sein, ist äußerst gefährlich. Ihre dunklen Tunnel wimmeln von wilden Worgen, die von räuberischen Instinkten getrieben werden und alle unter dem rücksichtslosen Kommando ihres ehemaligen Aufsehers, Grimson der Bleiche, vereint sind.",al={"tiefenfelsmine gefahr","ist die tiefenfelsmine sicher","bedrohungen in der tiefenfelsmine"}}},fp="14,186,15.292.0,29.345.1,30.150.0,48.215.0,24.207.0,37.142.0"}
P.entries["subzone:deeprun-tram"] = {n="Die Tiefenbahn",s="Unter den Bergen befördert die Tiefenbahn Reisende zwischen Eisenschmiede und Sturmwind. König Magni Bronzebart gab sie nach dem Zweiten Krieg in Auftrag, und ihre beiden Gleise befördern Bürger, Soldaten und Waren zwischen den Hauptstädten der Allianz.",h="Unter den Bergen befördert die Tiefenbahn Reisende zwischen Eisenschmiede und Sturmwind.",kw={"die tiefenbahn","der zwergendistrikt","gelbin mekkadrill","magni bronzebart","unterirdischer see","u-bahn","tinkertown","tiefenbahn"},ang={["faction:Alliance"]="Für die Allianz verbindet die Bahn zwei ihrer am stärksten befestigten Hauptstädte. Sie ermöglicht schnelle Truppenbewegungen zwischen ihnen und unterstützt ihre gegenseitige Verteidigung.",["profession:Engineering"]="Die Eisenbahn ist eine Errungenschaft gnomischer Ingenieurskunst, mit fortschrittlichem Gleisantrieb, verstärkten Glaskonstruktionen, die den Tiefen eines unterirdischen Sees standhalten, und komplexen elektrischen Schaltstationen."},sec={{t="Ein Wunderwerk unterirdischer Ingenieurskunst",b="Nach dem Zweiten Krieg suchte König Magni Bronzebart einen schnelleren Weg, zwergische Hilfe und Vorräte nach Sturmwind zu schicken. Gebirgspässe machten die Reise langsam, also bat er Hochtüftler Gelbin Mekkadrill, eine unterirdische Eisenbahn zu entwerfen.\n\nGnomische Ingenieure bahnten einen Weg unter einem Berg hindurch und durch einen gewaltigen unterirdischen See. Ratten erschwerten die Arbeiten, doch die Bahn wurde fertiggestellt. Sie befördert Tausende kostenlos zwischen Eisenschmiede und Sturmwind."}},faq={{q="Warum wurde die Tiefenbahn gebaut?",a="Nach dem Zweiten Krieg brauchte König Magni Bronzebart einen schnelleren Weg für Vorräte und zwergische Truppen, die Sturmwinds Wiederaufbau und Verteidigung unterstützten. Er beauftragte Hochtüftler Gelbin Mekkadrill, die unterirdische Eisenbahn zwischen den beiden Hauptstädten zu entwerfen und zu bauen.",al={"warum wurde die tiefenbahn gebaut","zweck der tiefenbahn","wer baute die tiefenbahn"}},{q="Wie fährt die Bahn unter Wasser?",a="Bei Grabungen zwischen Dun Morogh und Sturmwind stießen gnomische Ingenieure in einen gewaltigen unterirdischen See vor. Sie bauten einen abgedichteten, verstärkten Glastunnel durch das Wasser, in dem Fahrgäste Threshadons und Haie neben dem Gleis schwimmen sehen können.",al={"tiefenbahn wasserfenster","tiefenbahn unter wasser","tiefenbahn see"}},{q="Warum gibt es so viele Ratten entlang der Gleise?",a="Die dunklen, feuchten Schächte entlang der Gleise bieten Ungeziefer Raum zur Vermehrung. Gnomische Bahnhofsvorsteher kämpfen dagegen an, dass Ratten Kabel zernagen und Bahnsteige überrennen, und Reisende sowie Rattenfänger wie Monty helfen manchmal, ihre Zahl zu verringern.",al={"tiefenbahn ratten","warum ratten in der tiefenbahn","rattenproblem"}},{q="Ist die Fahrt mit der Bahn kostenlos?",a="Ja. Eisenschmiede und Sturmwind finanzieren die Bahn als Dienst für die Bevölkerung und das Militär. Sie verkehrt ununterbrochen und ohne Fahrpreis für Bürger und Verbündete der Allianz.",al={"tiefenbahn kosten","tiefenbahn fahrpreis","was kostet die fahrt mit der tiefenbahn"}}},fx={a94670c5={q="Was ist Die Tiefenbahn?",a="Die Tiefenbahn ist ein unterirdisches und unter Wasser verlaufendes Eisenbahnsystem, das von Gnomen entworfen wurde und die Hauptstädte der Allianz, Eisenschmiede und Sturmwind, verbindet. Sie besteht aus Doppelgleisen und zwei Zügen mit je drei Waggons und bietet eine schnelle, kostenlose Beförderung zwischen der Festung der Zwerge im Gebirge und dem Königreich der Menschen.",al={"was ist die tiefenbahn","infos zur tiefenbahn","über die tiefenbahn"}},a0c9cf68={q="Was ist mit Die Tiefenbahn passiert?",a="Nach dem Zweiten Krieg wollte König Magni Bronzebart einen schnelleren Weg, um zwergische Vorräte und Truppen zu transportieren und beim Wiederaufbau des angeschlagenen Königreichs Sturmwind zu helfen. Er beauftragte den Hochtüftler Gelbin Mekkadrill mit dem Entwurf der unterirdischen Strecke. Trotz eines unerwarteten unterirdischen Sees und einer andauernden Rattenplage während des Baus wurde die Eisenbahn fertiggestellt und zu einer unverzichtbaren Lebensader für die Allianz.",al={"tiefenbahn geschichte","geschichte der tiefenbahn","wie wurde die tiefenbahn gebaut"}},c0b14a4e={q="Wer wartet und betreibt Die Tiefenbahn?",a="Gnomische Ingenieure arbeiten täglich an Die Tiefenbahn, um sicherzustellen, dass ihre mechanischen Waggons reibungslos und sicher zwischen den Hauptstädten verkehren. Neben den Ingenieurteams werden die Bahnhöfe und Tunnel von lokalen Händlern, Gleisarbeitern und Schädlingsbekämpfern wie Monty besucht, der unermüdlich versucht, die hartnäckige Rattenpopulation entlang der Gleise in den Griff zu bekommen.",al={"wer betreibt die tiefenbahn","tiefenbahn personal","wer arbeitet bei der tiefenbahn"}},["2e1a8782"]={q="Ist Die Tiefenbahn gefährlich?",a="Die Fahrt mit der Bahn selbst ist bemerkenswert ruhig und sicher; sie wurde konstruiert, um Reisende sicher unter Bergen und unterirdischen Gewässern zu befördern. Wenn Ihr die Gleise jedoch zu Fuß begeht, setzt Ihr Euch rasenden Waggons und einer berüchtigten Rattenplage aus. Außerhalb der verstärkten Glasröhren lauern aquatische Raubtiere wie Dreschadon und Haie in den dunklen Tiefen des Sees, sicher von den Passagieren getrennt.",al={"tiefenbahn gefahr","ist die tiefenbahn sicher","gefahren in der tiefenbahn"}}},fp="12,243,36.434.0,31.258.0,36.237.0,44.235.0,25.146.0"}
P.entries["subzone:deepwater-tavern"] = {n="Tiefenwassertaverne",s="Im Hafen von Menethil können Reisende in der Tiefenwassertaverne rasten und nach Arbeit suchen. Seeleute und Abenteurer treffen sich dort, und Hafengerüchte können in einer Schlägerei enden.",h="Im Hafen von Menethil können Reisende in der Tiefenwassertaverne rasten und nach Arbeit suchen.",kw={"tiefenwassertaverne","lehrer für erste hilfe","gastwirt","hafen von menethil","tapoke slim jahn","tavernenschlägerei","sumpfland"},ang={["faction:Alliance"]="Als Mitglied der Allianz auf Reisen zwischen Eisenschmiede und dem offenen Meer könnt Ihr in der Tiefenwassertaverne rasten und Euch versammeln."},sec={{t="Herz des Hafens von Menethil",b="Im Hafen von Menethil bietet die Tiefenwassertaverne Schutz vor dem Regen der Marschen und beschwerlichen Wegen. Seeleute, Hafenarbeiter, Händler und erschöpfte Abenteurer versammeln sich unter ihren Holzbalken. Sie tauschen Neuigkeiten aus, treffen sich, wärmen sich auf und versorgen ihre Wunden.\n\nEinheimische Händler und ein Lehrer für Erste Hilfe helfen jenen, die in die Marschen ziehen oder über das große Meer aufbrechen. In der Taverne geht es lebhaft zu, und verschüttetes Bier kann einen Streit in eine Schlägerei verwandeln. Tapoke 'Slim' Jahn ist dafür bekannt, solche Schlägereien anzuzetteln."}},faq={{q="Wo befindet sich die Tiefenwassertaverne?",a="Die Tiefenwassertaverne liegt nahe dem Wasser im Hafen von Menethil, dem wichtigsten Hafen des Sumpflands an der Westküste von Khaz Modan.",al={"tiefenwassertaverne standort","wo ist die tiefenwassertaverne","hafen von menethil gasthaus"}},{q="Welche Dienste werden in der Taverne angeboten?",a="Die Taverne bietet Unterkunft, Speisen und Getränke sowie einheimische Händler und einen Lehrer für Erste Hilfe. Reisende durch die Marschen können dort ihre Vorräte auffüllen und ihre Wunden versorgen.",al={"tiefenwassertaverne dienste","menethil taverne lehrer","was gibt es in der tiefenwassertaverne"}},{q="Wer zettelt häufig Schlägereien in der Taverne an?",a="Tapoke 'Slim' Jahn zettelt häufig Schlägereien unter den rauflustigen Gästen und Seeleuten der Taverne an.",al={"tavernenschlägerei menethil","tapoke slim jahn","wer zettelt schlägereien in der tiefenwassertaverne an"}},{q="Warum ist die Taverne so belebt?",a="Der Hafen von Menethil ist ein wichtiger Knotenpunkt für Schifffahrt und Marine zwischen Khaz Modan und Kalimdor. Als einziges großes Gasthaus der Stadt zieht die Tiefenwassertaverne Seeleute, Söldner und Abenteurer der Allianz an, die ins Sumpfland aufbrechen.",al={"warum die tiefenwassertaverne besuchen","warum ist die tiefenwassertaverne beliebt"}}},fx={d7fa1340={q="Was ist die Tiefenwassertaverne?",a="Die Tiefenwassertaverne ist das Haupthotel und der gesellschaftliche Mittelpunkt von Hafen von Menethil, dem geschäftigen Seehafen der Allianz im Sumpfland. Seeleute, Kaufleute, Reisende und Abenteurer, die durch Khaz Modan ziehen, halten hier, um sich auszuruhen, Vorräte zu kaufen, medizinische Hilfe zu suchen oder lokale Arbeit anzunehmen. Sie bleibt einer der lebhaftesten Treffpunkte in Die Marschen.",al={"was ist die tiefenwassertaverne","tiefenwassertaverne sumpfland","hafen von menethil taverne"}},e51423df={q="Ist die Tiefenwassertaverne gefährlich?",a="Obwohl die Taverne sicher unter dem Schutz der Allianz im Hafen von Menethil liegt, ist sie alles andere als ruhig. Betrunkene Gäste und schillernde Stammgäste zetteln häufig gewalttätige Faustkämpfe im Schankraum an, oft provoziert von Unruhestiftern wie Tapoke Slim Jahn. Seid wachsam, aber unter ihrem Dach droht Euch wenig wirkliche Gefahr.",al={"ist die tiefenwassertaverne sicher","schlägereien tiefenwassertaverne","gefahr tiefenwassertaverne"}}},fp="16,161,24.469.0,38.118.0,46.172.0,43.89.0,26.217.0"}
P.entries["subzone:defias-hideout"] = {n="Defias Hideout",s="Landstreicher und Schläger der Defias halten sich im verfallenen Haus am südlichen Rand von Mondbruch auf. Sein oberes Stockwerk verbirgt einen Zugang zu Kammern unter der Stadt.",h="Landstreicher und Schläger der Defias halten sich im verfallenen Haus am südlichen Rand von Mondbruch auf.",kw={"die todesminen","defias","defias hideout","eingang","mondbruch","van cleef","westfall"},ang={["class:Rogue"]="Als Schurke könnt Ihr erkennen, wie die Defias in einem schlichten, verfallenen Herrenhaus einen Zugang zu einer gewaltigen unterirdischen Festung verbergen. Deren Ausmaß bleibt den beiläufigen Blicken der Patrouillen aus Sturmwind verborgen.",["faction:Alliance"]="Als Abenteurer der Allianz könnt Ihr Edwin van Cleefs Verschwörung bis zu diesem verfallenden Anwesen zurückverfolgen. Es ist ein wichtiger Stützpunkt für die Bemühungen, den Aufstand der Defias zu beenden."},sec={{t="Ein Tor in Ruinen",b="Edwin van Cleefs südliche Operationen liegen unter einem verfallenen Haus in Mondbruch. Landstreicher und Schläger der Defias durchstreifen seine geplünderten Räume, ähnlich wie in anderen Herrenhäusern und Bauernhäusern der Siedlung. Im oberen Stockwerk führt eine Öffnung hinab in die gewundenen Gänge der Todesminen.\n\nDie Bruderschaft hält den Großteil ihrer Kräfte am Rand von Mondbruch und bei der Arbeit unter Tage, sodass nur wenige Wachen im Haus bleiben. Sie bewachen das Versteck als engen Zugang zu den Minen, nicht als eigenständige Festung."}},faq={{q="Was befindet sich im Defias Hideout?",a="Eine Treppe im Haus führt zu einem gewundenen Tunnel und zum oberirdischen Eingang der Todesminen. Landstreicher durchstreifen das weitgehend leere Gebäude, und einige Banditen halten sich in der Nähe auf.",al={"im defias hideout","eingang zum versteck","was gibt es hier"}},{q="Warum ist das Versteck im Inneren kaum bewacht?",a="Die Bruderschaft der Defias hält ihre Kämpfer in den Straßen von Mondbruch bereit, um Eindringlinge abzufangen. Ihre Arbeiter und Vollstrecker arbeiten tief in den Minen.",al={"warum leer","wo sind die defias","warum so wenige wachen"}},{q="Wo in Mondbruch steht dieses Gebäude?",a="Das Versteck steht am südlichen Rand von Mondbruch im Südwesten von Westfall, nahe dem Fuß der Berge. Es ist ein großes, intaktes, zweistöckiges Gebäude.",al={"wie das versteck finden","wo ist das defias hideout","lage des verstecks"}},{q="Wer sind die Leute, die sich beim Versteck aufhalten?",a="Banditen der Defias und verzweifelte Landstreicher halten sich im Gebäude und in der Umgebung von Mondbruch auf. Manche Landstreicher flohen vor der Armut; andere schlossen sich aus Not der Bruderschaft an.",al={"wer sind die landstreicher","landstreicher von mondbruch","leute der defias"}}},fx={["34bb7c5e"]={q="Was ist Defias Hideout?",a="Defias Hideout ist ein verwittertes Gebäude in der von Banditen kontrollierten Stadt Mondbruch. An der Oberfläche scheint es nur ein weiteres verlassenes Haus zu sein, das von Vagabunden besetzt wurde, aber im Obergeschoss befindet sich der versteckte Eingang direkt in die Todesminen, die weitläufige unterirdische Festung der The Defias Brotherhood.",al={"defias hideout","was ist dieses gebäude","was ist defias hideout"}},d0a92509={q="Warum nennt man es Defias Hideout?",a="Es dient der The Defias Brotherhood als getarnter Zugang zu ihren unterirdischen Operationen unter Mondbruch. Die Banditen nutzen das gewöhnliche Äußere, um den Hauptdurchgang, der in die Todesminen führt, vor der The People's Militia und neugierigen Behörden der Allianz zu verbergen.",al={"warum defias hideout","name defias hideout","warum nennt man es defias hideout"}},["5348ff1f"]={q="Ist Defias Hideout gefährlich?",a="Das Gebäude selbst wird oft nur leicht bewacht, da die meisten Agenten der Defias entweder in den Straßen von Mondbruch patrouillieren oder tief unter der Erde arbeiten. Allerdings halten sich verzweifelte Vagabunden darin auf, und wenn Ihr durch den versteckten oberen Eingang tretet, befindet Ihr Euch direkt an der Schwelle der Todesminen und ihrer bewaffneten Bruderschaft.",al={"ist defias hideout gefährlich","wie gefährlich ist defias hideout","gefahr defias hideout"}}},fp="14,149,17.507.1,34.175.1,47.141.0,44.150.0,48.158.0"}
P.entries["subzone:demon-fall-canyon"] = {n="Demonfall-Canyon",s="Im südlichen Eschental trägt der Canyon die Narben der Schlacht, die die Orcs vom Blutfluch befreite. Thrall und Grommash Hellscream stellten sich hier Mannoroth.",h="Im südlichen Eschental trägt der Canyon die Narben der Schlacht, die die Orcs vom Blutfluch befreite.",kw={"eschental","blutfluch","demonfall-canyon","blutschrei","grommash hellscream","mannoroth","grubenlord","thrall"},ang={["faction:Horde"]="Als Mitglied der Horde steht Ihr auf geweihtem Boden, wo Grommash Hellscream sein größtes Opfer brachte und den Blutfluch der Brennenden Legion brach.",["race:Orc"]="Als Orc verdankt Ihr Eure geistige und körperliche Freiheit der Schlacht in diesem Canyon. Grom gab sein Leben, um Eure dämonische Knechtschaft zu beenden."},sec={{t="Mannoroths Fall",b="Nahe dem Dämonenhügel und dem Dämonenstieg trägt der Canyon noch immer die Narben des Dritten Krieges. Kriegshäuptling Thrall und Häuptling Grommash Hellscream spürten hier den Grubenlord Mannoroth auf, um seine Macht über die Horde zu brechen. Mannoroth streckte Thrall nieder. Grom nutzte die Gelegenheit, um seine Axt Blutschrei in die Brust des Dämons zu rammen.\n\nDie Höllenexplosion zerschmetterte Mannoroth und tötete Grom. Mit dem Tod des Grubenlords waren die Orcs von ihrer fortwährenden dämonischen Knechtschaft befreit."},{t="Geweihte, doch gefährliche Schlucht",b="Die Horde benannte den Canyon nach Groms letztem Gefecht und errichtete in der Nähe ein Denkmal zu Ehren seiner Erlösung. Mannoroths Tod entfesselte dämonische Macht, die das umliegende Land verdarb. Noch immer durchdringt Teufelsmagie den Canyon, in dem niedere Dämonen umherstreifen. Pilger, die diesen geweihten Boden aufsuchen, begegnen auf Schritt und Tritt Gefahren."}},faq={{q="Warum heißt dieser Ort Demonfall-Canyon?",a="Die Horde benannte den Canyon nach dem Fall Mannoroths, der hier von Grommash Hellscream erschlagen wurde.",al={"demonfall-canyon namensherkunft","warum heißt er demonfall-canyon","wie erhielt er seinen namen"}},{q="Was geschah hier zwischen Grom und Mannoroth?",a="Thrall und Grom stellten sich Mannoroth gemeinsam. Der Grubenlord schlug Thrall bewusstlos, doch Grom versetzte ihm mit seiner Axt einen tödlichen Hieb. Mannoroths Explosion aus dämonischem Feuer verwundete Grom tödlich. Mit seiner letzten Tat befreite Grom sein Volk vom Blutfluch.",al={"groms tod","grom gegen mannoroth","wie starb grom"}},{q="Warum streifen noch immer Dämonen im Canyon umher?",a="Mannoroths Tod entfesselte eine gewaltige Explosion dämonischer Energie, die den Boden des Canyons dauerhaft verdarb. Die anhaltende Teufelsverderbnis zieht noch immer niedere Dämonen an und bietet ihnen Zuflucht.",al={"warum dämonen im demonfall-canyon","demonfall-canyon gegner","warum ist er teufelsverderbt"}},{q="Wo steht das Denkmal für Grom Hellscream?",a="Nahe dem Demonfall-Canyon steht ein Denkmal zu Ehren von Grom Hellscream. Pilger der Horde kommen dorthin, um den Krieger zu ehren, der ihr Volk befreite.",al={"groms denkmal standort","hellscreams denkmal","wo ist groms grab"}}},fx={f0a5bd72={q="Was ist der Demonfall-Canyon?",a="Der Demonfall-Canyon ist eine von Narben gezeichnete, teufelskorrumpierte Schlucht, die in den südlichen Hügeln des Eschentals liegt, östlich des Dämonenstieg. Es ist der historische Schlachtplatz, an dem Kriegshäuptling Thrall und Grommash Höllschrei während des Dritten Krieges dem dämonischen Grubenlord Mannoroth gegenüberstanden. Heute ist der Canyon immer noch von nachwirkenden dämonischen Energien gezeichnet und dient der Horde als heilige Pilgerstätte, um sich an Groms ultimatives Opfer zu erinnern.",al={"was ist der demonfall-canyon","demonfall-canyon lore","über den demonfall-canyon"}},["1e62195e"]={q="Ist der Demonfall-Canyon gefährlich?",a="Extrem gefährlich. Der Tod des Grubenlords Mannoroth badete die Schlucht in roher Teufelsmagie, die die Erde weiterhin korrumpiert. Feindselige niedere Dämonen und umherstreifende Unholde wandern durch die Tiefen des Canyons und greifen jeden an, der es wagt, ihn zu betreten. Auch wenn die Hauptkommandanten der Brennende Legion hier besiegt wurden, muss jeder Reisende oder Pilger, der seinen Respekt erweist, ständig auf der Hut vor den rastlosen Monstern sein, die in den Felsen lauern.",al={"wie gefährlich ist der demonfall-canyon","ist der demonfall-canyon gefährlich","bedrohungen im demonfall-canyon"}}},fp="17,158,21.460.0,28.317.0,43.85.0,46.253.0,46.178.0,36.146.0"}
P.entries["subzone:demon-fall-ridge"] = {n="Dämonenstieg",s="Dämonen halten den Dämonenstieg im südöstlichen Eschental besetzt, über dem Ort, an dem Mannoroth fiel. Teufelsmagie befleckt noch immer die Höhen, und die Brennende Legion hat einen Höhlenbau der Nachtelfen für sich beansprucht.",h="Dämonen halten den Dämonenstieg im südöstlichen Eschental besetzt, über dem Ort, an dem Mannoroth fiel.",kw={"eschental","höhlenbau","brennende legion","demonfall-canyon","dämonenstieg","diathorus the seeker","schreckenslord"},ang={["class:Druid"]="Als Druide findet Ihr Dämonen in einem Höhlenbau vor, der einst dem Smaragdgrünen Traum geweiht war. Ihre Anwesenheit ist ein Affront gegen den Zirkel des Cenarius.",["class:Warlock"]="Als Hexenmeister findet Ihr einen aktiven Schreckenslord vor, der die Teufelsstreitkräfte anführt. Seine Befehlsgewalt offenbart, wie die Überreste der Legion in Kalimdor organisiert sind."},sec={{t="Über der Verderbnis",b="Westlich des Demonfall-Canyons blickt der Dämonenstieg auf den Ort hinab, an dem Grommash Hellscream gegen den Grubenlord Mannoroth kämpfte. Seine Klippen tragen noch immer die Narben der Teufelsmagie aus dem Dritten Krieg. Die überlebenden Dämonen nutzen die Höhen als Aufmarschgebiet. Niedere Dämonen patrouillieren an den felsigen Hängen, schänden das Waldland und bedrohen Reisende entlang der südlichen Grenze des Eschentals."},{t="Der entweihte Höhlenbau",b="In der Flanke des Kamms liegt ein verlassener Höhlenbau der Nachtelfen. Dunkle Zauberei erfüllt nun die Gänge, in denen einst Druiden schliefen. Teufelsunholde durchstreifen seine Hallen, und tief im Inneren herrscht Diathorus the Seeker über das Konklave. Der gerissene Schreckenslord befehligt die Dämonen, die im Wald verblieben sind."}},faq={{q="Wo liegt der Dämonenstieg?",a="Der Dämonenstieg erhebt sich im südöstlichen Eschental, westlich des Demonfall-Canyons und nahe der Grenze zum Brachland.",al={"lage des kamms","wo ist der dämonenstieg","eschental dämonenkamm"}},{q="Warum gibt es auf diesem Kamm Dämonen?",a="Der Kamm überblickt den Ort, an dem Mannoroth im Dritten Krieg starb. Dämonen, die die Niederlage der Legion überlebten, zerstreuten sich in die Höhen und verschanzten sich auf dem Kamm und in einem verlassenen Höhlenbau.",al={"warum dämonen hier","dämonenstieg dämonen","präsenz der brennenden legion"}},{q="Wer führt die Dämonen hier an?",a="Diathorus the Seeker befehligt das Konklave aus den tiefsten Winkeln des Höhlenbaus. Er ist ein mächtiger Schreckenslord der Nathrezim.",al={"wer ist hier der boss","dämonenanführer","diathorus the seeker"}},{q="Was ist das für ein Bau im Kamm?",a="Der Bau ist ein uralter Höhlenbau der Nachtelfen, einst ein Heiligtum, in dem Druiden den Smaragdgrünen Traum betraten. Er wurde verlassen und dann von der Brennenden Legion überrannt und entweiht.",al={"höhlenbau","demon fall höhle","was ist der höhlenbau"}}},fx={["38a8c952"]={q="Was ist der Dämonenstieg?",a="Der Dämonenstieg ist eine hohe, trostlose Klippe im südlichen Eschental, die über dem Demonfall-Canyon thront. Einst ein heiliger Grabhügel-Zufluchtsort für Nachtelfen-Druiden, sind der Kamm und seine unterirdischen Hallen in Dunkelheit gefallen, überrannt von überlebenden Mitgliedern der Brennende Legion, die einen abscheulichen Stützpunkt tief im Wald unterhalten.",al={"was ist der dämonenstieg","dämonenstieg lore","dämonenstieg übersicht"}},f78b2bbc={q="Wer lebt am Dämonenstieg?",a="Der Kamm wimmelt von dämonischen Überresten der Brennende Legion. Verschiedene niedere Dämonen schleichen auf den Oberflächenpfaden herum und bewachen den Eingang zum verlassenen Grabhügel, während tief im Inneren ihr Meister residiert, der Schreckenslord Diathorus der Sucher, der das dämonische Konklave befehligt.",al={"wer lebt am dämonenstieg","bewohner des dämonenstiegs","wer ist am dämonenstieg"}},c0607561={q="Ist der Dämonenstieg gefährlich?",a="Er ist außergewöhnlich gefährlich. Der Kamm wimmelt von feindseligen dämonischen Kräften, die bereit sind, jeden abzuschlachten, der dort eindringt. Wenn Ihr Euch in den ausgehöhlten Grabhügel wagt, müsst Ihr Euch verschanzten dämonischen Unholden stellen, was in einer Begegnung mit einem gerissenen und tödlichen Schreckenslord gipfelt.",al={"ist der dämonenstieg gefährlich","dämonenstieg bedrohungen","gefahr dämonenstieg"}},["45002eaf"]={q="Warum heißt der Dämonenstieg so?",a="Der Kamm hat seinen Namen von dem angrenzenden Demonfall-Canyon unterhalb, dem historischen Schlachtfeld, auf dem Grom Höllschrei während des Dritten Krieges den Grubenlord Mannoroth erschlug, womit er den dämonischen Blutfluch über die Orks brach und den Fall der Vorhut der Legion markierte.",al={"warum heißt der dämonenstieg so","dämonenstieg namensherkunft","bedeutung des namens demon fall"}},e8f31dd4={q="Warum ist der Grabhügel am Dämonenstieg verlassen?",a="Der in die Klippe gehauene Grabhügel wurde einst von Nachtelfen-Druiden für ihren langen Schlummer genutzt. Nach den Wirren des Dritten Krieges und der dämonischen Korruption, die sich vom nahegelegenen Canyon ausbreitete, verloren oder verließen die Elfen das Heiligtum, wodurch die Überlebenden der Legion es entweihen und besetzen konnten.",al={"warum ist der dämonenstieg ruiniert","verlassener grabhügel am dämonenstieg","warum ist der grabhügel verlassen"}}},fp="16,188,23.359.0,21.278.0,26.104.0,35.208.0,26.124.0,44.173.0"}
P.entries["subzone:demont-s-place"] = {n="Demonts Heim",s="Gesetzlose halten Demonts Heim westlich von Mondbruch im südwestlichen Westfall besetzt. Einst ernährten seine Felder das Königreich Sturmwind. Der wirtschaftliche Zusammenbruch und die Bruderschaft der Defias vertrieben die Verwalter und hinterließen leere Felder und verwitterte Zäune.",h="Gesetzlose halten Demonts Heim westlich von Mondbruch im südwestlichen Westfall besetzt.",kw={"defias","bruderschaft der defias","demonts heim","gehöft","mondbruch","westfall"},ang={["class:Rogue"]="Als Schurke könnt Ihr auf den verwüsteten Grundstücken rund um Mondbruch, darunter Demonts Heim, das gesetzlose Netzwerk erkennen, das die Bruderschaft der Defias im ganzen Umland errichtet hat.",["faction:Alliance"]="Für Reisende der Allianz zeigt Demonts Heim, wie weit die Ordnung aus Westfall zurückgewichen ist. Gesetzlose der Defias halten direkt unter den Augen des Königreichs ehemaliges Ackerland besetzt."},sec={{t="Ein verfallenes Gehöft",b="Demonts Heim liegt in Sichtweite von Mondbruch, zwischen den Familienhöfen, die einst das Königreich Sturmwind ernährten. Der wirtschaftliche Zusammenbruch und gesetzlose Banditen raubten dem Hof seine Lebensgrundlage und vertrieben seine Verwalter. Nun nutzen Gesetzlose sein Gelände als Erweiterung der Defias-Festung in Mondbruch."},{t="Im Griff der Bruderschaft",b="Die Bruderschaft der Defias hält Demonts Heim am Rande von Mondbruch besetzt. Schläger, Taschendiebe und vertriebene Arbeiter halten sich zwischen seinen Zäunen und zertrümmerten Gebäuden auf. Sie überfallen Reisende, die von den südlichen Straßen abkommen. Solange Mondbruch nicht zurückerobert und die Gesetzlosen nicht zerschlagen sind, kann hier keine friedliche Landwirtschaft mehr betrieben werden."}},faq={{q="Wo liegt Demonts Heim?",a="Demonts Heim liegt im südwestlichen Westfall, unmittelbar westlich der verlassenen Stadt Mondbruch.",al={"demonts heim lage","wo liegt demonts heim","demonts heim karte"}},{q="Wem gehört Demonts Heim?",a="Ein Siedler namens Demont besaß den Hof vermutlich, bevor Bauernunruhen und wirtschaftliche Not das Land erfassten. Seine ursprünglichen Bewohner sind längst geflohen oder umgekommen, und nun halten Banditen das verwüstete Ackerland besetzt.",al={"wem gehört demonts heim","wer ist demont","demonts hof besitzer"}},{q="Wer besetzt derzeit den Hof?",a="Mitglieder der Bruderschaft der Defias besetzen das Gehöft. Sie nutzen sein verwüstetes Gelände als Ausgangspunkt für ihre Einsätze außerhalb ihres Stützpunkts in Mondbruch.",al={"wer ist in demonts heim","welche feinde sind in demonts heim","demonts heim gegner"}},{q="Kann der Hof wieder bewirtschaftet werden?",a="Unter den derzeitigen Bedingungen kann der Hof nicht wieder bewirtschaftet werden. Die Defias halten den Süden Westfalls besetzt, und Sturmwind kann keine Garnisonstruppen entbehren. Das Gehöft bleibt für gewöhnliche Bauern zu gefährlich, um es wieder aufzubauen.",al={"demonts heim wieder aufbauen","ist demonts heim verlassen"}}},fx={["51911e59"]={q="Was ist mit Demonts Heim geschehen?",a="Einst ein funktionierendes Gehöft in der Kornkammer von Westfall, fiel Demonts Heim den weitverbreiteten Unruhen und dem wirtschaftlichen Ruin zum Opfer, die die Region heimsuchten. Es wurde von Agenten der The Defias Brotherhood beansprucht und besetzt.",al={"geschichte von demonts heim","was geschah bei demonts heim","warum ist demonts heim verlassen"}},["9301a59d"]={q="Warum ist Demonts Heim zerstört?",a="Das Gehöft wurde von seinen ursprünglichen Verwaltern inmitten des Niedergangs von Westfall verlassen und von der The Defias Brotherhood beschlagnahmt, wodurch die Gebäude verwahrlosten und zu kaum mehr als zerschlagenen Ruinen verkommen sind.",al={"warum ist demonts heim zerstört","demonts hof ruine","warum wurde demonts heim verlassen"}},f73fe511={q="Ist Demonts Heim gefährlich?",a="Ja. Direkt neben der Gesetzlosenfestung Mondbruch gelegen, wird das verlassene Gehöft häufig von gefährlichen Agenten der The Defias Brotherhood und örtlichen Plünderern patrouilliert oder überrannt.",al={"gefahr bei demonts heim","ist demonts heim sicher","bedrohungen bei demonts hof"}},["74f5ac6b"]={q="Was ist Demonts Heim?",a="Demonts Heim ist ein verfallener, zerstörter Bauernhof, der sich knapp westlich von Mondbruch in Westfall befindet. Wie bei anderen zerstörten Höfen Westfalls, wie etwa dem Todesacker, ist wenig von seinem einstigen bäuerlichen Leben übrig geblieben.",al={"was ist demonts heim","demonts heim westfall","demont bauernhof"}}},fp="14,241,18.300.0,27.310.0,32.98.0,24.212.0,32.135.0,39.201.0"}
P.entries["subzone:den-of-flame"] = {n="Der Flammenbau",s="Schwarze Drachkin halten den Flammenbau in den westlichen Düstermarschen, westlich der Stonemaul Ruinen. Die Stonemaul-Oger errichteten ihn als ihren Bau, doch Onyxias Brut hat sie vertrieben.",h="Schwarze Drachkin halten den Flammenbau in den westlichen Düstermarschen, westlich der Stonemaul Ruinen.",kw={"schwarzer drachenschwarm","der flammenbau","drakoniden","düstermarschen","onyxia","die stonemaul ruinen"},ang={["faction:Horde"]="Die Stonemaul-Oger sind eingeschworene Verbündete der Horde. Die Drachkin aus dem Flammenbau zu vertreiben, hilft dabei, ihre zerstörte Siedlung zu rächen."},sec={{t="Ein eroberter Bau",b="Schwarze Drakoniden patrouillieren am brennenden Rand des Flammenbaus und bewachen seinen Höhleneingang. Die Stonemaul-Oger erbauten die grobe Steinfestung als ihren Hauptbau und Zufluchtsort. Dann verwüstete der Schwarze Drachenschwarm die Siedlung des Clans. Die Brut zerstreute die Oger und eroberte den Bau, wo nun Drakoniden im Schatten von Onyxias nahegelegenem Hort Wache halten."}},faq={{q="Wozu wurde der Flammenbau ursprünglich errichtet?",a="Die Stonemaul-Oger errichteten den Flammenbau als Hauptbau ihres Clans. Sein Mauerwerk und seine Anlage folgen der Bauweise der Ogerclans.",al={"wer erbaute den flammenbau","ursprung des flammenbaus","ogerbau düstermarschen"}},{q="Warum haben schwarze Drachkin diesen Bau besetzt?",a="Onyxia richtete ihren Hort in der Nähe im Sumpf ein. Ihre Drachkin vertrieben die Stonemaul-Oger aus ihrer Siedlung und beanspruchten die Höhle als vorgeschobenen Außenposten der Brut.",al={"warum sind hier drachen","wer lebt im flammenbau","drakoniden düstermarschen"}},{q="Können die Stonemaul-Oger die Höhle zurückerobern?",a="Vorerst nicht. Die überlebenden Stonemaul-Oger haben sich an der Seite der Horde in Brackenwall niedergelassen. Schwarze Drakoniden halten ihren alten Bau mit starken Kräften besetzt.",al={"the den zurückerobern"}}},fp="12,183,17.378.0,47.128.0,45.169.0,41.148.0"}
P.entries["subzone:dire-maul"] = {n="Düsterbruch",s="In Feralas sind Düsterbruchs zerbrochene Hallen und Kolosseen unter rivalisierenden Mächten aufgeteilt. Einst hieß die uralte Stadt der Hochgeborenen Eldre'Thalas und hütete Königin Azsharas arkane Geheimnisse. Gordokoger, eindringende Satyrn und verkümmerte elfische Bewahrer teilen sich nun ihre zerfallenden Plätze.",h="In Feralas sind Düsterbruchs zerbrochene Hallen und Kolosseen unter rivalisierenden Mächten aufgeteilt.",kw={"düsterbruch","eldre'thalas","feralas","gordok","gordunni","immol'thar","shen'dralar","tortheldrin"},ang={["class:Mage"]="Als Magier könnt Ihr in den verfallenen Bibliotheken der Shen'dralar arkane Abhandlungen und Geheimnisse aus der Zeit vor der Großen Zerschlagung finden, bewacht von den Geistern meisterhafter Zauberer.",["race:NightElf"]="Als Nachtelf könnt Ihr Eldre'Thalas als tragisches Denkmal ungezügelter arkaner Hybris und jener dämonischen Kompromisse betrachten, die das uralte Kaldorei Empire zerbrachen."},sec={{t="Eldre'Thalas und die Große Zerschlagung",b="Eldre'Thalas beherbergte Königin Azsharas bevorzugte Zauberer, die Shen'dralar. Als der Brunnen der Ewigkeit während der Großen Zerschlagung zusammenbrach, errichtete Prinz Tortheldrin eine magische Barriere, die die Stadt rettete. Von ihrer Magiequelle abgeschnitten, sperrten die überlebenden Hochgeborenen den kolossalen Dämon Immol'thar unter ihrem Sanktum ein. Jahrtausendelang schöpften sie aus seiner Teufelsessenz, um ihre Unsterblichkeit und arkane Macht zu bewahren."},{t="Eine geteilte Ruine",b="Jahrhunderte der Isolation und schwindender Macht trieben Prinz Tortheldrin in den Wahnsinn. Er ließ die meisten seiner eigenen Bürger töten, damit eine kleine Kabale die verbleibende Energie des Dämons für sich allein beanspruchen konnte. Jenseits ihrer Heiligtümer beherrschen andere Mächte die Ruinen. Gordunnioger kontrollieren die Gordok Commons und veranstalten brutale Gladiatorenspiele in der Arena. Im Warpwood Quarter verbreiten Alzzin der Wildformer und seine verderbten Satyrn ihre Fäulnis."}},faq={{q="Wie hieß Düsterbruch ursprünglich?",a="Düsterbruch war einst Eldre'Thalas, eine prachtvolle Nachtelfenstadt, die vor zwölftausend Jahren von den Shen'dralar erbaut wurde. Sie errichteten sie, um Königin Azsharas kostbarstes arkanes Wissen zu schützen.",al={"düsterbruch ursprünglicher name","eldre'thalas geschichte","wer erbaute düsterbruch"}},{q="Wer lebt heute in Düsterbruch?",a="Feindliche Mächte teilen Düsterbruch unter sich auf. Gordunnioger kontrollieren unter King Gordok die nördlichen Gemeinschaftsplätze, Satyrn und verderbte Treants verseuchen die östlichen Gärten, und zurückgezogen lebende Hochgeborenenzauberer kämpfen in den westlichen Heiligtümern ums Überleben.",al={"wer ist in düsterbruch","düsterbruch bewohner","welche monster sind in düsterbruch"}},{q="Wie überstand die Stadt die Zerschlagung?",a="Als die Große Zerschlagung den Kontinent auseinanderriss, wirkten Prinz Tortheldrin und seine Arkanisten einen gewaltigen Schutzzauber. Er bewahrte Eldre'Thalas vor der Verwüstung, die das umliegende Reich versinken ließ.",al={"wie überstand eldre'thalas die zerschlagung","zerschlagung schutzschild düsterbruch","warum wurde es nicht zerstört"}},{q="Warum nutzen die Hochgeborenen hier dämonische Energie?",a="Nach der Zerstörung des Brunnens der Ewigkeit litten die Shen'dralar unter schwerem arkanem Entzug. Um ihre Macht und Unsterblichkeit zu bewahren, banden sie Immol'thar und entzogen dem Dämon seine Essenz, um zu überleben.",al={"immol'thar düsterbruch","warum entziehen die shen'dralar einem dämon energie","dämon in düsterbruch"}},{q="Was geschieht in der Arena von Düsterbruch?",a="Oger und Sklavenmeister nutzen das offene Kolosseum im Stadtzentrum, bekannt als der Schlägel, als Kampfgrube. Dort veranstalten sie Gladiatorenturniere, blutige Wettkämpfe und Herausforderungen um den Gordokthron.",al={"düsterbruch kolosseum","schlägel pvp","gladiatoren düsterbruch"}}},fp="9,269,36.412.0,14.406.1,37.179.0,27.246.0,39.205.0,48.200.0,39.195.0"}
P.entries["subzone:direforge-hill"] = {n="Hügel der Düsterschmiede",s="Feindselige Dunkeleisenzwerge halten den Hügel der Düsterschmiede im nordöstlichen Sumpfland besetzt, südöstlich von Dun Modr und nordöstlich des grünen Gürtels.",h="Feindselige Dunkeleisenzwerge halten den Hügel der Düsterschmiede im nordöstlichen Sumpfland besetzt...",kw={"balgaras","balgaras the foul","dunkeleisenzwerge","direforge","hügel der düsterschmiede","dun modr","der grüne gürtel","sumpfland"},ang={["class:Druid"]="Als Druide auf der Durchreise durch das Sumpfland müsst Ihr Euch mit dem feindseligen Lager der Dunkeleisenzwerge auf dem Hügel der Düsterschmiede auseinandersetzen.",["race:Dwarf"]="Als Bronzebeard-Zwerg aus Eisenschmiede seht Ihr, wie der Verrat des Dunkeleisenklans das Sumpfland erreicht. Hexenmeister wie Balgaras müssen sich dafür vor kaltem Stahl verantworten."},sec={{t="Eine Bastion dunkler Magie",b="Balgaras the Foul befehligt die Dunkeleisenzwerge auf dem Hügel der Düsterschmiede. Ihr Lager liegt südöstlich von Dun Modr, im nordöstlichen Sumpfland."},{t="Die Bedrohung für das Sumpfland",b="Reisende, die das nordöstliche Sumpfland durchqueren, müssen nahe am feindseligen Lager der Dunkeleisenzwerge auf dem Hügel der Düsterschmiede vorbeiziehen. Balgaras the Foul befehligt die Zwerge dort."}},faq={{q="Wo liegt der Hügel der Düsterschmiede?",a="Der Hügel der Düsterschmiede erhebt sich im nordöstlichen Sumpfland, südöstlich von Dun Modr und nordöstlich des grünen Gürtels. Er liegt nordwestlich der felsigen Steilhänge des Raptorgrats.",al={"hügel der düsterschmiede lage","wo liegt der hügel der düsterschmiede","direforge sumpfland"}},{q="Wer kontrolliert derzeit den Hügel der Düsterschmiede?",a="Feindselige Dunkeleisenzwerge halten den Hügel der Düsterschmiede unter dem Befehl des Hexenmeisters Balgaras the Foul besetzt.",al={"wer ist auf dem hügel der düsterschmiede","wer lebt auf dem hügel der düsterschmiede","hügel der düsterschmiede gegner"}},{q="Warum ist der Hügel der Düsterschmiede für das Sumpfland bedeutsam?",a="Auf dem Hügel der Düsterschmiede im nordöstlichen Sumpfland liegt ein feindseliges Lager der Dunkeleisenzwerge. Balgaras the Foul und seine Zwerge bedrohen Reisende, die die Region durchqueren.",al={"warum ist der hügel der düsterschmiede wichtig","direforge bedrohung","was geschieht auf dem hügel der düsterschmiede"}},{q="Wer ist Balgaras the Foul?",a="Balgaras the Foul ist ein Hexenmeister der Dunkeleisenzwerge, der die auf dem Hügel der Düsterschmiede lagernden Truppen befehligt. Seine verderbten Künste und sein aggressives Auftreten in den Hügeln machen ihn zu einem vorrangigen Ziel für die Verteidiger des Sumpfes.",al={"balgaras","balgaras the foul hintergrundgeschichte","wer ist balgaras"}}},fx={["5340135d"]={q="Was ist der Hügel der Düsterschmiede?",a="Der Hügel der Düsterschmiede ist ein erhöhter Bergrücken im nordöstlichen Teil des Sumpflands, der sich südöstlich von Dun Modr und nordwestlich des Raptorgrats befindet. Er dient als befestigtes Vorpostenlager für die feindseligen Dunkeleisenzwerge, die in der Region operieren.",al={"was ist der hügel der düsterschmiede","infos zu hügel der düsterschmiede","düsterschmiede sumpfland"}},c35b9f4a={q="Ist der Hügel der Düsterschmiede gefährlich?",a="Der Hügel der Düsterschmiede ist außergewöhnlich gefährlich. Das Lager wimmelt von aggressiven Dunkeleisenzwergen und ihren bösartigen Hexenmeistern, die alle unter der rücksichtslosen Führung von Balgaras der Scheußliche organisiert sind. Eindringlinge, die den Bergrücken hinaufwandern, werden sofort bei Sichtkontakt angegriffen.",al={"ist hügel der düsterschmiede sicher","gefahr bei düsterschmiede","bedrohungen am hügel der düsterschmiede"}}},fp="14,130,25.142.0,26.157.0,32.160.0,38.81.0,50.155.0,25.212.0"}
P.entries["subzone:dolanaar"] = {n="Dolanaar",s="In Dolanaar versammeln sich Reisende und Führer unter Teldrassils Ästen. Die Stadt südwestlich von Laubschattental ist der erste Ort, den junge Nachtelfen erreichen, nachdem sie ihre geschützten Übungsplätze verlassen haben. Waldläufer, Druiden und Handwerker helfen Neuankömmlingen, während sich seltsame Leiden im Weltbaum ausbreiten.",h="In Dolanaar versammeln sich Reisende und Führer unter Teldrassils Ästen.",kw={"darnassus","dolanaar","kal'dorei","nachtelfenstadt","laubschattental","teldrassil"},ang={["class:Druid"]="Als Druidenanwärter könnt Ihr in Dolanaar Rat zu Teldrassils Leiden suchen und lernen, Euren Geist auf das Gleichgewicht der Natur einzustimmen.",["race:NightElf"]="Als junger Nachtelf macht Ihr in Dolanaar Eure ersten Schritte in die weite Welt. Die wachsende Verderbnis des Weltbaums stellt Euren Schwur, die Natur zu bewahren, auf die Probe."},sec={{t="Ein Wegekreuz der Äste",b="Unter Teldrassils Blätterdach ist Dolanaar ein Kreuzungspunkt für Reisende. Südwestlich von Laubschattental sind seine Häuser und Plattformen nach traditioneller Nachtelfenart in den Wald eingewoben. Junge Nachtelfen kommen hierher, um ihre erste umfassende Ausbildung in Berufen, Kampfkünsten und Naturfertigkeiten zu erhalten. Die Straße nach Westen führt zur Hauptstadt Darnassus. Aus den umliegenden Ästen kommen Berichte über verderbte Wildtiere, aggressive Furbolgs und faulige Moose, und der Rat von Dolanaar hört sie an."}},faq={{q="Welchem Zweck dient Dolanaar?",a="Dolanaar ist der wichtigste Knotenpunkt und Außenposten für junge Nachtelfen, die die Übungsplätze für Anfänger in Laubschattental verlassen. Handwerker und Lehrer der Kampfkunst und Magie versammeln sich hier, und die Stadt bietet Reisenden eine Verbindung zur Hauptstadt.",al={"was ist dolanaar","dolanaar zweck","warum ist dolanaar wichtig"}},{q="Wo liegt Dolanaar?",a="Dolanaar liegt im mittleren Osten Teldrassils, einen kurzen Fußweg den Pfad entlang südwestlich von Laubschattental und östlich von Darnassus.",al={"dolanaar lage","wo liegt dolanaar","weg nach dolanaar"}},{q="Wie können Reisende von hier aus Darnassus erreichen?",a="Folgt der Waldstraße zu Fuß nach Westen durch Teldrassil, um die Tore von Darnassus zu erreichen. Dolanaar hat keinen eigenen Flugpunkt.",al={"reise nach darnassus","flugmeister dolanaar","von dolanaar nach darnassus"}},{q="Welche Bedrohungen betreffen Dolanaar?",a="Eine seltsame Verderbnis breitet sich im Wald um Dolanaar aus. Kranke Wildtiere, wahnsinnige Bäumlinge und feindselige Furbolgstämme bedrohen das Gebiet.",al={"ärger in dolanaar","dolanaar probleme","dolanaar quests"}}},fx={d9d46a9a={q="Was ist Dolanaar?",a="Dolanaar ist ein belebtes Nachtelfendorf, eingebettet in die zentral-östlichen Äste von Teldrassil, gleich südwestlich der Trainingsgelände von Laubschattental. Als Zentrum für regionalen Handel und Angelegenheiten auf dem großen Weltenbaum ist es normalerweise die erste größere Siedlung, auf die junge Nachtelfen stoßen, wenn sie sich in die weite Welt hinauswagen.",al={"was ist dolanaar","stadt dolanaar","dorf dolanaar"}},["6bb1c128"]={q="Ist Dolanaar gefährlich?",a="Innerhalb des Dorfes selbst seid Ihr sicher inmitten von Wachen, Druiden und Händlern. Die umliegenden Wälder bergen jedoch wachsende Unruhe. Verderbte Tierwelt, rastlose Gnarlkieferfurbolgs und finstere Harpyienschwärme bedrohen Reisende, die sich über den Rand der Siedlung hinauswagen.",al={"ist dolanaar gefährlich","sicherheit in dolanaar","ist dolanaar sicher"}}},fp="8,296,22.477.0,32.207.0,26.119.0,44.127.0,29.147.0"}
P.entries["subzone:dor-danil-barrow-den"] = {n="Der Dor'danil-Grabhügel",s="Südlich des Splitterholzpostens liegt der Dor'danil-Grabhügel im Schatten der Verlassenen. Einst schliefen hier Druiden, während ihre Geister den Smaragdgrünen Traum durchstreiften. Nun erfüllt Schrecken das Heiligtum.",h="Südlich des Splitterholzpostens liegt der Dor'danil-Grabhügel im Schatten der Verlassenen.",kw={"eschental","grabhügel","dor danil","dor'danil","irrsinnige druiden","mavoris cloudsbreak","mordenthal","taneel darkwood","uthil mooncall"},ang={["class:Druid"]="Als Druide kennt Ihr Grabhügel als heilige Orte, an denen Druiden mit dem Smaragdgrünen Traum in Verbindung treten. Die Folter und der zerrüttete Verstand jener in Dor'Danil sind ein unverzeihlicher Frevel.",["race:Undead"]="Als Untoter seht Ihr die Forschung der Verlassenen in Dor'Danil als unerbittliche Erforschung von Leben, Tod und seelentrennender Magie, selbst auf Kalimdors fernen Schlachtfeldern."},sec={{t="Ein entweihtes Heiligtum",b="Seit Jahrhunderten schlafen nachtelfische Druiden in Grabhügeln in ganz Kalimdor. Ihre Körper ruhen unter der Erde, während ihre Geister den Smaragdgrünen Traum durchwandern. Als die Horde ins Eschental vordrang, lag Dor'Danil tief hinter den feindlichen Linien. Die Orcs ließen die schlafenden Elfen weitgehend in Ruhe, doch die neu verbündeten Verlassenen sahen eine Gelegenheit. Ihre Agenten drangen in die Tiefen ein und begannen mit Experimenten, um die Druiden von ihren Geistern zu trennen.\n\nDie Qualen zerrütteten den Verstand der Träumer und trieben sie in den Wahnsinn. Nun streifen finstere Auftragsmörder der Verlassenen durch die dunklen Höhlen. Auch die gequälten Geister von Druiden, die nicht in ihre Körper zurückkehren können, suchen diese Höhlen heim."},{t="Die gequälten Wächter",b="Tief in Dor'Danils Tunneln wandern drei Druidengeister im Wahnsinn umher: Uthil Mooncall, Mavoris Cloudsbreak und Taneel Darkwood. Auch Darkslayer Mordenthal, ein Agent der Verlassenen, schleicht durch den Grabhügel. Für Nachtelfen und ihre Verbündeten vom Zirkel des Cenarius ist es eine düstere Gnade, die gepeinigten Geister zur Ruhe zu betten.\n\nDie Anwesenheit der Verlassenen zeigt die skrupellose, morbide Neugier, die Sylvanas' Agenten in Kalimdors Konflikte einbringen."}},faq={{q="Was ist der Dor'danil-Grabhügel?",a="Der Dor'danil-Grabhügel liegt unter der Erde im Eschental, südlich des Splitterholzpostens und südwestlich des Dämonenhügels. Einst schliefen hier Druiden in tiefer Trance, ihre Körper geborgen, während ihre Geister den Smaragdgrünen Traum betraten.",al={"was ist dieser ort","dor'danil-grabhügel infos","dor'danil hintergrundgeschichte"}},{q="Warum sind die Druidengeister im Inneren feindselig und wahnsinnig?",a="Agenten der Verlassenen drangen in den Grabhügel ein und experimentierten an den schlafenden Druiden, wobei sie deren Geister von ihren Körpern trennten. Das Trauma trieb die Druiden in gewalttätigen Wahnsinn.",al={"warum sind die druiden hier wahnsinnig","warum sind die geister wütend","irrsinnige druiden hintergrundgeschichte"}},{q="Wer ist Darkslayer Mordenthal?",a="Darkslayer Mordenthal ist ein Verlassener, der sich tief im Grabhügel unter dessen untoten Bewohnern aufhält. Seine Anwesenheit ist bekannt, doch er wird nicht als Leiter der Experimente benannt.",al={"mordenthal","wer ist der untote im inneren"}},{q="Welche namhaften Geister suchen die Tiefen heim?",a="Drei bedeutende Druidengeister suchen die unteren Kammern heim: Uthil Mooncall, Mavoris Cloudsbreak und Taneel Darkwood. Von ihren Körpern getrennt, durchstreifen sie die dunklen Tunnel in endloser Wut.",al={"namhafte gegner dor danil","namhafte druiden im inneren"}}},fx={b36fa772={q="Was geschah im Dor'danil-Grabhügel?",a="Historisch gesehen diente dieser Grabhügel als friedliche Zuflucht, in der Nachtelfendruiden in den Smaragdgrünen Traum eintraten. Als die Horde in das Eschental vorstieß, geriet der Ort tief hinter die feindlichen Linien. Während die Orks die schlafenden Druiden weitgehend ignorierten, entwickelten die Verlassene ein dunkleres Interesse. Sie führten Experimente durch, die darauf abzielten, die schlafenden Elfen von ihren Geistern zu trennen – ein Prozess, der den Verstand der Druiden zerrüttete und sie völlig wahnsinnig machte.",al={"geschichte von dordanil","was geschah in dordanil","hintergründe zu dordanil"}},c4765c4c={q="Ist der Dor'danil-Grabhügel gefährlich?",a="Der Dor'danil-Grabhügel ist außergewöhnlich gefährlich zu betreten. Seine verwinkelten unterirdischen Tunnel kriechen vor verstohlenen Assassinen der Verlassene, die ihre finstere Arbeit fortsetzen, sowie den gewalttätigen, gequälten Geistern der abgetrennten Druiden. Wer sich in seine tiefsten Kammern vorwagt, steht besonders furchterregenden rastlosen Geistern wie Uthil Mondruf, Mavoris Wolkenbruch und Taneel Dunkelwald gegenüber.",al={"ist der dor'danil-grabhügel gefährlich","gefahren im dordanil-grabhügel","bedrohungen im dordanil"}}},fp="20,177,22.620.0,23.405.1,29.219.0,52.159.0,29.170.0,39.189.0"}
P.entries["subzone:dormitory"] = {n="Dormitory",s="In Gnomeregan überrennen Troggs nun den Schlafsaal, und Strahlung erstickt seine Hallen. Einst lebten hier Gnome, doch nun beherrschen die Kreaturen, die sie vertrieben haben, die Wohnviertel der gefallenen Stadt.",h="In Gnomeregan überrennen Troggs nun den Schlafsaal, und Strahlung erstickt seine Hallen.",kw={"clean zone","schlafsaal","gnomeregan","hall of gears","lochkartenmaschine","trogg"},ang={["profession:Engineering"]="Selbst beim Versagen der biologischen Eindämmung verarbeiten die automatisierten Terminals der Matrix-Lochkartenmaschinen 3005-B weiterhin zuverlässig algorithmische Sicherheitslochkarten.",["race:Gnome"]="Für Euch als Gnom war der Schlafsaal einst ein Zuhause. Nun füllt verstrahlter Schutt seine Hallen, in denen die Unholde hausen, die Euer Volk vertrieben haben."},sec={{t="Ein überranntes Zuhause",b="Hinter den Dekontaminationskammern der Clean Zone beherbergte der Schlafsaal einst Gnomeregans Erfinder, Arbeiter und Familien. Als Hochtüftler Mekkatorque die Notfall-Strahlungsentlüftungen öffnete, um die eindringenden Troggs zu bekämpfen, wurde dieser dicht bevölkerte Teil der Stadt zur Falle. In seinen Gemeinschaftshallen und Wohnquartieren ist kein gnomisches Leben mehr zu finden. Mutierte Troggs gedeihen in der radioaktiven Luft. Um die tiefer gelegene Hall of Gears zu erreichen, müssen sich Reisende durch dieses Zeugnis der Katastrophe kämpfen."},{t="Terminals der Lochkartenmaschinen",b="Obwohl die Wohnquartiere verlassen sind, funktionieren Gnomeregans Verwaltungsmaschinen noch immer. Die Terminals der Matrix-Lochkartenmaschinen 3005-B verarbeiten Sicherheitslochkarten. Die Karten öffnen Datenterminals mit höherer Sicherheitsstufe tiefer in der Stadt, wo wichtige Aufzeichnungen aus der Zeit der Flucht der Gnome verblieben sind."}},faq={{q="Wozu diente der Schlafsaal vor dem Fall?",a="Der Schlafsaal beherbergte Gnomeregans Erfinder, Arbeiter und Familien. Nahe den Industrie- und Verwaltungssektoren konnten die Bewohner ihre Arbeitsplätze und Schlafkojen erreichen, bevor giftige Strahlung die unteren Korridore flutete.",al={"was ist der schlafsaal","zweck des schlafsaals","wer lebte hier"}},{q="Warum ist der Schlafsaal von Troggs befallen?",a="Als Troggs von unten in die Stadt eindrangen, flutete Hochtüftler Mekkatorque sie mit giftigem Gas, um die Eindringlinge zu töten. Stattdessen ließ die Strahlung die Überlebenden mutieren, machte sie noch grausamer und völlig unempfindlich gegen die Strahlung in den Wohnblöcken.",al={"warum sind hier troggs","troggbefall im schlafsaal","verstrahlte troggs"}},{q="Wohin führt der Schlafsaal?",a="Der Schlafsaal liegt hinter den desinfizierten Luftschleusen der Clean Zone und verbindet die oberen Ebenen mit der tiefer gelegenen Hall of Gears. Jeder, der tiefer nach Gnomeregan vordringen will, muss ihn durchqueren.",al={"ausgänge des schlafsaals","wohin vom schlafsaal aus","verbindungen des schlafsaals"}},{q="Was sind die Matrix-Lochkartenmaschinen, die hier stehen?",a="Die Terminals der Matrix-Lochkartenmaschinen 3005-B verarbeiten Sicherheitslochkarten. Die codierten Karten öffnen Terminals mit höherer Sicherheitsstufe und helfen, wichtige Daten zu bergen, die in Gnomeregan zurückgelassen wurden.",al={"lochkartenmaschine","matrix-lochkartenmaschine 3005-b","lochkarten"}}},fx={a2c6e6cc={q="Was ist der Schlafsaal?",a="Der Schlafsaal ist eine Wohnzone innerhalb von Gnomeregan, die gleich hinter der Clean Zone und der oberen Ebene der Hall of Gears liegt. Einst ein geschäftiges, dicht gedrängtes Viertel, in dem viele der Gnome-Bürger der Stadt lebten und ruhten, steht es nun verlassen da und verbindet sich nach unten mit der unteren Ebene der Hall of Gears.",al={"was ist der schlafsaal","schlafsaal gnomeregan","über den schlafsaal"}},["47f03a0e"]={q="Was ist mit dem Schlafsaal geschehen?",a="Als die Trogg-Invasion Gnomeregan überwältigte und giftige Strahlung die unteren Korridore flutete, ging der Schlafsaal vollständig verloren. Seine ansässigen Gnome wurden entweder getötet, flohen nach Eisenschmiede oder wurden durch den Fallout mutiert, wodurch sie ihre privaten Quartiere dem Verfall überließen, während unterirdische Schrecken die Kontrolle übernahmen.",al={"was geschah im schlafsaal","fall des schlafsaals","geschichte des schlafsaals"}},["9c6fea46"]={q="Warum wurde der Schlafsaal verlassen?",a="Der Schlafsaal wurde während des katastrophalen Falls der Stadt verlassen. Als giftige Strahlung den Sektor durchdrang, um den unterirdischen Trogg-Ausbruch zu stoppen, wurden die Wohnquartiere für normale Gnome unbewohnbar und verwandelten die einst gemütlichen Schlafsäle in eine vergiftete Ruine.",al={"warum ist der schlafsaal zerstört","schlafsaal verlassen","warum verließen gnome den schlafsaal"}},["410e0de9"]={q="Wer lebt jetzt im Schlafsaal?",a="Es sind keine zivilisierten Bürger mehr übrig. Die Quartiere wurden vollständig von verstrahlten Troggs überrannt, bösartigen unterirdischen Kreaturen, die durch den Fallout, der Gnomeregan während seiner letzten Stunden erstickte, deformiert wurden.",al={"wer kontrolliert den schlafsaal","bewohner des schlafsaals","wer lebt im schlafsaal"}},["33cb3e50"]={q="Ist der Schlafsaal gefährlich?",a="Es ist äußerst gefährlich. Jeder, der sich über die Sicherheit der nahegelegenen Clean Zone hinauswagt, tritt direkt in den Pfad der verstrahlten Troggs, die die schmalen Hallen bevölkern und Eindringlinge inmitten der anhaltenden toxischen Kontamination bei Sichtkontakt angreifen.",al={"gefahr im schlafsaal","ist der schlafsaal sicher","bedrohungen im schlafsaal"}},["68138d13"]={q="Warum heißt dieser Bereich Schlafsaal?",a="Er trägt den wörtlichen Namen seiner ursprünglichen Funktion: die gemeinschaftlichen Schlaf- und Wohnquartiere für einen großen Teil der arbeitenden Bevölkerung von Gnomeregan vor dem Fall.",al={"warum heißt er schlafsaal","bedeutung des namens schlafsaal","ursprung des schlafsaals"}}},fp="9,202,14.473.0,21.278.0,48.218.0,42.233.0,30.177.0,52.173.0"}
P.entries["subzone:drag"] = {n="Drag",s="In Orgrimmar zieht der Drag Händler und Handwerker zwischen drei Täler. Seine schattige Schlucht aus rotem Fels führt auch hinab zur Kluft der Schatten.",h="In Orgrimmar zieht der Drag Händler und Handwerker zwischen drei Täler.",kw={"alchemie","die kluft der schatten","drag","lederverarbeitung","nogg","orgrimmar","bergungsgut","schneiderei","der drag"},ang={["faction:Horde"]="Auf Eurer Reise durch Orgrimmar durchquert Ihr den Drag, der das militärische Herz der Hauptstadt mit ihren gemeinschaftlichen und mystischen Vierteln verbindet.",["profession:Engineering"]="Im Drag vermitteln Goblintüftler in Nogg’s Machine Shop der Horde Baupläne, den Umgang mit Sprengstoffen und Fachwissen der Ingenieurskunst."},sec={{t="Die Straße der Handwerker",b="Der Drag verläuft zwischen Orgrimmars roten Schluchtwänden und ist voller Handwerker und Händler. Anders als im Tal der Stärke, wo sich Soldaten sammeln und Befehle empfangen, spielt sich hier das tägliche Stadtleben ab. Hohe Klippen und Felle spenden der Straße Schatten. Gerbbottiche, alchemistische Kessel und die Zahnräder der Tüftler erfüllen sie mit Geräuschen und Gerüchen. Handwerker üben ihr Gewerbe aus und unterrichten aufstrebende Abenteurer, von Lederverarbeitern und Schneidern bis zu den Goblins in Nogg’s Machine Shop."},{t="Kreuzung von Schatten und Handwerk",b="Ladenfronten und Bergungshäuser säumen den Drag neben dem bewachten Eingang zur unterirdischen Kluft der Schatten. Ehrliche Händler teilen sich die Straße mit Schamanen auf dem Weg zum Valley of Wisdom und mit Anwendern dunkler Künste. Unter den düsteren, staubigen Überhängen der Schlucht kreuzen sich ihre Wege."}},faq={{q="Wozu dient der Drag in Orgrimmar?",a="Der Drag ist Orgrimmars wichtigstes Viertel für Einkäufe und Handel. Lehrer und Bedarfshändler versorgen Berufe wie Alchemie, Schneiderei, Lederverarbeitung, Kürschnerei, Verzauberkunst und Ingenieurskunst und bieten außerdem allgemeines Bergungsgut und Handelswaren an.",al={"zweck des drag","was ist der drag","welche geschäfte gibt es im drag"}},{q="Wohin führt der Drag?",a="Der Drag verbindet das Tal der Stärke im Süden mit dem Tal der Ehre im Nordosten, mit Wegen zum Valley of Wisdom. Der Eingang zu den düsteren Höhlen der Kluft der Schatten liegt an der westlichen Felswand.",al={"verbindungen des drag","weg zur kluft der schatten","wohin führt der drag"}},{q="Wer ist Nogg?",a="Nogg ist ein Gobliningenieur, der Nogg’s Machine Shop am Drag betreibt. Er bildet Ingenieure aus und versorgt Mitglieder der Horde mit Gerätschaften.",al={"nogg’s machine shop","wer betreibt die werkstatt"}},{q="Befinden sich alle Berufslehrer im Drag?",a="Die meisten Handwerks- und Sammelberufe haben Geschäfte auf den unteren und oberen Felsabsätzen des Drag. Die Schmiede und Bergleute der Stadt arbeiten in den feurigen Schmieden des Tals der Ehre.",al={"wo sind lehrer in orgrimmar","erste-hilfe-lehrer im drag"}}},fx={b51cb4ea={q="Was ist der Drag?",a="Der Drag ist eine geschäftige, im Schatten liegende Schluchtgasse in Orgrimmar, die das Tal der Stärke mit dem Tal der Weisheit verbindet. Unter den hoch aufragenden roten Klippen gelegen, dient er als das wichtigste Handels- und Handwerksviertel der Hauptstadt, vollgepackt mit Händlern, Kunsthandwerkern und Ausbildern, die ihre Berufe mit Abenteurern und Bürgern gleichermaßen teilen.",al={"was ist der drag","drag orgrimmar","über den drag"}},ba842caf={q="Was ist die Geschichte des Drag?",a="In die tiefen Schluchten von Durotar zusammen mit dem Rest von Orgrimmar gehauen, wurde der Drag als zentrale Handelsstraße besiedelt, als Thralls Horde die Stadt gründete. An die Schluchtwände in einem schattigen, rauen Teil der Hauptstadt grenzend, füllte er sich schnell mit Werkstätten, Schrotthändlern und Verkäufern, die begierig darauf waren, die neue Nation zu versorgen.",al={"geschichte des drag","wie wurde der drag gegründet","drag historie"}},["376c9470"]={q="Wer lebt und arbeitet im Drag?",a="Eine große Vielfalt an Handwerkern, Ladenbesitzern und Arbeitern hat hier ihr Zuhause und ihren Lebensunterhalt. Zu den bemerkenswerten Eigentümern gehören Nogg, der seine Ingenieurswerkstatt betreibt, Yelmak, der Tränke braut, Magar, der Stoffwaren produziert, und die Familie Droffers, die sich um Bergungsgut kümmert.",al={"wer lebt im drag","bewohner des drag","wer betreibt den drag"}},["5a953074"]={q="Ist der Drag gefährlich?",a="Obwohl der Drag in einem schattigen und rau gehauenen Schluchtkorridor liegt, ist er ein geschützter Teil von Orgrimmar und für Mitglieder der Horde nicht grundsätzlich gefährlich. Er liegt jedoch in unmittelbarer Nähe zu den dunklen Tunneln der Kluft, wo Hexenmeister und schurkische Elemente Künste praktizieren, die im Sonnenlicht missbilligt werden.",al={"ist der drag sicher","ist der drag gefährlich","gefahr im drag"}}},fp="4,141,26.464.0,33.291.0,39.234.0,25.224.0,12.138.0,48.179.0"}
P.entries["subzone:dragonmaw-gates"] = {n="Tore des Drachenmals",s="An den Toren des Drachenmals sperren schwere Befestigungen die Straße aus dem östlichen Sumpfland. Sie bewachen den Aufstieg nach Grim Batol, einer Bergfestung inmitten verfluchter Zwergenruinen.",h="An den Toren des Drachenmals sperren schwere Befestigungen die Straße aus dem östlichen Sumpfland.",kw={"axtroz","dragonmaw-klan","tore des drachenmals","grim batol","gebirgspass","red dragonflight","sumpfland"},ang={["faction:Alliance"]="Als Mitglied der Allianz beobachtet Ihr die Tore wachsam. Alles, was von der Höhenstraße herabkommt, bedroht die Stabilität des gesamten Sumpflands.",["race:Dwarf"]="Als Zwerg seht Ihr in den Toren die versiegelte Schwelle zu Grim Batol, der angestammten Heimat Eures Volkes. Die Zwerge verließen sie nach dem War of the Three Hammers, und die Dragonmaw-Orcs entweihten sie später."},sec={{t="Wächter von Grim Batol",b="Die Tore des Drachenmals versperren die gewundene Straße durch die schroffen Gipfel im östlichen Sumpfland. Die Dragonmaw-Orcs hielten Grim Batol während des Zweiten Krieges, und die Tore tragen ihren Namen. Die Straße bleibt befestigt, doch der Aufstieg ist noch immer gefährlich. Mächtige Jungdrachen suchen den Pass heim, und düstere Erinnerungen an die dunkle Geschichte des Klans verweilen in den Bergen."},{t="Eine umkämpfte Schwelle",b="Die Dragonmaw-Orcs wurden nach der Zerstörung der Demon Soul geschlagen und zerstreut. Doch der Bergpfad bleibt gefährlich. Mächtige rote Drachen wurden dabei beobachtet, wie sie die gewundenen Hänge und Felsvorsprünge rund um die Tore bewachen. Monströse Jungdrachen und Überreste des Dragonmaw-Klans lauern noch immer in den nahen Hügeln, während die Tore Reisenden den Weg versperren, die den Aufstieg wagen."}},faq={{q="Wohin führen die Tore des Drachenmals?",a="Die Tore versperren den gewundenen Bergpfad, der vom Sumpfland nach Osten führt, hinein nach Grim Batol und in die umliegenden Höhen.",al={"pfad hinter den toren des drachenmals","was liegt hinter den toren des drachenmals","straße hinter den toren"}},{q="Warum heißen sie Tore des Drachenmals?",a="Die Tore sind nach den Dragonmaw-Orcs benannt, die Grim Batol während des Zweiten Krieges besetzten und mit finsterer Zauberei rote Drachen versklavten.",al={"warum tore des drachenmals","name der tore des drachenmals","dragonmaw-orcs sumpfland"}},{q="Können Reisende die Tore passieren?",a="Die gewaltigen Tore sind fest verschlossen und schwer bewacht und versperren den gewöhnlichen Durchgang ins Hochgebirge.",al={"lassen sich die tore des drachenmals öffnen","durch die tore des drachenmals gelangen"}},{q="Wer bewacht die Straße rund um die Tore?",a="Wilde rote Drachkin und Jungdrachen suchen die Straße und die nahen Pässe heim. Versprengte Orcs und andere finstere Bedrohungen halten sich an den Berghängen.",al={"wer ist an den toren des drachenmals","drachen an den toren des drachenmals","axtroz tore des drachenmals"}}},fx={["3dd629b0"]={q="Wie gefährlich sind die Tore des Drachenmals?",a="Sie sind außerordentlich gefährlich. Die roten Drachen, die die Straße bewachen und von mächtigen Drachen wie Axtroz angeführt werden, heißen sterbliche Eindringlinge in der Nähe des Zugangs zu Grim Batol nicht willkommen. Jenseits der Drachen suchen feindselige Orcs des Drachenmals noch immer die umliegenden Hügel des Sumpflandes heim, was jeden Vorstoß in Richtung der Tore zu einer gefahrvollen Reise für Reisende macht.",al={"sind die tore des drachenmals gefährlich","gefahr an den toren des drachenmals","sind die tore des drachenmals sicher"}},fb3392df={q="Was ist an den Toren des Drachenmals geschehen?",a="Diese imposanten Tore wurden von den Orcs des Drachenmals befestigt, als sie die Bergfestung Grim Batol hielten und während des Zweiten Krieges den roten Drachenschwarm kontrollierten. Nachdem die Orcs besiegt und vertrieben worden waren, kamen rote Drachen unter der Führung des Drachen Axtroz, um die Zugänge zum Berg zu bewachen.",al={"geschichte der tore des drachenmals","was geschah an den toren des drachenmals","vergangenheit der tore des drachenmals"}}},fp="15,178,23.343.0,21.358.0,34.117.0,40.142.0,37.103.0,37.135.0"}
P.entries["subzone:dragonmurk"] = {n="Das Drachendüster",s="Im Süden der Düstermarschen wimmelt das Drachendüster von schwarzer Drachenbrut und Schlüpflingen. Uralte Ogerruinen und versengte Höhlen säumen diesen gefährlichen Landstrich, den Onyxias Brut beherrscht.",h="Im Süden der Düstermarschen wimmelt das Drachendüster von schwarzer Drachenbrut und Schlüpflingen.",kw={"schwarzer drachenschwarm","der flammenbau","das drachendüster","drachenbrut","düstermarschen","onyxia","die stonemaul ruinen","welpen"},ang={["faction:Alliance"]="Theramore behält das Drachendüster genau im Auge. Eine ungehindert wachsende schwarze Drachenbrut so nahe an der Festung könnte Unheil bringen.",["faction:Horde"]="Schwarze Drachen vertrieben die Stonemaul-Oger aus ihrem Dorf. Sie bedrohen weiterhin Expeditionen der Horde, die tief in den Sumpf vordringen."},sec={{t="Eine Brut im Sumpf",b="Im Süden der Düstermarschen wimmelt es auf nassen Pfaden und im zähen Schlamm von schwarzen Wyrmkin, Drachenbrut und hungrigen Welpen. Der Schwarze Drachenschwarm beherrscht das Land um das Drachendüster. Stonemaul, ein zerstörtes Dorf, und der versengte Flammenbau stehen beide unter seiner Kontrolle."},{t="Wacht über die Brutmutter",b="Onyxias schwarze Drachenbrut bevölkert den Morast und bewacht ihr Gelege. Das südliche Dustwallow ist Onyxias wichtigster Nistplatz in Kalimdor. Sie ist die Tochter von Deathwing. Ihre Wyrmkin patrouillieren durch den Sumpf und vernichten Eindringlinge, um die Eier vor Theramores Spähern und den nahen Lagern der Horde zu schützen."}},faq={{q="Was ist das Drachendüster?",a="Das Drachendüster ist ein Landstrich im Süden der Düstermarschen, der von Welpen, Drakes und Drachenbrut des Schwarzen Drachenschwarms überrannt wurde.",al={"was ist das drachendüster","wo liegt das drachendüster","drachendüster lage"}},{q="Warum gibt es hier so viele schwarze Drachen?",a="Onyxias Hort liegt im Süden der Düstermarschen, wo ihre Nachkommen und Diener nisten, heranwachsen und Bedrohungen von außen fernhalten.",al={"warum schwarze drachen in dustwallow","wer führt die drachen hier an","onyxia drachen dustwallow"}},{q="Welche markanten Orte liegen nahe dem Drachendüster?",a="Der Flammenbau und die Stonemaul Ruinen liegen im Drachendüster und seiner Umgebung. Schwarze Drachenbrut hält beide besetzt.",al={"drachendüster markante orte","was liegt nahe dem drachendüster","orte um das drachendüster"}},{q="Ist das Drachendüster für Reisende sicher?",a="Nein. Feindselige, aggressive Drachkin machen das Drachendüster zu einem der gefährlichsten Wildnisgebiete im südlichen Kalimdor.",al={"ist das drachendüster gefährlich","kann man durch das drachendüster gehen"}}},fp="10,172,18.255.0,24.281.1,19.115.0,41.126.0,41.101.0,33.110.0"}
P.entries["subzone:dreadmaul-post"] = {n="Schreckensfelsposten",s="Oger halten den Schreckensfelsposten nahe dem Dunklen Portal. Der Dreadmaulclan errichtete diese befestigte Siedlung in den Verwüsteten Landen, nachdem er aus Draenor herübergekommen war. Reisende müssen sich den Ogern und den unwirtlichen Einöden rund um ihr Lager stellen.",h="Oger halten den Schreckensfelsposten nahe dem Dunklen Portal.",kw={"verwüstete lande","das dunkle portal","dreadmaul","schreckensfelsposten","ogerhügel","oger"},ang={["faction:Alliance"]="Für Späher der Allianz, die das Dunkle Portal beobachten, sind die Dreadmauloger eine gewalttätige, fest verschanzte Gefahr. Ihre Anwesenheit erschwert Patrouillen durch die südlichen Ausläufer des Kontinents.",["faction:Horde"]="Die Dreadmaul kämpften einst an der Seite der Old Horde, doch wilde Clans wie ihrer haben mit Thralls neuer Ordnung gebrochen. Sie betrachten jeden Reisenden als feindlichen Eindringling."},sec={{t="Überreste von Draenor",b="Der Dreadmaulclan kam vor Jahrzehnten mit der Horde nach Azeroth. Nahe dem Dunklen Portal errichteten sie grobe Steinhügel und Erdwälle in den roten Einöden der Verwüsteten Lande. Der Schreckensfelsposten ist einer ihrer wichtigsten Außenposten. Von hier aus halten die Oger das Ödland und geraten mit umherstreifenden Bestien und Reisenden aneinander, die sich ihrem Gebiet nähern."}},faq={{q="Wer lebt am Schreckensfelsposten?",a="Der Ogerclan der Dreadmaul lebt am Schreckensfelsposten. Sie kamen während der Kriege aus Draenor durch das Dunkle Portal und fanden zwischen den trostlosen Felsen der Verwüsteten Lande eine dauerhafte Heimat.",al={"wer ist am schreckensfelsposten","bewohner schreckensfelsposten","dreadmauloger"}},{q="Warum sind die Oger noch immer in den Verwüsteten Landen?",a="Nachdem die Old Horde gefallen und das Dunkle Portal versiegelt worden war, verstreuten sich viele Oger über Azeroth. Der Dreadmaulclan blieb nahe dem Ort seiner Ankunft und machte die verwüsteten Einöden um den ruhenden Riss zu seiner Heimat.",al={"warum dreadmaul hier","oger verwüstete lande","warum oger nahe dem portal"}},{q="Wer durchstreift sonst noch die Gegend nahe dem Posten?",a="Neben den Ogern durchstreifen Skorpide und Basilisken die rote Wüste nahe dem Schreckensfelsposten.",al={"draenei verwüstete lande","wer ist nahe dreadmaul","kreaturen schreckensfelsposten"}}},fp="14,214,19.333.0,28.182.0,45.223.0,40.85.0"}
P.entries["subzone:dreadmaul-rock"] = {n="Schreckensfels",s="Die Oger der Firegut leben in den Höhlen und Erdhügeln des Schreckensfels in der Brennenden Steppe.",h="Die Oger der Firegut leben in den Höhlen und Erdhügeln des Schreckensfels in der Brennenden Steppe.",kw={"brennende steppe","dreadmaul gipfel","schreckensfels","oger der firegut","ogerhügel"},ang={["faction:Alliance"]="Für die Streitkräfte der Allianz, die die Grenzpässe vom Rotkammgebirge aus bewachen, sind die aggressiven Oger des Schreckensfels eine ständige, brutale Gefahr gleich jenseits des nördlichen Kamms.",["faction:Horde"]="Reisende der Horde, die die Steppe zum Schwarzfels durchqueren, müssen sich am Schreckensfels vorsichtig bewegen und dürfen den auf sein Revier bedachten Clan der Firegut nicht erzürnen."},sec={{t="Bollwerk der Firegut",b="Über den verbrannten Ebenen der Brennenden Steppe halten die Oger der Firegut die Klippen und Höhlen des Schreckensfels besetzt. Die gewaltige Steinformation ist von einem labyrinthischen Höhlensystem durchzogen. Obwohl sein Name eine mögliche Verbindung zu den Ogern der Dreadmaul aus den Verwüsteten Landen nahelegt, beherrscht der Clan der Firegut den Fels.\n\nSie nutzen seine hoch gelegenen Pfade, Klippen und Erdhügel im Inneren als befestigtes Lager. Von dort aus beherrschen sie das umliegende Ödland und bedrohen jeden, der die nördlichen Hänge zur Schwarzfelsspitze überquert."}},faq={{q="Wer lebt am Schreckensfels?",a="Die Oger der Firegut nutzen den Schreckensfels als ihren Hauptstützpunkt. Sie bewohnen die äußeren Klippenpfade und das weit verzweigte Höhlensystem im Inneren des Felsens.",al={"wer ist am schreckensfels","schreckensfels gegner","welche oger sind am schreckensfels"}},{q="Warum heißt er Schreckensfels, wenn hier Oger der Firegut leben?",a="Der Clan der Firegut beherrscht den Gipfel, doch der Name deutet darauf hin, dass der Fels einst dem Ogerclan der Dreadmaul gehört haben könnte, der im Süden in den Verwüsteten Landen stark vertreten ist.",al={"warum dreadmaul","dreadmaul oder firegut","verbindung zu dreadmaul-ogern"}},{q="Wie ist der Fels aufgebaut?",a="Steile Rampen winden sich den Fels hinauf, neben einem verschlungenen Höhlennetz im Inneren voller Ogerhügel und Behausungen.",al={"dreadmaul höhlen","dreadmaul gipfel aufbau","orientierung am schreckensfels"}},{q="Wo liegt der Schreckensfels?",a="Der Schreckensfels erhebt sich in der Brennenden Steppe, nördlich des Weges zum Rotkammgebirge und östlich des Schwarzfels.",al={"schreckensfels lage","wo ist der schreckensfels","ogerstützpunkt brennende steppe"}}},fp="14,106,25.506.0,28.139.0,58.175.0,36.108.0,32.124.0"}
P.entries["subzone:dreadmist-den"] = {n="Glutnebelbau",s="Kultisten der Burning Blade vollziehen ihre Riten unter dem Glutnebelgipfel im nördlichen Brachland. Roter Dunst erfüllt die Höhle, die ihnen als Dämonenschrein dient.",h="Kultisten der Burning Blade vollziehen ihre Riten unter dem Glutnebelgipfel im nördlichen Brachland.",kw={"brachland","burning blade","kultisten","demon seed","glutnebelbau","glutnebelgipfel","roter nebel"},ang={["class:Warlock"]="Als Hexenmeister könnten Euch die dämonischen Relikte und instabilen Teufelsenergien im Glutnebelbau sowie die dunklen Geheimnisse der Burning Blade anziehen.",["faction:Horde"]="Als Mitglied der Horde droht Euch Gefahr durch den Bau der Burning Blade, der über dem Brachland liegt. Seine Präsenz bedroht nahe Handelswege und Siedlungen und erfordert rasches Handeln von den Verteidigern der Horde."},sec={{t="Ein Bau finsterer Schatten",b="Der Glutnebelbau öffnet sich zwischen den zerklüfteten Hängen des Glutnebelgipfels. Kultisten der Burning Blade versammeln sich in seinem dunklen Heiligtum, wo dichter purpurroter Dampf die steinernen Tunnel in rotes Zwielicht taucht. Fernab der wachsamen Augen der Horde auf den Ebenen unterhalb vollzieht der Kult dämonische Riten und bewacht seine lästerlichen Relikte. Er plant, Verderbnis über Kalimdor zu verbreiten."},{t="Der Demon Seed",b="Tief im Glutnebelbau ruht der Demon Seed über dem Altar of Fire. Die Burning Blade schätzt das Artefakt wegen seiner Teufelsmacht, und es ist mit der Brennenden Legion verbunden. Ak'Zeloth bereitet einen Machtstein vor, um diese Verbindung zu stören. Späher der Horde und angehende Hexenmeister, die den Aktivitäten des Kults nachgehen, begegnen in der Höhle Gefahren, während sie ergründen, wie weit der dämonische Einfluss im Brachland reicht."}},faq={{q="Was ist der Glutnebelbau?",a="Der Glutnebelbau liegt unter dem Glutnebelgipfel im nördlichen Brachland. Kultisten der Burning Blade nutzen seine Höhlen als Enklave und als Ort für ihre Riten.",al={"glutnebelbau","was ist der glutnebelbau","brachland glutnebelhöhle"}},{q="Was verursacht den roten Nebel im Bau?",a="Roter Dunst hüllt den Glutnebelbau und den Gipfel darüber ein. Kultisten der Burning Blade vollziehen dort dämonische Riten, doch die genaue Ursache des Dunstes ist unbekannt.",al={"roter dunst glutnebel","purpurroter nebel brachland","roter nebel glutnebelbau"}},{q="Was ist der Demon Seed, der sich darin befindet?",a="Der Demon Seed ist ein dunkles Artefakt, das tief im Glutnebelbau verwahrt wird. Die Burning Blade schätzt ihn als mächtigen Fokus für Teufelsmagie.",al={"demon seed","was ist der demon seed","artefakt im glutnebelbau"}},{q="Warum interessiert sich die Horde für diese Höhle?",a="Die Horde fürchtet die Dämonenverehrung der Burning Blade und deren Bemühungen, die Horde in ganz Kalimdor zu untergraben. Eine Festung nahe dem Wegekreuz und Orgrimmar bedroht die Sicherheit des Brachlands.",al={"horde glutnebelbau","warum den glutnebelbau säubern","orks burning blade brachland"}}},fx={["43f375e7"]={q="Wer lebt im Glutnebelbau?",a="Die Höhle wird von Kultisten der Burning Blade besetzt. Diese dämonischen Anbeter nutzen die abgeschiedene Berghöhle als verstecktes Heiligtum und rituelle Zuflucht, während sie unter der ewigen Dämmerung leben, die durch die unnatürlichen roten Dämpfe im Inneren erzeugt wird.",al={"bewohner des glutnebelbaus","wer ist im glutnebelbau","wer kontrolliert den glutnebelbau"}},bcbe1c71={q="Ist der Glutnebelbau gefährlich?",a="Der Bau ist gefährlich, da die Kultisten der Burning Blade ihren dämonischen Schrein verteidigen. Ein roter Dunst verhüllt die Höhle und Eindringlinge müssen sich mit den feindseligen Bewohnern auseinandersetzen.",al={"gefahr im glutnebelbau","ist die glutnebelhöhle sicher","wie gefährlich ist der glutnebelbau"}},["5db705cc"]={q="Warum heißt es Glutnebelbau?",a="Die Höhle hat ihren Namen von dem dunkelroten Nebel, der das Innere ständig einhüllt. Dieser giftige Nebel sickert durch den Gipfel, taucht alles im Inneren in ein unheimliches Dämmerlicht und verleiht sowohl dem Berg als auch dem Bau darunter seinen finsteren Namen.",al={"warum glutnebelbau","ursprung des namens glutnebelbau","bedeutung von glutnebelbau"}}},fp="13,145,23.341.0,14.393.1,22.146.0,40.147.0,36.128.0,40.181.0"}
P.entries["subzone:dreadmist-peak"] = {n="Glutnebelgipfel",s="Am Glutnebelgipfel hängt ein roter Dunst über den Felsen nordwestlich des Wegekreuzes im Brachland. Der Kult der Burning Blade unterhält dort eine verborgene Zuflucht.",h="Am Glutnebelgipfel hängt ein roter Dunst über den Felsen nordwestlich des Wegekreuzes im Brachland.",kw={"brachland","burning blade","glutnebelbau","glutnebelgipfel","miasma","sarilus foulborne"},ang={["class:Druid"]="Als Taurendruide untersucht Ihr von Camp Taurajo aus die Wasserquellen des Glutnebelgipfels und sucht nach den unnatürlichen Giftstoffen, die Gazellen und Wildtiere der Ebenen vergiften.",["faction:Alliance"]="Als Agent der Allianz nahe dem Eschental verfolgt Ihr die Magie, die Wasserelementare verdirbt, bis zu Sarilus Foulborne, einem untoten Beschwörer auf dem Gipfel."},sec={{t="Ein Hort der Verderbnis",b="Roter Dunst verdunkelt den Himmel über dem Glutnebelgipfel. Auf dem Kamm und in den Senken darunter gewähren Kultisten der Burning Blade Hexenmeistern und Toxikologen Unterschlupf. Sie vergiften das Wasser in der Nähe und schmieden Ränke gegen die neuen Mächte, die Anspruch auf das zentrale Kalimdor erheben."},{t="Verflochtene Intrigen",b="Sarilus Foulborne, ein abtrünniger Magier der Verlassenen, hat auf dem Glutnebelgipfel sein Lager aufgeschlagen. Dort beugt er elementare Kräfte seinem Willen, um Wassergeister bis weit nach Norden ins Eschental zu verderben."}},faq={{q="Warum ist die Luft um den Glutnebelgipfel rot und neblig?",a="Niemand weiß, woher der rötlich-orangefarbene Nebel um den Glutnebelgipfel kommt. Er bedeckt die Pfade und den Glutnebelbau, wo Hexenmeister der Burning Blade ihre Rituale vollziehen.",al={"roter nebel glutnebel","orangefarbener nebel glutnebelgipfel","warum ist glutnebel rot"}},{q="Wer beherrscht den Glutnebelgipfel?",a="Der Kult der Burning Blade beherrscht den Glutnebelgipfel. Seine Mitglieder überwachen die Pfade und bewachen den Glutnebelbau unterhalb des Gipfels. Sarilus Foulborne, ein abtrünniger untoter Magier, hat sich ebenfalls auf dem Berg niedergelassen.",al={"wer lebt auf dem glutnebelgipfel","glutnebelgipfel feinde","burning blade glutnebel"}},{q="Wie erreicht Ihr den Glutnebelgipfel?",a="Folgt der Hauptstraße vom Wegekreuz nach Norden bis zur Weggabelung zum Eschental und zum Steinkrallengebirge. Wendet Euch nach Nordwesten zu dem aufragenden Felsen und steigt dann den Pfad an seiner Nordseite hinauf. Das ist der sicherste Weg zum Gipfel.",al={"weg zum glutnebelgipfel","glutnebelgipfel lage","glutnebel pfad"}}},fx={["225dd39b"]={q="Was ist der Glutnebelgipfel?",a="Der Glutnebelgipfel ist ein zerklüfteter, unheilvoller Berg, der sich nordwestlich des Wegekreuzes im nördlichen Brachland erhebt. Eingehüllt in einen unheimlichen rot-orangefarbenen Nebel, dient er als berüchtigter Stützpunkt für den finsteren Kult der Burning Blade. Seine Höhen verbergen tückische Höhlen wie den Glutnebelbau, in denen Hexenmeister und Kultisten abscheuliche Rituale durchführen, um die umliegende Savanne zu verheeren.",al={"was ist der glutnebelgipfel","lore des glutnebelgipfels","erzaehl mir vom glutnebelgipfel"}},["9aed69cf"]={q="Ist der Glutnebelgipfel gefährlich?",a="Er ist außergewöhnlich gefährlich. Auf dem Berg wimmelt es von fanatischen Akolythen, Schlägern, Toxikologen und dunklen Beschwörern der Burning Blade, die ihre Ritualstätten erbittert bewachen. Abgesehen von den feindseligen Kultisten wird vermutet, dass das Wasser des Gipfels die Tierwelt des darunter liegenden Brachlands vergiftet.",al={"ist der glutnebelgipfel gefaehrlich","bedrohungen auf dem glutnebelgipfel","gefahren des glutnebelgipfels"}}},fp="14,146,19.227.0,24.158.1,51.167.0,28.178.0,32.207.0"}
P.entries["subzone:dreadmurk-shore"] = {n="Dreadmurk Shore",s="Nebel und Murlocs der Mirefin gefährden Reisende an Dreadmurk Shore, zwischen der Insel Theramore und dem Brachland. Seebestien durchstreifen das Wasser und machen diese Küste zu einer gefährlichen Passage durch die Düstermarschen.",h="Nebel und Murlocs der Mirefin gefährden Reisende an Dreadmurk Shore, zwischen der Insel Theramore und dem...",kw={"insel alcaz","defias","dreadmurk shore","düstermarschen","mirefin","murloc","schiffbruch","theramore"},ang={["class:Rogue"]="Als Schurke könnt Ihr die Spur geheimer Fracht der Defias durch abgelegene Lager und versunkene Wracks verfolgen. Oder Ihr könnt Euch an den gewalttätigen Wachen der Mirefin vorbeischleichen.",["faction:Alliance"]="Überlebende der Bruderschaft der Defias nahe Theramore deuten auf Verschwörungen hin, die über Westfall hinausreichen. Sie bedrohen die Stabilität der Allianz in Kalimdor."},sec={{t="Eine tückische Küste",b="Am nordöstlichen Rand der Düstermarschen liegen schlammige Untiefen, Gezeitentümpel und neblige Inseln zwischen der Insel Theramore und der Feste Northwatch. Der Stamm der Mirefin beherrscht diese Küste. Diese territorialen Murlocs greifen Reisende an, die sich ihren Dörfern nähern. Meeresschildkröten und andere Wasserraubtiere durchstreifen die seichten Gewässer, während aus den Sümpfen im Landesinneren Gefahr droht."},{t="Infiltratoren der Defias",b="Ein Schiff der Bruderschaft der Defias erlitt zwischen Dreadmurk Shore und der Insel Alcaz Schiffbruch. Gesetzlose wurden an den Strand und auf die kleinen Inseln gespült. Diese menschlichen Verbrecher kamen aus den Östlichen Königreichen und halten sich nun nahe Lady Jaina Prachtmeers Festung auf. Ihre Anwesenheit zieht Theramores Aufmerksamkeit auf sich und bedroht das fragile Machtgefüge in der gesamten Bucht."}},faq={{q="Wo liegt Dreadmurk Shore?",a="Dreadmurk Shore erstreckt sich entlang der nordöstlichen Küste der Düstermarschen zum großen Meer hin, zwischen der Insel Theramore und dem Brachland, nahe der Feste Northwatch.",al={"dreadmurk shore lage","wo liegt dreadmurk shore"}},{q="Warum gibt es Banditen der Defias an dieser Küste?",a="Ein Schiff der Bruderschaft der Defias erlitt vor Kurzem vor der Küste zwischen Dreadmurk Shore und der Insel Alcaz Schiffbruch. Überlebende erreichten den abgelegenen Strand und die Felsvorsprünge, wo sie provisorische Lager errichteten und versuchten, ihre versunkene Fracht zu bergen.",al={"defias in den düstermarschen","warum sind die defias hier","schiffbrüchige defias"}},{q="Wer sind die Murlocs, die am Strand leben?",a="Der Murlocstamm der Mirefin lebt entlang der Küste. Seine Mitglieder errichteten einfache Fischersiedlungen auf den Sandbänken und felsigen Inselchen und verteidigen ihr Gebiet erbittert gegen Patrouillen aus Theramore und schiffbrüchige Eindringlinge.",al={"murlocs der mirefin","dreadmurk shore murlocs"}},{q="Wird Dreadmurk Shore von Theramore kontrolliert?",a="Theramore beansprucht die Herrschaft über die Ländereien rund um die Insel, doch Dreadmurk Shore bleibt gesetzlos. Wilde, sumpfige Untiefen sowie dort lebende Murlocs und Wegelagerer hindern Lady Jaina Prachtmeers Wachen daran, regelmäßig zu patrouillieren.",al={"wem gehört dreadmurk shore","gehört dreadmurk shore zur allianz"}}},fp="15,194,19.351.0,19.333.1,33.150.0,43.221.0,43.211.0,43.213.0"}
P.entries["subzone:dream-bough"] = {n="Traum-Geäst",s="Auf einer Insel im nördlichen Feralas bewachen grüne Drachen das Traum-Geäst. Der uralte Große Baum birgt einen Zugang zum Smaragdgrünen Traum.",h="Auf einer Insel im nördlichen Feralas bewachen grüne Drachen das Traum-Geäst.",kw={"traum-geäst","smaragdgrüner traum","feralas","großer baum","grüner drachenschwarm","jademirsee"},ang={["class:Druid"]="Als Druide kennt Ihr das Traum-Geäst als heiligen Boden, eine lebendige Brücke zwischen Azeroths Wildnis und dem Smaragdgrünen Traum, den Euer Orden hütet.",["race:NightElf"]="Als Nachtelf könnt Ihr in diesem großen Baum die uralte Pflicht Eures Volkes erkennen, die Natur zu pflegen und zu verteidigen."},sec={{t="Der Große Baum von Jademir",b="Das Traum-Geäst ragt auf einer Insel im Jademirsee über den Wald empor. Es ist der größte Baum im nördlichen Feralas. In seinem Stamm öffnet sich ein natürliches Portal, das direkt in den ungezähmten Smaragdgrünen Traum führt."},{t="Die smaragdgrünen Wächter",b="Der Grüne Drachenschwarm bewacht das Traum-Geäst und den Zugang in seinem Stamm. Drachkin und Drachen patrouillieren an den Ufern des Sees und auf den Wegen zum großen Baum. Druiden kommen zur Einkehr und zum Schlummer, während sie zwischen den Welten wandeln. Nur wenige ungebetene Reisende werden nahe dieser Schwelle geduldet, also nähert Euch mit Bedacht."}},faq={{q="Was ist das Traum-Geäst?",a="Das Traum-Geäst ist ein gewaltiger Großer Baum auf einer Insel im Jademirsee im nördlichen Feralas. Ein Zugang in seinem Stamm führt direkt in den Smaragdgrünen Traum.",al={"traum-geäst baum","was ist das traum-geäst","jademirsee baum"}},{q="Wer hat das Traum-Geäst gepflanzt?",a="Keine Überlieferung aus diesem Zeitalter hält fest, wer das Traum-Geäst gepflanzt hat. Der Große Baum birgt einen Zugang zum Smaragdgrünen Traum, und der Grüne Drachenschwarm wacht darüber.",al={"wer ließ das traum-geäst wachsen","ursprung des traum-geästs","staghelm baum"}},{q="Warum gibt es hier grüne Drachen?",a="Der Grüne Drachenschwarm bewacht den Smaragdgrünen Traum. Da sich im Stamm des Traum-Geästs ein direkter Zugang öffnet, halten Drachen und ihre Artgenossen Wache, um ihn vor Eindringlingen zu schützen.",al={"grüner drachenschwarm traum-geäst","drachen am jademirsee"}},{q="Können Spieler das Portal zum Smaragdgrünen Traum betreten?",a="Das Portal im Stamm des Traum-Geästs führt in den Smaragdgrünen Traum, doch sterbliche Abenteurer, die im körperlichen Reich wach sind, können es nicht durchschreiten. Mächtige schlafende Druiden und der Grüne Drachenschwarm wechseln ungehindert zwischen den Welten.",al={"portal des traum-geästs benutzen","smaragdgrünen traum in feralas betreten"}}},fp="11,132,25.195.0,20.304.0,24.148.0,28.159.0,33.166.0,52.206.0"}
P.entries["subzone:dreamer-s-rock"] = {n="Dreamer's Rock",s="Bei Dreamer's Rock schläft Naralex, während das Brachland noch immer auf Erneuerung wartet. Er kam, um das Land durch den Smaragdgrünen Traum wiederherzustellen, doch seine Verbindung nährt nun einen Alptraum.",h="Bei Dreamer's Rock schläft Naralex, während das Brachland noch immer auf Erneuerung wartet.",kw={"grabhügelbau","dreamer's rock","druids of the fang","smaragdgrüner traum","mutanus","naralex","die höhlen des wehklagens"},ang={["class:Druid"]="Als Druide erkennt Ihr die Gefahr in Naralex' Versuch, den Smaragdgrünen Traum zu erreichen. Edle Absichten können auf Schrecken treffen, die im Inneren schlummern.",["race:NightElf"]="Als Nachtelf findet Ihr unter dem dürren Brachland eine verderbte heilige Kammer, die einem Grabhügelbau gleicht. Naralex und seine Anhänger gingen fern von Kalimdors nördlichen Wäldern tragische Risiken ein."},sec={{t="Der Schlummer von Naralex",b="Im Herzen der Höhlen des Wehklagens liegt Naralex in einer Kammer, die einem nachtelfischen Grabhügelbau gleicht. Er versank in tiefe Trance, um die unterirdischen Quellen zu erreichen und den Smaragdgrünen Traum in den trockenen Boden des Brachlands zu leiten. Dunkle Mächte bemächtigten sich dieser Verbindung, und sein Alptraum verzerrt nun die Tierwelt der Kammer. Seine Anhänger wurden zu den giftigen Druids of the Fang, und schreckliche Verirrungen strömen in die wache Welt."},{t="Das Ritual des Erwachens",b="Ein überlebender Disciple of Naralex kann Dreamer's Rock erreichen und das Ritual des Erwachens vollziehen, sobald die Verderbnis der Fanglords beendet ist. Sobald der Gesang beginnt, entsendet Naralex' anhaltender Alptraum Monstrositäten, um seine Macht über dessen schlafenden Geist zu bewahren. Mutanus der Verschlinger ist der letzte Schrecken dieser seelischen Qual. Die Verirrung steigt aus den Tiefen des Unterbewusstseins des Träumers empor, um jene zu verschlingen, die ihn befreien wollen."}},faq={{q="Wer schläft bei Dreamer's Rock?",a="Naralex, ein Nachtelfendruide, schläft bei Dreamer's Rock. Er kam in die Höhlen des Wehklagens, um durch ihre unterirdischen Wasserläufe dem Brachland neues Leben zu schenken, doch Alpträume ergriffen seine Verbindung zum Smaragdgrünen Traum.",al={"schlafender elf","wer schläft hier","wer ist naralex","identität des träumers"}},{q="Warum heißt diese Kammer Dreamer's Rock?",a="Die Kammer verdankt ihren Namen Naralex, der als „der Träumer“ bekannt ist. Wie ein nachtelfischer Grabhügelbau birgt sie seinen ruhenden Körper, während sein Geist durch den Traum reist.",al={"warum dreamer's rock","namensbedeutung dreamer's rock","namensherkunft"}},{q="Was geschieht, wenn Ihr versucht, Naralex zu wecken?",a="Nachdem die Fanglords besiegt sind, versucht ein überlebender Disciple of Naralex, das Ritual des Erwachens zu vollziehen. Das Ritual ruft Schrecken aus Naralex' Alptraum hervor, die seinen schlafenden Geist bewachen.",al={"naralex wecken","ritual des disciple","naralex-ereignis"}},{q="Warum wurden Naralex' Anhänger feindselig?",a="Naralex' Alptraum verzerrte den Geist seiner Anhänger. Sie brachen ihre Cenarion-Gelübde, nahmen Schlangenaspekte an und wurden zu den Druids of the Fang, die den qualvollen, endlosen Schlaf ihres Meisters bewachen.",al={"ursprung der druids of the fang","warum sind die druiden böse","verderbte druiden"}}},fx={["8278540a"]={q="Was ist Dreamer's Rock?",a="Dreamer's Rock ist eine abgelegene natürliche Kammer tief in den Höhlen des Wehklagens, die hinter der Screaming Gully liegt. Sie fungiert wie ein traditioneller druidischer Bau und dient als Ruhestätte, an der der Nachtelf-Druide Naralex seinen tiefen Schlaf antrat, um den Smaragdgrünen Traum in das Brachland zu leiten.",al={"was ist dreamer's rock","kammer von dreamer's rock","wo ist dreamer's rock"}},["29a7d0a7"]={q="Was geschah bei Dreamer's Rock?",a="Naralex kam in diese Kammer, um den Smaragdgrünen Traum anzuzapfen und das grüne Leben in das trockene Brachland zurückzubringen. Stattdessen sickerte eine dunkle Verderbnis in seine Vision, die seinen edlen Schlaf in einen wachen Albtraum verwandelte. Die Schrecken aus seinem gestörten Geist manifestierten sich in Fleisch und Blut und brachen in die Höhle aus, wo sie seine Anhänger und die umliegenden Quellen korrumpierten.",al={"geschichte von dreamer's rock","was ist hier mit naralex passiert","wie ist dreamer's rock gefallen"}},["70f268b5"]={q="Ist Dreamer's Rock gefährlich?",a="Es ist außerordentlich gefährlich. Die Kammer liegt im Herzen der Verderbnis der Höhle, direkt dem verdrehten Unterbewusstsein von Naralex ausgesetzt. Jeder Versuch, den schlafenden Druiden zu stören oder zu wecken, lockt bösartige Albtraum-Ausgeburten hervor, die darauf erpicht sind, ihn gefangen zu halten, einschließlich des monströsen Schreckens, der als Mutanus der Verschlinger bekannt ist.",al={"wie gefährlich ist dreamer's rock","bedrohungen bei dreamer's rock","ist es bei dreamer's rock sicher"}}},fp="14,171,22.404.0,20.412.1,34.214.0,42.163.0,42.172.1,41.196.0"}
P.entries["subzone:drowned-reef"] = {n="Das versunkene Riff",s="Schiffen auf dem Weg zur Faldirbucht droht vor Arathis Südküste Gefahr durch das versunkene Riff. Darunter liegen uralte Ruinen, wo Daggerspine-Naga die Gezeiten der Bucht beherrschen zu können scheinen.",h="Schiffen auf dem Weg zur Faldirbucht droht vor Arathis Südküste Gefahr durch das versunkene Riff.",kw={"arathihochland","daggerspine","das versunkene riff","die faldirbucht","maiden's folly","naga","prinz nazjak","spirit of silberwald","versunkene ruinen"},ang={["race:NightElf"]="Als Nachtelf mögen Euch die überfluteten Hallen und verkalkten Edelsteine an das Reich der Kaldorei erinnern. Es versank vor zehntausend Jahren während der Great Sundering in Trümmern im Meer."},sec={{t="Ein Friedhof der Schiffe",b="Jenseits des versteckten Eingangs zur Faldirbucht ruhen zertrümmerte Schiffe unter den Wellen. Die Maiden's Folly und die Spirit of Silberwald liegen unter ihnen. Daggerspine-Naga bewohnen das Riff unter dem Befehl von Prinz Nazjak. Sie scheinen die Gezeiten der Bucht beherrschen zu können und könnten Besatzungen, die dort Schutz suchen, zum Verhängnis werden."},{t="Die versunkene Stadt",b="Tief unter dem Riff liegen die Ruinen einer uralten Elfenstadt. Taucht zwischen den versunkenen Gebäuden, und Ihr könnt zwischen den Überresten noch immer verkalkte Elfenedelsteine finden."}},faq={{q="Was ist das versunkene Riff?",a="Das versunkene Riff liegt vor der Südküste des Arathihochlands, unmittelbar vor der Faldirbucht. Seine Gewässer gefährden Schiffe, während uralte Ruinen unter dem Meer liegen.",al={"das versunkene riff","wo liegt das versunkene riff","arathi riff"}},{q="Warum liegen hier so viele versunkene Schiffe?",a="Schiffen droht in den Gewässern vor Arathis Südküste Gefahr. Daggerspine-Naga scheinen die Gezeiten der Bucht beherrschen zu können und gefährden so Besatzungen, die in der Faldirbucht Zuflucht suchen.",al={"warum sinken schiffe","versunkene schiffe arathi","maidens folly"}},{q="Wer beherrscht das versunkene Riff?",a="Daggerspine-Naga bewohnen unter dem Befehl von Prinz Nazjak die überfluteten Ruinen des versunkenen Riffs. Sie machen Jagd auf gestrandete Seeleute und bewachen ihr Unterwasserrevier.",al={"wer führt die naga hier an","prinz nazjak","daggerspine-naga arathi"}},{q="Was sind das für Ruinen unter dem Riff?",a="Die Ruinen unter dem versunkenen Riff gehören zu einer uralten Elfenstadt. Zwischen ihren versunkenen Gebäuden sind verkalkte Elfenedelsteine erhalten geblieben.",al={"unterwasserruinen arathi","elfenruinen versunkenes riff"}}},fp="12,166,20.318.0,15.158.0,25.171.0,40.170.0,30.155.0,46.124.0"}
P.entries["subzone:drowned-sacellum"] = {n="Drowned Sacellum",s="Am Eingang der Tiefschwarzen Grotte liegt das Drowned Sacellum unter der Küste. Zwischen Brackwasserbecken und Höhlenwurzeln hausen nun Murlocs und Makrura in seinem zerbrochenen Mauerwerk.",h="Am Eingang der Tiefschwarzen Grotte liegt das Drowned Sacellum unter der Küste.",kw={"bfd","tiefschwarze grotte","drowned sacellum","makrura","murloc","schrein","der zoramstrand"},ang={["class:Druid"]="Als Druide seht Ihr gewaltige Baumwurzeln, die von der Oberfläche durch die steinerne Decke dringen. Inmitten der verderbten unterirdischen Gewässer überdauert die Natur.",["race:NightElf"]="Als Nachtelf seht Ihr einen uralten Schrein, der im Salzwasser versunken und von Murlocs besetzt ist. Er erinnert an das Erbe der Kaldorei, das unter dem Zoramstrand verloren ging."},sec={{t="Ein versunkenes Heiligtum",b="Ihr überschreitet die Schwelle der Tiefschwarzen Grotte und betretet das Drowned Sacellum. Einst ein stiller Ort der Verehrung Elunes, liegt die Kapelle seit Langem eingestürzt unter Eschentals Küste. Brackwasserbecken bedecken ihre uralten Marmorbodenplatten. Seesterne klammern sich unter mächtigen Wurzeln an die Höhlendecke, während dunkle Irrwische durch die Finsternis flackern. Folgt dem zerbrochenen Steinpfad mit Bedacht, und er führt Euch tiefer in den Tempelkomplex zum Pool of Ask'ar."},{t="Unterschlupf der Aasfresser",b="Die Nachtelfenhüter verließen das Drowned Sacellum vor langer Zeit. Nun beherrschen Aasfresser von der Küste die Ruinen. Aggressive Murlocs und schwer gepanzerte Makrura teilen sich die trüben Gewässer und greifen jeden an, der ihre Nistplätze stört. Dunklere Bedrohungen durch Kulte lauern tiefer im Tempel. Diese Raubkreaturen bewachen den ersten Abschnitt der unterirdischen Ruinen."}},faq={{q="Wozu diente das Drowned Sacellum ursprünglich?",a="Vor dem Sundering war das Drowned Sacellum eine elfische Stätte der Verehrung Elunes. Es lag innerhalb des größeren unterirdischen Tempelkomplexes.",al={"drowned sacellum zweck","was ist das drowned sacellum","sacellum geschichte"}},{q="Welche Kreaturen bewohnen diesen Teil der Höhlen?",a="Wilde Murlocs und Makrura bewohnen die überfluteten Ruinen. In Brackwasserbecken und Nistspalten gedeihen sie prächtig.",al={"drowned sacellum gegner","was lebt im drowned sacellum","monster im drowned sacellum"}},{q="Wie gelangt Ihr durch das Drowned Sacellum?",a="Überquert die bröckelnden Plattformen und Säulen, die halb versunken aus dem Wasser ragen. Der Tunnel vor Euch führt zum Pool of Ask'ar.",al={"weg durch das drowned sacellum","drowned sacellum sprung","weg zum pool of ask'ar"}},{q="Woher kommt das Licht in der Höhle?",a="Dunkle Irrwische schweben zwischen dicken, verdrehten Wurzeln, die aus den Wäldern Eschentals darüber durch die Höhlendecke dringen. Sie spenden das schwache, unheimliche Licht der Höhle.",al={"warum leuchtet es","irrwische im drowned sacellum","drowned sacellum beleuchtung"}}},fx={b0803046={q="Was ist das Drowned Sacellum?",a="Das Drowned Sacellum ist ein verfallener, unterirdischer Schrein direkt innerhalb des Eingangs der Höhlen von Blackfathom. Es liegt halb untergetaucht in einem Becken aus dunklem Salzwasser und sein antikes Mauerwerk ist jetzt mit Seesternen verkrustet und von dicken Baumwurzeln erstickt, die von der Höhlendecke darüber herabhängen.",al={"was ist das drowned sacellum","geschichte des drowned sacellum","drowned sacellum blackfathom"}},["515e8f31"]={q="Warum heißt es Drowned Sacellum?",a="Ein Sacellum ist ein kleiner, geweihter Schrein oder eine Kapelle. Dieses besondere Heiligtum erhielt seinen düsteren Namen, weil das umliegende Meerwasser in die unterirdischen Höhlen gesickert ist, seine Kammern vollständig überflutet und seinen heiligen Altar teilweise unter Salzwasser zurückgelassen hat.",al={"warum drowned sacellum","namensbedeutung des drowned sacellum","ursprung des namens sacellum"}},["97f28086"]={q="Ist das Drowned Sacellum gefährlich?",a="Ja. Obwohl es einst ein heiliger Ort der Anbetung war, wird der überflutete Schrein heute von aggressiven Murlocs und gepanzerten Makrura heimgesucht. Sie leben zusammen inmitten der trüben Becken und zerstörten Säulen und greifen jeden bösartig an, der versucht, tiefer in die Höhlen von Blackfathom vorzudringen.",al={"ist das drowned sacellum sicher","bedrohungen am drowned sacellum","gefahr drowned sacellum"}}},fp="16,162,21.431.0,17.335.0,50.138.0,48.103.0,46.128.0,45.151.0"}
P.entries["subzone:dry-hills"] = {n="Die Trockenen Hügel",s="Harpyien des Hexenschwingenstamms beherrschen die grünen Trockenen Hügel über dem Brachland.",h="Harpyien des Hexenschwingenstamms beherrschen die grünen Trockenen Hügel über dem Brachland.",kw={"brachland","die trockenen hügel","goldstraße","harpyien","serena bloodfeather","steinkrallengebirge","hexenschwingenstamm"},ang={["class:Hunter"]="Das zerklüftete Hochland bietet ergiebige Jagdgründe. Flinke Hecklefanghyänen, räuberische Sunscale scytheclaws und wilde Harpyien streifen dort umher.",["faction:Horde"]="Harpyien des Hexenschwingenstamms nisten in den Trockenen Hügeln und bedrohen die nördlichen Handelsrouten, die das Wegekreuz mit dem Steinkrallengebirge und Eschental verbinden. Champions der Horde müssen ihre Zahl regelmäßig verringern."},sec={{t="Eine grüne Zuflucht für Harpyien",b="Die Trockenen Hügel erheben sich am nordwestlichen Rand des Brachlands unterhalb des Steinkrallengebirges. Ihre Hänge sind grüner als die trockenen Ebenen darunter, doch die Steilhänge bieten Reisenden kaum Sicherheit. Serena Bloodfeather führt die Harpyien des Hexenschwingenstamms von ihren Horsten entlang der Felsklippen aus. Ihre Plünderer stoßen auf Versorgungskarawanen herab, die auf der nördlichen Goldstraße unterwegs sind. Verlassene orkische Befestigungen und verfallene Belagerungsmaschinen verrotten im Gestrüpp."},{t="Bedrohung für das Wegekreuz",b="Harpyien des Hexenschwingenstamms greifen von den Hügeln aus an, um Handelsrouten auszuplündern und nahe Siedlungen zu drangsalieren. Deshalb setzt die Horde ein dauerhaftes Kopfgeld auf ihre Federn aus. Ihre Nester und Horste in den felsigen Schluchten werden schwer bewacht. Dort streifen Hecklefanghyänen umher, während wilde Sonnenschuppenraptoren im Hochland jagen."}},faq={{q="Warum heißen die Trockenen Hügel so, wenn sie so grün sind?",a="Trotz ihres Namens sind die Trockenen Hügel deutlich grüner als das umliegende Brachland. Keine Aufzeichnung erklärt den Namen oder diesen örtlichen Gegensatz.",al={"warum trockene hügel","trockene hügel grün","trockene hügel gelände"}},{q="Wer lebt in den Trockenen Hügeln?",a="Der Hexenschwingenstamm der Harpyien kontrolliert unter Serena Bloodfeathers Herrschaft fast die gesamten Hügel. Auch Hecklefanghyänen und Sonnenschuppenraptoren durchstreifen die felsigen Hänge.",al={"wer lebt in den trockenen hügeln","trockene hügel bewohner","harpyien trockene hügel"}},{q="Warum interessiert sich die Horde für dieses Gebiet?",a="Plünderer des Hexenschwingenstamms greifen von den Hügeln aus an, um Versorgungskarawanen auf der nördlichen Goldstraße auszuplündern. Befehlshaber der Horde setzen Kopfgelder aus, um ihre Zahl zu verringern und ihre Anführer auszuschalten.",al={"horde trockene hügel","warum hier harpyien bekämpfen","trockene hügel quests"}},{q="Was sind die verfallenen Türme und Katapulte mitten in den Hügeln?",a="Die Türme und Katapulte sind die Überreste eines verlassenen orkischen Außenpostens. Die erhaltenen Bauten verraten weder seinen ursprünglichen Auftrag noch den Grund seiner Aufgabe.",al={"orkturm trockene hügel","verlassene katapulte trockene hügel","orkruinen trockene hügel"}}},fx={["06447f2d"]={q="Was sind Die trockenen Hügel?",a="Die trockenen Hügel sind ein üppiges, grünes Gebiet, das in den nordwestlichen Ausläufern des Brachlands liegt, direkt an den Abhängen des Steinkrallengebirges. Im krassen Gegensatz zu den ausgedörrten Savannen, die sich nach Süden und Osten erstrecken, blüht dieses Gebiet mit grünem Gebüsch und hohen Klippen. Sein ruhiges Erscheinungsbild täuscht jedoch, da die Hänge zur Brutstätte gefährlicher Kreaturen und zu einem umkämpften Hochland an der Grenze der Horde-Gebiete geworden sind.",al={"was sind die trockenen hügel","geschichte der trockenen hügel","info zu den trockenen hügeln"}},["9a122504"]={q="Sind Die trockenen Hügel gefährlich?",a="Ein Vorstoß in Die trockenen Hügel ist gefährlich. Die Felsen werden erbittert von den Hexenflügelharpien unter der Führung von Serena Bloodfeather bewacht, die aktiv Versorgungskarawanen überfallen, die die nördliche Goldstraße entlangreisen. Jenseits der Harpien und ihrer Hinterhalt-Jäger streifen aggressive Hecklefanghyänen und Sonnenkappenraptoren durch die Bergrücken, bereit, jeden zu zerreißen, der sich ohne Vorbereitung vom ausgetretenen Pfad entfernt.",al={"sind die trockenen hügel sicher","bedrohungen in den trockenen hügeln","gefahr in den trockenen hügeln"}}},fp="9,61,25.417.0,24.302.0,48.137.0,27.163.0,41.176.0,68.156.0"}
P.entries["subzone:drygulch-ravine"] = {n="Staubwindklamm",s="Dustwind-Harpien überfallen Versorgungskarawanen an der Staubwindklamm im östlichen Durotar. Ihr erreicht ihren felsigen Zufluchtsort durch eine Höhle von der Klingenschlucht aus oder mit einem gefährlichen Sprung von oben.",h="Dustwind-Harpien überfallen Versorgungskarawanen an der Staubwindklamm im östlichen Durotar.",kw={"staubwindklamm","durotar","dustwind-harpien","harpiennester","orgrimmar","klingenschlucht","gestohlene vorräte"},ang={["faction:Horde"]="Die Nistplätze der Harpien zu sichern und gestohlene Vorräte zurückzuholen hilft, Durotars Handelswege vor ständigen Raubüberfällen zu schützen.",["race:Orc"]="Als junger Ork könnt Ihr Euch gegen die wilden Harpien beweisen, die auf den felsigen Klippen Eurer Heimat lauern."},sec={{t="Räuberunterschlupf in den Teufelsfelsen",b="Östlich von Orgrimmar liegt die Staubwindklamm geschützt zwischen Durotars zerklüfteten Felsen. Ein enger natürlicher Tunnel von der Klingenschlucht aus ist der einzige ebenerdige Zugang. Dustwind-Harpien nisten an den steilen Klippen, wo sie ihre Brut aufziehen und Güter anhäufen, die sie Versorgungstrecks der Horde auf den Pfaden der Region geraubt haben."},{t="Ein Dorn in Durotars Seite",b="Die Dustwind-Harpien sind die größte Gefahr in der Klamm. Ihre Matriarchinnen bewachen erbittert die Eier, die auf den hohen Felsvorsprüngen verborgen liegen. Späher der Horde schicken oft junge Krieger los, um den Schwarm auszudünnen, gestohlene Handelskisten zu bergen und die Herrschaft der Harpien über die Klamm zu brechen."}},faq={{q="Wie gelangt Ihr in die Staubwindklamm?",a="Ihr erreicht die Klamm mit einem Sprung von den hohen Klippen darüber, sofern Ihr ihn überlebt, oder durch den kleinen Höhleneingang in der benachbarten Klingenschlucht.",al={"staubwindklamm eingang","wie in die staubwindklamm gelangen","wo ist die höhle zur staubwindklamm"}},{q="Welche Kreaturen leben in der Staubwindklamm?",a="Dustwind-Harpien beherrschen die Klamm. Auf ihren zerklüfteten Felsvorsprüngen nisten sie, legen Eier und verstecken gestohlene Karawanenvorräte.",al={"staubwindklamm gegner","was gibt es in der staubwindklamm","wer lebt in der staubwindklamm"}},{q="Warum interessiert sich die Horde für diese Klamm?",a="Dustwind-Harpien überfallen Durotars Handelswege und horten gestohlene Fracht in der Schlucht. Die Obrigkeit in Klingenhügel schickt regelmäßig Rekruten los, um Vorräte zurückzuholen und den Schwarm auszudünnen.",al={"warum harpien in der staubwindklamm töten","staubwindklamm quests","interesse der horde an der staubwindklamm"}}},fx={c29d93c1={q="Ist die Staubwindklamm gefährlich?",a="Die Staubwindklamm ist für unbegleitete Reisende und Versorgungskarawanen gefährlich. Die hohen Klippen werden von den aggressiven Staubwindharpien dominiert, die von ihren Nestern herabstürzen, um Eindringlinge anzugreifen und vorbeiziehende Horde-Transporte zu überfallen. Die Navigation durch die steilen Abgründe und engen Spalten lädt zu Hinterhalten ein, insbesondere in der Nähe ihrer hohen Nester, wo die wildesten Harpien aggressiv ihre Brut bewachen.",al={"ist die staubwindklamm gefährlich","bedrohungen in der staubwindklamm","wie gefährlich ist die staubwindklamm"}},["7b842580"]={q="Was ist die Staubwindklamm?",a="Die Staubwindklamm ist ein abgelegener, steilwandiger Canyon, eingebettet in die schroffen Felsen von Durotar. Hauptsächlich durch eine schmale Höhlenöffnung abseits der Klingenschlucht zugänglich, bietet sie eine geschützte Felsspalte fernab der offenen Ebenen. Sie ist zu einem abgelegenen Nistplatz für Staubwindharpyien geworden, isoliert von den größeren Siedlungen der Horde.",al={"was ist die staubwindklamm","lore der staubwindklamm","infos zur staubwindklamm"}}},fp="15,175,31.311.0,25.248.0,36.147.0,39.119.0,42.173.0"}
P.entries["subzone:drywhisker-gorge"] = {n="Schlucht der Trockenstoppel",s="Nordöstlich von Hammerfall halten die Drywhisker-Kobolde eine Schlucht in den östlichen Bergen des Arathihochlands besetzt. Sie bewachen die innere Höhle, reiche Mineralvorkommen und uralte Elementarrelikte, die unter der Erde begraben liegen.",h="Nordöstlich von Hammerfall halten die Drywhisker-Kobolde eine Schlucht in den östlichen Bergen des...",kw={"arathihochland","drywhisker","schlucht der trockenstoppel","hammerfall","kobold","geringes blutsteinerz","princess myzrael","steinsplitter"},ang={["faction:Horde"]="Die feindseligen Drywhisker-Kobolde leben gleich hinter dem Bergkamm östlich von Hammerfall. Sie bedrohen die Ostflanke des Außenpostens.",["profession:Mining"]="Bergleute schätzen die Höhle der Drywhisker als einzige bekannte Quelle für Geringes Blutsteinerz. Das dichte, von karminroten Adern durchzogene Mineral liegt tief im Fels, den die Kobolde besetzt halten."},sec={{t="Ein Bau in den Ostklippen",b="Die Drywhisker-Kobolde halten die zerklüfteten Felsen östlich von Hammerfall besetzt. Ihr Clan hat sich tief in die Berge gegraben und verteidigt seine gewundenen Gänge erbittert. Dort unten bauen sie Adern von Geringem Blutsteinerz ab. Ihre Festung liegt nahe genug, um den Orcs in Hammerfall Schwierigkeiten zu bereiten."},{t="Geheimnisse der tiefen Höhle",b="Tief in der Höhle der Drywhisker liegt ein Steinsplitter. Die Kobolde sind mit den hoch aufragenden Steinriesen des Hochlands verbündet und hüten Partikel uralter Erdmagie. Der Splitter birgt ein gefangenes Fragment der Essenz von Princess Myzrael. Sie ist eine uralte Erdentität, die unter der Oberfläche gebunden ist."}},faq={{q="Wer lebt in der Schlucht der Trockenstoppel?",a="Der Koboldclan der Drywhisker lebt in der Schlucht und ihren Höhlengängen. Sie verteidigen ihr Gebiet und ihre Bergwerke sowie die darin verborgenen Relikte.",al={"schlucht der trockenstoppel bewohner","was ist in der schlucht der trockenstoppel","wer beherrscht die schlucht der trockenstoppel"}},{q="Wo liegt die Schlucht der Trockenstoppel?",a="Die Schlucht der Trockenstoppel durchschneidet die östlichen Berge des Arathihochlands, nordöstlich von Hammerfall. Ein unwegsamer Pfad führt durch die Hügel östlich des Außenpostens zum Höhleneingang hinauf.",al={"weg zur schlucht der trockenstoppel","schlucht der trockenstoppel lage","wo ist die höhle in arathi"}},{q="Was macht die Höhle im Inneren so bedeutsam?",a="Die Höhle birgt seltene Vorkommen von Geringem Blutsteinerz und einen uralten Steinsplitter. Der Splitter enthält ein Fragment der gefangenen Essenz von Princess Myzrael.",al={"was ist in der höhle","drywhisker höhle geheimnisse","myzrael splitter"}},{q="Warum sind die Kobolde mit Bergriesen verbündet?",a="Der Clan der Drywhisker ist mit den örtlichen Steinriesen verbündet. Die Kobolde dienen Erdrelikten und Elementarpartikeln und bewachen sie. Diese sind mit den Fesseln von Princess Myzrael tief unter Arathi verbunden.",al={"kobolde und riesen","warum sind drywhisker mit riesen verbündet"}}},fp="16,206,29.257.0,26.281.1,30.162.0,34.184.0,39.153.0,48.176.0"}
P.entries["subzone:dun-algaz"] = {n="Dun Algaz",s="Orcs der Dragonmaw haben Dun Algaz eingenommen und damit die leicht passierbare Straße zwischen den Landen von Eisenschmiede und dem Hafen von Menethil gesperrt. Der bewachte Pass und seine Tunnel verbinden Loch Modan mit dem Sumpfland.",h="Orcs der Dragonmaw haben Dun Algaz eingenommen und damit die leicht passierbare Straße zwischen den Landen...",kw={"algaz-tor","station algaz","dragonmaw","dun algaz","loch modan","hafen von menethil","gebirgspass","sumpfland"},ang={["faction:Alliance"]="Für die Allianz ist Dun Algaz eine unverzichtbare Route für Nachschub und Truppen, die den Hafen von Menethil mit Loch Modan und Eisenschmiede verbindet.",["race:Dwarf"]="Als Zwerg kennt Ihr Dun Algaz als uralte Straße Eures Volkes, die durch den Gebirgsrücken von Khaz Modan geschlagen wurde. Orcs der Dragonmaw halten nun seine zwergischen Bastionen und bedrohen die Nachschublinien zum Hafen von Menethil. Ihre Besetzung bleibt eine Beleidigung und eine Bedrohung für die Sicherheit."},sec={{t="Ein Engpass zwischen Reichen",b="Dun Algaz führt durch die schroffen Gipfel zwischen Loch Modan und dem Sumpfland. Den Pass gab es schon vor dem Krieg der Drei Hämmer. Nachdem der Wildhammer-Klan aus Eisenschmiede vertrieben worden war, zog sein Volk auf diesem Weg nach Norden. Steintunnel, Bastionen und Wachposten sichern die Straße. Wer Dun Algaz hält, beherrscht die einzige Überlandroute aus den Kernlanden der Zwerge zum Hafen von Menethil am westlichen Meer."},{t="Das Wiedererstarken der Dragonmaw",b="Nach ihrer Niederlage bei Dun Modr im Zweiten Krieg zog sich die Alte Horde nach Dun Algaz zurück. Der Pass wurde zu ihrem letzten südlichen Bollwerk gegen die Streitkräfte von Sir Anduin Lothar. Die Allianz eroberte ihn für eine Weile zurück, doch Orcs der Dragonmaw haben die Festung erneut überrannt. Zwergische Mountaineers haben sich in die oberen Tunnel zurückgezogen, sodass Reisende im Gebirgskorridor ein tödlicher Spießrutenlauf erwartet."}},faq={{q="Warum ist Dun Algaz gerade so gefährlich?",a="Orcs der Dragonmaw sind aus den umliegenden Bergen herabgestiegen und haben den unteren Pass und die Festung eingenommen. Zwergische Mountaineers wurden zum oberen Pass nahe der Station Algaz zurückgedrängt. Auf der Hauptstraße wimmelt es nun von feindlichen Orcs, die Reisenden zwischen Loch Modan und dem Sumpfland auflauern.",al={"warum sind orcs in dun algaz","dun algaz orcs","wer kontrolliert dun algaz"}},{q="Warum ist dieser Pass für die Zwerge so wichtig?",a="Dun Algaz ist die wichtigste Überlandroute von Eisenschmiede und Loch Modan zum Hafen von Menethil im Sumpfland. Der Hafen von Menethil ist Khaz Modans wichtigster Seezugang zu den übrigen Gebieten der Allianz, weshalb der Pass für Nachschub, Truppen und Handel unverzichtbar ist.",al={"dun algaz bedeutung","warum braucht eisenschmiede dun algaz"}},{q="Spielte Dun Algaz im Zweiten Krieg eine Rolle?",a="Ja. Nach ihrer Niederlage bei Dun Modr zog sich die Horde der Orcs durch Thandol Valley zurück und baute Dun Algaz zu einer Verteidigungsfestung aus. Sir Anduin Lothar befahl einen Angriff, um sie aus Khaz Modan zu vertreiben, doch die Allianz konnte die Horde nicht vollständig verdrängen. Dun Algaz blieb eine ihrer letzten Festungen in der Region.",al={"dun algaz zweiter krieg","anduin lothar dun algaz"}},{q="Welche Geschichte verbindet Dun Algaz mit den Wildhammer-Zwergen?",a="Lange vor dem Zweiten Krieg wurden die Wildhammer-Zwerge während des uralten Krieges der Drei Hämmer aus Eisenschmiede vertrieben. Auf ihrem Weg nach Norden ins Sumpfland zogen sie durch Dun Algaz und ließen sich schließlich in Grim Batol nieder.",al={"wildhammer dun algaz","krieg der drei hämmer pass"}}},fx={e0cd650e={q="Was ist Dun Algaz?",a="Dun Algaz ist eine Reihe von gehauenen Tunneln und Bergwällen, die die Gipfel durchschneiden, welche Loch Modan mit dem Sumpfland verbinden. Einst eine sichere Zwergenfestung und der wichtigste Überlandkorridor zwischen der Eisenschmiede und den nördlichen Küsten, stellt dieser befestigte Pass den kritischen Transit zwischen dem Herzen von Khaz Modan und dem Hafen von Menethil sicher.",al={"was ist dun algaz","pass von dun algaz","tor von dun algaz"}},f60a7bc4={q="Wer kontrolliert Dun Algaz?",a="Dun Algaz ist weitgehend in die Hände der Orcs des Drachenmals gefallen. Obwohl zwergische Bergsteiger immer noch die oberen Tunnel bewachen und den nördlichen Zugang von Loch Modan sichern, haben sich feindselige Plünderer des Drachenmals in den unteren Bereichen und auf den Bergstraßen verschanzt und die Kontrolle über den Pass übernommen.",al={"wer lebt in dun algaz","wer kontrolliert dun algaz","wer führt dun algaz"}},["59a004f5"]={q="Warum wurde Dun Algaz von den Zwergen aufgegeben?",a="Die Festung wurde nach heftigen Angriffen von Überresten des Clans des Drachenmals aufgegeben. Die Orcs überwältigten die in der Festung stationierten zwergischen Verteidiger und zwangen die Bergsteiger der Eisenschmiede zum Rückzug und zur Konsolidierung ihrer Linien am oberen Tunnel des Passes, wodurch ein Großteil der Straße ungepflegt blieb und von feindlichen Kräften besetzt wurde.",al={"warum wurde dun algaz aufgegeben","warum ist dun algaz ruiniert","warum haben die zwerge dun algaz verlassen"}}},fp="9,168,27.409.0,24.388.0,40.284.0,45.251.0,44.319.0,65.230.0"}
P.entries["subzone:dun-garok"] = {n="Dun Garok",s="Dun Garok hält die südöstlichen Höhen des Vorgebirges des Hügellands. Captain Ironhill führt die Zwergengarnison, die Interessen der Allianz und nahe gelegene Unternehmungen im Azurschacht verteidigt. Die Verlassenen von Tarrens Mühle sehen die Festung als Bedrohung an ihrer Grenze.",h="Dun Garok hält die südöstlichen Höhen des Vorgebirges des Hügellands.",kw={"der azurschacht","dun garok","zwerg","hillsbrad","eisenschmiede","ironhill","festung","gebirgsjäger"},ang={["faction:Horde"]="Als Mitglied der Horde steht Ihr einer gut verteidigten Zwergenenklave gegenüber, die die Sicherheit der Verlassenen rund um Tarrens Mühle bedroht. Ihre Garnison ist ein vorrangiges Ziel.",["race:Dwarf"]="Als Zwerg könnt Ihr auf Dun Garok blicken, wo Captain Ironhill und seine Gebirgsjäger ihre menschlichen Verbündeten verteidigen und Eisenschmiedes Einfluss bis nach Lordaeron sichtbar machen."},sec={{t="Eine Bastion im Vorgebirge",b="Dun Garok hält die schroffen Höhen im Südosten von Hillsbrad. Captain Ironhill führt die Gebirgsjäger und Scharfschützen aus Eisenschmiede, die den Außenposten verteidigen. Sie bewachen Menschensiedlungen und schützen Unternehmungen der Allianz im Azurschacht. Steinmauern und tiefe Verschanzungen helfen der Garnison, Bedrohungen aus der Umgebung standzuhalten."},{t="Ziel von Tarrens Mühle",b="Dun Garok liegt nahe bei Tarrens Mühle, und die Verlassenen sehen darin einen Übergriff auf ihre südliche Grenze. Die Truppen von Sylvanas Windläufer nehmen Anstoß an den bewaffneten Zwergen nahe ihrer Festung. Sie planen, in die Festung einzudringen, ihre Verteidigung zu brechen und Captain Ironhills Garnison zu töten, um die Herrschaft der Verlassenen über Hillsbrad zu sichern."}},faq={{q="Was ist Dun Garok?",a="Dun Garok bewacht als befestigter Zwergenaußenposten die südöstlichen Berge des Vorgebirges des Hügellands. Seine Truppen aus Eisenschmiede verteidigen die Besitzungen der Allianz in der Region.",al={"dun garok lage","was ist diese zwergenfestung","hillsbrad zwergenfestung"}},{q="Wer befehligt Dun Garok?",a="Captain Ironhill befehligt die Gebirgsjäger und Scharfschützen von Dun Garok. Sie verteidigen Hillsbrad und den nahe gelegenen Azurschacht.",al={"dun garok anführer","wer führt dun garok","captain ironhill"}},{q="Warum wollen die Verlassenen Dun Garok zerstören?",a="Die Verlassenen sehen Dun Garok nahe Tarrens Mühle als Bedrohung für die Sicherheit an ihrer südlichen Grenze. Sie entsenden Agenten, um die Garnison zu vernichten.",al={"warum greift die horde dun garok an","verlassene dun garok","tarrens mühle dun garok konflikt"}},{q="Welchen strategischen Wert hat Dun Garok für die Allianz?",a="Dun Garok hilft der Allianz, Hillsbrad zu verteidigen und den nahe gelegenen Azurschacht vor einer feindlichen Übernahme zu schützen.",al={"warum ist dun garok wichtig","allianz zweck dun garok"}}},fx={b8973178={q="Was geschah in Dun Garok?",a="Dun Garok wurde als eine Zwergenfestung in den südöstlichen Hügeln errichtet, um umliegende menschliche Siedlungen und Der Azurschacht zu verteidigen. Seit die Verlassene ihre Herrschaft in Lordaeron gefestigt haben, betrachten sie die Zwergenfestung als eine ernste militärische Bedrohung und entsenden regelmäßig Soldaten und Mercenaries, um die Verteidiger zu schikanieren und zu vertreiben.",al={"geschichte von dun garok","was geschah hier","hintergrund von dun garok"}},d2b489e2={q="Ist Dun Garok gefährlich?",a="Ja. Die Festung ist schwer befestigt und wird von disziplinierten Zwergensoldaten unter Hauptmann Ironhill verteidigt. Für Angehörige der Horde und der Verlassene provoziert das Betreten von Dun Garok sofortige Feindseligkeit von Seiten der Elite-Schützen und Gebirgswachen, die ihre Wälle mit hartnäckiger Entschlossenheit verteidigen.",al={"ist dun garok sicher","gefahr in dun garok","bedrohungen in dun garok"}}},fp="9,263,26.302.0,21.310.0,18.163.0,23.117.0,46.132.0,52.105.0"}
P.entries["subzone:dun-mandarr"] = {n="Dun Mandarr",s="Im Südosten von Winterquell bewachen erzürnte Mondkin das verlassene Zwergenlager Dun Mandarr.",h="Im Südosten von Winterquell bewachen erzürnte Mondkin das verlassene Zwergenlager Dun Mandarr.",kw={"blue-feathered amulet","dun mandarr","zwergenlager","jaron stoneshaper","mondkin","wildkin","winterquell"},ang={["class:Druid"]="Als Druide wisst Ihr, dass die Mondkin, die Dun Mandarr bewachen, Artefakte der Natur und der Gestirne erbittert beschützen. Sie reagieren mit Gewalt, wenn Außenstehende heilige Relikte wie das Blue-Feathered Amulet stören.",["race:Dwarf"]="Als Zwerg erkennt Ihr das traditionelle zwergische Präfix im Namen Dun Mandarr. Die Ruinen erinnern Euch daran, dass archäologischer Ehrgeiz im uralten Kalimdor in einer Katastrophe enden kann."},sec={{t="Ein verlassenes Lager",b="Dun Mandarr liegt in den gefrorenen südöstlichen Ausläufern von Winterquell. Jaron Stoneshaper schlug dort sein Lager auf und legte das Blue-Feathered Amulet frei. Die Entdeckung versetzte die einheimischen Wildkin in rasende Wut. Sie fielen über das Lager her und vertrieben die Zwerge. Nun streifen Mondkin durch die zerstörten Unterkünfte und bewachen die Höhle. Keine freundliche Seele ist zwischen den Schneewehen geblieben."}},faq={{q="Was geschah mit dem Lager in Dun Mandarr?",a="Der zwergische Forscher Jaron Stoneshaper errichtete das Lager in Dun Mandarr. Bei Ausgrabungen legte er das Blue-Feathered Amulet frei und brachte damit die Wildkin der Umgebung dazu, anzugreifen. Jaron und seine Gefährten flohen und ließen das Lager verlassen und überrannt zurück.",al={"warum ist dun mandarr verlassen","wer hat dun mandarr erbaut","was ist dun mandarr"}},{q="Warum gibt es hier so viele Mondkin?",a="Die einheimischen Wildkin betrachten die Höhle und die umliegenden Relikte als heilig. Als Jaron Stoneshaper das Blue-Feathered Amulet ausgrub, gerieten sie in einen wilden Blutrausch, um es zurückzuerobern und ihr Revier zu verteidigen. Sie vertrieben die Eindringlinge und übernahmen das Lager.",al={"warum gibt es hier wildkin","dun mandarr eulenbestien","warum greifen eulenbestien an"}},{q="Wohin ging Jaron Stoneshaper?",a="Nachdem tobende Mondkin Jaron Stoneshaper aus seinem Lager vertrieben hatten, zog er sich an einen anderen Ort in Winterquell zurück. Dort sammelte er seine Kräfte und suchte Hilfe, um seine gestohlenen Forschungsunterlagen und seine Ausrüstung zurückzuholen.",al={"wo ist jaron stoneshaper","jaron stoneshaper aufenthaltsort"}}},fp="11,94,15.356.0,41.235.0,35.251.0,31.181.0"}
P.entries["subzone:dun-modr"] = {n="Dun Modr",s="Dunkeleisenzwerge halten Dun Modr und den südlichen Zugang zum Thandol-Übergang. Während des Zweiten Krieges wechselte die Festung in einem erbitterten Kampf den Besitzer.",h="Dunkeleisenzwerge halten Dun Modr und den südlichen Zugang zum Thandol-Übergang.",kw={"balgaras the foul","dunkeleisenzwerge","dun modr","eisenschmiede","gebirgsjäger","thandol-übergang","sumpfland"},ang={["faction:Alliance"]="Als Mitglied der Allianz steht Ihr einer Bedrohung für die Route über den Thandol-Übergang gegenüber. Sie verbindet Eisenschmiede mit den verbliebenen Streitkräften der Allianz im Norden.",["race:Dwarf"]="Als Zwerg mögt Ihr eine traditionsreiche Bergsiedlung der Bronzebeards in den Händen der Dunkeleisenzwerge als bittere Schmach empfinden. Die Rache ruft."},sec={{t="Eine umkämpfte Bastion",b="Am Nordrand des Sumpflands bewacht Dun Modr die Hauptstraße zwischen Khaz Modan und den nördlichen Menschenkönigreichen. Über Jahrzehnte hinweg haben Armeen um diese Route gekämpft. Während des Zweiten Krieges eroberte die Orc-Horde die Zwergenfestung und nutzte sie, um Raubzüge zu starten und den Armeen der Allianz standzuhalten.\n\nKrieger aus Stromgarde segelten von Tol Barad herbei, um sie zurückzuerobern, doch die Orcs schlugen in einem blutigen Kampf zurück. Schließlich trieben Streitkräfte der Allianz unter Lord Anduin Lothar die Eindringlinge nach Süden über den Thandol-Übergang und brachten die Festung wieder in zwergische Hände."},{t="Der Einfall der Dunkeleisenzwerge",b="Da Eisenschmiedes Aufmerksamkeit geteilt war und viele seiner besten Gebirgsjäger der Allianz in der Ferne dienten, lag Dun Modr ungeschützt da. Die Eindringlinge der Dunkeleisenzwerge nutzten ihre Chance. Sie sabotierten den Thandol-Übergang mit Sprengstoff und überrannten dann die Festung. Unter Führung des Hexenmeisters Balgaras the Foul überwältigten sie die Verteidiger und vertrieben die Garnison der Bronzebeards. Nun halten Gebirgsjäger etwas weiter die Straße hinunter eine düstere Verteidigungslinie und suchen Hilfe, um die Besatzer zu vertreiben."}},faq={{q="Warum ist Dun Modr so wichtig?",a="Dun Modr bewacht die wichtigste Straße nach Norden durch das Sumpfland zum Thandol-Übergang. Wer die Festung hält, kann den Überlandverkehr, den Nachschub und die Truppenbewegungen zwischen Khaz Modan und dem nördlichen Lordaeron kontrollieren.",al={"warum ist dun modr wichtig","bedeutung von dun modr","strategischer wert von dun modr"}},{q="Wer kontrolliert Dun Modr derzeit?",a="Dunkeleisenzwerge halten Dun Modr unter dem Hexenmeister Balgaras the Foul. Eisenschmiede treue Gebirgsjäger der Bronzebeards halten von einem nahen Lager aus Wache und hoffen, die Festung zurückzuerobern.",al={"wer ist in dun modr","wer herrscht über dun modr","wer lebt in dun modr"}},{q="Was geschah während des Zweiten Krieges mit Dun Modr?",a="Die Orc-Horde eroberte Dun Modr und nutzte es als vorgeschobenen Stützpunkt. Streitkräfte aus Stromgarde griffen von Tol Barad aus an, und heftige Kämpfe folgten. Anduin Lothars Streitkräfte der Allianz vertrieben die Horde schließlich aus der Region.",al={"zweiter krieg dun modr","orcs in dun modr","hat die horde dun modr erobert"}},{q="Wer ist Balgaras the Foul?",a="Balgaras the Foul ist der Hexenmeister der Dunkeleisenzwerge, der die Besatzung von Dun Modr anführt. Seine Truppen beschädigten den Thandol-Übergang und vertrieben die örtlichen Verteidiger aus Eisenschmiede aus der Festung.",al={"geschichte von balgaras the foul","wer ist balgaras","anführer der dunkeleisenzwerge in dun modr"}}},fx={["9363f36e"]={q="Was ist Dun Modr?",a="Dun Modr ist eine alte, befestigte Zwergenstadt an der nördlichen Hauptstraße im Sumpfland, direkt südlich von The Thandol Span. Einst eine geschäftige Festung mit eigener Schmiede und Gasthaus, bewachte sie historisch das Tor zwischen Khaz Modan und den nördlichen Königreichen von Lordaeron.",al={"was ist dun modr","hintergrund von dun modr","über dun modr"}},["72873e9f"]={q="Warum ist Dun Modr eine Ruine?",a="Während Eisenschmiede seine Bergsteiger und Soldaten weit weg in Azeroth für die Allianz kämpfen ließ, griffen Dunkeleisenzwerge die verwundbare Region von innen heraus an. Sie sabotierten The Thandol Span, überrannten die geschwächten Verteidigungsanlagen von Dun Modr und hinterließen die Stadt als rauchende Ruine.",al={"warum ist dun modr zerstört","fall von dun modr","was hat dun modr zerstört"}},["3c329954"]={q="Ist Dun Modr gefährlich?",a="Es ist äußerst gefährlich. Dun Modr wimmelt von feindseligen Dunkeleisenzwergen, angeführt von dem bösartigen Hexenmeister Balgaras the Foul. Reisende, die versuchen, nördlich über The Thandol Span zu gelangen, riskieren einen Hinterhalt, es sei denn, sie gehen vorsichtig vor oder unterstützen die dort stationierten Zwergenbergsteiger.",al={"bedrohungen in dun modr","gefahr in dun modr","ist es sicher bei dun modr"}}},fp="8,149,19.537.0,23.440.0,29.212.0,32.171.0,48.208.0,25.173.0"}
P.entries["subzone:dunemaul-compound"] = {n="Truppenlager der Dünenbrecher",s="Am westlichen Rand von Tanaris versammeln sich Dunemaul-Oger um ihre zentrale Siedlung. Der Hügel und das Höhlennetz des Clans liegen zwischen felsigen Bergrücken.",h="Am westlichen Rand von Tanaris versammeln sich Dunemaul-Oger um ihre zentrale Siedlung.",kw={"truppenlager der dünenbrecher","dunemaul oger","ogerhügel","omgorn","tanaris"},ang={["class:Warlock"]="Als Hexenmeister mögt Ihr die Dunemaul-Hexenmeister in einem scheinbar primitiven Wüstenclan als ungewöhnlichen Anblick empfinden. Ihre Anwesenheit zeigt, dass Traditionen der Schatten- und Teufelsmagie selbst in abgelegenen Ogerhügeln Wurzeln geschlagen haben.",["faction:Horde"]="Viele Oger zogen einst mit der Old Horde in den Krieg, doch die abgeschotteten Dunemaul unterstehen keiner äußeren Macht. Sie behandeln Reisende der Horde wie alle anderen Eindringlinge."},sec={{t="Eine Festung im Sand",b="Im westlichen Tanaris verteidigen Dunemaul-Oger ihre Festung gegen Reisende, die die Dünen durchqueren. Das raue, trockene Klima hat den Clan gelehrt, durch rohe Gewalt und Opportunismus zu überleben. Ihre Siedlung erstreckt sich um einen Ogerhügel und ein Höhlennetz. Krieger und Vollstrecker patrouillieren neben verdrehten Zauberwirkern, die dunkle Hexenmeister- und Magiermagie einsetzen. Die Oger weisen ungebetene Gäste mit Gewalt ab."}},faq={{q="Wer herrscht über das Truppenlager der Dünenbrecher?",a="Gor'marok the Ravager führt die Dunemaul-Oger im Lager an. In Gadgetzan fürchtet Andi Lynn die Stärke dieser neu eingetroffenen Schar.",al={"dunemaul anführer","dunemaul boss"}},{q="Welche Arten von Ogern leben hier?",a="Hier leben gewöhnliche Schläger und Vollstrecker sowie listige Ogermagier und Hexenmeister, die dunkle Teufelsmagie und Shadow Magic einsetzen.",al={"dunemaul arten","dunemaul gegner"}},{q="Warum interessiert sich die Horde für dieses Lager?",a="Es gibt keine Aufzeichnungen über ein Interesse der Horde an diesem Lager. Gor'marok the Ravager führt die unabhängige Dunemaul-Schar an. In Gadgetzan fordert Andi Lynn die Zerstörung des Lagers, weil sie fürchtet, dass ihre wachsende Stärke die Region bedrohen wird.",al={"horde dunemaul"}},{q="Wer ist Omgorn the Lost?",a="Omgorn the Lost ist ein schwer aufzuspürender, einzelgängerischer Oger, der manchmal am Rand des Truppenlagers der Dünenbrecher umherstreift. Er hält sich von den gewöhnlichen Wachposten fern, die am Hügel patrouillieren.",al={"omgorn","seltener oger tanaris"}}},fp="17,146,25.395.0,32.134.0,30.118.0,45.238.0,23.164.0"}
P.entries["subzone:durnholde-keep"] = {n="Burg Durnholde",s="Gesetzlose finden in Burg Durnholde Zuflucht, östlich von Tarrens Mühle im Vorgebirge des Hügellands. Die zerstörte Festung diente einst als Hauptquartier der Allianz für die südlichen Internierungslager der Orcs. Nun hält das Syndikat ihre Ruinen besetzt.",h="Gesetzlose finden in Burg Durnholde Zuflucht, östlich von Tarrens Mühle im Vorgebirge des Hügellands.",kw={"blackmoore","burg durnholde","hillsbrad","internierung","syndikat","taretha foxton","tarrens mühle","thrall"},ang={["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass Durnholdes zerbrochene Wehrmauern einst Lordaeron schützten und seine Gerechtigkeit wahrten. Nun haben Gesetzlose und Halsabschneider des Syndikats dort ihren Unterschlupf.",["race:Orc"]="Als Orc kennt Ihr Durnholdes zerfallenes Gemäuer als den Ort, an dem Kriegshäuptling Thrall seine Ketten abwarf. Seine Flucht beendete Jahrzehnte der Gefangenschaft der Orcs und entfachte die Wiedergeburt der Horde."},sec={{t="Ein Schmelztiegel der Gefangenschaft",b="Nach dem Zweiten Krieg machte die Allianz Burg Durnholde zu ihrem Hauptquartier für die südlichen Internierungslager. Lieutenant General Aedelas Blackmoore befehligte die Festung und ihre Arena, in der Orcs zur Unterhaltung und zum Profit kämpften. Blackmoore zog den verwaisten Säugling Go'el als Sklaven auf, nannte ihn Thrall und bildete ihn zum Kämpfer aus.\n\nMit Taretha Foxtons Hilfe entkam Thrall der Gefangenschaft und vereinte später die verstreuten Orc-Clans unter der neuen Horde. Er kehrte nach Durnholde zurück, belagerte die Burg und erschlug Blackmoore. Dann rief er die Erdgeister an, um ihre Mauern zu zerschmettern."},{t="In den Fängen des Syndikats",b="Burg Durnholde liegt seit ihrem Einsturz vor dem Dritten Krieg in Trümmern. Nach dem Fall Lordaerons suchte das Syndikat zwischen ihren zerbrochenen Wehrmauern Zuflucht. Die Banditen sind enteignete Adlige und Halsabschneider aus Alterac.\n\nVon der zerstörten Vorburg und den Türmen aus überfallen sie Reisende im gesamten Vorgebirge des Hügellands. Die alte Festung dient ihnen nun als befestigter Außenposten."}},faq={{q="Warum liegt Burg Durnholde in Trümmern?",a="Thrall kehrte mit der befreiten Horde nach Durnholde zurück, um seinem früheren Herrn, Lieutenant General Aedelas Blackmoore, gegenüberzutreten. Nachdem er Blackmoore erschlagen hatte, rief er die Erdgeister an, die Festung zu zerstören, damit sie sein Volk nie wieder einsperren konnte.",al={"wer hat durnholde zerstört","was ist mit burg durnholde geschehen","warum ist durnholde zerstört"}},{q="Wer hält Burg Durnholde derzeit besetzt?",a="Das Syndikat hält Burg Durnholde besetzt. Seine verbannten Adligen aus Alterac sind zu Gesetzlosen geworden und nutzen die verfallenden Wehrmauern als Zuflucht für ihre Raubzüge und Angriffe in ganz Hillsbrad.",al={"wer lebt in durnholde","durnholde gegner","syndikat in durnholde"}},{q="Welche Verbindung hatte Thrall zu diesem Ort?",a="Aedelas Blackmoore fand den verwaisten Orc als Kind und zog ihn in Durnholde als Sklaven auf. Thrall erlernte Taktik und wurde gezwungen, als Gladiator zu kämpfen, bevor er mit Taretha Foxtons Hilfe entkam.",al={"hat thrall hier gelebt","thrall durnholde geschichte","war thrall hier gefangen"}},{q="Welchem Zweck diente die Burg während des Zweiten Krieges?",a="Durnholde war eine Festung der Allianz. Nach dem Zweiten Krieg wurde sie unter Lieutenant General Aedelas Blackmoore zur Kommandozentrale für die Internierungslager, in denen die besiegten Orcs gefangen gehalten wurden.",al={"durnholde zweiter krieg","wozu wurde durnholde genutzt"}}},fx={["1d89eea7"]={q="Was ist Burg Durnholde?",a="Burg Durnholde ist eine zerstörte Festung östlich von Tarrens Mühle im Vorgebirge des Hügellands. Einst eine geschäftige militärische Festung mit Kasernen, einer Arena und einem Magierturm, diente sie als administratives Command Center für die Orc-Internierungslager der Allianz nach dem Zweiter Krieg. Heute ist sie eine weitläufige Ruine, die von Gesetzlosen und Plünderern besetzt ist.",al={"was ist durnholde","überblick über burg durnholde","wo ist durnholde"}},e6548fd4={q="Ist Burg Durnholde gefährlich?",a="Ja. Die zerfallenen Mauern und das umliegende Gelände sind stark von Agenten des Syndikat befallen, einer aggressiven kriminellen Organisation, die aus ehemaligem Adel aus Alterac und Wegelagerern besteht. Sie bewachen die Trümmer erbittert und greifen alle Reisenden oder Abenteurer an, die ihren Lagern zu nahe kommen.",al={"ist durnholde gefährlich","bedrohungen in burg durnholde","welche gefahren gibt es in durnholde"}},d850e42f={q="Was geschah bei Burg Durnholde?",a="Nach dem Zweiten Krieg wurde Burg Durnholde zum Command Center der Internierungslager für Orcs und erlangte unter Generalleutnant Aedelas Blackmoore traurige Berühmtheit, der den gefangenen Orc Thrall hier als Gladiator aufzog. Nach seiner Flucht kehrte Thrall an der Spitze einer neugeformten Horde zurück, um sein Volk zu befreien. Er besiegte Blackmoore im Kampf und rief die Erdgeister an, um die Festung dem Erdboden gleichzumachen.",al={"geschichte von durnholde","durnholde lore","belagerung von durnholde"}}},fp="14,220,23.563.0,32.356.0,31.242.0,38.166.0,43.201.0,54.185.0"}
P.entries["subzone:dust-plains"] = {n="Die Staubebenen",s="Gnollrudel durchstreifen die Staubebenen, Westfalls trockene Südgrenze. Das Ödland erstreckt sich zur Küste und zu den östlichen Hügeln, wo Klaven's Tower die Ebene überragt.",h="Gnollrudel durchstreifen die Staubebenen, Westfalls trockene Südgrenze.",kw={"die staubebenen","gnolle","klaven's tower","ebenen","südliches westfall","westfall"},ang={["faction:Alliance"]="Die Staubebenen sind ein weiteres gesetzloses Grenzgebiet, in dem Sturmwinds Vernachlässigung deutlich wird. Reisende und örtliche Verteidiger stehen unerbittlichen Gnollrudeln ohne offizielle Verstärkung gegenüber."},sec={{t="Eine karge Grenze",b="Im Süden Westfalls führen die Staubebenen von geplagtem Ackerland in trostlose Wildnis. Wilde Gnolle beanspruchen diesen trockenen Boden schon lange für sich. Sie überfallen Reisende und stellen sich jedem entgegen, der zur Küste oder zu den nahen Hügeln unterwegs ist.\n\nKlaven's Tower markiert die östliche Grenze. Klaven Mortwake, ein Defias-Schurke, hält den alten Magierturm besetzt. Gnolle durchstreifen das umliegende Ödland, sodass Reisende dort keinen Schutz finden."}},faq={{q="Wo liegen die Staubebenen?",a="Die Staubebenen liegen im Süden Westfalls, südlich der verlassenen Gehöfte. Sie erstrecken sich zu den Klippen und zu Klaven's Tower im Osten.",al={"staubebenen lage","wo liegen die staubebenen","wo staubebenen"}},{q="Welche Gefahren erwarten Reisende in den Staubebenen?",a="Wilde Gnolle unterhalten einfache Lager überall auf den staubigen Ebenen. Sie greifen jeden an, der sich in ihre Nähe verirrt.",al={"was lebt in den staubebenen","staubebenen feinde","mobs in den staubebenen"}},{q="Was ist das für ein Turm am östlichen Rand der Ebenen?",a="Klaven's Tower ist ein alter Magierturm, der den östlichen Rand der Staubebenen überragt. Der Defias-Schurke Klaven Mortwake hält ihn als Stützpunkt besetzt.",al={"staubebenen turm","östlicher turm westfall","was ist mortwakes turm"}},{q="Hat die Volksmiliz irgendeine Kontrolle über die Staubebenen?",a="Nein. Die Volksmiliz ist mit der Verteidigung der Späherkuppe und der nördlichen Höfe gegen die Bruderschaft der Defias völlig ausgelastet. Umherstreifende Gnolle beherrschen die Staubebenen außerhalb ihrer Reichweite.",al={"miliz staubebenen","ist die wache von westfall hier"}}},fx={["008911b2"]={q="Wer lebt in Die Staubebenen?",a="Keine friedlichen Siedler nennen diesen trockenen Landstrich ihr Zuhause. Stattdessen bewohnen wilde Gnolle raue Lager, die über die Ebenen verstreut sind, und greifen jeden an, der sich von den nördlichen Ackerländern nach Süden verirrt. Im Osten halten Defias unter dem Schurke Klaven Mortwake Klaven's Tower und stellen sicher, dass die südlichen Ausläufer von Westfall gesetzlos und voller Gefahren bleiben.",al={"wer lebt hier","bewohner der staubebenen","wer kontrolliert die staubebenen"}},["54892ac9"]={q="Wie gefährlich sind Die Staubebenen?",a="Sie gehören zu den gefährlichsten Regionen in Westfall. Weit weg von Späherkuppe und dem Schutz von The People's Militia sind die Ebenen von gewalttätigen Gnollen und Defias-Gesetzlosen überrannt. Unvorbereitete Reisende, die sich in das südliche Brachland wagen, werden leicht umzingelt und niedergestreckt.",al={"sind die staubebenen gefährlich","gefahrenstufe staubebenen","bedrohungen in den staubebenen"}}},fp="11,169,17.403.0,34.141.0,51.92.0,52.145.0,64.177.0"}
P.entries["subzone:dustbowl"] = {n="Das Staubbecken",s="Im Ödland durchqueren Reisende das Staubbecken zwischen Kargath und dem Fangzahntal. Kojoten, Geier und Felselementare streifen durch seine trockenen Rinnen und über das offene Gelände.",h="Im Ödland durchqueren Reisende das Staubbecken zwischen Kargath und dem Fangzahntal.",kw={"ödland","geier","camp wurg","kojoten","das staubbecken","kargath","felselementare","fangzahntal"},ang={["faction:Horde"]="Gleich hinter Kargath ist das Staubbecken die erste offene Wildnis, die Späher der Horde auf ihrem Weg nach Osten ins Ödland durchqueren."},sec={{t="Ein versengter Übergang",b="Camp Wurg kennzeichnet das Staubbecken im nordwestlichen Ödland. Trockene Schluchten durchziehen den rissigen Lehm, und raue Winde fegen Sand über die offene Ebene. Kakteen und vereinzelte, knorrige Bäume klammern sich an den kargen Boden.\n\nKojoten streifen umher, Geier kreisen am Himmel, und lebende Felselementare wandern über den zerklüfteten Boden. Ohne einen Führer ist die Durchquerung dieser Wildnis gefährlich. Camp Wurg bietet einen Orientierungspunkt im Buschland zwischen Kargath und dem Fangzahntal."}},faq={{q="Wo liegt das Staubbecken?",a="Das Staubbecken liegt im nordwestlichen Ödland, zwischen Kargath im Westen und dem Fangzahntal nahe der Mitte.",al={"staubbecken lage","wo liegt das staubbecken","staubbecken ödland karte"}},{q="Welche Kreaturen streifen durch das Staubbecken?",a="Kojoten streifen durch das Staubbecken, während Geier am Himmel kreisen. Felselementare wandern über seinen steinigen Boden.",al={"staubbecken gegner","was lebt im staubbecken","staubbecken wildtiere"}},{q="Welche Orientierungspunkte gibt es im Staubbecken?",a="Camp Wurg ist ein Orientierungspunkt im Staubbecken, zwischen Kargath und dem mittleren Ödland.",al={"lager im staubbecken","camp wurg staubbecken"}},{q="Können hier draußen überhaupt Pflanzen überleben?",a="Widerstandsfähige Kakteen und vereinzelte, knorrige Bäume wachsen trotz des trockenen Klimas im Staubbecken.",al={"staubbecken flora","pflanzen im staubbecken"}}},fp="8,172,19.444.0,30.116.0,35.100.0,41.82.0,36.86.0"}
P.entries["subzone:dustfire-valley"] = {n="Staubfeuertal",s="Am Nordrand der Sengenden Schlucht endet das Staubfeuertal am verschlossenen Tor des Steinwerkpasses und der Straße nach Loch Modan.",h="Am Nordrand der Sengenden Schlucht endet das Staubfeuertal am verschlossenen Tor des Steinwerkpasses und der...",kw={"staubfeuertal","loch modan","verschlossenes tor","sengende schlucht","steinwerkpass","tal der könige"},ang={["race:Dwarf"]="Als Zwerg wisst Ihr, dass dieses stark befestigte Tor einen Hintereingang zwischen dem sicheren Khaz Modan und dem vom Dark Iron-Clan beherrschten Gebiet markiert."},sec={{t="Die nördliche Grenze",b="Asche bedeckt den Fels im Staubfeuertal, wo kahle Schluchtwände um Euch aufragen. An seinem nördlichen Ende versperrt ein verschlossenes Zwergentor den Steinwerkpass. Die Torflügel verwehren den direkten Weg ins Tal der Könige und nach Loch Modan, sodass das Tal eine Sackgasse im schwefeligen Ödland der Sengenden Schlucht bleibt."}},faq={{q="Wohin führt das Tor im Staubfeuertal?",a="Das Tor versperrt den Steinwerkpass, einen Gebirgsdurchgang durch die Höhen zum Tal der Könige in Loch Modan.",al={"staubfeuertal tor","verschlossene tür staubfeuertal","wohin führt der steinwerkpass"}},{q="Könnt Ihr das Tor nach Loch Modan öffnen?",a="Das Zwergentor ist verschlossen, um Loch Modan vor Bedrohungen aus der Sengenden Schlucht zu schützen. Ein bestimmter Schlüssel ist nötig, um hindurchzugelangen.",al={"wie das tor öffnen","steinwerkpass öffnen","schlüssel zum tor im staubfeuertal"}},{q="Warum heißt dieses Gebiet Staubfeuertal?",a="Das Staubfeuertal verdankt seinen Namen der Vulkanasche, dem trockenen Staub und der anhaltenden Hitze in der Schlucht nahe den nördlichen Bergwänden.",al={"staubfeuertal name","warum staubfeuertal"}}},fp="15,124,21.291.0,44.110.0,36.121.0,40.130.0"}
P.entries["subzone:dustwallow-bay"] = {n="Dustwallow Bay",s="Schiffe durchqueren die seichten Gewässer der Dustwallow Bay auf dem Weg zur Insel Theramore. Der Meeresarm liegt zwischen den Düstermarschen und der Insel, mit Buchten und Untiefen fernab der Hauptseewege des östlichen Kalimdor.",h="Schiffe durchqueren die seichten Gewässer der Dustwallow Bay auf dem Weg zur Insel Theramore.",kw={"dustwallow bay","düstermarschen","großes meer","nat pagle","theramore","tidefury-bucht"},ang={["faction:Alliance"]="Für Seeleute und Reisende der Allianz auf dem Weg nach Kalimdor ist Dustwallow Bay das letzte Stück offenes Meer vor dem befestigten Hafen der Insel Theramore."},sec={{t="Gewässer der östlichen Marsch",b="In den Düstermarschen treffen trübe Feuchtgebiete auf das große Meer. Die Insel Theramore liegt im Osten, und Schiffe durchqueren die Bucht, um Lady Jaina Prachtmeers Inselzuflucht zu erreichen. Schiffe kommen und gehen an ihren Docks, doch die Küste bleibt wild und gefährlich. Felsvorsprünge, Murloclager und versteckte Buchten wie die Tidefury-Bucht säumen das Ufer."},{t="Ein Paradies für Fischer",b="Abseits der Krokilisken und feindseligen Bestien der Marsch bieten die Inseln und Buchten ruhige Gewässer und reiche Fänge. Kleine Inselchen nahe der Tidefury-Bucht locken Angler an, die Abgeschiedenheit suchen. Nat Pagle, der berühmte Fischer, wirft seine Angel oft von den Felsen aus aus, fernab vom Gedränge Theramores."}},faq={{q="Wo liegt Dustwallow Bay?",a="Dustwallow Bay erstreckt sich entlang der Ostküste des mittleren Kalimdor, zwischen den durchnässten östlichen Ufern der Düstermarschen und der Insel Theramore.",al={"dustwallow bay lage","wo liegt dustwallow bay","dustwallow wasser"}},{q="Wer ist in der Bucht anzutreffen?",a="Nat Pagle, der berühmte Angler, ist in den äußeren Bereichen der Bucht anzutreffen. Er lagert auf einem kleinen Inselchen in der nahe gelegenen Tidefury-Bucht, südwestlich der Insel Theramore.",al={"wer ist in dustwallow bay","nat pagle dustwallow bay","npcs dustwallow bay"}},{q="Kann man Dustwallow Bay gefahrlos durchschwimmen?",a="Die Bucht zu durchschwimmen ist gefährlich. Murlocs, Haie und andere aggressive Wasserbewohner halten sich häufig in ihren seichten Gewässern und an ihren Küsten auf.",al={"ist dustwallow bay gefährlich","monster in dustwallow bay"}}},fp="14,208,27.334.0,19.266.0,32.138.0,28.151.0,38.126.0"}
P.entries["subzone:dustwind-cave"] = {n="Staubwindhöhle",s="Hoch über der Klingenschlucht üben Initianden der Burning Blade in der Staubwindhöhle, nordöstlich von Klingenhügel. Die Höhle beherbergt den Kult und seinen Übungsplatz in Durotar.",h="Hoch über der Klingenschlucht üben Initianden der Burning Blade in der Staubwindhöhle, nordöstlich von...",kw={"burning blade","kultisten","durotar","staubwindhöhle","teufelsblut","klingenhügel","klingenschlucht"},ang={["class:Warlock"]="Als Hexenmeister der Horde erkennt Ihr vielleicht die dunklen Rituale in der Staubwindhöhle. Die Burning Blade richtet ihre Teufelsgaben gegen Thralls neue Ordnung.",["faction:Horde"]="Für die Horde ist die Staubwindhöhle eine gefährliche Bresche innerhalb Eurer Grenzen. Sie beherbergt Dämonenkultisten in Rufweite von Klingenhügel."},sec={{t="Ein Schatten in den Klippen",b="Die Staubwindhöhle thront über der Klingenschlucht, nahe Klingenhügel, und stellt eine Gefahr für den Ort dar. Hier bildet die Burning Blade unbemerkt von den Behörden der Horde Rekruten aus. Kultisten lehren verbotene dunkle Magie und Dämonologie und bereiten Initianden darauf vor, das junge Reich der Orcs innerhalb von Durotars Grenzen zu schwächen."},{t="Verderbte Blutlinien",b="Wer die Staubwindhöhle betritt, riskiert, der Verderbnis der Burning Blade zu erliegen. Kultisten wirken unberechenbare dunkle Künste, darunter Leiden durch Teufelsblut. Ihr Wirken zeigt, wie sehr der Kult an dem dämonischen Erbe festhält, das Thrall zu verbannen suchte. Die Kabale aus der Höhle zu vertreiben, ist für Durotars zerbrechlichen Frieden von Bedeutung."}},faq={{q="Wo liegt die Staubwindhöhle?",a="Die Staubwindhöhle liegt hoch oben auf den Klippen der Klingenschlucht, nordöstlich von Klingenhügel in Durotar.",al={"staubwindhöhle lage","wo liegt die staubwindhöhle","wie die staubwindhöhle finden"}},{q="Wer hält die Staubwindhöhle besetzt?",a="Kultisten und Initianden der Burning Blade halten die Staubwindhöhle besetzt. Der dämonische Kult verbreitet Teufelsverderbnis und versucht, die Horde zu destabilisieren.",al={"wer ist in der staubwindhöhle","staubwindhöhle gegner","mobs in der staubwindhöhle"}},{q="Warum ist die Burning Blade hier tätig?",a="Die Burning Blade nutzt die Staubwindhöhle als abgelegenen Ausbildungsposten. Erfahrene Kultisten lehren neue Rekruten dämonische Künste, fernab der unmittelbaren Blicke der Wachen von Orgrimmar und Klingenhügel.",al={"warum sind kultisten in der staubwindhöhle","burning blade ziel durotar"}},{q="Warum will die Horde diese Höhle räumen lassen?",a="Dämonen verehrende Kultisten nahe Klingenhügel bedrohen durchreisende Rekruten und Durotars Verteidigung.",al={"warum die staubwindhöhle räumen","bedrohung für die horde staubwindhöhle"}}},fx={["580d7a1c"]={q="Was ist Staubwindhöhle?",a="Staubwindhöhle ist eine kleine Höhle, die in die hohen Klippen über der Klingenschlucht gegraben wurde und direkt nordöstlich von Klingenhügel liegt. Verborgen vor den wachsamen Augen der Grunts von Orgrimmar, dient sie als geheimer Ausbildungsort und Zufluchtsort für Initianden des schattenanbetenden Burning Blade-Kults.",al={"was ist die staubwindhöhle","hintergrund der staubwindhöhle","über die staubwindhöhle"}},c011eaae={q="Ist Staubwindhöhle gefährlich?",a="Sie ist ziemlich gefährlich, besonders für unerfahrene Abenteurer. Die Höhle wimmelt von fanatischen Anhängern des Burning Blade und ihren eifrigen Auszubildenden. Jenseits von Stahlklingen und rücksichtslosen Hinterhalten nutzen diese Eiferer verderbende Schatten- und Dämonenmagie, um ihren dunklen Einfluss über Durotar zu verbreiten.",al={"ist die staubwindhöhle sicher","bedrohungen in der staubwindhöhle","wie gefährlich ist die staubwindhöhle"}}},fp="13,171,22.307.0,18.283.0,31.97.0,27.134.0,40.183.0,42.93.0"}
P.entries["subzone:dwarven-district"] = {n="Der Zwergendistrikt",s="Im nördlichen Viertel von Sturmwind halten Zwergenhandwerker ihre Öfen und Werkstätten in Betrieb. Die Tiefenbahn verbindet ihre Heimat mit Eisenschmiede.",h="Im nördlichen Viertel von Sturmwind halten Zwergenhandwerker ihre Öfen und Werkstätten in Betrieb.",kw={"die tiefenbahn","der zwergendistrikt","jägergilde","eisenschmiede","potts plates","sturmwind"},ang={["profession:Blacksmithing"]="Als Schmied könnt Ihr Sturmwinds leistungsfähige Schmiedeeinrichtungen nutzen, mit weitläufigen Schmelzöfen, robusten Ambossen und erfahrenen Lehrern.",["race:Dwarf"]="Als Zwerg fern von Khaz Modan könnt Ihr im Tosen arbeitender Hochöfen und einer schnellen Verbindung zurück nach Eisenschmiede vertraute Geborgenheit finden."},sec={{t="Eine Heimat fern von Khaz Modan",b="Zwergische Handwerker, Schmiede und Ingenieure haben im nördlichen Viertel von Sturmwind ihr Zuhause. Sein wuchtiges Steinmauerwerk, seine Schmelzbetriebe und Handwerksläden erinnern an Eisenschmiede. Bei Potts' Plates finden Handwerker aus Khaz Modan vertraute Gesellschaft.\n\nAn der Ostseite des Distrikts führt ein offener Tunnel mit gewölbter Decke zur Station der Tiefenbahn in Sturmwind. Die Bahn verbindet die Hauptstadt der Menschen direkt mit Eisenschmiede."}},faq={{q="Warum gibt es eine Zwergenenklave in Sturmwind?",a="Keine Chronik berichtet, wie die Zwergenenklave entstand. Heute füllen ihre Schmiede, Bergleute und Ingenieure die Schmieden und Werkstätten, während die Tiefenbahn das Viertel direkt mit Eisenschmiede verbindet.",al={"warum zwerge in sturmwind","ursprung des zwergenviertels","warum heißt es zwergendistrikt"}},{q="Wie gelangt Ihr von hier nach Eisenschmiede?",a="An der Ostseite des Distrikts führt ein offener Tunnel mit gewölbter Decke zur Station der Tiefenbahn. Die unterirdische Strecke bringt Reisende innerhalb weniger Minuten zwischen Sturmwind und Eisenschmiede hin und her.",al={"wie nach eisenschmiede gelangen","wo ist die bahn","eingang zur tiefenbahn"}},{q="Welche Berufe werden im Zwergendistrikt gelehrt?",a="Bergbau, Schmiedekunst und Ingenieurskunst werden im Zwergendistrikt gelehrt. Große Schmiedeöfen, Ambosse und spezialisierte Lehrer stehen für alle drei Handwerke bereit.",al={"berufe im zwergendistrikt","lehrer im zwergendistrikt","schmiedekunstlehrer sturmwind"}},{q="Wo können Jäger in Sturmwind ausgebildet werden?",a="Sturmwinds Jäger haben ihr Hauptquartier bei der Hunter's Guild im Zwergendistrikt, neben zwergischen Scharfschützen und Handelsvorräten.",al={"jägerlehrer sturmwind","jägerhütte","sturmwind jägergilde"}}},fx={e5d74eee={q="Was ist Der Zwergendistrikt?",a="Der Zwergendistrikt ist das geschäftige industrielle Herz von Sturmwind, eingebettet in dessen nordöstliche Ecke. Gefüllt mit wallendem Schmiederauch und dem Klang der Hämmer der Schmiede, dient diese Enklave als primäres Zuhause und Werkstatt für die Zwergenbevölkerung der Stadt, sowie für viele Gnome. Neben seinen Gießereien und Werkstätten beherbergt es die Endstation der Tiefenbahn in Sturmwind, die die Hauptstadt der Menschen direkt mit Eisenschmiede verbindet.",al={"was ist der zwergendistrikt","zwergendistrikt sturmwind","erzähle mir vom zwergendistrikt"}},c66f318a={q="Wer lebt im Zwergendistrikt?",a="Der Distrikt wird hauptsächlich von Zwergen und Gnomen bewohnt, die als Schmiede, Bergleute, Ingenieure und Büchsenmacher ihren Lebensunterhalt verdienen. Sie finden dort auch reisende Besucher, die gerade von der Tiefenbahn kommen, lokale Händler, die Handwerker versorgen, sowie Mitglieder der Jäger-Gilde der Stadt, die sich hier zusammen mit ihren Begleittieren versammeln.",al={"wer lebt im zwergendistrikt","bewohner des zwergendistrikts","einwohner des zwergendistrikts"}},ab83050b={q="Ist der Zwergendistrikt gefährlich?",a="Innerhalb der bewachten Mauern von Sturmwind ist der Distrikt im Allgemeinen sicher vor äußeren Invasionen. Die Schwerindustrie birgt jedoch ihre eigenen Gefahren, von verbrühenden Schmieden und instabilen technischen Apparaturen bis hin zum dichten Dunst, der die Luft verpestet. Ruhige Ecken wie Cut-Throat Alley laden zudem zwielichtige Gestalten und illegale Geschäfte abseits der wachsamen Augen der Stadtwache ein.",al={"ist der zwergendistrikt sicher","gefahr im zwergendistrikt","bedrohungen im zwergendistrikt"}},["60b8a274"]={q="Was geschah zur Gründung des Zwergendistrikts?",a="Wie der Distrikt entstand, ist in den Chroniken dieser Ära nicht festgehalten. Heute ist er Heimat und Arbeitsplatz der Zwergenschmiede, Bergleute und Ingenieure Sturmwinds, ein fester Bestandteil der Gemeinschaft und Industrie der Stadt, der über die Tiefenbahn mit Eisenschmiede verbunden ist.",al={"geschichte des zwergendistrikts","wie entstand der zwergendistrikt"}},["04c5fe8f"]={q="Warum heißt er Der Zwergendistrikt?",a="Er verdankt seinen Namen den Zwergen, die hier leben und arbeiten. Seine Schmieden, Essen und Steinmetzarbeiten spiegeln die Anblicke, Klänge und die Handwerkskunst ihrer bergigen Heimat wider und schaffen einen unverwechselbaren Winkel Sturmwinds, der der Zwergenkultur und der Schwerindustrie gewidmet ist.",al={"warum heisst es zwergendistrikt","name zwergendistrikt"}}},fp="16,141,27.393.0,44.187.0,38.177.0,53.145.0,37.137.0"}
P.entries["subzone:eastern-strand"] = {n="Oststrand",s="Daggerspine-Naga halten den Oststrand an Hillsbrads südöstlicher Küste. Seine Strände und Untiefen reichen bis nahe an die Grenze zum Arathihochland.",h="Daggerspine-Naga halten den Oststrand an Hillsbrads südöstlicher Küste.",kw={"strand","küste","daggerspine","oststrand","vorgebirge des hügellands","naga"},ang={["faction:Alliance"]="Als Reisende der Allianz steht Ihr am Oststrand Daggerspine-Naga gegenüber, die Süderstades seeseitige Verteidigung und nahe Patrouillen von der Flanke her bedrohen.",["faction:Horde"]="Als Reisende der Horde könnte ein geordneter Vorstoß der Naga von der Küste ins Landesinnere Eure Bewegungen und Nachschublinien im südlichen Hillsbrad stören."},sec={{t="Eine feindselige Küste",b="Daggerspine-Naga beherrschen den Oststrand am südöstlichen Rand von Hillsbrad. Auf der anderen Seite der Bucht liegt der Weststrand. Süderstade und Tarrens Mühle kämpfen um die menschlichen Bauernhöfe der Region, während die Naga diese Sandflächen und Gezeitensäume beherrschen. Sie kommen aus dem großen Meer, überqueren die Sandbänke und lassen sich zwischen Felsvorsprüngen nieder. Von dort aus beobachten sie das Festland."},{t="Das Gebiet der Daggerspine",b="Krieger und Zauberwirker der Daggerspine durchstreifen die Strände und nahen Gewässer südöstlich von Süderstade. Ihre Anwesenheit macht die Küste für Reisende gefährlich."}},faq={{q="Wo liegt der Oststrand?",a="Der Oststrand erstreckt sich entlang der südöstlichen Küste des Vorgebirges des Hügellands in Richtung der Grenze zum Arathihochland.",al={"oststrand lage","wo liegt der oststrand","oststrand karte"}},{q="Welche Kreaturen bewohnen den Oststrand?",a="Daggerspine-Naga überrennen den Strand und die nahen Gewässer des Oststrands, darunter Fußsoldaten, Räuber und Zauberwirker entlang des Gezeitensaums.",al={"oststrand gegner","wer lebt am oststrand","oststrand feinde"}},{q="Warum sammeln sich die Naga an diesem Strand?",a="Daggerspine-Naga besetzen die Strände und Gewässer des Oststrands. Welches Ziel sie über die Besetzung dieses Küstengebiets hinaus verfolgen, ist in der Classic-Überlieferung nicht verzeichnet.",al={"warum sind naga in hillsbrad","daggerspine angriffspläne","was machen die naga hier"}},{q="Wie unterscheidet sich der Oststrand vom Weststrand?",a="Beide Strände liegen an Hillsbrads Südküste. Der Weststrand liegt im Südwesten in Richtung Silberwald, wo Torn Fin-Murlocs leben. Der Oststrand liegt im Südosten in Richtung Arathi und wird von Daggerspine-Naga gehalten.",al={"weststrand im vergleich zum oststrand","zwei strände in hillsbrad"}}},fx={["1e981837"]={q="Was ist der Oststrand?",a="Der Oststrand ist die windgepeitschte südöstliche Küste des Vorgebirge des Hügellands, die den kalten Gewässern vom großen Meer zugewandt ist. Während er den Weststrand auf der anderen Seite der Küste der Region widerspiegelt, zeichnet sich dieser Strand durch einen starken Befall von Daggerspine-Naga aus, die im seichten Wasser lauern und sich entlang der Brandung versammeln.",al={"was ist der oststrand","hintergrund zum oststrand","erzähle mir vom oststrand"}},["05c2d3e2"]={q="Ist der Oststrand gefährlich?",a="Die Küstenlinie ist gefährlich für Reisende. Aggressive Daggerspine-Naga, einschließlich Kriegern und Zauberwirkern, durchstreifen die Strände und das Wasser und greifen Außenstehende an, die sich ihrem Territorium nähern.",al={"gefahr am oststrand","ist der oststrand sicher","wie gefährlich ist der oststrand"}},a940bc43={q="Warum heißt er Oststrand?",a="Er ist einfach nach seiner Geografie benannt. 'Strand' ist ein alter Begriff für ein Ufer oder einen Strand, und dieser Abschnitt bildet die östliche Hälfte der Küste, die an das Vorgebirge des Hügellands grenzt, und steht im natürlichen Kontrast zum Weststrand, der hinter Süderstade liegt.",al={"warum heißt er oststrand","ursprung des namens oststrand","woher hat der oststrand seinen namen"}}},fp="14,145,19.363.0,21.154.1,36.106.0,42.141.0,41.154.0,59.205.0"}
P.entries["subzone:eastmoon-ruins"] = {n="Ostmondruinen",s="Oger der Dunemaul besetzen die Ostmondruinen westlich der Klaffenden Schlucht im östlichen Tanaris. Ihr Lager liegt zwischen den Überresten einer uralten Trollstätte.",h="Oger der Dunemaul besetzen die Ostmondruinen westlich der Klaffenden Schlucht im östlichen Tanaris.",kw={"dunemaul","eastmoon","ostmondruinen","die klaffende schlucht","tanaris","trollruinen"},ang={["class:Rogue"]="Als Schurke könnt Ihr die zerbrochenen Säulen und Mauern nutzen, um am Rand des Lagers an Ogern der Dunemaul vorbeizuschleichen oder ihnen aufzulauern.",["race:Troll"]="Als Troll könnt Ihr hier erkennen, wie weit sich der Einfluss Eurer Vorfahren über Kalimdor erstreckte, bevor der Wüstensand den Süden verschlang."},sec={{t="Steine im Sand",b="Westlich der Klaffenden Schlucht ragen alte Trollsteine aus dem Wüstensand von Tanaris. Ihre Säulen und Plätze sind im Lauf der Zeit zerfallen. Heute suchen Oger der Dunemaul zwischen den zerbrochenen Mauern Schutz und beobachten die nahen Handelswege."}},faq={{q="Wer hat die Ostmondruinen erbaut?",a="Uralte Trolle erbauten die Ostmondruinen. Ihr Mauerwerk und ihre Plätze sind noch immer in der Wüste zu finden, von der Zeit gezeichnet.",al={"wer erbaute die ostmondruinen","ursprung von eastmoon","trolle erbauten eastmoon"}},{q="Wer beherrscht die Ostmondruinen heute?",a="Oger der Dunemaul besetzen heute die Ostmondruinen. Sie lagern zwischen den alten Mauern und wachen über das östliche Tanaris.",al={"wer lebt in eastmoon","gegner in den ostmondruinen","wastewanders in eastmoon"}},{q="Wo liegen die Ostmondruinen?",a="Die Ostmondruinen liegen im östlichen Tanaris, unmittelbar westlich der Klaffenden Schlucht.",al={"lage der ostmondruinen","wo liegt eastmoon","ostmondruinen finden"}},{q="Gibt es Quests in den Ostmondruinen?",a="Die Ostmondruinen sind ein Lager der Oger der Dunemaul und ein altes Wahrzeichen tief in der Wüste. Ihr könnt die Umgebung erkunden, doch kein Auftrag führt gezielt zu den Ruinen.",al={"quests in eastmoon","quests in den ostmondruinen","gibt es hier eine quest"}}},fp="14,144,18.212.0,29.99.0,32.103.0,37.69.0,39.173.0"}
P.entries["subzone:eastvale-logging-camp"] = {n="Holzfällerlager des Osttals",s="Holzbestellungen aus Sturmwind erreichen das Holzfällerlager des Osttals, wo Gefahren die Arbeit erschweren. Wölfe und Bären vertreiben Holzfäller aus den östlichen Wäldern, doch das Lager liefert weiterhin Holz nach Sturmwind und in nahegelegene Siedlungen.",h="Holzbestellungen aus Sturmwind erreichen das Holzfällerlager des Osttals, wo Gefahren die Arbeit erschweren.",kw={"osttal","elwynn","haggard","pferde","holzfällerlager","bauholz","raelen","holz"},ang={["faction:Alliance"]="Im Holzfällerlager des Osttals könnt Ihr zuverlässige Rösser aus Sturmwind kaufen.",["race:Human"]="Als Mensch aus Sturmwind seid Ihr auf das Holz des Osttals angewiesen, um die Siedlungen des Königreichs wiederaufzubauen und instand zu halten."},sec={{t="Ein lebenswichtiger Betrieb unter Belagerung",b="Holzkäufer aus dem gesamten Königreich Sturmwind schicken dem Holzfällerlager des Osttals Bestellungen mit strengen Fristen. Wölfe und Bären streifen durch die Wälder rund um die Arbeitsstätten. Sie vertreiben Holzfäller und lassen geschlagenes Holz zurück.\n\nVorsteherin Raelen leitet die Arbeit des Lagers. Reisende helfen dabei, die Bestien zu vertreiben und das zurückgelassene Holz zu bergen, bevor die Lieferungen in Verzug geraten."},{t="Leben an der Ostgrenze",b="Das Holzfällerlager des Osttals hat Wohnhäuser und Pferdeställe, in denen Reisende edle Reittiere kaufen können. Auf einem nahegelegenen Hügel oberhalb der Arbeitsstätte lebt der pensionierte Marschall Haggard in einem ruhigen Herrenhaus.\n\nEinst führte er die Wache von Sturmwind an. Dann verließ er ihren Dienst, um seinen Ruhestand fernab der Politik der Hauptstadt zu verbringen."}},faq={{q="Was ist die Hauptaufgabe des Holzfällerlagers des Osttals?",a="Das Holzfällerlager des Osttals versorgt das Königreich Sturmwind mit Holz aus dem östlichen Wald von Elwynn. Seine Holzfäller arbeiten lange, um strenge Fristen einzuhalten und Baumeister und Adlige im ganzen Reich zu beliefern.",al={"warum gibt es das osttal","was ist das osttal","bedeutung des holzes aus dem osttal"}},{q="Warum heuert das Holzfällerlager ständig Abenteurer an?",a="Wölfe und Bären bedrohen die Arbeiter in den dichten Wäldern rund um das Holzfällerlager des Osttals. Ihre Angriffe vertreiben Holzfäller vom geschlagenen Holz und gefährden die fristgerechte Versendung der Bestellungen.",al={"probleme im osttal","warum brauchen holzfäller hilfe","wölfe im osttal"}},{q="Wer ist Marschall Haggard?",a="Marschall Haggard ist der ehemalige Anführer der Wache von Sturmwind und inzwischen im Ruhestand. Er verließ den Dienst vor einigen Jahren und lebt nun auf einem friedlichen Anwesen auf den Anhöhen über dem Holzfällerlager des Osttals.",al={"haggard","alter mann beim osttal","marshal haggard elwynn"}},{q="Könnt Ihr im Holzfällerlager des Osttals Reittiere kaufen?",a="Ja. Der Pferdestall im Holzfällerlager des Osttals verkauft Reitpferde und bietet Reitausbildung an.",al={"pferdehändler im osttal","pferde im osttal","reittier kaufen elwynn"}}},fx={ba9b781f={q="Was ist das Holzfällerlager des Osttals?",a="Das Holzfällerlager des Osttals ist ein weitläufiges Netzwerk aus Sägemühlen, Ställen und Arbeiterunterkünften, das in die östlichen Ausläufer des Wald von Elwynn eingebettet ist. Es dient als lebenswichtige wirtschaftliche Ader für das Königreich Sturmwind, da es ständig Holz verarbeitet, um strenge Aufträge und Baufristen im gesamten Reich zu erfüllen.",al={"was ist das osttal","holzfällerlager des osttals","über das holzfällerlager des osttals"}},["85f79eeb"]={q="Wer lebt im Holzfällerlager des Osttals oder betreibt es?",a="Der tägliche Holzbetrieb untersteht Vorsteherin Raelen, die die Arbeiter verwaltet und danach strebt, die Holzlieferungen pünktlich zu halten. Das Lager beherbergt auch zahlreiche Holzfäller, örtliche Stallburschen und pensionierte Persönlichkeiten wie Marschall Haggard, der sich in seinem Anwesen gleich hinter den geschäftigen Sägemühlen aufhält.",al={"wer betreibt das osttal","wer leitet das holzfällerlager des osttals","vorsteher des osttals"}},["6b46ecbb"]={q="Ist das Holzfällerlager des Osttals gefährlich?",a="Während das Lager selbst bewacht wird, sind die umliegenden Wälder voll von räuberischen Wölfen und aggressiven Bären, die regelmäßig die Holzfäller belauern. Arbeiter wurden von ihren Arbeitsplätzen vertrieben und zurückgelassenes Holz liegt verstreut im Unterholz, was ein Vordringen über die Mühlengebäude hinaus für Unvorsichtige gefährlich macht.",al={"wie gefährlich ist das osttal","ist das osttal sicher","bedrohungen im osttal"}},c2c2b618={q="Was geschah am Holzfällerlager des Osttals?",a="Das Lager wurde errichtet, um Elwynns dichte Waldgebiete zu holzen. Im Laufe der Zeit ließen sich hier Veteranen im Ruhestand wie der ehemalige Kommandant der Wache von Sturmwind, Marschall Haggard, nieder, um ruhige Abgeschiedenheit zu finden. Trotz stetigen Betriebs sieht sich das Lager zunehmend bedrängt, da die örtliche Tierwelt außer Kontrolle gerät und Holztransporte sowie die Sicherheit der Arbeiter gefährdet.",al={"geschichte des osttals","geschichte des holzfaellerlagers des osttals","vergangenheit des osttals"}}},fp="21,234,29.368.0,28.276.0,50.199.0,50.187.0,23.182.0,44.94.0"}
P.entries["subzone:eastwall-gate"] = {n="Ostwalltor",s="An Stratholmes östlicher Mauer bietet das Ostwalltor einen Weg in die zerstörte Stadt. Es liegt im Norden der Östlichen Pestländer, abseits des Chaos an den Haupttoren.",h="An Stratholmes östlicher Mauer bietet das Ostwalltor einen Weg in die zerstörte Stadt.",kw={"alonsus chapel","östliche pestländer","ostwalltor","elders’ square","schlüssel zur stadt","fallgitter","seiteneingang","stratholme"},ang={["class:Paladin"]="Als Paladin gelangt Ihr in die Nähe der Alonsus Chapel, einer heiligen Zuflucht inmitten der Asche und der Schrecken der Geißel.",["class:Rogue"]="Als Schurke müsst Ihr das Schlösserknacken meisterhaft beherrschen, um das Ostwalltor ohne den Schlüssel zur Stadt zu öffnen."},sec={{t="Die Hintertür ins Verderben",b="Das Ostwalltor durchbricht Stratholmes östliche Befestigungen. Der Haupteingang führt auf den King’s Square, doch dieser verriegelte Durchgang führt zum Elders’ Square nahe den Stufen der Alonsus Chapel. Von dort könnt Ihr in die Tiefen der Stadt vordringen, ohne die vorderen Barrikaden oder die Reihen der Untoten zu passieren."},{t="Durch das Eisengitter",b="Schweres Eisenwerk versperrt das Ostwalltor. Der Schlüssel zur Stadt, der in Stratholme zu finden ist, öffnet es, und ein hinreichend geschickter Infiltrator kann seine meisterhaften Schlösser knacken. Ein mechanischer Hebel an der Innenwand hebt das Fallgitter an, damit Verbündete folgen können."}},faq={{q="Wohin führt das Ostwalltor?",a="Das Ostwalltor führt auf den Elders’ Square im zerstörten Stratholme, nahe der Alonsus Chapel.",al={"wohin führt das ostwalltor","ostwalltor ziel","was liegt hinter dem ostwalltor"}},{q="Wie lässt sich das Tor öffnen?",a="Das Ostwalltor ist verschlossen. Der Schlüssel zur Stadt, der in Stratholme zu finden ist, öffnet es, oder ein erfahrener Schurke kann das Schloss knacken. Ein Hebel im Inneren hebt das Fallgitter an.",al={"wie das ostwalltor öffnen","ostwalltor aufschließen","ostwalltor schlüssel"}},{q="Warum sollten Abenteurer diesen Eingang dem Haupttor vorziehen?",a="Durch das Ostwalltor können Stoßtrupps die verseuchten vorderen Straßen umgehen und die Stadt nahe dem Elders’ Square betreten. Von dort können sie bestimmte Stadtviertel schneller erreichen.",al={"warum das ostwalltor nutzen","vorteile des seiteneingangs","warum seitentor stratholme"}},{q="Könnt Ihr das Tor von innen öffnen?",a="Ja. Ein Hebel auf Stratholmes Seite hebt das Ostwalltor an und lässt andere ohne Schlüssel hindurch.",al={"hebel im ostwalltor","ostwalltor von innen öffnen"}}},fp="13,161,21.299.0,24.237.0,34.84.0,27.156.0,59.171.0,38.95.0"}
P.entries["subzone:eastwall-tower"] = {n="Ostwallturm",s="An der östlichen Straße wacht der Ostwallturm über eine noch immer von der Geißel verseuchte Wildnis. Als Spähturm für Lordaeron erbaut, fiel er, als die Geißel im Dritten Krieg das Königreich überrollte.",h="An der östlichen Straße wacht der Ostwallturm über eine noch immer von der Geißel verseuchte Wildnis.",kw={"östliche pestländer","ostwallturm","lordaeron","turm der pestländer","spähturm"},ang={["faction:Alliance"]="Für die Allianz ehrt die Rückeroberung des Ostwallturms Lordaerons gefallene Soldaten und sichert den Zugang zur Kapelle des Hoffnungsvollen Lichts gegen Vorstöße der Geißel.",["faction:Horde"]="Der zerstörte Spähturm überblickt Straßen durch die feindseligen nördlichen Lande."},sec={{t="Zerstörte Wacht an der Grenze",b="Die zerbrochenen Wehrgänge des Ostwallturms blicken auf Straßen durch das von der Geißel verseuchte Umland hinab. Er wurde zum Schutz von Lordaerons Grenze erbaut und wachte über Reisende auf dem Weg in die entlegensten Winkel des Reiches. Als die Geißel im Dritten Krieg einfiel, fiel der Außenposten mit den umliegenden Siedlungen. Zerbrochene Steinbögen und verbranntes Gebälk sind geblieben.\n\nDie Armeen des Lichkönigs suchen die Region noch immer heim. Von seiner Anhöhe aus überblickt der zerstörte Turm die östlichen Straßen."}},faq={{q="Was war der Ostwallturm vor seinem Fall?",a="Vor seinem Fall war der Ostwallturm ein vom Königreich Lordaeron erbauter Spähturm zur Verteidigung. Er war Teil der Grenzwacht und schützte Handelswege und abgelegene Bauernhöfe, bevor der Dritte Krieg Lordaerons Untergang brachte.",al={"geschichte des ostwallturms","wer erbaute den ostwallturm","was war dieser ort"}},{q="Wer hat den Turm zerstört?",a="Die Geißel zerstörte den Ostwallturm während der Eroberung durch Prinz Arthas Menethil und der anschließenden Verwüstung Lordaerons durch die Untoten. Untote Monstrositäten zerschmetterten seine Verteidigungsanlagen, töteten die Verteidiger und hinterließen den Turm als Ruine.",al={"wie wurde der ostwallturm zerstört","was geschah mit dem ostwallturm"}},{q="Warum ist der Turm strategisch wichtig?",a="Selbst als Ruine beherrscht der Ostwallturm eine Anhöhe entlang der östlichen Straßen der Pestländer. Von dort überblickt er das von der Geißel verseuchte Umland.",al={"bedeutung des ostwallturms","lage des ostwallturms"}},{q="Kann man am Turm sicher rasten?",a="Der Ostwallturm steht in einem von der Geißel verseuchten Landstrich und bietet keinen sicheren Zufluchtsort.",al={"hier rasten","freundliche wachen"}}},fp="14,200,28.446.0,39.217.0,24.222.0,41.149.0,29.82.0"}
P.entries["subzone:echo-isles"] = {n="Die Echoinseln",s="Die Dunkelspeer wollen die Echoinseln zurückerobern, die nun Zalazane beherrscht. Dort fanden sie ihre erste Heimat, nachdem sie mit Thrall das große Meer überquert hatten.",h="Die Dunkelspeer wollen die Echoinseln zurückerobern, die nun Zalazane beherrscht.",kw={"dunkelspeer","durotar","die echoinseln","sen'jin","trolle","vol'jin","voodoo","zalazane"},ang={["faction:Horde"]="Für die Horde bedeutet die Sicherung der Echoinseln, Durotars Südküste zu stabilisieren, Sen'jin zu schützen und ihre Grenzen gegen Bedrohungen durch Flotten und abtrünnige Mystiker zu halten.",["race:Troll"]="Für die Dunkelspeer sind die Echoinseln ihre versprochene Heimat in Kalimdor und eine Erinnerung an Zalazanes Verrat. Ihre Rückeroberung ist eine Frage des Überlebens ihres Stammes und der persönlichen Ehre."},sec={{t="Eine zerrüttete Zuflucht",b="Die Dunkelspeer machten die Echoinseln zu ihrer Heimat, nachdem sie mit Thrall das große Meer überquert hatten. Ihr Frieden endete, als Großadmiral Daelin Prachtmeers Seestreitkräfte während des Angriffs von Kul Tiras in Durotar einfielen. Die Trolle schlugen Prachtmeers Flotte zurück, doch innerhalb ihres eigenen Stammes erwuchs eine Gefahr.\n\nZalazane, einer ihrer Hexendoktoren, wandte sich dunklen Künsten zu und versklavte den Geist seiner Stammesgenossen. Häuptling Vol'jin und die freien Dunkelspeer flohen erneut. Jenseits der schmalen Meerenge fanden sie vorübergehend Zuflucht in Sen'jin."},{t="Zalazanes Würgegriff",b="Aggressive Raubtiere, verdorbene Wildtiere und Zalazanes Knechte überrennen nun die tropischen Inseln. Der abtrünnige Hexendoktor nutzt bösartige Verhexungen, Voodoofetische und Ju-Ju-Haufen, um Bestien und gefangene Trolle seinem Willen zu unterwerfen. Vol'jins Späher und Krieger brechen oft von ihrem Lager am Strand der Dunkelspeere auf. Bei diesen häufigen Vorstößen suchen sie die Überreste ihrer Gefallenen und eine Gelegenheit, den Mystiker niederzustrecken, der ihnen ihre Heimat raubte."}},faq={{q="Warum leben die Dunkelspeertrolle derzeit nicht hier?",a="Zalazane verriet die Dunkelspeer und beraubte seine Stammesgenossen mit dunkler Magie ihres freien Willens, wodurch sie zu gehorsamen Dienern wurden. Häuptling Vol'jin befahl dem Stamm, an Durotars Festlandküste zu fliehen, wo sie Sen'jin als Stützpunkt gründeten, während sie um die Rückeroberung ihrer Heimat kämpfen.",al={"warum verlassen","warum gingen die trolle fort","heimat der trolle"}},{q="Wer ist Zalazane?",a="Zalazane ist ein Hexendoktor der Dunkelspeer, der sich gegen seinen Stamm wandte. Sein mächtiger Voodoo und seine dunkle Magie belegten die Inseln mit Flüchen, verdarben die heimischen Wildtiere und versklavten andere Trolle zu willenlosen Knechten.",al={"wer ist zalazane","boss auf den echoinseln","hexendoktor zalazane"}},{q="Welche Gefahren lauern auf den Inseln?",a="Wilde Raptoren, Tiger und verderbte Bestien durchstreifen die Inseln. Auch Zalazanes Voodoohaufen und seine gedankenkontrollierten Trolldiener sind dort zu finden, darunter verhexte Trolle und Voodootrolle.",al={"mobs auf den echoinseln","was ist auf den inseln","gefahren der echoinseln"}},{q="Wie gelangte der Stamm der Dunkelspeer ursprünglich auf diese Inseln?",a="Thrall und die Horde retteten die Dunkelspeer vor einer versinkenden Insel und feindseligen Naga im großen Meer. Die Trolle reisten nach Kalimdor, wo ihnen die Echoinseln überlassen wurden, damit sie sich neben ihren verbündeten Orcs niederlassen konnten.",al={"wie kamen die trolle hierher","herkunft der dunkelspeer","geschichte der echoinseln"}}},fx={["7222f2f6"]={q="Was sind Die Echoinseln?",a="Die Echoinseln sind ein tropisches Archipel direkt vor den südöstlichen Küsten von Durotar. Ursprünglich von den Dunkelspeeren als ihre neue Heimat in Kalimdor beansprucht, sind die Inseln heute stark umkämpft und werden von wilden Tieren, verfluchten Trollen und dunkler Magie geplagt.",al={"was sind die echoinseln","echoinseln","wo sind die echoinseln"}},["2c6446a5"]={q="Was geschah mit Die Echoinseln?",a="Nachdem sie mit Thralls Horde aus ihrer sinkenden Heimat entkommen waren, siedelten sich die Dunkelspeere auf den Echoinseln an. Sie waren bald gezwungen zu evakuieren, als die Flotte von Admiral Daelin Prachtmeer angriff. Obwohl Prachtmeer schließlich besiegt wurde und die Trolle zurückkehrten, verriet sie der Hexendoktor Zalazane, indem er dunkle Zauberei einsetzte, um seine Brüder zu versklaven und Vol'jins Volk an die Küste von Durotar zu treiben.",al={"geschichte der echoinseln","lore der echoinseln","was geschah auf den echoinseln"}}},fp="10,142,21.500.0,15.429.0,51.288.0,16.204.0,32.168.0,63.207.0"}
P.entries["subzone:echo-ridge-mine"] = {n="Echokammmine",s="Kobolde halten die Echokammmine in den nordwestlichen Klippen des Nordhaintals besetzt, die das Tal einst mit Stein und Erz versorgte.",h="Kobolde halten die Echokammmine in den nordwestlichen Klippen des Nordhaintals besetzt, die das Tal einst mit...",kw={"echokamm","echokammmine","kobold","marschall mcbride","mine","nordhain","nordhaintal"},ang={["profession:Mining"]="Die Schächte der Echokammmine bergen Mineralvorkommen, doch Schürfer müssen sich durch die kerzentragenden Kobolde kämpfen, um das Erz zu erreichen.",["race:Human"]="Als Mensch, der dem Ruf Sturmwinds folgt, helft Ihr, die Echokammmine zu räumen und die Abtei von Nordhain zu verteidigen."},sec={{t="Ein Stützpunkt für Ungeziefer",b="Die Echokammmine wurde in die Hügel oberhalb der Abtei von Nordhain geschlagen, um das Tal mit Stein und Metall zu versorgen. Kobolde strömten durch ihre Stollen und vertrieben die Arbeiter. Marschall McBride fürchtet, dass sie die Sicherheit Nordhains und seine Rekruten gefährden. Deshalb schickt er neue Rekruten in die Mine, um ihre Zahl zu verringern und sie zurückzuerobern."},{t="Die Bedrohung unter Nordhain",b="Kobolde sind über die Echokammmine hinaus in den Wald von Elwynn vorgedrungen. Vom nordwestlichen Kamm aus bedrohen sie Nordhains Übungsgelände und die Versorgung der Abtei mit Rohstoffen."}},faq={{q="Warum sind Kobolde in der Echokammmine?",a="Kobolde graben sich in dunkle, mineralreiche Stollen. Die Echokammmine war nur schwach gesichert, also überrannten sie die Mine und graben nun nach Schätzen, während sie die Stollen für sich beanspruchen.",al={"warum kobolde hier","echokamm kobolde","wer hat die mine eingenommen"}},{q="Wer versucht, die Echokammmine zurückzuerobern?",a="Marschall McBride bei der Abtei von Nordhain leitet die Bemühungen, die Echokammmine zu räumen. Er schickt neu eingetroffene Abenteurer los, um ihre Stollen auszukundschaften und die Zahl der Kobolde zu verringern, bevor sie sich weiter im Tal ausbreiten.",al={"wer will den echokamm zurück","echokamm quests","mcbride echokamm"}},{q="Wo liegt die Echokammmine?",a="Der Eingang der Echokammmine liegt in der nordwestlichen Ecke des Nordhaintals, in den felsigen Hang unmittelbar nördlich der Weinberge der Abtei geschlagen.",al={"echokamm lage","wo ist der echokamm","echokammmine finden"}}},fx={["7d0021d3"]={q="Was ist die Echokammmine?",a="Die Echokammmine ist eine Bergbauhöhle in den nordwestlichen Kämmen des Nordhaintal. Sie wurde gegründet, um das Tal und die Abtei mit Stein und Erz zu versorgen, ist jedoch kürzlich nach der Übernahme durch plündernde Kobolde in Unordnung geraten.",al={"was ist die echokammmine","infos zur echokammmine","erzähl mir von der echokammmine"}},d8e2171b={q="Was geschah in der Echokammmine?",a="Die Mine wurde von örtlichen menschlichen Bergleuten aktiv betrieben, bis ein Befall von Kobolden die Schächte überflutete. Die Eindringlinge vertrieben die Arbeiter und übernahmen die Tunnel, was die Behörden von Nordhain zwang, ihre Arbeitskräfte abzuziehen und militärische Hilfe zur Beseitigung des Befalls zu suchen.",al={"geschichte der echokammmine","was ist hier passiert","warum wurde die mine geschlossen"}},["9fd09044"]={q="Warum ist die Echokammmine verlassen?",a="Die menschlichen Operationen kamen abrupt zum Stillstand, als die Kobolde die Arbeiter überwältigten. Da es an sofortigen Wachen mangelte, um die Sicherheit unter Tage zu gewährleisten, stellte die Abtei den normalen Minenbetrieb ein und verließ sich auf neu eingetroffene Rekruten, um das Ungeziefer zu vertreiben.",al={"warum ist die echokammmine verlassen","ist die echokammmine ruiniert","warum ist die mine geschlossen"}},df055836={q="Ist die Echokammmine gefährlich?",a="Die Tunnel sind voll von defensiven Kobolden, die nach Ressourcen graben und ihre kerzenbeleuchteten Ansprüche bewachen. Während einzelnes Ungeziefer relativ schwach ist, kann ein unaufmerksamer Reisender in den gewundenen, geschlossenen Schächten schnell in die Enge getrieben werden.",al={"ist die echokammmine gefährlich","gefahr in der echokammmine","wie gefährlich ist die echokammmine"}}},fp="15,118,21.319.0,29.175.0,35.173.0,41.206.0,33.138.0"}
P.entries["subzone:elder-rise"] = {n="Die Anhöhe der Ältesten",s="Auf der Anhöhe der Ältesten versammeln sich Donnerfels' spirituelle Führer und Älteste östlich des zentralen Plateaus. Lange Hängebrücken verbinden sie mit der High Rise und der Middle Rise.",h="Auf der Anhöhe der Ältesten versammeln sich Donnerfels' spirituelle Führer und Älteste östlich des zentralen...",kw={"zirkel des cenarius","die anhöhe der ältesten","halle der ältesten","hamuul runetotem","magatha grimmtotem","mulgore","donnerfels"},ang={["class:Druid"]="Als Druide findet Ihr das Heiligtum von Erzdruide Hamuul Runentotem auf der Anhöhe der Ältesten. Es ist der regionale Sitz des Zirkels des Cenarius in Kalimdor.",["race:Tauren"]="Als Tauren findet Ihr den Rat der Ältesten und spirituelle Führer auf der Anhöhe der Ältesten. Sie führen Eure Stämme durch Frieden, Tradition und die komplexen Realitäten der Horde."},sec={{t="Zuflucht für Glauben und Rat",b="Schwankende Seilbrücken führen Euch von der Anhöhe der Ältesten zu den Hauptmesas von Donnerfels. Tauren-Druiden und -Priester unterweisen hier Akolythen und führen sie auf den Wegen der Natur und spirituellen Hingabe. Erzdruide Hamuul Runentotem hat sein Heim oben auf der Mesa. Er brachte den Druidismus zu den Tauren zurück und knüpfte enge Bande mit dem Zirkel des Cenarius. In der Nähe versammeln sich Stammesführer in der Halle der Ältesten, um über die Bedürfnisse ihrer jungen Hauptstadt zu beraten."},{t="Eine heikle Präsenz",b="Auf der Anhöhe der Ältesten herrscht Frieden, doch politische Spannungen bleiben bestehen. Magatha Grimmtotem, Matriarchin des verschwiegenen und hochmütigen Grimmtotem-Stammes, lebt in einer Hütte zwischen den beiden Brücken. Cairne Bluthuf heißt alle Tauren-Geschlechter willkommen und gewährt ihnen Sitze im Rat. Doch Magathas Anwesenheit erinnert die Stadt daran, dass nicht jeder Stamm die pazifistischen Ideale der Bluthufe oder ihr fragloses Bündnis mit der Horde teilt."}},faq={{q="Wozu dient die Anhöhe der Ältesten?",a="Die Anhöhe der Ältesten ist Donnerfels' Zentrum für spirituelle Lehre und städtische Beratungen. Druiden des Zirkels des Cenarius, Tauren-Priester, der Rat der Ältesten und Stammesführer versammeln sich hier.",al={"zweck der anhöhe der ältesten","was ist auf der anhöhe der ältesten","gebäude auf der anhöhe der ältesten"}},{q="Wer führt die Druiden auf der Anhöhe der Ältesten an?",a="Erzdruide Hamuul Runentotem führt die Druiden auf der Anhöhe der Ältesten an. Als enger Freund und Berater von Cairne Bluthuf ist er der ranghöchste Tauren im Zirkel des Cenarius und unterweist jene, die dem Ruf der Natur folgen.",al={"erzdruide donnerfels","anführer der tauren-druiden","hamuuls aufenthaltsort"}},{q="Warum bleibt Magatha Grimmtotem hier?",a="Magatha Grimmtotem wohnt in einem Zelt zwischen den Brücken und nimmt für ihr Volk am Rat der Ältesten teil. Sie ist die alte Weise und Häuptling des Grimmtotem-Stammes, dessen Klan Cairnes Verbündeten misstraut.",al={"wo ist magatha","magatha grimmtotem aufenthaltsort","grimmtotem auf der anhöhe der ältesten"}},{q="Wie erreicht Ihr die Anhöhe der Ältesten?",a="Überquert eine große hölzerne Seilbrücke von der High Rise oder vom unteren Plateau aus. Die Anhöhe der Ältesten liegt direkt östlich des zentralen Plateaus der Stadt.",al={"zur anhöhe der ältesten gelangen","brücken der anhöhe der ältesten","weg zur anhöhe der ältesten"}}},fx={f529ee1a={q="Was ist Die Anhöhe der Ältesten?",a="Die Anhöhe der Ältesten ist die östliche Mesa von Donnerfels, die über weite Seilbrücken mit den zentralen Felsen verbunden ist. Sie dient als spirituelles und kontemplatives Herz der Taurenhauptstadt, beherbergt den Rat der Ältesten und dient als örtliche Zuflucht für den Zirkel des Cenarius. Priester, Druiden und weise Älteste versammeln sich hier oben auf dem windgepeitschten Felsen, um zu meditieren, Praktizierende der heiligen Künste auszubilden und Angelegenheiten der Natur und des Stammes zu besprechen.",al={"die anhöhe der ältesten","was ist die anhöhe der ältesten","über die anhöhe der ältesten"}},bfedf1b8={q="Wer lebt auf Die Anhöhe der Ältesten?",a="Die Anhöhe der Ältesten ist die Heimat der spirituellen Führer der Stadt, einschließlich Taurendruiden und Priestern. Erzdruide Hamuul Runentotem leitet die Präsenz des Zirkel des Cenarius hier und bildet Schüler in Gleichgewicht und Harmonie aus. Auf der Mesa tritt auch der regierende Rat der Ältesten zusammen, und Magatha Grimmtotem, die Matriarchin des Stammes der Grimmtotem, unterhält ihren Wohnsitz zwischen den Brücken.",al={"wer ist auf der anhöhe der ältesten","bewohner der anhöhe der ältesten","wer lebt auf der anhöhe der ältesten"}},ea2405f4={q="Ist Die Anhöhe der Ältesten gefährlich?",a="Die Anhöhe der Ältesten ist vollkommen friedlich und hoch über den Ebenen von Mulgore geschützt und bietet Mitgliedern der Horde und respektvollen Reisenden eine Zuflucht. Die einzige wahre Gefahr, der Ihr begegnen könntet, ist ein unvorsichtiger Fehltritt über die Kante der Mesa oder die im Wind schwankenden hohen Seilbrücken.",al={"ist die anhöhe der ältesten sicher","gefahr auf der anhöhe der ältesten","feinde auf der anhöhe der ältesten"}},["06c00c52"]={q="Warum heißt es Die Anhöhe der Ältesten?",a="Die Anhöhe hat ihren Namen vom Rat der Ältesten der Tauren, die sich hier in der Halle der Ältesten versammeln, um Donnerfels ihre kollektive Weisheit und spirituelle Führung anzubieten. Ihre Klippen und Zelte sind für diese angesehenen Gemeindeführer und Mentoren reserviert.",al={"warum heißt es anhöhe der ältesten","herkunft des namens anhöhe der ältesten","name der anhöhe der ältesten"}}},fp="10,160,30.410.0,21.404.0,28.185.0,35.209.0,37.211.0,28.141.0"}
P.entries["subzone:eldreth-row"] = {n="Eldreth Row",s="Gordunnioger patrouillieren in Eldreth Row, den verfallenen westlichen Hallen von Düsterbruch. Überwuchertes Mauerwerk markierte einst die äußere Schwelle des uralten Eldre'Thalas.",h="Gordunnioger patrouillieren in Eldreth Row, den verfallenen westlichen Hallen von Düsterbruch.",kw={"broken commons","düsterbruch","dire pool","eldre'thalas","eldreth row","feralas","gordunni","warpwood quarter"},ang={["race:NightElf"]="Als Nachtelf mögt Ihr im uralten Mauerwerk von Eldre'Thalas eine Erinnerung an den Fall der Hochgeborenen und die Sundering sehen. Oger halten nun die Ruinen besetzt."},sec={{t="Die Schwelle von Eldre'Thalas",b="Eldreth Row führt in die äußeren Hallen des uralten Eldre'Thalas. Die Prachtstraße liegt vor den tiefer gelegenen Vierteln und den Broken Commons. Jahrhunderte der Vernachlässigung haben das Mauerwerk rissig werden lassen, und Pflanzen aus Feralas überwuchern die Kolonnaden. Die Hallen der Hochgeborenen dienen den Gordunniogern nun als Aufmarschgebiet. Ihre Patrouillen bewachen die Wege nach Osten zum Warpwood Quarter und nach Westen am Dire Pool vorbei."}},faq={{q="Was ist Eldreth Row?",a="Eldreth Row ist die äußere Eingangshalle von Düsterbruch in Feralas. Sie liegt vor den Broken Commons und den inneren Toren.",al={"eldreth row","was ist dieser ort","eingang zu düsterbruch"}},{q="Wer kontrolliert Eldreth Row derzeit?",a="Gordunnioger besetzen Eldreth Row und patrouillieren auf den verfallenen Prachtstraßen, um die Ruinen von Düsterbruch zu bewachen.",al={"wer lebt hier","wer kontrolliert eldreth row","monster in eldreth row"}},{q="Wohin führt Eldreth Row?",a="Eldreth Row führt weiter hinein zu den Broken Commons und den Hauptanlagen von Düsterbruch. Das Warpwood Quarter liegt im Osten, der Dire Pool im Westen.",al={"wohin führt diese halle","ausgänge von eldreth row","wege durch düsterbruch"}}},fp="11,146,29.380.0,20.116.0,35.94.0,28.152.0"}
P.entries["subzone:emerald-sanctuary"] = {n="Das Smaragdrefugium",s="Am südlichen Eingang zum Teufelswald versammeln sich Druiden im Smaragdrefugium, um den dämonischen Verderb zu erforschen und die Wälder zu heilen.",h="Am südlichen Eingang zum Teufelswald versammeln sich Druiden im Smaragdrefugium, um den dämonischen Verderb...",kw={"zirkel des cenarius","verderbnis","druiden","das smaragdrefugium","teufelswald","jaedenar"},ang={["class:Druid"]="Als Druide aus Darnassus oder Donnerfels teilt Ihr den Auftrag, das Land zu heilen, der über die Treue zu einer Fraktion hinausgeht."},sec={{t="Ein Leuchtfeuer im Verderben",b="Am südlichen Rand des Teufelswalds liegt das Smaragdrefugium, der Stützpunkt des Zirkels des Cenarius in den verheerten Wäldern. Druiden der Nachtelfen und Tauren arbeiten hier Seite an Seite und lassen die Fraktionskonflikte, die sich über Kalimdor ausbreiten, ruhen, um das Land zu heilen. Forscher spüren verderbte Pflanzen auf und erforschen Jaedenar, auf der Suche nach einem Weg, den vergifteten Boden zu reinigen."}},faq={{q="Welchem Zweck dient das Smaragdrefugium?",a="Der Zirkel des Cenarius errichtete das Lager, um den dämonischen Verderb zu erforschen und zu bekämpfen, der den Teufelswald erstickt. Druiden untersuchen verderbte Pflanzen, Tiere und Gewässer und koordinieren dann den Kampf gegen Kultisten des Shadow Council tiefer in den Wäldern.",al={"warum ist das smaragdrefugium hier","was tun druiden hier","zweck des smaragdrefugiums"}},{q="Können sowohl Allianz als auch Horde das Smaragdrefugium besuchen?",a="Ja. Der Zirkel des Cenarius ist unabhängig und neutral. Er heißt Besucher aus der Allianz und der Horde willkommen, die helfen wollen, den Teufelswald von seinem tief verwurzelten Verderb zu reinigen.",al={"ist das smaragdrefugium neutral","horde im smaragdrefugium erlaubt","smaragdrefugium allianz freundlich"}},{q="Welche Bedrohung bereitet den Druiden hier die größte Sorge?",a="Die Druiden fürchten die dämonischen Energien, die seit dem Dritten Krieg den gesamten Wald entstellt haben, besonders in Jaedenar. Die weitläufigen Höhlen im Norden bieten dem Shadow Council Unterschlupf, der Verderbnis in den Wäldern verbreitet.",al={"größte bedrohung im teufelswald","wogegen kämpfen die druiden","bedrohung durch jaedenar"}}},fp="17,115,22.339.0,45.229.0,56.161.0,46.218.0"}
P.entries["subzone:engineering-labs"] = {n="Engineering Labs",s="In Gnomeregan liegen die Engineering Labs auf Ebenen in Trümmern, die mit dem Workshop Entrance und der Launch Bay verbunden sind. Einst ein Zentrum gnomischer Erfindungskunst, gingen sie in der radioaktiven Katastrophe der Stadt unter. Wahnsinnige Lepragnome und außer Kontrolle geratene Maschinen bevölkern nun die Kammern.",h="In Gnomeregan liegen die Engineering Labs auf Ebenen in Trümmern, die mit dem Workshop Entrance und der...",kw={"engineering labs","gnomeregan","launch bay","lepragnom","lochograph","tinkers' court","workshop entrance"},ang={["profession:Engineering"]="In den Engineering Labs zeugen funktionierende Lochographenterminals und weggeworfene Baupläne vom Höhepunkt gnomischer Automatisierung vor dem Fall der Stadt.",["race:Gnome"]="Als verbannter Gnom seht Ihr eine tragische Ruine. Diese Labore bildeten einst das Herzstück der technologischen Triumphe Eures Volkes. Nun sind die verstrahlten Ruinen von Euren verderbten Verwandten überrannt."},sec={{t="Ein gefallenes Erfinderzentrum",b="Die Engineering Labs beherbergten einst Gnomeregans Erfinderarbeit. Eine zentrale mechanische Struktur erhebt sich über zwei Ebenen, die durch einen Lastenaufzug verbunden sind. Zur Blütezeit der Stadt entwarfen Tüftler hier Baupläne und verfeinerten Uhrwerkgeräte. Strahlung trieb die verbliebenen Forscher in den Wahnsinn. Jetzt bewachen geistesgestörte Lepragnome neben abtrünnigen Konstrukten die fehlerhafte Maschinerie."},{t="Ein entscheidender Knotenpunkt",b="Die Engineering Labs verbinden Wege durch Gnomeregans untere Bereiche. Gänge führen zur Launch Bay, zu Tinkers' Court und zum Hintereingang des Workshop Entrance. Auf der unteren Ebene verarbeiten Terminals des Matrix-Lochographen 3005-D codierte Lochkarten, die Gnomeningenieure bei sich tragen."}},faq={{q="Wozu dienten die Engineering Labs ursprünglich?",a="Vor Gnomeregans Fall erforschten, bauten und testeten Ingenieure in den Engineering Labs komplexe Apparaturen und automatisierte Geräte. Techniker nutzten die gewaltige Kammer mit ihren zwei Ebenen, um Baupläne für neue Technologie zu entwerfen.",al={"zweck der engineering labs","was wurde hier hergestellt","geschichte der engineering labs"}},{q="Welche Gefahren durchstreifen die Engineering Labs heute?",a="Verstrahlte Lepragnome und außer Kontrolle geratene mechanische Automaten durchstreifen beide Ebenen. Gas, das beim Fall der Stadt freigesetzt wurde, trieb die verbliebenen Bewohner in den Wahnsinn, und sie greifen jeden unverstrahlten Eindringling sofort an.",al={"wer ist hier drin","feinde in den engineering labs","monster hier"}},{q="Was sind die Matrix-Lochographen 3005-D?",a="Matrix-Lochographen 3005-D sind automatisierte Datenterminals auf der unteren Ebene der Engineering Labs. Ingenieure und Abenteurer nutzen sie, um codierte Datenkarten zu stanzen, ihre Sicherheitsfreigabe zu erhöhen und technische Archive zu entschlüsseln, die innerhalb der Stadt erhalten sind.",al={"lochograph d","matrix-lochograph 3005-d","maschine für gelbe karten"}},{q="Wie ist dieses Gebiet mit dem Rest von Gnomeregan verbunden?",a="Die obere Ebene ist mit dem Hintereingang des Workshop Entrance und mit Gängen zur Launch Bay verbunden. Die untere Ebene führt zu Hauptkorridoren, die die Launch Bay und Tinkers' Court verbinden.",al={"wohin führt das","ausgänge der engineering labs","wege zu den engineering labs"}}},fx={["36276ef1"]={q="Was ist die Engineering Labs?",a="Die Engineering Labs bilden einen mehrstöckigen Forschungssektor tief in der ruinierten Technostadt Gnomeregan. Bestehend aus einem oberen Schaltkreis und einem unteren Stockwerk, die durch eine offene Aufzugsplattform verbunden sind, beherbergten sie einst hochrangige technologische Experimente, automatisierte Systeme und Diagnosemaschinen wie die Matrix-Lochkartenstanzer 3005-D.",al={"was sind die engineering labs","engineering labs gnomeregan","über die engineering labs"}},a7c381fe={q="Was geschah mit den Engineering Labs?",a="Als die Troggs Gnomeregan durchbrachen, autorisierte der Hochtüftler Mekkatorque die Freisetzung giftiger Strahlung, um die Eindringlinge auszurotten. Anstatt die Stadt zu retten, sättigte der Niederschlag Sektoren wie die Engineering Labs. Die Gnome, die darin arbeiteten, wurden entweder getötet oder auf schreckliche Weise in verstrahlte Gnomeregan-Lepragnome verwandelt, während ihre mechanischen Apparaturen Amok liefen.",al={"geschichte der engineering labs","was geschah hier","fall der engineering labs"}},["2ced7fd6"]={q="Warum sind die Engineering Labs ruiniert und verlassen?",a="Die Labore wurden während des tragischen Falls von Gnomeregan aufgegeben, als radioaktive Entlüftungen die Hallen fluteten, um die Trogg-Invasion zu bekämpfen. Die katastrophale Strahlenbelastung machte die gesamte Einrichtung für unversehrte Gnome unbewohnbar und überließ wertvolle Ausrüstung, Baupläne und Terminals der Gnade von wahnsinnigen Überlebenden und abtrünnigen Automaten.",al={"warum sind die engineering labs ruiniert","warum wurden die engineering labs aufgegeben","fall der labors"}},["526db480"]={q="Wer kontrolliert die Engineering Labs jetzt?",a="Hier hat kein Gnom mehr das Sagen, der noch bei Verstand ist. Die Labore sind von wahnsinnigen Lepragnomen und außer Kontrolle geratenen mechanischen Konstrukten verseucht, die unermüdlich auf beiden Ebenen patrouillieren, darunter der gewaltige Crowd Pummeler 9-60 auf der Südseite der oberen Ebene.",al={"wer lebt in den engineering labs","engineering labs bewohner","wer leitet die engineering labs"}},["620f0877"]={q="Ist es gefährlich, die Engineering Labs zu erkunden?",a="Die Labore sind äußerst gefährlich. Neben der anhaltenden Strahlenbelastung in ganz Gnomeregan müsst Ihr Euch mit angriffslustigen Lepragnomen, defekten Maschinen und feindlichen Konstrukten wie dem Crowd Pummeler 9-60 auseinandersetzen, der auf dem oberen Rundweg patrouilliert.",al={"sind die engineering labs gefährlich","engineering labs gefahren","gefahr in den engineering labs"}}},fp="16,253,29.359.0,16.270.0,51.207.0,43.200.0,48.257.0,53.178.0"}
P.entries["subzone:ethel-rethor"] = {n="Ethel Rethor",s="An Desolaces Nordwestküste liegen Ethel Rethors überflutete Hallen unter dem Meer. Ein versiegelter Turm ragt über die Wellen, während Naga die versunkene Siedlung beherrschen.",h="An Desolaces Nordwestküste liegen Ethel Rethors überflutete Hallen unter dem Meer.",kw={"argentumdämmerung","azore aldamor","desolace","desolace küste","ethel rethor","kaldorei ruinen","naga","versunkene ruinen"},ang={["faction:Alliance"]="Wenn Ihr als Reisender der Allianz Desolaces feindseliges Ödland durchquert, könnt Ihr nahe den Ruinen einem seltenen freundlichen Gesicht begegnen: Azore Aldamort, einem Beobachter der Argentumdämmerung.",["race:NightElf"]="Für Nachtelfen ist Ethel Rethor ein düsteres Denkmal ihres verlorenen Reiches und der verheerenden Großen Zerschlagung. Mutierte Artgenossen streifen nun durch seine versunkenen Hallen."},sec={{t="Ein versunkenes Relikt",b="Ethel Rethors zerbrochene Steine säumen die Küste des westlichen Kalimdor. Vor der Großen Zerschlagung stand hier eine Nachtelfensiedlung, doch ein Großteil davon ist seither im Meer versunken. Zertrümmerte Fundamente liegen unter den Wellen, und ein verwitterter Turm ragt aus der Brandung. Eine kleine Brücke führt zu seinem versiegelten Portal, das den Elementen und Eindringlingen weiterhin verschlossen bleibt. Naga beherrschen nun die überfluteten Kammern und die nahen Untiefen, weshalb es gefährlich ist, sich diesen Gewässern zu nähern."},{t="Wächter an der Küste",b="Reisende kommen nach Ethel Rethor, um Kalimdors vergessene Geschichte zu erforschen und seine heutigen Gefahren zu beobachten. Nahe den Ruinen dient Azore Aldamort der Argentumdämmerung. Er beobachtet die Naga und bietet jenen Hilfe an, die bereit sind, in die versunkenen Gänge hinabzutauchen. Die Gewässer vor der Küste sind gefährlich, und landeinwärts erstreckt sich karges Ödland. So bleiben die Ruinen ein einsamer Treffpunkt an der Küste."}},faq={{q="Was ist Ethel Rethor?",a="Ethel Rethors verfallene Nachtelfensiedlung liegt an Desolaces Nordwestküste. Die meisten ihrer einstigen Bauwerke sind im Meer versunken, sodass nur ein einsamer Turm vor der Küste und überflutetes Mauerwerk bleiben.",al={"ethel rethor geschichte","was ist dieser ort in desolace","ethel rethor ruine"}},{q="Wer beherrscht Ethel Rethor heute?",a="Naga besetzen Ethel Rethors versunkene Ruinen und die nahen Riffe. Sie haben die überfluteten Hallen für sich beansprucht und patrouillieren aggressiv durch die umliegenden Untiefen.",al={"wer lebt in ethel rethor","ethel rethor monster","naga bei ethel rethor"}},{q="Könnt Ihr den Turm betreten?",a="Eine kleine Brücke führt zum Eingang des Turms, doch das Portal ist fest versiegelt. Reisende können sein Äußeres erkunden und in die Ruinen darunter hinabtauchen.",al={"ethel rethor turm öffnen","ethel rethor tür","im inneren von ethel rethor"}},{q="Warum ist die Argentumdämmerung hier?",a="Azore Aldamort, ein Vertreter der Argentumdämmerung, hält nahe Ethel Rethor Wache. Obwohl sich die Argentumdämmerung auf die Geißel im Osten konzentriert, überwachen ihre Agenten in ganz Kalimdor ungewöhnliche magische Störungen, uralte Ruinen und Bedrohungen wie die Naga.",al={"argentumdämmerung in desolace","azore aldamor ethel rethor","argentumdämmerung npc desolace"}}},fp="12,163,15.456.0,21.364.0,21.197.0,30.143.0,28.148.0,28.239.0"}
P.entries["subzone:everlook"] = {n="Ewige Warte",s="Ewige Warte bietet Reisenden Schutz, wo die Wege von Winterquell zusammentreffen. Das Steamwheedle Cartel hält diesen nördlichen Außenposten für Händler, Prospektoren und Forscher offen und bietet eine neutrale Zuflucht vor der Kälte dieser Höhenlage.",h="Ewige Warte bietet Reisenden Schutz, wo die Wege von Winterquell zusammentreffen.",kw={"ewige warte","goblin","gregor greystone","schnee","steamwheedle cartel","handelsaußenposten","winterquell"},ang={["profession:Engineering"]="Ewige Warte ist ein wichtiger Treffpunkt für hochstufige Ingenieure, besonders für jene, die sich auf Gobliningenieurskunst spezialisieren. Sie können lernen, einen Dimensionsreißer zu bauen, der direkt auf die Siedlung abgestimmt ist."},sec={{t="Handel am Rand der Welt",b="An der Wegkreuzung von Winterquell liegt Ewige Warte, der nördlichste Außenposten des Steamwheedle Cartel. Wie Gadgetzan und Beutebucht ist es eine ummauerte Siedlung unter Dauerfrost. Reisende der Allianz und der Horde finden hier Wärme und Schutz, weil die Stadt strikte Neutralität wahrt. Ihre Bank und ihr gemeinsames Auktionshaus sind die einzigen funktionsfähigen Einrichtungen dieser Art in der Region. Angeworbene Schläger bewachen die Siedlung, in der Reisende Zuflucht vor wilden Frostsäblern und Yetis suchen."},{t="Zahnräder in der Tundra",b="Unter den vereisten Holzdächern und zwischen den verspielten Pinguintapeten von Ewige Warte liegen Ingenieurswerkstätten und fortschrittliche alchemistische Labore. Goblintüftler gehen ihrem Handwerk fernab neugieriger Blicke nach.\n\nDie Argentumdämmerung entsandte kürzlich Gregor Greystone, um mit der Stadtführung zu verhandeln. Der Orden beobachtet aufmerksam die uralten Ruinen der Region und die sich im Norden zusammenbrauenden Bedrohungen."}},faq={{q="Wer kontrolliert Ewige Warte?",a="Das Steamwheedle Cartel besitzt und betreibt Ewige Warte. Die Argentumdämmerung entsandte Gregor Greystone als ihren Vertreter.",al={"wer betreibt ewige warte","anführer von ewige warte","wer hat in ewige warte das sagen"}},{q="Warum ist Ewige Warte für Allianz und Horde gleichermaßen sicher?",a="Das Steamwheedle Cartel setzt strikte Handelsneutralität durch. Goblinschläger verprügeln rasch jeden, der einen Kampf beginnt, sodass Reisende jeder Zugehörigkeit ungehindert Handel treiben können.",al={"ist ewige warte neutral","können horde und allianz ewige warte besuchen","pvp-regeln in ewige warte"}},{q="Warum ist die Argentumdämmerung in Ewige Warte?",a="Die Argentumdämmerung unterhält durch ihren Gesandten Gregor Greystone eine offizielle Präsenz in Ewige Warte. Er vertritt den Orden gegenüber den Goblinhändlern und hält nach örtlichen Bedrohungen Ausschau.",al={"was macht die argentumdämmerung hier","gregor greystone ewige warte","argentumdämmerung winterquell"}},{q="Woher bezieht Ewige Warte seine Handelswaren?",a="Die Handelswaren von Ewige Warte kommen mit Handelsflügen und Karawanen auf dem Landweg entlang der Haupthandelsrouten von Winterquell an. Diese Routen treffen am Außenposten zusammen.",al={"schmuggel in ewige warte","handelswaren aus winterquell","woher kommen die waren von ewige warte"}}},fp="8,226,33.448.0,19.364.0,22.112.0,49.173.0,35.173.0,40.145.0"}
P.entries["subzone:faldir-s-cove"] = {n="Die Faldirbucht",s="Blackwater Raiders suchen nun in der Faldirbucht Schutz, nachdem ihre Flotte an der Küste von Arathi ein Unglück ereilte. Der Hafen erinnert auch an die frühen Siedler, die von hier nach Süden segelten, um Sturmwind zu gründen.",h="Blackwater Raiders suchen nun in der Faldirbucht Schutz, nachdem ihre Flotte an der Küste von Arathi ein...",kw={"blackwater raiders","kapitän o'breen","kapitän steelgut","draxlegauge","das versunkene riff","faldir","die faldirbucht","harbinger","phizzlethorpe"},ang={["race:Gnome"]="Als Gnom könnt Ihr Doktor Draxlegauge und Professor Phizzlethorpe im Lager finden, wo sie mit Ingenieursgeräten elfische Edelsteine in den verkalkten Küstenriffen untersuchen und abbauen.",["race:Human"]="Als Mensch steht Ihr an der Küste, von der Eure Vorfahren Arathor verließen und nach Süden zu den Siedlungen segelten, aus denen Sturmwind hervorging."},sec={{t="Tor zum Süden und Piratenzuflucht",b="Südlich von Burg Stromgarde liegt die Faldirbucht hinter den Klippen, erreichbar durch einen verborgenen unterirdischen Tunnel. Der Hafen trägt den Namen von Faldir, einem Entdecker des alten Arathor, dessen Expedition über das große Meer segelte, um Sturmwind zu gründen. Heute suchen Blackwater Raiders aus Beutebucht in seinen Gewässern Schutz. Die Kapitäne Steelgut und O'Breen führten sie auf der Suche nach uralten elfischen Schätzen nach Norden, doch ihre Expedition saß schließlich in der Bucht fest."},{t="Der Untergang der Blackwater-Flotte",b="Die Blackwater-Expedition ereilte an der Küste von Arathi ein Unglück. Unnatürliche Gezeiten, die revierverteidigende Naga auf dem vorgelagerten versunkenen Riff hervorriefen, zerschmetterten zwei ihrer drei Schiffe. Nur die Harbinger erreichte die Faldirbucht unversehrt. Da Naga die Gewässer durchstreifen und ihre Seekarten unter den Wellen verloren sind, sitzen die überlebenden Piraten und gnomischen Forscher hier fest. Sie sind auf Reisende angewiesen, die gegen die Schrecken des Wassers kämpfen und versunkenes Gut vom Meeresboden bergen."}},faq={{q="Wer war Faldir?",a="Faldir war ein Pionier aus dem alten Menschenreich Arathor. Er und seine Gefolgsleute segelten von dieser Küste nach Süden über das Meer, um die Siedlungen zu gründen, aus denen Sturmwind hervorging.",al={"faldir geschichte","wer ist faldir","faldir gründer"}},{q="Wie erreicht Ihr die Faldirbucht?",a="Ihr erreicht die Faldirbucht durch einen verborgenen Tunnel unmittelbar südöstlich der äußeren Südmauern von Burg Stromgarde. Der Durchgang verläuft unterirdisch und mündet am abgeschiedenen Ufer.",al={"wie zur faldirbucht gelangen","faldirbucht eingang","höhle zur faldirbucht"}},{q="Warum sind die Blackwater Raiders hier?",a="Kapitän Steelgut und Kapitän O'Breen führten die Blackwater Raiders von Beutebucht nach Norden, um nach versunkenen elfischen Schätzen zu suchen. Gnomische Erfinder begleiteten sie und brachten Geräte mit, die Edelsteine in den vorgelagerten Riffen aufspüren sollten.",al={"warum sind piraten hier","blackwater raiders arathi","was machen die piraten"}},{q="Was geschah mit ihren Schiffen?",a="Feindselige Naga auf dem versunkenen Riff riefen unnatürliche Gezeiten hervor, die zwei der drei Schiffe der Expedition zerstörten. Das Flaggschiff Harbinger erreichte die Bucht, doch die Seekarten der Besatzung versanken unter den Wellen.",al={"warum sind die schiffe zerstört","versunkene schiffe arathi","wer hat die schiffe versenkt"}}},fp="13,192,34.441.0,33.450.0,15.180.0,31.172.0,36.214.0,29.197.0"}
P.entries["subzone:falfarren-river"] = {n="Der Falfarren",s="Der Falfarren fließt durch das zentrale Eschental und trennt die Lande der Nachtelfen von den Vorposten der Horde. Reisende begegnen an seinen Ufern wilden Gefahren und offenen Konflikten.",h="Der Falfarren fließt durch das zentrale Eschental und trennt die Lande der Nachtelfen von den Vorposten der...",kw={"eschental fluss","astranaar","falfarren","der falfarren","dämonenhügel","splitterholz","xavian"},ang={["faction:Alliance"]="Wenn Ihr als Nachtelf oder Verbündeter den Falfarren nach Osten überquert, gelangt Ihr an die Frontlinien der Horde nahe dem Splitterholzposten.",["faction:Horde"]="Als Mitglied der Horde markiert der Falfarren die westliche Grenze Eurer Ausbreitung vom Splitterholzposten aus. Jenseits davon liegt befestigtes Gebiet der Nachtelfen."},sec={{t="Eine umkämpfte natürliche Grenze",b="Vom Hyjal stürzt der Falfarren über Wasserfälle nach Xavian hinab. Dann schlängelt er sich zwischen dem Splitterholzposten und Nachtflucht hindurch. Bei normalem Wetter ist das Wasser weder besonders tief noch schwer zu durchqueren.\n\nDer Fluss bildet eine grobe Grenze durch das zentrale Eschental. Astranaar und das Herz der Lande der Kaldorei liegen im Westen, während die Lager und Holzfällerbetriebe der Horde im Osten liegen. Holzbrücken an der Hauptstraße führen Reisende in den umkämpften Wald, wo Patrouillen an den Ufern aufeinanderprallen."},{t="Gefahren in den Untiefen",b="Der Falfarren birgt Gefahren, die über Zusammenstöße zwischen Schildwachen und Grunzern hinausgehen. Nahe dem Dämonenhügel durchstreifen verderbte Sumpfbestien und aggressive Wassergeschöpfe die schlammigen Untiefen. Regen kann die Strömung anschwellen lassen.\n\nDichte Baumkronen säumen beide Ufer, wo Hinterhalte und Scharmützel oft auf den Fluss übergreifen."}},faq={{q="Wo beginnt und endet der Falfarren?",a="Der Falfarren entspringt in den Höhen des Hyjal und stürzt über Wasserfälle in den See bei Xavian. Er schlängelt sich südwestwärts durch Eschental und verschwindet dann unterirdisch unter den nördlichen Bergen des Brachlands.",al={"quelle des falfarren","wohin fließt der fluss"}},{q="Warum ist der Falfarren für den Krieg im Eschental bedeutsam?",a="Der Falfarren bildet im zentralen Eschental eine grobe Grenze zwischen den Gebieten unter der Kontrolle der Nachtelfen und der Horde. Astranaar liegt im Westen, während der orkische Splitterholzposten und aktive Holzfällerbetriebe der Horde im Osten liegen.",al={"warum ist der falfarren wichtig","flussgrenze eschental"}},{q="Welche Bedrohungen erwarten Reisende an den Flussufern?",a="Aggressive Sumpfbestien durchstreifen die Untiefen, besonders nahe den verderbten Landen um den Dämonenhügel. Patrouillen der Allianz und der Horde bewachen Brücken und Übergänge, und an den Ufern können Scharmützel oder Hinterhalte ausbrechen.",al={"monster im falfarren","gefahren am falfarren"}}},fx={["553b1115"]={q="Was ist Der Falfarren?",a="Der Falfarren ist ein zentraler Wasserweg, der von Nordosten nach Südwesten durch das Eschental fließt. Er fließt von den Hängen des Hyjal an Xavian vorbei und verschwindet unter den nördlichen Bergen des Brachland, wodurch er als grobe natürliche Grenze dient, die das Land der Nachtelfen um Astranaar vom Stützpunkt der Horde am Splitterholzposten trennt.",al={"was ist der falfarren","infos zum falfarren","wo ist der falfarren"}},["6238ff52"]={q="Ist Der Falfarren gefährlich?",a="Ja. Neben den andauernden militärischen Auseinandersetzungen zwischen den Sentinels und der Horde entlang seiner Übergänge bergen die Gewässer selbst natürliche Gefahren. Aggressive Sumpfbestien lauern unter der Oberfläche rund um den Dämonenhügel und stellen eine tödliche Überraschung für jeden dar, der versucht, die Untiefen zu durchqueren.",al={"ist der falfarren gefährlich","gefahren des falfarren","falfarren bedrohungen"}}},fp="15,162,28.484.0,23.298.0,45.221.0,63.209.0,58.212.0"}
P.entries["subzone:fallen-sky-lake"] = {n="Himmelssturzsee",s="Am Himmelssturzsee verteidigen Shadethickets die Ufer und die zentrale Insel zwischen dem Außenposten der Silberschwingen und dem Lager des Kriegshymnenklans.",h="Am Himmelssturzsee verteidigen Shadethickets die Ufer und die zentrale Insel zwischen dem Außenposten der...",kw={"eschental","himmelssturzsee","orakel","shadethicket","außenposten der silberschwingen","lager des kriegshymnenklans","sumpfbestie"},ang={["class:Druid"]="Als Druide wisst Ihr, dass Nachtelfen einst Mondsteine am Himmelssturzsee sammelten. Shadethicket-Sumpfbestien beanspruchen nun seine Gewässer und machen diesen stillen Winkel des Waldes gefährlich.",["race:NightElf"]="Als Nachtelf findet Ihr den Himmelssturzsee unmittelbar südlich des Außenpostens der Silberschwingen, im heiligen Wald Eurer Ahnen. Wilde Bestien sind angesichts des anschwellenden Trommelns der Horde unberechenbar geworden."},sec={{t="Ein umkämpftes Refugium",b="Südlich des Außenpostens der Silberschwingen und westlich des Lagers des Kriegshymnenklans führt Euch der Himmelssturzsee in umkämpfte Gewässer. Gewaltige Shadethickets durchstreifen das Ufer und die kleine Insel in seiner Mitte und betrachten Eindringlinge als Bedrohung.\n\nEin mächtiges Shadethicket-Orakel herrscht im Herzen der Insel. Das Orakel hortet die gefallenen Mondsteine, die einst hier gesammelt wurden, und hält die Shadethickets an den See gebunden, wachsam gegenüber Reisenden."}},faq={{q="Wo liegt der Himmelssturzsee?",a="Der Himmelssturzsee liegt im östlichen Eschental, südlich des Außenpostens der Silberschwingen, westlich des Lagers des Kriegshymnenklans und nordöstlich des Hains der Silberschwingen.",al={"himmelssturzsee lage","wo liegt der himmelssturzsee","wie den himmelssturzsee finden"}},{q="Welche Kreaturen leben am Himmelssturzsee?",a="Aggressive Shadethickets durchstreifen den Himmelssturzsee und seine Ufer. Ein Shadethicket-Orakel führt sie von der zentralen Insel aus an.",al={"mobs am himmelssturzsee","was gibt es am himmelssturzsee","himmelssturzsee feinde"}},{q="Warum ist das Shadethicket-Orakel wichtig?",a="Das Shadethicket-Orakel führt die Shadethickets am See an und hortet die gefallenen Mondsteine, die Nachtelfen einst dort sammelten. Wer einen Mondstein braucht, muss das Orakel auf der zentralen Insel erschlagen.",al={"orakel am himmelssturzsee","shadethicket-orakel","wer ist auf der insel"}}},fx={["0e5e2d0e"]={q="Was ist der Himmelssturzsee?",a="Der Himmelssturzsee ist ein kleines, abgelegenes Gewässer im zentralen Eschental, südlich des Außenpostens der Silberschwingen und westlich des Lager des Kriegshymnenklans. In seinem Herzen liegt eine einsame Insel, umgeben von ruhigen, aber unheimlichen Gewässern, inmitten der uralten, umkämpften Wälder.",al={"himmelssturzsee","über den himmelssturzsee","was ist dieser see"}},["62a4135b"]={q="Ist der Himmelssturzsee gefährlich?",a="Ja, er ist alles andere als friedlich. Der See und seine Ufer werden von feindseligen Schattengestrüppen heimgesucht, gewaltigen Sumpfbestien, die durch die Gewässer und entlang der Ufer streifen. Im Zentrum der Insel des Sees lauert das Orakel der Schattengestrüppe, eine besonders furchterregende und feindselige Kreatur, die die herabgefallenen Mondsteine des Sees hortet.",al={"gefahren des himmelssturzsees","ist es hier sicher","bedrohungen am himmelssturzsee"}}},fp="15,123,21.405.0,33.138.0,43.116.0,41.196.0"}
P.entries["subzone:fallow-sanctuary"] = {n="Zuflucht der Verirrten",s="In den Sümpfen des Elends birgt die Zuflucht der Verirrten einen Stamm, der von seiner vertrauten Welt abgeschnitten ist. Die Verirrten sind mutierte Draenei, die durch Trauer und Heimweh verwildert sind.",h="In den Sümpfen des Elends birgt die Zuflucht der Verirrten einen Stamm, der von seiner vertrauten Welt...",kw={"zuflucht der verirrten","verirrte","noboru der knüppel","ongeku","sümpfe des elends"},ang={["class:Warlock"]="Als Hexenmeister seht Ihr an den Verirrten, wie dunkle Energien lebendes Fleisch verformen und einen zerbrechlichen Geist zerrütten können."},sec={{t="Dem Wahnsinn verfallene Zuflucht",b="Zwischen den versunkenen Bäumen der Sümpfe des Elends haben die Verirrten die Zuflucht der Verirrten zu ihrem Rückzugsort gemacht. Die Trennung von ihrer angestammten Welt und dunkle Energien haben sie verformt.\n\nTrauer und Isolation zerrütteten den Verstand des Stammes. Heute sind sie feindselig und verwildert und greifen Außenstehende an, die ihr Dorf betreten."},{t="Verschwundene Anführer",b="Ongeku und Noboru der Knüppel führten einst die Zuflucht der Verirrten. Ihre Abwesenheit und ihr Tod ließen das Dorf ohne seine Anführer zurück."}},faq={{q="Was ist die Zuflucht der Verirrten?",a="Die Zuflucht der Verirrten ist eine Siedlung in den Sümpfen des Elends. Sie ist die Heimat der Verirrten, einer stark mutierten Gruppe von Draenei, die durch das Dunkle Portal kamen.",al={"geschichte der zuflucht der verirrten","was ist dieses dorf","lager der verirrten im sumpf"}},{q="Warum sind die Verirrten hier feindselig?",a="Trauer und Heimweh haben die Verirrten der Zuflucht der Verirrten in den Wahnsinn getrieben. Auf Azeroth gefangen und von allem Vertrauten abgeschnitten, sind sie verwildert und greifen Außenstehende an.",al={"warum greifen verirrte an","sind verirrte böse","verwilderte verirrte"}},{q="Wer führt die Zuflucht der Verirrten?",a="Ongeku und Noboru der Knüppel führten einst die Verirrten in der Zuflucht der Verirrten. Ihr Verschwinden und ihr Tod ließen den Stamm ohne seine Anführer zurück.",al={"wer führt die zuflucht der verirrten","noboru","ongeku"}}},fp="16,167,24.307.0,16.121.0,29.159.0,35.176.0,31.139.0"}
P.entries["subzone:faol-s-rest"] = {n="Faols Ruheplatz",s="Im östlichen Tirisfal liegt Faols Ruheplatz südwestlich des Scharlachroten Klosters, vernachlässigt unter einem verseuchten Blätterdach. Die Grabstätte birgt das Grab von Erzbischof Alonsus Faol, dem Gründer der Ritter der Silbernen Hand. Heute ruhen hier die Geister jener, die nahe dem Kloster sterben.",h="Im östlichen Tirisfal liegt Faols Ruheplatz südwestlich des Scharlachroten Klosters, vernachlässigt unter...",kw={"alonsus faol","kirche des heiligen lichts","faols ruheplatz","friedhof","das scharlachrote kloster","silberne hand","tirisfal"},ang={["class:Paladin"]="Als Paladin geht Eure Berufung auf Erzbischof Faol zurück, der einst Uther und seine Gefährten versammelte, um Kampfkunst mit dem Heiligen Licht zu vereinen. Sein ungepflegtes Grab erinnert an die Anfänge des Ordens.",["class:Priest"]="Als Priester folgt Ihr dem Glauben, den Faol als höchstes Oberhaupt der Kirche des Heiligen Lichts durch den Zweiten Krieg führte. Sein verfallenes Denkmal spiegelt den tragischen Niedergang der Kirche im nördlichen Lordaeron wider."},sec={{t="Grabmal des Erzbischofs",b="Bevor der Dritte Krieg Lordaeron verwüstete, kamen Trauernde zu Faols Ruheplatz, um Erzbischof Alonsus Faol zu ehren. Er führte die Kirche des Heiligen Lichts durch die dunklen Tage des Zweiten Krieges und gründete die Paladine zum Schutz der Menschheit. Faol starb friedlich vor der Ankunft der Geißel, und der Anblick des Untergangs seines Königreichs blieb ihm erspart. Damals reisten Trauernde auf der Straße von Capital City hierher, um Gaben niederzulegen und ihren geliebten Patriarchen zu ehren."},{t="Verödung im Schatten des Klosters",b="Die Seuche des Untods ließ Tirisfal verkümmern, und die Pilger stellten ihre Reisen ein. Heute liegt das Denkmal verlassen und rissig unter den hohen Klippen des Scharlachroten Klosters. Wildes Gestrüpp hat die Pfade zurückerobert, und feuchter Nebel sammelt sich um das Grab. Die Geister jener, die nahe dem Kloster oder anderswo in Tirisfal fallen, sammeln sich hier, bevor sie zu den Gefahren ringsum zurückkehren."}},faq={{q="Wer war Alonsus Faol?",a="Alonsus Faol führte die Kirche des Heiligen Lichts während des Zweiten Krieges als Erzbischof. Für seine Weisheit und sein Mitgefühl verehrt, organisierte er Hilfe für Flüchtlinge und gründete die Ritter der Silbernen Hand. Er vereinte heilige Priester und fromme Ritter zu den ersten Paladinen der Menschheit, darunter Uther der Lichtbringer und Turalyon.",al={"wer ist faol","alonsus faols geschichte","wer liegt hier begraben"}},{q="Warum steht dieses Denkmal nahe dem Scharlachroten Kloster?",a="Die Kirche des Heiligen Lichts besaß geweihte Stätten nahe dem Scharlachroten Kloster im nördlichen Lordaeron. Faol wurde in diesem stillen Winkel von Tirisfal vor dem Untergang des Königreichs bestattet, lange bevor scharlachrot gekleidete Eiferer das nahe Kloster befestigten.",al={"warum nahe dem kloster","verbindung zum scharlachroten kloster","bedeutung des ortes"}},{q="Pflegt heute noch jemand das Grab?",a="Niemand kümmert sich um das Grab. Seit die Geißel Lordaeron eroberte, wird die Stätte vernachlässigt. Der Scharlachrote Kreuzzug steigt nur selten zur Pflege in die Senke hinab, und die Verlassenen haben wenig Interesse daran, die Schreine der alten Kirche zu ehren. Die Grabsteine bleiben verwittert und überwuchert.",al={"wer pflegt faols ruheplatz","ist der ort verlassen","grabpflege"}},{q="Welchen praktischen Zweck erfüllt Faols Ruheplatz für Reisende?",a="Faols Ruheplatz ist der örtliche Geisterfriedhof für die umliegende Wildnis und das Scharlachrote Kloster. Wer beim Versuch stirbt, das Kloster zu betreten, oder auf Reisen durch das östliche Tirisfal umkommt, kehrt als Geist zum stillen Denkmal des Erzbischofs zurück.",al={"weg vom friedhof","was ist dieser ort im spiel","klosterfriedhof"}}},fx={f2893c17={q="Was ist Faols Ruheplatz?",a="Faols Ruheplatz ist ein abgelegener, feierlicher Friedhof in den Hügeln des östlichen Tirisfal, direkt südwestlich des Scharlachroten Klosters. Die Stätte wurde zu Ehren von Erzbischof Alonsus Faol erbaut, einer der am meisten verehrten Figuren des Heiligen Lichts und Gründer der Ritter der Silbernen Hand, und zog einst gläubige Pilger aus ganz Lordaeron an, bevor das Königreich fiel.",al={"was ist faols ruheplatz","faols ruheplatz überlieferungen","faols ruheplatz"}},["02f08d97"]={q="Was geschah bei Faols Ruheplatz?",a="Erzbischof Alonsus Faol verstarb vor dem Dritten Krieg und wurde hier unter großer Trauer beigesetzt. Pilger reisten aus allen Ecken des Königreichs an, um an seinem Grab ihre Ehrerbietung zu erweisen. Als jedoch die Geißel durch Lordaeron fegte, zerfiel das Königreich in Trümmer und die Toten erhoben sich, wodurch der heilige Hang geschändet, verlassen und ungepflegt zurückblieb.",al={"faols ruheplatz geschichte","was geschah mit faols ruheplatz","geschichte von faols ruheplatz"}},["7971c9da"]={q="Warum ist Faols Ruheplatz zerstört und verlassen?",a="Als die Plage der Untoten Lordaeron heimsuchte, wurde das Königreich, das einst den Erzbischof verehrte, vernichtet. Da sich der Scharlachrote Kreuzzug in seiner nahegelegenen Festung verschanzt hat und einen endlosen Krieg gegen die Untoten führt, bleibt niemand übrig, der sich um das Denkmal kümmert, sodass das Grab verwittert, überwuchert und von der Außenwelt weitgehend vergessen ist.",al={"warum ist faols ruheplatz verlassen","warum ist faols ruheplatz zerstört","wer kümmert sich um faols ruheplatz"}},["3ebb89a0"]={q="Ist Faols Ruheplatz gefährlich?",a="Während die unmittelbare Lichtung um das Grab ruhig und feierlich ist, sind die umliegenden Hänge gefährlich. Eiferer des Scharlachroten Kreuzzugs patrouillieren an den nahegelegenen Zugängen zum Kloster und greifen jeden Außenstehenden bei Sichtkontakt an, während wilde Bestien und umherstreifende Geißel durch die nebelverhangenen Hügel des östlichen Tirisfal ziehen.",al={"ist faols ruheplatz gefährlich","ist faols ruheplatz sicher","faols ruheplatz gefahr"}},bc843590={q="Warum heißt dieser Ort Faols Ruheplatz?",a="Die Stätte wurde zu Ehren von Erzbischof Alonsus Faol benannt, der nach seinem Ableben hier beigesetzt wurde. Als heiliger Patriarch von der Kirche des Heiligen Lichts angesehen, wurde das Gedenkgelände gewidmet, um dem geliebten Anführer seine letzte, friedliche Ruhe zu gewähren.",al={"warum heißt es faols ruheplatz","nach wem ist faols ruheplatz benannt","faols ruheplatz name"}}},fp="11,263,22.434.0,41.374.0,21.316.0,56.253.0,37.279.0,60.255.0"}
P.entries["subzone:far-watch-post"] = {n="Fernwacht",s="Verteidiger der Horde bewachen die Fernwacht westlich der Brücke über den Südstrom. Sie schützen die Grenze und die Karawanen auf dem Weg zum Wegekreuz vor Borstennackenrotten und Übergriffen der Allianz.",h="Verteidiger der Horde bewachen die Fernwacht westlich der Brücke über den Südstrom.",kw={"brachland","bau","durotar","fernwacht","peons","borstennacken","der südstrom","wachturm","wölfe"},ang={["faction:Alliance"]="Jenseits der Brücke von Durotar hindert die Fernwacht Späher und Saboteure der Allianz daran, sich ungehindert der orkischen Hauptstadt zu nähern.",["faction:Horde"]="Für einen jungen Krieger der Horde, der Durotar verlässt, ist die Fernwacht der letzte vertraute Boden vor Kalimdors rauem, gefährlichem Kernland."},sec={{t="Wächter der Grenze",b="Die Fernwacht bewacht den westlichen Brückenkopf auf dem Weg von Durotar ins Brachland. Dahinter beginnt die trockene Savanne, und der Posten ist das erste Zeichen der Herrschaft der Horde. Ein orkischer Wachturm, ein Bau und Belagerungskatapulte sind auf die Ebenen ausgerichtet und werden für drohende Gefahren bereitgehalten.\n\nSüdlich der Hauptstraße versorgen Peons Reitwölfe für Boten oder Verstärkung. Der Posten sichert die Versorgungsstraße zum Wegekreuz. Seine Verteidiger kontrollieren Reisende und weisen umherstreifende Borstennackenstämme und Späher der Allianz zurück."}},faq={{q="Welchen Zweck erfüllt die Fernwacht?",a="Die Fernwacht bewacht die Grenze zwischen Durotar und dem Brachland. Ihre Verteidiger schützen Versorgungskarawanen der Horde und hindern Borstennackenstämme und Eindringlinge der Allianz daran, den Südstrom nach Durotar zu überqueren.",al={"warum steht die fernwacht hier","zweck der fernwacht","aufgabe des außenpostens fernwacht"}},{q="Wer kontrolliert diesen Außenposten?",a="Die Horde unterhält die Fernwacht als aktives Militärlager. Grunzer der Orcs besetzen den Turm und halten die Belagerungsmaschinen instand, während Peons die Reitwölfe versorgen.",al={"wer führt die fernwacht","fraktion der fernwacht"}},{q="Welchen Bedrohungen ist der Außenposten ausgesetzt?",a="Borstennackenrotten aus dem nahen Buschland bedrängen die Fernwacht. Auch Streitkräfte der Allianz könnten durch das Brachland in Richtung Orgrimmar vorstoßen.",al={"feinde der fernwacht","gefahren bei der fernwacht"}}},fx={c35ec5b1={q="Was ist Fernwacht?",a="Fernwacht ist ein befestigter Außenposten der Horde, der westlich der Brücke liegt, die Durotar mit dem Brachland verbindet. Gekennzeichnet durch einen stabilen Wachturm, einen Orc-Bau, Katapulte und Wolfszwinger im Süden, dient er als das primäre Tor, das die westliche Grenze von Durotar verteidigt und Reisenden sowie Versorgungskarawanen, die in die wilden Ebenen ziehen, den Durchgang sichert.",al={"was ist fernwacht","fernwacht überlieferungen","erkläre fernwacht"}},d7c9315a={q="Ist Fernwacht gefährlich?",a="Für Reisende der Horde bietet der Außenposten selbst Sicherheit unter der wachsamen Aufsicht erfahrener Krieger und Peons. Jenseits seines Umfangs bleibt das Gebiet jedoch gefährlich. Feindselige Stacheleber streifen durch das umliegende Gestrüpp, und potenzielle Überfälle der Allianz bedrohen die offene Straße, was von Reisenden und Wachen gleichermaßen ständige Wachsamkeit erfordert.",al={"ist fernwacht sicher","gefahr fernwacht","fernwacht gefahr"}}},fp="14,181,22.495.0,38.207.0,26.155.0,35.128.0"}
P.entries["subzone:fargodeep-mine"] = {n="Tiefenschachtmine",s="Kobolde wimmeln nun durch die Tiefenschachtmine, südlich von Goldhain im Herzen des Walds von Elwynn. Ihr Gold füllte einst Sturmwinds Schatzkammer, doch nun haben sich Kobolde in ihren Tunneln niedergelassen.",h="Kobolde wimmeln nun durch die Tiefenschachtmine, südlich von Goldhain im Herzen des Walds von Elwynn.",kw={"kerzen","elwynn","tiefenschachtmine","goldhain","goldtooth","kobold","marschall dughan","remy two times"},ang={["faction:Alliance"]="Die Tiefenschachtmine von Ungeziefer zu befreien, hilft dabei, die Nachschubwege und das Ackerland rund um Goldhain zu sichern.",["profession:Mining"]="Obwohl die Tiefenschachtmine von Plagegeistern befallen ist, bergen ihre felsigen Tunnel noch immer zugängliche Kupferadern für angehende Bergleute."},sec={{t="Eine verlorene Ader",b="Einst floss Gold aus der Tiefenschachtmine in Sturmwinds Schatzkammer. Als die militärische Präsenz des Königreichs in Elwynn schwand, wurde die abgelegene Mine verwundbar. Kobolde füllten ihre dunklen Tunnel und schufen einen Bau unter den Hügeln. Nun sorgen sich Marschall Dughan und Goldhains Behörden um das verlorene Erz und die Gefahr für nahegelegene Höfe, darunter die Anwesen der Stonefields und Maclures."},{t="Die Tiefen des Baus",b="Die Tiefenschachtmine erstreckt sich über mehrere Ebenen, deren untere Schächte tief unter den Waldboden reichen. Koboldarbeiter und Ungeziefer huschen über Holzgerüste und bewachen das Wachs und den Goldstaub, die sie zusammengetragen haben. Goldtooth, ein gerissener Koboldanführer, lauert in einer Höhle oberhalb der Haupttunnel. Er hortet Schmuckstücke, die er Reisenden und Anwohnern gestohlen hat."}},faq={{q="Warum hat Sturmwind die Tiefenschachtmine aufgegeben?",a="Sturmwind vernachlässigte die Tiefenschachtmine, als seine Truppen über die südlichen Lande verstreut kaum noch ausreichten. Die Stadtwachen konzentrierten sich auf Goldhain und die Hauptstraßen und ließen die unterirdische Mine unbewacht. Kobolde zogen ein und befestigten ihre Tunnel.",al={"warum aufgegeben","warum verließen die menschen die tiefenschachtmine","wem gehörte die tiefenschachtmine"}},{q="Warum sind die Kobolde hier so gefährlich für die örtlichen Bauern?",a="Die Tiefenschachtmine liegt zwischen den Höfen der Familien Stonefield und Maclure. Kobolde kommen aus ihren Tunneln, um Vieh, Werkzeuge und persönliche Gegenstände zu stehlen. Sie drangsalieren auch jeden, der sich dem Eingang nähert.",al={"warum sind kobolde ein problem","bedrohung durch kobolde","stonefield kobolde"}},{q="Wer ist Goldtooth?",a="Goldtooth ist ein bedeutender Kobold, der in einer Höhle in den oberen Bereichen der Tiefenschachtmine haust. Er ist dafür bekannt, Auntie Bernice Stonefields kostbare Familienhalskette gestohlen zu haben.",al={"goldtooth","wer ist goldtooth","goldtooth aufenthaltsort"}},{q="Warum wollen die Leute in Goldhain Gegenstände aus der Mine?",a="Die Leute in Goldhain sehen einen Grund, die Tiefenschachtmine von den Plagegeistern zu befreien. Remy 'Two Times' kauft geborgenen Goldstaub, während der Alchemist William Pestle Kerzenwachs der Kobolde als Reagenz verwendet. Marschall Dughan muss den Befall überwachen lassen, um Elwynn zu schützen.",al={"tiefenschachtmine quests","warum kerzen sammeln","goldstaub"}}},fx={["7f063a4c"]={q="Was ist der Tiefenschachtmine?",a="Tiefenschachtmine ist eine verlassene Goldmine im zentralen Wald von Elwynn, südlich von Goldhain. Einst eine aktive Ausgrabungsstätte, die das Königreich Sturmwind belieferte, ist sie außer Betrieb und wird nun vollständig von unterirdischen Gnollen überrannt, die sich durch ihre oberen Kammern und unteren Schächte graben.",al={"was ist tiefenschachtmine","tiefenschachtmine überblick","über tiefenschachtmine"}},e2f4f077={q="Was geschah bei Tiefenschachtmine?",a="Ursprünglich von Bergleuten aus Sturmwind betrieben, die die reichen Goldadern Elwynns abbauten, wurde die Stätte schließlich aufgegeben, als sich die Bergleute zurückzogen. In ihrer Abwesenheit zog ein Clan aggressiver Gnolle ein, die Tunnel gruben, ihre Baue errichteten und die alten Schächte in einen befestigten Unterschlupf verwandelten, der benachbarte Siedlungen bedroht.",al={"tiefenschachtmine geschichte","was geschah hier","tiefenschachtmine überlieferungen"}}},fp="14,177,11.366.0,20.348.0,41.229.0,55.195.0,17.162.0,52.252.0"}
P.entries["subzone:farstrider-lodge"] = {n="Die Weitschreiter-Lodge",s="Im südöstlichen Loch Modan heißt die Weitschreiter-Lodge Jäger und Reisende auf dem Weg in die Wildnis willkommen. Ihr hochelfischer Stil hebt sie hervor, doch auch Zwerge und Menschen leben dort.",h="Im südöstlichen Loch Modan heißt die Weitschreiter-Lodge Jäger und Reisende auf dem Weg in die Wildnis...",kw={"die weitschreiter-lodge","farstriders","hochelf","jägerlodge","loch modan","thelsamar","vyrin swiftwind"},ang={["class:Hunter"]="Als Jäger findet Ihr in der Weitschreiter-Lodge Ausbildung in Schießkunst und Wildtierausbildung, inmitten des Wildes in den umliegenden Hügeln von Loch Modan.",["race:Dwarf"]="Als Zwerg teilt Ihr die Weitschreiter-Lodge mit menschlichen Bewohnern und dem Hochelfen Vyrin Swiftwind."},sec={{t="Ein Elfenrefugium in den Bergen",b="Die Weitschreiter-Lodge sieht anders aus als die Steinbauten von Khaz Modan. Ihre Bauweise erinnert an hochelfische Handwerkskunst, doch Vyrin Swiftwind ist der einzige bekannte Hochelf, der noch dort lebt. Zwerge und Menschen wohnen an seiner Seite. Niemand weiß, wer die Lodge gegründet hat oder wann sie erbaut wurde."},{t="Eine Rast vor der Wildnis",b="In den südöstlichen Hügeln von Loch Modan bietet die Weitschreiter-Lodge Jägern und Reisenden eine Rast, bevor sie in die Wildnis aufbrechen. Dort arbeiten Jäger- und Begleitertrainer neben Händlern. Andere kommen, um Hilfe im Umgang mit der heimischen Tierwelt zu suchen."}},faq={{q="Warum steht eine Elfenlodge in Khaz Modan?",a="Die Bauweise der Weitschreiter-Lodge deutet auf hochelfische Ursprünge hin, und Vyrin Swiftwind ist ihr einziger bekannter hochelfischer Bewohner. Niemand weiß, wer sie gegründet hat, wann sie erbaut wurde oder welchem Zweck sie ursprünglich diente.",al={"warum elfengebäude loch modan","wer hat die weitschreiter-lodge erbaut","warum hochelfenlodge hier"}},{q="Leben hier noch Hochelfen?",a="Vyrin Swiftwind ist der einzige Hochelf, von dem bekannt ist, dass er in der Weitschreiter-Lodge lebt. Auch Zwerge und Menschen wohnen dort, darunter Gebirgsjäger und Waidmänner, die die Lodge instand halten und mit Reisenden Handel treiben.",al={"gibt es hier hochelfen","wer lebt in der weitschreiter-lodge","vyrin swiftwind"}},{q="Welche Dienste bietet die Weitschreiter-Lodge?",a="In der Weitschreiter-Lodge gibt es Jäger- und Begleitertrainer, Händler sowie Gesuche um Hilfe in der Wildnis von Loch Modan.",al={"was gibt es in der weitschreiter-lodge","jägertrainer loch modan"}}},fx={ede1c062={q="Was ist die Weitschreiter-Lodge?",a="Die Weitschreiter-Lodge ist ein Jagd-Außenposten, der an den südöstlichen Ufern von Loch Modan liegt. Charakteristisch durch seine elegante elfische Architektur inmitten der rauen Zwergenhügel, dient sie als friedlicher Zufluchtsort für Fährtenleser, Tierbändiger und Wanderer, die durch Khaz Modan reisen.",al={"was ist die weitschreiter-lodge","weitschreiter-lodge überlieferungen","erzähle mir von der weitschreiter-lodge"}},["65e56c06"]={q="Ist die Weitschreiter-Lodge gefährlich?",a="Die Weitschreiter-Lodge selbst ist ein sicherer Zufluchtsort für Mitglieder der Allianz und bietet Ruhe und Vorräte. Die Wildnis direkt vor ihrer Tür wimmelt jedoch von aggressiven Wildtieren und nahegelegenen feindseligen Troggs und Gnollen, die durch die Täler von Loch Modan streifen.",al={"ist die weitschreiter-lodge sicher","ist die weitschreiter-lodge feindselig","gefahr weitschreiter-lodge"}},["048016ac"]={q="Warum heißt sie die Weitschreiter-Lodge?",a="Der Name erinnert an die Farstriders, die Waldläufer von Quel'Thalas, und passt zur hochelfischen Architektur der Lodge. Die genaue Gründungsgeschichte der Lodge ist nicht belegt.",al={"warum heißt sie die weitschreiter-lodge","weitschreiter-lodge namensbedeutung","wer sind die farstriders loch modan"}}},fp="16,174,31.276.0,26.232.0,42.203.0,39.191.0,48.108.0"}
P.entries["subzone:feathermoon-stronghold-classic"] = {n="Mondfederfeste",s="Auf der Insel Sardor bewacht die Mondfederfeste die Westküste von Feralas. Generalin Shandris Mondfeder gründete sie als wichtigsten Aufmarschort und militärischen Stützpunkt der Allianz im südlichen Kalimdor.",h="Auf der Insel Sardor bewacht die Mondfederfeste die Westküste von Feralas.",kw={"allianz","mondfederfeste","feralas","die vergessene küste","insel sardor","schildwachen","shandris mondfeder"},ang={["faction:Alliance"]="Der Allianz bietet die Mondfederfeste einen sicheren Zufluchtsort, einen Handelsposten und einen Aufmarschort für Einsätze tief im südlichen Kalimdor.",["race:NightElf"]="Als Nachtelf könnt Ihr die Mondfederfeste als südlichen Militärsitz von Generalin Shandris Mondfeder und den Schildwachen betrachten, die über die uralte Wildnis wachen."},sec={{t="Bastion der Schildwachen im Süden",b="Die Mondfederfeste bewacht die Insel Sardor, direkt vor der Vergessenen Küste. Generalin Shandris Mondfeder errichtete die Festung, um die Macht der Schildwachen tief in den Süden Kalimdors zu tragen. Tyrande Wisperwind vertraut Shandris seit zehntausend Jahren als ihrer Unterführerin. Die Insel schützt die Festung vor Bestien, Ogern und Truppen der Horde, die das Festland von Feralas durchqueren."},{t="Lebensader über die Wellen",b="Boote und Hippogryphen verbinden die Mondfederfeste mit dem Festland und fernen Zentren der Allianz. Ein Passagierboot überquert den Kanal zwischen der Insel Sardor und dem Steg an der Vergessenen Küste. Für längere Reisen verbindet ein Hippogryphenhorst die Festung mit Thalanaar an der Grenze zu Tausend Nadeln, der Nijelspitze im Hochland von Desolace und Auberdine im Norden."}},faq={{q="Wie erreicht Ihr die Mondfederfeste vom Festland von Feralas aus?",a="Nehmt vom Festland von Feralas aus die Fähre von einem Steg an der Vergessenen Küste über die Meerenge, oder schwimmt durch den schmalen Kanal zur Insel Sardor. Reisende der Allianz können auch mit dem Hippogryphen fliegen, nachdem sie den Flugmeister entdeckt haben.",al={"wie zur mondfederfeste gelangen","boot zur mondfederfeste","anreise zur insel sardor"}},{q="Wer befehligt die Mondfederfeste?",a="Generalin Shandris Mondfeder befehligt die Mondfederfeste. Sie führt die Schildwachen und dient Hohepriesterin Tyrande Wisperwind seit Langem als militärische Unterführerin.",al={"wer führt die mondfederfeste","anführer der mondfederfeste","shandris mondfeder"}},{q="Warum liegt die Festung auf einer Insel statt auf dem Festland?",a="Die abgeschiedene Lage der Insel Sardor schützt die Mondfederfeste vor den zahlreichen Gefahren von Feralas, darunter angriffslustige Wildtiere, urzeitliche Ruinen und feindliche Truppen. Dieser Schutz ermöglicht es den Schildwachen, einen sicheren Rückzugsort zu halten.",al={"warum auf der insel sardor","warum eine inselfestung","hintergrund zur lage der mondfederfeste"}},{q="Wohin führen die Flugrouten von der Mondfederfeste?",a="Die Hippogryphenrouten der Mondfederfeste führen nach Auberdine in der Dunkelküste, zur Nijelspitze in Desolace und nach Thalanaar in Feralas.",al={"flugmeister der mondfederfeste","wohin fliegen die hippogryphen der mondfederfeste"}}},fp="22,194,29.354.0,25.359.0,62.210.0,36.167.0,67.207.0,47.119.0"}
P.entries["subzone:fel-rock"] = {n="Teufelsfels",s="Nördlich von Dolanaar breitet sich Verderbnis im Teufelsfels aus und bedroht Teldrassils Wälder. Lord Melenas und seine Grells haben die einst friedliche Höhle zu einer Gefahr gemacht.",h="Nördlich von Dolanaar breitet sich Verderbnis im Teufelsfels aus und bedroht Teldrassils Wälder.",kw={"dolanaar","teufelsfels","grell","lord melenas","satyr","tallonkai flinkwurzel","teldrassil"},ang={["class:Druid"]="Als Druide des Zirkels des Cenarius seht Ihr die Verderbnis des Teufelsfelsens als Wunde im jungen Weltbaum. Sie muss getilgt werden, bevor sich die Seuche ausbreitet.",["race:NightElf"]="Für die Kaldorei bedrohen Lord Melenas und seine Festung nahe Dolanaar Teldrassil und verlangen nach rascher Vergeltung."},sec={{t="Ein Hort der Verderbnis",b="Nördlich von Dolanaar liegt der Teufelsfels inmitten der bewaldeten Hügel Teldrassils. Einst friedlich, ist die Höhle nun von verdrehten Wurzeln und seltsamen Schatten erfüllt. Wilde Grells und Grellbruten streifen darin umher. Die Verderbnis dringt bis in die Äste des Weltbaums vor."},{t="Die Festung des Satyrs",b="Lord Melenas, ein Satyr, hat den Teufelsfels zu seiner Festung gemacht. Von der Höhle aus verbreitet er Verderbnis, während die Schildwachen der Nachtelfen Wache halten. Druiden in Dolanaar, darunter Tallonkai Flinkwurzel, suchen Verteidiger, um die Höhle zu reinigen und Melenas zu erschlagen. Sie müssen die Seuche aufhalten, bevor sie weiter in die umliegenden Wälder vordringt."}},faq={{q="Wo liegt der Teufelsfels?",a="Der Teufelsfels liegt in den Hügeln direkt nördlich von Dolanaar, im Herzen Teldrassils.",al={"teufelsfels lage","wo ist der teufelsfels","teufelsfels finden"}},{q="Wer herrscht über den Teufelsfels?",a="Lord Melenas, ein Satyr, gebietet über den Teufelsfels und hat Grells um sich geschart, die seinen Willen ausführen.",al={"wer ist im teufelsfels","boss des teufelsfelsens","lord melenas aufenthaltsort"}},{q="Warum sorgen sich die Druiden um den Teufelsfels?",a="Ein Satyr und von Teufelsenergie verdorbene Grells bedrohen Teldrassils natürliches Gleichgewicht. Druiden wie Tallonkai Flinkwurzel entsenden Verteidiger, um Lord Melenas zu erschlagen und die Verderbnis einzudämmen.",al={"warum den teufelsfels reinigen","teufelsfels quest","tallonkai flinkwurzel quest"}},{q="Welche Kreaturen hausen in der Höhle?",a="Aggressive Grells und Grellbruten hausen im Teufelsfels, zusammen mit ihrem Meister, dem Satyr Lord Melenas.",al={"teufelsfels kreaturen","was ist im teufelsfels","teufelsfels feinde"}}},fx={["32acb48e"]={q="Was ist der Teufelsfels?",a="Der Teufelsfels ist eine dunkle, korrumpierte Höhle, die in die Äste von Teldrassil gehauen wurde und nördlich von Dolanaar liegt. Während sie einst eine natürliche und unberührte Höhle war, hat sich im Inneren ihrer Aushöhlungen eine abscheuliche dämonische Verderbnis festgesetzt, die sie zu einem faulen Nistplatz für bösartige Grells und Satyrn gemacht hat.",al={"was ist der teufelsfels","teufelsfels überblick","teufelsfels überlieferungen"}},["3eaad617"]={q="Warum heißt er Teufelsfels?",a="Die Höhle hat ihren Namen von der abscheulichen, dämonischen Verderbnis, die ihren Stein und ihre Aushöhlungen befallen hat. Einst eine unberührte, natürliche Grotte auf Teldrassil, verdiente sie sich durch die Ankunft von Satyrn und den sich ausbreitenden Einfluss dunkler Teufelsmagie den düsteren Namen Teufelsfels.",al={"warum teufelsfels","teufelsfels namensursprung","warum heißt es teufelsfels"}}},fp="8,163,19.236.0,16.318.0,26.77.0,19.83.0,40.167.0,39.98.0"}
P.entries["subzone:felfire-hill"] = {n="Dämonenhügel",s="Im östlichen Eschental kriechen noch immer Dämonen über die verheerte Anhöhe des Dämonenhügels. Im Dritten Krieg schlugen dort Höllenbestien ein, und noch immer brennt Teufelsmacht im Boden. Wachen der Horde halten die Brücken zum Hügel nahe ihren Siedlungen.",h="Im östlichen Eschental kriechen noch immer Dämonen über die verheerte Anhöhe des Dämonenhügels.",kw={"eschental","brennende legion","dämonen","dämonenhügel","höllenbestien","splitterholzposten","holzfällerlager des kriegshymnenklans"},ang={["class:Warlock"]="Als Hexenmeister verspürt Ihr womöglich gefährliche Neugier auf die Teufelsenergie, die auf dem Bergrücken verweilt, wo die Höllenbestien der Legion landeten.",["faction:Horde"]="Als Angehörige der Horde haltet Ihr die befestigten Brücken um den Dämonenhügel, um die Verbindungsstraße zwischen dem Splitterholzposten und dem Holzfällerlager des Kriegshymnenklans vor dämonischen Überfällen zu schützen."},sec={{t="Eine Narbe der Brennenden Legion",b="Im Dritten Krieg schickte die Brennende Legion flammende Meteore über Kalimdor, die furchterregende Höllenbestien trugen. Mehrere schlugen auf diesem Bergrücken in Eschental ein. Ihre Feuer verbrannten den uralten Wald und verdarben die Erde. Die Legion fiel am Hyjal, doch Dämonen, die ihre Niederlage überlebten, durchstreifen noch immer die versengten Hänge. Teufelsenergie durchtränkt das Land, das sie heimsuchen."},{t="Die Übergänge bewachen",b="Der Dämonenhügel liegt südöstlich des Splitterholzpostens und südwestlich des Holzfällerlagers des Kriegshymnenklans, nahe wichtiger Unternehmungen der Horde. Verbliebene Dämonen drohen in den umliegenden Wald vorzudringen. Deshalb errichteten Streitkräfte der Horde befestigte Barrikaden und Wachtürme an beiden Brücken zum Hügel. Die Wachen halten die Kreaturen in ihrer verheerten Zuflucht fest."}},faq={{q="Warum ist der Dämonenhügel verderbt?",a="Im Dritten Krieg regneten furchterregende Höllenbestien der Brennenden Legion vom Himmel und schlugen auf dem Dämonenhügel ein. Ihr Einschlag und die Verseuchung durch Teufelsenergie verbrannten den Elfenwald und hinterließen zerklüfteten Fels und dämonische Energien, die nie verflogen.",al={"warum ist der dämonenhügel grün","geschichte des dämonenhügels","was geschah mit dem dämonenhügel"}},{q="Welche Kreaturen leben auf dem Dämonenhügel?",a="Überlebende Dämonen und Höllenkonstrukte aus der Invasion der Legion im Dritten Krieg bevölkern den Dämonenhügel. Sie bleiben Sterblichen gegenüber feindselig, die sich ihrem verderbten Boden nähern.",al={"monster am dämonenhügel","gegner am dämonenhügel"}},{q="Warum hat die Horde die Brücken hier befestigt?",a="Der Dämonenhügel liegt zwischen dem Splitterholzposten und dem Holzfällerlager des Kriegshymnenklans. Befehlshaber der Horde befestigten beide Brücken, damit umherstreifende Dämonen nicht ausbrechen und nahe Lager, Versorgungskonvois und Holzfällerbetriebe überrennen.",al={"brückenwachen der horde dämonenhügel","warum bewachen orcs den dämonenhügel"}},{q="Ist der Dämonenhügel mit den Nachtelfen verbunden?",a="Der Dämonenhügel liegt nordöstlich des Dor'danil-Grabhügels auf Boden, der einst zum heiligen Wald von Eschental gehörte. Seine sich ausbreitende dämonische Verderbnis und umherstreifende Unholde gefährden die nahen Ruhestätten und die umliegende Wildnis.",al={"dor'danil dämonenhügel","grabhügel dämonen"}}},fx={["1806e9cd"]={q="Was ist der Dämonenhügel?",a="Der Dämonenhügel ist eine verheerte Anhöhe im zentralen Eschental, südöstlich des Splitterholzpostens und südwestlich des Holzfällerlagers des Kriegshymnenklans gelegen. Im Gegensatz zu den üppigen Wäldern, die ihn umgeben, dient diese vernarbte Anhöhe als verschanzter dämonischer Brückenkopf innerhalb des Waldes.",al={"was ist der dämonenhügel","dämonenhügel informationen","wo ist der dämonenhügel"}},["168acc03"]={q="Was geschah am Dämonenhügel?",a="Während des Dritten Krieges brachte die Brennende Legion Zerstörung über das Eschental. Der Dämonenhügel markiert die genaue Absturzstelle, an der mehrere flammende Infernos vom Himmel herabstürzten, die Erde versengten und die Landschaft in eine dauerhafte Festung für verbliebene Dämonen korrumpierten.",al={"dämonenhügel geschichte","was geschah hier","dämonenhügel dritter krieg"}},d9143043={q="Ist der Dämonenhügel gefährlich?",a="Er ist außergewöhnlich gefährlich. Der Hügel wimmelt von feindseligen Dämonen, die jeden Reisenden bedrohen, der durch das zentrale Eschental zieht. Die Gefahr ist so schwerwiegend, dass die Horde aktiv beide Brücken, die in Richtung des Gebiets führen, befestigt, um Siedlungen wie den Splitterholzposten vor dämonischen Einfällen zu schützen.",al={"ist der dämonenhügel gefährlich","dämonenhügel gefahr","bedrohung dämonenhügel"}},["4c2c069f"]={q="Warum heißt es Dämonenhügel?",a="Der Hügel erhielt seinen grimmigen Namen durch die katastrophale Ankunft der Infernals der Brennenden Legion während des Dritten Krieges. Ihr feuriger Abstieg verwüstete den Boden mit dämonischem Teufelsfeuer und hinterließ eine geschwärzte Erde, die dauerhaft von verderblichen, brennenden Energien durchdrungen ist.",al={"warum dämonenhügel","herkunft des namens dämonenhügel","name von dämonenhügel"}}},fp="12,232,28.360.0,22.340.0,30.236.0,36.177.0,43.222.0,45.219.0"}
P.entries["subzone:felpaw-village"] = {n="Revier der Teufelspfoten",s="Im Revier der Teufelspfoten bewachen verderbte Furbolgs den nördlichen Pfad des Teufelswalds zur Holzschlundfeste. Dämonische Verderbnis hat die Siedlung gegen alle Außenstehenden aufgebracht.",h="Im Revier der Teufelspfoten bewachen verderbte Furbolgs den nördlichen Pfad des Teufelswalds zur...",kw={"verderbnis","deadwood","felpaw","revier der teufelspfoten","teufelswald","furbolg","timbermaw"},ang={["class:Druid"]="Als Druide, der sich der Wiederherstellung der natürlichen Ordnung verschrieben hat, seht Ihr in den gefallenen Deadwood des Reviers der Teufelspfoten womöglich eine tragische Mahnung daran, dass das Gift der Legion noch immer in heiligen Wäldern wirkt.",["race:NightElf"]="Die Night Elves zählten die Furbolgs einst zu ihren treuen Verbündeten. Für Euch machen der Wahnsinn und die rituelle Entwürdigung der Deadwood bei Felpaw diesen Verlust besonders bitter."},sec={{t="Eine Bastion der Verderbnis",b="Verderbte Deadwood-Furbolgs halten den Nordrand des Teufelswalds im Revier der Teufelspfoten besetzt. Einst sanftmütige Hüter des Waldes, verfielen sie der dämonischen Verderbnis, die während des Dritten Krieges entfesselt wurde, und verwilderten. Primitive Hütten und Ritualtotems füllen ihre verseuchte Enklave. Nahe dem Tunneleingang zur Holzschlundfeste greifen feindselige Krieger jeden an, der sich nähert."},{t="Ein Dorn neben der Holzschlundfeste",b="Am nördlichen Ausgang des Teufelswalds wachen Timbermaw-Wachen über die wenigen unverdorbenen Furbolgs, die in der Region verblieben sind. Sie trauern um ihre gefallenen Vettern, bleiben jedoch wachsam. Die Deadwood bedrohen den Durchgang zur Holzschlundfeste und könnten die Verderbnis durch deren Tore nach Mondlichtung und Winterquell tragen. Deshalb rufen die Wachen Reisende dazu auf, ihre Reihen zu lichten und ihre Ritualfetische zu beschlagnahmen."}},faq={{q="Wer lebt im Revier der Teufelspfoten?",a="Deadwood-Furbolgs leben im Revier der Teufelspfoten. Die dämonische Verderbnis, die sich im Teufelswald ausbreitet, hat den örtlichen Stamm erfasst.",al={"revier der teufelspfoten bewohner","wer ist bei felpaw","deadwood-furbolgs nördlicher teufelswald"}},{q="Warum sind die Furbolgs hier feindselig?",a="Dämonische Energien, die Boden, Wasser und Tierwelt des Teufelswalds vergiften, trieben die Deadwood-Furbolgs in den Wahnsinn. Sie sehen Außenstehende als Feinde an und sind keiner Vernunft mehr zugänglich.",al={"warum greifen deadwood an","sind felpaw-furbolgs freundlich","warum sind bären im teufelswald wütend"}},{q="Wo liegt das Revier der Teufelspfoten?",a="Das Revier der Teufelspfoten liegt am äußersten Nordende des Teufelswalds, entlang der Straße zum südlichen Haupteingang der Holzschlundfeste.",al={"revier der teufelspfoten kartenposition","wo ist das revier der teufelspfoten","wie kommt man zu felpaw"}},{q="Welche Verbindung hat das Revier der Teufelspfoten zur Holzschlundfeste?",a="Die unverdorbenen Timbermaw beobachten das Revier der Teufelspfoten von ihren nahe gelegenen Toren aus. Die Deadwood bedrohen den Durchgang zwischen Teufelswald, Winterquell und Mondlichtung. Die Timbermaw belohnen Außenstehende, die die feindseligen Reihen des Dorfes lichten und Ritualfedern der Deadwood bergen.",al={"verbindung zu timbermaw","holzschlundfeste ruf felpaw","timbermaw deadwood"}}},fp="14,152,26.343.0,29.377.0,28.116.0,34.156.0,32.113.0,49.259.0"}
P.entries["subzone:felstone-field"] = {n="Teufelssteinfeld",s="Die Verderbnis der Geißel hat das Teufelssteinfeld im Nordwesten der Westlichen Pestländer erfasst. Einst Ackerland für Lordaeron, liegt es nun in Trümmern unter einem Pestkessel, der giftige Dämpfe in die Luft speit.",h="Die Verderbnis der Geißel hat das Teufelssteinfeld im Nordwesten der Westlichen Pestländer erfasst.",kw={"kessellord gallenschlund","teufelssteinfeld","janice felstone","jeremiah payson","lordaeron","ol' emma","pestkessel","scharlachroter kreuzzug","westliche pestländer"},ang={["faction:Alliance"]="Als Überlebender der Allianz in Sturmwind seht Ihr im Teufelssteinfeld vielleicht verlorenes Land Eurer Vorfahren und vertriebene Verwandte. Ol' Emma erhebt noch immer Anspruch auf ein verwüstetes Erbe im Norden.",["race:Undead"]="Als Verlassener könnt Ihr in diesem zerstörten Hof eine Erinnerung an das Leben sehen, das Euer Volk einst in Lordaeron führte. Verwandte wie Jeremiah Payson überlebten nur durch den Untod."},sec={{t="Ein verseuchtes Gehöft",b="Das Teufelssteinfeld versorgte Lordaeron einst als friedlicher Familienhof mit Nahrung. Als die Seuche durch den Norden fegte, nahmen der Kult der Verdammten und die Geißel das Gehöft rasch ein. Totes Unkraut und Fäulnis bedecken heute die Felder. Im Herzen des Hofes stößt ein gewaltiger Pestkessel unablässig üble Dämpfe in den Himmel. Kessellord Gallenschlund bewacht ihn mit Skelettschindern, Zauberern und unersättlichen Ghulen."},{t="Verweilende Geister und Eiferer",b="Zwischen den Ruinen bleiben Spuren der lebenden Welt zurück. Im nordöstlichen Bauernhaus wandert der Geist von Janice Felstone voller Trauer durch die Überreste ihres einstigen Heims. Patrouillen des Scharlachroten Kreuzzugs durchstreifen die Grenzen des Anwesens. Sie vernichten gewaltsam jeden Untoten, den sie finden, und strecken Außenstehende nieder, die ihrem Kreuzzug zu nahe kommen."}},faq={{q="Was bewirkt der Kessel in der Mitte des Feldes?",a="Der Kessel ist eine Seuchenmaschine der Geißel, die Pestilenz im umliegenden Land und in der Luft verbreitet. Er verdirbt den Boden und erweckt die Toten. Kessellord Gallenschlund bewacht ihn mit Skelettdienern und Ghulen.",al={"felstone kessel","warum gibt es dort einen kessel","pestkessel felstone"}},{q="Wer ist der Geist im Bauernhaus?",a="Der Geist ist Janice Felstone, die frühere Herrin des Gehöfts. Sie starb, als die Geißel das Gebiet überrannte, und ihr Geist bleibt an das Haus ihrer Familie gebunden, unfähig oder unwillig, Ruhe zu finden.",al={"janice felstone","geist im felstone-haus","wer ist im haus"}},{q="Warum patrouillieren Scharlachrote Kreuzfahrer auf dem Hof?",a="Der Scharlachrote Kreuzzug entsendet aggressive Stoßtrupps in die Westlichen Pestländer, um die Geißel zu vernichten. Reisende der Horde und der Allianz, die unerlaubt ihr Gebiet betreten, betrachten sie als mögliche Seuchenträger oder Feinde und greifen sie sofort an.",al={"scharlachroter kreuzzug felstone","kreuzfahrer beim teufelssteinfeld"}},{q="Wer besitzt eigentlich die Besitzurkunde für das Teufelssteinfeld?",a="Jeremiah Payson in Unterstadt und Ol' Emma in Sturmwind behaupten beide, ihre Schwester Janice Felstone habe ihnen die Besitzurkunde gegeben. Ob zwei Urkunden ausgestellt wurden oder das Chaos der Seuche die Erbfolge zwischen lebenden und untoten Familienmitgliedern durcheinanderbrachte, bleibt ein Rätsel.",al={"teufelssteinfeld besitzurkunde","wem gehört felstone","better late than never besitzurkunde"}}},fp="14,199,20.380.0,28.319.1,54.209.0,38.195.0,52.220.0,45.260.1"}
P.entries["subzone:fenris-isle"] = {n="Insel Fenris",s="Auf der Insel Fenris halten Rot Hide-Gnolle und ein abtrünniger Nekromant der Geißel eine Festung im Lordameresee vor dem Silberwald.",h="Auf der Insel Fenris halten Rot Hide-Gnolle und ein abtrünniger Nekromant der Geißel eine Festung im...",kw={"insel fenris","burg fenris","der lordameresee","rot hide","silberwald","thule ravenclaw"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr Agenten der Verlassenen helfen, die Rot Hide-Gnolle zu untersuchen und ihre Festung auf der anderen Seite des Lordameresees anzugreifen.",["race:Undead"]="Als Verlassener seht Ihr die Insel Fenris als unerträgliche Bastion der Geißel direkt vor Eurer Haustür. Unablässige Angriffe sind nötig, um Thule Ravenclaws Rot Hide-Gnolle daran zu hindern, die östlichen Gewässer des Silberwalds zu überrennen."},sec={{t="Eine gefallene Festung im See",b="Burg Fenris bewachte einst Lordaerons militärischen Außenposten auf der Insel Fenris. Als die Geißel über das nördliche Lordaeron hinwegfegte, wurde die Garnison niedergemetzelt oder floh ins Exil. Die Toten nahmen die Insel in Besitz, und später machten Rot Hide-Gnolle sie zu ihrer Festung. Ihr primitives Reich breitet sich nun an den Ufern des Sees aus. Die Verlassenen des Silberwalds beobachten die Insel genau, denn sie fürchten, dass ihre verschanzten Bewohner ihre nördlichen Ländereien bedrohen."},{t="Der Herr von Burg Fenris",b="Thule Rabenklaue befehligt Burg Fenris aus ihren zerfallenden Steinhallen heraus. Einst mit den Kirin Tor verbündet, wandte sich der Nekromant den dunklen Künsten der Geißel zu und unterwarf die einheimischen Gnolle seinem Willen. Seine Zauberei erweckt ihre gefallenen Artgenossen und stärkt die Insel gegen Eindringlinge.\n\nVon diesem abgelegenen Zufluchtsort aus überwacht Thule die Fährüberfahrten des Sees. Späher der Verlassenen und Streitkräfte der Horde schlagen zu, bevor eine größere Bedrohung entstehen kann, um seine Herrschaft über die Inselgruppe zu brechen."}},faq={{q="Was ist die Insel Fenris?",a="Die Insel Fenris liegt im Lordameresee vor der Ostküste des Silberwalds. Vor dem Dritten Krieg war sie eine Festung des Königreichs Lordaeron. Jetzt ist die Insel von pestverseuchten Gnollen und Dienern der Geißel befallen.",al={"wo liegt die insel fenris","geschichte der insel fenris","was ist diese insel"}},{q="Wer kontrolliert die Insel Fenris derzeit?",a="Rot Hide-Gnolle besetzen die Insel Fenris und halten Burg Fenris als ihre Festung. Ermittler der Verlassenen suchen nach dem Ursprung der wachsenden Bedrohung.",al={"wer herrscht über die insel fenris","bosse der insel fenris","wer lebt auf der insel fenris"}},{q="Was geschah mit den Menschen, die früher hier lebten?",a="Als die Geißel Lordaeron während des Dritten Krieges überrannte, wurden die menschlichen Verteidiger und Bewohner von Burg Fenris ermordet oder vertrieben. Die Festung lag in Trümmern, bis Gnolle und Nekromanten ihre verlassenen Wehrmauern in Besitz nahmen.",al={"was geschah mit den menschen von burg fenris","wer erbaute burg fenris"}},{q="Warum will die Horde die Insel angreifen?",a="Die Verlassenen sehen die verschanzten Rot Hide-Gnolle als Bedrohung für den Silberwald und die nahe gelegene Fährverbindung. Ihre Agenten suchen Hilfe, um die feindlichen Streitkräfte auf der Insel zu untersuchen und ihre Vorhaben zu stören.",al={"geschichte von sturm auf die insel fenris","warum greift die horde die insel fenris an","verlassene insel fenris"}}},fx={["5a4e2fe3"]={q="Warum liegt Burg Fenris in Trümmern?",a="Burg Fenris diente einst als florierende militärische Festung für das Königreich Lordaeron. Als die Geißel während des Dritten Krieges über die nördlichen Reiche hinwegfegte, fiel die Festung. Ihre Verteidiger und Bewohner wurden abgeschlachtet oder in die Flucht geschlagen, sodass der Außenposten dem Verfall überlassen blieb, bis Thule Rabenklaue und seine Gnolle die Trümmer für sich beanspruchten.",al={"warum ist insel fenris verlassen","burg fenris in ruinen","was zerstörte burg fenris"}},["115572ef"]={q="Ist die Insel Fenris gefährlich?",a="Die Insel Fenris ist äußerst gefährlich. Die Insel ist vollkommen von Rotpelzgnollen verseucht und wird von dem abtrünnigen Zauberer Thule Rabenklaue beherrscht. Umgeben vom trüben Wasser des Lordameresee, sieht sich jeder Entdecker, der die Insel betritt, aggressiven, kranken Bestien und dunkler Zauberei innerhalb der baufälligen Festung gegenüber.",al={"ist insel fenris sicher","gefahren der insel fenris","bedrohungen auf der insel fenris"}}},fp="11,121,31.436.0,25.468.1,20.210.0,35.138.0,50.218.0,52.194.0"}
P.entries["subzone:fenris-keep"] = {n="Burg Fenris",s="Auf der Insel Fenris, abgeschieden im Herzen des Lordameresees, gehört Burg Fenris nun der Geißel. Thule Rabenklaue hält die steinerne Festung, die einst Truppen Lordaerons beherbergte.",h="Auf der Insel Fenris, abgeschieden im Herzen des Lordameresees, gehört Burg Fenris nun der Geißel.",kw={"insel fenris","burg fenris","lordaeron","der lordameresee","rot hide","geißel","silberwald","thule ravenclaw"},ang={["class:Mage"]="Als Magier könnt Ihr erkennen, wie Thule Rabenklaue die Lehren der Kirin Tor verraten hat. Er stellte Dalarans arkanes Wissen in den Dienst der dunklen Künste der Geißel.",["faction:Horde"]="Für die Horde und besonders die Verlassenen bleibt Burg Fenris eine Bastion der Geißel. Sie müssen sie auslöschen, um den Silberwald und die Wasserwege des Lordameresees zu sichern."},sec={{t="Die Geißel am Lordameresee",b="Thule Rabenklaue herrscht über Burg Fenris und bedroht die Verlassenen im Silberwald. Von der Festung aus schickt er Rot Hide-Gnolle gegen jeden, der einen Fuß auf die Insel setzt. Die Insel Fenris liegt nur wenige Meilen über das Wasser von der Grenze zu Tirisfal entfernt. Deshalb entsenden die Verlassenen aus dem Grabmal und Unterstadt Streiter, um die Verteidigung der Burg zu durchbrechen und die Herrschaft des abtrünnigen Nekromanten zu beenden."},{t="Eine gefallene Bastion Lordaerons",b="Vor dem Dritten Krieg bewachte Burg Fenris den Lordameresee für das Königreich Lordaeron. Eine beträchtliche Streitmacht hielt die Inselfestung. Als die Geißel über das Land hinwegfegte, fiel die Burg mit dem Rest des Reiches.\n\nThule Rabenklaue, ein ehemaliger Zauberer der Kirin Tor, der seinen Orden verriet, nahm die Festung ein. Er schloss sich der Geißel an und unterwarf die Gnolle der Insel mit Nekromantie, wodurch sie zum unersättlichen Rot Hide-Rudel wurden. Nun hat er sich tief in den steinernen Hallen der Burg verschanzt."}},faq={{q="Was ist Burg Fenris?",a="Burg Fenris ist eine abgelegene Steinfestung auf der Insel Fenris im Lordameresee. Einst eine militärische Bastion des gefallenen Königreichs Lordaeron, wird sie heute von der untoten Geißel gehalten.",al={"burg fenris hintergrundgeschichte","was ist burg fenris","burg fenris"}},{q="Wer herrscht derzeit über Burg Fenris?",a="Thule Rabenklaue herrscht über Burg Fenris. Der ehemalige Magier der Kirin Tor verriet die Lebenden, um der Geißel zu dienen, und befehligt aus der Festung vom Untod verdorbene Rot Hide-Gnolle.",al={"wer kontrolliert burg fenris","burg fenris boss","herr der insel fenris"}},{q="Warum gibt es Gnolle in Burg Fenris?",a="Thule Rabenklaue unterwarf die einheimischen Gnolle mit dunkler Magie und Krankheit und verwandelte sie in Rot Hide-Gnolle. Sie bewachen die Burg und die umliegende Insel als seine treuen Stoßtruppen.",al={"rot hide-gnolle fenris","warum gnolle in der burg","fenris gnolle"}},{q="Warum ist Burg Fenris für die Verlassenen von Bedeutung?",a="Burg Fenris bietet der Geißel einen gut zu verteidigenden Stützpunkt am Lordameresee. Sie bedroht die Bewegungsfreiheit der Verlassenen im östlichen Silberwald und in Tirisfal, weshalb Sylvanas' Streitkräfte einen Geißelkommandanten so nahe an ihren Grenzen nicht ungehindert gewähren lassen können.",al={"warum greifen verlassene fenris an","verlassene burg fenris","unterstadt fenris"}}},fx={c58313a0={q="Was ist mit Burg Fenris geschehen?",a="Burg Fenris besaß einst einen enormen strategischen Wert und beherbergte eine beträchtliche Garnison des Militärs des Königreichs Lordaeron inmitten der Gewässer des Lordameresee. Als der Dritte Krieg das Land überrollte, überrannte die Geißel die Festung. Anstatt gereinigt zu werden, fiel sie in die Hände von Thule Rabenklaue, einem abtrünnigen Magier des Kirin Tor, der sich mit dem Lichkönig verbündete und die örtlichen Gnollstämme in gefräßige, untote Diener verwandelte.",al={"geschichte von burg fenris","was passierte in burg fenris","wissen über burg fenris"}},["07ecc870"]={q="Warum ist Burg Fenris verfallen?",a="Burg Fenris verfiel, als die Geißel während des Dritten Krieges die Verteidigung von Lordaeron dezimierte. Die Militärgarnison, die einst die Festung instand hielt, wurde abgeschlachtet, wodurch die Bauwerke ungepflegt blieben und verrotteten. Heute steht sie als verfallende Festung da, die von nekromantischer Magie und wilden, fleischfressenden Gnollen beherrscht wird.",al={"warum ist burg fenris verlassen","wer zerstörte burg fenris","trümmer von burg fenris"}},["6ae37309"]={q="Ist Burg Fenris gefährlich?",a="Sie ist außerordentlich gefährlich. Die Festung und die umliegende Insel wimmeln von Rotpelzgnollen, die jeden hungrig angreifen, der ihre Ufer betritt. Innerhalb der Festung selbst residiert Thule Rabenklaue, ein gefährlicher Nekromant, der dunkle Magie über seine monströsen Diener ausübt.",al={"gefahr burg fenris","ist burg fenris sicher","wie gefährlich ist burg fenris"}}},fp="11,175,24.370.1,29.479.1,20.177.0,32.172.1,40.177.1,43.244.0"}
P.entries["subzone:feral-scar-vale"] = {n="Wildschrammtal",s="Im westlichen Feralas halten Feral Scar-Yetis eine felsige Schlucht tief in der oberen Wildnis. Ihre Höhlen liegen jenseits der Waldpfade, wo Reisenden Gefahr droht.",h="Im westlichen Feralas halten Feral Scar-Yetis eine felsige Schlucht tief in der oberen Wildnis.",kw={"wildschrammtal","feralas","die obere wildnis","leitroboter","oox-22/fe","yeti"},ang={["class:Hunter"]="Als Jäger könnt Ihr Feral Scar-Yetis aufspüren, die an den Klippen umherstreifen, und Euer Geschick bei der Großwildjagd unter dem Blätterdach der oberen Wildnis erproben.",["profession:Engineering"]="Ein gestrandeter gnomischer Leitroboter liegt in den Yetitunneln. Als Ingenieur könnt Ihr ihn mithilfe einer Notfunkbake sicher in die Zivilisation zurückbringen."},sec={{t="Bau der Yetis",b="Seit Generationen halten die urtümlichen Feral Scar-Yetis die Höhlen des Wildschrammtals. Anders als die Yetis von Alterac und Dun Morogh haben sich diese Unholde an die feuchte Wildnis von Feralas angepasst. Sie verteidigen ihr Höhlennetz erbittert und bewahren Knochentrophäen auf. Eindringlinge werden aus ihren Jagdgründen vertrieben."},{t="Kuriositäten in den Höhlen",b="Gnomische Notsignale haben bisweilen in die tieferen Höhlen des Wildschrammtals geführt. Verlorene Geräte sitzen dort zwischen den Yetis fest, darunter auch robotische Vermessungshühner. Sie warten darauf, aktiviert und geborgen zu werden."}},faq={{q="Welche Kreaturen leben im Wildschrammtal?",a="Feral Scar-Yetis beherrschen das Tal. Diese gewaltigen Raubtiere verteidigen ihr Revier, leben in den felsigen Höhlen und durchstreifen den umliegenden Wald.",al={"wildschrammtal gegner","was gibt es im wildschrammtal","kreaturen im tal"}},{q="Wo liegt das Wildschrammtal?",a="Das Wildschrammtal liegt im westlichen Feralas, in der oberen Wildnis und südlich der Hauptstraße unter dem Blätterdach des Regenwalds.",al={"wildschrammtal lage","wo liegt das wildschrammtal","wie das wildschrammtal finden"}},{q="Warum gibt es Yetis in einem üppigen Regenwald?",a="Obwohl Yetis meist mit verschneiten Bergen verbunden werden, leben auch in Kalimdors uralter Wildnis Feral Scar-Yetis. Diese besondere Art gedeiht seit Generationen in dicht bewaldeten Tälern.",al={"warum yetis in feralas","dschungelyetis","feralas yeti hintergrundgeschichte"}},{q="Was ist das mechanische Huhn in der Höhle?",a="Homing Robot OOX-22/FE ist ein mechanisches Vermessungshuhn, das von gnomischen Ingenieuren gebaut wurde. Es stürzte in einer Höhle tief im Tal ab und blieb hinter den Linien der Yetis liegen.",al={"oox-22/fe","roboterhuhn feralas","leitroboter wildschrammtal"}}},fp="15,155,17.292.0,24.217.0,47.131.0,33.125.0,41.174.0,47.159.0"}
P.entries["subzone:field-of-giants"] = {n="Feld der Riesen",s="Im südlichen Brachland grasen gewaltige Bestien auf dem Feld der Riesen, während Silithiden die Ebene bedrohen. Das wilde Land erstreckt sich von Camp Taurajo bis zu den Sümpfen der Düstermarschen.",h="Im südlichen Brachland grasen gewaltige Bestien auf dem Feld der Riesen, während Silithiden die Ebene...",kw={"brachland","camp taurajo","feld der riesen","goldstraße","kodo","korran","ruga rachtotem","silithiden","donnerechse"},ang={["class:Hunter"]="Donnerechsen und gewaltige Kodos durchstreifen das Feld der Riesen und machen es zu einem der besten Jagdgründe des Brachlands für Jäger, die mächtige Bestien suchen.",["faction:Horde"]="Silithidenbauten nahe der Straße zwischen Camp Taurajo und den Düstermarschen bedrohen Reisen durch das Brachland. Anführer in der ganzen Region rufen nach Spähern."},sec={{t="Wildes Grenzland im Süden",b="Die südliche Goldstraße durchquert das Feld der Riesen, fernab des besser verteidigten Nordens. Ihre hölzernen Wachtürme stehen weitgehend verlassen da, und große Herden durchstreifen die offenen Ebenen. Jäger und Naturforscher kommen, um Kalimdors gewaltige Bestien zu sehen, doch hier lauert auch Gefahr. Zwergische Ausgräber aus Bael Modan graben im Süden rücksichtslos, während eine finsterere Bedrohung begonnen hat, sich unter der Erde vorzugraben."},{t="Der schleichende Schwarm",b="Silithidenbauten sind jüngst überall auf dem Feld der Riesen aus dem Boden hervorgebrochen. Sie markieren die nördlichste bekannte Sichtung dieser unersättlichen Kreaturen in Kalimdor. Ihre seltsamen Hügel und aggressiven Schwärme haben die Horde alarmiert. Korran, ein Trollspäher vom Wegekreuz, und Ruga Rachtotem, ein Taurenkrieger in Camp Taurajo, drängen Abenteurer, die Bauten zu untersuchen und herauszufinden, was diese Schrecken so weit aus den tiefen Wüsten herlockt."}},faq={{q="Warum heißt es Feld der Riesen?",a="Die Ebene verdankt ihren Namen ihrer gewaltigen Tierwelt. Große Herden hoch aufragender Kodos und Donnerechsen grasen hier neben anderen riesigen Bestien Kalimdors.",al={"feld der riesen namensherkunft","warum feld der riesen"}},{q="Was sind das für Insektenhügel im Boden?",a="Diese Hügel gehören Silithiden, insektenartigen Raubtieren, die sich aus den Tiefen der Erde nach oben gegraben haben. Ihre Bauten sind die nördlichsten, die in Kalimdor entdeckt wurden, und sie bedrohen Reisende und die heimische Tierwelt.",al={"insektenhügel brachland","insekten im südlichen brachland","was sind silithiden"}},{q="Wer lebt in der Nähe des Felds der Riesen?",a="Auf der Ebene selbst liegen nur wenige Siedlungen, doch der Orcschamane Brine lebt auf einem südlichen Höhenzug. In der Nähe beobachtet der vertriebene Gann Steinkeil aus seinem Exil die zwergische Ausgrabung in Bael Modan und schmiedet Pläne gegen sie.",al={"wer lebt hier","feld der riesen npcs"}},{q="Warum sind die Wachtürme entlang der Straße verlassen?",a="Die Horde konzentriert ihre Streitkräfte entlang der nördlichen Goldstraße nahe dem Wegekreuz, sodass weniger Patrouillen für die südlichen Gebiete bleiben. Angesichts der Bedrohung durch Silithiden und aggressive Wildtiere wurden die Türme vernachlässigt.",al={"verlassene türme goldstraße","südliches brachland wachtürme"}}},fx={c3e59f7c={q="Was ist das Feld der Riesen?",a="Das Feld der Riesen ist eine ausgedehnte Ebene im südlichen Brachland, die zwischen Camp Taurajo und der Straße Richtung Düstermarschen liegt. Durchzogen vom südlichen Abschnitt der Goldstraße, sind diese sonnenverbrannten Ebenen berühmt für die riesigen Herden von Donner-Echsen, Kodos und anderen kolossalen Bestien aus Kalimdor, die frei über die Savanne ziehen.",al={"feld der riesen übersicht","was ist das für ein ort feld der riesen","über das feld der riesen"}},["2ebbbb7d"]={q="Was ist die Geschichte des Feld der Riesen?",a="Das Feld der Riesen war lange Zeit ein wildes Revier für die größte Megafauna Kalimdors und wurde einst regelmäßig entlang der südlichen Goldstraße bewacht, bevor seine Verteidigungstürme vernachlässigt wurden. In jüngster Zeit ist die Landschaft unruhig geworden, da eindringende Silithid-Schwärme riesige Nester unter der Erde gegraben haben und nahegelegene Zwergenausgräber bei Bael Modan örtliche Stämme wie das Volk von Gann Steinkeil vertrieben haben.",al={"geschichte des feld der riesen","was geschah am feld der riesen","feld der riesen vergangenheit"}},b9c947c6={q="Ist das Feld der Riesen gefährlich?",a="Es ist ziemlich gefährlich. Neben den turmhohen, aggressiven Donner-Echsen und schweren Kodoherden, die über die Ebenen trampeln, ist kürzlich ein aggressiver Silithid-Bau unter der roten Erde ausgebrochen. Reisende auf der südlichen Goldstraße finden kaum Schutz, da die regionalen Wachtürme leer und unbewacht stehen.",al={"gefahr am feld der riesen","wie gefährlich ist das feld der riesen","ist es hier sicher"}}},fp="15,173,28.392.0,18.436.0,37.156.0,40.203.0,35.200.0,49.210.0"}
P.entries["subzone:fire-plume-ridge"] = {n="Feuersäulengrat",s="Der Feuersäulengrat brennt im Herzen des Kraters von Un'Goro. Sein Magma wärmt das Becken und speist die Geysire und Dampfbecken. Feuerelementare durchstreifen seine Hänge.",h="Der Feuersäulengrat brennt im Herzen des Kraters von Un'Goro.",kw={"blazerunner","elementare","feuersäulengrat","lava","ringo","ungoro","vulkan"},ang={["class:Shaman"]="Als Schamane seht Ihr Feuergeister über den Grat toben. Sie offenbaren die elementaren Kräfte unter Kalimdors Erdkruste.",["profession:Mining"]="Als Bergmann könnt Ihr in den Felsklüften und an den hitzegehärteten Hängen des Grats freiliegende Mineralien finden. Dense Thorium entstand dort unter vulkanischem Druck."},sec={{t="Die Feuerstelle des Kraters",b="Lava fließt vom Feuersäulengrat hinab in das Dschungelbecken des Kraters von Un'Goro. Unter dem Gestein verzweigen sich Magmakanäle im Boden und speisen die Geysire und heißen Quellen. Die Hitze ist gewaltig, daher brauchen Reisende beim Aufstieg auf den Grat Wasser und Schatten."},{t="Ein Hort der Elementare",b="Feuerelementare durchstreifen die glühenden Lavaströme, angezogen von der Hitze tief unter dem Grat. Blazerunner haust in einer Höhle nahe dem Gipfel und herrscht über die Elementare von Un'Goro. Wer zum Gipfel hinaufsteigt, begegnet sengender Hitze und Geistern, die ihre feurige Heimat verteidigen."}},faq={{q="Was ist das für ein Vulkan in der Mitte des Kraters von Un'Goro?",a="Der Feuersäulengrat erhebt sich im Zentrum des Kraters von Un'Goro. Seine Magmakanäle wärmen das Becken und speisen seine Geysire und Dampfquellen.",al={"name des vulkans in ungoro","vulkan im zentrum von ungoro","feuersäulengrat lage"}},{q="Wer herrscht über die Elementare am Feuersäulengrat?",a="Blazerunner herrscht von einer Höhle nahe dem Gipfel aus über die Feuerelementare von Un'Goro.",al={"boss des feuersäulengrats","blazerunner aufenthaltsort","feuerelementarboss ungoro"}},{q="Warum sitzt ein Forscher im Inneren des Grats fest?",a="Ringo, ein mit den Goblins verbündeter Abenteurer, betrat den Vulkan, um ihn zu erkunden. Schwere Hitzeerschöpfung ließ ihn in einer Höhle im Süden festsitzen, unfähig, allein zu entkommen.",al={"wer sitzt im feuersäulengrat fest","ringo ungoro","verirrter kerl im vulkan"}},{q="Wie beeinflusst der Vulkan den Rest von Un'Goro?",a="Vom Feuersäulengrat aus verlaufen Magmakanäle unter dem Kraterboden von Un'Goro. Sie erwärmen die Erde und speisen die Geysire, Thermalöffnungen und Dampfbecken.",al={"warum ist ungoro so heiß","geothermische aktivität im krater","oberflächennahe magmaadern ungoro"}}},fp="16,147,24.234.0,19.255.0,52.129.0,45.72.0,51.151.0,48.146.0"}
P.entries["subzone:fire-scar-shrine"] = {n="Schrein des Sengenden Feuers",s="Am Schrein des Sengenden Feuers hat Teufelsverderbnis die alte Kultstätte der Nachtelfen südwestlich von Astranaar erfasst. Nun sammeln sich Dämonen zwischen den Altarsteinen.",h="Am Schrein des Sengenden Feuers hat Teufelsverderbnis die alte Kultstätte der Nachtelfen südwestlich von...",kw={"akkrilus","eschental","astranaar","athrikus narassin","cult of the dark strand","schrein des sengenden feuers","ilkrud magthrull","schattenrat"},ang={["class:Warlock"]="Als Hexenmeister könnt Ihr in den teuflischen Brandmalen und ungebändigten Dämonenbeschwörungen am Schrein des Sengenden Feuers die Handschrift des Schattenrats erkennen. Sie weisen auf die Unterwanderungen durch den Rat in ganz Kalimdor hin.",["race:NightElf"]="Als Nachtelf habt Ihr Grund, rasche Vergeltung für die Dämonen zu suchen, die den Schrein des Sengenden Feuers so nahe bei Astranaar entweihen."},sec={{t="Verderbnis im Wald",b="Südwestlich von Astranaar und westlich der Sternenstaubruinen liegt der Schrein des Sengenden Feuers unter einer sich ausbreitenden Verderbnis. Diener des Cult of the Dark Strand und des Schattenrats nähren seine Verderbnis. Teufelsmagie hat die Erde versengt, und Dämonen sammeln sich offen zwischen den Bäumen. Die Verteidiger des Waldes stellen sich ihnen dort entgegen."},{t="Schatten von Dark Strand",b="Ilkrud Magthrull, ein Orc-Hexenmeister, brachte auf Befehl von Athrikus Narassin Verderbnis zum Schrein des Sengenden Feuers. Er diente dem Cult of the Dark Strand an der Seite von Agenten des Schattenrats. Beschworene Unholde patrouillieren nun ungehindert zwischen den Altarsteinen. Ein Riss im Schleier zieht manchmal größere Schrecken an, darunter die hoch aufragende Verdammniswache Akkrilus."}},faq={{q="Wo liegt der Schrein des Sengenden Feuers?",a="Der Schrein des Sengenden Feuers liegt im südwestlichen Eschental, südwestlich von Astranaar, südlich des Schreins von Aessina und westlich der Sternenstaubruinen.",al={"schrein des sengenden feuers standort","wo ist der schrein des sengenden feuers","schrein des sengenden feuers karte"}},{q="Warum gibt es Dämonen am Schrein des Sengenden Feuers?",a="Agenten des Schattenrats und des Cult of the Dark Strand haben den Schrein des Sengenden Feuers verderbt. Der Orc-Hexenmeister Ilkrud Magthrull war unter ihnen. Ihre Rituale beschworen Dämonen und hinterließen Teufelsverderbnis auf dem heiligen Boden.",al={"warum dämonen hier","was hat den schrein des sengenden feuers verderbt","wer hat die dämonen beschworen"}},{q="Wer ist Akkrilus?",a="Akkrilus ist eine Verdammniswache, die manchmal von den dämonischen Energien um die verderbten Steine zum Schrein des Sengenden Feuers gezogen wird.",al={"akkrilus","verdammniswache am schrein des sengenden feuers","seltener dämon schrein des sengenden feuers"}},{q="Welche Verbindung hat dieser Ort zum Cult of the Dark Strand?",a="Ilkrud Magthrull, der Orc-Hexenmeister am Schrein des Sengenden Feuers, diente Athrikus Narassin, dem Anführer des Cult of the Dark Strand. Sie nutzten den Schrein als Stützpunkt für Dämonenbeschwörungen und ihre Bestrebungen in Eschental.",al={"cult of the dark strand schrein des sengenden feuers","verbindung zu dark strand","athrikus narassin schrein des sengenden feuers"}}},fx={["2cfd3821"]={q="Was ist der Schrein des Sengenden Feuers?",a="Der Schrein des Sengenden Feuers ist eine verderbte heilige Stätte im südwestlichen Eschental, südwestlich von Astranaar und westlich von The Ruins of Stardust. Einst ein friedlicher Zufluchtsort der uralten Wälder, ist er unter dunklem, dämonischem Einfluss in Bosheit und Ruinen verfallen.",al={"wissen über schrein des sengenden feuers","was ist dieser schrein","schrein des sengenden feuers eschental"}},["45677f07"]={q="Warum ist der Schrein des Sengenden Feuers zerstört und verderbt?",a="Der Schrein fiel den niederträchtigen Machenschaften des Schattenrats und seiner sterblichen Handlanger, dem Kult der Dunklen Küste, zum Opfer. Durch ihre Rituale verderbt, wurde dem Zufluchtsort seine natürliche Anmut geraubt und er wurde in eine verheerte Festung dämonischer Macht verwandelt.",al={"warum ist schrein des sengenden feuers zerstört","warum ist der schrein des sengenden feuers verderbt","was zerstörte den schrein des sengenden feuers"}},["81dc8561"]={q="Wie gefährlich ist der Schrein des Sengenden Feuers?",a="Er ist außergewöhnlich gefährlich. Das Gelände des Schreins wimmelt von aggressiven Dämonen, die von dunklen Beschwörern zurückgelassen wurden, und gelegentlich manifestiert sich der schreckliche Verdammniswache Akkrilus, um jeden Reisenden zu jagen, der sich heranzuwagen traut.",al={"ist der schrein des sengenden feuers gefährlich","bedrohungen am schrein des sengenden feuers","gefahren am schrein des sengenden feuers"}}},fp="16,147,22.307.0,26.335.0,34.139.0,41.208.0,16.112.0,68.210.1"}
P.entries["subzone:firewatch-ridge"] = {n="Feuerwachtgrat",s="Dunkeleisenzwerge halten den Feuerwachtgrat über dem Kessel im Norden der Sengenden Schlucht. Ihre Wachposten, Golems und Feuerspinnen bewachen den Felsvorsprung, während der Schattenhammer Höhlen im Nordwesten besetzt hält.",h="Dunkeleisenzwerge halten den Feuerwachtgrat über dem Kessel im Norden der Sengenden Schlucht.",kw={"kessel","dunkeleisen","feuerwachtgrat","flammenspinnen","golems","sengende schlucht","schattenhammer"},ang={["race:Dwarf"]="Als Zwerg aus Eisenschmiede könnt Ihr im Feuerwachtgrat eine düstere Mahnung an die tief verwurzelte Bosheit Eurer Dunkeleisenvettern, ihre Eisenindustrie und ihre dunklen Bündnisse unter dem Schwarzfels sehen."},sec={{t="Ein versengter Aussichtspunkt",b="Vom Feuerwachtgrat blickt Ihr auf die industrielle Verwüstung des Kessels hinab. Dunkeleisenwachen, Ingenieure und geschmolzene Golems patrouillieren auf den zerklüfteten Felsen und verteidigen ihren Stützpunkt neben giftigen Flammenspinnen, die im schwelenden Gestein heimisch sind. Die Höhe erlaubt den Dunkeleisenzwergen, die Ascheebenen zu überwachen und Vorstöße aus Eisenschmiede oder von der Thoriumbruderschaft frühzeitig zu erkennen."},{t="Der Schatten des Kults",b="Der Schattenhammer hält ein Höhlennetz in den nordwestlichen Ausläufern des Grats besetzt. Seine Kultisten wirken im Schatten des Dunkeleisenlagers und vollziehen dunkle Rituale unter dem Fels, wo mächtige Elitefanatiker Wache halten. Die Höhlen liegen sowohl nahe den Anlagen der Dunkeleisenzwerge als auch nahe dem Schwarzfels. Elementar- und Apokalypsenkulte treffen im feurigen Herzen der Sengenden Schlucht aufeinander."}},faq={{q="Was ist der Feuerwachtgrat?",a="Der Feuerwachtgrat erhebt sich über der Ausgrabungsstätte des Kessels in der Sengenden Schlucht, wo die Dunkeleisenzwerge ein großes Lager unterhalten.",al={"was ist dieser ort","feuerwachtgrat informationen","feuerwachtgrat überblick"}},{q="Welche Feinde bewohnen den Feuerwachtgrat?",a="Feindliche Dunkeleisenzwerge, mechanische Golems und heimische Feuerspinnen bewohnen den Grat. Elitekultisten des Schattenhammers halten das Höhlennetz im Nordwesten besetzt.",al={"welche mobs gibt es hier","feinde feuerwachtgrat","feuerwachtgrat gefahren"}},{q="Warum ist der Schattenhammer hier?",a="Der Schattenhammer besetzt die nordwestlichen Höhlen des Grats, um nahe dem Schwarzfels und den in der Region gebundenen Feuerelementaren Elementarverehrung und apokalyptische Rituale zu betreiben.",al={"schattenhammer feuerwachtgrat","kultisten in der höhle","nordwestliche höhle feuerwachtgrat"}},{q="Wie hängt der Feuerwachtgrat mit dem Kessel zusammen?",a="Der Feuerwachtgrat erhebt sich direkt über dem Kessel und bietet den Dunkeleisenzwergen einen befestigten Aussichtspunkt, um den Bergbau zu überwachen und ihren Steinbruch gegen Angriffe zu verteidigen.",al={"feuerwachtgrat und kessel","aussichtspunkt über dem kessel","warum den kessel überblicken"}}},fp="15,200,24.350.0,22.347.0,24.116.0,37.161.0,34.182.0,48.160.0"}
P.entries["subzone:flame-crest"] = {n="Flammenkamm",s="Flammenkamm überblickt von einem Felsvorsprung in der Brennenden Steppe die vulkanische Einöde. Das neutrale Lager beherbergt Späher, Tiersammler und Strategen, während Wind Rider Reisende über das Rotkammgebirge und darüber hinaus tragen.",h="Flammenkamm überblickt von einem Felsvorsprung in der Brennenden Steppe die vulkanische Einöde.",kw={"schwarzfelsklan","brennende steppe","etrigg","flammenkamm","flugverbindung","kibler","opus","wind rider"},ang={["faction:Horde"]="Flammenkamm bietet Reisenden der Horde eine Flugverbindung mit Wind Rider und Unterschlupf in einem neutralen Lager im Norden der Brennenden Steppe.",["race:Orc"]="Als Orc, der Thrall treu ergeben ist, könnt Ihr von diesem Lager aus den abtrünnigen Schwarzfelsklan beobachten. Seine Anwesenheit befleckt den Berg."},sec={{t="Ein unsicherer Hochsitz",b="Flammenkamm klammert sich an einen Felsvorsprung über den Asche- und Lavaebenen. Ihr überquert eine schmale Holzbrücke, um das Lager zu erreichen. Seine Höhenlage hilft, umherstreifende Bestien und marodierende Orckriegstrupps fernzuhalten. Wind Rider tragen Reisende über das Rotkammgebirge nach Kargath, Steinard, zur Thoriumspitze und nach Rog'mar in den Flusslanden."},{t="Schatten von Blackrock",b="Späher in Flammenkamm beobachten den Schwarzfelsklan, der sich in der Schwarzfelsspitze verschanzt hat. Sie sammeln Informationen und planen, wie sie die abtrünnige Dunkle Horde zerschlagen können. Das Lager treibt auch Handel mit exzentrischen Einzelgängern, darunter Kibler, ein Tiermeister, der in einer nahegelegenen Höhle lebt."}},faq={{q="Was ist Flammenkamm?",a="Flammenkamm ist ein neutrales Lager in der Brennenden Steppe. Eine grobe Brücke führt zu seinem schmalen Felsvorsprung, wo Reisende Flugverbindungen, Unterschlupf für Späher und Vorräte in einer tödlichen Region finden.",al={"flammenkamm überblick","was ist flammenkamm","brennende steppe hordelager"}},{q="Wohin fliegt der Flugmeister von Flammenkamm?",a="Wind Rider aus Flammenkamm fliegen nach Kargath im Ödland, Steinard in den Sümpfen des Elends, zur Thoriumspitze in der Sengenden Schlucht und nach Rog'mar in den Flusslanden.",al={"flammenkamm flugpunkt","flammenkamm flugverbindung","welche orte verbindet flammenkamm"}},{q="Warum unterhält die Horde einen Außenposten in der Brennenden Steppe?",a="Die Horde unterhält keine Festung in Flammenkamm. Das Lager ist neutral, doch seine Wind Rider tragen Reisende der Horde. Vom Felsvorsprung aus beobachten Späher den Schwarzfelsklan im Schwarzfels. Die Dunkle Horde widersetzt sich Kriegshäuptling Thrall und bedroht die Region, weshalb ein Aussichtspunkt vor Ort von Bedeutung ist.",al={"warum ist die horde in der brennenden steppe","flammenkamm zweck","hordenmission flammenkamm"}},{q="Wer lebt in der Höhle bei Flammenkamm?",a="Kibler und sein redseliger Papagei Opus leben in der Höhle am hinteren Ende des Felsvorsprungs. Kibler ist ein exzentrischer Tierbändiger, der sich für seltene und gefährliche Wildtiere aus der umliegenden Einöde und der Schwarzfelsspitze interessiert.",al={"kibler höhle","wer ist in der höhle bei flammenkamm","flammenkamm papagei"}},{q="Was macht Etrigg in Flammenkamm?",a="Etrigg ist nicht in Flammenkamm stationiert. Der erfahrene Orc dient an der Seite von Kriegshäuptling Thrall in Orgrimmar. Die neutrale Raststätte beherbergt Händler, Späher und Wind Rider, die den Schwarzfelsklan beobachten.",al={"etrigg brennende steppe","warum ist etrigg in flammenkamm","ariok und etrigg"}}},fp="11,223,18.311.0,19.252.0,20.190.0,48.161.0,63.286.0,37.210.0,37.198.0"}
P.entries["subzone:foothold-citadel"] = {n="Foothold-Zitadelle",s="In der Foothold-Zitadelle bereiten sich Theramores Wachen darauf vor, die Insel zu verteidigen. Die Festung beherbergt das Kommando und die Kasernen der Allianz auf der Insel Theramore und überblickt die Siedlung.",h="In der Foothold-Zitadelle bereiten sich Theramores Wachen darauf vor, die Insel zu verteidigen.",kw={"kasernen","daelin prachtmeer","düstermarschen","foothold-zitadelle","garran mumm","gustav van howzen","samaul","theramore"},ang={["faction:Alliance"]="Die Foothold-Zitadelle ist der wichtigste Militärposten der Allianz im südlichen Kalimdor. Ihre Offiziere koordinieren die Verteidigung gegen Sumpfbestien, Grimtotem-Marodeure und wachsame Späher der Horde.",["faction:Horde"]="Die Horde erinnert sich an die Foothold-Zitadelle als den Ort, an dem Rexxar und Thrall Großadmiral Prachtmeers Feldzug beendeten, um Durotar zu schützen."},sec={{t="Herz der Wache von Theramore",b="Die Foothold-Zitadelle beherbergt die Verteidigung der Allianz innerhalb der Steinmauern der Insel Theramore. Captain Garran Mumm und Commander Samaul führen die Wache von Theramore von ihren Hallen aus. Feldsanitäter, Logistikoffiziere und Rüstmeister arbeiten an ihrer Seite. Wachen patrouillieren und üben, um die Streitkräfte von Lady Jaina Prachtmeer auf Bedrohungen aus den umliegenden Sümpfen vorzubereiten."},{t="Nachhall vom Fall des Admirals",b="Die Foothold-Zitadelle erinnert an die frühen Tage Theramores. Großadmiral Daelin Prachtmeer riss die Stadt an sich, um seinen persönlichen Kreuzzug gegen die Horde zu führen, und die Festung wurde zum Schauplatz seines letzten Gefechts. Thralls verbündete Streitmacht drang unter Rexxar, einem Halbogerkrieger, in die Zitadelle ein und streckte den Admiral nieder. Die Festung wurde instand gesetzt, doch der blutige Konflikt bleibt in Erinnerung."}},faq={{q="Wozu dient die Foothold-Zitadelle?",a="Die Foothold-Zitadelle dient der Wache von Theramore als Hauptquartier und Kaserne. Dort arbeiten Führungsoffiziere, taktische Planer und Logistikpersonal neben dem örtlichen Zahlmeister und medizinischem Personal, und es gibt Ausbildungseinrichtungen.",al={"foothold-zitadelle zweck","theramore kasernen","was ist dieses gebäude"}},{q="Was geschah hier mit Großadmiral Daelin Prachtmeer?",a="Während des Konflikts nach dem Dritten Krieg riss Großadmiral Daelin Prachtmeer Theramore an sich, um gegen die junge Horde Krieg zu führen. Eine vereinte Streitmacht unter der Führung des Champions Rexxar stürmte die Zitadelle und tötete den Admiral in seinem eigenen Hauptquartier.",al={"daelins tod","daelin prachtmeer letztes gefecht","wer tötete daelin"}},{q="Wer hat derzeit das Kommando in der Foothold-Zitadelle?",a="Captain Garran Mumm und Commander Samaul überwachen unter der Autorität von Lady Jaina Prachtmeer die täglichen Patrouillen der Garnison und die Sicherheit der Region.",al={"wer führt die zitadelle","wache von theramore kommandant","zitadelle anführer"}},{q="Kann ich in der Zitadelle medizinische Hilfe erhalten?",a="Ja. Doktor Gustav van Howzen lebt in der Foothold-Zitadelle. Er versorgt verwundete Wachleute und unterrichtet Reisende der Allianz in fortgeschrittener Feldmedizin und Triage.",al={"zitadelle arzt","theramore sanitäter","erste-hilfe-lehrer theramore"}}},fp="16,169,28.344.0,28.389.0,34.211.0,54.233.0,47.141.0,45.153.0"}
P.entries["subzone:forest-s-edge"] = {n="Der Waldrand",s="Am Waldrand bedrohen Flusskammgnolle unter Hogger Reisende an Elwynns südwestlicher Grenze.",h="Am Waldrand bedrohen Flusskammgnolle unter Hogger Reisende an Elwynns südwestlicher Grenze.",kw={"wald von elwynn","der waldrand","waldrand","gnolle","hogger","nazferiti river","flusskamm","weststromgarnison"},ang={["faction:Alliance"]="Als Rekrut der Allianz im Wald von Elwynn müsst Ihr früh den Waldrand sichern und Hogger besiegen, um Eure Bereitschaft zum Dienst an der Krone zu beweisen.",["profession:Herbalism"]="Am Waldrand wachsen gewöhnliche Waldkräuter entlang der Flussufer und in den schattigen Hainen. Achtet beim Sammeln auf aggressive Gnollpatrouillen."},sec={{t="Eine umkämpfte Grenze",b="Am Waldrand erstrecken sich die Wälder südwestlich von Sturmwind, zwischen dem Obsthain am Spiegelsee und den Flüssen an der Grenze zu Westfall. Die Weststromgarnison liegt in der Nähe, doch Sturmwind hat zu wenige Soldaten, um die Wälder von wilden Bestien und plündernden Trupps freizuhalten. Eber streifen zwischen den Bäumen und an den Ufern umher. Flusskammgnolle sammeln sich in großer Zahl und nutzen die Wälder als Aufmarschgebiet."},{t="Hoggers Hochburg",b="Hogger und sein Rudel jagen durch die Wälder des Waldrands. Er ist ein riesiger, brutaler Gnollhäuptling, der Überfälle auf nahe gelegene Höfe anführt und Reisende drangsaliert. Die Armee von Sturmwind hat ein Kopfgeld auf ihn ausgesetzt. Sein Rudel macht das Waldgebiet für jeden gefährlich, der es durchquert."}},faq={{q="Wo genau liegt der Waldrand?",a="Der Waldrand liegt im Südwesten des Walds von Elwynn, südlich der Weststromgarnison. Der Obsthain am Spiegelsee und die Wasserläufe in Richtung Westfall begrenzen das Gebiet.",al={"waldrand lage","wo liegt der waldrand","waldrand karte"}},{q="Warum ist dieses Gebiet so gefährlich?",a="Flusskammgnolle haben die Wälder für sich beansprucht und bedrohen Reisende entlang Elwynns südwestlicher Grenze. Ihr Häuptling Hogger ist die größte Bedrohung und streift durch dieselben Wälder.",al={"warum ist der waldrand gefährlich","was gibt es am waldrand","waldrand bedrohungen"}},{q="Wer ist Hogger?",a="Hogger ist ein mächtiger Gnollanführer, der gewaltsame Angriffe entlang Elwynns Grenzen leitet. Die Armee von Sturmwind bietet ein Kopfgeld für den Beweis seines Todes und warnt davor, ihm allein entgegenzutreten.",al={"hogger geschichte","wer ist hogger","hogger infos"}},{q="Warum hat die Weststromgarnison das Gebiet noch nicht gesichert?",a="Sturmwinds Streitkräfte sind im ganzen Königreich überlastet. Unruhen in Westfall und Bedrohungen von allen Seiten lassen der Weststromgarnison zu wenige Soldaten, um die Gnolllager zu räumen, weshalb Freiwillige sich ihnen stellen müssen.",al={"warum sichert die weststromgarnison das gebiet nicht","warum helfen sturmwinds wachen nicht","weststromgarnison wachen"}}},fx={["898568c8"]={q="Wer lebt am Waldrand?",a="Der Waldrand ist vollständig in die Hände aggressiver Gnolle gefallen. Unter der brutalen Herrschaft des monströsen Gnolls Hogger haben diese Plünderer die Wälder und Flussufer für sich beansprucht. Die örtliche Tierwelt, hauptsächlich umherstreifende Eber, teilt sich nun die Lichtung mit diesen herumstreunenden Gnollrudeln.",al={"wer lebt hier","bewohner vom waldrand","wer ist am waldrand"}},["61fe669f"]={q="Warum heißt es Der Waldrand?",a="Das Gebiet bildet die südwestliche Grenze vom Wald von Elwynn, wo der dichte Wald dem Fluss Nazferiti und den offenen Ebenen in Richtung Westfall weicht. Eingebettet neben den Flussufern und Obstplantagen stellt es auf natürliche Weise den äußeren Saum des Waldes dar, bevor Reisende in härtere Länder überqueren.",al={"warum heißt es waldrand","bedeutung des namens waldrand","warum waldrand"}}},fp="13,100,20.370.0,19.272.0,31.157.0,30.168.0,14.179.0,47.211.0"}
P.entries["subzone:forest-song"] = {n="Forest Song",s="Im nordöstlichen Eschental hält Forest Song nahe Satyrnaar und Bough Shadow Wacht. Die uralten Ruinen der Kaldorei liegen größtenteils verlassen da, während Kayneth Stillwind die östliche Grenze bewacht.",h="Im nordöstlichen Eschental hält Forest Song nahe Satyrnaar und Bough Shadow Wacht.",kw={"eschental","bough shadow","östliches eschental","forest song","ruinen der kaldorei","kayneth stillwind","satyrnaar"},ang={["class:Druid"]="Als Druide findet Ihr Kayneth Stillwind, der allein für den Zirkel des Cenarius in den verderbten Grenzlanden unter dem Blätterdach nahe dem Great Tree von Bough Shadow Wacht hält.",["faction:Alliance"]="Als Abenteurer der Allianz könnt Ihr Forest Song als einsamen Außenposten nutzen, während Ihr das nordöstliche Eschental nach Azshara oder in den Teufelswald durchquert."},sec={{t="Einsame Wacht im östlichen Eschental",b="Die weißen Säulen und zerbrochenen Torbögen von Forest Song ragen zwischen den Bäumen des nordöstlichen Eschentals auf. Einst eine elegante Siedlung der Kaldorei, liegt die Ruine heute von Efeu und wilden Farnen überwuchert da. Satyrnaar liegt im Südwesten, während das Holzfällerlager des Kriegshymnenklans von Süden her vordringt. Östliche Pfade führen von hier nach Azshara und Bough Shadow. Dämonische Verderbnis und Einfälle der Horde suchen die Wälder heim, doch in den Ruinen bleibt es still."},{t="Wächter der Grenze",b="Kayneth Stillwind hält allein über Forest Song Wacht. Von dem verfallenden Außenposten aus hält der Druide nach Feinden Ausschau, die in die Wildnis vordringen, darunter die Verlassenen in den östlichen Wäldern. Astranaar liegt weit entfernt, und Forest Song besitzt keine Garnisonsbefestigungen. Dennoch können sich hier Reisende der Allianz sammeln, die nach Norden in den Teufelswald ziehen oder der Verderbnis nachgehen, die sich im Blätterdach ausbreitet."}},faq={{q="Wer lebt in Forest Song?",a="Kayneth Stillwind, ein Nachtelfendruide, lebt allein in den uralten Ruinen von Forest Song.",al={"wer ist in forest song","forest song npcs","forest song bewohner"}},{q="Welche Bedrohungen gibt es nahe Forest Song?",a="Satyrnaar liegt im Südwesten, wo sich verderbte Satyrn sammeln, und das Holzfällerlager des Kriegshymnenklans liegt im Süden. Bei Bough Shadow im Nordosten bewacht der grüne Drachenschwarm einen Great Tree, der in den Smaragdgrünen Traum führt.",al={"forest song gefahren","feinde nahe forest song"}},{q="Warum ist Kayneth Stillwind hier stationiert?",a="Kayneth Stillwind beobachtet feindliche Bewegungen in den östlichen Wäldern und schickt Verbündete gegen die Gefahren vor Ort aus. Dazu gehören die finsteren Unternehmungen der Verlassenen und die Krankheiten, die sie verbreiten.",al={"warum ist kayneth hier","kayneth stillwind aufgabe"}},{q="Ist Forest Song eine bedeutende Siedlung der Allianz?",a="Nein. Forest Song ist eine unbefestigte Ruine ohne aktive Garnison, Händler oder militärische Infrastruktur. Kayneth Stillwind hält dort als einziger vorgeschobener Beobachter Wacht.",al={"allianzstadt forest song","ist forest song eine stadt"}}},fx={["3234d9c0"]={q="Was ist Forest Song?",a="Forest Song ist eine uralte Nachtelfenruine im nordöstlichen Eschental, eingebettet zwischen Satyrnaar, Das Holzfällerlager des Kriegshymnenklans und dem großen grünen Drachenportal bei Bough Shadow. Anstatt einer geschäftigen Stadt liegt sie weitgehend ruhig unter den uralten Ästen und dient als einsamer Wachtposten.",al={"was ist forest song","forest song eschental","erzähle mir von forest song"}},["766b0515"]={q="Was ist mit Forest Song passiert?",a="Wie viele andere antike Kaldorei-Stätten, die über das gesamte Eschental verstreut sind, verfiel Forest Song über lange vergangene Zeitalter hinweg. In der heutigen Zeit liegt die Siedlung in Trümmern und wurde lange von der bedeutenden Zivilisation verlassen, bis jüngste eindringende Gefahren ihre strategische Bedeutung wieder in den Fokus rückten.",al={"geschichte von forest song","was passierte bei forest song","warum liegt forest song in trümmern"}}},fp="11,183,35.421.0,21.378.0,25.86.0,34.212.0,40.187.0,43.157.0"}
P.entries["subzone:forgotten-coast"] = {n="Die Vergessene Küste",s="Meeresriesen und Wasserelementare durchstreifen das Westufer von Feralas, wo die Vergessene Küste auf das verhüllte Meer trifft.",h="Meeresriesen und Wasserelementare durchstreifen das Westufer von Feralas, wo die Vergessene Küste auf das...",kw={"feralas","die vergessene küste","insel sardor","meeresriesen","verhülltes meer"},ang={["faction:Alliance"]="Für die Allianz verbindet die Küste das Festland von Kalimdor mit der Mondfederfeste auf der Insel Sardor. Meeresriesen durchstreifen das Ufer, also seid wachsam.",["faction:Horde"]="Nehmt als Reisender der Horde die nördlichen Waldpfade, um sicherer ans Wasser zu gelangen. Der südliche Pfad verläuft nahe den nachtelfischen Fähranlegern."},sec={{t="Am Rand des Regenwalds",b="Der Regenwald endet an der Vergessenen Küste, und dahinter erstreckt sich das verhüllte Meer. Ohne schützendes Blätterdach liegt der Strand offen vor Wind und Wetter. Meeresriesen überragen das Ufer, während Wasserelementare durch die Brandung streifen. Reisende, die den Wald durchqueren, müssen an diesen uralten Wächtern vorbei, um das Wasser zu erreichen. Eine Fähre bringt sie vom Festland zur Insel Sardor, der Heimat der nachtelfischen Mondfederfeste."}},faq={{q="Welche Gefahren durchstreifen die Vergessene Küste?",a="Meeresriesen und Wasserelementare entsteigen dem verhüllten Meer und durchstreifen die Vergessene Küste.",al={"monster an der vergessenen küste","gefahren der vergessenen küste","was gibt es an der küste"}},{q="Wie erreicht Ihr von hier aus die Mondfederfeste?",a="Nehmt die Fähre von der Küste über den Kanal zur Insel Sardor, wo die Nachtelfen die Mondfederfeste halten. Meeresriesen durchstreifen die Gewässer nahe dem Anleger.",al={"wie gelangt man zur mondfederfeste","boot zur mondfederfeste","fähre zur mondfederfeste"}},{q="Ist die Vergessene Küste für die Horde zugänglich?",a="Ja. Ein nördlicher Pfad führt zur Küste hinab, sodass Reisende der Horde den südlichen Weg zum nachtelfischen Fährübergang und seinen Schildwachen meiden können.",al={"hordenzugang zur vergessenen küste","wie erreicht die horde die küste","sicherer hordenpfad zur vergessenen küste"}}},fp="15,111,22.407.0,40.87.0,50.158.0,47.144.0"}
P.entries["subzone:forgotten-pool"] = {n="Forgotten Pool",s="Jenseits der Moonshrine Ruins liegt der Forgotten Pool unter der Tiefschwarzen Grotte. Monströse Tiefseeräuber lauern in seinen dunklen Wassern.",h="Jenseits der Moonshrine Ruins liegt der Forgotten Pool unter der Tiefschwarzen Grotte.",kw={"tiefschwarze grotte","höhle","forgotten pool","moonshrine ruins","alter serra'kis","drescher","unter wasser"},ang={["faction:Horde"]="Als Späher der Horde in der Tiefschwarzen Grotte könnt Ihr den Alten Serra'kis im Forgotten Pool entdecken, fernab der vom Gesang erfüllten Hallen des Kults."},sec={{t="Ein versunkenes Versteck",b="Taucht durch die versunkenen Wasserwege jenseits der Moonshrine Ruins, um den Forgotten Pool zu erreichen. Dunkles Wasser füllt diese abgeschiedene Höhle, die vom trockenen Land abgeschnitten ist.\n\nIn der Nähe singen Kultisten des Twilight's Hammer, und Naga patrouillieren durch die überfluteten Hallen. Der Pool liegt abseits von ihnen. Der Alte Serra'kis, ein uralter Schrecken der Gewässer, hat sein Versteck in dessen Tiefen."}},faq={{q="Wo liegt der Forgotten Pool?",a="Der Forgotten Pool liegt tief in der Tiefschwarzen Grotte, jenseits der Moonshrine Ruins. Schwimmt durch überflutete Tunnel, um die versunkene Höhle zu erreichen.",al={"wo ist forgotten pool","forgotten pool lage","forgotten pool finden"}},{q="Was lauert im Forgotten Pool?",a="Der Alte Serra'kis, ein uraltes, drescherähnliches Ungeheuer, lauert im Forgotten Pool. Die abgeschiedene Höhle ist sein Versteck.",al={"forgotten pool monster","wer lebt im forgotten pool","forgotten pool boss"}},{q="Führt der Forgotten Pool noch irgendwohin?",a="Nein. Der Forgotten Pool ist eine Sackgasse unter Wasser ohne weitere Durchgänge. Er ist ein abgeschiedenes Nest unter Wasser.",al={"ist forgotten pool eine sackgasse","wohin führt forgotten pool"}}},fx={["5f3c8292"]={q="Was ist der Forgotten Pool?",a="Der Forgotten Pool ist eine überflutete unterirdische Höhle, versteckt in den Tiefen der Tiefschwarze Grotte, gleich hinter den Moonshrine Ruins. Abgeschnitten von den Tempelkorridoren durch untergetauchte Passagen, bildet er eine stagnierende, abgeschiedene aquatische Sackgasse tief unter den Ruinen der alten Nachtelfen-Zuflucht.",al={"was ist forgotten pool","wissen über forgotten pool","über forgotten pool"}},a4c2428d={q="Ist der Forgotten Pool gefährlich?",a="Ja, das Schwimmen durch seine dunklen, wassergefüllten Tunnel birgt ernste Gefahren. Neben dem Risiko des Ertrinkens in den untergetauchten Passagen dient der Pool als Versteck des Alten Serra'kis, eines monströsen aquatischen Dreschers, neben anderen lauernden Schrecken, die das Tauchen in seine Tiefen für jeden unvorsichtigen Entdecker gefährlich machen.",al={"ist forgotten pool gefährlich","gefahr forgotten pool","bedrohungen forgotten pool"}}},fp="14,127,16.328.0,36.139.0,37.104.0,43.104.0"}
P.entries["subzone:forgotten-pools"] = {n="Die Vergessenen Teiche",s="Im nördlichen Brachland ziehen die Vergessenen Teiche Wildtiere, Kolkar-Zentauren und die Horde in einen Kampf um Wasser. Nordwestlich vom Wegekreuz speisen unterirdische Quellen diese Oase in der trockenen Savanne.",h="Im nördlichen Brachland ziehen die Vergessenen Teiche Wildtiere, Kolkar-Zentauren und die Horde in einen...",kw={"brachland","zentauren","das wegekreuz","deviatfisch","die vergessenen teiche","kolkar","laden mushrooms","oase"},ang={["class:Druid"]="Das rasche Wachstum mutierter Vegetation und von Deviatfischen rund um die Vergessenen Teiche liefert Cenarion-Forschern Hinweise bei ihren Untersuchungen unnatürlicher Veränderungen im gesamten Brachland.",["faction:Horde"]="Die Kontrolle über die Vergessenen Teiche hilft, die Handelswege vom Wegekreuz zu sichern und die Kolkar daran zu hindern, die westlichen Nachschublinien der Horde abzuschneiden."},sec={{t="Eine Oase im Ödland",b="In den Vergessenen Teichen sammelt sich Süßwasser. Dichtes Schilf, Palmen und Laden Mushrooms wachsen am Rand des ausgedörrten Brachlands. Ebenenschreiter, Schnappkiefer-Schildkröten und Zhevras kommen zum Trinken hierher. An den Ufern bewachen Kolkar-Zentauren ihr Lager und das Wasser vor Reisenden. Ihre Ansprüche bringen sie in Konflikt mit Reisenden der Horde vom Wegekreuz, und alle drei ringen um die Oase."},{t="Ökologische Rätsel",b="Deviatfische gedeihen in den Vergessenen Teichen, einem der seltenen Oberflächengewässer der Region, in denen sie zu finden sind. Ihre Anwesenheit deutet auf tiefere Verbindungen zu den seltsamen, verwandelnden Energien hin, die den Grundwasserspiegel des Brachlands verändern. Naturkundler und Späher der Horde beobachten die Gewässer und die ungewöhnlichen Pilze an den Ufern. Sie sind auf der Hut vor dem, was in den Boden sickern könnte."}},faq={{q="Wo liegen die Vergessenen Teiche?",a="Die Vergessenen Teiche liegen im nördlichen Brachland, direkt nordwestlich vom Wegekreuz und knapp nördlich der Straße, die nach Westen zum Steinkrallengebirge abzweigt.",al={"vergessene teiche lage","wo liegen die vergessenen teiche","vergessene teiche finden"}},{q="Warum sind die Kolkar-Zentauren hier?",a="Wasser erhält das Leben im trockenen Brachland, daher beanspruchen die Kolkar mit Gewalt jede Oase, die sie erreichen können. Sie versorgen ihre Kriegerscharen und verwehren durchreisenden Karawanen der Horde und nahe gelegenen Siedlungen lebenswichtige Ressourcen.",al={"zentauren an den vergessenen teichen","warum sind die kolkar hier","kolkar vergessene teiche"}},{q="Was macht die Fische und Pflanzen hier ungewöhnlich?",a="Die Vergessenen Teiche sind einer der wenigen Orte über der Erde, an denen Deviatfische gedeihen, und an den Ufern wachsen ungewöhnliche Laden Mushrooms. Diese Mutationen deuten auf unterirdische Störungen hin, die die Grundwasserleiter des Brachlands beeinflussen.",al={"deviatfisch vergessene teiche","laden mushrooms","warum sind die fische hier seltsam"}},{q="Kam Thrall durch diese Oase?",a="Keine Aufzeichnung berichtet, an welchen Oasen Thralls Horde auf ihrem langen Marsch durch das Brachland rastete, daher ist unbekannt, ob die Vergessenen Teiche darunter waren.",al={"thrall vergessene teiche","haben orcs hier gelagert","warcraft 3 oase"}}},fx={["670d71f6"]={q="Was ist Die vergessenen Teiche?",a="Die vergessenen Teiche ist eine üppige Oase im nördlichen Brachland, nordwestlich von Das Wegekreuz gelegen. Im Gegensatz zum umliegenden ariden Buschland fördern ihre frischen Gewässer eine dichte Vegetation, einschließlich eigentümlicher, beladener Pilze entlang der Ufer und seltsamer, mutierter Deviatfisch, die in ihren Tiefen schwimmen.",al={"was ist die vergessenen teiche","die vergessenen teiche brachland","über die vergessenen teiche"}},a5a5def4={q="Wer lebt bei Die vergessenen Teiche?",a="Die Oase wird von feindseligen Kolkar-Zentauren beansprucht, die ihre lebenswichtigen Gewässer aggressiv zusammen mit einheimischen Schnappschildkröten und Bestien bewachen.",al={"wer kontrolliert die vergessenen teiche","wer ist bei die vergessenen teiche","bewohner der vergessenen teiche"}},["62a6fb30"]={q="Sind Die vergessenen Teiche gefährlich?",a="Ja, Reisen dorthin erfordern Vorsicht. Grimmige Kolkar-Stürmer und -Treiber patrouillieren erbittert an den Ufern und greifen jeden an, der sich ihrer Wasserversorgung nähert. Zusätzlich zu den Zentauren schleichen bösartige Raubtiere am Rande herum und mutierte Kreaturen bewohnen die Gewässer der Oase.",al={"sind die vergessenen teiche gefährlich","bedrohungen bei den vergessenen teichen","gefahr die vergessenen teiche"}}},fp="15,202,22.381.0,20.355.0,38.164.0,32.206.0,44.235.0,35.153.0"}
P.entries["subzone:forlorn-cavern"] = {n="Forlorn Cavern",s="In Eisenschmiedes nördlichen Tiefen birgt die Forlorn Cavern jene, die sich im Schatten halten. Diebe, Beutelschneider und Anwender der dunklen Künste gehen dort ihren Geschäften nach, fernab der Großen Schmiede und der Zwergenwachen.",h="In Eisenschmiedes nördlichen Tiefen birgt die Forlorn Cavern jene, die sich im Schatten halten.",kw={"bonegrip","forlorn cavern","hall of explorers","eisenschmiede see","mystic ward","schurkenlehrer","stoneblade","hexenmeisterlehrer"},ang={["class:Rogue"]="Als Schurke findet Ihr in diesem Stützpunkt der Allianz in Khaz Modan Lehrer und Vorräte. Entlang der feuchten Steinwege werden Gifte und spezialisierte Klingen verkauft.",["class:Warlock"]="Als Hexenmeister könnt Ihr in diesem abgeschiedenen Teil von Eisenschmiede bei Bonegrip's Runes and Dooms lernen und Vorräte finden."},sec={{t="Eisenschmiedes schattiger Winkel",b="Kalt und feucht liegt die Forlorn Cavern unter Eisenschmiedes Ambossklang und der Hitze der Großen Schmiede. Ihre gewundenen Pfade folgen dem nördlichen Ufer des unterirdischen Sees, verborgen zwischen dem Mystic Ward und der Hall of Explorers. Schurken und Hexenmeister üben dort, und Händler versorgen sie. Auch Waffenhändler und Fischer arbeiten am See."}},faq={{q="Wo in Eisenschmiede liegt die Forlorn Cavern?",a="Die Höhle liegt im Norden von Eisenschmiede am unterirdischen See. Betretet sie vom Mystic Ward im Osten aus, oder folgt dem Tunnel von der Hall of Explorers nach Westen.",al={"forlorn cavern lage","wie zur forlorn cavern gelangen","wo ist die forlorn cavern"}},{q="Warum versammeln sich hier Schurken und Hexenmeister?",a="Die natürliche Dunkelheit und Abgeschiedenheit der Höhle machen sie zu einem diskreten Treffpunkt. Dort finden sich Schurken- und Hexenmeisterlehrer sowie Händler, die beide Gruppen versorgen.",al={"warum hexenmeister hier","warum schurken in der forlorn cavern","zwielichtiges viertel eisenschmiede"}},{q="Welche Läden und Dienste gibt es in der Forlorn Cavern?",a="In der Höhle gibt es Schurken- und Hexenmeisterlehrer, Bonegrip's Runes and Dooms für Anwender dunkler Magie, den Waffenladen Stoneblade und The Traveling Fisherman für Angelbedarf.",al={"forlorn cavern händler","läden in der forlorn cavern"}}},fx={["307bd9d1"]={q="Was ist die Forlorn Cavern?",a="Die Forlorn Cavern ist ein dunkler, gewundener Bezirk, der sich tief in Eisenschmiede um einen unterirdischen See schlängelt. Versteckt zwischen dem Mystic Ward und der Hall of Explorers bieten ihre abgeschiedenen Schatten einen ruhigen Zufluchtsort für die weniger rühmlichen Bewohner von Eisenschmiede, darunter örtliche Schurken, heimliche Hexenmeister und Nischenhändler, die lieber abseits neugieriger Zwergenaugen operieren.",al={"was ist die forlorn cavern","forlorn cavern übersicht","über forlorn cavern"}},["15f7ff40"]={q="Ist die Forlorn Cavern gefährlich?",a="Obwohl sie als Teil von Eisenschmiede bewacht wird, solltet Ihr dennoch vorsichtig sein. Die schummrigen Ecken der Höhle bieten zwielichtigen Gestalten, Dieben, Taschendieben und Praktizierenden dunkler Teufelsmagie Schutz. Solange Ihr Euren Verstand beisammenhaltet und die heiklen Geschäfte respektiert, die dort abgewickelt werden, bleibt der Bezirk friedlich genug für Reisende, um ihn unbeschadet zu durchqueren.",al={"ist forlorn cavern sicher","gefahr in forlorn cavern","bedrohungen in forlorn cavern"}}},fp="14,218,25.346.0,49.160.0,39.160.0,59.183.0"}
P.entries["subzone:forlorn-cloister"] = {n="Forlorn Cloister",s="Zwischen den Gräbern des Forlorn Cloister erheben sich die Gefallenen, und Scharlachrote Kreuzfahrer verbrennen ihre Leichen, um sie aufzuhalten.",h="Zwischen den Gräbern des Forlorn Cloister erheben sich die Gefallenen, und Scharlachrote Kreuzfahrer...",kw={"forlorn cloister","friedhof","scharlachroter kreuzzug","das scharlachrote kloster","thalnos","tirisfal"},ang={["class:Priest"]="Als Priester seht Ihr, was geschieht, wenn ein heiliges Sanktuarium der Dunkelheit anheimfällt. Heilige Riten weichen hastig errichteten Scheiterhaufen, und gequälte Erscheinungen streifen über das Gelände.",["race:Undead"]="Als Verlassener erkennt Ihr hier womöglich eine düstere Ironie. Die fanatischen Kreuzfahrer brandmarken alle Untoten als Monster, können aber nicht verhindern, dass ihre eigenen Brüder unter ihren Füßen auferstehen."},sec={{t="Eine verzehrte Weihe",b="Ihr betretet einen Friedhof, auf dem Scharlachrote Kreuzfahrer mit Fackeln zwischen den Gräbern umhereilen. Sie verbrennen ihre gefallenen Brüder, doch die Seuche hat die Erde unter ihnen bereits verdorben.\n\nEinst betteten die Priester und Paladine von Lordaeron hier ihre geehrten Toten in Frieden zur Ruhe. Nun gleiten Gespenster zwischen den Grüften umher, und Leichen graben sich aus den Gräbern. Die Kreuzfahrer halten Wache, doch dunkle Magie tief im Erdreich ruft die Toten weiterhin dazu auf, sich zu erheben."},{t="Der Herr der Gräber",b="Blutmagier Thalnos befehligt die Toten im Forlorn Cloister. Der skelettierte Zauberer ist eine weitere tragische Gestalt des Klosters, dem Untod verfallen und nach Rache dürstend. Mit dunkler Magie bindet er die Seelen der Verstorbenen und schlachtet jeden ab, der seinen verseuchten Friedhof betritt."}},faq={{q="Wo liegt das Forlorn Cloister?",a="Das Forlorn Cloister umfasst den unter freiem Himmel gelegenen Friedhofsflügel des Scharlachroten Klosters im Nordosten von Tirisfal.",al={"forlorn cloister lage","wo liegt forlorn cloister","friedhofsflügel"}},{q="Warum verbrennen die Scharlachroten Kreuzfahrer hier Leichen?",a="Der Scharlachrote Kreuzzug verbrennt seine Gefallenen in dem verzweifelten Versuch, die Seuche der Geißel daran zu hindern, sie auferstehen zu lassen. Der Boden des Forlorn Cloister ist bereits verdorben, und unverbrannte Leichen erheben sich bald als willenlose Zombies.",al={"warum leichen verbrennen","leichenverbrennung scharlachroter kreuzzug","was tun die kreuzfahrer"}},{q="Wer herrscht über das Forlorn Cloister?",a="Blutmagier Thalnos herrscht über den Friedhof. Der mächtige untote Zauberwirker befehligt die umherwandernden Toten und greift lebende Eindringlinge an.",al={"forlorn cloister boss","wer hat hier das sagen","friedhofsboss"}},{q="Warum wird der Friedhof von Geistern heimgesucht, obwohl der Scharlachrote Kreuzzug das Kloster hält?",a="Die Scharlachroten Kreuzfahrer haben trotz ihres religiösen Eifers die Kontrolle über ihren Friedhof verloren. Nekromantische Energien, die durch Lordaeron strömen, haben die begrabenen Toten aufgerüttelt und die lebende Garnison in einen endlosen Kampf gegen die Geister ihrer einstigen Gefährten gestürzt.",al={"warum gibt es geister","warum untote im kloster","gehört der friedhof zur geißel"}}},fx={["9a53d37e"]={q="Was ist das Forlorn Cloister?",a="Das Forlorn Cloister ist der Friedhofsflügel unter freiem Himmel im Scharlachroten Kloster. Einst ein friedlicher Ort der Ruhe für die Gefallenen des Ordens, ist er zu einem trostlosen Innenhof verkommen, in dem Erde und Grüfte von rastlosen Toten wimmeln. Auch wenn der Scharlachrote Kreuzzug den Rest des Klosters erbittert verteidigt, führen sie hier einen verzweifelten, endlosen Kampf, nur um die Schrecken einzudämmen, die aus dem Boden steigen.",al={"was ist das forlorn cloister","forlorn cloister scharlachrotes kloster","über das forlorn cloister"}},a5f6d48a={q="Ist das Forlorn Cloister gefährlich?",a="Das Cloister ist gefährlich. Eifrige Scharlachrote Kreuzzügler verbrennen Körper, während rastlose Geister und wandelnde Leichen zwischen den Grabsteinen umherwandern. Tiefer im Inneren haust Blutmagier Thalnos, ein untoter Magier, der Eindringlinge angreift.",al={"ist forlorn cloister gefährlich","bedrohungen im forlorn cloister","gefahr im forlorn cloister"}}},fp="16,112,23.426.0,23.272.0,38.125.0,50.195.0,36.128.0,72.260.0"}
P.entries["subzone:forlorn-ridge"] = {n="Der einsame Grat",s="Stellungen der Allianz und der Horde säumen die Hänge des einsamen Grats im Südwesten Azsharas. Der Grat erhebt sich über der Küste.",h="Stellungen der Allianz und der Horde säumen die Hänge des einsamen Grats im Südwesten Azsharas.",kw={"azshara","der einsame grat","befestigungen","berg","die ruinen von eldarath","vulkan"},ang={["faction:Alliance"]="Als Soldat der Allianz könnt Ihr die Truppenbewegungen der Horde beobachten, die sich vom Brachland und vom Eschental nach Osten ausbreiten. Der einsame Grat bietet Euch eine frühe Warnung und einen Überblick über das Gelände.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr Stützpunkte entlang des einsamen Grats nutzen, um Azsharas zerklüftete Grenzgebiete unmittelbar nördlich von Durotar gegen Vorstöße der Allianz zu sichern."},sec={{t="Eine umkämpfte Anhöhe",b="Der einsame Grat erhebt sich über dem Westen Azsharas und gleicht in seiner Form einem uralten, längst ruhenden Vulkan. Von seinen Höhen aus könnt Ihr die Küste und die verfallenen elfischen Anwesen unterhalb sehen.\n\nDer Grat beherrscht diesen Landstrich, weshalb Streitkräfte der Allianz und der Horde Lager und Außenposten entlang seiner zerklüfteten Hänge errichtet haben. Über die Klippen hinweg beobachten sie einander."}},faq={{q="Was ist der einsame Grat?",a="Der einsame Grat erhebt sich über der Wildnis und den Küstenstraßen im Südwesten Azsharas.",al={"wo liegt der einsame grat","einsamer grat azshara","was ist dieser berg"}},{q="Warum kämpfen die Allianz und die Horde um diesen Grat?",a="Der einsame Grat bietet einen weiten Blick über den Westen Azsharas. Von seinen Höhen aus kann jede der beiden Fraktionen Truppenbewegungen zwischen den Küstenruinen und den Pässen im Landesinneren beobachten. Deshalb haben beide befestigte Stellungen an seinen Hängen errichtet.",al={"warum gibt es hier lager","wer kontrolliert den einsamen grat","allianz gegen horde einsamer grat"}},{q="War der einsame Grat ursprünglich ein Vulkan?",a="Die zerklüftete Form des einsamen Grats deutet darauf hin, dass er einst ein Vulkan gewesen sein könnte. Er ruht schon lange und ist überwuchert.",al={"ist der einsame grat ein vulkan","vulkan in azshara"}}},fp="13,119,19.334.0,22.83.0,56.209.0,39.108.0"}
P.entries["subzone:forlorn-rowe"] = {n="Das Verlassene Gut",s="Am Nordrand des Friedhofs von Rabenflucht liegt das Verlassene Gut im Schatten des Schreckens. Morbent Fel hat dort sein Heim, und seine Magie erweckt im ganzen Dämmerwald die ruhelosen Toten.",h="Am Nordrand des Friedhofs von Rabenflucht liegt das Verlassene Gut im Schatten des Schreckens.",kw={"friedhof","dämmerwald","das verlassene gut","morbent fel","nekromant","rabenflucht","untoter"},ang={["class:Paladin"]="Als Paladin steht Ihr auf dem Verlassenen Gut finsteren Riten gegenüber, die dem Heiligen Licht trotzen. Geweihte Relikte und gerechter Zorn können die Schutzzauber des Nekromanten durchdringen.",["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass Morbent Fel vom Verlassenen Gut vertrieben werden muss, um der Westgrenze des Dämmerwalds wieder etwas Sicherheit zu bringen."},sec={{t="Ein Sitz der Nekromantie",b="Das Verlassene Gut erhebt sich in düsterem Zwielicht am Nordrand des Friedhofs von Rabenflucht. Morbent Fel hat sein Heim auf dem Hügel. Der Nekromant erweckt viele der Toten, die durch die umliegende Wildnis streifen. Von oben lenken seine verderbten Verzauberungen skelettierte Diener und machen den Nordwesten des Dämmerwalds für Reisende gefährlich."},{t="Die Läuterung des Hügels",b="Morbent Fels Herrschaft über das Verlassene Gut lässt sich nicht mit gewöhnlichem Stahl brechen. Dunkle Verzauberungen schützen ihn vor den Waffen der Sterblichen, bis Relikte heiliger Macht ihn schwächen. Um den Nekromanten zu bezwingen und seine Herrschaft über die Wälder zu brechen, müssen Abenteurer geweihte Waffen finden und den Fluch bekämpfen, der das Friedhofsgelände erstickt."}},faq={{q="Wo liegt das Verlassene Gut?",a="Das Verlassene Gut erhebt sich am nördlichen Höhenzug des Friedhofs von Rabenflucht im Nordwesten des Dämmerwalds und überblickt den Friedhof.",al={"verlassenes gut lage","wo ist das verlassene gut","verlassenes gut finden"}},{q="Wer wohnt auf dem Verlassenen Gut?",a="Morbent Fel hat seinen Unterschlupf auf dem Verlassenen Gut. Der mächtige Nekromant nutzt finstere arkane Riten, um die Untoten zu erwecken und zu befehligen, die durch den Dämmerwald wandern.",al={"wer ist auf dem verlassenen gut","verlassenes gut boss","haus auf dem hügel dämmerwald"}},{q="Warum ist Morbent Fel hier so schwer zu bekämpfen?",a="Morbent Fel schützt sich mit verderbter Zauberei. Gewöhnliche Angriffe sind nahezu wirkungslos, bis ein geweihtes Relikt, das seine Magie bannen soll, ihm seinen Schutz nimmt.",al={"morbent fel schild","morbent fel immun","wie morbent fel töten"}},{q="Gehört das Verlassene Gut zum Friedhof?",a="Ja. Das Verlassene Gut erhebt sich an der Nordgrenze des Friedhofs von Rabenflucht und überblickt die Gräber und Gruften darunter.",al={"gehört das verlassene gut zu rabenflucht","verbindung zu rabenflucht"}}},fx={aabdcca0={q="Was ist Forlorn Rowe?",a="Forlorn Rowe ist ein dunkler, trostloser Hügel am nördlichen Rand des Friedhofs von Rabenflucht im nordwestlichen Dämmerwald. Eingehüllt in unnatürliches Düster, überblickt diese verfluchte Anhöhe den weitläufigen Friedhof und dient als persönliches Bollwerk von Morbent Fel, einem bösen Nekromanten, der seine abscheuliche Zauberei einsetzt, um die umherstreifenden Toten des Waldes zu befehligen.",al={"was ist forlorn rowe","forlorn rowe übersicht","über forlorn rowe"}},e9789594={q="Ist Forlorn Rowe gefährlich?",a="Es ist extrem gefährlich. Morbent Fel wirkt tödliche nekromantische Magie von seinem Zuhause auf der Anhöhe aus und bindet und befehligt aktiv die Untoten, die den nördlichen Friedhof überfluten. Ein Betreten dieser schattigen Hänge zieht den Zorn sowohl der rastlosen Leichen, die er belebt, als auch des Meisters der Zauberei selbst auf Euch.",al={"gefahr bei forlorn rowe","wie gefährlich ist forlorn rowe","ist es hier sicher"}}},fp="12,174,20.310.0,18.321.1,34.113.0,30.144.0,41.162.1,41.111.0"}
P.entries["subzone:fray-island"] = {n="Prügel-Eiland",s="Krieger versammeln sich auf Prügel-Eiland vor der Händlerküste des Brachlands. Auf diesem felsigen Inselchen erproben Kämpfer aus ganz Azeroth ihr Können in einem rauen Trainingsring.",h="Krieger versammeln sich auf Prügel-Eiland vor der Händlerküste des Brachlands.",kw={"affray","brachland","berserker stance","big will","prügel-eiland","klannoc macleod"},ang={["class:Warrior"]="Als Krieger könnt Ihr Eure Disziplin und Stärke auf dem Trainingsplatz von Prügel-Eiland erproben. Klannoc Macleod und The Affray prüfen, ob Ihr die Berserker Stance einnehmen könnt.",["race:Human"]="Klannoc Macleod ist ein Mensch, doch die Krieger, die sich in seinem Ring versammeln, verbindet der Kampf über die Grenzen der Völker hinweg."},sec={{t="Ein Prüfplatz für Raufbolde",b="Prügel-Eiland liegt vor den östlichen Klippen des Brachlands, jenseits der wachsamen Augen von Orgrimmar und Theramore. Krieger aller Völker und Gesinnungen trainieren hier. Klannoc Macleod beaufsichtigt die Kampfarena im Herzen der Insel. Erfahrene Kämpfer und unerprobte Rekruten treffen dort in brutalen Schlägereien aufeinander."},{t="Die Prüfung des Affray",b="Trotz der feindseligen Gewässer ringsum folgt der Ring auf Prügel-Eiland einem einfachen Kodex des Kampfes. Auf Anweisung ihrer Ausbilder stellen sich Krieger dem Affray, einem zermürbenden Spießrutenlauf gegen Wellen von Herausforderern. Die Prüfung endet mit einem Kampf gegen den Champion Big Will. Im Ring weicht die Treue zur Horde oder Allianz der Stärke und kriegerischen Disziplin."}},faq={{q="Wozu dient Prügel-Eiland?",a="Prügel-Eiland ist ein Trainingsplatz für Krieger und Schauplatz des Affray, einer brutalen Kampfprüfung. Krieger beider Fraktionen erproben dort ihr Durchhaltevermögen und meistern fortgeschrittene Haltungen.",al={"warum nach prügel-eiland","prügel-eiland zweck","was gibt es auf prügel-eiland"}},{q="Wer kontrolliert Prügel-Eiland?",a="Kein Königreich und keine Fraktion herrscht über Prügel-Eiland. Krieger aller Völker und Gesinnungen trainieren dort, während Klannoc Macleod den Kampfring beaufsichtigt.",al={"wer leitet prügel-eiland","wer lebt auf prügel-eiland","prügel-eiland fraktion"}},{q="Wie erreiche ich Prügel-Eiland?",a="Prügel-Eiland liegt im großen Meer, vor der Ostküste des Brachlands und südlich von Ratschet. Um dorthin zu gelangen, müsst Ihr vom Ufer aus eine weite Strecke durch Gewässer voller Haie und Frenzys schwimmen.",al={"prügel-eiland erreichen","wo liegt prügel-eiland","wie nach prügel-eiland gelangen"}},{q="Was ist The Affray?",a="The Affray ist eine Ausdauerprüfung im Kampfkäfig von Prügel-Eiland. Ein Krieger steht auf dem Gitter und besiegt aufeinanderfolgende Wellen von Herausforderern, bevor er gegen den Raufbold Big Will antritt.",al={"the affray","prügel-eiland arena","kampf gegen big will"}}},fx={["0872188f"]={q="Was ist Prügel-Eiland?",a="Prügel-Eiland ist eine kleine, trockene Insel vor der Ostküste vom Brachland, südlich von Ratschet. Sie dient als isolierter Übungsplatz und Kampfarena für Krieger aller Völker und Gesinnungen, die ihre Kampfeslust testen wollen.",al={"prügel-eiland geschichte","was ist prügel-eiland","prügel-eiland brachland"}},["122aa5b5"]={q="Was geschah auf Prügel-Eiland?",a="Prügel-Eiland wurde als Kampfübungsplatz gegründet, unter der Leitung des Ausbilders Klannoc Macleod. Es steht seit Langem außerhalb der Fraktionspolitik und zieht Kämpfer und Raufbolde aus ganz Azeroth an, um ihre Kampfkünste in der Arena zu testen.",al={"historie von prügel-eiland","vergangenheit von prügel-eiland","was geschah hier"}},d609582c={q="Ist Prügel-Eiland gefährlich?",a="Ja, für Unvorbereitete. Die Kampfarena testet jeden Herausforderer gegen Wellen von erbitterten Raufbolden, und die Insel überhaupt zu erreichen bedeutet ein langes Schwimmen durch Gewässer voller feindseliger Schlammflossen.",al={"ist prügel-eiland sicher","bedrohungen auf prügel-eiland","gefahr auf prügel-eiland"}},b15eb391={q="Warum heißt es Prügel-Eiland?",a="Der Name der Insel leitet sich von The Affray ab, dem brutalen Wettkampf und der Kampfgrube, die auf dem Gelände unterhalten wird. Krieger und Kämpfer reisen von weit her an, um sich in diesen Raufereien zu messen, was der gesamten Insel ihren kämpferischen Ruf verleiht.",al={"bedeutung des namens prügel-eiland","warum prügel-eiland","warum heißt es prügel-eiland"}}},fp="11,163,29.286.0,23.350.0,29.180.0,25.134.0,27.184.0,19.179.0"}
P.entries["subzone:frayfeather-highlands"] = {n="Fransenfederhochland",s="In Feralas verteidigen Fransenfederhippogryphen ihre angestammten Horste. Plünderer und Naturforscher trotzen den Schwärmen auf der Suche nach unversehrten Eiern.",h="In Feralas verteidigen Fransenfederhippogryphen ihre angestammten Horste.",kw={"eier","feralas","fransenfeder","gadgetzan","hochland","hippogryph","nester"},ang={["class:Druid"]="Als Druide schätzt Ihr die wilden Tiere Kalimdors sehr. Die ungestörten Horste des Fransenfederhochlands spiegeln die urwüchsige Lebenskraft des Waldes wider.",["race:NightElf"]="Als Nachtelf verehrt Ihr Hippogryphen als heilige Gefährten Elunes. Ihre wilden Nester in Feralas verdienen Schutz vor rücksichtsloser Ausbeutung."},sec={{t="Horste der Hippogryphen",b="Wilde Hippogryphen ziehen ihre Brut an steilen Hängen und auf schroffen Felsen über dem Waldboden von Feralas auf. Die Schwärme verteidigen ihre verstreuten Nester zwischen den Felsvorsprüngen mit erbitterter Aggressivität. Wie sicher sie sich an den zerklüfteten Klippen bewegen, lockt Außenstehende zu den Nistplätzen. Goblingeschäftsleute im fernen Gadgetzan suchen ungeschlüpfte Eier für Forschung und Profit."}},faq={{q="Welche Kreaturen leben im Fransenfederhochland?",a="Große Schwärme wilder Fransenfederhippogryphen nisten an den hohen Felswänden. Sie verteidigen ihr Revier erbittert gegen Eindringlinge.",al={"fransenfeder tierwelt","was gibt es hier","fransenfeder bestien"}},{q="Warum interessieren sich Reisende für die Hippogryphennester?",a="In den Nestern liegen seltene Hippogrypheneier. Abenteurer tragen entwicklungsfähige Eier durch Tanaris nach Gadgetzan, wo Goblins sie für Forschung und Profit in der Super Egg-O-Matic verarbeiten.",al={"hippogrypheneier","eierquest","warum eier stehlen"}},{q="Wo liegt das Fransenfederhochland?",a="Das Hochland erhebt sich im Süden von Feralas über das dichte Blätterdach des Dschungels. Seine zerklüfteten Hänge bieten offene Sitzplätze zum Nisten.",al={"fransenfeder lage","wo liegt das fransenfederhochland","wie fransenfeder finden"}}},fp="21,136,24.337.0,49.135.0,53.174.0,44.123.0"}
P.entries["subzone:freewind-post"] = {n="Freiwindposten",s="Der Freiwindposten sichert von einem hohen Tafelberg aus die Stellung der Horde in Tausend Nadeln. Taurenaufzüge und gewundene Seilbrücken führen zu diesem Zufluchtsort, wo die Horde Zentaurenkriegstrupps trotzt und sich für das Grenzland rüstet.",h="Der Freiwindposten sichert von einem hohen Tafelberg aus die Stellung der Horde in Tausend Nadeln.",kw={"düsterwolkengipfel","aufzug","freiwindposten","galak","der steilhang","tafelberg","tauren","tausend nadeln","wyvern"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr Euch auf den Freiwindposten als wichtigen Zufluchtsort und Flugverbindung zwischen dem Südlichen Brachland und Tanaris verlassen. Er erleichtert Reisen durch das zentrale Kalimdor.",["race:Tauren"]="Als shu'halo könnt Ihr sehen, wie der Freiwindposten die Höhe der Tafelberge zum Schutz vor den seit jeher plündernden Zentauren nutzt und zugleich die angestammten Wyvern der Klippen hütet."},sec={{t="Eine Festung im Himmel",b="Der Freiwindposten schmiegt sich an die Tafelberge des Canyons, wo die Höhe seine Bewohner schützt. Die Galak-Zentauren beherrschen den trockenen Canyongrund, können aber weder die steilen Klippen erklimmen noch die schweren Holzaufzüge leicht überwinden, die Reisende der Horde hinaufbefördern. Seil- und Plankenbrücken verbinden den Posten mit benachbarten Felsnadeln und bieten dem Außenposten hoch oben Schutz.\n\nHarpyien kreischen entlang der Klippen, während die Tauren die nahen Wyvern-Brutstätten am Steilhang hüten. Dort entnehmen sie Eier aus wilden Gelegen und ziehen die Jungen zu treuen Wind Rider-Reittieren für die Horde heran."},{t="Schatten vom Düsterwolkengipfel",b="Der Freiwindposten beobachtet den Stamm der Grimmtotem am Düsterwolkengipfel, nordwestlich auf der anderen Seite des Canyons. Einst als starrsinnige Traditionalisten geduldet, greifen die Grimmtotem unter Häuptling Arnak nun zu Entführungen, Mord und Gewalt. Verdächtige Rituale und das Geflüster dunkler Macht umgeben die nahen Gipfel.\n\nDie einheimischen Tauren beobachten den Himmel und die Seilbrücken mit wachsendem Grauen. Ihre gefährlichsten Feinde könnten jenseits der Canyonwinde verschanzt sein, statt unten durch die Salzebenen zu streifen."}},faq={{q="Warum wurde der Freiwindposten so hoch oben auf einem Tafelberg erbaut?",a="Der Freiwindposten erhebt sich über den Canyongrund, um Schutz vor feindlichen Kriegstrupps der Galak-Zentauren zu bieten. Zentauren sind auf ebenem Boden überlegen, können aber weder steile Klippen erklimmen noch die mechanischen Holzaufzüge der Tauren leicht überwinden.",al={"warum liegt der freiwindposten im himmel","warum tafelberg","freiwindposten höhenlage"}},{q="Wie gelangt man zum Posten hinauf und wieder hinunter?",a="Die meisten Reisenden nutzen die großen mechanischen Holzaufzüge am Fuß des Haupttafelbergs. Ein Hinterweg windet sich über Seilbrücken und Holzrampen zwischen benachbarten Felssäulen hindurch. Ein unbedachter Schritt kann einen tödlichen Sturz auf den Canyongrund bedeuten.",al={"wie zum freiwindposten hinauf","freiwindposten aufzug","freiwindposten eingang"}},{q="Wie steht der Freiwindposten zu den Grimmtotem?",a="Die Beziehungen zwischen dem Freiwindposten und den Grimmtotem sind äußerst angespannt. Den Grimmtotem am Düsterwolkengipfel nordwestlich des Postens werden Mord, Entführungen und grundlose Feindseligkeit gegenüber anderen Tauren vorgeworfen. Die Verteidiger des Postens behalten ihre Nachbarn im Auge.",al={"grimmtotem freiwindposten","düsterwolkengipfel freiwindposten","warum sind die grimmtotem hier böse"}},{q="Welche Bedeutung hat der Steilhang für den Posten?",a="Der Steilhang ist ein angestammtes Nistgebiet wilder Wyvern auf der anderen Seite des Canyons. Die Tauren des Freiwindpostens beobachten die Tiere und entnehmen ihren Nestern Eier, um die Jungen zu Wind Rider-Reittieren für die Horde heranzuziehen.",al={"warum steilhang","steilhang wyvern freiwindposten"}}},fx={["1f4dfdb3"]={q="Was ist Freiwindposten?",a="Freiwindposten ist ein befestigter Außenposten der Horde, der hoch oben auf einer hoch aufragenden Felsnadel mitten im Tausend Nadeln liegt. Überwiegend von Tauren bewohnt, die To Thunder Bluff treu ergeben sind, dient er als zentraler Knotenpunkt für Handel, Verteidigung und Kommunikation für Reisende, die durch die Schluchten zwischen dem Südlichen Brachland, Feralas und Tanaris navigieren.",al={"was ist freiwindposten","freiwindposten","über freiwindposten"}},["17ef52e2"]={q="Was geschah in Freiwindposten?",a="Die Tauren errichteten Freiwindposten auf den hohen Tafelbergen, um eine verteidigbare Festung außerhalb der Reichweite der randalierenden Galak-Zentauren unter ihnen zu bauen. Mit der Zeit entwickelte er sich zu einem unverzichtbaren Außenposten, um die Schluchten zu sichern, Wyvern-Reittiere vom nahe gelegenen Der Steilhang zu untersuchen und zu zähmen, sowie den zunehmend feindseligen Grimtotem-Clan am Düsterwolkengipfel zu überwachen.",al={"geschichte von freiwindposten","historie von freiwindposten","was geschah hier"}},["5739dc9d"]={q="Wer lebt in Freiwindposten oder verwaltet ihn?",a="Der Posten wird von Tauren der Horde bewohnt und verteidigt, die dem Häuptling Cairne Bluthuf treu ergeben sind. Neben tapferen Kriegern, die die Brücken und Aufzüge bewachen, ist er die Heimat von Händlern, Wind Rider-Meistern und Ältesten, die Patrouillen gegen regionale Bedrohungen wie die Galak-Zentauren, kreischende Harpyien und Verrat durch die nahe gelegenen Grimtotem koordinieren.",al={"wer verwaltet freiwindposten","einwohner von freiwindposten","wer lebt hier"}},["880e92a9"]={q="Ist Freiwindposten gefährlich?",a="Der Außenposten selbst ist gut geschützt, aber seine schiere Höhe macht einen Fehltritt über die Kanten oder schwankende Seilbrücken tödlich. Jenseits seines Umkreises wimmelt der Schluchtboden von feindseligen Galak-Zentauren, in den Schluchtspitzen nisten raubende Harpyien und der finstere Grimtotem-Stamm plant vom benachbarten Düsterwolkengipfel aus Verrat gegen die Stadt.",al={"ist freiwindposten gefährlich","gefahren in freiwindposten","bedrohungen für freiwindposten"}}},fp="13,212,21.506.0,31.468.1,48.208.0,41.233.0,65.270.0,48.210.0"}
P.entries["subzone:frostfire-hot-springs"] = {n="Die Frostfeuerquellen",s="Unter dem Schnee im Westen von Winterquell steigt Dampf aus den Frostfeuerquellen auf. Neugierige Gelehrte und abgehärtete Angler kommen trotz der Kälte, während feindselige Furbolgs sich nahe den Becken aufhalten.",h="Unter dem Schnee im Westen von Winterquell steigt Dampf aus den Frostfeuerquellen auf.",kw={"die flüsternde schlucht","donova schneeweh","die frostfeuerquellen","holzschlundfeste","winterfall","winterquell"},ang={["class:Druid"]="Die unerklärliche Wärme und die ungewöhnlichen Eigenschaften der Quellen werfen Fragen über die Kräfte unter Winterquell auf.",["race:Dwarf"]="Als Zwerg erkennt Ihr in Donova Schneeweh vielleicht die Neugier Eures Volkes wieder. Sie trotzt der eisigen Witterung, um geologische Rätsel zu erforschen."},sec={{t="Dampfende Wasser im Schnee",b="Nahe dem Tunnel zur Holzschlundfeste fließt an den Frostfeuerquellen warmes Wasser unter dem Schnee. Niemand weiß, was es heiß hält. Winterfallfurbolgs streifen an den Ufern umher, und ihre Angriffslust macht es gefährlich, sich den Becken zu nähern. Angler, die den Furbolgs und der Winterkälte trotzen, finden hier seltenes eisfreies Wasser, in dem Fische gedeihen."},{t="Ein geothermisches Rätsel",b="Die Quellen ziehen neugierige Beobachter an, die sich fragen, wie ihr Wasser in diesem gefrorenen Land heiß bleibt. Donova Schneeweh, eine wissbegierige Zwergin, hält in der Nähe einsame Wacht und untersucht ihren Ursprung und ihre Zusammensetzung. Sie vermutet, dass die Hitze nicht natürlichen Ursprungs sein könnte. Dunkle Magie aus der dämonischen Hochburg der Flüsternden Schlucht könnte nach Norden sickern und das Wasser unter der Erde aufwühlen."}},faq={{q="Warum gibt es heiße Quellen im eisigen Winterquell?",a="Niemand weiß, was die Quellen erhitzt. Donova Schneeweh untersucht, ob dämonischer Einfluss aus der Flüsternden Schlucht dahinterstecken könnte.",al={"warum ist das wasser heiß","ursprung der frostfeuerquellen","heißes wasser winterquell"}},{q="Wer ist Donova Schneeweh?",a="Donova Schneeweh ist eine zwergische Forscherin, die nahe den heißen Quellen lagert. Sie untersucht ihre ungewöhnlichen Eigenschaften und sucht die Hilfe von Reisenden, um die Gefahren von Winterquell zu verstehen.",al={"zwerg bei den quellen","donova schneeweh hintergrund","questgeber heiße quellen"}},{q="Könnten die Quellen mit dämonischer Magie verbunden sein?",a="Donova Schneeweh vermutet, dass dämonische Verderbnis aus der weit im Süden gelegenen Flüsternden Schlucht tief durch die Erde dringen könnte. Sie könnte unterirdische Wasserströme erhitzen oder verändern, die an den Frostfeuerquellen emporsteigen.",al={"dämon heiße quellen","verbindung zur flüsternden schlucht","verdorbenes wasser"}},{q="Wer lebt rund um die heißen Quellen?",a="Aggressive Winterfallfurbolgs beherrschen das Gebiet nahe den Quellen und greifen Fremde an, sobald sie sie erblicken. Bleibt in der Nähe der Becken wachsam.",al={"frostfeuerquellen feinde","wer kontrolliert die heißen quellen","furbolgs heiße quellen"}}},fp="21,182,27.313.0,20.365.0,51.134.0,22.175.0,43.196.0,33.122.0"}
P.entries["subzone:frostmane-hold"] = {n="Höhle der Frostmähnen",s="Frostmähnen-Trolle unternehmen Raubzüge von den Klippen südlich von Gnomeregan im westlichen Dun Morogh aus. Die Wache von Eisenschmiede beobachtet ihr Lager und ihre Höhlen, während die Räuber in die Lande der Zwerge vordringen.",h="Frostmähnen-Trolle unternehmen Raubzüge von den Klippen südlich von Gnomeregan im westlichen Dun Morogh aus.",kw={"dun morogh","frostmane","höhle der frostmähnen","kopfjäger","hauthäuter","eistroll","kharanos","vejrek"},ang={["race:Dwarf"]="Die Frostmane kämpfen seit Jahrhunderten um Dun Morogh. Als Gebirgsjäger helft Ihr, die Höhle der Frostmähnen von Feinden zu säubern und das verschneite Kernland von Eisenschmiede zu schützen.",["race:Gnome"]="Südlich von Gnomeregan bildet die Höhle der Frostmähnen eine weitere gefährliche Front neben der umkämpften ehemaligen Gnomenhauptstadt."},sec={{t="Eine Trollbastion im Schnee",b="Im westlichen Dun Morogh reicht die Höhle der Frostmähnen tief in die kalten Klippen hinein. Einfache Bauten stehen vor ihren verwinkelten Höhlen, wo Kürschner und Kopfjäger die Stammesfestung bewachen. Von hier aus überfallen Räuber der Frostmähnen die Täler, bedrohen Reisende auf Gebirgspässen und stellen die Verteidigung rund um Kharanos auf die Probe."},{t="Kharanos ein Dorn im Auge",b="Die Zwergenkommandanten in Kharanos fürchten die wachsende Streitmacht der Frostmane. Junge Gebirgsjäger und Abenteurer erkunden die Höhlen und kartieren ihre Verteidigungsanlagen. Sie dezimieren die Kriegstrupps, bevor sich der Stamm zu einem organisierten Angriff auf die Außenposten der Zwerge sammeln kann."}},faq={{q="Wer lebt in der Höhle der Frostmähnen?",a="In der Höhle leben Eistrolle der Frostmane, darunter Jäger, Hauthäuter, Kopfjäger, Häuptlinge und Räuber.",al={"wer ist in der höhle der frostmähnen","gegner in der höhle der frostmähnen","trolle in der höhle der frostmähnen"}},{q="Wo liegt die Höhle der Frostmähnen?",a="Die Höhle der Frostmähnen liegt im westlichen Dun Morogh, südlich der Industrieruinen von Gnomeregan und westlich von Kharanos.",al={"lage der höhle der frostmähnen","wo ist die höhle der frostmähnen","höhle der frostmähnen finden"}},{q="Warum interessieren sich die Zwerge für diese Höhle?",a="Die Anführer der Zwerge in Kharanos fürchten, dass die Frostmane ihre Kräfte sammeln, um Siedlungen zu überfallen. Sie entsenden Späher, um die Höhlen zu kartieren und die Reihen der Trolle zu lichten.",al={"warum die höhle der frostmähnen erkunden","kharanos trollquest"}},{q="Gibt es Troggs in der Höhle der Frostmähnen?",a="Nein. Eistrolle der Frostmane halten die Höhle besetzt. Die Troggs in Dun Morogh bleiben hauptsächlich in ihren eigenen Unterschlüpfen und den Ruinen von Gnomeregan.",al={"troggs höhle der frostmähnen","rockjaw frostmane"}}},fx={["81bf3a2c"]={q="Was ist die Höhle der Frostmähnen?",a="Die Höhle der Frostmähnen ist ein weitläufiges Höhlensystem und Basislager, das in die eisigen Berge im westlichen Dun Morogh eingebettet ist, direkt südlich von Gnomeregan. Bestehend aus rustikalen Strukturen und tiefen Höhlen, dient sie als zentrale Festung für die einheimischen Frostmähnen-Eistrolle.",al={"was ist die höhle der frostmähnen","höhle der frostmähnen dun morogh","über die höhle der frostmähnen"}},["406236bf"]={q="Ist die Höhle der Frostmähnen gefährlich?",a="Sie ist extrem gefährlich für jeden Reisenden der Allianz. Die Festung wird erbittert von den Frostmähnen-Kopfjägern und -Häutern verteidigt, die keine Gnade gegenüber Fremden zeigen, die in ihr Gebiet wandern.",al={"ist die höhle der frostmähnen gefährlich","gefahr höhle der frostmähnen","wie sicher ist die höhle der frostmähnen"}},["0c447a8f"]={q="Warum heißt es Höhle der Frostmähnen?",a="Die Festung hat ihren Namen direkt von dem Stamm der Frostmähnen-Eistrolle, die die Höhlen aushöhlten und diese gefrorenen Berge als ihre angestammte Heimat beanspruchen.",al={"warum heißt es höhle der frostmähnen","bedeutung des namens höhle der frostmähnen","woher kommt der name höhle der frostmähnen"}}},fp="14,172,28.304.0,25.238.0,28.109.0,32.105.0,44.154.0,35.123.0"}
P.entries["subzone:frostmane-hovel"] = {n="Höhle der Frostmähnen",s="Im südlichen Coldridgetal drängen Frostmähnen-Trolle auf die Übungsgelände der Zwerge vor.",h="Im südlichen Coldridgetal drängen Frostmähnen-Trolle auf die Übungsgelände der Zwerge vor.",kw={"ambossar","das coldridgetal","dun morogh","frostmane","behausung","trolle"},ang={["faction:Alliance"]="Als Reisende der Allianz könnt Ihr die Präsenz der Frostmane unmittelbar vor Ambossar erkennen. Selbst das Kernland von Eisenschmiede muss sich gegen nahe Feinde verteidigen.",["race:Dwarf"]="Als junger Bronzebeard-Rekrut, der im Coldridgetal ausgebildet wird, müsst Ihr helfen, das umliegende Gebiet gegen den feindseligen Stamm der Frostmane in solchen Höhlen zu sichern."},sec={{t="Ein Trollunterschlupf im Tal",b="Frostmähnen-Trolle suchen in Höhlen Schutz, die in die Berge südlich des Coldridgetals gehauen sind. Sie weigern sich, die verschneiten Höhen Eisenschmiede zu überlassen, und überfallen nahe Zwergenlager. Ihre Angriffe stören die Nachschubwege ins Tal."}},faq={{q="Was ist die Frostmane Hovel?",a="Frostmane-Trolle suchen in einer natürlichen Höhle im südlichen Coldridgetal Schutz vor Unwettern und dringen dabei in das Gebiet der Zwerge vor.",al={"frostmane hovel","was ist diese höhle","coldridgetal trollhöhle"}},{q="Warum gibt es Trolle im Coldridgetal?",a="Der Stamm der Frostmane lebt seit Generationen auf den verschneiten Gipfeln Dun Moroghs. Als erbitterte Rivalen der Bronzebeard-Zwerge steigen sie von den hohen Bergkämmen herab, um Nachschubwege zu überfallen und Zwergensiedlungen herauszufordern.",al={"warum trolle hier","dun morogh trolle","präsenz der frostmane"}},{q="Wer kontrolliert diese Höhle?",a="Plündernde Frostmane-Trolle halten die Höhle besetzt und nutzen ihre geschützte Felsspalte als Ausgangspunkt für Vorstöße über die südliche Hochfläche des Tals.",al={"wer führt die höhle","wer lebt in frostmane hovel"}}},fp="15,89,25.221.0,28.131.0,41.206.0,23.126.0"}
P.entries["subzone:frostsaber-rock"] = {n="Frostsäblerfelsen",s="Frostsäbler finden am Frostsäblerfelsen im Norden von Winterquell Zuflucht und Ausbildung. Seine felsige Anhöhe überblickt die verschneiten Weiten der Region.",h="Frostsäbler finden am Frostsäblerfelsen im Norden von Winterquell Zuflucht und Ausbildung.",kw={"allianz reittier","frostsäbler","frostsäblerfelsen","rivern frostwind","wintersaber","winterquell"},ang={["class:Hunter"]="Als Jäger könnt Ihr auf dem Felsen und an den umliegenden Hängen einige der wildesten einheimischen Raubtiere des nördlichen Kalimdor beobachten.",["faction:Alliance"]="Als Held der Allianz könnt Ihr auf dem Felsen Rivern Frostwinds Vertrauen gewinnen und die mühsame Ausbildung beginnen, um den berühmten Frostsäbler aus Winterquell zu reiten."},sec={{t="Ein Hochsitz in der Tundra",b="Der Frostsäblerfelsen erhebt sich über die gefrorene Wildnis im Norden von Winterquell. Frostsäbler durchstreifen seine Hänge und Täler. Auf dem Gipfel zieht Rivern Frostwind, ein einsamer Nachtelf, die Katzen auf und pflegt sie. Champions der Allianz, die den rauen Bedingungen trotzen und ihre Hingabe beweisen, können das seltene Privileg erlangen, Aufzucht, Zähmung und Reiten eines dieser Schneereittiere zu erlernen."}},faq={{q="Wer lebt auf dem Frostsäblerfelsen?",a="Rivern Frostwind lagert auf dem Gipfel und bildet die Frostsäblerkatzen der Region aus. Mitglieder der Allianz, die einen Frostsäbler als Gefährten suchen, können in ihm einen Lehrmeister finden.",al={"wer ist am frostsäblerfelsen","frostsäblerfelsen lehrmeister","rivern standort"}},{q="Können Spieler der Horde hier Wildtiere ausbilden?",a="Nein. Rivern Frostwind bietet nur vertrauenswürdigen Verbündeten der Allianz Ausbildung und tierische Gefährten an. Reisende der Horde sind auf dem Gipfel nicht willkommen.",al={"horde frostsäblerfelsen","kann die horde einen frostsäbler bekommen","rivern horde"}},{q="Welche Kreaturen leben rund um den Felsen?",a="Wilde Frostsäblerkatzen durchstreifen den eisigen Felsen und die nahe gelegenen Hochebenen. Auch andere widerstandsfähige Wildtiere, die im rauen Klima von Winterquell heimisch sind, leben dort.",al={"was lebt hier","frostsäblerfelsen wildtiere","frostsäbler in winterquell"}}},fp="15,137,21.357.0,31.159.0,36.137.0,41.139.0"}
P.entries["subzone:frostwhisper-gorge"] = {n="Frosthauchschlucht",s="Im Süden von Winterquell verläuft die Frosthauchschlucht direkt nördlich der Flüsternden Schlucht. Uralte Nachtelfenruinen liegen auf ihrem eisigen Boden und ihren Klippen, die nun von Frostmaulriesen beherrscht werden. Ein einsames Zwergenlager am östlichen Rand überblickt das Meer.",h="Im Süden von Winterquell verläuft die Frosthauchschlucht direkt nördlich der Flüsternden Schlucht.",kw={"die flüsternde schlucht","frostmaul","frosthauchschlucht","eisenschmiede","winterquell"},ang={["race:Dwarf"]="Hoch am östlichen Rand des Abgrunds hat ein reisender Zwerg sein Lager aufgeschlagen. Dort gibt es ein Banner von Eisenschmiede, ein Gewehr und reichlich Bier, mit Blick auf das Meer.",["race:NightElf"]="Uralte Nachtelfenbauwerke liegen in den verschneiten Tiefen der Schlucht, wo nun Frostmaulriesen umherstreifen."},sec={{t="Ein gefrorener Abgrund voller Ruinen und Riesen",b="Die Frosthauchschlucht durchschneidet die südlichen Berge von Winterquell, direkt nördlich der Flüsternden Schlucht. Schnee bedeckt den Schluchtboden und die Klippenkämme, wo Mauerreste uralter Nachtelfensiedlungen erhalten sind. Frostmaulriesen und ihre Bewahrer beanspruchen die Schlucht nun für sich. Sie verteidigen ihre gefrorenen Felsen erbittert und machen Reisen in die Schlucht gefährlich."},{t="Der östliche Aussichtspunkt",b="Ein schmaler, stiller Pfad führt zu einem kleinen Außenposten oben auf den östlichen Klippen der Schlucht. Reisende, die auf Wyvern oder Greifen zwischen Azshara, Orgrimmar und Winterquell fliegen, können ihn von oben entdecken. Ein Banner von Eisenschmiede kennzeichnet das einsame Zwergenlager am Klippenrand. Dort stehen Proviantkisten, Bierfässer, ein bequemer Stuhl und ein Gewehr, das an seine Ablage gelehnt ist. Vom Lager blickt man über den Abhang hinunter zum großen Meer."}},faq={{q="Welche Kreaturen leben in der Frosthauchschlucht?",a="Frostmaulriesen und ihre Bewahrer bewohnen den Schluchtboden und die umliegenden Terrassen.",al={"monster in der frosthauchschlucht","was lebt in der frosthauchschlucht","frosthauchschlucht gegner"}},{q="Wo liegt die Frosthauchschlucht?",a="Die Frosthauchschlucht durchschneidet die eisigen Klippen im Süden von Winterquell, direkt nördlich der Flüsternden Schlucht.",al={"frosthauchschlucht lage","wo ist die frosthauchschlucht","frosthauchschlucht karte"}},{q="Was ist das kleine Zwergenlager auf den östlichen Klippen?",a="Über einem einsamen Zwergenlager auf dem östlichen Kamm weht ein Banner von Eisenschmiede. Dort gibt es einen Stuhl, ein Gewehr, Proviantkisten und Bierfässer. Das Lager bietet einen Blick über die Klippe zum Meer.",al={"zwergenlager winterquell","eisenschmiede flagge frosthauchschlucht","lager auf den östlichen klippen"}},{q="Gibt es unten in der Schlucht Nachtelfenruinen?",a="Ja. Uralte Säulen und Mauerreste der Nachtelfen liegen auf dem Schluchtboden und den oberen Klippenkämmen, Überreste alter Behausungen der Kaldorei.",al={"elfenruinen frosthauchschlucht","nachtelfenarchitektur winterquell schlucht"}}},fp="18,235,34.346.0,20.418.0,42.96.0,36.100.0,51.188.0,44.135.0"}
P.entries["subzone:fungal-rock"] = {n="Fungusfels",s="An der nordöstlichen Klippe des Kraters von Un'Goro haben Gorillas ihren Bau im Fungusfels. Geisterpilze wachsen in seinen feuchten Gängen, die zu den gefährlichsten Affenbauen des Kraters gehören.",h="An der nordöstlichen Klippe des Kraters von Un'Goro haben Gorillas ihren Bau im Fungusfels.",kw={"a-me 01","krater","fungusfels","geisterpilz","gorilla","u'cha","uhk'loc","un'goro"},ang={["profession:Herbalism"]="Am Fungusfels könnt Ihr Geisterpilze sammeln, doch Gorillas bewachen die Höhlengänge und verteidigen ihr Revier.",["race:Gnome"]="Als Gnom möchtet Ihr vielleicht A-Me 01 untersuchen, Karna Remtravels mechanischen Affenprototyp, der nahe dem Teich am Eingang zurückgelassen wurde."},sec={{t="Der Affenbau",b="Ein Wasserfall und ein Teich markieren den Eingang zum Fungusfels am nordöstlichen Rand des Kraters von Un'Goro. Gewaltige Gorillas haben ihren Bau in den feuchten unterirdischen Gängen. Un'Goro Stompers und Thunderers bewegen sich dort zwischen Geisterpilzen. Tief im Inneren behaupten der Silberrücken U'cha und der Albinogorilla Uhk'loc ihr Revier. Nahe dem Höhleneingang kann ein neugieriger Reisender A-Me 01 finden, einen beschädigten mechanischen Affen, den Gnomenforscher zurückgelassen haben."}},faq={{q="Was ist der Fungusfels?",a="Die feuchten Gänge des Fungusfels schneiden sich in die nordöstliche Wand des Kraters von Un'Goro. Geisterpilze wachsen zwischen den feindseligen Gorillas in seinen Höhlen.",al={"wo ist der fungusfels","was ist die höhle im fungusfels"}},{q="Wer herrscht über die Affen im Fungusfels?",a="U'cha, ein gewaltiger Silberrücken, beherrscht die tiefste Kammer des Fungusfels. Auch der seltene weiße Gorilla Uhk'loc streift durch die Höhlen.",al={"wer ist u'cha","boss im fungusfels","anführer im fungusfels"}},{q="Warum steht ein mechanischer Gorilla vor der Höhle?",a="A-Me 01 ruht nahe dem Teich vor dem Eingang zum Fungusfels. Der Zwergenforscher Karna Remtravel baute den mechanischen Affen, der während der Feldbeobachtungen ausfiel und auf Bergung oder Reparatur wartet.",al={"was ist a-me 01","robotergorilla ungoro","ame 01"}},{q="Welche wertvollen Rohstoffe wachsen im Fungusfels?",a="Geisterpilze wachsen im feuchten, schattigen Inneren des Fungusfels. Er ist einer der wenigen Orte im südlichen Kalimdor, an denen Kräuterkundige diesen begehrten Pilz sammeln können.",al={"geisterpilze ungoro","kräuter im fungusfels"}}},fp="11,166,11.422.0,20.134.0,38.120.0,51.191.0,44.163.0"}
P.entries["subzone:fungal-vale"] = {n="Das Fungustal",s="Im Fungustal streifen Schrecken der Geißel unter trübem Dunst umher, und Akolythen des Kults der Verdammten dienen zwischen den Pilzen. Das Tal liegt im südlichen Zentrum der Östlichen Pestländer, nördlich vom Turm der Kronenwache und Marris' Siedlung.",h="Im Fungustal streifen Schrecken der Geißel unter trübem Dunst umher, und Akolythen des Kults der Verdammten...",kw={"verseuchung","turm der kronenwache","kult der verdammten","östliche pestländer","das fungustal","pilz","marris' siedlung","seuche des untods","geißel"},ang={["class:Druid"]="Als Druide seht Ihr im Fungustal den Kreislauf der Natur verhöhnt, wo die Geißel das Leben durch endlose, unheilige Fäulnis ersetzt hat.",["profession:Herbalism"]="Als Kräuterkundiger seht Ihr, wie Nekromantie Lordaerons heimische Pflanzen verdirbt und den Boden mit Pilzen erstickt."},sec={{t="Ein Garten der Fäulnis",b="Nördlich von Marris' Siedlung gehört das Fungustal zu den am stärksten verderbten Orten Lordaerons. Kränklich violette Erde quillt unter einem Dunst aus nekrotischen Sporen vor fremdartigen Pilzen auf. Die Seuche des Untods hat den Boden verformt und unheilige Gewächse hervorgebracht, die Aasbestien und schlurfende Untote nähren. Mitglieder des Kults der Verdammten pflegen die verseuchten Blüten und vollziehen inmitten des Verfalls üble Riten."}},faq={{q="Was ist das Fungustal?",a="Das Fungustal ist ein verderbtes Tal in den südlichen Östlichen Pestländern, nördlich vom Turm der Kronenwache und Marris' Siedlung. Die Seuche des Untods hat das Land verseucht und gewöhnliche Vegetation in ausufernde Pilzwucherungen verwandelt.",al={"wo liegt das fungustal","geschichte des fungustals","überblick über das fungustal"}},{q="Warum ist der Boden hier violett?",a="Die Seuche des Untods hat den Boden mit nekrotischer Macht durchtränkt. Sie verformt das Land zu einem fruchtbaren Nährboden für hoch ansteckende Sporen und färbt die Erde violett wie einen Bluterguss.",al={"warum ist der boden violett","violette erde pestländer","boden im fungustal"}},{q="Wer kontrolliert dieses Gebiet?",a="Schrecken der Geißel und sterbliche Kultisten des Kults der Verdammten halten das Fungustal besetzt. Untote wandern durch den Dunst, während Akolythen die verderbten Pilze pflegen.",al={"wer ist im fungustal","feinde im fungustal","kultisten im fungustal"}},{q="Wo liegt es im Verhältnis zu den örtlichen Wegmarken?",a="Das Fungustal liegt im südlichen Zentrum der Östlichen Pestländer, nördlich der Straße zwischen Marris' Siedlung und dem Turm der Kronenwache.",al={"wie gelangt man ins fungustal","lage des fungustals","nahe dem turm der kronenwache"}}},fp="11,210,15.372.0,24.221.0,30.164.0,23.151.0,48.116.0"}
P.entries["subzone:furlbrow-s-pumpkin-farm"] = {n="Brauenwirbels Kürbishof",s="Banditen und Erntegolems halten Brauenwirbels Kürbishof im nördlichen Westfall besetzt, abseits der Straße aus dem Wald von Elwynn. Bauer Brauenwirbel und Verna haben ihr Zuhause an die Bruderschaft der Defias verloren.",h="Banditen und Erntegolems halten Brauenwirbels Kürbishof im nördlichen Westfall besetzt, abseits der Straße...",kw={"defias","hof","brauenwirbel","erntegolem","jansen","kürbis","verna","westfall"},ang={["faction:Alliance"]="Für die Allianz zeigt der überrannte Hof, dass Sturmwind beim Schutz seines Kernlands versagt hat. Treue Bauern bleiben den Banditen schutzlos ausgeliefert."},sec={{t="Eine verlorene Ernte",b="Nahe der nördlichen Grenze von Westfall versorgte Brauenwirbels Kürbishof einst das Königreich mit Nahrung. Die Bruderschaft der Defias vertrieb Bauer Brauenwirbel und seine Frau Verna von ihrem Land. Nun durchstreifen mechanische Erntegolems die Felder und greifen jeden an, der sich nähert. Banditen besetzen die Hofgebäude, während die rechtmäßigen Besitzer neben der Straße nahe Jansens Hof lagern und um ihr Zuhause und ihre Lebensgrundlage trauern."},{t="Bollwerk der Defias",b="Die Bruderschaft der Defias hat Gehöfte wie das von Brauenwirbel eingenommen, während Sturmwinds Militärgarnison darum ringt, die Bauern auf dem Land in Westfall zu schützen. Banditen lagern auf dem Hof und nutzen ihn als Aufmarschgebiet. Tödliche Erntewächter sichern die Grenzen des Geländes, sodass Reisende auf der nahen Hauptstraße Hinterhalten ausgeliefert sind."}},faq={{q="Wem gehört dieser Kürbishof?",a="Bauer Brauenwirbel und seine Frau Verna Brauenwirbel besitzen den Hof. Gesetzlose vertrieben sie, und das Paar sucht nun an der Straße nahe Jansens Hof Zuflucht.",al={"wem gehört brauenwirbels hof","brauenwirbel besitzer","wer lebt hier"}},{q="Warum ist der Hof verlassen?",a="Die Bruderschaft der Defias nahm den Hof ein und vertrieb die Brauenwirbels. Schläger besetzen die Gebäude, während durchgedrehte mechanische Erntegolems das Kürbisfeld bewachen.",al={"warum ist der hof verlassen","was ist mit dem hof passiert","warum sind hier banditen"}},{q="Wo sind die Brauenwirbels jetzt?",a="Bauer Brauenwirbel und seine Frau suchen direkt nordöstlich des Hofes neben der Hauptstraße nahe Jansens Hof Zuflucht. Ihren Karren und ihre Habseligkeiten haben sie bei sich.",al={"wo ist bauer brauenwirbel","brauenwirbel aufenthaltsort","brauenwirbel finden"}},{q="Warum greifen mechanische Erntegolems hier Menschen an?",a="Die mechanischen Konstrukte sind darauf programmiert, die Bewohner von Westfall anzugreifen, und patrouillieren auf Land, das die Defias besetzt halten. Ihre genaue Herkunft bleibt ungewiss.",al={"erntegolems","warum sind golems feindselig","wer hat die golems erschaffen"}}},fx={["3bec6795"]={q="Was ist Brauenwirbels Kürbishof?",a="Brauenwirbels Kürbishof ist ein überlaufener Hof im nördlichen Westfall, der einst dem Anbau von Kürbissen für das Königreich Sturmwind gewidmet war. Heute steht er als ein weiteres Opfer des Niedergangs des Reiches da, seine fruchtbaren Felder bleiben unbebaut und wurden von Gesetzlosen übernommen.",al={"was ist brauenwirbels kürbishof","brauenwirbels kürbishof lore","brauenwirbel hof"}},["1ceb8202"]={q="Was geschah auf Brauenwirbels Kürbishof?",a="Als The Defias Brotherhood in ganz Westfall aufstieg, fegten ihre Banditen durch das lokale Land und zwangen Bauer Brauenwirbel und seine Frau Verna, um ihr Leben zu fliehen. Die Bruderschaft beschlagnahmte das Anwesen, stationierte Diebe im Bauernhaus und ließ mechanische Erntegolems frei, um auf dem Feld zu patrouillieren.",al={"geschichte brauenwirbel hof","was passierte mit brauenwirbels hof","wie fiel brauenwirbels hof"}},["25362e80"]={q="Ist Brauenwirbels Kürbishof gefährlich?",a="Ja. Der Hof ist zu einer Hochburg der Defias geworden. Feindliche Banditen besetzen die Gebäude, während abtrünnige Erntegolems durch die Kürbisfelder streifen und jeden Reisenden oder vertriebenen Bauern angreifen, der es wagt, sich zu nähern.",al={"ist brauenwirbels kürbishof gefährlich","gefahr brauenwirbels kürbishof","bedrohungen bei brauenwirbels kürbishof"}}},fp="23,184,14.380.0,17.302.0,27.150.0,26.161.0,28.149.0,56.147.0"}
P.entries["subzone:gadgetzan"] = {n="Gadgetzan",s="Handel führt beide Fraktionen nach Gadgetzan, wo das Steamwheedle Cartel den Frieden wahrt. Jeder darf eintreten, sofern er Münzen mitbringt oder Arbeit anzubieten hat.",h="Handel führt beide Fraktionen nach Gadgetzan, wo das Steamwheedle Cartel den Frieden wahrt.",kw={"auktionshaus","gadgetzan","goblin","neutral","steamwheedle cartel","tanaris","wastewander","wasserfeld"},ang={["profession:Blacksmithing"]="Als Schmied könnt Ihr Gadgetzans leistungsfähige Schmieden und Ambosse nutzen, die erfahrene Metallhandwerker bevorzugen. Die Stadt ist ein wichtiger Sammelpunkt für Mitglieder des Mithril Order.",["profession:Engineering"]="Als Ingenieur findet Ihr in Gadgetzan fortgeschrittene Lehrer und spezielle Baupläne. Die Stadt verfügt außerdem über eine Teleportationsplattform für Ankünfte, die auf gnomische Ingenieure abgestimmt ist."},sec={{t="Eine Bastion des Profits",b="Inmitten der sengenden Sande von Tanaris ist Gadgetzan der Handelsstützpunkt des Steamwheedle Cartel im südlichen Kalimdor. Goblinerfindungsgeist verleiht den Gebäuden ihre zusammengewürfelte Gestalt. Darin befinden sich ein Auktionshaus, eine Bank, ein Gasthaus und Werkstätten für Ingenieure, Schmiede und Alchemisten.\n\nFlugmeister befördern Reisende beider Fraktionen nach Tanaris, Feralas und ins Becken von Un'Goro. Hier herrscht der Handel. Lasst Eure Waffen in den Scheiden und haltet Euren Geldbeutel offen, dann lassen die Goblins Euch in Frieden passieren."},{t="Wüstennöte und erzwungene Ordnung",b="Goblin-Schläger sorgen in Gadgetzan für Ordnung. Sie verprügeln jeden, der den Handel gefährdet oder eine Schlägerei zwischen den Fraktionen anzettelt. Jenseits der Tore kämpft die Gadgetzan Water Company am Wasserfeld gegen Wastewander-Banditen. Wasser ist in Tanaris kostbar, daher heuert das Kartell Söldner an, um die Banditenanführer zu besiegen und Wasserbeutel zurückzuholen. Die Wasserspeicher der Stadt hängen von diesem Nachschub ab."}},faq={{q="Können Allianz und Horde einander in Gadgetzan angreifen?",a="Nein. Das Steamwheedle Cartel hält Gadgetzan streng neutral. Goblin-Schläger patrouillieren durch die Stadt und greifen jeden an, der den Frieden bricht oder anderen Reisenden Schaden zufügt.",al={"ist gadgetzan sicher","pvp in gadgetzan","können horde und allianz hier kämpfen"}},{q="Warum ist Wasser hier so wichtig?",a="Gadgetzan ist auf Wasser aus den Fördertürmen der Gadgetzan Water Company am Wasserfeld angewiesen. Wastewander-Banditen haben die Brunnen überrannt und die Hauptwasserversorgung der Stadt abgeschnitten. Deshalb bieten die Goblins Belohnungen für gestohlene Wasserbeutel.",al={"gadgetzan water company","warum wasserbeutel","konflikt am wasserfeld"}},{q="Wer kontrolliert Gadgetzan?",a="Das Steamwheedle Cartel besitzt und regiert Gadgetzan. Es ist Azeroths größte und bekannteste Handelsorganisation der Goblins.",al={"wer regiert gadgetzan","gadgetzan fraktion","welchem kartell gehört gadgetzan"}},{q="Was macht das Auktionshaus hier besonders?",a="Gadgetzans neutrales Auktionshaus ermöglicht es Allianz und Horde, miteinander Waren zu handeln. Für dieses Vorrecht verlangen die Goblins eine wesentlich höhere Transaktionsgebühr.",al={"gadgetzan auktionshaus","neutrales auktionshaus","fraktionsübergreifendes ah"}}},fp="9,148,32.484.0,34.375.0,54.158.0,41.241.0,23.126.0,42.160.0"}
P.entries["subzone:gahrron-s-withering"] = {n="Gahrrons Trauerfeld",s="Auf Gahrrons Trauerfeld verseucht die Geißel einen alten Bauernhof Lordaerons an der Straße zu den Östlichen Pestländern. Ein gewaltiger Kessel stößt Pestdämpfe in die Luft.",h="Auf Gahrrons Trauerfeld verseucht die Geißel einen alten Bauernhof Lordaerons an der Straße zu den Östlichen...",kw={"kessel","darrowshire","gahrron","gahrrons trauerfeld","joseph redpath","soulwrath"},ang={["class:Paladin"]="Als Paladin findet Ihr in den abscheulichen Dämpfen aus dem Kessel von Cauldron Lord Soulwrath und den rastlosen Toten auf den verwüsteten Feldern ein klares Ziel.",["faction:Alliance"]="Für Veteranen der Allianz birgt dieser Bauernhof eine düstere Erinnerung. Der gesprungene Schild von Captain Joseph Redpath liegt noch immer im verfluchten Boden, ein Überbleibsel von Darrowshires Fall."},sec={{t="Von Ernte zu Verfall",b="Vor dem Dritten Krieg versorgte dieser Bauernhof Lordaeron mit Getreide. Dann fegten der Kult der Verdammten und die Geißel über das Land, und die Felder verstummten. Nun liegt das Gehöft zerstört und verlassen da. Quälende Visionen, klagende Gespenster und rastlose Geister durchstreifen die verfallenen Nebengebäude unter Aufsehern der Geißel, die dem Lich King die Treue geschworen haben."},{t="Der Kessel und Redpaths Fall",b="Cauldron Lord Soulwrath betreut einen gewaltigen Pestkessel der Geißel inmitten der verdorbenen Felder. Giftiges Miasma strömt daraus hervor, vergiftet die Erde und vertreibt alles natürliche Leben.\n\nDieser Bauernhof markiert auch das tragische Ende der Tragödie im nahegelegenen Darrowshire. Verteidiger der Allianz stellten hier Captain Joseph Redpath und streckten ihn nieder, nachdem dunkle Verderbnis von ihm Besitz ergriffen hatte. Sein zersplitterter Schild liegt noch immer im verfluchten Boden."}},faq={{q="Wie hieß Gahrrons Trauerfeld vor der Pest?",a="Keine Aufzeichnung bewahrt den Namen des Bauernhofs vor der Pest. Heute ist er nur noch als Gahrrons Trauerfeld bekannt. Er war ein bewirtschaftetes Gehöft Lordaerons, bis die Geißel das Umland verwüstete.",al={"ursprünglicher name","alter name","gahrrons quickening"}},{q="Warum steht hier ein riesiger Kessel?",a="Die Geißel stellte den Kessel hier auf, um Pestdämpfe in der ganzen Region zu verbreiten. Cauldron Lord Soulwrath bewacht ihn, damit er weiterhin Boden und Luft verseuchen kann.",al={"pestkessel","was bewirkt der kessel","topf auf dem feld"}},{q="Wer war Joseph Redpath und warum ist er hier von Bedeutung?",a="Captain Joseph Redpath verteidigte das nahegelegene Darrowshire und zählt zu den Helden des Ortes. Sein gesprungener Schild liegt nahe der Scheune des Gehöfts, ein Relikt von Darrowshires tragischem Fall.",al={"redpaths schild","captain redpath","verbindung zu darrowshire"}},{q="Wer kontrolliert Gahrrons Trauerfeld derzeit?",a="Die Geißel hält den Bauernhof besetzt. Geisterhafte Gespenster, klagende Tode und quälende Visionen suchen ihn unter Cauldron Lord Soulwrath heim, einem mächtigen Offizier der Nekromantie.",al={"wer ist hier","gegner bei gahrron","geißel hat das sagen"}}},fp="19,159,21.327.0,36.415.1,54.182.0,35.156.0,51.177.1,43.154.0"}
P.entries["subzone:galardell-valley"] = {n="Galardelltal",s="Gnolle durchstreifen das Galardelltal unterhalb des Turms von Ilgalar im nordöstlichen Rotkammgebirge. Das Tal bedroht die nahen Siedlungen.",h="Gnolle durchstreifen das Galardelltal unterhalb des Turms von Ilgalar im nordöstlichen Rotkammgebirge.",kw={"fangore","galardelltal","gnolle","morganth","rotkammgebirge","der turm von ilgalar"},ang={["faction:Alliance"]="Seenhains überforderte Stadtwache kann die Straße nach Nordosten nicht sichern, solange Gnollrudel und Morganths dunkle Präsenz das Galardelltal beherrschen."},sec={{t="Ein Hort der Bestien und Schatten",b="Gnolle aus dem Rotkammgebirge durchstreifen das Galardelltal, außerhalb der Reichweite von Seenhains Verteidigern. Sie streifen durch das Tiefland und lagern auf dem Schluchtboden, unter brutalen Rudelführern wie Leutnant Fangore. Über den Schluchten erhebt sich der Turm von Ilgalar, die Festung des abtrünnigen Magiers Morganth. Gemeinsam machen Gnolle und Turm das Tal zu einer Quelle des Schreckens für die nahen Siedlungen."}},faq={{q="Wo liegt das Galardelltal?",a="Das Galardelltal liegt im äußersten Nordosten des Rotkammgebirges, hinter den hohen Felsklippen jenseits der Straßen, die vom Immerruhsee nach Norden führen.",al={"galardelltal lage","wo liegt das galardelltal","wie findet man das galardelltal"}},{q="Welche Kreaturen leben im Tal?",a="Blutrünstige Gnollrudel durchstreifen die Pfade des Tals in dichten Gruppen, angeführt von gefährlichen Rohlingen wie Leutnant Fangore.",al={"gegner im galardelltal","wer lebt im galardelltal","galardell gegner"}},{q="Was ist der dunkle Turm über dem Tal?",a="Der Turm von Ilgalar ist die steinerne Festung des abtrünnigen Zauberers Morganth und überragt das Tal.",al={"galardelltal turm","turmspitze über galardell","turm bei gnollen im rotkammgebirge"}},{q="Wer ist Leutnant Fangore?",a="Leutnant Fangore ist ein gefährlicher Gnollanführer im Tal. Wenn er herausgefordert wird, ruft er listig und wild mit seinem Heulen nahe Gnollrudel zu Hilfe. Sie können unvorsichtige Reisende rasch überwältigen.",al={"fangore","leutnant fangore","galardelltal boss"}}},fx={["3f06acf8"]={q="Was ist das Galardelltal?",a="Das Galardelltal ist ein zerklüftetes Becken in den nordöstlichen Ausläufern des Rotkammgebirges. Das Tal wird von der drohenden Silhouette vom Turm von Ilgalar dominiert und ist in feindliche Hände gefallen, da es völlig von Rudeln aggressiver Gnolle überrannt und in dunkle Magie gehüllt wurde.",al={"was ist das galardelltal","galardelltal lore","erzähle mir vom galardelltal"}},eb0794a1={q="Wie gefährlich ist das Galardelltal?",a="Es ist extrem gefährlich. Wilde Gnollrudel patrouillieren durch die Klippen und das dichte Gestrüpp und arbeiten zusammen, um Eindringlinge zu umschwärmen. Schlimmer noch, ihr Anführer, Leutnant Fangore, kann unter dem wachsamen Auge des dunklen Zauberers Morganth schnell Verstärkung aus der Umgebung herbeirufen, um unvorsichtige Reisende zu überwältigen.",al={"ist das galardelltal gefährlich","gefahr im galardelltal","ist es hier sicher"}}},fp="16,129,26.365.0,34.153.0,34.116.0,46.100.0,26.185.0"}
P.entries["subzone:gallery-of-treasures"] = {n="Gallery of Treasures",s="Im Scharlachroten Kloster verbindet die Gallery of Treasures das Huntsman's Cloister mit dem Athenaeum. Der Scharlachrote Kreuzzug bewacht einen Korridor voller Gemälde, Relikte und illuminierter Texte Lordaerons, während er Krieg gegen die Untoten führt.",h="Im Scharlachroten Kloster verbindet die Gallery of Treasures das Huntsman's Cloister mit dem Athenaeum.",kw={"athenaeum","gallery of treasures","library","lordaeron relikte","gemälde","das scharlachrote kloster"},ang={["class:Paladin"]="Als Paladin seht Ihr Artefakte und Banner, die an den verlorenen Ruhm der Silver Hand und des gefallenen Lordaeron erinnern. Nun sind sie in den Händen von Fanatikern, deren rechtschaffene Überzeugung in blinden Fanatismus umgeschlagen ist.",["race:Undead"]="Als Untoter seht Ihr Gemälde und Erbstücke, die Euren Vorfahren unter den Verlassenen gehörten. Lebende Kreuzfahrer bewachen sie eifersüchtig, während sie danach trachten, Lordaerons einstige Bürger auszulöschen."},sec={{t="Ein Hort verlorenen Erbes",b="Tief im Library-Flügel erstreckt sich die Gallery of Treasures von den Hundezwingern des Huntsman's Cloister bis zu den Archiven des Athenaeum. Gemälde und historische Artefakte säumen den Korridor. Kleine Kammern beherbergen Bücher, die aus allen Teilen des gefallenen Lordaeron geborgen wurden.\n\nDer Scharlachrote Kreuzzug nennt diese Relikte das unbefleckte Vermächtnis der Menschheit und hat geschworen, dieses Erbe zu schützen. Seine Fanatiker bewachen den Durchgang gegen Außenstehende, die ihr Heiligtum betreten."}},faq={{q="Wo befindet sich die Gallery of Treasures?",a="Die Gallery of Treasures liegt im Library-Flügel des Scharlachroten Klosters. Gleich hinter dem Huntsman's Cloister führt der verzierte Durchgang zum Athenaeum.",al={"galerie standort","wo ist gallery of treasures","wie findet man gallery of treasures"}},{q="Was wird in der Gallery of Treasures aufbewahrt?",a="Die Galerie beherbergt erhaltene Kunstwerke, historische Relikte, illuminierte Texte und Gemälde, die aus dem verwüsteten Lordaeron geborgen wurden. Sie säumen den Korridor und füllen die angrenzenden Lesekammern.",al={"was ist in gallery of treasures","galerie beute","galerie relikte"}},{q="Warum sammelt der Scharlachrote Kreuzzug diese Schätze?",a="Der Scharlachrote Kreuzzug sieht sich als Lordaerons wahrer Überrest. Er sammelt kulturelle Werke, um die Erinnerung an seine Heimat und ihr heiliges Erbe zu bewahren, während er ausmerzt, was er für unrein hält.",al={"warum hat der scharlachrote kreuzzug schätze","zweck der kreuzzugsrelikte"}},{q="Wer bewacht die Galerie?",a="Fanatiker des Scharlachroten Kreuzzugs patrouillieren im Korridor, darunter Verteidiger und Initianden. Sie bewachen den Weg zu Arkanist Doan und den tiefer gelegenen Archiven des Klosters.",al={"galerie gegner","wer ist in gallery of treasures"}}},fx={a0f9e8c0={q="Ist die Gallery of Treasures gefährlich?",a="Ja, zutiefst. Die Galerie wird schwer von eifrigen Verteidigern des Scharlachroten Kreuzzugs bewacht, die jeden Außenstehenden als Agenten der Verderbnis oder der Geißel betrachten. Sich durch ihre prunkvollen Hallen zu bewegen bedeutet, sich an disziplinierten Kreuzrittern vorbeizukämpfen, die bereit sind, Eindringlinge auf der Stelle abzuschlachten.",al={"ist die gallery of treasures gefährlich","gefahr gallery of treasures","gefahr scharlachrotes kloster galerie"}}},fp="20,228,29.421.0,42.160.0,41.180.0,53.179.0,23.157.0"}
P.entries["subzone:gallows-end-tavern"] = {n="Taverne Zur Galgenschlinge",s="In Brill versammeln sich Verlassene in der Taverne Zur Galgenschlinge, um Gastfreundschaft und Gemeinschaft zu erleben. Das wichtigste Gasthaus des Ortes bietet Schutz und Spirituosen, mit Klassenlehrern und Handwerksausbildern in seinen Hallen und geheimen Verhören darunter.",h="In Brill versammeln sich Verlassene in der Taverne Zur Galgenschlinge, um Gastfreundschaft und Gemeinschaft...",kw={"brill","verlassene","taverne zur galgenschlinge","gastwirt","scharlachroter zelot","tirisfal","untoter"},ang={["faction:Alliance"]="Unter der Schankstube halten die Verlassenen gefangene Späher der Allianz und Zeloten des Scharlachroten Kreuzzugs fest, um Informationen zu gewinnen und Verhöre durchzuführen.",["race:Undead"]="Als neu erwachter Verlassener findet Ihr in der Taverne Zur Galgenschlinge Euer erstes bedeutendes Gasthaus jenseits von Todesend. Sie ist ein Knotenpunkt auf dem Weg in die weite Welt."},sec={{t="Ein Treffpunkt der Toten",b="An Brills Straße versammeln sich in der Taverne Zur Galgenschlinge neu erwachte Verlassene, die Todesend verlassen und nach Süden in Richtung Unterstadt reisen. Obwohl sie untot sind, kommen sie wegen der Gemeinschaft, des Handels und der Zuflucht. Klassenlehrer unterweisen junge Krieger, Priester, Magier, Schurken und Hexenmeister. Auch Händler und Mediziner sind hier anzutreffen."},{t="Geheimnisse im Keller",b="Unter den Dielen der Taverne werden Kriegsgefangene gefesselt und vor den Blicken der Öffentlichkeit bewacht. Unter ihnen befinden sich ein gefangener Scharlachroter Zelot und ein zwergischer Gebirgsjäger. Die Verlassenen halten sie für Verhöre und Experimente fest, während sie darum kämpfen, ihre Grenzen gegen eifernde Kreuzfahrer und Späher der Allianz zu sichern."}},faq={{q="Wo befindet sich die Taverne Zur Galgenschlinge?",a="Die Taverne Zur Galgenschlinge steht im Zentrum von Brill, der wichtigsten Siedlung der Verlassenen in Tirisfal, unmittelbar nördlich von Unterstadt.",al={"taverne zur galgenschlinge standort","wo ist die taverne zur galgenschlinge","brill gasthaus standort"}},{q="Warum brauchen die Untoten ein Gasthaus oder eine Taverne?",a="Die Verlassenen brauchen weder Schlaf noch die Nahrung der Sterblichen, um zu überleben, doch Tavernen bewahren soziale Bindungen und Gewohnheiten aus ihrem früheren Leben. Die Taverne Zur Galgenschlinge bietet außerdem einen sicheren Mittelpunkt des Gemeindelebens für Ausbildung, Handel und Amtsgeschäfte.",al={"warum trinken untote","warum brauchen verlassene tavernen","untote gasthaus hintergrundgeschichte"}},{q="Wer wird im Keller gefangen gehalten?",a="In den Kellern unter der Taverne Zur Galgenschlinge halten die Verlassenen einen Scharlachroten Zeloten des feindlichen Scharlachroten Kreuzzugs und einen zwergischen Gebirgsjäger der Allianz gefangen.",al={"taverne gefangene","wer ist im keller","brill taverne kerker"}},{q="Welche Dienste und Lehrer sind hier zu finden?",a="Die Taverne beherbergt Lehrer für Krieger, Priester, Magier, Schurken und Hexenmeister sowie Lehrer für Erste Hilfe und Verzauberkunst, Händler für allgemeine Waren und einen Gastwirt.",al={"taverne zur galgenschlinge lehrer","wer unterrichtet im gasthaus von brill","taverne händler"}}},fx={d83e4303={q="Was ist die Taverne Zur Galgenschlinge?",a="Die Taverne Zur Galgenschlinge dient als soziales Herzstück und lebenswichtiger Zufluchtsort in Brill in Tirisfal. Inmitten der verseuchten Ruinen von Lordaeron gelegen, ist sie die erste voll funktionsfähige Taverne, die von den Verlassenen unterhalten wird. Reisende, Apothekergehilfen und vorbeiziehende Abenteurer versammeln sich unter ihren krummen Holzbalken, um sich auszuruhen, Rat zu suchen, Vorräte zu handeln und von den ansässigen Mentoren in dunklen und kriegerischen Künsten ausgebildet zu werden.",al={"was ist die taverne zur galgenschlinge","erzähle mir von der taverne zur galgenschlinge","taverne zur galgenschlinge"}},ae373cb3={q="Ist die Taverne Zur Galgenschlinge gefährlich?",a="Für loyale Verbündete der Verlassenen und der Horde ist die Taverne ein befestigter Zufluchtsort, der von den Todeswachen von Brill geschützt wird. Doch direkt unter den Dielen lauert Gefahr. Die Keller dienen als Gefängnis für gefangene Feinde – namentlich einen scharlachroten Eiferer, der verhört werden soll, und einen Bergsteiger aus Eisenschmiede –, was alle, die eintreten, daran erinnert, dass der Krieg gegen lebende Eiferer und Eindringlinge direkt vor ihrer Haustür geführt wird.",al={"ist die galgenschlinge gefährlich","gefahr in der taverne zur galgenschlinge","ist die galgenschlinge sicher"}}},fp="19,220,30.322.0,21.306.0,41.128.0,40.223.0,34.148.0,45.165.0"}
P.entries["subzone:gaping-chasm"] = {n="Die Klaffende Schlucht",s="Im Südosten von Tanaris öffnet sich die Klaffende Schlucht zu einem Silithidenschwarm der Hazzali. Seine Tunnel erstrecken sich unter der Wüste und zeigen, wie weit die Brut über die westlichen Sande hinaus vorgedrungen ist.",h="Im Südosten von Tanaris öffnet sich die Klaffende Schlucht zu einem Silithidenschwarm der Hazzali.",kw={"rutenwünschels","die klaffende schlucht","hazzali","schwarm","sandhschrecke","scrimshank","silithiden","tanaris"},ang={["profession:Mining"]="Als Bergarbeiter könnt Ihr in den freiliegenden Spalten und im abgesunkenen Erdreich des Schwarms reiche Mineralvorkommen finden. Um sie zu erreichen, müsst Ihr Dutzende bösartiger, grabender Insekten abwehren.",["race:Gnome"]="Als Gnom solltet Ihr Euch an den Tod des jüngeren Feldmessers Scrimshank in der Schlucht erinnern. Feldforschung in Kalimdor erfordert neben wissenschaftlicher Neugier auch beträchtliche Feuerkraft."},sec={{t="Der Schwarm in den Dünen",b="Die Klaffende Schlucht durchzieht Tanaris, wo sich Tunnel zwischen Harzhügeln winden. Unter der Wüste graben die Hazzali-Silithiden als aggressive Brut ihre Gänge. Stecher, Schwärmer und massige Sandhschrecken jagen jeden, der hinabsteigt, ob Reisender oder Schatzsucher. In den Tunneln können sie in klebrigen Kokons gefangen werden."},{t="Das Grab eines Feldmessers",b="Als der Schwarm wuchs, wuchs auch die Sorge in Gadgetzan. Leitender Feldmesser Rutenwünschels schickte den jüngeren Feldmesser Scrimshank in die Grube, um die durch die Insektentunnel verursachten geologischen Veränderungen zu kartieren und zu vermessen. Die Expedition endete in einer Katastrophe. Scrimshank starb inmitten der zirpenden Brut und hinterließ verstreute Ausrüstung und Messinstrumente als Warnung davor, die Silithiden zu unterschätzen."}},faq={{q="Welche Kreaturen leben in der Klaffenden Schlucht?",a="Die Hazzali-Silithiden leben in der Schlucht. Ihr Schwarm umfasst viele Kasten, darunter Arbeiterdrohnen, geflügelte Stecher, Schwärmer und gewaltige, chitingepanzerte Sandhschrecken.",al={"was lebt in der klaffenden schlucht","insekten in der schlucht von tanaris","gegner in der klaffenden schlucht"}},{q="Wo liegt die Klaffende Schlucht?",a="Die Klaffende Schlucht liegt im Südosten von Tanaris, südlich von Gadgetzan und östlich des Gebirgskamms, der Tanaris von der westlichen Wildnis trennt.",al={"wo ist die klaffende schlucht","lage der klaffenden schlucht","wie findet man die klaffende schlucht"}},{q="Warum wurde ein gnomischer Feldmesser in die Schlucht geschickt?",a="Leitender Feldmesser Rutenwünschels schickte den jüngeren Feldmesser Scrimshank aus Gadgetzan los, um die Höhle zu vermessen und ihre geologische Aktivität zu beurteilen. Die Hazzali-Silithiden überwältigten und töteten Scrimshank, bevor er seine Arbeit abschließen konnte.",al={"wer war scrimshank","rutenwünschels feldmesserquest","warum ging scrimshank dorthin"}},{q="Sind die Silithiden hier mit denen in anderen Teilen Kalimdors verwandt?",a="Ja. Die Hazzali-Silithiden in Tanaris teilen die insektenartige Natur und die Schwarmbewusstseinsstruktur der Bruten im Südlichen Brachland und in Silithus im Westen. Ihre Anwesenheit deutet auf eine gefährliche, koordinierte Ausbreitung über den Süden Kalimdors hin.",al={"sind diese silithiden mit silithus verbunden","warum gibt es insekten in tanaris"}}},fp="12,182,21.296.0,18.367.0,45.164.0,34.146.0,45.211.1,69.231.0"}
P.entries["subzone:garren-s-haunt"] = {n="Garrens Schlupfwinkel",s="Rot Hide-Gnolle durchstreifen die verfallenen Felder von Garrens Schlupfwinkel im nördlichen Tirisfal. Die Familie Garren bewirtschaftete hier das Land, bis die Geißel sie abschlachtete und ihr Heim dem Verfall überließ.",h="Rot Hide-Gnolle durchstreifen die verfallenen Felder von Garrens Schlupfwinkel im nördlichen Tirisfal.",kw={"gehöft","garrens schlupfwinkel","maggot eye","seuche","rot hide","tirisfal"},ang={["race:Undead"]="Der verfallene Hof erinnert an das Gemetzel aus der Zeit vor den Verlassenen. Die Vertreibung der Rot Hide-Gnolle hilft, das nördliche Tirisfal für die Dark Lady zu sichern."},sec={{t="Ein verseuchtes Gehöft",b="Unter dem Königreich Lordaeron ernährte Garrens Schlupfwinkel eine Menschenfamilie. Vor dem Dritten Krieg brachten seine Felder reiche Ernten hervor. Dann fegte die Seuche des Untodes über das Land, und die Geißel kam zum Hof. Garren und seine Verwandten wurden abgeschlachtet. Heute umgeben graue, verdorrte Felder ein Bauernhaus und eine Scheune, die beide unter Tirisfals düsterem Himmel verfallen."},{t="Die Rot Hide-Besetzer",b="Rot Hide-Gnolle haben den Hof unter der Führung des grausamen Maggot Eye besetzt. Vom Untod verdorben, verteidigen sie das erbeutete Gelände erbittert. Sie plündern die Überreste restlos aus und fallen über Reisende oder Patrouillen der Verlassenen her, die das nördliche Tirisfal durchqueren."}},faq={{q="Wer war Garren?",a="Garren war ein menschlicher Bauer, der vor dem Dritten Krieg hier mit seiner Familie lebte. Sie bestellten die Felder, bis die Geißel Lordaeron überrannte und alle auf dem Hof niedermetzelte, während sich die Seuche ausbreitete.",al={"garren hintergrund","wer lebte hier","garrens geschichte"}},{q="Welche Kreaturen besetzen den Hof heute?",a="Rot Hide-Gnolle unter der Führung von Maggot Eye besetzen den Hof. Sie durchstreifen seine Felder und Gebäude und greifen alle an, die ihnen zu nahe kommen.",al={"monster in garrens schlupfwinkel","was lebt hier","wer kontrolliert den hof"}},{q="Warum heißt der Ort Garrens Schlupfwinkel?",a="Der Hof trägt den Namen seines ermordeten Besitzers Garren. „Schlupfwinkel“ beschreibt das trostlose, verlassene Land, das dem Verfall überlassen wurde, nachdem seine Familie unter Tirisfals düsterem Himmel erschlagen worden war.",al={"warum schlupfwinkel genannt","garren namensherkunft"}},{q="Warum haben die Verlassenen den Hof nicht zurückerobert?",a="Die Kräfte der Verlassenen sind durch den Ausbau der Befestigungen von Unterstadt und den Kampf gegen den Scharlachroten Kreuzzug sowie aktive Überreste der Geißel gebunden. Um Plünderer wie die Rot Hide-Gnolle auf abgelegenen Höfen müssen sich weitgehend durchreisende Söldner und Abenteurer kümmern.",al={"warum verlassenen den hof ignorieren","verlassene garrens schlupfwinkel"}}},fx={f7a25cdf={q="Was ist Garrens Schlupfwinkel?",a="Garrens Schlupfwinkel ist ein weitläufiges, verlassenes Gehöft im nördlichen Tirisfal. Vor dem Fall von Lordaeron war es ein produktives Gehöft mit einem großen Bauernhaus, einer Scheune, mehreren Silos und weiten Feldern. Heute, von der Pest des Untodes befallen, sind die Ernten zu grauem Staub verkümmert und der Hof steht als düstere Erinnerung an die landwirtschaftliche Vergangenheit des Königreichs.",al={"was ist garrens schlupfwinkel","garrens schlupfwinkel farm","wo ist garrens schlupfwinkel"}},b3ebc210={q="Was ist in Garrens Schlupfwinkel passiert?",a="Während der Geißelung von Lordaeron fegte die Geißel durch Tirisfal und verwüstete die Landschaft. Garren und seine gesamte Familie wurden brutal ermordet, als die Untoten ihr Gehöft überrannten. Die verpestete Erde erstickte das Leben auf den Feldern, ließ das Land verwüstet zurück und erlaubte aasfressenden Monstern, die leeren Gebäude zu besetzen.",al={"geschichte von garrens schlupfwinkel","was ist hier passiert","wie wurde garrens schlupfwinkel zerstört"}},["0c808513"]={q="Warum ist Garrens Schlupfwinkel ruiniert und verlassen?",a="Das Gehöft wurde verwüstet, als die Pest des Untodes über Lordaeron hinwegfegte, die ansässige Familie tötete und die Gebäude unter einem korrupten Himmel verrotten ließ. Da die menschlichen Besitzer geschlachtet wurden und der umliegende Boden über jedes natürliche Maß hinaus verseucht ist, sind keine lebenden Bauern geblieben, um das Land zu bestellen, sodass die ruinierten Gebäude im Nebel verfallen.",al={"warum ist garrens schlupfwinkel ruiniert","warum wurde garrens schlupfwinkel aufgegeben","wer hat garrens schlupfwinkel ruiniert"}},["41bc539b"]={q="Ist Garrens Schlupfwinkel gefährlich?",a="Ja. Fäulnisnagergnolle und ihr Anführer, Madenauge, besetzen den ruinierten Hof und greifen Reisende an, die sich ihrem Territorium nähern.",al={"ist garrens schlupfwinkel sicher","gefahren bei garrens schlupfwinkel","wie gefährlich ist garrens schlupfwinkel"}}},fp="14,174,20.349.0,22.239.0,15.187.0,35.123.0,32.165.0,38.239.0"}
P.entries["subzone:garrison-armory"] = {n="Garnisonswaffenkammer",s="Bergleute der Allianz arbeiten in der Garnisonswaffenkammer südwestlich der Burg Nethergarde. Ihr Erz versorgt die Festung und bringt Sturmwind Wohlstand.",h="Bergleute der Allianz arbeiten in der Garnisonswaffenkammer südwestlich der Burg Nethergarde.",kw={"verwüstete lande","garnisonswaffenkammer","mine","nethergarde","ingenieur von nethergarde","burg nethergarde","minenarbeiter von nethergarde","sturmwind"},ang={["faction:Alliance"]="Die Belegschaft der Waffenkammer arbeitet unablässig, um die Burg Nethergarde für ihre einsame Wacht mit Waffen, Rüstungen und Handelswaren zu versorgen.",["profession:Mining"]="Wertvolle Mineraladern durchziehen das zerklüftete Gestein unter der Garnisonswaffenkammer und machen ihre Minenschächte zu einer umkämpften Abbaustätte."},sec={{t="Eine Lebensader in der Roten Wüste",b="Die Burg Nethergarde muss weiter über das Dunkle Portal wachen, und lange Versorgungszüge aus Sturmwind können nicht jeden Bedarf decken. In den unterirdischen Minenschächten der Garnisonswaffenkammer arbeiten Bergleute unter der Aufsicht von Vorarbeitern, mit Ingenieuren an ihrer Seite. Das dort geförderte Erz geht an Nethergardes Schmiede und Befestigungsanlagen oder gelangt nach Sturmwind, im Tausch gegen Nahrung, Werkzeuge und andere Versorgungsgüter für die Burg."},{t="Verwundbare Industrie",b="Die Garnisonswaffenkammer liegt außerhalb der Hauptmauern der Burg Nethergarde, den Gefahren der roten Wüste ausgesetzt. Dreadmaul-Oger und wilde Tiere durchstreifen die umliegenden Felsen. Bewaffnete Wachen schützen die Arbeiter in den Tunneln, denn jede Störung des Minenbetriebs gefährdet die Wacht der Burg über das verwüstete Grenzland."}},faq={{q="Wofür wird die Garnisonswaffenkammer genutzt?",a="Arbeiter der Burg Nethergarde bauen in der Garnisonswaffenkammer Metalle und Mineralien ab. Das Erz versorgt die Festung und wird in Sturmwind gegen Nahrung und Ausrüstung eingetauscht.",al={"zweck der garnisonswaffenkammer","was ist diese mine","warum gibt es hier eine mine"}},{q="Wer arbeitet in der Waffenkammer?",a="Bergleute, Ingenieure und Vorarbeiter aus Nethergarde arbeiten in der Waffenkammer. Sie fördern Erz und halten die Schächte unter Nethergardes Befehl instand.",al={"wer ist darin","waffenkammer-npcs","garnisonsminenarbeiter"}},{q="Warum benötigt Burg Nethergarde diese Mine?",a="Die Burg Nethergarde steht einsam in den öden Verwüsteten Landen, wo regelmäßiger Nachschub schwierig ist. Die Mine liefert Metall, um Ausrüstung zu reparieren und Verteidigungsanlagen zu verstärken. Überschüssige Materialien können in Sturmwind gegen lebenswichtige Versorgungsgüter eingetauscht werden.",al={"warum nethergarde sie braucht","bedeutung der waffenkammer","ressourcen von nethergarde"}},{q="Können Spieler der Horde die Garnisonswaffenkammer betreten?",a="Die Garnisonswaffenkammer wird von feindseligen Arbeitern und Wachen der Allianz gehalten. Dennoch wagen sich Abenteurer der Horde in ihre Tiefen, um reichhaltiges Erz aus den Minenschächten zu bergen.",al={"kann die horde hierher gelangen","horde in der garnisonswaffenkammer","ist es sicher für die horde"}}},fp="15,135,28.382.0,19.300.0,37.156.0,24.135.0,41.232.0,44.148.0"}
P.entries["subzone:gates-of-ironforge"] = {n="Tore von Eisenschmiede",s="Von Dun Morogh steigen Reisende zu den Toren von Eisenschmiede hinauf, wo ein steinerner König den Weg in die Zwergenhauptstadt bewacht. Die Tore öffnen sich in der Bergwand, und gleich dahinter steht die Statue von Hochkönig Modimus Ambossar.",h="Von Dun Morogh steigen Reisende zu den Toren von Eisenschmiede hinauf, wo ein steinerner König den Weg in die...",kw={"commons","dun morogh","tore von eisenschmiede","eingang nach eisenschmiede","haupttor von eisenschmiede","modimus ambossar"},ang={["faction:Alliance"]="Ihr betretet die Tore von Eisenschmiede, eine der am stärksten befestigten Festungen der Allianz. Von den eisigen Tälern Dun Moroghs aus lässt sie sich nahezu unmöglich belagern.",["race:Dwarf"]="Erinnert Euch unter dem Abbild von Hochkönig Modimus Ambossar an die uralte Zeit, als alle Zwergenclans als eine einzige Sippe unter einem Berg lebten."},sec={{t="Die Schwelle des Berges",b="Aus dem Herzen von Dun Morogh steigt Ihr über eine gewundene, befestigte Rampe durch das verschneite Tiefland zu den Toren von Eisenschmiede hinauf. Hinter dem großen Portal steht ein steinernes Abbild von Hochkönig Modimus Ambossar. Er vereinte die Zwergenclans vor dem Krieg der drei Hämmer. Der Durchgang mündet ins Commons, wo sich Handel und Bankwesen von Eisenschmiede konzentrieren."}},faq={{q="Wohin führen die Tore von Eisenschmiede?",a="Die Tore von Eisenschmiede führen von Dun Morogh nach Eisenschmiede. Ihr gelangt ins südwestliche Commons, das Zentrum für Handel und Bankwesen der Stadt.",al={"eingang nach eisenschmiede","wohin führen die tore","lage der tore von eisenschmiede"}},{q="Wen stellt die Statue hinter den Toren dar?",a="Die Statue gleich hinter dem Eingang stellt Hochkönig Modimus Ambossar dar. Er herrschte über alle Zwergenclans, bevor politische Zerwürfnisse sie in die Fraktionen Bronzebeard, Wildhammer und Dark Iron spalteten.",al={"statue am tor von eisenschmiede","riesige zwergenstatue","wer ist die statue am tor"}},{q="Wie erreicht Ihr die Tore von Dun Morogh aus?",a="Begebt Euch aus dem Herzen von Dun Morogh nach Norden und steigt die breite, befestigte Steinrampe hinauf, die in den Berghang gehauen ist. Sie führt geradewegs zur äußeren Schwelle der Festung.",al={"wie gelangt man nach eisenschmiede","weg zu den toren von eisenschmiede","rampe von eisenschmiede"}}},fx={d3165cf1={q="Was sind die Tore von Eisenschmiede?",a="Die Tore von Eisenschmiede, auch bekannt als das Haupttor von Eisenschmiede, bilden den monumentalen Eingang, der direkt in die Felswand gehauen wurde und die verschneite Wildnis von Dun Morogh mit der Zwergenhauptstadt im Inneren verbindet. Diese massiven steinernen Portale beherrschen die Landschaft, heißen Reisende willkommen, die von der großen Rampe im Süden kommen, und führen sie direkt an einer imposanten Statue von Hochkönig Modimus Ambossar vorbei in die geschäftigen Commons.",al={"was sind die tore von eisenschmiede","haupttor von eisenschmiede","übersicht tore von eisenschmiede"}},d5c3b229={q="Sind die Tore von Eisenschmiede gefährlich?",a="Nein, die Tore von Eisenschmiede sind für Mitglieder der Allianz und friedliche Besucher völlig sicher. Dieser große Schwellenwert wird wachsam von den standhaften Bergkönigen und den Wachen von Eisenschmiede bewacht und ist stark gegen feindliche Übergriffe befestigt, was eine undurchdringliche Verteidigung des unterirdischen Königreichs gegen die Troggs, Frosttrolle und wilden Tiere darstellt, die durch die Felsen von Dun Morogh streifen.",al={"sind die tore von eisenschmiede sicher","gefahr tor von eisenschmiede","sind die tore sicher"}},["7ab63378"]={q="Warum heißen sie die Tore von Eisenschmiede?",a="Sie sind ganz buchstäblich nach ihrer Funktion benannt: Sie dienen als das große, befestigte Haupttor nach Eisenschmiede, der alten Bergheimat der Bronzebart-Zwerge. Durch diese kolossalen Bögen gelangen Besucher aus den rauen Elementen des zentralen Dun Morogh in die unterirdischen Feuer und Steinhallen des Königreichs selbst.",al={"warum tore von eisenschmiede","bedeutung tore von eisenschmiede","name haupttor von eisenschmiede"}}},fp="18,210,29.344.0,37.139.0,45.192.0,43.157.0"}
P.entries["subzone:gates-of-orgrimmar"] = {n="Gates of Orgrimmar",s="An Orgrimmars Südtor sichern Holz und Eisen den Durchlass im roten Fels des nördlichen Durotar. Dahinter weicht die trockene Einöde dem Tal der Stärke, dem belebten Gemeinschaftsplatz der Hauptstadt. Das Tor verkündet die Ausdauer und die kriegerische Stärke der Horde.",h="An Orgrimmars Südtor sichern Holz und Eisen den Durchlass im roten Fels des nördlichen Durotar.",kw={"durotar","gates of orgrimmar","haupttor","orgrimmar grunts","thrall","tal der stärke"},ang={["faction:Alliance"]="Als Späher oder Eindringling der Allianz steht Ihr vor einem der am stärksten bewachten Engpässe Kalimdors, der durch einen Frontalangriff kaum zu durchbrechen ist.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr die Tore als einen Ort der Sicherheit und Zugehörigkeit sehen, eine hart erkämpfte Heimat, geschaffen unter Kriegshäuptling Thralls Führung."},sec={{t="Die Bastion von Durotar",b="Orgrimmars Haupttor bewacht die gewaltige Schlucht, die in die Berge rings um die Stadt gehauen wurde. Über dem Eingang ragen Holzpalisaden auf, verstärkt durch Eisenspitzen und Wachtürme. Reisende aus Klingenhügel und dem Buschland von Durotar erwartet ein prächtiger Empfang – und eine Warnung an jeden, der die New Horde bedroht. Bewaffnete Orgrimmar Grunts patrouillieren auf dem Zugangsweg und beobachten alle, die eintreten."},{t="Schwelle zum Tal",b="Hinter dem schattigen Torbogen betretet Ihr das Tal der Stärke, Orgrimmars ziviles und militärisches Herz. Der Tunnel verengt den Weg für Gesandte, Händler und Krieger, während Wachposten die Vorbeiziehenden beobachten. Hier nimmt der Traum von Kriegshäuptling Thrall Gestalt an: ein sicherer Zufluchtsort, der der rauen Wüste abgerungen wurde, wo die vielen Völker der Horde ohne Furcht gemeinsam wandeln können."}},faq={{q="Wohin führen die Gates of Orgrimmar?",a="Die Gates of Orgrimmar führen aus dem nördlichen Durotar ins Tal der Stärke, den Haupteingang und zentralen Gemeinschaftsplatz der Stadt.",al={"was verbinden die tore","wo ist das vordere tor"}},{q="Wer bewacht die Tore?",a="Orgrimmar Grunts bewachen die vorderen Tore und halten nach feindlichen Eindringlingen und wilden Tieren Ausschau.",al={"wer schützt das tor","torwachen"}},{q="Warum ist der Eingang mit Holz und Spitzen befestigt?",a="Holzpalisaden und Eisenspitzen folgen dem Vorbild orkischer Grenzbefestigungen. Robustes Holz aus den umliegenden Landen schafft zwischen den Schluchtwänden einen schwer zu überwindenden Engpass.",al={"warum holz und eisenspitzen","orkische torgestaltung"}},{q="Können Spieler der Allianz dieses Tor passieren?",a="Mitglieder der Allianz, die das Haupttor passieren wollen, treffen auf feindselige, kampferprobte Wachen, die Feinde der Horde sofort bei Sichtkontakt niederschlagen.",al={"kann die allianz eintreten","allianz durch das tor"}}},fx={a102033b={q="Was sind die Tore von Orgrimmar?",a="Die Tore von Orgrimmar dienen als stark befestigter Haupteingang zur Hauptstadt der Horde. Dieser imposante Schwellenwert aus Holz und Eisen, der direkt durch die rauen, purpurroten Canyonwände des nördlichen Durotar geschlagen wurde, markiert die Grenze zwischen der wilden Weite des Brachlands und dem geschäftigen Herzen vom Tal der Stärke.",al={"gates of orgrimmar","was sind die tore von orgrimmar","orgrimmar tor"}},ecbfa379={q="Warum ist dieser Eingang gefährlich?",a="Für loyale Champions der Horde stellt das Tor Sicherheit und Stärke dar. Für Mitglieder der Allianz ist die Annäherung an die Schwelle jedoch ein Todesurteil. Standhafte Orgrimmar-Grunzer patrouillieren durch die Türme und den Durchgang, bereit, gnadenlos jeden Eindringling niederzuschlagen, der es wagt, sich ungebeten zu nähern.",al={"sind die tore von orgrimmar gefährlich","sind die tore gefährlich","gefahr tore"}},["86fa8d49"]={q="Warum heißen sie die Tore von Orgrimmar?",a="Das Tor hat seinen Namen von der Stadt, die es schützt, welche Thrall gründete und zu Ehren des ehemaligen Kriegshäuptlings Orgrim Schicksalshammer benannte. Als wichtigstes Portal in und aus der Festungsstadt steht es als Denkmal für orkische Souveränität und das bleibende Vermächtnis von Schicksalshammer.",al={"warum tore von orgrimmar","bedeutung tore von orgrimmar"}}},fp="18,255,22.362.0,23.356.0,37.124.0,21.90.0,51.149.0,44.128.0"}
P.entries["subzone:gelkis-village"] = {n="Dorf der Gelkis",s="Im Südwesten von Desolace hält der erdverbundene Zentaurenstamm der Gelkis sein Dorf und bewacht die südliche Route. Ihre Schlucht überblickt die Nord-Süd-Straße und macht die Durchreise für Reisende ohne die Gunst des Stamms gefährlich.",h="Im Südwesten von Desolace hält der erdverbundene Zentaurenstamm der Gelkis sein Dorf und bewacht die südliche...",kw={"bolgans loch","zentaur","desolace","feralas","gelkis","khan shaka","magram","schattenflucht"},ang={["faction:Horde"]="Als Mitglied der Horde steht Ihr den befestigten Stellungen der Gelkis nahe Schattenflucht gegenüber, einer Siedlung der Dunkelspeer an der Küste unmittelbar im Westen. Die Gelkis bleiben eine Bedrohung für die Unternehmungen der Horde in der Nähe.",["race:Tauren"]="Als Tauren wisst Ihr, dass die Zentauren Euer Volk seit Generationen aus seinen angestammten Ländern vertreiben. Die Befestigungen der Gelkis erinnern bitter daran, dass sie Kalimdor weiterhin bedrohen."},sec={{t="Eine Festung in der Schlucht",b="Das Dorf der Gelkis erstreckt sich durch eine tiefe Schlucht zwischen steilen Klippen und Seilbrücken. Die Gelkis haben ihre angestammten Ländereien zu einer dauerhaften Festung gemacht, deren Außenposten bis an die Grenze von Feralas reichen. Khan Shaka führt die Krieger von Bolgans Loch aus, einer Höhle in der südlichen Felswand.\n\nReisende, die durch Desolace nach Süden ziehen, müssen sich durch die Schlucht kämpfen oder vorsichtig vorgehen. Die Gelkis betrachten ungebetene Wanderer als Freiwild in ihrem endlosen Krieg mit rivalisierenden Zentaurenstämmen."}},faq={{q="Wer lebt im Dorf der Gelkis?",a="Im Dorf lebt der Stamm der Gelkis, einer der verfeindeten Zentaurenstämme von Desolace. Sie verehren die Erde und folgen Khan Shaka, der in Bolgans Loch wohnt, einer Höhle in der Felswand.",al={"bewohner der gelkis","wer beherrscht das dorf der gelkis","zentaurendorf im süden"}},{q="Warum sind die Zentauren der Gelkis Fremden gegenüber feindselig?",a="Die Gelkis verteidigen ihr Revier und begegnen Fremden feindselig, doch am meisten hassen sie den rivalisierenden Stamm der Magram. Wer Krieger der Magram jagt, kann ihr Vertrauen gewinnen und sicheres Geleit ins Dorf erhalten.",al={"warum greifen die gelkis an","gelkis feindselig","freundschaft mit den gelkis möglich"}},{q="Wo liegt das Dorf der Gelkis?",a="Das Dorf der Gelkis liegt im Südwesten von Desolace, unmittelbar östlich und etwas südlich von Schattenflucht, einer Trollsiedlung. Seine Schluchten grenzen an die südliche Bergflanke und überblicken den Pfad, der nach Süden nach Feralas führt.",al={"gelkis lage","dorf der gelkis finden","wo sind die gelkis"}},{q="Was ist Bolgans Loch?",a="Bolgans Loch ist eine große Höhle in der südlichen Felswand der Schlucht, die über hoch gelegene Brücken und Felsvorsprünge mit dem Dorf verbunden ist. Sie ist das innerste Heiligtum und der Machtsitz des Khans der Gelkis.",al={"bolgans loch","höhle im dorf der gelkis","wo ist der khan der gelkis"}}},fp="14,223,24.462.0,28.180.0,48.183.0,32.214.0,22.184.0"}
P.entries["subzone:ghost-walker-post"] = {n="Geistwandlerposten",s="Im Herzen von Desolace behauptet sich der Geistwandlerposten neben dem Kodofriedhof. Tauren und Orcs verteidigen den Außenposten der Horde gegen Zentaurenclans und die Burning Blade, während seine Schamanen sterbende Kodos und deren Geister betreuen.",h="Im Herzen von Desolace behauptet sich der Geistwandlerposten neben dem Kodofriedhof.",kw={"burning blade","zentauren","desolace","geistwandlerposten","gurda wildmane","horde","der kodofriedhof","schattenflucht","tauren","thrall"},ang={["class:Shaman"]="Unter Gurda Wildmane sprechen die Schamanen hier mit uralten Geistern und erleichtern sterbenden Tieren den Übergang in die Geisterwelt.",["race:Tauren"]="Als Tauren erkennt Ihr in der Wacht Eures Volkes neben den uralten Ruhestätten der Kodos seine heilige Pflicht gegenüber der Natur."},sec={{t="Wacht über das Ödland",b="Der Geistwandlerposten bietet der Horde einen Stützpunkt auf den staubigen Ebenen im Herzen von Desolace. Marodierende Zentauren und Kultisten der Burning Blade streifen in der Nähe umher und bedrohen den Posten ständig. Seine Einrichtungen bieten nur das Nötigste. Es gibt weder ein Gasthaus noch einen Flugmeister. Taurenwachen und ein von Kriegshäuptling Thrall entsandtes Kontingent von Orcs halten Wache über das Ödland."},{t="Hüter des Friedhofs",b="Gurda Wildmane, eine Taurenschamanin, führt den Geistwandlerposten neben dem Kodofriedhof. Schamanen betreuen die sterbenden Kodos, die zum Verenden hierherkommen. Sie erleichtern den Tieren den Übergang ins nächste Leben und halten Zwiesprache mit ihren verweilenden Geistern.\n\nDie Verteidiger des Postens bleiben gegen Bedrohungen gewappnet. Hier ehren die Tauren ihr uraltes Band mit den mächtigen Kodos."}},faq={{q="Was ist der Geistwandlerposten?",a="Der Geistwandlerposten ist ein kleiner, karger Außenposten der Horde im Herzen von Desolace, den hauptsächlich Tauren mit Unterstützung einer Orcgarnison halten.",al={"geistwandlerposten infos","was ist dieses lager","hordenlager desolace"}},{q="Wer führt den Geistwandlerposten?",a="Gurda Wildmane, eine Taurenschamanin, führt den Geistwandlerposten und kümmert sich um seine Verteidigung und den benachbarten Kodofriedhof.",al={"wer hat das kommando","geistwandlerposten anführerin","gurda wildmane"}},{q="Warum liegt der Posten nahe dem Kodofriedhof?",a="Gurda Wildmane und andere Taurenschamanen leben am Posten, um sterbenden Kodos den Übergang ins nächste Leben zu erleichtern und mit den Geistern verstorbener Tiere Zwiesprache zu halten.",al={"warum am kodofriedhof","kodogeister lager","schamane kodofriedhof"}},{q="Welche Feinde bekämpft der Geistwandlerposten?",a="Die Garnison bekämpft feindselige Zentaurenclans und Streitkräfte der Burning Blade, die in ganz Desolace operieren.",al={"geistwandlerposten feinde","wer greift den geistwandlerposten an","posten bedrohungen"}},{q="Kann ich hier einen Flugpunkt freischalten oder in einem Gasthaus rasten?",a="Nein. Der Geistwandlerposten hat weder ein Gasthaus noch einen Flugmeister. Reisende müssen andernorts nach einer Transportmöglichkeit suchen, etwa in Schattenflucht.",al={"flugmeister geistwandlerposten","gastwirt geistwandlerposten","flugpunkt hier?"}},{q="Wie unterscheidet er sich von Schattenflucht?",a="Schattenflucht ist eine geschützte Trollenklave an der Westküste von Desolace. Der Geistwandlerposten liegt im Landesinneren, ist nahen Bedrohungen ausgesetzt und widmet sich der Grenzverteidigung und spirituellen Pflichten.",al={"schattenflucht im vergleich zum geistwandlerposten","anderes hordenlager desolace"}}},fp="17,219,21.341.0,26.336.0,26.131.0,28.115.0,48.143.0,42.93.0,47.130.0,42.190.0"}
P.entries["subzone:gnomeregan"] = {n="Gnomeregan",s="Troggs und Lepragnome streifen zwischen zerstörten Verteidigungsanlagen durch Gnomeregans vergiftete Hallen. Die Stadt war einst die unterirdische Hauptstadt der Gnome, bis eine verzweifelte Verteidigung in einer Katastrophe endete.",h="Troggs und Lepragnome streifen zwischen zerstörten Verteidigungsanlagen durch Gnomeregans vergiftete Hallen.",kw={"dun morogh","gnomeregan","lepragnom","mekkadrill","thermaplugg","tinkers court","trogg"},ang={["profession:Engineering"]="Obwohl radioaktives Gift Gnomeregan erstickt, birgt die Stadt die größte Ansammlung von Bauplänen, fortschrittlichen Ersatzteilen und funktionierenden Industriemaschinen in den Östlichen Königreichen.",["race:Gnome"]="Für die Gnome bleibt der Verlust Gnomeregans eine tiefe Wunde. Seine verstrahlten Hallen zu betreten, ist eine ernste Pilgerfahrt, um Thermaplugg zu vernichten und verlorene mechanische Erbstücke zurückzuholen."},sec={{t="Ein Wunder der Ingenieurskunst",b="Gnomeregans Hallen waren einst vom Schaffen gnomischer Ingenieure erfüllt. Zwerge aus Eisenschmiede halfen vor Jahrhunderten beim Bau der Stadt und schlugen sie in die verschneiten Felsen des westlichen Dun Morogh. Dampfgetriebene Zahnräder, Kupferrohre und gewaltige Montagehallen machten sie zum Herzen gnomischer Industrie und Erfindungskunst. Im Zweiten Krieg versorgte sie die Allianz mit Bauplänen, Flugmaschinen und komplexen Waffen. Selbst Orgrim Schicksalshammers Horde konnte die Stadt während ihrer Belagerung nicht bezwingen."},{t="Der Fall und die vergifteten Hallen",b="Während des Dritten Krieges strömten Troggs aus den Tiefen der Erde herauf und brachen in Gnomeregans unterste Kammern ein. Hochtüftler Gelbin Mekkadrill beschloss, der Invasion allein entgegenzutreten, da er keine Armeen der Allianz vom Gemetzel in Lordaeron abziehen wollte.\n\nAuf Anraten des Chefingenieurs Robogenieur Thermaplugg befahl er, radioaktives Gas in den unteren Kammern freizusetzen, um die Troggs auszulöschen. Stattdessen stärkte das Gas viele Troggs und tötete fast achtzig Prozent des Gnomenvolkes. Überlebende, die ihm ausgesetzt waren, wurden zu entstellten Lepragnomen, und Thermaplugg übernahm die Herrschaft über die vergifteten Ruinen."}},faq={{q="Warum ist Gnomeregan voller Strahlung?",a="Als Troggs die Stadt überrannten, ließ Hochtüftler Mekkadrill auf Anraten von Robogenieur Thermaplugg radioaktives Gas in Gnomeregans untere Lüftungsschächte strömen. Das Gas sollte die Troggs töten, doch es brachte Tausende Gnome um, verwandelte Überlebende in Lepragnome und hinterließ eine dauerhaft verstrahlte Stadt.",al={"warum ist es radioaktiv","gnomeregan giftgas","was hat gnomeregan vergiftet"}},{q="Wo sind all die überlebenden Gnome jetzt?",a="Überlebende Gnome flohen nach Eisenschmiede, wo König Magni Bronzebart ihnen im Tinkers’ Court Zuflucht gewährte. Hochtüftler Gelbin Mekkadrill arbeitet dort daran, seinem verstreuten Volk zu helfen und dessen Heimkehr zu planen.",al={"wo leben gnome","gnomenflüchtlinge","wo ist mekkadrill"}},{q="Wer herrscht jetzt über Gnomeregan?",a="Robogenieur Thermaplugg herrscht über Gnomeregan und hat sich zu dessen König erklärt. Einst Mekkadrills oberster Berater, befehligt er aus dem tiefsten Inneren der Stadt abtrünnige Verteidigungsautomaten, verstrahlte Lepragnome und mutierte Troggs.",al={"wer ist der boss von gnomeregan","gnomeregan anführer","thermaplugg"}},{q="Warum half die Allianz während der Invasion nicht, Gnomeregan zu retten?",a="Mekkadrill beschloss, die Allianz nicht um Hilfe zu bitten. Während die Geißel im Dritten Krieg die Menschheit verheerte, hielten die Gnome ihren unterirdischen Kampf geheim, um keine dringend benötigten Verteidiger aus Lordaeron abzuziehen.",al={"warum hilft die allianz nicht","warum halfen die menschen den gnomen nicht","gnome im dritten krieg"}}},fx={["927c35f4"]={q="Was ist Gnomeregan?",a="Gnomeregan ist die unterirdische Hauptstadt der Gnome, erbaut unter den verschneiten Gipfeln von Dun Morogh. Als Wunderwerk aus schmiedeeiserner Technik, Uhrwerkmechanik und dampfbetriebener Technologie stand sie Generationen lang als pulsierendes Herz der gnomischen Kultur, des Einfallsreichtums und der politischen Macht an der Seite ihrer Zwergenverbündeten.",al={"was ist gnomeregan","stadt gnomeregan","gnomenhauptstadt"}},["702e95d4"]={q="Ist Gnomeregan gefährlich?",a="Extrem gefährlich. Die unteren Tiefen sind von anhaltender, tödlicher Strahlung durchflutet, die in der Lage ist, Körper und Geist zu verformen. Die Hallen wimmeln von wilden Troggs, wahnsinnigen Leprognomen, defekten Kampfautomaten und den tödlichen Fallen des selbsternannten Königs Thermaplugg. Das Betreten ohne angemessene Vorbereitung oder eine starke Gruppe lädt zu einem schrecklichen Tod ein.",al={"ist gnomeregan gefährlich","gefahren von gnomeregan","wie gefährlich ist gnomeregan"}}},fp="10,186,23.459.0,31.587.0,36.309.0,39.205.0,28.229.0,65.209.0"}
P.entries["subzone:go-shek-farm"] = {n="Go'Sheks Hof",s="Go'Sheks Hof stellt Nahrung und Vieh für Hammerfall im Arathihochland bereit. Dort arbeiten auch Apotheker der Verlassenen im Geheimen.",h="Go'Sheks Hof stellt Nahrung und Vieh für Hammerfall im Arathihochland bereit.",kw={"apotheker jorell","arathi","go'sheks hof","goshek","hammerfall","kinelory","quae","swee","witherbark"},ang={["faction:Alliance"]="Der Hof versorgt Hammerfall und beherbergt Apotheker der Verlassenen, deren geheime Arbeit die Aufmerksamkeit der Allianz erregt hat.",["faction:Horde"]="Die Sicherung von Go'Sheks Hof hilft, Hammerfall zu versorgen und dessen Umland gegen die vordringenden Witherbark-Trolle zu verteidigen."},sec={{t="Ein Außenposten der Horde im Osten",b="Go'Sheks Hof liegt südlich von Hammerfall, unmittelbar nördlich des Gebiets der feindseligen Witherbark-Trolle. Die Horde hält den Hof, und Hammerfall-Grunzer patrouillieren über seine Felder und durch seine Ställe. Nahrung und Vieh vom Hof helfen der orcischen Siedlung, ihre Stellung im Arathihochland zu halten."},{t="Die Werkstatt des Apothekers",b="Die Königliche Apothekervereinigung unterhält auf Go'Sheks Hof eine unauffällige Präsenz, angeführt von Gestalten wie Apotheker Jorell. Kuriere transportieren Notizen, Reagenzien und Forschungsergebnisse zwischen dem Hof und Tarrens Mühle, wobei frühe Formen der neuen Seuche der Verlassenen untersucht werden. Späher der Allianz versuchen, die Boten abzufangen und herauszufinden, welches Gift im Boden von Arathi zubereitet wird."}},faq={{q="Warum hält die Horde Go'Sheks Hof besetzt?",a="Go'Sheks Hof versorgt das nahe Hammerfall mit Nahrung und Vieh. Außerdem bietet er den Verlassenen einen bewachten Ort für sensible chemische und alchemistische Forschungen.",al={"wem gehört go'sheks hof","warum sind orcs auf go'sheks hof","go'sheks hof horde"}},{q="Wem gehörte dieser Hof früher?",a="Über die früheren Besitzer des Hofes gibt es keine Aufzeichnungen. Heute bewirtschaften und bewachen ihn Orcs aus dem nahen Hammerfall für die Horde.",al={"go'sheks hof geschichte","menschenhof arathi","primwell skye"}},{q="Welche Experimente finden hier statt?",a="Apotheker der Verlassenen betreiben auf dem Hof geheime alchemistische Arbeiten. Agenten der Allianz untersuchen dort den Kurierverkehr und die Aufzeichnungen, um die Art dieser Arbeiten zu ergründen.",al={"apotheker jorell","seuchenexperimente arathi","verlassenenforschung go'shek"}},{q="Warum beobachten Agenten der Allianz den Hof?",a="Quae und Kinelory untersuchen verdächtigen Verkehr zwischen Go'Sheks Hof und Tarrens Mühle. Sie suchen nach Beweisen für die Aktivitäten der Verlassenen und brauchen Hilfe, um an diese zu gelangen.",al={"quae kinelory","allianzaufklärung go'shek","hinweise auf eine neue seuche"}}},fp="12,128,27.260.0,25.349.1,40.153.0,26.111.0,44.151.0,48.161.0"}
P.entries["subzone:goblin-foundry"] = {n="Goblin Foundry",s="In den Todesminen halten Goblins die Goblin Foundry für die Bruderschaft der Defias in Betrieb. Gilnid beaufsichtigt die Handwerker und Ingenieure rund um ihren großen Schmelztiegel.",h="In den Todesminen halten Goblins die Goblin Foundry für die Bruderschaft der Defias in Betrieb.",kw={"kessel","die todesminen","defias","goblin foundry","vancleef"},ang={["faction:Alliance"]="Unter Westfall zeigt die Werkstatt der Defias das Ausmaß der industriellen Ressourcen der Bruderschaft.",["profession:Engineering"]="Die Gießerei zeigt das Geschick der Goblins in Metallverarbeitung und Mechanik. Ihre Ingenieure setzen ferngesteuerte Golems ein, um die Werkstatt zu verteidigen."},sec={{t="Industrielle Ambitionen",b="Tief unter Mondbruch arbeiten Goblin-Handwerker und -Ingenieure für die Bruderschaft der Defias. Schmelzöfen und Eisenrampen füllen die Kammer. Dort stellen sie Anker und Kanonenkugeln her."},{t="Gilnids Werkstatt",b="Gilnid, der Schmelzer, beaufsichtigt die Goblin-Belegschaft. Handwerker halten die Produktion am Laufen, während Ingenieure ferngesteuerte Golems zur Verteidigung der Werkstatt einsetzen. Enge Rampen und geschmolzenes Metall machen die Kammer für Eindringlinge gefährlich."}},faq={{q="Was wurde in der Goblin Foundry hergestellt?",a="Goblin-Handwerker fertigen schwere Metallwaren für die Bruderschaft der Defias, darunter Anker und Kanonenkugeln.",al={"was wird hier hergestellt","zweck der gießerei","fabrik in den todesminen"}},{q="Warum gibt es Golems in der Gießerei?",a="Goblin-Ingenieure setzen ferngesteuerte Golems ein, um ihre Werkstatt gegen Eindringlinge zu verteidigen.",al={"warum sind hier golems","roboter der gießerei","mechanische gegner in den todesminen"}},{q="Wo sind die Goblins, die diese Werkstatt betrieben haben?",a="Goblin-Handwerker und -Ingenieure arbeiten noch immer unter Gilnid, dem Schmelzer, in der Gießerei.",al={"wo sind die goblins","ingenieure der gießerei","gilnids arbeiter"}},{q="Was ist das große Gebilde in der Mitte des Raumes?",a="Ein gewaltiger industrieller Schmelztiegel beherrscht die Mitte des Raumes. Er schmilzt Erz aus den Minen ein, um daraus Panzerplatten und mechanische Fahrgestelle zu schmieden.",al={"topf in der mitte der gießerei","schmelzbottich","kessel in den todesminen"}}},fx={["60ac21cc"]={q="Welche Arbeit wird in der Goblin Foundry verrichtet?",a="Die Gießerei ist nach wie vor in Betrieb. Goblinhandwerker und Ingenieure arbeiten dort unter Gilnid und produzieren Metallwaren für The Defias Brotherhood.",al={"welche arbeit wird in der goblin foundry verrichtet","was stellen goblins in der foundry her","produktion in der goblin foundry"}},["22e4861d"]={q="Ist die Goblin Foundry gefährlich?",a="Die Gießerei ist gefährlich für Eindringlinge. Goblinhandwerker, Ingenieure und ihre ferngesteuerten Golems verteidigen schmale Rampen rund um einen massiven Schmelzkessel.",al={"ist die goblin foundry gefährlich","gefahren der foundry","bedrohung durch goblin foundry"}},["11526e87"]={q="Warum wird sie Goblin Foundry genannt?",a="Die Kammer ist nach den Goblin-Tüftlern und Metallurgen benannt, die von The Defias Brotherhood angeheuert wurden, um sie zu betreiben. Sie wurde speziell für Goblin-Ingenieurskunst und Verhüttung konzipiert, komplett mit aufwendigen Rampen, Sprengkesseln und Werkbänken, die auf ihre explosiven industriellen Ambitionen ausgelegt sind.",al={"warum heißt sie goblin foundry","ursprung des namens goblin foundry","wer hat die goblin foundry benannt"}},a84744f8={q="Was ist die Goblin Foundry?",a="Die Goblin Foundry ist eine höhlenartige Industriewerkstatt, die tief im unterirdischen Komplex der Todesminen liegt. Die Anlage wurde von Söldner-Goblin-Ingenieuren erbaut und betrieben, die von der Defias-Bruderschaft unter Vertrag genommen wurden, und beherbergt massive Schmelzanlagen, Laufstege und Werkstätten, die dazu bestimmt sind, Metallarbeiten, Werkzeuge und mechanisierte Kriegsinstrumente für Edwin van Cleefs verborgene Rebellion zu schmieden.",al={"was ist die goblin foundry","goblin foundry lore","was ist diese gießerei"}},bbcfa33c={q="Was ist in der Goblin Foundry passiert?",a="Goblin-Handwerker und Ingenieure errichteten die Gießerei als aktive Defias-Werkstatt. Gilnid leitet ihre Metallarbeiten, während Ingenieure ferngesteuerte Golems einsetzen, um sie zu verteidigen.",al={"was ist hier passiert","geschichte der gießerei","geschichte der goblin foundry"}}},fp="14,165,20.172.0,17.226.0,43.100.0,36.86.0,44.83.0,54.153.0"}
P.entries["subzone:gol-bolar-quarry"] = {n="Steinbruch Gol'Bolar",s="Im Steinbruch Gol'Bolar haben Troggs die Bergleute aus den verschneiten Hügeln im Südosten von Dun Morogh vertrieben. Die Zwerge aus Eisenschmiede kamen wegen Stein und Erz, doch nun liegt die Ausgrabung still.",h="Im Steinbruch Gol'Bolar haben Troggs die Bergleute aus den verschneiten Hügeln im Südosten von Dun Morogh...",kw={"dun morogh","gol'bolar","mine","prospector gehn","steinbruch","trogg"},ang={["profession:Mining"]="Freiliegende Felsstufen und nahe Tunnel bergen reiche Mineraladern. Verschanzte Troggs stehen zwischen Euch und dem Erz.",["race:Dwarf"]="Als Zwerg schützt Ihr mit der Räumung des Steinbruchs Gol'Bolar Eisenschmiedes Bodenschätze in den Bergen und wahrt den Stolz Eures Clans. Die Zwerge können es sich nicht leisten, diese Schätze den Troggs zu überlassen."},sec={{t="Ein Steinbruch unter Belagerung",b="Zwerge aus Eisenschmiede eröffneten den Steinbruch Gol'Bolar südöstlich von Kharanos, um Stein und Bodenschätze aus den Bergen zu gewinnen. Ihre Grabungen durchbrachen unterirdische Höhlengänge und brachten eine Horde feindseliger Troggs ans Tageslicht. Die Kreaturen vertrieben bald die Bergleute.\n\nDas obere Lager ist nun ein umkämpfter Aufmarschplatz. Aufseher, Händler und Prospector Gehn versammeln dort zwergische und gnomische Rekruten, um die Troggs zurückzudrängen und die Grube zurückzuerobern."}},faq={{q="Was ist der Steinbruch Gol'Bolar?",a="Der Steinbruch Gol'Bolar ist ein Tagebau im Südosten von Dun Morogh. Zwerge aus Eisenschmiede unterhalten ihn als Ausgrabungsstätte und kleinen Außenposten mit Vorräten und Arbeit für Abenteurer aus der Gegend.",al={"gol bolar","was ist das für ein ort","steinbruch infos"}},{q="Warum gibt es hier so viele Troggs?",a="Zwergische Bergleute gruben zu tief und brachen in Tunnel durch, die von Troggs bewohnt waren. Die Kreaturen strömten in die offenen Gruben und nahen Minenschächte und drängten die Bergleute zum oberen Rand des Steinbruchs zurück.",al={"warum sind hier troggs","troggbefall","wer hat den steinbruch angegriffen"}},{q="Wer ist Prospector Gehn?",a="Prospector Gehn ist ein zwergischer Aufseher im Lager des Steinbruchs. Er leitet die Bemühungen zur Sicherung der Ausgrabungsstätte und bietet Kopfgelder und Aufgaben für Abenteurer, die bereit sind, die Troggs zu dezimieren.",al={"wer ist gehn","prospector gehn"}}},fx={e8696793={q="Was ist im Steinbruch Gol'Bolar geschehen?",a="Steinbruch Gol'Bolar begann als eine aktive Ausgrabungsstätte und ein Bergbaulager der Zwerge im südöstlichen Dun Morogh, das dem Abbau von Stein und der Förderung wertvoller Mineralien gewidmet war. Der reguläre Betrieb kam jedoch zu einem plötzlichen Stillstand, als unterirdische Troggs in die unteren Ausgrabungen und die nahe gelegene Mine durchbrachen. Die bösartigen Kreaturen überwältigten die Bergleute schnell und zwangen die Zwerge zum Rückzug, um ein befestigtes Lager auf den oberen Kämmen des Steinbruchs zu errichten und Hilfe bei der Rückeroberung zu suchen.",al={"geschichte von steinbruch gol'bolar","was ist in gol'bolar geschehen","hintergrund von gol'bolar"}},["3a8dc0a0"]={q="Wer lebt oder arbeitet im Steinbruch Gol'Bolar?",a="Eine widerstandsfähige Gruppe von zwergischen Bergleuten, Aufsehern und Hilfspersonal hält das Lager mit Blick auf die Grube. Der Außenposten, der von Prospektor Gehn und anderen Ausgräbern beaufsichtigt wird, umfasst Waffenhändler, Proviantmeister und Berufsausbilder, die junge Bergsteiger und Entdecker bei ihrem Kampf gegen die Trogg-Bedrohung unterstützen.",al={"wer betreibt den steinbruch gol'bolar","lager im steinbruch gol'bolar","wer lebt in gol'bolar"}},becb3bb6={q="Ist der Steinbruch Gol'Bolar gefährlich?",a="Ja. Während der obere Rand und das kleine Lager von den einheimischen Zwergen geschützt werden, wimmelt es in der offenen Grube und der darunter liegenden Gol'Bolarmine von feindseligen Troggs. Jeder Reisende, der unvorsichtig in die Ausgrabungsstätte hinabsteigt, riskiert, von aggressiven Tunnelgräbern umschwärmt zu werden, die die Stätte als ihr Eigen beanspruchen.",al={"ist gol'bolar gefährlich","gefahr im steinbruch gol'bolar","bedrohungen in gol'bolar"}}},fp="16,173,20.438.0,25.170.0,34.189.0,23.175.0"}
P.entries["subzone:gol-bolar-quarry-mine"] = {n="Gol'Bolarmine",s="Troggs halten die Gol'Bolarmine unter dem Steinbruch im östlichen Dun Morogh besetzt. Zwerge aus Eisenschmiede bauten in ihren Stollen Stein und reiche Erzvorkommen ab, bis ihre Spitzhacken in Trogg-Höhlen durchbrachen. Jetzt führt Hammerbuckel die Kriegsbande in den tiefsten Schächten an.",h="Troggs halten die Gol'Bolarmine unter dem Steinbruch im östlichen Dun Morogh besetzt.",kw={"dun morogh","gol'bolar","gol'bolarmine","hammerspine","mine","steinbruch","troggs"},ang={["profession:Mining"]="Feindselige Troggs versperren noch immer die Mine. Ihre tiefsten Stollen müssen geräumt werden, bevor die Bergleute zurückkehren können.",["race:Dwarf"]="Jeder Hieb einer Spitzhacke in den Berg birgt die Gefahr, das zu wecken, was darunter liegt. Die Rückeroberung von Gol'Bolar Mine würde ihren Wert und den Stolz der Zwerge wiederherstellen."},sec={{t="Ein Durchbruch in der Tiefe",b="Die Spitzhacken der Zwerge durchbrachen eine Wand zu Höhlen, in denen Troggs hausten. Damit endete ihr Bergbau. Troggs strömten aus der Dunkelheit, überwältigten die Arbeitsmannschaften und vertrieben sie aus der Mine. Die verlassenen Schächte bleiben in der Hand der Troggs."},{t="Hammerspines Unterschlupf",b="Jüngere Troggs durchstreifen die sonnenbeschienenen Terrassen des Steinbruchs, doch die Mine beherbergt die wildesten Kämpfer der Kriegsbande. Tief in ihren engen Stollen lauert Hammerspine, ihr grausamer Häuptling. Die örtlichen Gebirgsjäger müssen den wertvollen Steinbruch noch immer zurückerobern. Dafür müssen sie die tiefsten Schächte der Mine erreichen und den Zustrom der Troggs an der Quelle unterbinden."}},faq={{q="Warum ist die Mine voller Troggs?",a="Zwergische Bergleute brachen beim Graben in eine verborgene Höhle durch. Troggs strömten durch den Durchbruch, schlachteten einige Bergleute ab und vertrieben die übrigen, bevor sie die Schächte in Besitz nahmen.",al={"warum sind troggs in gol bolar","wie kamen die troggs hierher","wer hat die mine übernommen"}},{q="Wer führt die Troggs in der Gol'Bolarmine an?",a="Hammerspine führt die Troggs in der Gol'Bolarmine an. Der hünenhafte Rohling befehligt tief in den Schächten die stärksten Kämpfer der Kriegsbande.",al={"boss der mine","trogganführer gol bolar","wer ist hammerspine"}},{q="Unterscheidet sich die Mine vom Rest des Steinbruchs?",a="Ja. Schwächere Troggs durchstreifen die äußere Steinbruchgrube, während sich in den tiefen, engen Stollen die härtesten Kämpfer und ihr Häuptling aufhalten.",al={"steinbruch und mine unterschied","sind die troggs in der mine stärker"}},{q="Können Bergleute hier noch arbeiten?",a="Nein. Der Bergbau ist zum Erliegen gekommen. Zwergische Gebirgsjäger und Abenteurer kämpfen nun darum, die Troggs zu vertreiben, statt Stein abzubauen.",al={"ist die mine in betrieb","betreiben die zwerge noch bergbau"}}},fx={["58d8a204"]={q="Was ist in der Gol'Bolarmine geschehen?",a="Die Mine wurde aktiv von zwergischen Prospektoren ausgehoben, bis sie bei ihren Grabungen direkt in ein unterirdisches Höhlensystem einbrachen, das von Troggs bewohnt wurde. Überrascht und überwältigt von dem wilden Ansturm wurden die Zwerge gewaltsam aus den Tiefen vertrieben und verloren sowohl die inneren Tunnel als auch den umliegenden Steinbruch an die Eindringlinge.",al={"geschichte der gol'bolarmine","was geschah in der mine","hintergrund der gol'bolarmine"}},["2d64c093"]={q="Ist die Gol'Bolarmine gefährlich?",a="Sie ist wesentlich gefährlicher als der Steinbruch außerhalb. Während schwächere Aasfresser durch die offenen Gruben streifen, lauern in diesen engen Tunneln unter dem Kommando ihres brutalen Anführers Hammerspine die tiefsten und stärksten Troggs. Wer unvorbereitet eintritt, sieht sich einem tödlichen unterirdischen Hinterhalt gegenüber.",al={"ist die gol'bolarmine gefährlich","wie gefährlich ist die gol'bolarmine","trogg-gefahr in der gol'bolarmine"}}},fp="21,238,20.233.0,19.330.0,31.162.0,50.134.0,50.125.0,27.122.0"}
P.entries["subzone:golakka-hot-springs"] = {n="Die heißen Quellen von Golakka",s="Im westlichen Krater von Un'Goro schießen die Geysire der heißen Quellen von Golakka nördlich der Terrorflucht empor. Die Hitze des Feuersäulengrats zieht Forscher und Alchemisten zu den dampfenden Becken.",h="Im westlichen Krater von Un'Goro schießen die Geysire der heißen Quellen von Golakka nördlich der...",kw={"feuersäulengrat","geysir","golakka","heiße quellen","krakle","spark nilminer","dämpfende furie","terrorflucht","un'goro"},ang={["class:Shaman"]="Als Schamane könnt Ihr in den heißen Quellen beobachten, wie Feuer und Wasser aufeinanderprallen. Aus ihrem Zusammentreffen entstehen brodelnde Dämpfende Furien entlang der mineralreichen Ufer.",["race:Gnome"]="Als Gnom teilt Ihr vielleicht Spark Nilminers Faszination für die gewaltige Geologie dieses Ortes. Er trotzt den brühend heißen Drucköffnungen, um geothermische Kräfte bei der Arbeit zu beobachten."},sec={{t="Kochendes Wasser und vulkanischer Dampf",b="Die heißen Quellen von Golakka sprudeln nördlich der Terrorflucht im westlichen Krater von Un'Goro. Die Hitze des Feuersäulengrats treibt brühend heißes Wasser durch den Boden nach oben. Es hinterlässt Mineralterrassen, und überall im Becken brechen Geysire aus. Dämpfende Furien durchstreifen die Becken, wo Grundwasser auf vulkanische Hitze trifft. Entdecker, Kräuterkundler und Forscher kommen weiterhin, um die ungewöhnliche Geologie des Kraters zu studieren."},{t="Neugierige Bewohner und seltsame Chemie",b="Alchemisten schätzen Golakkas Quellwasser als starken Katalysator. Sie verwenden es sogar in empfindlichen Mixturen wie Liebestränken. Spark Nilminer, ein neugieriger Besucher, thront auf der zentralen Geysiröffnung. Der Forscher Krakle kommt, um zu untersuchen, wie die Quellen bis ins vulkanische Herz des Kraters reichen."}},faq={{q="Warum sind die Quellen so heiß?",a="Das Vulkansystem des Feuersäulengrats erhitzt die Quellen unter dem Krater von Un'Goro. Magma überhitzt das Grundwasser und treibt kochendes, mineralreiches Wasser und Dampf durch die Geysire und terrassenförmigen Becken.",al={"warum kocht das wasser","geothermische hitze un'goro","verbindung zum feuersäulengrat"}},{q="Welche Kreaturen leben in den heißen Quellen von Golakka?",a="Dämpfende Furien durchstreifen die Ufer und Becken. Vulkanische Hitze verwandelt lebendiges Wasser in brodelnden, unberechenbaren Dampf.",al={"elementare der heißen quellen","was lebt in golakka","dämpfende furie"}},{q="Wofür wird das Wasser der heißen Quellen verwendet?",a="Alchemisten und exzentrische Brauer schätzen das Wasser wegen seiner ungewöhnlichen chemischen Eigenschaften. Reines Quellwasser fließt in besondere Gebräue ein, darunter auch mächtige Liebestränke.",al={"verwendung von golakkas wasser","heiße quellen liebestrank","reagenzien der heißen quellen"}},{q="Wer ist Krakle und was hat er hier gemacht?",a="Krakle erforscht die geothermische Verbindung zwischen den heißen Quellen von Golakka und dem Feuersäulengrat. Er sammelt Beobachtungen und Temperaturmesswerte rund um die Quellen.",al={"krakle un'goro","krakle heiße quellen","forscher an den heißen quellen"}}},fp="19,168,33.369.0,41.286.0,27.198.0,43.111.0,48.163.0,41.153.0"}
P.entries["subzone:gold-coast-quarry"] = {n="Der Goldküstensteinbruch",s="Im Südwesten von Westfall hält die Bruderschaft der Defias den Goldküstensteinbruch und nutzt seine verbliebenen Schätze für ihre Rebellion. Einst halfen sein Stein, seine Mineralien und sein Gold beim Wiederaufbau von Sturmwind.",h="Im Südwesten von Westfall hält die Bruderschaft der Defias den Goldküstensteinbruch und nutzt seine...",kw={"defias","bruderschaft der defias","der goldküstensteinbruch","mine","volksmiliz","steinbruch","sturmwind","westfall"},ang={["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass die Rückeroberung von Orten wie dem Goldküstensteinbruch entscheidend ist, um die Ordnung in Westfall wiederherzustellen. Da es keine königlichen Garnisonen gibt, haben örtliche Freiwillige zu den Waffen gegriffen.",["profession:Mining"]="Als Bergarbeiter in Westfall könnt Ihr entlang der Klippen des Steinbruchs ergiebige Felswände und Mineraladern finden. Um sie abzubauen, müsst Ihr Euch durch fest verschanzte Patrouillen der Defias kämpfen."},sec={{t="Eine geplünderte Rohstoffquelle",b="Sturmwind bezog einst Stein und Gold aus dem Goldküstensteinbruch, um das Königreich wiederaufzubauen. Nachdem die königlichen Truppen Westfall verlassen hatten, nahmen Straßenräuber der Defias und abtrünnige Arbeiter die Mine ein. Nun halten Patrouillen der Bruderschaft auf den terrassierten Rampen über der Küste Wache und bauen die verbliebenen Mineralien ab, um ihre Rebellion zu finanzieren."}},faq={{q="Wofür wurde der Steinbruch ursprünglich genutzt?",a="Sturmwind erschloss den Goldküstensteinbruch, um Stein, Mineralien und Gold zu gewinnen. Stein aus Steinbrüchen in ganz Westfall half, die Stadt nach dem Zweiten Krieg wiederaufzubauen.",al={"warum gibt es hier einen steinbruch","was wurde hier abgebaut","zweck von gold coast"}},{q="Wer kontrolliert derzeit den Goldküstensteinbruch?",a="Die Bruderschaft der Defias kontrolliert den Goldküstensteinbruch. Ihre Banditen, Plünderer und Straßenräuber patrouillieren entlang der terrassierten Klippen und Mineneingänge und halten Siedler fern, während sie Rohstoffe für ihre eigenen Unternehmungen gewinnen.",al={"wer ist am steinbruch","wem gehört der goldküstensteinbruch","feinde am steinbruch"}},{q="Warum hat Sturmwind keine Wachen geschickt, um den Steinbruch zu räumen?",a="Seit König Varian Wrynn verschwunden ist, weigert sich das Sturmwind House of Nobles, eine ständige Garnison in Westfall zu finanzieren. Die Krone hat die Region aufgegeben und überlässt es der Volksmiliz, allein um die Kontrolle über Orte wie den Steinbruch zu kämpfen.",al={"warum keine armee aus sturmwind","wo sind die wachen","warum ist er verlassen"}},{q="Wo liegt der Goldküstensteinbruch?",a="Der Goldküstensteinbruch schneidet sich in die Klippen im Südwesten von Westfall, südlich der Gehöfte von Saldean und Alexston, oberhalb des großen Meeres.",al={"lage des steinbruchs","wie findet man den goldküstensteinbruch","wo ist er"}}},fx={ddbe2f8b={q="Was ist Der Goldküstensteinbruch?",a="Der Goldküstensteinbruch war einst eine wertvolle Gold- und Mineralienmine im Tagebau, die dem Königreich Sturmwind diente. Die Stätte liegt nahe den westlichen Klippen von Westfall und ist zusammen mit dem Rest des Landes der Kontrolle der Krone entglitten und verfällt nun in den Händen von Rebellen.",al={"was ist der goldküstensteinbruch","wissen über den goldküstensteinbruch","goldküstensteinbruch westfall"}},f837a40e={q="Was ist mit dem Goldküstensteinbruch geschehen?",a="Einst eine produktive Abbaustätte, die die Schatzkammern von Sturmwind füllte, wurde der Steinbruch vom Königreich aufgegeben, als Unruhen und wirtschaftlicher Zusammenbruch über Westfall hereinbrachen. Ohne kaiserliche Wachen und königliche Finanzierung wurden die lukrativen Werke von The Defias Brotherhood beschlagnahmt, um ihre fortwährende Rebellion zu finanzieren.",al={"geschichte des goldküstensteinbruchs","was geschah im goldküstensteinbruch"}},["0f9583d4"]={q="Warum wurde der Goldküstensteinbruch aufgegeben?",a="Als die Steinmetze revoltierten und die königliche Autorität in ganz Westfall zusammenbrach, zog Sturmwind seine Garnisonen ab, um die Hauptstadt zu schützen. Da es an Soldaten und Unterstützung fehlte, um die Bergleute vor Banditen und Wegelagerern zu schützen, kam der rechtmäßige Betrieb zum Erliegen, was die Stätte reif für eine Übernahme machte.",al={"warum wurde der goldküstensteinbruch aufgegeben","warum ist der goldküstensteinbruch verfallen"}},["29652250"]={q="Ist der Goldküstensteinbruch gefährlich?",a="Extrem gefährlich. Der Steinbruch wimmelt von feindseligen Defias-Schurken und Wegelagerern, die ihren mineralischen Reichtum und ihre Außenposten rücksichtslos gegen alle umherziehenden Reisenden oder Mitglieder von The People's Militia verteidigen.",al={"gefahr im goldküstensteinbruch","ist der goldküstensteinbruch sicher","wer greift im goldküstensteinbruch an"}}},fp="17,183,20.306.0,40.147.0,45.209.0,53.227.0,39.131.0"}
P.entries["subzone:gold-road"] = {n="Goldstraße",s="Karawanen und Krieger der Horde ziehen auf der Goldstraße durch das Brachland. Sie führt vom Mor'shan-Schutzwall an der Grenze zum Eschental am Wegekreuz vorbei nach Süden.",h="Karawanen und Krieger der Horde ziehen auf der Goldstraße durch das Brachland.",kw={"karawane","das wegekreuz","goldstraße","verkehrsweg","mor'shan","brachland"},ang={["class:Hunter"]="Als Jäger könnt Ihr entlang der Savannenstraße den Tieren der Ebenen folgen. Löwen und Raptoren können zu frühen Gefährten werden, die Ihr aufspüren oder zähmen könnt.",["faction:Horde"]="Für die Horde werden auf der Goldstraße Vorräte durch Kalimdor befördert. Sie verbindet die Hauptstadt der Orcs in Durotar mit den Taurengebieten in Mulgore und den nördlichen vorgeschobenen Lagern nahe dem Eschental."},sec={{t="Die Lebensader des Brachlands",b="Die Goldstraße durchzieht das Brachland als langer, unbefestigter Verkehrsweg. Nahe ihrem nördlichen Ende schützen der Mor'shan-Schutzwall und der Mor'shan-Stützpunkt vor Einfällen der Nachtelfen aus dem Eschental. Weiter südlich zweigt eine Straße nach Osten nach Durotar ab, bevor die Goldstraße das Wegekreuz erreicht.\n\nHinter der Siedlung führt die Straße an örtlichen Oasen und den Ausläufern nahe den Höhlen des Wehklagens vorbei. Ihr nördlicher Abschnitt endet an einem ausgetrockneten Flussbett, wo Reisende das gefährlichere südliche Brachland betreten."},{t="Ein lebenswichtiger und gefährlicher Weg",b="Handel und Truppenbewegungen der Horde führen entlang der Goldstraße durch Kalimdors zentrale Gebiete. Doch auf ihrer gesamten Länge lauert Gefahr. Stacheleberstämme, Kriegstrupps der Zentauren, Ebenenschreiter und Löwen bedrohen Nachschubkarawanen und einsame Boten.\n\nDie Horde setzt beträchtliche Mittel ein, um Kundschafter und Krieger entlang der Straße zu stationieren. Dennoch bleiben Reisende bewaffnet und wachsam, sobald sie die größeren Außenposten verlassen."}},faq={{q="Wo beginnt und endet die Goldstraße?",a="Die Goldstraße beginnt am Mor'shan-Schutzwall an der Grenze zum Eschental. Ihr nördlicher Abschnitt führt südwärts durch das Wegekreuz zu einem ausgetrockneten Flussbett, das das nördliche vom südlichen Brachland trennt. Von dort führt die Südliche Goldstraße an Camp Taurajo vorbei und weiter in Richtung des Großen Aufzugs.",al={"verlauf der goldstraße","wohin führt die goldstraße","länge der goldstraße"}},{q="Warum ist die Goldstraße für die Horde so wichtig?",a="Die Goldstraße verbindet die wichtigsten Gebiete der Horde im Zentrum Kalimdors. Sie verbindet die Nachschublinien aus Durotar und dem Hafen von Ratschet mit der Heimat der Tauren in Mulgore und der nördlichen Front gegen die Nachtelfen im Eschental.",al={"warum ist die goldstraße wichtig","bedeutung der goldstraße"}},{q="Welche Bedrohungen streifen nahe der Straße umher?",a="Überfalltrupps der Razormane- und Borstennacken-Stacheleber, Kolkar-Zentauren und wilde Tiere wie Savannenstreuner und Donnerechsen streifen nahe der Straße umher. Außerhalb des Wegekreuzes ist sie alles andere als sicher.",al={"ist die goldstraße sicher","feinde auf der goldstraße","gefahren der goldstraße"}},{q="Wie ist die Goldstraße mit Durotar verbunden?",a="Nördlich des Wegekreuzes zweigt eine Straße nach Osten von der Goldstraße ab. Sie überquert den Südstrom über eine Holzbrücke und führt nach Durotar.",al={"straße nach durotar","abzweigung nach durotar"}}},fx={["5bf25b24"]={q="Ist die Goldstraße gefährlich zu bereisen?",a="Obwohl sie als die Hauptverkehrsader durch das Brachland dient, lädt schon ein leichtes Abweichen vom Pfad zur Gefahr ein. Die nördlichen Abschnitte streifen wilde Stacheleberbaue, aggressive Ebenenbestien und umherziehende Zentauren-Plünderer. Weiter südlich führt die Straße durch umkämpftes Gebiet, das voll von feindseligen Stachelmähnenstämmen, Silithid-Nestern und aggressiver Tierwelt in der Nähe der Oasen ist. Dicht an der Straße zu bleiben und in Gruppen zu reisen, bietet Eure besten Überlebenschancen.",al={"ist die goldstraße gefährlich","gefahr auf der goldstraße","ist die goldstraße sicher"}}},fp="9,160,25.467.0,26.382.0,39.282.0,47.234.0,34.205.0,42.129.0"}
P.entries["subzone:golden-plains"] = {n="Die Goldenen Ebenen",s="Im zentralen Mulgore liegen die Goldenen Ebenen südöstlich von Donnerfels. Tauren jagen in diesem sonnigen Becken, während umherziehende Kodoherden grasen.",h="Im zentralen Mulgore liegen die Goldenen Ebenen südöstlich von Donnerfels.",kw={"arra'chea","die goldenen ebenen","jagdgründe","kodo","mulgore","donnerfels"},ang={["class:Hunter"]="Diese weiten Ebenen und ihre umherziehenden Kodoherden bieten Jägern offenes Gelände, um legendäre Tiere wie Arra'chea aufzuspüren.",["race:Tauren"]="Für die Tauren verkörpern die Goldenen Ebenen die Fülle ihrer Heimat. Heilige Jagdgründe erstrecken sich im Schatten von Donnerfels."},sec={{t="Herz der Jagd",b="Unterhalb der hoch aufragenden Tafelberge von Donnerfels breiten sich goldene und grüne Gräser über Mulg ores wildes Herz aus. Nomadische Tauren schätzen diese traditionellen Jagdgründe, in denen die Tierwelt gedeiht. Große Kodoherden durchstreifen das Becken, und Jäger erzählen Geschichten von legendärer Jagdbeute. Dazu zählt der gewaltige Kodo Arra'chea, der durch das hohe Gras streift."}},faq={{q="Was sind die Goldenen Ebenen?",a="Die Goldenen Ebenen erstrecken sich südöstlich von Donnerfels über das zentrale Mulgore. Tauren schätzen dieses weite Graslandbecken mit seinen weiten Ausblicken und seiner reichen Tierwelt als traditionelles Jagdgebiet.",al={"goldene ebenen mulgore","wo liegen die goldenen ebenen"}},{q="Welche Tiere durchstreifen die Goldenen Ebenen?",a="Wilde Kodoherden durchstreifen das Becken neben anderen heimischen Geschöpfen Mulg ores. Am bekanntesten ist Arra'chea, ein scheuer und verehrter Kodo, der diese Graslande durchstreifen soll.",al={"tiere der goldenen ebenen","kodos in den goldenen ebenen"}},{q="Warum ist dieses Gebiet für die Tauren wichtig?",a="Die Ebenen liefern Wild und Häute für die neu gegründeten Siedlungen in ganz Mulgore. Sie halten auch die Tradition der Tauren lebendig, ihre Jagdbeute aufzuspüren und zu ehren.",al={"tauren goldene ebenen","warum tauren hier jagen"}}},fx={["977b4a77"]={q="Ist es gefährlich, durch Die goldenen Ebenen zu wandern?",a="Für einen unvorsichtigen Reisenden bergen die Ebenen echte Gefahren. Obwohl das Becken nicht von feindseligen Armeen wimmelt, ist es wildes Gebiet, das von Herden massiver Kodo beherrscht wird. Störungen können diese kolossalen Bestien leicht zu einem tödlichen Ansturm provozieren, und legendäre, aggressive Kreaturen wie Arra'chea streifen frei durch das wogende Grasland.",al={"sind die goldenen ebenen gefährlich","gefahr in den goldenen ebenen","sind die goldenen ebenen sicher"}}},fp="13,137,17.330.0,27.191.0,36.166.0,41.164.0"}
P.entries["subzone:goldshire"] = {n="Goldhain",s="Goldhain liegt dort, wo Elwynns Straßen zwischen Sturmwind, Westfall, dem Rotkammgebirge und der südlichen Grenze zusammentreffen. Nach dem Ersten Krieg wiederaufgebaut, bietet es Reisenden das Gasthaus \"Zur Höhle des Löwen\", während eine hart bedrängte Wache von Sturmwind die Stadt verteidigt.",h="Goldhain liegt dort, wo Elwynns Straßen zwischen Sturmwind, Westfall, dem Rotkammgebirge und der südlichen...",kw={"kristallsee","elwynn","goldhain","gasthaus \"zur höhle des löwen\"","marschall dughan","murloc","riverpaw","der steinhügelsee"},ang={["faction:Alliance"]="Als Reisende der Allianz kommt Ihr durch Goldhain, wenn Ihr von der Hauptstadt in die Grenzgebiete von Westfall, dem Rotkammgebirge und dem Dämmerwald zieht.",["race:Human"]="Als Mensch, der gerade die Abtei von Nordhain verlassen hat, erhaltet Ihr in Goldhain einen ersten echten Eindruck vom Königreich jenseits der Klostermauern und einen ernüchternden Blick auf Sturmwinds bedrängte Grenzen."},sec={{t="Eine Kreuzung unter Druck",b="Goldhain sichert die Kreuzung im ländlichen Elwynn, wo die Königsstraßen zusammentreffen. Die Bedrohungen rücken näher, während Sturmwinds Truppen schwinden und König Varian Wrynn auf mysteriöse Weise abwesend bleibt. Marschall Dughan muss sich auf vorbeiziehende Abenteurer statt auf reguläre Truppen verlassen, um die Grenzen zu bewachen. Riverpaw-Gnolle drängen von Westen vor, während feindselige Murlocs die Ufer des Steinhügelsees und des Kristallsees für sich beanspruchen. Ihre Angriffe haben königliche Wachen das Leben gekostet und die Gefahr nahe an die Stadt herangetragen."},{t="Narben der großen Kriege",b="Goldhain und Mondbruch waren die letzten Festungen, die im Ersten Krieg fielen. Kriegshäuptling Schwarzfaust schnitt König Llane Wrynn I. von seinem Reich ab, bevor er Burg Sturmwind plünderte, und die orcische Horde überrannte beide Städte. Goldhain wurde in Asche gelegt und lag öde, bis es nach dem Zweiten Krieg wiederaufgebaut wurde."}},faq={{q="Wer ist für die Verteidigung von Goldhain verantwortlich?",a="Marschall Dughan von der Wache von Sturmwind befehligt Goldhains Verteidigung. Er koordiniert die Garnison vom Stadtzentrum aus, doch fehlende Verstärkung zwingt ihn, unabhängige Abenteurer gegen Bedrohungen an den Grenzen und für Kopfgeldjagden auf Monster anzuheuern.",al={"wer führt goldhain","goldhain marschall","wer beschützt goldhain"}},{q="Welche Gefahren bedrohen die Stadt derzeit?",a="Riverpaw-Gnolle unternehmen Raubzüge nach Osten in Richtung Weststromgarnison, während feindselige Murlocs den Steinhügelsee und den Kristallsee unsicher machen. Örtliche Späher warnen, dass die Scharmützel ohne Eingreifen Goldhains Straßen erreichen könnten.",al={"goldhain probleme","warum ist goldhain in gefahr","feinde nahe goldhain"}},{q="Was geschah mit Goldhain während des Ersten Krieges?",a="Goldhain war eine der letzten beiden Städte der Menschen, die vor der Plünderung Sturmwinds fielen. Kriegshäuptling Schwarzfaust zerstörte es zusammen mit Mondbruch, um König Llanes Nachschubwege abzuschneiden, und ließ es bis zum Wiederaufbau nach dem Zweiten Krieg in Trümmern liegen.",al={"goldhain erster krieg","fiel goldhain an die orcs","goldhain zerstörung"}},{q="Warum ist das Gasthaus \"Zur Höhle des Löwen\" so bemerkenswert?",a="Das Gasthaus \"Zur Höhle des Löwen\" gehört zu Azeroths angesehensten und meistbesuchten Schankhäusern. Am Knotenpunkt mehrerer regionaler Landstraßen dient es Reisenden, die das Königreich durchqueren, als Treffpunkt, Rastplatz und Übungsstätte.",al={"gasthaus \"zur höhle des löwen\"","goldhain gasthaus","taverne in goldhain"}}},fx={["510017eb"]={q="Was ist Goldhain?",a="Goldhain ist eine geschäftige Stadt der Menschen, die zentral im Wald von Elwynn liegt und an der Kreuzung zwischen Sturmwind, dem Nordhaintal, Westfall und dem Rotkammgebirge ruht. Als wichtige Zwischenstation für Handel und Reisende ist sie oft die erste größere Siedlung, die von angehenden Helden besucht wird, die die Abtei verlassen.",al={"was ist goldhain","über goldhain","stadt goldhain"}},c15b14b9={q="Wer lebt in Goldhain?",a="Goldhain ist die Heimat von menschlichen Händlern, Handwerkern und Berufsausbildern, die sich um Reisende und Bauern aus der Umgebung kümmern. Sicherheit und Verwaltung unterstehen Marschall Dughan und seinen Wachen von Sturmwind, die den Außenposten besetzen, die Ordnung entlang der Kreuzung aufrechterhalten und ankommende Abenteurer dorthin schicken, wo Verteidigung am dringendsten benötigt wird.",al={"wer lebt hier","wer lebt in goldhain","einwohner von goldhain"}},d3dbe578={q="Ist Goldhain gefährlich?",a="Innerhalb der Stadtgrenzen hält die Wache von Sturmwind Euch relativ sicher, aber die Gefahr kriecht gefährlich nah an den Umkreis heran. Aggressive Flusspfoten-Gnolle schleichen durch die westlichen Grenzgebiete, während tödliche Murlocs in der Nähe gelegene Seen und Flüsse überrannt haben und drohen, direkt in das Dorf vorzudringen, wenn sie nicht aufgehalten werden.",al={"ist goldhain sicher","gefahr in goldhain","ist es hier gefährlich"}}},fp="9,244,25.467.0,23.299.0,40.234.0,45.210.0,48.235.0,39.224.0"}
P.entries["subzone:gordok-commons"] = {n="Gordok Commons",s="In den Gordok Commons regiert König Gordok die nördliche Festung der Gordunni in Düsterbruch.",h="In den Gordok Commons regiert König Gordok die nördliche Festung der Gordunni in Düsterbruch.",kw={"düsterbruch nord","eldre'thalas","gordok","gordok commons","könig gordok","knot thimblejack","mizzle","tributlauf"},ang={["profession:Engineering"]="Als Ingenieur könnt Ihr Knot Thimblejack, dem gefangenen Goblin, helfen, Vorräte aufzutreiben, kaputte Fallen zu reparieren und raffinierte Ablenkungen gegen die Ogerwachen zu ersinnen."},sec={{t="Sitz des Ogerkönigs",b="Die Gordok Commons nehmen einen alten aristokratischen Flügel von Eldre'Thalas ein. Die Oger haben seine nachtelfischen Säulen und gewölbten Durchgänge ihren eigenen Bedürfnissen angepasst. Waffenkammern, primitive Barrikaden und Übungsplätze drängen sich in den Hallen. Hier trainieren die Gordok, die wildesten und diszipliniertesten Kämpfer des Gordunniclans. Am äußersten Ende hält König Gordok auf Gordoks Sitz Hof und herrscht durch Gewalt und Furcht."},{t="Das Recht der Nachfolge",b="Unter den Gordunni entscheidet Stärke darüber, wer herrscht. Nach der Clantradition übernimmt jeder, der den amtierenden Monarchen erschlägt, den Titel König Gordok und gewinnt den Gehorsam der überlebenden Hauptleute und Wachen. Ein Herausforderer kann sich heimlich oder mit List an den Leutnants des Königs vorbeischleichen. Tötet der Herausforderer nur den König, erkennen die Wachen die Autorität des Siegers an und bringen üppige Tribute, statt ihren früheren Herrscher zu rächen."}},faq={{q="Wo liegen die Gordok Commons?",a="Die Gordok Commons nehmen das nördliche Viertel von Düsterbruch in Feralas ein. Betretet die Ruine durch die Broken Commons und folgt dann den gewaltigen Steinkorridoren zum nördlichen Eingang.",al={"gordok commons lage","wo ist düsterbruch nord","wie findet man die gordok commons"}},{q="Wer sind die Gordokoger?",a="Die Gordok sind die Elitekriegerkaste des Ogerclans der Gordunni. Ihre Verwandten durchstreifen die Wildnis von Feralas in verstreuten, wilden Banden, während die Gordok in den Commons organisiert und schwer bewaffnet sind und unter ihrem König einer strengen Befehlshierarchie folgen.",al={"wer sind die gordok","gordokclan","gordunni elite"}},{q="Wie wird die Herrschaft der Oger in den Commons bestimmt?",a="Der Kampf entscheidet, wer über die Gordok herrscht. Wer den regierenden König Gordok tötet, beansprucht die Krone, und die übrigen Oger unterwerfen sich ihrem neuen Herrscher.",al={"wie wird man könig der gordok","gordok nachfolge","könig gordok geschichte"}},{q="Warum lassen Abenteurer die Ogerwachen am Leben?",a="Wenn ein Eindringling König Gordok besiegt und seine Leutnants am Leben lässt, unterwerfen sich die Befehlshaber dem neuen König. Die Garnison bringt demjenigen wertvollen Tribut, der den Thron direkt beansprucht.",al={"warum tributlauf","wachen verschonen","gordok tribut geschichte"}}},fp="14,91,21.397.0,17.411.0,36.173.0,25.245.0,45.148.0,47.185.0"}
P.entries["subzone:gordunni-outpost"] = {n="Außenposten der Gordunni",s="Nördlich vom Larisspavillon halten die Gordunni-Oger ein befestigtes Lager in den Klippen. Ihre Anwesenheit lässt die umliegende Wildnis austrocknen und verdorren.",h="Nördlich vom Larisspavillon halten die Gordunni-Oger ein befestigtes Lager in den Klippen.",kw={"großfaust","kanalisierer","feralas","gordunni","hügelwache","larisspavillon","oger","außenposten","ogerzähmer"},ang={["class:Druid"]="Als Druide seht Ihr, wie die Anwesenheit der Gordunni der Natur schadet. Das üppige Blätterdach des Dschungels ist verdorrt und kahl.",["class:Hunter"]="Als Jäger seht Ihr, wie Ogerzähmer Bergbestien fangen und misshandeln. Sie halten Kreaturen wie den großen Sasquatch Großfaust gefesselt in Käfigen."},sec={{t="Ein verderbter Stützpunkt",b="Oberhalb des Larisspavillons patrouillieren Gordunni-Oger auf Pfaden, die in die nördlichen Berge von Feralas geschlagen wurden. Ihre Magie und ihr zerstörerisches Treiben entziehen der Wildnis das Leben. Pflanzen sterben ab, und die Berghänge liegen kahl da.\n\nErdpfade führen zu einem flachen Höhleneingang und einem größeren Hügelbau, der in die hinteren Klippen gegraben wurde. Hügelwachen, Kanalisierer und Ogerzähmer bewachen das Lager. Nahe der tieferen Höhle halten sie Großfaust, einen gefangenen Sasquatch, unter primitiven Bedingungen fest."}},faq={{q="Warum ist die Landschaft um diesen Außenposten verdorrt?",a="Die Zauberei und die zerstörerische Besatzung durch den Gordunni-Clan entziehen dem umliegenden Boden das Leben. Dschungelpflanzen verdorren, und der Boden wird trocken und braun.",al={"warum ist es braun","abgestorbenes gras feralas","verderbnis durch oger"}},{q="Welche Arten von Ogern besetzen den Außenposten der Gordunni?",a="Hügelwachen der Gordunni verteidigen den Außenposten, Kanalisierer der Gordunni wirken grobe Angriffszauber, und Ogerzähmer der Gordunni bewachen das Lager und seine gefangenen Bestien.",al={"welche gegner sind hier","gordunni-arten","wer lebt hier"}},{q="Wer ist Großfaust?",a="Großfaust ist ein gewaltiger Sasquatch, den die Gordunni-Oger nahe dem Eingang ihrer hinteren Höhle gefangen halten. Die Ogerzähmer halten ihn als Trophäe oder für Experimente gefesselt.",al={"sasquatch im käfig","wer ist großfaust","gefangener der oger"}},{q="Wo liegt der Außenposten der Gordunni?",a="Der Außenposten der Gordunni liegt hoch im Gebirgskamm nördlich vom Larisspavillon im Osten von Feralas.",al={"wo ist der außenposten der gordunni","lage des außenpostens","wie kommt man zum außenposten der gordunni"}}},fp="16,148,19.418.0,50.150.0,48.152.0,15.161.0,38.97.0"}
P.entries["subzone:grand-vestibule"] = {n="Grand Vestibule",s="Im Grand Vestibule bewachen scharlachrote Wachen den Durchgang zu den inneren Hallen des Klosters. Karmesinrote Säulen und Statuen gefallener Kreuzfahrer säumen den Eingang.",h="Im Grand Vestibule bewachen scharlachrote Wachen den Durchgang zu den inneren Hallen des Klosters.",kw={"eingangshalle","grand vestibule","scarlet augur","scarlet disciple","das scharlachrote kloster","scarlet sentry","tirisfal"},ang={["faction:Alliance"]="Als Champion der Allianz seht Ihr, wie Lordaerons einstige heilige Stätten entweiht wurden. Die Hingabe an das Licht ist in gewalttätigen Fanatismus umgeschlagen.",["race:Undead"]="Als Untoter stellt Ihr Euch den lebenden Fanatikern, die von dieser prächtigen Eingangshalle nordöstlich der Unterstadt aus die Herrschaft der Verlassenen in Tirisfal bedrohen."},sec={{t="Die Schwelle des Fanatismus",b="Hinter den äußeren Toren des Scharlachroten Klosters betretet Ihr eine Marmorhalle, gesäumt von Säulen und Statuen gerüsteter Champions. Scharlachrote Wachen, Jünger und Auguren patrouillieren über die Steinplatten. Sie strecken jeden nieder, der ohne den karmesinroten Wappenrock des Ordens eintritt. Hier trifft die strenge Disziplin des Kreuzzugs auf seinen Glaubenseifer."},{t="Ein umkämpfter Begegnungsort",b="Jeder Eindringling muss das Grand Vestibule durchqueren, um die bewachten inneren Flügel des Klosters zu erreichen. Nach Norden entsandte Champions der Allianz und Streitkräfte der Horde aus der nahen Unterstadt treffen unter seinen hohen Bögen auf die Verteidiger des Kreuzzugs. Dahinter liegen die inneren Kreuzgänge."}},faq={{q="Was ist das Grand Vestibule?",a="Das Grand Vestibule ist eine Eingangskammer im Nordosten von Tirisfal. Es verbindet den äußeren Hof des Scharlachroten Klosters mit seinen vier inneren Flügeln.",al={"was ist dieser raum","grand vestibule infos","eingangshalle des klosters"}},{q="Welche Feinde bewachen diesen Bereich?",a="Scarlet Sentries, Scarlet Disciples und Scarlet Augurs bewachen die Kammer für den Scharlachroten Kreuzzug und verwehren Eindringlingen den Zutritt.",al={"wer patrouilliert hier","mobs im vestibül","kreuzfahrer im vestibül"}},{q="Warum kämpfen Allianz und Horde hier?",a="Champions der Allianz betreten das Kloster, um die Fanatiker des Kreuzzugs anzugreifen, während die Horde Tirisfal für die Verlassenen sichern will. Beide durchqueren dieselbe Eingangshalle, obwohl dort keine überlieferte Schlacht zwischen den Fraktionen stattfand.",al={"pvp im vestibül","warum kämpfen spieler hier","umkämpftes vestibül"}},{q="Wen stellen die Statuen im Vestibül dar?",a="Die Statuen stellen geehrte Krieger und Helden des Scharlachroten Kreuzzugs in schweren Plattenrüstungen dar. Sie sind Symbole für den Kampf des Kreuzzugs gegen die Untoten.",al={"wen stellen die statuen dar","statuen im vestibül","denkmäler des kreuzzugs"}}},fx={["14cb93f7"]={q="Wer kontrolliert das Grand Vestibule?",a="The Scarlet Crusade hat die absolute Herrschaft über diese große Eingangskammer. Scharlachrote Auguren, Jünger und Wachen halten zwischen den hoch aufragenden Säulen und geschnitzten Statuen Wache und verteidigen die Schwelle zu ihren inneren Heiligtümern erbittert gegen jeden, den sie als befleckt oder unwürdig erachten.",al={"wer lebt im grand vestibule","wer verwaltet das grand vestibule","kontrolle über das grand vestibule"}},["38ab369b"]={q="Warum heißt diese Halle Grand Vestibule?",a="Ein Vestibül dient als Eingangshalle oder Vorraum, der in ein größeres Gebäude führt. Als äußerste Kammer von Das Scharlachrote Kloster machen ihre weitläufige Architektur, die hoch aufragenden Kolonnaden und die kunstvollen Statuen der Helden des Kreuzzugs sie in ihrer Größe und ihrem Zweck wahrhaft großartig.",al={"warum grand vestibule","ursprung des namens grand vestibule","bedeutung von grand vestibule"}},c059d7f1={q="Ist das Grand Vestibule gefährlich?",a="Äußerst gefährlich. Verteidiger des Scharlachroten Kreuzzugs sind in der gesamten Halle postiert und strecken Eindringlinge nieder, lange bevor sie die inneren Flügel des Klosters erreichen können.",al={"ist das grand vestibule sicher","wie gefaehrlich ist das grand vestibule","gefahr im grand vestibule"}}},fp="15,161,25.314.0,26.274.0,28.151.0,29.116.0,41.242.0,44.146.0"}
P.entries["subzone:great-forge"] = {n="Die Große Schmiede",s="Im Zentrum von Eisenschmiede hält die Große Schmiede ihre Feuer und ihre Schmiede in Gang. Ihr Großer Amboss zieht Menschen aus der ganzen Bergstadt an.",h="Im Zentrum von Eisenschmiede hält die Große Schmiede ihre Feuer und ihre Schmiede in Gang.",kw={"gießerei","großer amboss","die große schmiede","gryth thurden","eisenschmiede","magni bronzebart","myolor sunderfury"},ang={["profession:Blacksmithing"]="Der Große Amboss ist die bedeutendste Schmiedestätte der Allianz, mit hochrangigen Lehrern im Herzen der Stadt.",["race:Dwarf"]="Für Zwerge ist die Große Schmiede das Fundament der Zivilisation unter dem Berg. Ihre Feuer halten eine jahrhundertealte Schmiedetradition lebendig."},sec={{t="Herz des Berges",b="Die Große Schmiede war das erste Bauwerk, das die frühen Zwerge unter dem Berg von Eisenschmiede errichteten. Die Hauptstadt wuchs in Ringen um sie herum. Geschmolzener Stein und Schlacke fließen aus riesigen Gießereien durch glühende Kanäle und tauchen die Höhle in bernsteinfarbenen Dunst.\n\nIm Zentrum wacht Schmiedemeister Myolor Sunderfury über den gewaltigen Großen Amboss. Meister der Metallverarbeitung versammeln sich an seinem Rand und schmieden Tag und Nacht Rüstungen, Werkzeuge und Waffen."},{t="Knotenpunkt der Allianz",b="Schmiedearbeit ist nur ein Teil der Aufgaben der Großen Schmiede. Gildenstuben, Versorgungsläden und der wichtigste Gryphon Roost der Stadt umgeben die Halle. Gryth Thurden betreut den Horst, wo Reisende aus der gesamten Allianz inmitten der Hammerschläge zusammenkommen."}},faq={{q="Warum ist die Stadt nach dieser Schmiede benannt?",a="Die Große Schmiede war der erste Teil der Siedlung, die die Zwerge unter dem Berg in den Fels schlugen. Als sich die Hallen von ihrer zentralen Kammer aus nach außen ausbreiteten, nannten sie die Stadt nach dem großen Schmelzofen in ihrem Herzen Eisenschmiede.",al={"warum heißt eisenschmiede eisenschmiede","namensgeber der stadt","ursprung von eisenschmiede"}},{q="Welche bemerkenswerten Gegenstände wurden hier geschaffen?",a="Zwergische Schmiede haben über Generationen hinweg Waffen und Rüstungen am Großen Amboss gefertigt, darunter historische Meisterwerke. Die Feuer der Schmiede ließ man niemals erkalten.",al={"was wurde am großen amboss gefertigt","berühmte waffen der großen schmiede"}},{q="Wer beaufsichtigt die Schmiede?",a="Myolor Sunderfury leitet als Hüter der Großen Schmiede ihre tägliche Arbeit und Instandhaltung.",al={"hüter der großen schmiede","wer leitet die schmiede"}},{q="Warum ist es hier immer so voll?",a="Die Große Schmiede liegt im Zentrum von Eisenschmiede und ist mit dem äußeren Ring und den benachbarten Vierteln verbunden. Ihre Handwerkslehrer, Geschäfte und ihr zentraler Gryphon Roost ziehen Bürger, Kuriere und Reisende durch die Halle.",al={"warum so viele leute bei der schmiede","warum herrscht in der schmiede hochbetrieb"}}},fx={eab323ad={q="Was ist Die Große Schmiede?",a="Die Große Schmiede ist das feurige Herz und Namensgeberin von Eisenschmiede. Sie liegt genau im Zentrum der unterirdischen Bergstadt und ist ein geschäftiger, rußgefüllter Knotenpunkt, der sich um den legendären Großen Amboss dreht. Umgeben von tosenden Gießereien, geschäftigen Läden, Berufsausbildern und dem Greifenhorst der Stadt, steht die Schmiede niemals still und dient sowohl als wirtschaftliches Kraftzentrum als auch als lebendiger Treffpunkt des zwergischen Lebens.",al={"was ist die große schmiede","große schmiede eisenschmiede","über die große schmiede"}},dc416ec6={q="Ist Die Große Schmiede gefährlich?",a="Innerhalb der sicheren unterirdischen Grenzen von Eisenschmiede seid Ihr vor wilden Tieren und feindlichen Armeen sicher, bewacht von standhaften zwergischen Wachen. Die Schmiede selbst ist jedoch ein aktives industrielles Wunderwerk voller offener Rinnen mit geschmolzener Schlacke, sengender Hitze und schwerer Maschinerie. Ein unvorsichtiger Fehltritt über das Geländer oder in die lodernden Gruben wird sich für jeden, der unvorbereitet ist, schnell als tödlich erweisen.",al={"ist die große schmiede gefährlich","gefahren der großen schmiede","kann man in die große schmiede fallen"}}},fp="11,144,21.431.0,19.235.0,39.213.0,42.166.0,23.97.0,33.213.0"}
P.entries["subzone:great-lift"] = {n="Der Große Aufzug",s="Am Großen Aufzug reisen Menschen zwischen dem Südlichen Brachland und Tausend Nadeln. Plattformen der Tauren befördern Reisende und Vorräte zwischen dem Rand und dem Schluchtgrund, während Stacheleber die südliche Straße bedrohen.",h="Am Großen Aufzug reisen Menschen zwischen dem Südlichen Brachland und Tausend Nadeln.",kw={"kriegerheld mondhorn","aufzug","der große aufzug","grish fernläufer","stacheleber","brachland","tausend nadeln"},ang={["faction:Horde"]="Für die Horde verbindet der Aufzug das zentrale Kalimdor mit Tausend Nadeln und der Schimmernden Ebene. Er eröffnet eine lebenswichtige Route zu diesen abgelegenen Gegenden.",["race:Tauren"]="Als Tauren gehört Ihr zu dem Volk, das den Aufzug aus stabilem Bauholz und Gegengewichten errichtete. Er befördert Reisende durch zerklüftetes Gelände, ohne die Erde zu vernarben."},sec={{t="Tor aus Holz und Seil",b="Am Rand zwischen dem Südlichen Brachland und Tausend Nadeln hängen zwei hölzerne Plattformen über der Schlucht. Schweres Bauholz, geflochtene Seile und Seilzüge mit Gegengewichten befördern Karawanen, Kuriere und Krieger über den steilen Abgrund. Kriegerheld Mondhorn wacht auf der oberen Plattform, und Grish Fernläufer hält unten Wache. Sie weisen Reisenden den Weg und helfen dabei, Fracht sicher zu befördern."},{t="Gefahren am Schluchtrand",b="Die Straße zum Großen Aufzug führt durch feindseliges Gebiet im Südlichen Brachland. Stacheleberstämme sind nach Süden vorgedrungen und bedrohen nun die Route zwischen Tausend Nadeln und den nördlichen Pfaden. Reisende auf diesem langen Weg müssen Räuber aus dem Kral abwehren, bevor sie die hölzernen Plattformen erreichen."}},faq={{q="Wer hat den Großen Aufzug gebaut?",a="Die Tauren entwarfen und bauten den Großen Aufzug, um den steilen Höhenunterschied zwischen dem Brachland und dem Schluchtgrund von Tausend Nadeln zu überwinden.",al={"wer hat den großen aufzug gebaut","erbauer des großen aufzugs","ursprung des taurenaufzugs"}},{q="Warum ist die Reise zum Aufzug gefährlich?",a="Stacheleber aus dem Südlichen Brachland sind zum Schluchtrand vorgedrungen. Ihre Raubtrupps bedrängen Karawanen und Kuriere auf dem Weg zum Aufzug oder überfallen sie aus dem Hinterhalt.",al={"warum sind hier stacheleber","gefahren im südlichen brachland","straße zum aufzug versperrt"}},{q="Wer wacht über den Großen Aufzug?",a="Kriegerheld Mondhorn und Grish Fernläufer wachen über den Großen Aufzug. Sie helfen Reisenden der Horde und behalten die Wege und die umliegende Wildnis im Auge.",al={"wer bewacht den aufzug","wächter des aufzugs","tauren am aufzug"}},{q="Wohin führt der Große Aufzug?",a="Die Plattformen befördern Reisende hinab zum Schluchtgrund von Tausend Nadeln und hinauf ins Südliche Brachland.",al={"wohin führt der aufzug","was liegt unter dem aufzug","ziel des aufzugs"}}},fx={["15c17117"]={q="Was ist Der große Aufzug?",a="Der große Aufzug ist ein massiver, von Tauren konstruierter Aufzug am Abgrund, der das südliche Brachland vom Talboden der Tausend Nadeln trennt. Er dient als Hauptweg für Reisende, Händler und Boten, die sicher die aufragenden Klippen hinabsteigen wollen, ohne sich auf tückische Abstürze einzulassen.",al={"was ist der große aufzug","info zum großen aufzug","über den großen aufzug"}},["9d5e1aa9"]={q="Ist Der große Aufzug gefährlich?",a="Die mechanische Plattform selbst ist solide, aber die umliegenden Zugänge sind voller Gefahren. Aggressive Stacheleberstämme im südlichen Brachland haben ihr Territorium bis direkt an die Klippen ausgedehnt, überfallen Karawanen und drohen, Reisenden, die versuchen, die Kante des Aufzugs zu erreichen, den Weg abzuschneiden.",al={"ist der große aufzug gefährlich","ist der große aufzug sicher","bedrohungen am großen aufzug"}}},fp="10,205,35.372.0,18.290.0,25.120.0,39.147.0,32.149.0,31.102.0"}
P.entries["subzone:greatwood-vale"] = {n="Hochwipfeltal",s="Im östlichen Steinkrallengebirge halten die Grimtotem das Hochwipfeltal und greifen nahe Siedlungen an. Der gefährliche Weberpass führt in das bewaldete Tal, das ihnen nun als Ausgangsbasis für blutige Angriffe dient.",h="Im östlichen Steinkrallengebirge halten die Grimtotem das Hochwipfeltal und greifen nahe Siedlungen an.",kw={"camp aparaje","hochwipfeltal","grimtotem","grundig darkcloud","makaba flachhuf","malaka'jin","steinkrallengebirge","weberpass"},ang={["faction:Horde"]="Die Sicherung des Hochwipfeltals hilft, Malaka'jin, den gefährdeten südlichen Außenposten, vor plötzlichen Flankenangriffen durch abtrünnige Grimtotem zu schützen.",["race:Tauren"]="Für ein treues Kind von Donnerfels ist die Säuberung des Hochwipfeltals eine schmerzliche, persönliche Pflicht, nachdem die Grimtotem andere Tauren in Camp Aparaje abgeschlachtet haben."},sec={{t="Ein umkämpftes Tal",b="Das Hochwipfeltal ist abseits des Weberpasses zu einem gewalttätigen Grenzland geworden. Grundig Darkcloud führt die Grimtotem an, die in großer Zahl in das Tal eingezogen sind. Sie verhindern einen sicheren Durchgang und terrorisieren die umliegenden Ausläufer."},{t="Die Geißel von Camp Aparaje",b="Vom Hochwipfeltal aus fielen Plünderer der Grimtotem in das nahe Camp Aparaje ein und schlachteten fast alle Tauren dort ab. Makaba Flachhuf entkam. Nun schickt er rachsüchtige Krieger der Horde ins Herz des Tals, um die abtrünnigen Grimtotem zu töten und Grundig Darkclouds Herrschaft zu beenden."}},faq={{q="Wer kontrolliert derzeit das Hochwipfeltal?",a="Grundig Darkcloud führt die Grimtotem an, die das Hochwipfeltal besetzen. Ihre Kriegerscharen und Zauberwirker bedrohen jeden, der durch die Wälder reist.",al={"wer lebt im hochwipfeltal","feinde im hochwipfeltal","grimtotem im hochwipfeltal"}},{q="Was geschah in Camp Aparaje?",a="Plünderer der Grimtotem griffen Camp Aparaje vom Hochwipfeltal aus an und massakrierten die meisten seiner friedlichen Taurenbewohner. Makaba Flachhuf überlebte und sinnt auf Rache an den Plünderern und ihrem Anführer.",al={"geschichte von camp aparaje","was geschah mit aparaje","warum griffen die grimtotem an"}},{q="Warum kämpft die Horde hier gegen die Grimtotem?",a="Die Grimtotem sind der Horde nicht offiziell beigetreten, obwohl Magatha in Donnerfels weilt. Nachdem Grundig Darkclouds Anhänger andere Tauren in Camp Aparaje angegriffen hatten, baten Überlebende Krieger der Horde um Hilfe.",al={"warum grimtotem töten","makaba flachhuf quest","avenge my village"}}},fx={["87537350"]={q="Was ist Hochwipfeltal?",a="Hochwipfeltal ist ein bewaldetes Tal in den Ausläufern des Steinkrallengebirges, das über den Weberpass erreicht werden kann. Malaka'jin liegt südlich davon. Feindliche Grimtotemtauren haben das Tal zu einer Basis für Angriffe auf nahegelegene Siedlungen gemacht.",al={"hochwipfeltal","was ist das für ein ort","steinkrallengebirge tal"}},["3922b097"]={q="Ist Hochwipfeltal gefährlich?",a="Ja, Hochwipfeltal ist außerordentlich feindselig. Abgesehen von giftigen Webholzspinnen, die den Zugang entlang des Weberpasses befallen, ist das Tal in die Hände abtrünniger Grimtotemtauren gefallen. Angeführt vom Kriegsfürsten Grundig Darkcloud jagen diese Plünderer aktiv jeden Außenstehenden, der sich in den Wald wagt.",al={"gefahr in hochwipfeltal","ist es hier sicher","bedrohungen in hochwipfeltal"}}},fp="14,187,18.208.0,27.268.0,38.140.0,30.195.0,45.214.0"}
P.entries["subzone:green-belt"] = {n="Der grüne Gürtel",s="Im östlichen Sumpfland liegt der grüne Gürtel unterhalb der Höhenzüge von Grim Batol. Sumpfbestien, Krokolisken und giftige Schleime durchstreifen das Marschland, während Rethiel der Sumpfhüter allein Wache hält.",h="Im östlichen Sumpfland liegt der grüne Gürtel unterhalb der Höhenzüge von Grim Batol.",kw={"sumpfbestien","dragonmaw","der grüne gürtel","grim batol","schleime","rethiel","sumpfland","welpen"},ang={["class:Druid"]="Als Druide könnt Ihr erkennen, wie entstellte Schleime und ungebändigte Sumpfbestien die natürliche Harmonie des Marschlands stören. Das Moor bereitet den Hütern der Wildnis Sorge.",["race:NightElf"]="Als Nachtelf mag Euch Rethiels des Sumpfhüters einsame Wache in einem Sumpf der Östlichen Königreiche überraschen. Seine Anwesenheit erinnert an den Zirkel des Cenarius und die Hingabe der Nachtelfen, wilde Landstriche zu heilen, wo immer sie liegen."},sec={{t="Ein wildes, umkämpftes Moor",b="Im östlichen Sumpfland machen die moosigen Gewässer des grünen Gürtels das Reisen gefährlich. Gewaltige Krokolisken, wabernde Schleime und schlurfende Sumpfbestien durchstreifen das Moor. Tief im Inneren hält Rethiel der Sumpfhüter einen einsamen Wachposten besetzt. Der Nachtelf erforscht die Ökologie des Moors und hält dessen feindselige Kreaturen im Zaum."},{t="Überreste des Zweiten Krieges",b="Trümmer einer Karawane des Dragonmaw-Clans liegen verstreut im Morast. Sie wurden nach der verheerenden Schlacht beim nahe gelegenen Grim Batol zurückgelassen. Purpurrote Welplinge verweilen bei den zerbrochenen Karren und zertrümmerten Käfigen und erinnern an die einstige Versklavung Alexstraszas und ihrer roten Drachenbrut durch den Clan."}},faq={{q="Wo liegt der grüne Gürtel?",a="Der grüne Gürtel erstreckt sich im östlichen Sumpfland entlang der durchnässten Niederungen zwischen der Hauptstraße und den Ausläufern, die nach Grim Batol hin ansteigen.",al={"grüner gürtel lage","wo liegt der grüne gürtel","grüner gürtel sumpfland karte"}},{q="Wer ist Rethiel der Sumpfhüter?",a="Rethiel der Sumpfhüter ist ein Nachtelf, der allein im Marschland des Sumpflands Wache hält. Fern seiner angestammten Heimat Kalimdor will er das Gleichgewicht der Natur im Sumpf bewahren und wirbt Reisende an, um verderbenden Bestien und Schleimen beizukommen.",al={"wer ist rethiel","rethiel der sumpfhüter","nachtelf im grünen gürtel"}},{q="Warum gibt es hier rote Welpen und zerbrochene Wagen?",a="Die zerbrochenen Wagen sind Überreste einer Versorgungskarawane des Dragonmaw-Clans, die in die Nachwehen des Zweiten Krieges geriet. Die Orcs wurden aus Grim Batol vertrieben, und ihre Herrschaft über die red dragonflight wurde gebrochen.",al={"dragonmaw-karawane","warum gibt es welpen im sumpfland","rote welpen sumpfland"}},{q="Welche Bedrohungen durchstreifen den grünen Gürtel?",a="Gefährliche Krokolisken, giftige lebende Schleime und hoch aufragende Sumpfbestien durchstreifen den grünen Gürtel und verschmelzen mit der durchnässten Vegetation.",al={"grüner gürtel gegner","gefahren im grünen gürtel","welche monster leben hier"}}},fx={b9266860={q="Was ist Der grüne Gürtel?",a="Der grüne Gürtel ist eine wilde, überwucherte Weite im östlichen Sumpfland. Im Gegensatz zu den trockeneren Straßen und zwergischen Ausgrabungen im Westen und Süden bleibt dieses durchnässte Gebiet weitgehend ungezähmtes Marschland, das durch dichten Sumpfbewuchs, schlammige Tümpel und die einsame Anwesenheit des mysteriösen Hüters Rethiel der Sumpfhüter gekennzeichnet ist.",al={"was ist der grüne gürtel","grüner gürtel sumpfland","über den grünen gürtel"}},["453ecde9"]={q="Wer lebt im Grünen Gürtel?",a="Keine zivilisierte Siedlung beansprucht Der grüne Gürtel. Abgesehen von einheimischen Sumpfprädatoren ist Rethiel der Sumpfhüter der einzige nennenswerte Bewohner, der über dieses wilde Sumpfland wacht. Er hält hier einsam Wache, überwacht das natürliche Gleichgewicht und verteidigt den Sumpf gegen eindringende Fäulnis.",al={"wer lebt im grünen gürtel","bewohner des grünen gürtels","einwohner des grünen gürtels"}},e91fe995={q="Wie gefährlich ist Der grüne Gürtel?",a="Sich in Der grüne Gürtel zu begeben, birgt ernsthafte Gefahren für unvorsichtige Reisende. Die trüben Gewässer wimmeln von aggressiven Krokilisken, wandernden Schlämmen und hochaufragenden Sumpfbestien. Überdies ziehen Überreste zertrümmerter Dragonmaw-Wagen ungezähmte rote Welpen an, die jeden, der in ihr Territorium eindringt, aggressiv niederschlagen.",al={"ist der grüne gürtel gefährlich","gefahren im grünen gürtel","bedrohungen im grünen gürtel"}}},fp="10,173,24.295.0,26.283.0,32.128.0,31.239.0,48.205.0,35.119.0"}
P.entries["subzone:greenpaw-village"] = {n="Laubtatzenlichtung",s="Die Laubtatzenlichtung liegt zwischen Rajenbaum und der Silberwindzuflucht, wo die Furbolgs der Foulweald weiterhin feindselig sind. Chief Murgut und Schamane Oakpaw führen den verderbten Stamm an, während Streitkräfte der Allianz und der Horde im Eschental gegen ihn kämpfen.",h="Die Laubtatzenlichtung liegt zwischen Rajenbaum und der Silberwindzuflucht, wo die Furbolgs der Foulweald...",kw={"eschental","foulweald","furbolg","laubtatzenlichtung","murgut","oakpaw","rajenbaum","silberwindzuflucht"},ang={["class:Druid"]="Als Druide erlebt Ihr in der Laubtatzenlichtung das Leid des uralten Bärenvolkes, wo das Gleichgewicht der Natur in wilden Wahnsinn umgeschlagen ist.",["race:NightElf"]="Für Nachtelfen erinnert die Verderbnis der Foulweald nahe Rajenbaum und ihren heiligen Mondbrunnen an die noch immer bestehenden dämonischen Narben des Eschentals."},sec={{t="Eine verderbte Siedlung",b="Südlich von Rajenbaum und nordöstlich der Silberwindzuflucht leben die Furbolgs der Foulweald in der Laubtatzenlichtung. Seit dem Dritten Krieg hat die Verderbnis im Boden und in den Geistern des Eschentals sie befallen. Chief Murgut führt den Stamm an, mit Schamane Oakpaw als seinem verderbten spirituellen Führer. Reisende, die ihr Waldgebiet betreten, werden angegriffen."},{t="Im Kreuzfeuer",b="Die Angriffe der Foulweald führen rings um die Laubtatzenlichtung zu Kämpfen. Schildwachen der Allianz und Druiden der Nachtelfen wollen die Furbolgs läutern und nahegelegene Vorposten und heilige Mondbrunnen schützen. Auch Streitkräfte der Horde, die durch das Eschental vorrücken, kämpfen gegen sie, während beide Fraktionen durch den Wald drängen."}},faq={{q="Wo liegt die Laubtatzenlichtung?",a="Die Laubtatzenlichtung liegt im zentralen Eschental, südlich von Rajenbaum, nordöstlich der Silberwindzuflucht und nordwestlich des südlichen Mondbrunnens.",al={"laubtatzenlichtung lage","wo liegt die laubtatzenlichtung","laubtatzenlichtung finden"}},{q="Wer lebt in der Laubtatzenlichtung?",a="Der Furbolgstamm der Foulweald lebt in der Laubtatzenlichtung. Chief Murgut führt ihn an, mit Schamane Oakpaw als seinem verderbten spirituellen Berater.",al={"wer ist hier","laubtatzenlichtung gegner","laubtatzenlichtung furbolgs"}},{q="Warum sind die Furbolgs in der Laubtatzenlichtung feindselig?",a="Die dämonische Verderbnis, die nach dem Einfall der Brennenden Legion ins Eschental zurückblieb, trieb die Foulweald in rasende Angriffslust.",al={"warum sind furbolgs wahnsinnig","sind die furbolgs der laubtatzenlichtung verderbt"}},{q="Warum kämpfen Allianz und Horde hier?",a="Beide Fraktionen sehen die aggressiven Foulweald als Bedrohung für ihre Straßen und Siedlungen. Die Nachtelfen wollen den Wahnsinn nahe ihren Mondbrunnen läutern oder eindämmen, während Streitkräfte der Horde beim Vorrücken durch das Eschental gegen die Furbolgs kämpfen.",al={"laubtatzenlichtung quests","wer greift die laubtatzenlichtung an"}}},fx={["44cbc3fb"]={q="Was ist Laubtatzenlichtung?",a="Laubtatzenlichtung ist eine Furbolgsiedlung im zentralen Eschental, südlich von Rajenbaum und nordöstlich der Silberwindzuflucht gelegen. Einst eine friedliche Enklave inmitten des uralten Waldes, dient sie als Heimatlager für den Stamm der Foulweald, komplett mit rustikalen Holzhütten, Totems und Feuerstellen unter dem dichten Blätterdach des Waldes.",al={"was ist laubtatzenlichtung","geschichte der laubtatzenlichtung","erzähle mir von der laubtatzenlichtung"}},e6fbac57={q="Was ist in Laubtatzenlichtung geschehen?",a="Wie viele Furbolggemeinschaften im gesamten Eschental erlagen die Bewohner von Laubtatzenlichtung der schleichenden dämonischen Verderbnis, die den Wald während des Dritten Krieges verseuchte. Wahnsinnig geworden durch dunkle Energien, wurden die Foulweald gegenüber Außenstehenden gewalttätig und aggressiv und verwandelten ihre friedliche Siedlung in einen feindseligen Bau, der sowohl Nachtelfen als auch nahegelegene Außenposten der Horde auf den Plan ruft.",al={"historie der laubtatzenlichtung","was passierte in laubtatzenlichtung","historischer hintergrund laubtatzenlichtung"}},["303ee734"]={q="Ist Laubtatzenlichtung gefährlich?",a="Laubtatzenlichtung ist außerordentlich gefährlich, wenn man unvorbereitet hineinwandert. Die Furbolgs der Foulweald sind aggressiv, greifen jeden Eindringling sofort an und kämpfen mit wilder Kraft. Unter ihren Reihen befinden sich mächtige Schamanen wie Oakpaw und wilde Anführer wie Häuptling Murgut, was das Lager für einsame Reisende, die sich durch das Herz des Waldes bewegen, gefährlich macht.",al={"wie gefährlich ist die laubtatzenlichtung","ist die laubtatzenlichtung gefährlich","gefahren in laubtatzenlichtung"}}},fp="16,230,22.334.0,24.299.0,34.143.0,30.136.0,49.112.0,45.237.0"}
P.entries["subzone:greymane-wall"] = {n="Der Greymane-Wall",s="Am Südrand des Silberwalds versperrt der Greymane-Wall den Weg nach Gilneas. König Genn Greymane ließ ihn nach dem Zweiten Krieg errichten, und seine Tore bleiben der Außenwelt verschlossen.",h="Am Südrand des Silberwalds versperrt der Greymane-Wall den Weg nach Gilneas.",kw={"arugal","genn greymane","gilneas","der greymane-wall","pyrewood","silberwald"},ang={["faction:Alliance"]="Für die Allianz erinnert der Greymane-Wall daran, wie Gilneas seine einstigen Verbündeten im Stich ließ. Als die Geißel Lordaeron einnahm, ignorierte Greymane ihre Bitten und ließ sie vor seinen Toren zurück.",["faction:Horde"]="Für die Verlassenen, die nun den Silberwald beanspruchen, bildet der Greymane-Wall eine unüberwindbare Südgrenze. Er schottet ein Menschenkönigreich ab, dessen Absichten und Stärke unbekannt bleiben."},sec={{t="Ein Denkmal der Isolation",b="Nach dem Zweiten Krieg wandte sich König Genn Greymane von der Allianz ab, verbittert über ihre Forderungen, besonders die Steuern für die Internierungslager der Orcs. Er glaubte, Gilneas habe genug mit Münzen und Blut für die Nöte jenseits seiner Grenzen bezahlt. Also zog er das Königreich aus der Allianz zurück und befahl, am Ansatz der Halbinsel eine gewaltige Barriere zu errichten. Als der Dritte Krieg die Seuche des Untods und verzweifelte Flüchtlinge zum Wall brachte, blieben seine Tore geschlossen."},{t="Der Preis der Abschottung",b="Der Wall hielt die Geißel davon ab, die Halbinsel zu überrennen. Der Silberwald jenseits davon fand keine solche Sicherheit. Erzmagier Arugal aus Dalaran beschwor wilde Worgen, um die Untoten zu bekämpfen, doch die Bestien ließen sich nicht kontrollieren. Nun durchstreifen sie den Wald unterhalb des schweigenden Walls. Was hinter den Toren liegt, bleibt der Außenwelt unbekannt."}},faq={{q="Was liegt jenseits des Greymane-Walls?",a="Jenseits des Walls liegt Gilneas, ein Königreich auf einer Halbinsel, das von König Genn Greymane regiert wird. Vor dem Dritten Krieg schottete sich Gilneas von Lordaeron und dem Rest der Welt ab und stellte jeden Handel und jede Kommunikation ein.",al={"was ist hinter dem wall","wohin führt der greymane-wall","welches königreich liegt hinter dem wall"}},{q="Könnt Ihr die Tore des Greymane-Walls öffnen?",a="Nein. Das Fallgitter und die eisenbeschlagenen Tore sind von der Südseite aus verriegelt. Gilneas hat jeden Kontakt zur Außenwelt abgebrochen, und nichts gelangt hinein oder hinaus.",al={"wie am greymane-wall vorbeikommen","lässt sich der greymane-wall öffnen","das tor öffnen"}},{q="Warum wurde der Wall hier errichtet und nicht weiter südlich?",a="Keine Aufzeichnung erklärt den genauen Verlauf des Walls. Er durchquert den Südrand des Silberwalds am Ansatz der Halbinsel der Gilneer, sodass Dörfer wie Pyrewood und Mühlenbern nördlich davon liegen.",al={"warum wurde er hier gebaut","warum pyrewood abschneiden","ländereien von crowley abgeschnitten"}},{q="Was geschah mit den Flüchtlingen, die während des Dritten Krieges hierher flohen?",a="Als die Geißel Lordaeron verwüstete, versammelten sich Scharen menschlicher Flüchtlinge vor dem Wall und flehten um Einlass. König Greymane weigerte sich, die Tore zu öffnen, um sein Königreich zu schützen. Schließlich schlachteten die Untoten die verzweifelten Flüchtlinge draußen ab.",al={"geißel flüchtlinge wall","flüchtlinge vor dem greymane-wall"}}},fx={["29630d52"]={q="Was ist Der Greymane-Wall?",a="Der Greymane-Wall ist ein kolossales steinernes Bollwerk, das sich über die südliche Grenze des Silberwaldes erstreckt. Von König Genn Greymane nach dem Zweiten Krieg in Auftrag gegeben, riegelt es das Königreich Gilneas vom Lordaeron und dem Rest der Welt hinter massiven, undurchdringlichen Toren ab.",al={"was ist der greymane-wall","der greymane-wall","riesiger wall im silberwald"}},["18f5ff7d"]={q="Warum heißt es Der Greymane-Wall?",a="Er ist nach König Genn Greymane benannt, dem Herrscher von Gilneas, der seinen Bau befahl. Verärgert über hohe Steuern zur Unterstützung der Orc-Internierungslager der Allianz und müde von fremden Kriegen, errichtete Greymane die kolossale Barriere, um seine Nation vollständig zu isolieren.",al={"warum heißt er greymane-wall","wer benannte den greymane-wall","namensherkunft greymane"}},e1e9af4d={q="Wer kontrolliert Der Greymane-Wall?",a="Der Wall gehört vollständig dem isolationistischen Königreich Gilneas, das von König Genn Greymane regiert wird. Während Gilneer Wachen von der sicheren Seite der großen Befestigungsanlagen Wache halten, ist der äußere Perimeter völlig der Wildnis und den Schatten, die durch den Silberwald streifen, überlassen.",al={"wer kontrolliert den greymane-wall","wer bewacht den wall","wer lebt am greymane-wall"}},["6b007fab"]={q="Ist Der Greymane-Wall gefährlich?",a="Der Wall selbst ist eine unpassierbare Steinbarriere, aber die Ländereien vor seinem Tor sind gefährlich. Der Silberwald ist überlaufen von wilden Worgen, rachsüchtigen Geistern und feindseligen Bestien, die über jeden Reisenden herfallen, der zu nahe am stillen, versperrten Eingang verweilt.",al={"ist der greymane-wall sicher","ist es gefährlich am wall","bedrohungen am greymane-wall"}}},fp="13,174,23.444.0,22.326.1,35.204.0,44.161.0,53.185.0,65.246.0"}
P.entries["subzone:grim-batol"] = {n="Grim Batol",s="Über dem östlichen Sumpfland bleiben Grim Batols Tore versiegelt. Ein Fluch vertrieb die Wildhammerzwerge aus der Festung, und die Orcs des Dragonmawclans machten sie später zu einer Drachenbrutstätte.",h="Über dem östlichen Sumpfland bleiben Grim Batols Tore versiegelt.",kw={"alexstrasza","dämonenseele","dragonmaw","grim batol","modgud","nekros","sumpfland","wildhammer"},ang={["faction:Horde"]="Für die Horde erinnert Grim Batol an den Zweiten Krieg. Der Dragonmawclan eroberte mit versklavten Drachen die Lüfte, bevor er gewaltsam zugrunde ging.",["race:Dwarf"]="Für Euch als Zwerg erinnert Grim Batol an den Krieg der drei Hämmer. Einst war es eine stolze Schwesterstadt von Eisenschmiede, bis Dunkeleisenzauberei es unbewohnbar machte."},sec={{t="Eine zweifach verfluchte Festung",b="Thane Khardros Wildhammer schlug Grim Batol nach dem uralten Bürgerkrieg der drei Clans aus den zerklüfteten Bergen östlich des Sumpfes. Während des Kriegs der drei Hämmer belagerte die Dunkeleisenzauberin Modgud die Festung. Khardros streckte sie nieder, doch mit ihrem letzten Atemzug warf Modgud einen finsteren Schatten über ihre Steine.\n\nDas Verderben blieb in den Hallen zurück und machte sie unbewohnbar. Die überlebenden Wildhammerzwerge gaben ihr Königreich auf und zogen nach Norden ins Hinterland."},{t="Ketten der Drachenkönigin",b="Während des Zweiten Krieges entsandte Orgrim Schicksalshammer den Dragonmawclan, um Grim Batol einzunehmen. Der Hexenmeister Nekros Skullcrusher führte sie an, und mit dem uralten Artefakt namens Dämonenseele versklavten sie die rote Drachenkönigin Alexstrasza tief unter dem Berg. Dort angekettet, musste sie Gelege für die Kriegsanstrengungen der Horde ausbrüten, bis eine kleine Schar von Helden das Artefakt zerschmetterte.\n\nBefreit verbrannte der erzürnte Drachenaspekt die Orcs im Inneren. Grim Batol wurde zu einer trostlosen Ruine, die von überlebenden roten Drachen aufmerksam bewacht wurde."}},faq={{q="Können Spieler Grim Batol betreten?",a="Nein. Die gewaltigen Steintore am Ende der Bergstraße bleiben Reisenden verschlossen. Ihr könnt nur die Tore und äußeren Wehrgänge in den Bergen des östlichen Sumpflands besuchen.",al={"grim batol betreten","ist grim batol offen","grim batol tor"}},{q="Warum haben die Wildhammerzwerge die Festung verlassen?",a="Während des Kriegs der drei Hämmer belegte die Dunkeleisenzauberin Modgud Grim Batol mit einem finsteren Schattenfluch, bevor sie erschlagen wurde. Das Verderben machte die Festung unbewohnbar und zwang die Wildhammerzwerge, sie aufzugeben und den Nistgipfel im Hinterland zu errichten.",al={"warum verließen die zwerge grim batol","wildhammerfluch","modguds fluch"}},{q="Was geschah mit den Orcs des Dragonmawclans, die hier lebten?",a="Der Magier Rhonin und seine Gefährten zerschmetterten die Dämonenseele und befreiten die gefangene Drachenkönigin Alexstrasza von ihren Ketten. Erzürnt über ihre Gefangenschaft verbrannte sie mit ihrer Brut Nekros Skullcrusher und brach die Macht des Dragonmawclans in der Festung.",al={"dragonmaw grim batol","was geschah mit den orcs hier","nekros skullcrusher"}},{q="Wer kontrolliert Grim Batol derzeit?",a="Grim Batol liegt verlassen da. Überreste des Dragonmawclans und wilde Tiere hausen in den umliegenden Felsen, während der Red Dragonflight den verfluchten Berg bewacht, damit seine dunkle Geschichte nicht wiederkehrt.",al={"wem gehört grim batol","wer lebt jetzt in grim batol"}}},fx={["7aeea9cc"]={q="Was ist Grim Batol?",a="Grim Batol ist eine uralte, weitläufige Bergfestung, die in die östlichen Gipfel jenseits des Sumpflands gehauen wurde. Obwohl ihre aufragenden Tore und Zinnen das Sumpfgebiet überblicken, erstreckt sich der Großteil der Festung tief unter die Erde. Vom Wildhammerclan nach seiner Verbannung aus Eisenschmiede gegründet, diente sie als deren stolze Hauptstadt, bevor dunkle Zauberei die Hallen korrumpierte und sie zu einer düsteren, bedrohlichen Bastion machte, die jahrhundertelang Leid, Besatzung und Krieg gesehen hat.",al={"was ist grim batol","festung grim batol","über grim batol"}},["06dc57c0"]={q="Ist Grim Batol gefährlich?",a="Grim Batol ist außerordentlich gefährlich und streng für Reisende abgeriegelt. Langanhaltende dunkle Zauberei aus dem Krieg der drei Hämmer verunreinigt noch immer ihr Inneres, und die Himmel und Zugänge um ihre kolossalen Tore werden von elitären, feindseligen roten Drachen patrouilliert, die auf jeden Eindringling achten. Zwischen der anhaltenden Verderbnis im Inneren und den tödlichen Wächtern draußen lädt jeder Annäherungsversuch an die Festung zu unmittelbarer Gefahr ein.",al={"wie gefährlich ist grim batol","ist grim batol sicher","bedrohungen in grim batol"}}},fp="10,183,23.487.0,26.520.0,29.177.0,42.246.0,51.248.0,34.201.0"}
P.entries["subzone:grimesilt-dig-site"] = {n="Rußschlacks Grabungsstätte",s="Schildwachen der Dunkeleisenzwerge patrouillieren in Rußschlacks Grabungsstätte in der Sengenden Schlucht. Hier begann Eisenschmiedes Suche nach Relikten, und die überlebenden Mitglieder der Expedition kämpfen im Verborgenen ums Überleben.",h="Schildwachen der Dunkeleisenzwerge patrouillieren in Rußschlacks Grabungsstätte in der Sengenden Schlucht.",kw={"archäologie","dunkeleisenzwerge","dorius stonetender","ausgrabung","rußschlacks grabungsstätte","eisenschmiede","sengende schlucht"},ang={["faction:Alliance"]="Die Grabungsstätte zeugt von einem Unterfangen Eisenschmiedes, das die Dunkeleisenzwerge zerschlugen. Bedrängte Untertanen der Allianz warten in tückischem Gebiet auf ihre Rettung.",["race:Dwarf"]="Für Bronzebeard-Zwerge ist Grimesilt eine bittere Erinnerung an die Bedrohung durch die Dunkeleisenzwerge jenseits der Berge und die Gefahren für zwergische Altertümer und Archäologen in feindlichen Landen."},sec={{t="Eine umkämpfte Ausgrabung",b="Schildwachen der Dunkeleisenzwerge patrouillieren in Rußschlacks Grabungsstätte in der Sengenden Schlucht. Gelehrte aus Eisenschmiede entsandten zunächst eine Expedition, um unter den Felsen nach Relikten zu suchen. Die einheimischen Dunkeleisenzwerge vertrieben die Ausgräber und beschlagnahmten ihre Ausrüstung. Verwundet und verstreut bleiben die Mitglieder der ursprünglichen Expedition in und um die Grube gefangen."}},faq={{q="Wer gründete ursprünglich Rußschlacks Grabungsstätte?",a="Bronzebeard-Zwerge aus Eisenschmiede begannen die Ausgrabung. Ihre Mannschaft kam, um unter der Sengenden Schlucht uralte Artefakte freizulegen, doch die Dunkeleisenzwerge überfielen und vertrieben sie.",al={"wer grub in grimesilt","wer gründete rußschlacks grabungsstätte","gründer von grimesilt"}},{q="Wer kontrolliert die Grabungsstätte jetzt?",a="Der Clan der Dunkeleisenzwerge kontrolliert die Ausgrabung. Sie besetzen die Gruben und bewachen die verbliebenen Werkzeuge und das Gebiet gegen jeden Versuch Eisenschmiedes, es zurückzuerobern.",al={"wem gehört grimesilt","feinde von grimesilt","wer ist in grimesilt"}},{q="Gibt es Überlebende der ursprünglichen Mannschaft?",a="Ja. Einige Arbeiter haben überlebt, darunter der verletzte Ausgräber Dorius Stonetender, der nahe dem Boden der Grube liegt. Ein weiteres Mitglied der Mannschaft versteckt sich in einem nahe gelegenen Plumpsklo.",al={"überlebende in grimesilt","dorius stonetender","wer ist in grimesilt gefangen"}}},fp="18,166,22.310.0,50.187.0,30.159.0,47.158.0"}
P.entries["subzone:grimtotem-compound"] = {n="Truppenlager der Grimmtotem",s="Im Herzen von Feralas unterhalten die Grimmtotem zwei Lager östlich von Düsterbruch. Ihr Truppenlager dient als Stützpunkt für geheimnisvolle, zerstörerische Unternehmungen in der Region.",h="Im Herzen von Feralas unterhalten die Grimmtotem zwei Lager östlich von Düsterbruch.",kw={"truppenlager","düsterbruch","feralas","gnolle","grimmtotem","grimmlingflitzer","tauren"},ang={["faction:Alliance"]="Als Mitglied der Allianz steht Ihr Grimmtotem gegenüber, die den Night Elves und ihren Verbündeten unerbittlich feindselig gesinnt sind.",["race:Tauren"]="Als Tauren wisst Ihr vielleicht, dass die Grimmtotem Cairne Bluthuf dem Namen nach huldigen. Ihr Truppenlager zeigt ihren ungezügelten Ehrgeiz, fern der wachsamen Augen von Donnerfels."},sec={{t="Eine Bastion des schwarzen Stammes",b="Östlich von Düsterbruch sichern zwei Lager der Grimmtotem dem Clan einen Stützpunkt in Feralas. Anders als die Tauren, die Cairne Bluthuf in Donnerfels folgen, handeln sie unabhängig und begegnen Außenstehenden feindselig.\n\nIn der südlichen Hälfte halten sie aus eigenen Gründen gefangene einheimische Feendrachen in einem großen Holzkäfig. Schurken-Gnolle streifen am nördlichen Rand umher."}},faq={{q="Wer lebt im Truppenlager der Grimmtotem?",a="Der Clan der Grimmtotem lebt im Truppenlager. Diese verschwiegenen, aggressiven Tauren handeln unabhängig von den mit der Horde verbündeten Stämmen in Mulgore und sind für ihre Feindseligkeit gegenüber Außenstehenden und ihre rücksichtslosen Methoden bekannt.",al={"wer ist hier","truppenlager der grimmtotem gegner","wer kontrolliert das truppenlager der grimmtotem"}},{q="Warum sind Feendrachen im Truppenlager eingesperrt?",a="Die Grimmtotem haben einheimische Feendrachen gefangen und in einen großen Käfig im südlichen Dorf gesperrt. Warum sie die Geschöpfe festhalten, ist unbekannt.",al={"warum sind feendrachen eingesperrt","eingesperrte feendrachen","grimmtotem feendrachen"}},{q="Wo liegt das Truppenlager der Grimmtotem?",a="Das Truppenlager liegt im Herzen von Feralas, direkt östlich der uralten Ruinen der Highborne in Düsterbruch. Wilde Gnollrudel lagern in der Nähe im Nordosten.",al={"truppenlager der grimmtotem lage","wo ist das truppenlager der grimmtotem"}}},fp="18,152,28.349.0,36.195.0,45.148.0,40.139.0"}
P.entries["subzone:grizzled-den"] = {n="Der Graufelsbau",s="In Dun Morogh hausen Wendigorrudel im Graufelsbau, südwestlich von Kharanos.",h="In Dun Morogh hausen Wendigorrudel im Graufelsbau, südwestlich von Kharanos.",kw={"höhle","dun morogh","frost","der graufelsbau","kharanos","wendigo"},ang={["profession:Mining"]="Kupfervorkommen durchziehen die äußeren und inneren Tunnel des Graufelsbaus, doch Wendigos machen den Abbau dort gefährlich.",["race:Dwarf"]="Für junge zwergische Bergsteiger, die rund um Kharanos ausgebildet werden, ist die Säuberung des Graufelsbaus eine Bewährungsprobe."},sec={{t="Ein frostkalter Unterschlupf",b="Südwestlich von Kharanos schneidet sich der Graufelsbau in die schroffen Felsen von Dun Morogh. Wendigorrudel haben sich in seinen Höhlungen eingenistet. Diese aggressiven, affenähnlichen Bestien hauchen Eindringlingen Frost entgegen und schließen sich zusammen, um ihren Bau zu verteidigen. Jäger wagen sich für dichte Wendigomähnen in die Höhle, mit denen Handwerker kalte Stühle und Kutschensitze mit isolierendem Fell auskleiden."},{t="Verborgene Schätze",b="Prospektoren bauen Kupferadern in den gefrorenen Steinwänden des Graufelsbaus ab. Späher durchsuchen seine dunkleren Winkel nach weggeworfenen Schließkisten. Tiefer in den Tunneln lauern die größten und bösartigsten Raubtiere des Baus im Schatten."}},faq={{q="Wo liegt der Graufelsbau?",a="Der Graufelsbau liegt zwischen den schneebedeckten Bergkämmen von Dun Morogh, südwestlich von Kharanos.",al={"graufelsbau lage","wo ist der graufelsbau","weg zum graufelsbau"}},{q="Welche Kreaturen leben im Graufelsbau?",a="Wilde Wendigorrudel leben im Graufelsbau. Die weißpelzigen Bestien speien eisigen Frost und stürzen sich in Scharen auf Eindringlinge.",al={"was ist im graufelsbau","graufelsbau gegner","kreaturen im graufelsbau"}},{q="Warum wagen sich Leute in den Graufelsbau?",a="Jäger suchen Wendigomähnen für warme Sitzbezüge, während andere die Tunnel betreten, um Kupfer aus den Wänden abzubauen.",al={"warum zum graufelsbau","graufelsbau quests","wendigomähnen"}}},fx={["4377d186"]={q="Was ist Der altgediente Bau?",a="Der altgediente Bau ist ein weitläufiges Höhlensystem, das in den schneebedeckten Hügeln südwestlich von Kharanos in Dun Morogh versteckt liegt. Es dient als natürlicher Unterschlupf in den Bergen und ist in der gesamten Region berüchtigt für sein frostiges Inneres und die wilden Tiere, die in seinen felsigen Tiefen Schutz suchen.",al={"was ist der altgediente bau","überblick altgedienter bau","über den altgedienten bau"}},["44a06046"]={q="Ist Der altgediente Bau gefährlich?",a="Ja, er stellt eine echte Gefahr für einsame Reisende und unerfahrene Abenteurer dar. Die Höhle ist von aggressiven Wendigos befallen, die Frostzauber wirken können. Schlimmer noch, diese Bestien neigen dazu, sich zusammenzurotten, um Eindringlinge zu überwältigen, und ein besonders grausames Exemplar lauert tief in den Kavernen.",al={"wie gefährlich ist der altgediente bau","gefahr im altgedienten bau","ist der altgediente bau sicher"}}},fp="12,84,20.342.0,16.220.0,34.91.0,40.113.0,44.110.0"}
P.entries["subzone:grizzlepaw-ridge"] = {n="Grautatzengrat",s="Bären beanspruchen die rauen Hügel des Grautatzengrats südlich von Thelsamar in Loch Modan. Die örtlichen Jäger fürchten Ol' Sooty, einen gewaltigen Bären unter ihnen.",h="Bären beanspruchen die rauen Hügel des Grautatzengrats südlich von Thelsamar in Loch Modan.",kw={"bären","grautatzengrat","loch modan","ol' sooty","sooty","thelsamar"},ang={["class:Hunter"]="Als Jäger könnt Ihr auf dem Grautatzengrat wilde Tiere aufspüren und Euch Spitzenräubern wie Ol' Sooty stellen.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Bären auf dem Grat neben Thelsamar den örtlichen Gebirgsjägern und den Versorgungswegen zu schaffen machen."},sec={{t="Heimat der Bären",b="Der Grautatzengrat erhebt sich über der Straße südlich von Thelsamar, und an seinem westlichen Rand liegt das Splittersteintal. Revierverteidigende Bären bedrohen Reisende am Gebirgsrand, weshalb jene, die zwischen den Zwergensiedlungen unterwegs sind, die Baumgrenze und die felsigen Terrassen im Auge behalten. Tief im Grat lebt Ol' Sooty, ein ungewöhnlich wilder Bär, den die örtlichen Jäger fürchten."}},faq={{q="Wo liegt der Grautatzengrat?",a="Der Grautatzengrat liegt in den zentralen Hügeln von Loch Modan, direkt südlich von Thelsamar und östlich des Splittersteintals.",al={"wo liegt der grautatzengrat","lage des grautatzengrats","wie kommt man zum grautatzengrat"}},{q="Welche gefährlichen Kreaturen leben auf dem Grautatzengrat?",a="Aggressive Bären durchstreifen den Grautatzengrat. Am berüchtigtsten ist Ol' Sooty, eine außergewöhnlich große und wilde Bestie, die manchmal zum Fuß des Berges hinabstreift.",al={"bären am grautatzengrat","wer ist ol sooty","ol sooty loch modan"}}},fx={["57fe1f79"]={q="Was ist der Grautatzengrat?",a="Der Grautatzengrat ist ein raues, bergiges Gebiet in Loch Modan, das südlich von Thelsamar und östlich vom Splittersteintal aufragt. Es ist ungezähmte Zwergenwildnis, die von dichten Wäldern und felsigen Klippen dominiert wird und vor allem als Jagdrevier und Territorium gefährlicher Gebirgsbären bekannt ist.",al={"was ist der grautatzengrat","grautatzengrat lore","über den grautatzengrat"}},["09913c6a"]={q="Ist der Grautatzengrat gefährlich?",a="Für unvorsichtige Reisende ist er recht gefährlich. Der Grat wird von einem großen Rudel aggressiver Bären durchstreift. Am schlimmsten unter ihnen ist Ol' Sooty, ein berüchtigt wilder Bär, dessen Lager sich oben in den Höhen befindet und der gelegentlich zum Fuß des Tals hinunterwandert, um jeden zu zerfleischen, der seinen Weg kreuzt.",al={"wie gefährlich ist der grautatzengrat","grautatzengrat gefahr","bedrohungen im grautatzengrat"}},d9ee2216={q="Warum heißt es Grautatzengrat?",a="Der Grat verdankt seinen Namen der großen, aggressiven Population von Gebirgsbären, die seine Hänge und felsigen Höhen als ihr Territorium beanspruchen, allen voran wilde Bestien wie Ol' Sooty.",al={"namensursprung grautatzengrat","warum grautatzengrat","wie erhielt der grautatzengrat seinen namen"}}},fp="16,139,17.346.0,34.114.0,50.162.0"}
P.entries["subzone:grol-dom-farm"] = {n="Grol'doms Hof",s="An der Straße von Durotar zum Wegekreuz züchtet Grol'doms Hof Schweine im nördlichen Brachland. Kranal Fiss und seine Familie bewirtschaften das Gehöft unter ständigen Schikanen aggressiver Borstennacken.",h="An der Straße von Durotar zum Wegekreuz züchtet Grol'doms Hof Schweine im nördlichen Brachland.",kw={"brachland","feuertotem","grol'doms hof","grol'dom","kranal fiss","schweinefarm","razormane","schweine"},ang={["class:Shaman"]="Als Schamaneninitiand auf dem Pfad der Elemente kommt Ihr zu Grol'doms Hof, um die gefährlichen Riten zu bestehen, durch die Kranal Fiss Euch führt. Diese Riten lehren Euch, mit den Geistern des Feuers Zwiesprache zu halten.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr auf Grol'doms Hof sehen, welche Zähigkeit frühe Siedler brauchen, um sich im rauen, ungezähmten Brachland eine dauerhafte Lebensgrundlage aufzubauen."},sec={{t="Eine Schweinefarm in der Savanne",b="Nach der Besiedlung Durotars begann die Horde, auf Grol'doms Hof das trockene Brachland zu bewirtschaften. Kranal Fiss und seine Kinder kümmern sich um das Gehöft und züchten Schweine. Razormane-Borstennackenräuber durchstreifen die nahen Bergrücken und machen das Leben hier einsam und beschwerlich. Dennoch versorgt der Hof die aufstrebende Orc-Nation mit Nahrung."},{t="Ein Leuchtfeuer für junge Schamanen",b="Kranal Fiss versorgt auf Grol'doms Hof die Schweine und kennt die elementaren Riten. Er führt junge Schamanen durch ihre Prüfungen, weshalb Initianden der Horde auf dem spirituellen Pfad den Hof in stiller Wertschätzung halten. Suchende, die von Orgrimmar nach Westen reisen, werden regelmäßig hierhergeschickt, um zu lernen, wie sie mit den Urgeistern des Feuers Zwiesprache halten."}},faq={{q="Was ist Grol'doms Hof?",a="Grol'doms Hof züchtet Schweine im nördlichen Brachland, an der Straße zwischen Durotar und dem Wegekreuz. Dieses abgelegene Gehöft entstand nach der Gründung Orgrimmars und wird von Kranal Fiss und seinen Kindern bewirtschaftet.",al={"grol'doms hof infos","was ist dieser ort im brachland","orc-schweinefarm"}},{q="Wer lebt auf Grol'doms Hof?",a="Kranal Fiss und seine Kinder leben auf dem Hof. Sie kümmern sich um die Pferche, hüten die Schweine und verteidigen ihre karge Lebensgrundlage gegen umherstreifende Bestien und Borstennackenräuber.",al={"wer ist auf grol'doms hof","wer lebt hier","kranal fiss zuhause"}},{q="Warum kommen Schamanen zu Grol'doms Hof?",a="Kranal Fiss kennt die elementaren Riten, und Schamanen der Orcs und Tauren werden zu Beginn ihrer Ausbildung regelmäßig zu ihm geschickt. Er führt sie durch Prüfungen, damit sie sich ihren Call of Fire verdienen und das Feuertotem manifestieren können.",al={"schamane feuerquest","warum zu grol'doms hof kommen","kranal fiss schamane"}},{q="Welche Gefahren bedrohen den Hof?",a="Razormane-Borstennacken aus der umliegenden Savanne bedrängen den Hof unablässig. Ihre Überfälle bedrohen das Vieh und gefährden Kranals Familie.",al={"warum gibt es hier borstennacken","wer greift grol'doms hof an","feinde des hofes"}}},fx={["571c8690"]={q="Was ist die Geschichte von Grol'doms Hof?",a="Grol'doms Hof ist eine von mehreren Orc-Schweinefarmen, die nach der Gründung von Orgrimmar und Durotar im nördlichen Brachland errichtet wurden. Auf der Suche nach einem ehrlichen Lebensunterhalt in den trockenen Ebenen ließ sich Kranal Fiss hier mit seinen Kindern nieder, um Schweine zu züchten und unter dem Schutz der neuen Horde in Ruhe zu leben.",al={"geschichte von grol'doms hof","wie wurde grol'doms hof gegründet","was geschah bei grol'doms hof"}}},fp="13,197,28.286.0,25.306.0,22.208.0,27.160.0,37.205.0,27.142.0"}
P.entries["subzone:grom-gol-base-camp"] = {n="Basislager Grom'gol",s="Das Basislager Grom'gol hält die Stellung der Horde an der Westküste des Schlingendorntals. Kommandant Aggro'gosh führt den befestigten Außenposten im nördlichen Schlingendorntal, den Zeppeline mit Orgrimmar und Unterstadt verbinden. Dschungeltrolle und feindliche Streitkräfte der Allianz bedrohen das Lager.",h="Das Basislager Grom'gol hält die Stellung der Horde an der Westküste des Schlingendorntals.",kw={"aggro'gosh","grom'gol","gromgol","orgrimmar","steinard","schlingendorntal","unterstadt","zeppelin"},ang={["faction:Alliance"]="Als Reisender der Allianz steht Ihr in Grom'gol einer schwer befestigten Bastion der Horde gegenüber, deren Zeppelinrouten tief in die südlichen Östlichen Königreiche reichen.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr Grom'gol als sicheren Zufluchtsort und Aufmarschplatz nutzen, während Ihr die Dschungel und umkämpften Straßen des Schlingendorntals durchquert."},sec={{t="Eine Bastion im Dschungel",b="Im nordwestlichen Schlingendorntal hält Kommandant Aggro'gosh das Basislager Grom'gol. Palisaden und bewaffnete Grunzer schützen es vor Blutsichel-Kopfjägern, lauernden Naga und umherstreifenden Bestien. Das Lager hält die Versorgungswege nach Norden zu Steinard in den Sümpfen des Elends offen. Seine Wachen beobachten den Verkehr der Allianz, der vom Dämmerwald nach Süden oder von Beutebucht nach Norden zieht."},{t="Luftbrücke der Horde",b="Hölzerne Zeppelintürme machen Grom'gol zu einem wichtigen Versorgungsknotenpunkt in den Östlichen Königreichen. Goblinische Luftschiffe verkehren regelmäßig zwischen dem Lager und Orgrimmar sowie Unterstadt. Diese Luftbrücke bringt Verstärkung und Vorräte der Horde direkt ins Schlingendorntal, fernab der von der Allianz kontrollierten Straßen und der offenen See."}},faq={{q="Welchen Zweck erfüllt das Basislager Grom'gol?",a="Das Basislager Grom'gol ist der befestigte Aufmarschplatz der Horde im Schlingendorntal. Kommandant Aggro'gosh führt es, und seine Versorgungsroute nach Steinard in den Sümpfen des Elends hilft, die Interessen der Horde gegen Dschungeltrolle und Vorstöße der Allianz zu schützen.",al={"warum ist gromgol hier","gromgol zweck","was ist gromgol"}},{q="Wie reist Ihr nach Grom'gol und von dort weiter?",a="Zeppeline aus Grom'gol fliegen direkt nach Orgrimmar in Kalimdor und nach Unterstadt in Tirisfal. Ein Horst für Wind Rider verbindet das Lager mit Kargath, Steinard und Beutebucht.",al={"gromgol zeppelin","gromgol flugrouten","wie nach gromgol gelangen"}},{q="Wer führt das Basislager Grom'gol?",a="Kommandant Aggro'gosh, ein Orc, führt das Basislager Grom'gol. Er leitet seine Verteidigung gegen einheimische Trollstämme, wilde Raptoren und Späher der Allianz.",al={"gromgol anführer","wer führt gromgol","kommandant von gromgol"}},{q="Welche Gefahren bedrohen das Lager?",a="Grom'gol ist von allen Seiten bedroht. Dschungeltrolle der Blutsichel jagen an seinen Grenzen, Raptoren durchstreifen die Felder im Norden, und Soldaten der Allianz ziehen vom Dämmerwald südwärts oder von Beutebucht nordwärts.",al={"gromgol feinde","wer greift gromgol an"}}},fp="18,283,23.342.0,22.295.0,42.241.0,39.172.0,29.143.0,32.195.0"}
P.entries["subzone:grommash-hold"] = {n="Grommash Hold",s="Im Valley of Wisdom thront Grommash Hold als Thralls Sitz über den roten Klippen. Benannt zu Ehren von Grommash Hellscreams Opfer, ist die Festung das politische Herz der neuen Horde.",h="Im Valley of Wisdom thront Grommash Hold als Thralls Sitz über den roten Klippen.",kw={"etrigg","grommash hold","mannoroth","orgrimmar","thrall","thrall's fortress","valley of wisdom"},ang={["faction:Horde"]="In Grommash Hold liegt das Zentrum der Hoheitsgewalt der Horde. Hier werden Verträge geschlossen, und von ihren Hallen aus werden Feldzüge gegen Bedrohungen in ganz Kalimdor und den Östlichen Königreichen gelenkt.",["race:Orc"]="Für Orcs erinnern Grommash Hold und Mannoroths Überreste davor an Grom Hellscreams Opfer, das ihr Volk vom dämonischen Blutfluch befreite."},sec={{t="Der Sitz des Kriegshäuptlings",b="Grommash Hold erhebt sich aus den Klippen des Valley of Wisdom. Thrall empfängt in ihren Hallen Abgesandte, Bittsteller und Kriegsherren. Die dickwandigen Steinräume bleiben dämmrig und kühl, damit die Teilnehmer seiner Audienzen wachsam und besonnen bleiben. Mit erfahrenen Ratgebern wie Etrigg berät Thrall über die Verteidigung Kalimdors. Volksführer wie Vol'jin besuchen die Festung."},{t="Das Denkmal der Freiheit",b="Vor der Festung hängen Mannoroths zerschmetterte Rüstung und sein gehörnter Schädel an einem uralten Baum. Das Denkmal ehrt Grom Hellscream, der sein Leben gab, um den Grubenlord in Eschental zu erschlagen. Sein Opfer befreite die Orcs vom dämonischen Blutfluch. Die Überreste warnen auch vor einer Rückkehr zu rücksichtsloser Wildheit."}},faq={{q="Wer befindet sich in Grommash Hold?",a="Kriegshäuptling Thrall hält in Grommash Hold mit Anführern und Beratern der Horde Hof. Zu ihnen gehören der orcische Älteste Etrigg, der Dunkelspeer-Anführer Vol'jin und der Krieger Nazgrel.",al={"wer ist in der festung","wer lebt in grommash hold","wer herrscht hier"}},{q="Warum heißt die Festung Grommash Hold?",a="Grommash Hold verdankt ihren Namen Grommash 'Grom' Hellscream, dem legendären Häuptling des Kriegshymnenklans. Im Dritten Krieg tötete Grom den Grubenlord Mannoroth unter Einsatz seines eigenen Lebens und befreite die Orcs aus dämonischer Knechtschaft.",al={"warum grommash hold","wer war grommash","nach wem benannt"}},{q="Was sind das für riesige Knochen vor der Festung?",a="Der riesige Schädel und die Rüstung vor der Festung gehören Mannoroth, dessen Blut die Orcs auf Draenor erstmals versklavte. Die Überreste wurden aus Eschental hergebracht und an einem Baumstamm angebracht, um die Freiheit der Horde zu ehren.",al={"dämonenschädel draußen","mannoroths schädel","knochen davor"}},{q="Warum nennen manche Stadtschilder sie Thrall's Fortress?",a="Orcische Wachen und ältere Wegweiser nennen das Bauwerk Thrall's Fortress, nach dem Kriegshäuptling, der darin Hof hält.",al={"thrall's fortress","hold oder fortress"}}},fx={["84f3c4ab"]={q="Ist das Grommash Hold gefährlich?",a="Wenn Ihr der Horde gegenüber loyal seid, ist das Grommash Hold absolut sicher und Ihr seid willkommen, bei seinen Anführern vorstellig zu werden. Für Mitglieder der Allianz ist es einer der tödlichsten Orte auf Kalimdor. Schwer bewacht von Elite-Kor'kron-Wachen und beherbergt Wachhäuptling Thrall höchstpersönlich neben erfahrenen Champions, droht jedem Eindringling die sofortige und gnadenlose Hinrichtung, sobald er das Tal der Weisheit betritt.",al={"ist es sicher im grommash hold","gefahr im grommash hold","kann die allianz grommash hold betreten"}},ce374a3d={q="Was geschah in Grommash Hold?",a="Die Festung wurde zeitgleich mit Orgrimmar im Valley of Wisdom errichtet, um als Sitz der neuen Horde zu dienen. Thrall empfing hier während der Gründung Durotars den Halb-Oger und Bestienmeister Rexxar, und gemeinsam verteidigten sie das entstehende Reich. In ihren kalten Steinhallen haben Thrall und seine Berater seit dem Ende des Dritten Krieges die Fraktion regiert, die Verteidigung gegen herannahende Bedrohungen geplant und Gesandte verbündeter Stämme und Nationen empfangen.",al={"geschichte von grommash hold","grommash hold ereignisse","was geschah in grommash hold"}}},fp="13,167,24.354.0,23.303.0,28.165.0,30.233.0,43.206.0,49.122.0"}
P.entries["subzone:grove-of-the-ancients"] = {n="Der Hain der Uralten",s="Naturgeister und Kaldorei versammeln sich im Hain der Uralten, wo Onu, ein Urahne der Lehren, Wache hält. Alte Tempelruinen stehen am Wildbend im Südosten der Dunkelküste.",h="Naturgeister und Kaldorei versammeln sich im Hain der Uralten, wo Onu, ein Urahne der Lehren, Wache hält.",kw={"urahne der lehren","kreis der uralten","dunkelküste","der hain der uralten","onu","der wildbend"},ang={["class:Druid"]="Als Druide könnt Ihr an dieser verehrten Zuflucht Weisheit bei Onu, dem Urahnen der Lehren, und den Geistern des Waldes suchen.",["race:NightElf"]="Uralte Tempelruinen und Naturgeister umgeben den Hain, eine ehrfurchtgebietende Erinnerung an den langen Einklang der Kaldorei mit dem Land."},sec={{t="Zuflucht am Wildbend",b="Alte Tempelsteine umgeben den Hain der Uralten im Südosten der Dunkelküste. Der Wildbend fließt durch sein Herz und bietet Zuflucht vor einer unruhigen Küste. Naturgeister und Kaldorei versammeln sich hier als Kreis der Uralten. Gemeinsam wahren sie das Gleichgewicht des Waldes."},{t="Hüter und Wächter",b="Onu, ein Urahne der Lehren, beobachtet das wechselnde Schicksal des Landes und bietet Reisenden Weisheit. Umherziehende Händler und schlummernde Druiden ruhen unter den Ästen. Im Südosten behaupten Furbolgs in ihren Lagern ihr Revier. Schildwachen und Druiden der Allianz überwachen von diesem Grenzaußenposten aus die südlichen Gebiete der Dunkelküste."}},faq={{q="Wo liegt der Hain der Uralten?",a="Der Hain der Uralten liegt im Südosten der Dunkelküste, an den Ausläufern der Berge nahe dem Wildbend.",al={"hain der uralten lage","wo liegt der hain der uralten","onu standort"}},{q="Wer ist Onu?",a="Onu ist ein Urahne der Lehren, der im Hain lebt. Er wacht über die südöstlichen Wälder und berät Druiden und Reisende, die daran arbeiten, das Gleichgewicht der Dunkelküste wiederherzustellen.",al={"wer ist onu","urahne im hain der uralten","baumkerl dunkelküste"}},{q="Was ist der Kreis der Uralten?",a="Der Kreis der Uralten ist eine Versammlung mächtiger Naturgeister und uralter Treants, die im Hain zusammenkommen, um sich auszutauschen, Wissen zu teilen und das Wohlergehen der wilden Lande zu besprechen.",al={"kreis der uralten","treffen der uralten dunkelküste"}},{q="Gibt es Gefahren in der Nähe des Hains?",a="Feindselige Wildtiere und Lager revierverteidigender Furbolgs befinden sich jenseits des Flusses und südöstlich des Hains.",al={"gefahren im hain","ist der hain sicher","monster nahe dem hain"}}},fx={b540280c={q="Was ist die Grove of the Ancients?",a="Die Grove of the Ancients ist eine heilige Nachtelfenruine, die entlang des Wildbend in der südöstlichen Dunkelküste liegt. Um die zerfallenden Überreste eines alten Tempels erbaut, dient sie als abgelegenes Heiligtum, in dem sich der Zirkel der Ältesten versammelt, bewacht von verehrten Baumwächtern und schlummernden Hütern der Natur.",al={"grove of the ancients","was ist die grove of the ancients","über die grove of the ancients"}},a4149ac4={q="Warum heißt die Grove of the Ancients so?",a="Das Heiligtum verdankt seinen Namen sowohl den massiven, empfindungsfähigen Uralten, die hier leben, als auch dem alten Nachtelfenerbe, das tief in seinem Boden verwurzelt ist. Als Treffpunkt für den Zirkel der Ältesten und Heimat des ehrwürdigen Uralten der Lehren, Onu, steht es als ein dauerhaftes Denkmal für die urzeitlichen Hüter des Waldes.",al={"warum grove of the ancients","wie erhielt sie ihren namen","bedeutung des namens grove of the ancients"}},f8aa7b2c={q="Warum ist die Grove of the Ancients eine Ruine?",a="Die in der Lichtung verstreuten Steinstrukturen sind die Überreste eines alten Nachtelfentempels, der über Jahrtausende verfiel. Während die Architektur längst den Elementen und dem vordringenden Wald gewichen ist, bleibt das Land zutiefst heilig und wird aktiv von Naturgeistern gepflegt, anstatt in Stein wiederaufgebaut zu werden.",al={"warum ist die grove of the ancients eine ruine","tempelruinen der grove of the ancients","wer zerstörte die lichtung"}}},fp="21,184,25.275.0,20.323.0,35.113.0,11.160.0,31.177.0,33.102.0"}
P.entries["subzone:growless-cave"] = {n="Eisfellhöhle",s="Bergyetis durchstreifen die Eisfellhöhle im Alteracgebirge, während ihre Flame of Uzel Helculars finstere Absicht gegenwärtig hält.",h="Bergyetis durchstreifen die Eisfellhöhle im Alteracgebirge, während ihre Flame of Uzel Helculars finstere...",kw={"alterac","flame of uzel","frostmaw","eisfellhöhle","helcular","skhowl","yeti"},ang={["class:Mage"]="Die Überreste der Flame of Uzel warnen Magier vor der Gefahr, die Zauberkunst der Kirin Tor für Nekromantie einzusetzen.",["race:Undead"]="Für Verlassene, die Helculars Rache unterstützen, hat die Eisfellhöhle eine düstere Bedeutung. Seine dunklen Riten und Relikte bleiben über das gefallene Alterac verstreut."},sec={{t="Ein Bau voller Bestien und dunkler Magie",b="Bergyetis durchstreifen die Eisfellhöhle in den schroffen Höhen über Alteracs Ausläufern. Reisende meiden ihren Eingang an den tückischen Hängen, besonders wenn Skhowl, ein berüchtigter Yeti, draußen umherstreift. Doch die Bestien sind nicht die einzige Gefahr der Höhle.\n\nIm Inneren steht die Flame of Uzel, eine arkane Feuerschale, die der Menschenmagier Helcular hinterlassen hat. Vor seinem Tod wollte Helcular den Scheiterhaufen in einem dunklen Ritual nutzen, um ein Lich zu werden. Seine unheilvolle Wärme lockte einst Frostmaw, ein gewaltiges Raubtier, aus den gefrorenen Ödnissen an."}},faq={{q="Welche Kreaturen leben in der Eisfellhöhle?",a="Wilde, in Alterac heimische Bergyetis leben in der Eisfellhöhle. Skhowl, ein gefährlicher und seltener Yeti, streift manchmal direkt vor ihrem Eingang umher.",al={"wer lebt hier","eisfellhöhle gegner","was ist in der eisfellhöhle"}},{q="Was ist die Flame of Uzel?",a="Die Flame of Uzel ist ein zeremonieller Scheiterhaufen, den Helcular errichtete, ein ehemaliger Magier aus Dalaran, der zum Nekromanten wurde. Er schuf ihn für ein verbotenes Ritual, das ihn in einen unsterblichen Lich verwandeln sollte.",al={"flame of uzel","scheiterhaufen in der eisfellhöhle","helcular flamme"}},{q="Wer ist Frostmaw?",a="Frostmaw ist ein gewaltiger, außergewöhnlich wilder Yeti, der die Gipfel Alteracs durchstreift. Das Verbrennen von frischem Fleisch auf der Flame of Uzel lockte die gefräßige Bestie einst zur Höhle.",al={"frostmaw yeti","frostmaw"}},{q="Warum wagen sich Reisende hierher?",a="Abenteurer trotzen der Höhle, um gefährliche Yetis wegen ihrer Felle zu jagen oder den verbliebenen nekromantischen Artefakten nachzuspüren, die mit Helculars Vermächtnis in Alterac verbunden sind.",al={"warum zur eisfellhöhle","eisfellhöhle quests"}}},fx={ae5edb73={q="Was ist die Eisfellhöhle?",a="Die Eisfellhöhle ist eine Höhle, die in die eisigen Hänge des Alteracgebirges gegraben wurde. Fernab zivilisierter Siedlungen dient sie hauptsächlich als Bau für wilde Gebirgsyetis, geschützt vor den brutalen Winden des Hochlandes.",al={"was ist die eisfellhöhle","infos zur eisfellhöhle","über die eisfellhöhle"}},["719f5ae4"]={q="Was geschah in der Eisfellhöhle?",a="In der Vergangenheit wählte der ehrgeizige menschliche Magier Helcular diesen abgelegenen Bau, um die Flamme von Uzel zu errichten. Er beabsichtigte, dieses dunkle zeremonielle Scheiterhaufen als Instrument für seine nekromantischen Rituale zu nutzen, um zum Lich aufzusteigen.",al={"geschichte der eisfellhöhle","was geschah hier","helcular eisfellhöhle"}},["1fe34e74"]={q="Ist die Eisfellhöhle gefährlich?",a="Ja. Die Höhle wimmelt von bösartigen Gebirgsyetis, die ihr Lager aggressiv verteidigen. Gelegentlich schleicht die wandernde Bestie Skhowl direkt vor ihrem Eingang herum, und der gewaltige Yeti Frostmaw soll ebenfalls häufig in der Höhle anzutreffen sein.",al={"wie gefährlich ist die eisfellhöhle","gefahr in der eisfellhöhle","ist die eisfellhöhle sicher"}}},fp="13,120,30.483.0,37.140.0,26.184.0,16.160.0,33.153.0"}
P.entries["subzone:gryphon-roost"] = {n="Gryphon Roost",s="Greifen tragen Reisende von Sturmwinds östlichen Wehrmauern durch die Östlichen Königreiche. Der menschliche Greifenmeister Dungar Longdrink betreut den Horst neben dem Handelsdistrikt.",h="Greifen tragen Reisende von Sturmwinds östlichen Wehrmauern durch die Östlichen Königreiche.",kw={"dungar longdrink","flugmeister","gryphon roost","flug ab sturmwind","der handelsdistrikt","wildhammer"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr Botschaften auf dem Luftweg von Sturmwind in Gebiete wie Westfall und das Rotkammgebirge bringen. Diese Flüge helfen dabei, die dortigen Maßnahmen abzustimmen.",["race:Dwarf"]="Als Zwerg seht Ihr, wie die lange Tradition Eures Volkes im Greifenreiten nach Sturmwind getragen wird. Abgerichtete Greifen verbinden die Hauptstadt der Menschen mit Khaz Modan."},sec={{t="Tor zu den Lüften",b="Dungar Longdrink organisiert Flüge nach Eisenschmiede, Seenhain, Späherkuppe und zu weiteren Garnisonen und Siedlungen der Allianz. Der Horst verbindet Sturmwind mit diesen entlegenen Stützpunkten. Seine abgerichteten Greifen stehen für die bevorstehenden Reisen bereit."},{t="Ein Hauch vom Horst",b="Greifen und ihre Betreuer bringen ein Stück Tradition des Hinterlands nach Sturmwind. Der Wildhammer-Clan ehrt Greifen seit Langem als Gefährten. Während des Zweiten Krieges brachten sie Luftkrieg und Lufttransport in die gesamte Allianz. Leder, Futter und frische Winde verleihen dem Horst inmitten des städtischen Mauerwerks die Atmosphäre eines Grenzlands."}},faq={{q="Wo liegt der Gryphon Roost in Sturmwind?",a="Der Gryphon Roost liegt auf Sturmwinds östlichen Wehrmauern und ist über eine Treppe vom Handelsdistrikt aus erreichbar. Von dort überblickt er die Kanäle zwischen dem Handelsdistrikt und der Altstadt.",al={"wo ist der horst","standort des flugmeisters in sturmwind","gryphon roost finden"}},{q="Wer verwaltet die Flüge des Horsts?",a="Dungar Longdrink, ein menschlicher Flugmeister, verwaltet die Flüge des Horsts. Er organisiert Flugrouten und vermietet abgerichtete Greifen an Reisende, die zu verbündeten Siedlungen auf dem ganzen Kontinent aufbrechen.",al={"wer ist der flugmeister","flugmeister von sturmwind","dungar longdrink"}},{q="Warum betreiben Zwerge den Horst in einer Menschenstadt?",a="Dungar Longdrink, Sturmwinds Flugmeister, ist ein Mensch. Die Wildhammer-Zwerge pflegen eine lange Tradition des Greifenreitens, während Dungar die Flüge des Horsts verwaltet.",al={"warum zwerge im horst von sturmwind","wildhammer in sturmwind","greifen der zwerge"}},{q="Wohin können die Greifen von hier aus fliegen?",a="Der Horst verbindet Sturmwind mit Zielen der Allianz wie Späherkuppe, Seenhain, Dunkelhain und Eisenschmiede. Weitere Routen führen zu Siedlungen in den gesamten Östlichen Königreichen.",al={"flugrouten ab sturmwind","wohin fliegen greifen","flugverbindungen des horsts"}}},fx={c47c3c58={q="Was ist der Gryphon Roost?",a="Der Gryphon Roost ist der Luftverkehrsknotenpunkt von Sturmwind, der direkt neben dem geschäftigen Handelsdistrikt liegt. Er dient sowohl als Stall als auch als Horst für die Flugreittiere des Königreichs und ermöglicht es Boten, Soldaten und Reisenden, an Bord ausgebildeter Greifen schnell durch die Gebiete der Allianz zu reisen.",al={"was ist der gryphon roost","zweck des gryphon roost","sturmwind gryphon roost"}},["4cbfa62c"]={q="Ist der Gryphon Roost gefährlich?",a="Überhaupt nicht. Der Horst liegt tief im befestigten Herzen von Sturmwind, gut geschützt von Stadtwachen. Die hier untergebrachten Greifen sind gründlich gezähmt und an die Menschenmengen der Reisenden gewöhnt.",al={"ist der gryphon roost sicher","gefahren am gryphon roost","bedrohungen am gryphon roost"}},["5a6ce60b"]={q="Warum heißt es Gryphon Roost?",a="Die Anlage verdankt ihren direkten Namen ihrem Zweck: ein dedizierter Horst und Nistplatz für die geflügelten Greifen der Stadt, wo die Bestien zwischen langen Überlandflügen ausruhen, fressen und nisten können.",al={"warum heißt es gryphon roost","namensursprung gryphon roost","bedeutung von gryphon roost"}}},fp="13,170,20.226.0,20.319.0,48.181.0,32.182.0,50.164.0,37.172.0"}
P.entries["subzone:gunther-s-retreat"] = {n="Gunthers Zufluchtsort",s="Auf einer Insel im Blendwassersee birgt Gunthers Zufluchtsort einen abtrünnigen Totenbeschwörer. Gunther Arkanus befreite sich durch schiere Willenskraft von der Geißel, doch er traut keinem Fremden und hält untote Diener nahe seinem Lager.",h="Auf einer Insel im Blendwassersee birgt Gunthers Zufluchtsort einen abtrünnigen Totenbeschwörer.",kw={"blendwassersee","gunther arkanus","gunthers zufluchtsort","lich","lillith's dinner table","tirisfal","untoter"},ang={["class:Mage"]="Als Magier erkennt Ihr vielleicht Gunthers seltene Leistung: Sein magischer Wille brach den geistigen Griff des Lichkönigs ohne fremde Hilfe.",["race:Undead"]="Als Untoter teilt Gunther Arkanus das Schicksal der Verlassenen: frei vom Lichkönig, doch misstrauisch gegenüber einer Welt, die seiner Ansicht nach weiterhin der Geißel hörig ist."},sec={{t="Ein Einsiedler im Blendwassersee",b="Nebel hängt über dem Blendwassersee, wo untote Wachen Gunther Arkanus' einsames Lager bewachen. Im Untod erweckt, meisterte Gunther die arkanen Künste und riss seine Seele ohne Hilfe aus dem Griff des Lichkönigs.\n\nEr misstraut jedem und glaubt, dass die durch Lordaeron wandernden Untoten weiterhin Marionetten der Geißel sind. So zog sich Gunther auf die Insel zurück, um sein Handwerk in Frieden auszuüben. Seine Zombiewachen greifen jeden an, der das Wasser überquert."}},faq={{q="Wer lebt an Gunthers Zufluchtsort?",a="Gunther Arkanus, ein Totenbeschwörer, lebt auf der Insel. Er befreite sich aus eigener Kraft von der Herrschaft des Lichkönigs, und untote Knechte bewachen sein Lager.",al={"gunther insel","wer ist auf der insel","herr von gunthers zufluchtsort"}},{q="Warum sind die Untoten auf der Insel feindselig?",a="Gunther Arkanus glaubt, dass alle anderen Untoten in Tirisfal weiterhin von der Geißel versklavt sind. Er schätzt seine Unabhängigkeit, weshalb seine Diener jeden angreifen, der sich der Insel nähert.",al={"warum greift gunther an","warum feindselig","gehört gunther zur geißel"}},{q="Steht Gunther auf der Seite der Verlassenen?",a="Zunächst hält Gunther sich von den Verlassenen fern, obwohl auch er ein Untoter mit freiem Willen ist. Die Machthaber in Unterstadt wollen beweisen, dass sie dem Griff des Lichkönigs entkommen sind, und ihn für seine Talente anwerben.",al={"ist gunther in der horde","gunther verlassene","gunther unterstadt"}},{q="Was ist das kleine Eiland südwestlich des Zufluchtsorts?",a="Ein winziges, namenloses Eiland liegt unmittelbar südwestlich von Gunthers Zufluchtsort. Es ist als Lillith's Dinner Table bekannt, eine unheimliche Landmarke im Blendwassersee.",al={"lillith dinner table","kleine insel bei gunther","tischinsel"}}},fx={dc3ef5e2={q="Was ist Gunthers Zufluchtsort?",a="Gunthers Zufluchtsort ist eine einsame Insel im Blendwassersee im zentralen Tirisfal. Von umliegenden Gewässern geschützt, dient die Insel als abgelegenes Heiligtum von Gunther Arkanus, einem mächtigen, freiwilligen Lich. Vom Rest von Lordaeron abgeschnitten, wird das Gelände von schlurfenden untoten Dienern patrouilliert, die ihren zurückgezogen lebenden Meister bewachen.",al={"was ist gunthers zufluchtsort","gunthers zufluchtsort lore","insel im blendwassersee"}},["2d8f9787"]={q="Ist Gunthers Zufluchtsort gefährlich?",a="Ja, es ist sehr gefährlich, sich unvorbereitet zu nähern. Gunther Arkanus glaubt fälschlicherweise, dass alle anderen Untoten in Lordaeron gedankenlose Sklaven der Geißel sind. Um sein Heiligtum zu schützen, befiehlt er seinen Zombie-Schergen, jeden gewaltsam anzugreifen, der einen Fuß auf die Ufer der Insel setzt.",al={"ist gunthers zufluchtsort gefährlich","ist gunthers zufluchtsort sicher","gefahr gunthers zufluchtsort"}},["721e4715"]={q="Warum heißt es Gunthers Zufluchtsort?",a="Die Insel hat ihren Namen von Gunther Arkanus, dem freiwilligen Lich, der den Blendwassersee zu seinem privaten Rückzugsort machte. Nachdem er sich abgespalten und seine Unabhängigkeit im Tod bewahrt hatte, zog sich Gunther hierher zurück, um der Reichweite der Geißel zu entkommen und sich von der Außenwelt abzuschotten.",al={"warum heißt es gunthers zufluchtsort","namensursprung gunthers zufluchtsort","wer benannte gunthers zufluchtsort"}}},fp="17,204,29.425.0,31.146.0,41.172.0,37.200.0,49.141.0"}
P.entries["subzone:gurubashi-arena"] = {n="Arena der Gurubashi",s="Im südlichen Schlingendorntal versammeln sich Piraten und umherziehende Raufbolde in der Arena der Gurubashi. In ihrem uralten Steinring kämpfen sie um verschlossene Schatztruhen.",h="Im südlichen Schlingendorntal versammeln sich Piraten und umherziehende Raufbolde in der Arena der Gurubashi.",kw={"arena","wettlauf um beute","truhe","gurubashi","short john mithril","schlingendorntal","die große arena"},ang={["class:Warrior"]="Als Krieger stellt Ihr auf diesem Sand Euer Kampfgeschick auf die Probe. Die große Kriegspolitik spielt keine Rolle mehr, und persönliche Zähigkeit und Überlebenswille entscheiden den Kampf.",["race:Troll"]="Als Troll betretet Ihr heiligen Boden, ein Denkmal des alten Gurubashi-Imperiums. Einst vergossen Champions auf diesem Sand ihr Blut."},sec={{t="Ein blutiges Vermächtnis",b="Bevor Menschen oder Orcs ins Schlingendorntal kamen, errichtete das Trollimperium der Gurubashi die Arena der Gurubashi, auch Große Arena genannt. Sie ehrte ihre kriegerische Stärke. In uralten Zeiten kämpften Champions auf ihrem Sand bis zum Tod, bis Trollblut den Boden schlüpfrig machte."},{t="Der Wettlauf um Beute",b="Das Gurubashi-Imperium ist in verfeindete Stämme zerfallen, doch noch immer wird in der Arena Blut vergossen. Heute versammeln sich gesetzlose Freibeuter und Raufbolde zu einem anderen Spektakel. Short John Mithril, ein Pirat, beaufsichtigt das Gelände.\n\nAlle paar Stunden wird eine Truhe voller geraubter Beute in die Mitte des Rings geschleppt. Jeder, der den Boden der Arena betritt, wird zum Freiwild. Fraktionszugehörigkeiten spielen keine Rolle mehr, und jeder Kämpfer muss gegen alle anderen antreten, um den Preis zu erreichen."}},faq={{q="Wer hat die Arena der Gurubashi erbaut?",a="Das Gurubashi-Imperium erbaute die Arena vor Jahrhunderten, als es über die südlichen Regionen der Östlichen Königreiche herrschte. Das gewaltige Stadion war Schauplatz tödlicher Kampfprüfungen und uralter Trollrituale zu Ehren der Loa.",al={"wer erbaute die arena der gurubashi","ursprung der arena","geschichte der trollarena"}},{q="Warum wird hier heute gekämpft?",a="Die örtlichen Piraten nutzen die Arena für gesetzeswidrige Unterhaltung. Alle paar Stunden bringt ein Piratenkapitän eine Schatztruhe in die Mitte der Sandfläche, und jeder, der den Ring zu betreten wagt, kann darum kämpfen.",al={"warum bei den gurubashi kämpfen","gurubashi-truhe","geschichte des wettlaufs um beute"}},{q="Wer ist Short John Mithril?",a="Short John Mithril ist der Pirat, der die Arena und ihre regelmäßigen Truhenlieferungen beaufsichtigt. Er belohnt Kämpfer, die die Schlägereien überleben und seine Arenaschätze bergen.",al={"short john mithril","aufseher der arena"}},{q="Warum können mich Mitglieder meiner eigenen Fraktion hier angreifen?",a="Sobald Ihr den Sand der Arena betretet, sind Fraktionsverträge und militärische Bündnisse außer Kraft gesetzt. Nur jene, die in Eurer unmittelbaren Kampfgruppe an Eurer Seite kämpfen, bleiben von Eurer Klinge verschont.",al={"warum kämpft bei den gurubashi jeder gegen jeden","angriffe auf verbündete bei den gurubashi","pvp-regeln der arena"}}},fp="15,162,17.266.0,13.440.0,30.205.0,29.199.0,26.167.0,49.179.0"}
P.entries["subzone:haldarr-encampment"] = {n="Lager der Haldarr",s="Im westlichen Azshara halten Haldarr-Satyrn einen verdorbenen Außenposten nordöstlich des Shadowsong-Schreins und südwestlich von Valormok. Ihr Lager verseucht uralte Elfenruinen, und die verletzte Nachtelfen-Schildwache Keldara Sunblade liegt unter ihnen.",h="Im westlichen Azshara halten Haldarr-Satyrn einen verdorbenen Außenposten nordöstlich des Shadowsong-Schreins...",kw={"azshara","lager","haldarr","keldara sunblade","satyr","shadowsong-schrein","valormok"},ang={["faction:Horde"]="Unmittelbar südwestlich von Valormok bedroht dieses dicht bevölkerte Dämonennest die Späher und Nachschublinien der Horde, die über Azsharas Klippen vordringen.",["race:NightElf"]="Für die Kaldorei bleiben die Haldarr-Satyrn eine beschämende Erinnerung daran, wie die uralten Hochgeborenen dem dämonischen Wahnsinn verfielen."},sec={{t="Ein Hort der Dämonenbrut",b="Zerbrochene Steine kennzeichnen das Lager der Haldarr-Satyrn im westlichen Azshara. Diese entstellten Kreaturen stammen von den Hochgeborenen ab und wurden während der Zerschlagung durch dämonische Verderbnis verflucht. Sie jagen und drangsalieren jeden, der die herbstlichen Wälder durchquert. Ihre dicht bevölkerte Siedlung bedroht die Truppen der Horde im nahen Valormok und die schwindenden Reihen der Nachtelfen-Schildwachen, die über die Region wachen."},{t="Die gefangene Schildwache",b="Schildwache Keldara Sunblade liegt verletzt unter den Satyrn, tief im feindlichen Gebiet. Warum sie dort bleibt, ist nicht überliefert."}},faq={{q="Was ist das Lager der Haldarr?",a="Haldarr-Satyrn beherrschen eine verdorbene Siedlung im westlichen Azshara, nordöstlich des Shadowsong-Schreins und südwestlich von Valormok.",al={"geschichte des lagers der haldarr","was ist haldarr","wer lebt im lager der haldarr"}},{q="Wer sind die Haldarr?",a="Die Haldarr sind eine bösartige Sekte von Satyrn, die in Azshara leben. Wie alle Satyrn stammen sie von uralten Nachtelfen ab, die während des War of the Ancients dämonische Pakte eingingen. Ein Fluch verwandelte sie in ziegenbeinige Unholde, die dem fortwirkenden Willen der Brennenden Legion dienen.",al={"haldarr-satyrn","wer sind die satyrn hier"}},{q="Wer ist Schildwache Keldara Sunblade?",a="Schildwache Keldara Sunblade ist eine verwundete Nachtelfen-Schildwache im Lager der Haldarr, umgeben von feindseligen Satyrn. Warum sie dort ist, ist nicht überliefert.",al={"keldara sunblade","verletzter nachtelf","wer ist die gefangene hier"}},{q="Warum ist dieses Lager für Reisende in der Nähe gefährlich?",a="Aggressive Satyrn drängen sich im Lager und bedrohen die umliegenden Wege. Sie gefährden die von Valormok ausgehenden Unternehmungen der Horde und alle umherziehenden Späher in der Gegend.",al={"ist haldarr gefährlich","warum haldarr säubern"}}},fp="18,226,20.363.0,21.121.1,31.123.0,20.269.0,33.153.0,47.151.0"}
P.entries["subzone:hall-of-arms"] = {n="Hall of Arms",s="Im Military Ward von Eisenschmiede macht die Hall of Arms die Streitkräfte der Stadt kampfbereit. Der Kommandostab beaufsichtigt die Truppen, während Krieger und Jäger trainieren und Maschinen für den Krieg vorbereitet werden.",h="Im Military Ward von Eisenschmiede macht die Hall of Arms die Streitkräfte der Stadt kampfbereit.",kw={"kampfmeister","zwergenarmee","flugmaschinen","hall of arms","eisenschmiede","military ward","dampfpanzer"},ang={["class:Warrior"]="Als Krieger findet Ihr in der Hall of Arms zwergische Waffenknechte und Veteranen, die Euch unterweisen und als Kampfmeister führen.",["race:Dwarf"]="Als Zwerg könnt Ihr in der Hall of Arms sehen, wie Khaz Modan militärische Disziplin und mechanischen Erfindergeist vereint. Panzer und Flugstaffeln schützen das Bergkönigreich."},sec={{t="Herz des Bergarsenals",b="Die Hall of Arms befehligt die Streitkräfte von Eisenschmiede von der südöstlichen Ecke des Military Ward aus. Erfahrene Ausbilder schulen dort Krieger und Jäger, während die Anlage Kriegsmaschinen lagert und für den Einsatz bereitstellt. Dampfpanzer werden für die Schlachtfelder der Allianz zusammengebaut und gewartet. Gyrokopter und Flugmaschinen werden auf industriellen Förderbändern durch Schächte in der Höhlendecke transportiert und starten dann zum darüber liegenden Flugplatz von Eisenschmiede."}},faq={{q="Welchem Zweck dient die Hall of Arms?",a="Die Hall of Arms befehligt die Streitkräfte von Eisenschmiede. Sie bildet Krieger und Jäger aus und lagert, wartet und entsendet Kriegsmaschinen wie Dampfpanzer und Gyrokopter.",al={"was ist die hall of arms","aufgabe der hall of arms","warum gibt es die hall of arms"}},{q="Wohin fliegen die Flugmaschinen, die durch die Decke starten?",a="Förderanlagen transportieren Flugmaschinen durch Schächte in der Decke zum Flugplatz von Eisenschmiede an den Berghängen darüber. Dieser Schlot ist neben den Haupttoren einer der wenigen direkten Ausgänge aus dem Berg.",al={"deckenschacht eisenschmiede","flugmaschinentunnel","wohin fliegen die gyrokopter"}},{q="Wer bildet im Inneren der Halle aus?",a="Krieger- und Jägerausbilder unterrichten in der Hall of Arms. Kampfmeister der Allianz organisieren außerdem Truppenbewegungen und Rekrutierungen für Fronten auf dem ganzen Kontinent.",al={"ausbilder in der hall of arms","wer unterrichtet hier"}},{q="Wo liegt die Hall of Arms?",a="Die Hall of Arms steht im hinteren Teil des Military Ward von Eisenschmiede, im südöstlichen Viertel der Stadt.",al={"lage der hall of arms","weg zur hall of arms"}}},fx={b2a6f890={q="Was ist die Hall of Arms?",a="Die Hall of Arms dient als Command Center und primäres Hauptquartier der militärischen Stärke von Eisenschmiede. Sie befindet sich im Military Ward der Bergstadt und fungiert als lebenswichtiges Arsenal, Trainingskaserne und mechanisches Depot, wo zwergische Belagerungsmaschinen und Flugmaschinen gebaut, gewartet und für den Krieg in der gesamten Allianz bereitgestellt werden.",al={"was ist die hall of arms","infos zur hall of arms","über die hall of arms"}},db189d23={q="Ist die Hall of Arms gefährlich?",a="Nicht für Bürger und Verbündete von Eisenschmiede. Während sie mit zwergischen Waffen, Belagerungsmaschinen und schwer bewaffneten Truppen gespickt ist, ist sie eine der sichersten Bastionen im Königreich. Nur diejenigen, die dumm genug sind, die Stadt zu bedrohen oder die Allianz herauszufordern, müssen die darin versammelte Feuerkraft fürchten.",al={"ist die hall of arms sicher","gefahr in der hall of arms","gefahr hall of arms"}},["15a89202"]={q="Warum wird sie Hall of Arms genannt?",a="Der Komplex verdient seinen Namen, da er als zentrales Arsenal und militärisches Herz des Königreichs dient. Es ist das Depot, in dem Eisenschmiede seine Waffen sammelt – von persönlichen Waffen und Rüstungen, die zur Ausbildung von Kriegern und Jägern verwendet werden, bis hin zu schweren mechanisierten Kriegsmaschinen wie Dampfpanzern und Gyrokoptern.",al={"warum heißt die hall of arms so","ursprung des namens hall of arms","bedeutung der hall of arms"}}},fp="12,190,31.426.0,40.172.0,58.211.0,40.169.0,34.106.0"}
P.entries["subzone:hall-of-arms-northshire"] = {n="Hall of Arms",s="Die Hall of Arms ist der martialische Flügel der Abtei von Nordhain, die sich südlich der Haupthalle befindet. Hier drillen erfahrene Ausbilder die neuesten Rekruten der Sturmwind-Armee in den Künsten von Schwert, Schild und heiligem Kampf.",h="Die Hall of Arms ist der martialische Flügel der Abtei von Nordhain, die sich südlich der Haupthalle befindet.",kw={"wald von elwynn","hall of arms","abtei von nordhain","nordhaintal","paladin-ausbilder","stormwind-armee","krieger-ausbilder"},ang={["class:Paladin"]="Die Hall of Arms gleicht heilige Hingabe mit martialischer Entschlossenheit aus und bietet angehenden Paladinen ihre grundlegende Ausbildung im Führen des Lichts neben dem martialischen Waffengebrauch.",["class:Warrior"]="Für menschliche Krieger, die ihren Dienst antreten, ist dies der Flügel, in dem Ihr Eure allerersten Lektionen in Haltung, Waffenhandhabung und der martialischen Disziplin der Sturmwind-Armee erhaltet."},sec={{t="Grundlagen der Wache",b="Während die Kleriker und Gelehrten auf der anderen Seite des Innenhofs im Bibliotheksflügel über alten Folianten brüten, hallt die Hall of Arms wider vom Klirren stumpfen Stahls und dem schweren Rhythmus martialischer Ausbildung. Diese Kammer befindet sich an der Südseite der Abtei von Nordhain und dient als primäre Ausbildungsstation für unerfahrene menschliche Kämpfer und gläubige Anwärter, die für die Sturmwind-Armee zu den Waffen greifen. Hier lehren erfahrene Kampfausbilder und Paladin-Mentoren die grundlegenden Haltungen, Disziplinen und Fundamente, die erforderlich sind, um den Wald von Elwynn gegen eindringende Kobolde, Defias-Banditen und Gnoll-Plünderer zu verteidigen."}},faq={{q="Was ist der Zweck der Hall of Arms?",a="Die Hall of Arms dient als erstes martialisches Übungsgelände innerhalb der Abtei von Nordhain. Sie bietet neu rekrutierten Soldaten, Söldnern und Paladinen eine grundlegende Ausbildung in Waffen und Kampftechniken, bevor sie sich in das weitere Königreich hinauswagen.",al={"was ist dieser raum","zweck der hall of arms","was passiert hier"}},{q="Wer ist in diesem Flügel zu finden?",a="Der Flügel ist mit erfahrenen Krieger- und Paladin-Ausbildern besetzt, die im Auftrag der Sturmwind-Armee frische Rekruten in martialischen Disziplinen, Schildarbeit und grundlegenden Kampfmanövern unterweisen.",al={"wer ist in der hall of arms","ausbilder hall of arms","wer lehrt hier"}},{q="Wo befindet sich die Hall of Arms innerhalb der Abtei von Nordhain?",a="Die Hall of Arms liegt auf der Südseite der Abtei von Nordhain, direkt zugänglich von der zentralen Haupthalle und gegenüber dem Bibliotheksflügel auf der anderen Seite des Abtei-Innenhofs.",al={"standort hall of arms","wo ist die hall of arms","aufbau der abtei"}}},fx={["1c4cb7f4"]={q="Ist die Hall of Arms gefährlich?",a="Überhaupt nicht. Die Hall of Arms ist ein sicherer Zufluchtsort innerhalb der Abtei von Nordhain, geschützt vor den Defias-Taschendieben und Kobolden, die draußen im Tal umherstreifen. In ihren stillen Steinkammern wachen erfahrene Paladine und abgehärtete Soldaten über die Rekruten. Sofern Ärger nicht irgendwie die Tore der Abtei durchbricht, könnt Ihr hier ohne jede Bedrohung ruhen und trainieren.",al={"gefahr in der hall of arms","ist die hall of arms sicher","feinde in der hall of arms"}},c5e01713={q="Warum wird sie Hall of Arms genannt?",a="Der Flügel verdient seinen Namen durch seine Rolle als Zentrum für militärische Disziplin in der Abtei von Nordhain. Während der gegenüberliegende Flügel dem Studium und heiligen Texten in der Library gewidmet ist, ist diese Halle dem Waffenhandwerk gewidmet und beherbergt die Waffenmeister, Rüstkammern und Ausbilder, die neue Krieger und Paladine für die Armee von Sturmwind vorbereiten.",al={"warum hall of arms","bedeutung des namens hall of arms","was bedeutet hall of arms"}}},fp="12,100,23.440.0,40.154.0,34.134.0,58.108.0"}
P.entries["subzone:hall-of-arms-tyr-s-hand"] = {n="Hall of Arms",s="Scharlachrote Kämpfer halten die Hall of Arms in Tyrs Hand, tief im Südosten der Pestländer. Dieser Flügel der Tyr's Hand Abbey beherbergt die kriegerische Vorhut des Kreuzzugs, gegenüber der Bibliothek der Abtei.",h="Scharlachrote Kämpfer halten die Hall of Arms in Tyrs Hand, tief im Südosten der Pestländer.",kw={"abtei","waffenkammer","östliche pestländer","hall of arms","scharlachroter kreuzzug","tyrs hand"},ang={["class:Paladin"]="Für einen Ritter der Silver Hand ist die Hall of Arms ein bitterer Anblick: heilige Traditionen des geweihten Kampfes im Dienst fanatischer Abschottung.",["class:Warrior"]="Die Hall of Arms zeigt die Waffen der Menschen und ihre disziplinierte Schlachtvorbereitung in höchster Vollendung. Doch Fanatismus bestimmt ihren Einsatz."},sec={{t="Eine Bastion aus Stahl",b="Scharlachrote Kämpfer halten in der Hall of Arms Wache, südlich der Haupthalle der Tyr's Hand Abbey. Ihre Waffenkammer und ihre Quartiere füllen diesen Flügel, während gegenüber Archive und heilige Texte verwahrt werden. Die Verteidiger tragen schwere Rüstungen und schwören, die Untoten und jeden zu vernichten, den sie für unrein halten. Umgeben von den Schrecken der Pestländer bewachen sie die Abtei und halten ihre Waffen und Schilde bereit."}},faq={{q="Wo befindet sich die Hall of Arms?",a="Die Hall of Arms liegt innerhalb der Tyr's Hand Abbey in Tyrs Hand, im Südosten der Östlichen Pestländer. Sie bildet den südlichen Flügel der Abtei, gegenüber dem Library Wing.",al={"hall of arms standort","wo ist hall of arms","tyr's hand abbey hall of arms"}},{q="Wer hält die Hall of Arms besetzt?",a="Elitekämpfer des Scharlachroten Kreuzzugs halten die Hall of Arms. Krieger, Paladine und Wachen pflegen dort ihre Waffen und bereiten sich auf den Kampf gegen die Geißel und Fremde vor, die ihr Heiligtum betreten.",al={"wer lebt in hall of arms","hall of arms feinde","scharlachroter kreuzzug hall of arms"}},{q="Welchen Zweck erfüllt dieser Flügel im Vergleich zum Rest der Abtei?",a="Die Hall of Arms beherbergt Truppen und Waffen und dient dazu, beides für die Schlacht bereitzuhalten. Auf der anderen Seite der Abtei ist der gegenüberliegende Flügel dem Studium, der inneren Einkehr und den heiligen Schriften gewidmet. Hier bereiten sich die Verteidiger auf Angriffe der Geißel vor.",al={"zweck der hall of arms","wozu dient hall of arms"}},{q="Können Mitglieder der Allianz friedlich eintreten?",a="Nein. Der Scharlachrote Kreuzzug in Tyrs Hand greift Reisende der Allianz und der Horde sofort an. Obwohl sie dieselben menschlichen Wurzeln haben und das Heilige Licht verehren, sehen sie Fremde als mögliche Seuchenträger oder Verbündete des Bösen.",al={"ist der scharlachrote kreuzzug der allianz freundlich gesinnt","kann die allianz hall of arms besuchen","greift tyrs hand an"}}},fp="12,195,18.379.0,34.164.0,30.183.0,67.227.0,45.209.0"}
P.entries["subzone:hall-of-champions"] = {n="Hall of Champions",s="Im Waffenkammerflügel des Scharlachroten Klosters wird die Elite des Kreuzzugs in der Hall of Champions geprüft. Herod, der Scharlachrote Champion, führt von diesem Allerheiligsten aus dessen grimmigste Kämpfer an.",h="Im Waffenkammerflügel des Scharlachroten Klosters wird die Elite des Kreuzzugs in der Hall of Champions...",kw={"footman's armory","hall of champions","herod","scharlachroter kreuzzug","das scharlachrote kloster"},ang={["class:Paladin"]="Als Ritter des Heiligen Lichts erinnert Euch die Begegnung mit Herod, dem Scharlachroten Champion, in seiner eigenen Halle daran, dass wahre Tugend und Glaube in Fanatismus umschlagen können.",["race:Human"]="Als menschlicher Reisender aus Lordaeron erkennt Ihr unter den Champions des Kreuzzugs vielleicht ehemalige Verteidiger der nördlichen Königreiche. Sie haben sich dem fanatischen Kreuzzug verschrieben."},sec={{t="Sitz des Scharlachroten Champions",b="Hinter Footman's Armory erreicht Ihr die Hall of Champions im Herzen des Waffenkammerflügels des Klosters. Herod, der Scharlachrote Champion, befehligt hier die grimmigsten Kämpfer des Kreuzzugs.\n\nScharlachrote Rekruten stärken ihre Entschlossenheit und schulen ihre Fähigkeiten für das Ziel des Kreuzzugs: Lordaeron von allen Untoten und Außenseitern zu säubern."}},faq={{q="Welchem Zweck dient die Hall of Champions?",a="Die Hall of Champions ist das Allerheiligste der Waffenkammer des Klosters und eine Prüfungsstätte für die Elite des Scharlachroten Kreuzzugs. Herod, der Scharlachrote Champion, führt ihre Kämpfer an, während Rekruten ihre Fähigkeiten für den Krieg gegen die Untoten schulen.",al={"was ist die hall of champions","zweck der hall of champions","warum stehen hier statuen"}},{q="Wer sind die in den Statuen verewigten Personen?",a="Keiner der hier verewigten Champions wird in den Aufzeichnungen dieser Zeit namentlich genannt. Herod, der Scharlachrote Champion, ist die bekannteste Gestalt der Halle und bewacht die Kammer.",al={"wen stellen die statuen dar","statuennamen hall of champions","statuen im kloster"}},{q="Wie unterscheidet sich diese Halle von Sturmwinds Halle der Champions?",a="Obwohl ihre Namen ähnlich sind, liegt die Hall of Champions tief im Scharlachroten Kloster in Tirisfal und ehrt Gestalten des Scharlachroten Kreuzzugs. Die Halle der Champions in Sturmwind ist eine Militärgarnison, die Offizieren der Allianz und PvP-Rüstmeistern vorbehalten ist.",al={"ist das die pvp-halle in sturmwind","hall of champions im vergleich zur halle der champions","verwechslung der pvp-halle"}}},fx={["379bd11f"]={q="Wer beaufsichtigt die Hall of Champions?",a="Herod, der Scharlachrote Champion, besetzt die Hall of Champions in der Waffenkammer des Klosters. Er ist einer der führenden Köpfe von The Scarlet Crusade dort.",al={"wer leitet die hall of champions","wer ist in der hall of champions","boss der hall of champions"}},["91532869"]={q="Ist die Hall of Champions gefährlich?",a="Ja. Herod und die Verteidiger von The Scarlet Crusade sind Eindringlingen gegenüber feindselig eingestellt. Das Betreten dieser Kammer bedeutet, sich The Scarlet Crusade in ihrer eigenen Festung zu stellen.",al={"ist die hall of champions sicher","gefahr in der hall of champions"}},c3492897={q="Was ist die Hall of Champions?",a="Die Hall of Champions ist das Allerheiligste des Waffenkammerflügels des Scharlachroten Klosters und befindet sich gleich hinter der Fußknechtswaffenkammer. Sie ist der Sitz von Herod, dem Scharlachroten Champion, wo die grimmigsten Kämpfer des Kreuzzugs gegen Eindringlinge bereitstehen.",al={"was ist die hall of champions","hall of champions scharlachrot"}},["9eb683e4"]={q="Warum heißt sie Hall of Champions?",a="Die Kammer verdankt ihren Namen ihrer Rolle als Sitz der Champions des Kreuzzugs, wo Herod, der Scharlachrote Champion, über die Elitekämpfer des Ordens gebietet.",al={"warum heisst es hall of champions","name hall of champions"}}},fp="17,174,28.304.0,45.235.0,47.153.0,59.250.0"}
P.entries["subzone:hall-of-explorers"] = {n="Hall of Explorers",s="In Eisenschmiede zieht die Hall of Explorers Zwerge an, die nach den Ursprüngen ihres Volkes suchen. Die Forscherliga erforscht hier Azeroths Vergangenheit.",h="In Eisenschmiede zieht die Hall of Explorers Zwerge an, die nach den Ursprüngen ihres Volkes suchen.",kw={"archäologie","forscherliga","hall of explorers","eisenschmiede library","magellas","museum"},ang={["race:Dwarf"]="Als zwergischer Abenteurer könnt Ihr die hier gesammelten Relikte erkunden, während die Forscherliga nach den uralten Ursprüngen Eures Volkes und seiner Verbindung zu den Titanen sucht."},sec={{t="Hauptquartier der Forscherliga",b="Im Nordosten von Eisenschmiede füllt die Hall of Explorers eine Kaverne mit Gelehrten und Feldagenten. High Explorer Muninn Magellas leitet ihre Arbeit, während sie Ausgrabungen in fernen Ländern organisieren. Diese Expeditionen bringen Relikte, antike Titanenmaschinerie und prähistorische Knochen zurück. Im Zentrum der Halle bewahrt die Library historisches Wissen. Besucher können ihre Ausstellungen besichtigen, während andere Aufzeichnungen unter Verschluss bleiben."}},faq={{q="Wozu dient die Hall of Explorers?",a="Die Hall of Explorers ist Hauptquartier und Museum der Forscherliga. Gelehrte studieren Berichte, katalogisieren Ausgrabungsfunde und organisieren Ausgrabungen, um mehr über die Ursprünge der Zwerge und das uralte Azeroth zu erfahren.",al={"hall of explorers zweck","was geschieht hier","forscherliga hauptquartier"}},{q="Wer leitet die Arbeit hier?",a="High Explorer Muninn Magellas leitet die Expeditionen, das Museum und die Forschungsarchive der Halle.",al={"wer leitet die hall of explorers","forscherliga anführer","high explorer"}},{q="Wie ist dieser Ort mit dem Rest von Eisenschmiede verbunden?",a="Die Hall of Explorers liegt im Nordosten von Eisenschmiede. Torbögen verbinden sie mit der Großen Schmiede im Südwesten, der Forlorn Cavern im Westen und Tüftlerstadt im Süden.",al={"wie gelangt man hierher","hall of explorers ausgänge","wo ist die hall of explorers"}}},fx={f8b05ac5={q="Was ist die Hall of Explorers?",a="Die Hall of Explorers, manchmal auch Versammlung der Forscher genannt, ist ein bedeutender nordöstlicher Bezirk innerhalb von Eisenschmiede. Sie dient als Welthauptquartier der Forscherliga der Zwerge. Neben Büros und Forschungsarchiven fungiert sie als großes Museum und Library, in dem antike Relikte, riesige Skelette und historische Folianten ausgestellt sind, die bei Ausgrabungen in ganz Azeroth geborgen wurden.",al={"was ist die hall of explorers","hall of explorers eisenschmiede","versammlung der forscher"}},["4a4e8160"]={q="Ist die Hall of Explorers gefährlich?",a="Überhaupt nicht. Die Halle liegt sicher im stark befestigten Herzen von Eisenschmiede. Während die Expeditionen, die in die Wildnis entsandt werden, gefährlichen Ruinen, feindseligen Bestien und uralten Flüchen gegenüberstehen, ist der Bezirk selbst ein ruhiger, wissenschaftlicher Zufluchtsort voller Archivare, Archäologen und Würdenträger der Allianz, die ihre Funde studieren.",al={"ist die hall of explorers gefährlich","gefahr in der hall of explorers","ist es hier sicher"}},eaed4071={q="Warum wird sie Hall of Explorers genannt?",a="Der Bezirk hat seinen Namen direkt von seinen Gründern und Anführern, der Forscherliga der Zwerge. Die Liga wurde gegründet, um die Ursprünge des Zwergenvolkes aufzudecken und die Geschichte der Titanen zusammenzusetzen, und machte diesen Flügel der Bergstadt zum zentralen Stützpunkt und Archiv für ihre unerschrockenen Forscher.",al={"warum hall of explorers","warum heißt sie hall of explorers","hall of explorers namensherkunft"}}},fp="17,137,26.395.0,39.196.0,30.92.0,53.172.0"}
P.entries["subzone:hall-of-gears"] = {n="Hall of Gears",s="In Gnomeregan liegt die Hall of Gears hinter dem Clockwerk Run in Trümmern. Giftiger Schlamm füllt ihre untere Ebene, wo Schlämme und verstrahlte Troggs umherstreifen.",h="In Gnomeregan liegt die Hall of Gears hinter dem Clockwerk Run in Trümmern.",kw={"clean zone","clockwerk run","dormitory","gnomeregan","hall of gears","launch bay","radioaktiv","troggs"},ang={["profession:Engineering"]="Als Ingenieur erkennt Ihr die gewaltigen Ausmaße der gnomischen Zahnradwerke und erhöhten Plattformen aus der Zeit vor dem Fall. Radioaktiver Niederschlag hat sie stark zerfressen.",["race:Gnome"]="Als Gnom seht Ihr die gewaltigen Zahnräder und Laufstege, die im verstrahlten Schlamm versunken sind. Sie erinnern an die verzweifelte Entscheidung, die Eure Stadt vergiftete und Euer Volk ins Exil trieb."},sec={{t="Eine zerbrochene Maschine",b="Hinter dem Clockwerk Run liegt die Hall of Gears tief in Gnomeregans verfallenen Maschinenhallen. Ihre zwei Ebenen zeigen, wie vollständig die Hauptstadt der Gnome gefallen ist. Verstrahlte Troggs graben sich durch eingestürzte Zugangsschächte und streifen über die oberen Laufstege. Darunter bedecken radioaktive Lachen den Boden. Ätzende Schleime und lebende Giftelementare gedeihen im giftigen Abwasser."},{t="Wege durch den Unrat",b="Die Hall of Gears verbindet Teile von Gnomeregans Betriebsvierteln. Von den oberen Laufstegen führen Wege zu verseuchten Sackgassen, zur Clean Zone und zum Dormitory. Darunter führen gewundene Wartungsgänge in Richtung der Launch Bay. Die Schrecken, die Robogenieur Thermapluggs Entlüftungsplan hinterlassen hat, machen beide Ebenen noch immer gefährlich."}},faq={{q="Wo liegt die Hall of Gears?",a="Die Hall of Gears liegt tief in Gnomeregan, direkt hinter dem Clockwerk Run. Wege aus der Kammer führen zur Clean Zone, zum Dormitory und zur Launch Bay.",al={"hall of gears lage","wo liegt die hall of gears","wie zur hall of gears gelangen"}},{q="Warum ist die untere Ebene voller radioaktivem Schlamm?",a="Als High Tinker Mekkatorque befahl, radioaktives Gas abzulassen, um die Trogginvasion abzuwehren, sammelte sich verseuchtes Abwasser in den tiefer gelegenen Maschinenhallen der Stadt. Die untere Ebene der Hall of Gears wurde zu einer giftigen Einöde.",al={"warum ist es grün","radioaktiver abfall hall of gears","was ist der schlamm"}},{q="Welche Kreaturen bewohnen diese Kammer?",a="Verstrahlte Troggs strömen durch Einbruchstunnel auf die obere Ebene. Darunter entstanden aus den industriellen Abwässern radioaktive Niederschlagsschleime, Schlämme und instabile Giftelementare.",al={"hall of gears gegner","was lebt in der hall of gears","hall of gears mobs"}},{q="Wohin führen die Ausgänge von hier?",a="Die oberen Laufstege führen nach Südwesten zur Clean Zone und zum Dormitory sowie nach Südosten in einen Wartungsgang, der als Sackgasse endet. Ein gewundener Gang führt von der unteren Ebene nach Westen zur Launch Bay.",al={"hall of gears ausgänge","wohin von der hall of gears"}}},fx={d9a40d55={q="Was ist die Hall of Gears?",a="Die Hall of Gears ist eine massive, mehrstöckige Kammer in der unterirdischen Stadt Gnomeregan, direkt hinter dem Clockwerk Run. Wie ein Großteil des technologischen Wunders, das die Hauptstadt der Gnome einst war, war sie früher ein Zentrum geschäftiger Industrie und komplexer Maschinen. Heute steht sie als gefährlicher Korridor da, der zwischen verstrahlten oberen Laufstegen und giftigen, schlammbedeckten Tiefen aufgeteilt ist.",al={"hall of gears übersicht","was ist das für ein ort","hall of gears gnomeregan"}},["3f6f0027"]={q="Was ist mit der Hall of Gears passiert?",a="Als die barbarischen Troggs in die Stadt eindrangen, versuchten die Tüftler, die Invasoren zu vertreiben, indem sie die Hallen mit radioaktivem Fallout fluteten. Anstatt die Troggs zu vertreiben, mutierten sie durch das giftige Gas und kontaminierten den gesamten Sektor. Die Gnome waren gezwungen zu evakuieren und überließen die Hall of Gears den verstrahlten Monstern und dem kriechenden Giftmüll.",al={"geschichte der hall of gears","was ist hier passiert","gnomeregan katastrophe hall of gears"}},ad0af20b={q="Ist die Hall of Gears gefährlich?",a="Sie ist außerordentlich gefährlich. Die obere Ebene wimmelt von wilden, verstrahlten Troggs, die jedem Eindringling feindlich gesinnt sind. Darunter ist der Boden von radioaktivem Fallout überschwemmt, der von säurehaltigen Schlammwesen und flüchtigen Giftelementaren bewohnt wird. Das Durchqueren der Kammer erfordert das Meiden giftiger Pfützen und den Kampf gegen verdrehte Abscheulichkeiten, die durch den Ruin der Stadt entstanden sind.",al={"ist die hall of gears gefährlich","bedrohungen in der hall of gears","wie gefährlich ist die hall of gears"}}},fp="13,147,19.365.0,26.322.0,35.163.0,50.214.0,36.175.0,34.193.0"}
P.entries["subzone:hall-of-legends"] = {n="Halle der Legenden",s="In Orgrimmars Tal der Stärke versammeln sich Champions der Horde in der Halle der Legenden. Hinter ihrem bewachten Eingang beraten bewährte Offiziere über Schlachtpläne und rüsten sich mit Waffen und Rüstungen aus Kriegen in ganz Azeroth und darüber hinaus aus.",h="In Orgrimmars Tal der Stärke versammeln sich Champions der Horde in der Halle der Legenden.",kw={"halle der legenden","offizierskaserne","orgrimmar","pvp","spoils of war","stone guard","tal der stärke"},ang={["class:Warrior"]="Für Euch als Krieger an vorderster Front bedeutet der Einlass in die Halle der Legenden höchste militärische Anerkennung und Zugang zur besten Kriegsausrüstung der Horde.",["faction:Horde"]="Für die Horde würdigt die Halle der Legenden militärische Leistungen und bietet jenen strategischen Rat und begehrte Kriegsausrüstung, die für den Kriegshäuptling Blut vergießen."},sec={{t="Zuflucht der Champions der Horde",b="Offiziere der Horde versammeln sich in der Halle der Legenden, abseits der belebten Straßen des Tals der Stärke. Hinter ihrem bewachten Eingang beraten Strategen und Abgesandte der gesamten Fraktion über Karten umkämpfter Gebiete und die militärische Stärke beider Fraktionen. Zu ihnen gehören Chieftain Earthbind aus Donnerfels, Blood Guard Hini'wana von den Dunkelspeeren und Advisor Willington aus Unterstadt. Nur Krieger mit dem Rang Stone Guard oder höher dürfen eintreten und die Waffen und Beutestücke im Inneren beanspruchen."},{t="Kriegsbeute",b="Die Halle der Legenden hält ihre Waffenkammern mit kampferprobter Kriegsausrüstung für bewährte Offiziere der Horde gefüllt. Für jene, die in den militärischen Rängen aufsteigen, stehen diese Waffen und Rüstungen für Ehre, kriegerisches Können und hart errungene Siege."}},faq={{q="Wer darf die Halle der Legenden betreten?",a="Nur Champions der Horde mit dem Rang Stone Guard oder höher dürfen die Halle der Legenden betreten. Soldaten niedrigeren Ranges und gewöhnliche Bürger werden am Eingang abgewiesen.",al={"darf ich die halle der legenden betreten","halle der legenden voraussetzung","benötigter rang für die halle der legenden"}},{q="Wo befindet sich die Halle der Legenden?",a="Die Halle der Legenden steht in Orgrimmars Tal der Stärke, nahe der Hauptkaserne und dem Verwaltungssitz der Stadt.",al={"wo ist die halle der legenden","halle der legenden standort","wie gelangt man zur halle der legenden"}},{q="Was befindet sich in der Halle der Legenden?",a="In der Halle der Legenden stehen militärische Vertreter der verschiedenen Völker der Horde zu beiden Seiten eines zentralen Strategietisches. Karten von Azeroth und militärische Aufzeichnungen umgeben sie. Rüstmeister unterhalten dort Waffenkammern und geben angesehene Waffen, Rüstungen und Reittiere an verdiente Offiziere aus.",al={"was ist in der halle der legenden","halle der legenden innenraum"}},{q="Hat die Allianz einen vergleichbaren Ort?",a="Ja. Das Gegenstück der Allianz ist die Halle der Champions in der Altstadt von Sturmwind, eine Offizierskaserne und Waffenkammer für geehrte Kämpfer der Allianz.",al={"allianz halle der legenden","gegenstück der allianz"}}},fx={e332bf32={q="Was ist die Halle der Legenden?",a="Die Halle der Legenden dient als Elite-Militärkaserne und Waffenkammer für ausgezeichnete Offiziere der Horde, gelegen im Tal der Stärke in Orgrimmar. Hier versammeln sich kampferprobte Champions, um militärische Strategien zu planen, Kriegskarten von ganz Azeroth zu konsultieren und sich mit spezialisierten Waffen und Rüstungen auszurüsten, die geschmiedet oder aus Feldzügen in der ganzen Welt erbeutet wurden.",al={"was ist die halle der legenden","zweck der halle der legenden","was ist das für ein ort"}},e6163205={q="Wer beaufsichtigt die Halle der Legenden?",a="Die Halle wird von Quartiermeistern und Vertretern der Kernfraktionen der Horde besetzt, die sich um ihren zentralen Kriegstisch versammeln. Offiziere wie Häuptling Earthbind aus Donnerfels, Berater Willington, der die Verlassenen vertritt, und Blutwache Hini'wana von den Dunkelspeeren beraten über strategische Karten und inspizieren die Vorräte der Waffenkammer.",al={"wer leitet die halle der legenden","wer ist in der halle der legenden","offiziere der halle der legenden"}},["5e706ae3"]={q="Ist die Halle der Legenden gefährlich?",a="Die Halle der Legenden stellt keine physische Gefahr für loyale Champions der Horde dar, die sich das Recht verdient haben, ihre Schwelle zu überschreiten. Es ist ein sicheres, stark bewachtes Sanktuarium im Herzen von Orgrimmar, das ausschließlich Militärveteranen und den sie ausrüstenden Quartiermeistern gewidmet ist.",al={"ist die halle der legenden sicher","gefahr in der halle der legenden","ist es feindselig"}}},fp="15,230,28.477.0,17.208.0,42.158.0,37.119.0,35.289.0,46.155.0"}
P.entries["subzone:hall-of-masks"] = {n="Hall of Masks",s="In der Hall of Masks ragen geschnitzte Schädel über einem knochengefüllten Graben unter den Sümpfen des Elends auf. Die Kammer bildet eine Schwelle zu tieferen Gängen im versunkenen Tempel von Atal'Hakkar.",h="In der Hall of Masks ragen geschnitzte Schädel über einem knochengefüllten Graben unter den Sümpfen des...",kw={"atal'ai","broken hall","hall of masks","versunkener tempel","sümpfe des elends","der tempel von atal'hakkar"},ang={["class:Priest"]="Als Priester könnt Ihr die dunklen Praktiken der Atal'ai an der düsteren Gestaltung der Kammer und ihrem knochengefüllten Graben ablesen. Die genaue Nutzung des Grabens bleibt unbekannt.",["race:Troll"]="Als Dunkelspeer-Troll könnt Ihr erkennen, wie weit die Atal'ai-Zeloten in ihrem verzweifelten Streben nach Hakkar the Soulflayer gingen."},sec={{t="Eine grausige Schwelle",b="Hinter der Treppe von der Broken Hall erreicht Ihr einen zentralen Knotenpunkt im Versunkenen Tempel. Stilisierte Schädelmasken säumen seine Steinwände. Ein tiefer, mit weggeworfenen Knochen verstopfter Graben durchzieht den Boden, doch sein Zweck bleibt unbekannt. Von hier führen Gänge zur Butchery, zur Chamber of Blood und zur Den of the Caller."}},faq={{q="Wo liegt die Hall of Masks?",a="Die Hall of Masks liegt im Tempel von Atal'Hakkar unter dem Tränenteich in den Sümpfen des Elends. Steigt nahe dem Eingang des versunkenen Komplexes an der Broken Hall vorbei hinab, um sie zu erreichen.",al={"hall of masks lage","wo ist die hall of masks","hall of masks finden"}},{q="Warum heißt sie Hall of Masks?",a="Die Hall of Masks verdankt ihren Namen den gewaltigen geschnitzten Schädelmasken an ihren Wänden. Sie ragen über allen auf, die durch die Tempelgänge schreiten.",al={"hall of masks namensbedeutung","warum masken"}},{q="Welchen Zweck hatte der Graben im Boden?",a="Knochen liegen verstreut im Graben, doch sein genauer Zweck bleibt unbekannt.",al={"warum liegen knochen im boden","hall of masks knochengrube","knochengraben"}},{q="Wohin führen die Gänge aus dieser Halle?",a="Gänge aus der Hall of Masks führen tiefer in den Tempel, zur Butchery, zur Chamber of Blood und zur Den of the Caller.",al={"hall of masks ausgänge","wohin führt die hall of masks"}}},fp="13,182,20.326.0,35.183.0,35.148.0,48.63.0,42.130.0"}
P.entries["subzone:hall-of-mysteries"] = {n="Hall of Mysteries",s="In Eisenschmiedes Mystic Ward versammelt die Hall of Mysteries Zwerge und Gnome zur Glaubenspraxis und zum arkanen Studium. Sie lesen uralte Texte, ergründen das Heilige Licht und weben Verzauberungen in ihren blau erleuchteten Hallen.",h="In Eisenschmiedes Mystic Ward versammelt die Hall of Mysteries Zwerge und Gnome zur Glaubenspraxis und zum...",kw={"hall of mysteries","eisenschmiede","magier","mystic ward","paladin","priester","rohan","silberne hand","tome of divinity"},ang={["class:Paladin"]="Für zwergische Streiter der Silbernen Hand ist die Halle der Ort, an dem Meister Tugendprüfungen auferlegen und Zugang zum heiligen Tome of Divinity gewähren.",["class:Priest"]="Hohepriester Rohan führt Akolythen des Lichts hier durch geistliche Unterweisungen. Vielversprechende Priester reisen anschließend nach Süden, um sich mit Sturmwinds Führung zu beraten."},sec={{t="Ein Tempel der Magie und des Glaubens",b="Blaues und violettes Licht hebt die Hall of Mysteries zwischen Eisenschmiedes Stein, Eisen und schwerer Plattenrüstung hervor. Fünf emporragende Säulen bieten Gelehrten in wallenden Gewändern Schutz. Hier haben die zwergische Priesterschaft und der Orden der Silbernen Hand ihren Hauptsitz innerhalb von Khaz Modan. Sie verbinden arkanes Studium mit Hingabe an das Heilige Licht.\n\nJunge Kleriker und Ritter studieren hier Texte wie den Tome of Divinity. Sie erhalten Wegweisung, bevor sie weiter zur Kathedrale des Lichts in Sturmwind reisen."}},faq={{q="Welchem Zweck dient die Hall of Mysteries?",a="Die Hall of Mysteries vereint göttliche Hingabe und arkane Gelehrsamkeit in Eisenschmiede. Zwergische und gnomische Priester, Paladine und Magier versammeln sich dort, um heilige Schriften zu studieren, ihre Künste auszuüben und Neulinge auszubilden.",al={"was ist dieser ort","zweck der hall of mysteries","warum die hall of mysteries besuchen"}},{q="Wer führt hier die Geistlichen?",a="Hohepriester Rohan leitet die Priesterschaft in der Halle und weist zwergischen Anhängern des Lichts den Weg. Paladinmentoren wie Valgar Highforge führen die Ritter der Silbernen Hand in der Stadt.",al={"wer leitet die hall of mysteries","anführer der priester in eisenschmiede","wer ist hohepriester rohan"}},{q="Wie unterscheidet sie sich von der Kathedrale des Lichts in Sturmwind?",a="Sturmwinds Kathedrale des Lichts ist dem heiligen Glauben und dem zeremoniellen Gottesdienst gewidmet. Die Hall of Mysteries verbindet heiliges Studium mit arkaner Gelehrsamkeit, und ihre Atmosphäre ist gelehrt und still.",al={"kathedrale des lichts im vergleich zur hall of mysteries","ähnelt sie sturmwinds kathedrale"}},{q="Können Paladine hier ihre Ausbildungsprüfungen abschließen?",a="Ja. Zwergische Paladine studieren in der Halle den Tome of Divinity unter der Anleitung der Silbernen Hand. Ihr Unterricht und ihre heiligen Prüfungen stellen Mitgefühl, Hingabe und Mut auf die Probe.",al={"paladinquests in eisenschmiede","tome of divinity in eisenschmiede","quests für zwergenpaladine"}}},fx={["1847c72f"]={q="Was ist die Hall of Mysteries?",a="Die Hall of Mysteries ist ein großer Tempel und Zufluchtsort im Mystic Ward von Eisenschmiede. Dominiert von einem sanften blau-violetten Leuchten und hoch aufragenden geometrischen Säulen, dient sie als zentraler Knotenpunkt der Hauptstadt sowohl für göttliche Andacht als auch für die arkanen Künste. Innerhalb ihrer Kammern versammeln sich zwergische und gnomische Gelehrte, Priester, Paladine und Magier, um zu studieren, ihre Künste zu praktizieren und neue Lehrlinge auszubilden.",al={"was ist die hall of mysteries","hall of mysteries eisenschmiede","mystic ward tempel"}},e1807a94={q="Wer wohnt in der Hall of Mysteries?",a="Die Halle wird hauptsächlich von zwergischen und gnomischen Gelehrten bewohnt, die in fließende Roben gekleidet sind, was einen Kontrast zur schweren Plattenrüstung bildet, die man sonst in Eisenschmiede sieht. Zu ihren dort ansässigen Klerikern und Mentoren gehören Hohepriester Rohan von der Kirche des Lichts und Valgar Highforge vom Orden der Silbernen Hand, neben angesehenen Magier-Ausbildern, die Studenten in arkanem Wissen anleiten.",al={"wer lebt in der hall of mysteries","bewohner der hall of mysteries","wer ist in der hall of mysteries"}},["68d8f867"]={q="Ist die Hall of Mysteries gefährlich?",a="Nicht im Geringsten. Die Hall of Mysteries ist ein vollkommen sicheres Sanktuarium tief im Herzen von Eisenschmiede. Bewacht von den besten Paladinen, Priestern und Magiern des Königreichs, ist sie ein sicherer Zufluchtsort für Bürger der Allianz, die Heilung, spirituelle Einkehr oder akademisches Studium suchen.",al={"ist die hall of mysteries sicher","gefahr in der hall of mysteries","feinde in der hall of mysteries"}}},fp="17,218,27.473.0,45.213.0,26.189.0,59.188.0,49.174.0"}
P.entries["subzone:hall-of-the-brave"] = {n="Hall of the Brave",s="Krieger versammeln sich und trainieren in Orgrimmars Hall of the Brave im Tal der Ehre. Die Halle dient den Frontkämpfern, Drillmeistern und Kampfmeistern der Horde.",h="Krieger versammeln sich und trainieren in Orgrimmars Hall of the Brave im Tal der Ehre.",kw={"kaserne","kampfmeister","hall of the brave","orgrimmar","tal der ehre","kriegerlehrer","kriegergilde"},ang={["class:Warrior"]="Als Krieger könnt Ihr in der Hall of the Brave trainieren, Eurer Heimstatt für die Kriegskunst in der Hauptstadt. Ihre Ausbilder lehren Euch fortgeschrittene Haltungen und Kampfmanöver, während Euer Können wächst.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr in der Hall of the Brave die Disziplin ihrer Frontkämpfer erleben. Dort versammeln Kampfmeister Truppen für Kämpfe auf dem ganzen Kontinent."},sec={{t="Die Bastion der Krieger",b="Die Hall of the Brave überblickt die Gewässer und Trainingsringe des Tals der Ehre. Erfahrene Offiziere und kampferprobte Krieger lehren Rekruten Nahkampf, Haltungen und Disziplin. Trainingsattrappen und Waffen säumen die Halle. Dort organisieren Kampfmeister Kämpfer für große militärische Gefechte in ganz Azeroth."}},faq={{q="Welchem Zweck dient die Hall of the Brave?",a="Die Hall of the Brave ist Orgrimmars wichtigste Kaserne und Gildenhalle für Krieger. Erfahrene Ausbilder vermitteln Techniken, und an Trainingsattrappen können Krieger ihre Schläge verfeinern. Kampfmeister koordinieren militärische Einsätze in umkämpften Gebieten.",al={"was ist die hall of the brave","was ist dieses gebäude","zweck der hall of the brave"}},{q="Wo in Orgrimmar liegt die Halle?",a="Die Hall of the Brave liegt an der Ostseite des Tals der Ehre. Sie erstreckt sich entlang der roten Schluchtwände und überblickt den Teich in der Mitte.",al={"wo ist die hall of the brave","standort der hall of the brave","kriegerlehrer in orgrimmar finden"}},{q="Wer ist in der Halle anzutreffen?",a="Kriegerlehrer und Kampfmeister sind in der Halle anzutreffen. Die Kampfmeister koordinieren große militärische Konflikte, während Grunzer der Horde zwischen ihren Patrouillen rasten.",al={"wer ist in der hall of the brave","npcs in der hall of the brave"}}},fx={["1f330543"]={q="Ist die Hall of the Brave gefährlich?",a="Für loyale Mitglieder der Horde ist die Hall of the Brave absolut sicher – ein Ort der Gemeinschaft, der Unterweisung und des disziplinierten kriegerischen Stolzes. Doch ein Infiltrator der Allianz, der mutig oder töricht genug wäre, diesen Ort zu betreten, würde durch die Elite-Kriegsausbilder, Kampfmeister und erfahrenen Offiziere der Horde, die die Kasernen füllen, einen schnellen und brutalen Tod finden.",al={"ist die hall of the brave sicher","hall of the brave gefährlich","hall of the brave gefahr"}},["3fba9d5a"]={q="Was ist die Hall of the Brave?",a="Die Hall of the Brave ist die große Militärkaserne und das Kriegergildenhaus von Orgrimmar, gelegen im Tal der Ehre der Stadt. Sie dient als zentraler Knotenpunkt, an dem sich die kampferprobten Soldaten der Horde versammeln, trainieren und militärische Angelegenheiten koordinieren. Innerhalb ihrer befestigten Mauern feilen Kämpfer an ihren Fähigkeiten an Trainingsattrappen, konsultieren Veteranenoffiziere und bereiten sich auf die laufenden Kämpfe zur Verteidigung von Durotar und den Grenzen der Horde vor.",al={"was ist die hall of the brave","hall of the brave orgrimmar","kriegerhalle orgrimmar"}}},fp="17,165,21.306.0,45.250.0,39.137.0,33.160.0"}
P.entries["subzone:hammerfall"] = {n="Hammerfall",s="Truppen der Horde halten Hammerfall im Arathihochland, wo alte Verluste und hart errungene Freiheit den Außenposten prägen. Orcs und Verlassene verteidigen ihn gegen Oger der Felsfäuste, Witherbark-Trolle und den Bund von Arathor.",h="Truppen der Horde halten Hammerfall im Arathihochland, wo alte Verluste und hart errungene Freiheit den...",kw={"arathihochland","felsfäuste","entweihte","hammerfall","internierungslager","orgrim schicksalshammer","thrall","witherbark"},ang={["faction:Horde"]="Für die Horde ist Hammerfall ihre Festung im zentralen Arathihochland. Feindselige Oger, Waldtrolle und Überreste der Allianz umgeben sie.",["race:Orc"]="Für Orcs ist Hammerfall heiliger Boden. Orgrim Schicksalshammer gab hier sein Leben, als er gefangene Clangefährten befreite und die Würde des Kriegshäuptlings an Thrall weitergab."},sec={{t="Ein Erbe der Befreiung",b="Unter Hammerfall liegen die Ruinen eines Internierungslagers der Allianz. Nach dem Zweiten Krieg errichtete die Allianz der Menschen in ganz Lordaeron riesige Lager für besiegte Orcs, und dieses gehörte zu den größten. Jahre später griffen Thrall und Orgrim Schicksalshammer das Lager an, um seine apathischen Gefangenen zu befreien.\n\nWährend ihres Rückzugs stürmte ein Ritter der Allianz heran und stieß eine Lanze durch Schicksalshammers Rückenplatte. Der Kriegshäuptling wurde tödlich verwundet. Nach dem Dritten Krieg eroberte die neue Horde die Ruinen zurück und nannte ihren Außenposten zu seinem Gedenken Hammerfall."},{t="Ein Stützpunkt im Hochland",b="Hammerfall bietet der Horde einen Stützpunkt in Arathi. Seine Garnison steht aggressiven Ogern der Felsfäuste aus Fels'gor und der Halle der Felsfäuste sowie den einheimischen Witherbark-Trollen gegenüber. Entweihte der Verlassenen nutzen den Außenposten, um Ressourcen im umkämpften Arathibecken zu beanspruchen. Dort stellen sie sich dem Bund von Arathor der Allianz entgegen."}},faq={{q="Warum heißt dieser Stützpunkt Hammerfall?",a="Der Stützpunkt ehrt Orgrim Schicksalshammer, den die Lanze eines Ritters der Allianz tödlich verwundete, als er Orcs aus dem Internierungslager befreite.",al={"warum hammerfall","namensherkunft hammerfall","wer starb in hammerfall"}},{q="Was war Hammerfall, bevor die Horde es wiederaufbaute?",a="Bevor die Horde den Ort wiederaufbaute, befand sich dort eines der größten Internierungslager der Allianz von Lordaeron. Es wurde nach dem Zweiten Krieg errichtet, um gefangene Orcs einzusperren.",al={"geschichte hammerfall","was war hammerfall früher","internierungslager arathi"}},{q="Wer leitet derzeit die Verteidigung von Hammerfall?",a="Der Orc Drum Teufel herrscht über Hammerfall und leitet seine Verteidigung gegen die Oger der Felsfäuste und die Witherbark-Waldtrolle. Tallow, ein Krieger der Verlassenen in Tarrens Mühle, schickt Rekruten zunächst gegen die Oger der Felsfäuste in Fels'gor.",al={"anführer hammerfall","wer befehligt hammerfall","tallow drum teufel"}},{q="Warum sind die Verlassenen hier stationiert?",a="Entweihte der Verlassenen operieren von Hammerfall aus, um Vorräte aus dem Arathibecken zu sichern. Sie stellen sich dem Bund von Arathor der Allianz entgegen.",al={"verlassene hammerfall","warum sind untote in hammerfall","entweihte arathi"}}},fp="10,213,22.518.0,27.312.0,35.134.0,48.161.0,46.225.0,36.129.0"}
P.entries["subzone:harborage"] = {n="Der Sichere Hafen",s="Am Nordrand der Sümpfe des Elends birgt der Sichere Hafen verbannte Einheimische Draenors, die ihren Verstand bewahrt haben. Sie suchen Frieden am Wasser in einer rauen Wildnis.",h="Am Nordrand der Sümpfe des Elends birgt der Sichere Hafen verbannte Einheimische Draenors, die ihren Verstand...",kw={"broken","draenethyst","der sichere hafen","verirrte","magtoor","sümpfe des elends"},ang={["faction:Alliance"]="Wenn Ihr als Reisender der Allianz das Rotkammgebirge zum gefährlichen Sumpf hin verlasst, ist der Sichere Hafen einer der wenigen Orte im nördlichen Sumpf, an denen Ihr Leuten begegnen könnt, ohne dass sofort Blut fließt.",["faction:Horde"]="Steinard bildet einen Großteil der Präsenz der Horde im Sumpf. Die zurückgezogen lebenden Überlebenden des Sicheren Hafens bleiben unter sich, statt in den regionalen Konflikten Partei zu ergreifen."},sec={{t="Eine Zuflucht im Morast",b="Am Fuß der nördlichen Berge findet Ihr den Sicheren Hafen, ein kleines Lager abseits der wilden Stämme in den nahen Gewässern. Lederunterkünfte und hängende Kristalle kennzeichnen diese Zuflucht für verbannte Überlebende aus Draenor, die ihren Verstand bewahrt haben. Älteste wie Magtoor führen die Gemeinschaft. Gemeinsam behalten sie die Wildnis, ihre heimischen Raubtiere und die wilden Stämme ihrer gefallenen Brüder jenseits des Lagers im Auge."}},faq={{q="Wer lebt im Sicheren Hafen?",a="Verbannte aus Draenor leben im Sicheren Hafen. Obwohl sie nach dem Übertritt nach Azeroth gezeichnet und verändert wurden, haben sie ihren Verstand und ihre Kultur bewahrt, anders als die wilden Stämme andernorts im Sumpf.",al={"bewohner des sicheren hafens","wer ist im sicheren hafen","wer lebt hier"}},{q="Warum sind die Leute hier friedlich, während andere Sumpfstämme angreifen?",a="Die Bewohner des Sicheren Hafens bewahrten trotz ihrer körperlichen Verwandlung und Vertreibung ihren Verstand und ihre Vernunft. Ihre Verwandten im übrigen Moor verloren durch Einsamkeit und traumatische Erlebnisse den Verstand. Hier schlossen sich die Verbannten zusammen, um ihre Würde zu bewahren.",al={"warum sind sie freundlich","verirrte freundlich","sicherer hafen feindselig"}},{q="Wer führt den Sicheren Hafen?",a="Angesehene Älteste wie Magtoor führen die Gemeinschaft, die in einem fremden Sumpf ums Überleben ringt.",al={"anführer des sicheren hafens","magtoor","oberhaupt des sicheren hafens"}},{q="Wo liegt der Sichere Hafen?",a="Der Sichere Hafen liegt an den nördlichen Klippen der Sümpfe des Elends, gleich östlich des Gebirgspasses zum Rotkammgebirge.",al={"lage des sicheren hafens","wo ist der sichere hafen","sicheren hafen finden"}}},fp="9,166,19.400.0,27.179.0,65.233.0,24.83.0,31.125.0"}
P.entries["subzone:hearthglen"] = {n="Herdweiler",s="In den nördlichen Hügeln der Westlichen Pestländer hält Herdweiler stand. Seine Mauern überstanden Lordaerons Fall, und der Scharlachrote Kreuzzug nutzt die Siedlung und ihr Ackerland nun als nördliche Festung und Ausbildungsstätte.",h="In den nördlichen Hügeln der Westlichen Pestländer hält Herdweiler stand.",kw={"andorhal","herdweiler","mardenholde","scharlachroter kreuzzug","taelan fordring","tirion fordring","westliche pestländer"},ang={["class:Paladin"]="Als Paladin beschreitet Ihr die Zufahrten zu einem Ort, der einst Tirion Fordrings Heimat war. Sein Sohn hält Herdweiler nun für den Scharlachroten Kreuzzug. Die Stadt zeigt, wie tragisch der Orden zerbrach und daraus ein fanatischer Kreuzzug entstand.",["race:Undead"]="Als Verlassener steht Ihr in Herdweiler einem tödlichen Stachel im Norden gegenüber. Seine Kreuzfahrer hassen die Untoten und patrouillieren, um alle Späher auszulöschen, die sich von Andorhal aus nach Norden wagen."},sec={{t="Eine Bastion in der Fäulnis",b="Herdweiler wirkt noch immer wie eine lebendige Stadt Lordaerons, während vom nahen Andorhal nur skelettartige Ruinen bleiben. Sein Sägewerk, seine Spähtürme, Ställe und die betriebene Mine sind noch immer da. Lord Tirion Fordring regierte einst von Burg Mardenholde aus. Während des Zweiten Krieges blühte Herdweiler auf und wurde standhaft verteidigt.\n\nAls die Seuche des Untods während des Dritten Krieges über Lordaeron hereinbrach, fing Prinz Arthas Menethil hier verseuchtes Getreide ab. Er läuterte die infizierten Stadtbewohner und schlug gemeinsam mit Uther dem Lichtbringer eine gewaltige Belagerung der Geißel zurück. Herdweilers mächtige Mauern überstanden sie unversehrt."},{t="Unter dem Scharlachroten Banner",b="Nach dem Zusammenbruch des Königreichs geriet die Silberne Hand in Unordnung. Tirions Sohn Taelan Fordring sagte sich vom Orden los und schloss sich dem Scharlachroten Kreuzzug an. Trauer und Fanatismus erfassten bald die Festung. Scharlachrote Kreuzfahrer patrouillieren nun auf Herdweilers Zufahrten und bemannen seine Wälle. Sie richten jeden Außenstehenden hin, der ihr Land betritt, ob lebendig oder untot.\n\nHochlord Taelan Fordring herrscht von Burg Mardenholde aus. Von dort aus dient er dem kompromisslosen Krieg des Kreuzzugs gegen die Pestländer."}},faq={{q="Warum wirkt Herdweiler im Vergleich zum Rest der Pestländer so sauber?",a="Prinz Arthas und Uther der Lichtbringer halfen, Herdweiler während des Dritten Krieges vor der völligen Zerstörung zu bewahren. Sie töteten die ersten Seuchenopfer und durchbrachen eine gewaltige Belagerung der Geißel. Später befestigte der Scharlachrote Kreuzzug den Pass und das Tal und vernichtete die vorrückende Geißel, bevor die Fäulnis Fuß fassen konnte.",al={"warum ist herdweiler unversehrt","herdweiler nicht zerstört","herdweiler lebendig"}},{q="Wer kontrolliert Herdweiler derzeit?",a="Der Scharlachrote Kreuzzug kontrolliert Herdweiler von Burg Mardenholde aus, wo Hochlord Taelan Fordring herrscht. Er ist der Sohn von Tirion Fordring, dem früheren Lord und berühmten Paladin.",al={"wer herrscht über herdweiler","herdweiler anführer","wer hat das sagen in herdweiler"}},{q="Ist Herdweiler Besuchern der Allianz oder Horde freundlich gesinnt?",a="Nein. Der Scharlachrote Kreuzzug begegnet allen Außenstehenden mit äußerster Feindseligkeit und Paranoia. Seine Anhänger sehen Mitglieder der Horde als monströse Abscheulichkeiten. Unabhängige Reisende der Allianz werden als Seuchenträger oder Ketzer verurteilt und sollen bei Sichtkontakt hingerichtet werden.",al={"herdweiler betreten möglich","ist herdweiler feindselig","herdweiler sicher"}},{q="Was geschah mit Tirion Fordring?",a="Jahre vor dem Dritten Krieg wurde Tirion seines Titels enthoben und von der Allianz exkommuniziert, weil er einen ehrenhaften Orc namens Etrigg verteidigt hatte. In die Wildnis verbannt, ließ er Herdweiler hinter sich. Das Kommando über Mardenholde ging schließlich an seinen Sohn Taelan über.",al={"wo ist tirion","tirion herdweiler geschichte","warum ist tirion nicht hier"}}},fp="10,221,23.574.0,24.480.0,74.290.0,34.169.0,53.240.0,33.250.0"}
P.entries["subzone:helm-s-bed-lake"] = {n="Helmsbettsee",s="Im Südosten von Dun Morogh halten Zwerge ein Loch im Helmsbettsee offen, um Frischwasser zu schöpfen. Doch Bestien, Troggs und feindselige Dunkeleisenzwerge machen das Ufer gefährlich.",h="Im Südosten von Dun Morogh halten Zwerge ein Loch im Helmsbettsee offen, um Frischwasser zu schöpfen.",kw={"dunkeleisen","dun morogh","helmsbettsee","eisloch","narm faulk","trogg"},ang={["faction:Alliance"]="Bleibt als Reisender der Allianz auf Eurem Weg nach Osten in Richtung Loch Modan wachsam. Der Pfad im Süden führt dicht an den Hinterhalten der Dunkeleisenzwerge vorbei.",["race:Dwarf"]="Als Zwerg aus Eisenschmiede kennt Ihr den Helmsbettsee als lebenswichtige Frischwasserquelle, und seine Ufer sind unsicherer geworden. Dunkeleisensaboteure und Troggs dringen tiefer ins Herzland von Dun Morogh vor."},sec={{t="Ein tückisches Ufer",b="Das Eis ist fest genug, um es zu überqueren, doch die Ufer sind gefährlich. Vertriebene Troggs suchen entlang der Bergrücken nach Nahrung, und wilde Bestien streifen an den Rändern umher. Südlich des Wassers haben feindselige Dunkeleisenzwerge eine verlassene Hütte eingenommen. Sie überfallen Reisende, die in der Nähe vorbeikommen."}},faq={{q="Warum gibt es mitten im zugefrorenen See ein offenes Loch?",a="Einheimische Zwerge halten ein Loch im dicken Eis offen, um in Dun Moroghs eisiger Kälte an Frischwasser zu gelangen.",al={"eisloch","zugang zu wasser","warum ist das eis aufgebrochen"}},{q="Welche Gefahren lauern rund um den Helmsbettsee?",a="Das feste Eis lässt sich sicher überqueren, doch wilde Bestien und vertriebene Troggs streifen am Ufer umher. Feindselige Dunkeleisenzwerge besetzen ein altes Gebäude südlich des Wassers und vertreiben jeden, der sich nähert.",al={"bedrohungen am helmsbettsee","wer greift hier an","feinde in der nähe"}},{q="Wer ist Narm Faulk?",a="Narm Faulk ist ein Zwerg, dessen Leichnam am Ufer des Helmsbettsees liegt. Er fiel, als die Bedrohungen und die Zahl der Dunkeleiseninfiltratoren in der Gegend plötzlich zunahmen.",al={"narm faulks leichnam","toter zwerg am see","leichnam am helmsbettsee"}},{q="Halten die Dunkeleisenzwerge den See offiziell besetzt?",a="Die Dunkeleisenzwerge haben den See nicht erobert, doch ein bewaffneter Trupp hat ein verlassenes Gebäude unmittelbar südlich davon eingenommen. Sie nutzen es als vorgeschobene Stellung für Vorstöße ins Zentrum von Dun Morogh.",al={"dunkeleisenzwerge am see","hütte der dunkeleisenzwerge"}}},fx={ba815d26={q="Was ist der Helmsbettsee?",a="Der Helmsbettsee ist ein kleiner, größtenteils zugefrorener See, eingebettet im südöstlichen Dun Morogh. Ein Loch im dicken Eis wird offen gehalten, um Zugang zu frischem Trinkwasser zu ermöglichen. Während die gefrorene Oberfläche selbst festen Halt bietet, ist die Wildnis, die den See umgibt, weit weniger einladend und wimmelt von Raubtieren, umherstreifenden Troggs und feindseligen Infiltratoren der Dunkeleisenzwerge.",al={"helmsbettsee","wo ist der helmsbettsee","was ist dieser see"}}},fp="15,164,23.254.0,59.104.0,41.191.0,18.148.0,56.191.0"}
P.entries["subzone:heroes-vigil"] = {n="Heldenwache",s="Auf der Insel im Steinhügelsee liegt die Heldenwache vernachlässigt und von abtrünnigen Magiern überrannt. Der Stein der Erinnerung ehrt jene, die im Ersten Krieg fielen.",h="Auf der Insel im Steinhügelsee liegt die Heldenwache vernachlässigt und von abtrünnigen Magiern überrannt.",kw={"wald von elwynn","henze faulk","heldenwache","schurkenmagier","der steinhügelsee","stein der erinnerung"},ang={["class:Mage"]="Als Magier findet Ihr abtrünnige Magier auf heiligem Boden vor, die gefährliche Künste ohne die Disziplin oder Billigung der Academy of Arcane Sciences ausüben.",["race:Human"]="Als Mensch aus Sturmwind seht Ihr in diesem heiligen Steinkreis eine bittere Erinnerung an den Blutzoll des Ersten Krieges und das Versagen des Königreichs, sein Erbe zu schützen."},sec={{t="Ein vergessenes Denkmal",b="Die Heldenwache liegt rings um den Stein der Erinnerung auf einer Insel im Steinhügelsee. Ihr nach dem Ersten Krieg errichteter, beschrifteter Steinkreis ehrt die Soldaten und Bürger, die starben, als die Alte Horde Goldhain und die umliegenden Täler plünderte. Einst ein heiliger Ort des Glaubens und der Aufopferung, ist das Denkmal aus Sturmwinds Blick geraten. Sein Gelände ist überwuchert, und keine Soldaten kümmern sich darum."},{t="Von Abtrünnigen beansprucht",b="Ohne eine Garnison des Königreichs haben Ausgestoßene die Insel für sich beansprucht. Schurkenmagier kontrollieren den Steinhügelsee und das Gelände des Denkmals. Sie praktizieren wilde, undisziplinierte Magie außerhalb der Aufsicht der Kirin Tor und der Academy of Arcane Sciences. Nahe den Steinen liegt Henze Faulks Leichnam unter weiteren tragischen Opfern. Reisende können sich nur fragen, ob der Schrein jemals wieder Frieden finden wird."}},faq={{q="Was ist die Heldenwache?",a="Die Heldenwache liegt auf einer Insel im Steinhügelsee im östlichen Wald von Elwynn. Ihr Steinkreis und ihr Denkmal ehren jene, die im Ersten Krieg fielen.",al={"heldenwache","was ist die heldenwache","inselschrein elwynn"}},{q="Woran erinnert der Stein der Erinnerung?",a="Der Stein der Erinnerung ehrt die Bürger und Verteidiger, die starben, als die orkische Horde im Ersten Krieg Goldhain plünderte und den östlichen Wald von Elwynn verwüstete.",al={"stein der erinnerung","bedeutung des denkmals","was ist der stein der erinnerung"}},{q="Wer kontrolliert die Heldenwache heute?",a="Feindselige Schurkenmagier halten die Insel und die Heldenwache besetzt. Sie handeln außerhalb von Sturmwinds Gesetz und der Aufsicht etablierter magischer Institutionen.",al={"wer ist bei der heldenwache","feinde der heldenwache","magier am see"}},{q="Warum hat Sturmwind die Heldenwache vernachlässigt?",a="Sturmwind hat die Heldenwache unverteidigt und weitgehend vergessen zurückgelassen, weil König Varian Wrynn vermisst wird und innere Zwietracht, Räuber und Monstereinfälle das Reich überfordern. Abgelegene Schreine sind ohne Schutz geblieben.",al={"warum ist sie verlassen","warum hat sturmwind sie vergessen","vergessener schrein"}},{q="Wer ist Henze Faulk?",a="Henze Faulk ist ein Zwerg, dessen Leichnam nahe dem Denkmal liegt. Streitkräfte der Bruderschaft der Defias streckten ihn nieder, als er seinen Freund Gazin Tenorm rettete.",al={"henze faulks leichnam","wer ist der tote auf der insel"}}},fx={e301b338={q="Ist die Heldenwache gefährlich?",a="Ja, sehr, für Unvorsichtige. Die Insel im Steinhügelsee ist vollständig unter die Kontrolle von abtrünnigen Magiern und Beschwörern geraten, die im Exil verbotene Künste praktizieren. Sie greifen jeden an, der sich dem Denkmal nähert, was einen eigentlich friedlichen Ort des Gedenkens in eine tödliche Falle für Reisende verwandelt.",al={"ist die heldenwache sicher","heldenwache gefahr","heldenwache feindselig"}},c198f6a4={q="Warum heißt es Heldenwache?",a="Der Ort wurde als dauerhafte Wache und Mahnmal für die gefallenen Verteidiger des Ersten Krieges errichtet. In seinem Zentrum steht der Stein des Gedenkens, der zu Ehren der Soldaten und Zivilisten errichtet wurde, die abgeschlachtet wurden, als die Alte Horde durch den Wald von Elwynn tobte und Goldhain plünderte.",al={"warum heldenwache genannt","heldenwache namensbedeutung","wer sind die dort geehrten helden"}}},fp="13,156,20.392.0,20.379.0,22.146.0,47.162.0,33.145.0,38.235.0,19.145.0"}
P.entries["subzone:hetaera-s-clutch"] = {n="Hetaeras Gelege",s="Hetaeras Brut nistet nun in den versunkenen Ruinen unter Azsharas Bucht der Stürme. Einst kamen Nachtelfen in diesen Tempel, um Elune anzubeten.",h="Hetaeras Brut nistet nun in den versunkenen Ruinen unter Azsharas Bucht der Stürme.",kw={"azshara","die bucht der stürme","elune","hetaera","hetaeras gelege","hydra","versunkener tempel","tempel von elune"},ang={["class:Druid"]="Wenn Ihr als Druide die Bucht der Stürme erkundet, hütet Euch vor den Hydren, die dieses uralte Heiligtum beanspruchen. Sie sind Eindringlingen feindlich gesinnt.",["race:NightElf"]="Als Nachtelf mögt Ihr das versunkene Heiligtum Elunes, das nun ein Hydranest ist, als Erinnerung an die in der Sundering verlorene Zivilisation betrachten."},sec={{t="Ein ertrunkenes Heiligtum",b="Bevor die Great Sundering das uralte Kalimdor zerriss, kamen Nachtelfen in diesen Tempel, um Elune anzubeten. Das Heiligtum versank in der Bucht der Stürme, wo seine Säulen und Hallen seit zehntausend Jahren unter dem Meer ruhen. Nun bedecken die Gezeiten jedes Zeichen der Verehrung, und die Ruinen der Kaldorei liegen unter den Wellen."},{t="Domäne der Brutelmutter",b="Hetaera hat ihr Nest im versunkenen Heiligtum. Die gewaltige Hydra hat viele Köpfe und durchstreift die nahen Küstengewässer und Felseninseln. Ihre Nachkommen, die Spawn of Hetaera, streifen durch die verfallenen Torbögen und Korridore. Sie greifen jeden Oberflächenbewohner an, der sich in die Bucht hinabzuwagen traut."}},faq={{q="Wofür wurde Hetaeras Gelege ursprünglich erbaut?",a="Bevor Hetaeras Gelege versank, war es ein Tempel, der Elune, der Mondgöttin, geweiht war. Er wurde zur Blütezeit des alten nachtelfischen Reiches erbaut und versank während der Great Sundering im Ozean.",al={"was ist hetaeras gelege","was war dieser tempel","hetaeras gelege geschichte"}},{q="Wo befindet sich Hetaeras Gelege?",a="Hetaeras Gelege ruht tief unter der Bucht der Stürme, vor Azsharas zerklüfteter Südküste.",al={"wo ist hetaeras gelege","hetaeras gelege standort","wie findet man hetaeras gelege"}},{q="Wer ist Hetaera?",a="Hetaera ist eine dreiköpfige Hydra, die Azsharas Gewässer durchstreift. Ihre Kinder bevölkern den versunkenen Tempel, während sie meist knapp nördlich von Clutch schwimmt oder sich auf nahe gelegenen Inseln vor der Küste sonnt.",al={"wer ist hetaera","wo ist hetaera","was ist hetaera"}},{q="Welche Kreaturen bewohnen die versunkenen Ruinen?",a="Hetaeras Brut bewohnt die versunkenen Hallen. Diese wilden Wasserhydren verteidigen ihren Nistplatz gegen Eindringlinge, die zu nahe heranschwimmen.",al={"welche mobs sind in hetaeras gelege","was lebt in hetaeras gelege"}}},fp="16,138,19.317.0,25.277.0,47.196.0,34.91.0,15.200.0,43.136.0"}
P.entries["subzone:hidden-grove"] = {n="Der Versteckte Hain",s="Wilde Mondkin bewachen nun den Versteckten Hain im Nordosten von Winterquell.",h="Wilde Mondkin bewachen nun den Versteckten Hain im Nordosten von Winterquell.",kw={"krater","hasen","der versteckte hain","mondpirscher","winterquell"},ang={["class:Druid"]="Als Druide könnt Ihr die Mondkin des Kraters als wilde Natur betrachten, die sich erbittert zur Wehr setzt. Ihre Gegenwart mag spirituelle Fragen aufwerfen."},sec={{t="Ein abgeschiedener Zufluchtsort",b="Klippen schützen den Versteckten Hain vor den eisigen Winden von Winterquell. Schneebestäubte Bäume füllen den eingesunkenen Krater, der fast völlig von der Außenwelt abgeschnitten ist. Sein verborgener Rand ist schwer zu erreichen. Ihr müsst einen steilen Abstieg riskieren oder einen schmalen Höhlengang im südöstlichen Bergrücken finden.\n\nEinst lebten weiße Hasen ungestört im Tal. Nun haben angriffslustige wilde Mondkin die Lichtung eingenommen, und unachtsame Reisende können dort in einen Hinterhalt geraten."}},faq={{q="Wie gelangt man in den Versteckten Hain?",a="Der sicherste Weg in den Versteckten Hain führt durch eine verborgene Höhle in der südöstlichen Felswand. Ihr könnt den steilen Rand hinabklettern, doch ein Sturz könnte tödlich enden.",al={"versteckten hain betreten","eingang versteckter hain","wo ist die höhle"}},{q="Welche Kreaturen leben im Versteckten Hain?",a="Feindselige wilde Mondkin bewachen nun den Versteckten Hain. Bevor sie kamen, lebten harmlose weiße Hasen friedlich auf der Lichtung.",al={"was gibt es im versteckten hain","gegner im versteckten hain","wer lebt hier"}},{q="Wo in Winterquell liegt dieser Hain?",a="Der Versteckte Hain liegt im äußersten Nordosten von Winterquell, umschlossen von hoch aufragenden Felsklippen.",al={"lage versteckter hain","wo liegt der versteckte hain"}}},fp="12,69,20.411.0,37.160.0,40.118.0,44.90.0"}
P.entries["subzone:hidden-path"] = {n="Verborgener Pfad",s="In Durotar steigen junge Schamanen auf dem Verborgenen Pfad zum Geisterfelsen hinauf. Seine Höhen bieten einen Blick nach Westen über das Brachland.",h="In Durotar steigen junge Schamanen auf dem Verborgenen Pfad zum Geisterfelsen hinauf.",kw={"brachland","durotar","verborgener pfad","schamane","geisterfelsen","das tal der prüfungen"},ang={["class:Shaman"]="Als Schamane unternehmt Ihr auf dem Verborgenen Pfad Euren ersten wahren körperlichen und spirituellen Aufstieg. Er prüft Eure Wahrnehmung, bevor Ihr am Geisterfelsen Zwiesprache mit den Erdgeistern haltet.",["faction:Horde"]="Obwohl er den Schamanen heilig ist, ist der Verborgene Pfad ein unbefestigter Durchgang oberhalb des Tals der Prüfungen. Er hinterlässt einen blinden Fleck, der ein wachsames Auge erfordert."},sec={{t="Ein heiliger Aufstieg",b="Oberhalb des Tals der Prüfungen führt der Verborgene Pfad durch rote Gipfel und ist vom Grund des Canyons aus schwer zu erkennen. Mentoren schicken junge Schamanen auf diesen Weg, um ihre Aufmerksamkeit und Disziplin zu prüfen. Dann halten sie am Geisterfelsen Zwiesprache mit den Geistern. Von den höchsten Abschnitten aus könnt Ihr nach Westen über die sanft gewellten Savannen des Brachlands blicken."},{t="Strategische Schwachstelle",b="Der Verborgene Pfad durchquert die natürlichen Verteidigungsanlagen rund um das Tal. Ein niedriger Pass führt in Richtung Ratschet und zur Straße nach Orgrimmar. Er umgeht die üblichen Kontrollpunkte des Canyons. Daher fürchten die Verteidiger, dass Infiltratoren der Allianz den stillen Pfad zu den Übungsplätzen der Horde nehmen könnten."}},faq={{q="Wohin führt der Verborgene Pfad?",a="Der Verborgene Pfad steigt vom Tal der Prüfungen in die zerklüfteten Felsen hinauf und erreicht den Geisterfelsen, wo Schamanen Zwiesprache mit den Elementen halten. Seine Gebirgspässe bieten auch Verbindungen in Richtung Brachland und Küste.",al={"verborgener pfad ziel","wohin führt der verborgene pfad","verborgener pfad führt zu"}},{q="Warum ist der Pfad für Schamanen bedeutsam?",a="Junge Schamanen im Tal der Prüfungen beschreiten den Verborgenen Pfad im Rahmen ihrer ersten Elementarprüfungen. Der Aufstieg führt zum Geisterfelsen, wo sie Sapta trinken, um Zwiesprache mit den Geistern zu halten.",al={"schamanenpfad tal der prüfungen","geisterfelsen pfad","schamanenquest pfad"}},{q="Könnten Feinde den Verborgenen Pfad nutzen, um das Tal der Prüfungen anzugreifen?",a="Ja. Niedrige Durchgänge entlang des Verborgenen Pfades umgehen die üblichen bewachten Zugänge des Tals. Ein Stoßtrupp der Allianz aus Ratschet oder von der Küste könnte an den Spähern der Horde vorbeischlüpfen und unbemerkt das Übungsgelände betreten.",al={"verborgener pfad invasion der allianz","ist das tal der prüfungen verwundbar","tal der prüfungen hintereingang"}},{q="Was könnt Ihr vom höchsten Punkt des Pfades aus sehen?",a="Vom höchsten Punkt des Verborgenen Pfades aus könnt Ihr nach Westen über das Brachland und über die roten Canyons Durotars blicken.",al={"verborgener pfad aussicht","aussichtspunkt verborgener pfad"}}},fx={d2b4f0e1={q="Was ist der Verborgene Pfad?",a="Der Verborgene Pfad ist ein abgelegener Bergpfad, der sich durch die Felsen windet, die an das Tal der Prüfungen in Durotar grenzen. Er wird weitgehend vor den Augen der Öffentlichkeit verborgen gehalten und dient als geheimer Durchgang hinauf zum Geisterfelsen, einem heiligen Ort, an dem junge Schamanen mit den Elementargeistern kommunizieren. Von seinen höheren Kämmen aus überblickt er das zerklüftete Grenzland, das sich in Richtung Brachland erstreckt.",al={"verborgener pfad durotar","was ist der verborgene pfad","über den verborgenen pfad"}},["46af627a"]={q="Warum heißt es Verborgener Pfad?",a="Der Pfad verdankt seinen Namen seiner Verborgenheit. Eingebettet in die Felsen, die das Tal der Prüfungen säumen, ist er keine offensichtliche Straße oder markierte Route, sondern ein versteckter Weg durch die felsige Barriere. Ihn zu finden ist traditionell Teil der Prüfung eines Initianden, bei der ihre Wahrnehmung getestet wird, bevor sie den Geisterfelsen erreichen.",al={"warum verborgener pfad genannt","verborgener pfad namensbedeutung","verborgener pfad namensherkunft"}},a83f5cf6={q="Ist der Verborgene Pfad gefährlich?",a="Der Pfad selbst ist ruhig und frei von dauerhaften Siedlungen oder Monsterlagern, doch seine Isolation stellt ein strategisches Problem dar. Da eine tiefer gelegene Lücke entlang des Pfades einen unbewachten Durchgang zur Küste, nach Ratschet oder sogar nach Norden in Richtung Orgrimmar bietet, stellt er eine unbewachte Flanke dar, über die Infiltratoren der Allianz theoretisch in das Tal der Prüfungen schlüpfen könnten.",al={"ist der verborgene pfad sicher","verborgener pfad gefahr","feinde verborgener pfad"}}},fp="11,113,15.323.0,23.271.0,32.199.0,38.182.0,65.202.0,42.106.0"}
P.entries["subzone:high-rise"] = {n="High Rise",s="Auf Donnerfels’ Gipfel versammelt High Rise die Taurenstämme um sein zentrales Feuer hoch über Mulgore.",h="Auf Donnerfels’ Gipfel versammelt High Rise die Taurenstämme um sein zentrales Feuer hoch über Mulgore.",kw={"amphitheater","aska's kitchen","freudenfeuer","high rise","mulgore","donnerfels","wind rider-horst"},ang={["profession:Cooking"]="In Aska's Kitchen auf High Rise könnt Ihr bei den Meistern an der Feuergrube das Kochen über offener Flamme lernen. Es ist Donnerfels’ wichtigste Anlaufstelle, um dieses Handwerk zu erlernen.",["race:Tauren"]="Als Tauren seht Ihr, wie High Rise Eure Hauptstadt krönt und die Stämme zusammenführt. Jäger, Schamanen und Älteste versammeln sich um das hoch gelegene Gemeinschaftsfeuer."},sec={{t="Gipfel des Tafelbergs",b="Ihr findet High Rise auf Donnerfels’ Gipfel, wo freie Winde über Mulgore und die wogenden Ebenen wehen. Tauren versammeln sich in seinem Freiluft-Amphitheater um eine Feuerstelle, um Stammesbekanntmachungen zu hören und Entscheidungen mitzuerleben. Zelte und hölzerne Stände beherbergen Händler, Waffenkammern und Kochlehrer, darunter Aska's Kitchen und Mountaintop Bait & Tackle.\n\nGewaltige hölzerne Aufzüge verbinden die unteren Ebenen mit Mulg ores Prärieboden, doch keiner führt von der Prärie nach High Rise. Um hierher hinaufzugelangen, nehmt den Aufstieg vom Wind Rider-Horst oder überquert eine Seilbrücke von der Anhöhe der Ältesten oder der Anhöhe der Jäger."}},faq={{q="Wie erreicht Ihr High Rise?",a="Ihr erreicht High Rise von den unteren Ebenen über den zentralen Wind Rider-Horst oder über eine Hängebrücke von der Anhöhe der Ältesten oder der Anhöhe der Jäger. Kein Aufzug verbindet Mulg ores Ebenen direkt mit dieser Höhenstufe.",al={"wie gelangt man nach high rise","zugang zu high rise","aufstieg nach high rise"}},{q="Welche Dienste gibt es auf High Rise?",a="Handwerker und Versammlungsplätze unter freiem Himmel füllen High Rise. Aska's Kitchen bietet Kochunterricht, Mountaintop Bait & Tackle verkauft Angelausrüstung, und Ragetotem Arms sowie Thunderhoof's Firearms gehören zu den Waffenhändlern.",al={"lehrer auf high rise","geschäfte auf high rise","was gibt es auf high rise"}},{q="Wozu dient das Amphitheater auf High Rise?",a="Das Freiluft-Amphitheater versammelt Tauren um ein zentrales Freudenfeuer. Dort hören sie Neuigkeiten, beraten über Stammesangelegenheiten und werden auf dem Tafelberg Zeugen wichtiger Verkündungen.",al={"freudenfeuer auf high rise","auditorium auf high rise","versammlungsort der tauren"}}},fx={c9070a2e={q="Was ist High Rise?",a="High Rise ist die oberste Ebene der zentralen Mesa von Donnerfels. Hoch über den windgepeitschten Ebenen von Mulgore gelegen, dient sie als bürgerliches und zeremonielles Herz der Hauptstadt der Tauren. Sie verfügt über ein Freiluftamphitheater, das um ein zentrales Lagerfeuer angeordnet ist, verschiedene Handelsgeschäfte und direkte Seilbrücken, die nach außen sowohl zur Anhöhe der Jäger als auch zur Anhöhe der Ältesten führen.",al={"was ist high rise","high rise donnerfels","erzähle mir von high rise"}},b703b2f4={q="Wer lebt in High Rise oder leitet es?",a="High Rise dient als Sitz der Führung der Tauren innerhalb von Donnerfels. Hochhäuptling Cairne Bluthuf und der Ältestenrat beaufsichtigen die Stammesangelegenheiten von diesem Gipfel aus, wo sich die Bevölkerung versammeln kann, um wichtige Dekrete und schicksalhafte Entscheidungen mitzuerleben. Die Ebene ist auch die Heimat angesehener Handwerker, Waffenschmiede, Köche und Angler, die Stände und Wohnungen rund um das zentrale Gelände unterhalten.",al={"wer leitet high rise","wer ist für high rise verantwortlich","high rise bewohner"}},["8703b6d5"]={q="Ist High Rise gefährlich?",a="Nein, High Rise ist vollkommen friedlich und wird von den wachsamen Klippenwächtern von Donnerfels gut bewacht. Die einzige wirkliche Gefahr, der Ihr ausgesetzt seid, ist der gefährliche, steile Abgrund am Rand der Mesa oder ihre schmalen Seilbrücken, falls Ihr den Halt verlieren solltet.",al={"ist high rise sicher","gefahr high rise","bedrohungen high rise"}},e2f731cc={q="Warum heißt es High Rise?",a="Die Mesa von Donnerfels ist in Ebenen unterteilt, wobei High Rise den höchsten Punkt des zentralen Plateaus einnimmt. Da sie über der unteren und der mittleren Ebene liegt, verdient sie ihren Namen dadurch, dass sie die höchste Ebene des zentralen Pfeilers der Stadt ist.",al={"warum high rise","high rise namensbedeutung","high rise ursprung"}}},fp="9,95,18.584.0,31.200.0,41.215.0,51.166.0"}
P.entries["subzone:high-seat"] = {n="High Seat",s="König Magni Bronzebart hält im High Seat Hof, zwischen den Commons und der Großen Schmiede. Seine Berater und Historiker versammeln sich dort, und ein versiegelter Durchgang führt hinab in die Altstadt von Eisenschmiede.",h="König Magni Bronzebart hält im High Seat Hof, zwischen den Commons und der Großen Schmiede.",kw={"archesonus","barin redstone","bronzebeard","high seat","eisenschmiede","magni","thron"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr Euch für zwergischen Rat an den High Seat wenden. Gesandte, Berater und königliche Erlasse kommen dort zusammen.",["race:Dwarf"]="Als Zwerg blickt Ihr zum High Seat, wo König Magni Bronzebart das Volk von Khaz Modan führt und dessen Herrschaft fortsetzt."},sec={{t="Herz der Zwergenherrschaft",b="König Magni Bronzebart empfängt im High Seat Bittsteller und berät sich mit seinen Beratern. Die Königliche Historikerin Archesonus und Senator Barin Redstone stehen ihm zur Seite. Von hier aus lenkt Magni die Verteidigung der nördlichen Bastionen der Allianz. Der High Seat ist der Herrschaftssitz von Khaz Modan, und er führt das Königreich durch unruhige Zeiten in ganz Azeroth."},{t="Tor zur Altstadt von Eisenschmiede",b="Ein schweres Tor im hinteren Teil des Thronsaals führt hinab in die Altstadt von Eisenschmiede. Die tiefer gelegenen Ruinen sind die angestammten Hallen, die die Zwerge in den Fels schlugen, bevor die Stadt um die Große Schmiede herum umgestaltet wurde. Der Durchgang ist versiegelt und bewacht und hält den allgemeinen Verkehr von den uralten Hallen unter der Hauptstadt fern."}},faq={{q="Wer herrscht vom High Seat aus?",a="König Magni Bronzebart regiert Eisenschmiede vom Thron im High Seat aus. Er hört seine Untertanen an und lenkt die Geschicke des Bronzebeard-Clans. Außerdem stimmt er militärische und diplomatische Angelegenheiten mit der Großen Allianz ab.",al={"wer sitzt auf dem thron","könig von eisenschmiede","magnis thronsaal"}},{q="Wo liegt der High Seat in Eisenschmiede?",a="Der High Seat liegt zwischen den Commons und der Großen Schmiede und ist direkt mit dem äußeren Ring von Eisenschmiede verbunden. Bürger und Gesandte können die Kammer von dort aus erreichen.",al={"wo ist der high seat","high seat finden","lage des thronsaals"}},{q="Was ist der versiegelte Gang im hinteren Teil des Thronsaals?",a="Der große Torbogen im hinteren Teil des High Seat führt in die Altstadt von Eisenschmiede, die angestammten Ruinen unter der heutigen Bergstadt. Der Zugang zu den unteren Gängen ist beschränkt.",al={"tür hinter magni","tür zur altstadt von eisenschmiede","keller des high seat"}},{q="Wer berät den König hier noch?",a="Die Königliche Historikerin Archesonus und Senator Barin Redstone beraten König Magni im High Seat.",al={"npcs im high seat","magnis berater"}}},fx={dcfee083={q="Was ist der High Seat?",a="Der High Seat, auch bekannt als der Hohe Thron, ist der große Thronsaal des Königreichs Eisenschmiede. Im Herzen der Bergstadt, direkt neben der Großen Schmiede gelegen, ist dieser große Steinsaal der Ort, an dem der Zwergenmonarch Hof hält, Abgesandte empfängt und Petitionen von Untertanen aus ganz Khaz Modan anhört.",al={"was ist der high seat","eisenschmiede thronsaal","high seat eisenschmiede"}},e56e0189={q="Ist der High Seat gefährlich?",a="Nicht, wenn Ihr ein Freund der Allianz seid. Er ist das Herz der zwergischen Verwaltung, schwer bewacht von den persönlichen Beschützern des Königs und erfahrenen zwergischen Wachen. Es sei denn, eine einfallende Armee der Horde schafft es, die tiefen Bergverteidigungen von Eisenschmiede zu durchbrechen, haben Besucher, die unter dem Frieden des Königs stehen, in diesen Hallen nichts zu befürchten.",al={"ist der high seat sicher","high seat gefahr","bedrohungen im high seat"}}},fp="9,181,21.341.0,24.292.0,29.216.0,44.155.0,59.166.0,45.85.0"}
P.entries["subzone:high-wilderness"] = {n="Die obere Wildnis",s="Im Westen von Feralas erstreckt sich die obere Wildnis vom Verdantis bis zur Vergessenen Küste. Ihre hoch aufragenden Bäume bieten Wildtieren, umherstreifenden Treants und gefährlichen Bestien Zuflucht.",h="Im Westen von Feralas erstreckt sich die obere Wildnis vom Verdantis bis zur Vergessenen Küste.",kw={"feralas","die vergessene küste","die obere wildnis","hippogryphen","treants","verdantis","yetis"},ang={["class:Druid"]="Die uralten Treants und die lebendige Tierwelt der oberen Wildnis offenbaren Kalimdors urwüchsige Kraft, unberührt von der Zivilisation in den östlichen Landen.",["class:Hunter"]="Grimmige Bären, Wölfe und wilde Hippogryphen bevölkern die obere Wildnis, wo Ihr mächtige Bestien aufspüren und zähmen könnt."},sec={{t="Das urzeitliche Blätterdach",b="Die obere Wildnis erstreckt sich über den Westen von Feralas unter so gewaltigen Bäumen und so dichtem Blattwerk, dass kaum Himmel hindurchscheint. Wölfe, Bären, Hippogryphen und Yetis streifen darunter umher. Uralte Treants wandern zwischen den Wurzeln, während aggressive Ogerclans schattige Lichtungen besetzt halten. Das Unterholz verbirgt Raubtiere und Gefahren aus einem früheren Zeitalter, weshalb Reisende wachsam bleiben müssen."}},faq={{q="Wo liegt die obere Wildnis?",a="Die obere Wildnis umfasst die Waldgebiete im Westen von Feralas, westlich des Verdantis. Sie reicht bis zu den Klippen und Ufern entlang der Vergessenen Küste.",al={"obere wildnis lage","wo liegt die obere wildnis","obere wildnis feralas"}},{q="Welche Kreaturen durchstreifen die obere Wildnis?",a="Bären, Wölfe, Hippogryphen und wilde Yetis durchstreifen den Wald. Umherstreifende Treants und aggressive Oger leben ebenfalls unter dem Blätterdach.",al={"obere wildnis tierwelt","kreaturen in der oberen wildnis","bestien feralas"}}},fp="15,171,21.350.0,37.151.0,40.130.0"}
P.entries["subzone:highperch"] = {n="Der Steilhang",s="Wilde Wyvern nisten zwischen den Felsen des Steilhangs über der westlichen Schlucht von Tausend Nadeln. Ihre Rudel bewachen die Höhen und ihre Jungen.",h="Wilde Wyvern nisten zwischen den Felsen des Steilhangs über der westlichen Schlucht von Tausend Nadeln.",kw={"horst","der steilhang","nest","pao'ka bergrausch","tausend nadeln","wind rider","wyvern"},ang={["class:Hunter"]="Als Jäger könnt Ihr wilde Wyvern in ihrer natürlichen Heimat bei der Jagd und beim Bewachen ihrer Nester beobachten.",["faction:Horde"]="Als Champion der Horde könnt Ihr die wilden Verwandten der Windreiter sehen, die Euer Volk durch Kalimdor tragen."},sec={{t="Horst der Wyvern",b="Der Steilhang erhebt sich aus dem Schluchtboden und bietet Kalimdors einheimischen Wyvern einen zerklüfteten Zufluchtsort. Seine Höhe schützt sie vor Raubtieren und ermöglicht einen ungehinderten Start zu Jagdflügen über Tausend Nadeln.\n\nWyvernrudel bewachen ihre Nester unter wachsamen Patriarchen und Matriarchinnen. Sie verteidigen ihr Revier erbittert gegen jeden Eindringling, der ihr hoch gelegenes Reich erreicht."},{t="Zuflucht in den Höhen",b="Die Klippen locken einige Reisende und Jäger an, die den Aufstieg wagen wollen. Pao'ka Bergrausch, ein Taurenspäher, sitzt auf den Höhen fest und braucht Hilfe, um den Weißgipfelposten zu erreichen.\n\nWer die Klippen erklimmt, muss sich Dutzenden messerscharfer Klauen und giftiger Schwänze stellen."}},faq={{q="Welche Kreaturen leben am Steilhang?",a="Wilde Wyvern und Windreiter leben am Steilhang. Wachsame Patriarchen, ihre Gefährten und ausgewachsene, durch die Lüfte gleitende Tiere verteidigen ihre Nester auf den Klippen.",al={"steilhang bestien","was gibt es am steilhang","steilhang gegner"}},{q="Wo liegt der Steilhang?",a="Der Steilhang erhebt sich im Westen von Tausend Nadeln. Eine gewundene Rampe führt an der Südwand der Schlucht entlang hinauf in die Höhen.",al={"steilhang lage","wie den steilhang finden","wo ist der steilhang"}},{q="Warum ist der Steilhang für die Horde von Bedeutung?",a="Wyvern, auch Windreiter genannt, sind wichtige Flugreittiere der Horde. Sie verbündeten sich während des Dritten Krieges mit den Orcs, und Horste wie der Steilhang beherbergen einen gedeihenden Wildbestand.",al={"verbindung der horde zum steilhang","wyvern und horde","warum ist der steilhang den orcs wichtig"}},{q="Wer ist Pao'ka Bergrausch?",a="Pao'ka Bergrausch ist ein Taurenspäher, der zwischen den Wyvernnestern des Steilhangs festsitzt. Er braucht Geleitschutz zum Weißgipfelposten.",al={"pao'ka bergrausch","tauren am steilhang","wer sitzt am steilhang fest"}}},fx={["0cf6e9b4"]={q="Was ist Der Steilhang?",a="Der Steilhang ist eine erhöhte Mesa und ein Nistplatz, der sich über die westlichen Schluchten der Tausend Nadeln erhebt. Er dient als einer der primären natürlichen Lebensräume für die stolzen wilden Wyvern der Region, gefüllt mit ihren Nestern und hochfliegenden Schwärmen.",al={"was ist der steilhang","der steilhang info","über den steilhang"}},a95be4dc={q="Was ist am Steilhang passiert?",a="Seit Generationen bauen wilde Wyvern ihre Nester hoch oben auf diesem Zufluchtsort an der Klippe. Der Tauren-Späher Pao'ka Bergrausch ist inmitten der Felsen gestrandet und sucht Hilfe, um zum Weißgipfelposten zurückzukehren.",al={"der steilhang geschichte","was ist hier passiert","der steilhang vergangenheit"}},b4e36f31={q="Ist Der Steilhang gefährlich?",a="Ja. Die wilden Wyvern, die in den Felsen nisten, verteidigen ihre Gelege und ihr Territorium erbittert. Gefährten und mächtige Patriarchen stürzen sich auf jeden Eindringling, der vom Schluchtboden heraufklettert und sich zu nahe an ihre Nester wagt.",al={"ist der steilhang gefährlich","der steilhang gefahren","gefahr steilhang"}}},fp="9,138,20.351.0,23.259.0,33.128.0,27.112.0,42.178.0,28.120.0"}
P.entries["subzone:hillsbrad-fields"] = {n="Die Felder von Hillsbrad",s="Im westlichen Vorgebirge des Hügellands sind die Felder von Hillsbrad ständigen Angriffen aus dem nahen Tarrens Mühle ausgesetzt. Bauern und Miliz verteidigen eine der wenigen Menschengemeinschaften im einstigen Lordaeron, die der Geißel und dem Scharlachroten Kreuzzug widerstehen.",h="Im westlichen Vorgebirge des Hügellands sind die Felder von Hillsbrad ständigen Angriffen aus dem nahen...",kw={"battle of hillsbrad","darthalia","farmer getz","farmer ray","hillsbrad","die felder von hillsbrad","magistrate burnside","süderstade","tarrens mühle","verringtan"},ang={["faction:Alliance"]="Die Felder von Hillsbrad liefern Nahrung und stehen als Zeichen für Lordaerons ungebrochenen Geist. Schützt sie vor den Angriffen der Verlassenen.",["faction:Horde"]="Hochexekutorin Darthalia fordert die Zerschlagung von Hillsbrads Bauernhöfen und Miliz, um die südliche Grenze für die Verlassenen zu sichern."},sec={{t="Eine unbeugsame Bastion Lordaerons",b="Die Felder von Hillsbrad erstrecken sich von Darrow Hill bis zum Azurschacht. Obstgärten, Kürbisfelder und Weiden versorgen dort Süderstade und den verbliebenen Widerstand der Allianz. Während weite Teile Lordaerons dem Untod verfielen, harrten die Menschen aus und bewahrten den königlichen Wappenrock und die Heraldik ihres gefallenen Königreichs.\n\nMagistrate Burnside und der Rat von Hillsbrad führen die Gemeinde als unabhängige Bürgerschaft unter ständiger Belagerung. Verringtan, der örtliche Schmied, und seine Lehrlinge bewaffnen Bauern und Arbeiter, damit sie ihr Land verteidigen können."},{t="Front des untoten Vormarschs",b="Hochexekutorin Darthalia und die Streitkräfte der Verlassenen in Tarrens Mühle haben es auf Hillsbrads fruchtbare Felder abgesehen. Unterstadt sieht in der florierenden Menschensiedlung eine Bedrohung an seiner Südflanke und befiehlt deshalb ständige Überfälle auf Ernten, Vieh, Ratsmitglieder und Bauern. Als Reaktion haben Hillsbrads Verteidiger eine abgehärtete Miliz gebildet. Farmer Ray und Farmer Getz organisieren Hinterhalte und bekämpfen die Untoten, um ihr Zuhause zu schützen."}},faq={{q="Warum betreiben hier noch lebende Menschen Landwirtschaft?",a="Hillsbrad und das benachbarte Süderstade gehören zu den wenigen Siedlungen Lordaerons, die während des Dritten Krieges der vollständigen Vernichtung durch die Geißel entgingen. Ihre Bewohner blieben, um ihre Heimat wiederaufzubauen und zu erhalten, während andere nach Süden flohen oder sich dem Scharlachroten Kreuzzug anschlossen.",al={"warum sind menschen in hillsbrad","wer lebt auf den feldern von hillsbrad","sind die bauern am leben"}},{q="Wer herrscht über die Stadt und die Felder?",a="Magistrate Burnside regiert die Stadt und die Felder gemeinsam mit Clerk Horrace Whitesteed und dem Rat von Hillsbrad vom Rathaus aus. Farmer Ray und Farmer Getz bewirtschaften nahe gelegene Landgüter, und Verringtan rüstet die Stadtwache aus.",al={"wer führt hillsbrad","führung von hillsbrad","magistrat von hillsbrad"}},{q="Warum greifen die Verlassenen die Bauernhöfe an?",a="Hochexekutorin Darthalia in Tarrens Mühle betrachtet Hillsbrad als gefährlichen Stützpunkt der Allianz an der Grenze der Verlassenen. Auf Befehl Unterstadts sollen Soldaten die Versorgungslinien der Menschen unterbrechen, indem sie Nahrungsvorräte vernichten, Vieh abschlachten und Stadtoberhäupter töten, um den Weg für die Vorherrschaft der Verlassenen im Vorgebirge freizumachen.",al={"warum greifen verlassene hillsbrad an","grund für battle of hillsbrad","angriffe aus tarrens mühle"}},{q="Was geschah mit Hillsbrad während des Zweiten Krieges?",a="Während des Zweiten Krieges befahl Kriegshäuptling Orgrim Schicksalshammer einen Angriff auf Hillsbrad, um die Moral der Menschen zu brechen, während die Horde ihre Streitkräfte in der Region um Süderstade verstärkte. Hillsbrad wurde zerstört, doch die Allianz vertrieb die Orcs, und die Stadt wurde wiederaufgebaut.",al={"hillsbrad im zweiten krieg","orcs zerstörten hillsbrad","geschichte der felder von hillsbrad"}}},fx={["253bd91d"]={q="Was sind Die Felder von Hillsbrad?",a="Die Felder von Hillsbrad sind das fruchtbare landwirtschaftliche Herzland, das die Stadt Hillsbrad in den westlichen Ausläufern umgibt. Ihre weitläufigen Obstgärten, Kürbisfelder und Weiden liefern Nahrung nicht nur für die lokale Bevölkerung, sondern auch für den nahe gelegenen Hafen von Süderstade und die Außenposten der Allianz in der gesamten Region. Anders als weite Teile des nördlichen Lordaeron überstanden ihre Ackerflächen die Geißel weitgehend intakt und sind einer der wenigen Orte, an denen lebende menschliche Bauern unter dem Banner des gefallenen Königreichs noch Feldfrüchte anbauen.",al={"was sind die felder von hillsbrad","felder von hillsbrad übersicht","über die felder von hillsbrad"}},c30a4664={q="Sind Die Felder von Hillsbrad gefährlich?",a="Extrem, je nachdem, wer Ihr seid. Die Felder sind derzeit ein primäres Schlachtfeld im Krieg zwischen den lebenden Menschen von Hillsbrad und der Garnison der Verlassenen in Tarrens Mühle. Die Bauern, Arbeiter und Stadtwachen sind schwer bewaffnet, organisiert und wachsam gegenüber Einfällen der Untoten und führen bösartige Hinterhalte gegen Eindringlinge durch. Für Champions der Verlassenen, die von Hochexekutorin Darthalia entsandt wurden, ist die Säuberung dieser befestigten Gehöfte ein blutiger und hart umkämpfter Feldzug.",al={"sind die felder von hillsbrad sicher","felder von hillsbrad gefahr","wie gefährlich sind die felder von hillsbrad"}}},fp="16,222,30.511.0,32.417.0,47.262.0,35.214.0,41.305.0,49.249.0"}
P.entries["subzone:hive-ashi"] = {n="Bau des Ashischwarms",s="Im Norden von Silithus schickt der Bau des Ashischwarms seine Silithidenschwärme durch Sand und Tunnel. Er ist einer von drei großen Bauten der Region, in denen Arbeiter, Verteidiger und Stecher über hoch aufragende Hügel ziehen.",h="Im Norden von Silithus schickt der Bau des Ashischwarms seine Silithidenschwärme durch Sand und Tunnel.",kw={"cenarion","bau des ashischwarms","silithiden","silithus","die schwarmsäule"},ang={["class:Druid"]="Der Zirkel des Cenarius wacht über die verderbten Sande von Silithus. Als Druide seid Ihr aufgerufen, die Insektenplage aus dem Bau des Ashischwarms zu erforschen und einzudämmen, bevor sie die Natur verschlingt.",["faction:Alliance"]="Als Agent der Allianz in Silithus helft Ihr, Informationen über den Bau des Ashischwarms zu sammeln, damit seine aggressiven Schwärme benachbarte Gebiete im Süden Kalimdors nicht bedrohen."},sec={{t="Der nördliche Hügel",b="Im Norden von Silithus markieren die Chitinspitzen des Baus des Ashischwarms das Gebiet eines wieder erstarkenden Silithidenschwarms. Arbeiter suchen Nahrung, während giftige Verteidiger nach Süden und Osten zur Schwarmsäule ziehen. Unter den Hügeln bieten gefährliche Tunnel der Kolonie Schutz. Um zu erfahren, was sich in der Wüste regt, müssen Reisende sie betreten."},{t="Eine freigelegte Bedrohung",b="Späher des Zirkels des Cenarius überwachen den Bau des Ashischwarms. Sie entsenden Kämpfer, um den Schwarm zu dezimieren und Berichte aus den Tiefen der Kolonie zurückzubringen. Glyphen und koordiniertes Verhalten im Ashischwarm deuten darauf hin, dass die Insekten einem gemeinsamen Willen folgen, obwohl sie geistlos wirken. Ihre Zahl wächst, und die Wächter der südlichen Grenzen räumen der Vernichtung der Brut Vorrang ein, bevor sie sich über den Norden von Silithus hinaus ausbreitet."}},faq={{q="Was ist der Bau des Ashischwarms?",a="Der Bau des Ashischwarms ist eine aktive Silithidenkolonie im Norden von Silithus. Tausende grabende Insekten höhlen die Wüste aus und schaffen miteinander verbundene Tunnel und Hügel.",al={"bau des ashischwarms","bau des ashischwarms standort","was ist der ashischwarm"}},{q="Welche Arten von Silithiden leben im Bau des Ashischwarms?",a="Der Bau des Ashischwarms beherbergt Arbeiter, Sandpirscher, giftige Stecher und schwer gepanzerte Verteidiger.",al={"ashischwarm gegner","bau des ashischwarms kreaturen","welche silithiden gibt es hier"}},{q="Wie hängt der Bau des Ashischwarms mit der Schwarmsäule zusammen?",a="Silithiden breiten sich vom Bau des Ashischwarms über den Wüstenboden aus und umschwärmen die nahe gelegene Schwarmsäule.",al={"schwarmsäule verbindung","ashischwarm und schwarmsäule"}},{q="Warum untersuchen Späher des Zirkels des Cenarius diesen Bau?",a="Der Zirkel des Cenarius erforscht das Wiedererstarken der Silithiden und wie sich die Bauten untereinander abstimmen. Späher beobachten die seltsamen Glyphen des Ashischwarms und verfolgen, wie schnell sich die Kolonie ausbreitet.",al={"warum den bau des ashischwarms auskundschaften","bau des ashischwarms späherbericht"}}},fp="9,199,18.316.0,18.390.0,18.141.0,41.91.0,49.108.0,43.158.0"}
P.entries["subzone:hive-regal"] = {n="Bau des Regalschwarms",s="Im südlichen Silithus bedrohen die Bruten des Baus des Regalschwarms die Wüste um eine seiner drei großen Silithidenkolonien.",h="Im südlichen Silithus bedrohen die Bruten des Baus des Regalschwarms die Wüste um eine seiner drei großen...",kw={"wühler","bau","bau des regalschwarms","regal","silithiden","silithus","sklavenmacher","feuerspucker"},ang={["class:Druid"]="Als Druide wisst Ihr, dass der Zirkel des Cenarius die Ausbreitung des Baus des Regalschwarms genau beobachtet. Der Zirkel betrachtet die vordringende Verderbnis durch die Silithiden als existenzbedrohende Plage für das Ökosystem der Wüste."},sec={{t="Der südliche Bau",b="Der Bau des Regalschwarms erstreckt sich über das südliche Silithus, wo sich Silithiden in großer Zahl sammeln. Harzspitzen ragen über tiefen Tunneln auf. Darin leben gefährliche Bruten, von giftigen Feuerspuckern und Wühlern bis hin zu räuberischen Sklavenmachern. Der Bau bewacht seine Grenzen und erntet organisches Material von Reisenden, die ihm zu nahe kommen."},{t="Unterirdisches Netzwerk",b="Unter dem roten Sand von Silithus reichen die Gänge des Baus des Regalschwarms tief in die Erde. Seltsame Glyphen markieren den Eingang und entlegene Stellen in den Tunneln. Sie deuten darauf hin, dass eine organisierte Intelligenz den Schwarm lenkt, die über bloßen wilden Instinkt hinausgeht. Gelehrte und Späher untersuchen den Bau des Regalschwarms und seine Schwesterbauten auf Anzeichen einer größeren Macht, die sich unter dem Ödland regt."}},faq={{q="Wo liegt der Bau des Regalschwarms?",a="Der Bau des Regalschwarms liegt im südlichen Silithus, inmitten von rotem Sand und hoch aufragenden insektoiden Hügeln.",al={"bau des regalschwarms standort","wo ist der bau des regalschwarms","bau des regalschwarms finden"}},{q="Welche Arten von Kreaturen leben im Bau des Regalschwarms?",a="Im Bau des Regalschwarms leben feindselige Silithidenarten, darunter Wühler, Lauerer, Feuerspucker und Sklavenmacher, die den Bau verteidigen.",al={"bau des regalschwarms kreaturen","was ist im bau des regalschwarms","bau des regalschwarms feinde"}},{q="Warum interessieren sich Forscher für den Bau des Regalschwarms?",a="Späher und Gelehrte untersuchen die seltsamen Wandglyphen im Bau des Regalschwarms, um sie zu entziffern und die Silithidenbedrohung im gesamten südlichen Kalimdor zu überwachen.",al={"warum zum bau des regalschwarms","bau des regalschwarms forschung","bau des regalschwarms glyphen"}},{q="Wie unterscheidet sich der Bau des Regalschwarms von den anderen Bauten in Silithus?",a="Der Bau des Regalschwarms ist die südlichste der drei großen Kolonien von Silithus, neben dem Bau des Ashischwarms und dem Bau des Zoraschwarms. Jeder beherbergt spezialisierte Silithidenkasten, und alle scheinen ein gemeinsames Ziel zu verfolgen.",al={"andere bauten silithus","drei bauten","unterschied zwischen den bauten"}}},fp="10,110,17.316.0,20.348.0,28.83.0,43.124.0,45.133.0,60.185.0"}
P.entries["subzone:hive-zora"] = {n="Bau des Zoraschwarms",s="Im Westen von Silithus breitet sich der Silithidenschwarm aus dem Bau des Zoraschwarms im Sand aus. Er ist einer der drei großen Baue in der Wüste, und seine aggressiven Kasten drängen nach außen.",h="Im Westen von Silithus breitet sich der Silithidenschwarm aus dem Bau des Zoraschwarms im Sand aus.",kw={"zirkel des cenarius","bauschwestern","bau des zoraschwarms","schinder","silithiden","silithus","wegwächter"},ang={["class:Druid"]="Als Druide des Zirkels des Cenarius seht Ihr das Vordringen des Baus des Zoraschwarms als widernatürlich an, da es das natürliche Gleichgewicht der Wüstenwildnis stört.",["profession:Mining"]="Als Bergmann könnt Ihr in den gewundenen Tunneln und um Silithidenkolonien wie den Bau des Zoraschwarms reiche Thoriumadern und seltene schleimbedeckte Mineralvorkommen finden."},sec={{t="Der westliche Schwarm",b="Steinerne Spitzen ragen aus dem Sand des Baus des Zoraschwarms im Westen von Silithus. Poröse Hügel markieren die Eingänge zu tiefen Tunneln, die von Wühlern der Silithiden gegraben wurden. Wegwächter und Schinder patrouillieren am Rand. Darunter brüten Tunnelgräber und Bauschwestern. Der Zirkel des Cenarius und andere Späher beobachten, wie die Bedrohung durch die Silithiden in dieses uralte Grenzland vordringt."}},faq={{q="Was ist der Bau des Zoraschwarms?",a="Die oberirdischen Spitzen des Baus des Zoraschwarms führen in ein gewaltiges Tunnelnetz unter dem Westen von Silithus.",al={"bau des zoraschwarms","was ist der bau des zoraschwarms","bau des zoraschwarms silithus"}},{q="Welche Kreaturen leben im Bau des Zoraschwarms?",a="Die Kasten der Silithiden bevölkern den Bau des Zoraschwarms. Wegwächter patrouillieren draußen, schwere Schinder verteidigen das Gelände, Tunnelgräber graben in der Tiefe, und giftige Bauschwestern hausen im Inneren.",al={"bau des zoraschwarms gegner","welche monster sind im bau des zoraschwarms","wer lebt im bau des zoraschwarms"}},{q="Warum untersucht der Zirkel des Cenarius diesen Bau?",a="Späher und Forscher in Silithus beobachten den Bau des Zoraschwarms, um das Anwachsen und die Bewegungen der Silithidenbedrohung zu verfolgen. Gesandte untersuchen das Verhalten der Silithiden, entziffern ihre Glyphen und dezimieren ihre wachsende Zahl, bevor der Schwarm die Region überrennt.",al={"warum den bau des zoraschwarms auskundschaften","zirkel des cenarius bau des zoraschwarms"}},{q="Wie unterscheidet sich der Bau des Zoraschwarms von den anderen Bauen in Silithus?",a="Der Bau des Zoraschwarms liegt von den drei großen Bauen am weitesten westlich. Der Bau des Ashischwarms bildet den Stützpunkt im Norden, während der Bau des Regalschwarms den Süden beherrscht. Jeder hat seine eigene Brut, und alle streben danach, sich über die Wüste auszubreiten.",al={"andere baue silithus","unterschied zwischen den bauen","bau des regalschwarms bau des ashischwarms"}}},fp="9,165,17.325.0,18.88.0,33.158.0,51.228.0,59.190.0"}
P.entries["subzone:horizon-scout"] = {n="Horizon Scout",s="Vor Azsharas Südküste liegt die Horizon Scout versunken in den Verfallenen Gegenden. Captain Vanessa Beltis ist an Land gestrandet, und ein Teil ihrer Besatzung sitzt unter den Wellen fest.",h="Vor Azsharas Südküste liegt die Horizon Scout versunken in den Verfallenen Gegenden.",kw={"azshara schiffswrack","azsharit","horizon scout","roland geardabbler","die verfallenen gegenden","spitelash","vanessa beltis"},ang={["faction:Alliance"]="Als Mitglied der Allianz findet Ihr die Besatzung der Horizon Scout nach einer verheerenden Fahrt durch Azsharas gefährliche Gewässer zwischen Küste und Meer verstreut vor.",["race:Gnome"]="Als Gnom seht Ihr, dass die überlebende Besatzung auf Roland Geardabblers anhaltenden Zauber angewiesen ist, um im überfluteten Rumpf atmen zu können."},sec={{t="Gefangen am Meeresgrund",b="Die Horizon Scout liegt als Wrack zwischen den Untiefen der Verfallenen Gegenden vor Azsharas zerklüfteter Küste. Captain Vanessa Beltis erreichte eine nahe gelegene Halbinsel, doch ein Teil ihrer Besatzung ging mit dem Rumpf unter. Sie leben noch, weil Roland Geardabbler, ein Gnom, im Wrack einen Wasseratmungszauber aufrechterhält.\n\nFeindselige Wasserraubtiere und räuberische Naga patrouillieren in den Gewässern. Die Seeleute sitzen in den vorderen Abteilen fest und können die Oberfläche nicht aus eigener Kraft erreichen."},{t="Der Hinterhalt der Naga",b="Ein Splitter rohen Azsharits liegt im vorderen Treppenhaus der Horizon Scout. Das Mineral ist geheimnisvoll und kommt nur an diesen Küsten vor. Spitelash-Naga durchstreifen die Verfallenen Gegenden und griffen das Schiff vermutlich an, um Artefakte oder Ressourcen seiner Expedition an sich zu reißen.\n\nDas Schiff sank, sodass seine Überlebenden nicht mit den Geheimnissen oder Schätzen entkommen konnten, die diese Küste birgt."}},faq={{q="Wo liegt die Horizon Scout?",a="Die Horizon Scout liegt versunken auf dem Meeresgrund in den Verfallenen Gegenden vor Azsharas Südküste.",al={"horizon scout standort","wo ist horizon scout","horizon scout finden"}},{q="Wie bleibt die Besatzung unter Wasser am Leben?",a="Roland Geardabbler, ein Gnom, kanalisiert im gesunkenen Rumpf unablässig Wasseratmung und hält die eingeschlossene Besatzung mit atembarer Luft am Leben.",al={"wie können sie atmen","warum ist die besatzung nicht tot","roland geardabbler aura"}},{q="Wer ist Captain Vanessa Beltis?",a="Captain Vanessa Beltis befehligt die Horizon Scout. Sie erreichte mit einigen gestrandeten Überlebenden Azsharas südliche Halbinsel, während andere Seeleute noch im Rumpf festsitzen.",al={"vanessa beltis","horizon scout kapitän","schiffskapitän"}},{q="Warum sank die Horizon Scout?",a="Spitelash-Naga haben die Horizon Scout mit ziemlicher Sicherheit aus dem Hinterhalt angegriffen und versenkt. Ein Splitter rohen Azsharits auf dem unteren Deck deutet darauf hin, dass sie Bodenschätze oder Artefakte suchten, die die Expedition gesammelt hatte.",al={"warum sank horizon scout","wer versenkte horizon scout","was geschah mit dem schiff"}}},fp="13,170,26.448.0,15.351.0,35.102.0,39.139.0,30.168.0,38.184.0"}
